let file = """{"version":3,"file":"executionErrorStore-AFzyih5Y.js","names":["$attrs","$slots"],"sources":["../../src/stores/queueSettingsStore.ts","../../src/core/graph/subgraph/liftNodeErrorsToBoundary.ts","../../src/utils/missingResourceAbsorption.ts","../../src/utils/errorSeverityClassification.ts","../../src/composables/graph/useNodeErrorFlagSync.ts","../../src/platform/workflow/core/utils/workflowId.ts","../../src/platform/workflow/persistence/base/draftCacheV2.ts","../../src/platform/workflow/persistence/stores/workflowDraftStoreV2.ts","../../src/utils/positionBounds.ts","../../src/renderer/core/spatial/boundsCalculator.ts","../../src/assets/palettes/arc.json","../../src/assets/palettes/dark.json","../../src/assets/palettes/github.json","../../src/assets/palettes/light.json","../../src/assets/palettes/nord.json","../../src/assets/palettes/solarized.json","../../src/constants/coreColorPalettes.ts","../../src/stores/workspace/colorPaletteStore.ts","../../src/renderer/extensions/minimap/data/MinimapDataSource.ts","../../src/renderer/extensions/minimap/minimapCanvasRenderer.ts","../../src/renderer/core/thumbnail/graphThumbnailRenderer.ts","../../src/renderer/core/thumbnail/useWorkflowThumbnail.ts","../../src/renderer/extensions/layerEditor/layerEditorDialogKey.ts","../../src/platform/workflow/core/utils/workflowFlattening.ts","../../src/platform/errorCatalog/accountPreconditionRouting.ts","../../src/utils/createAnnotatedPath.ts","../../src/renderer/extensions/vueNodes/composables/useNodeZIndex.ts","../../src/utils/litegraphUtil.ts","../../src/utils/nodeOutputUtil.ts","../../src/utils/objectUrlUtil.ts","../../src/stores/nodeOutputStore.ts","../../src/stores/jobPreviewStore.ts","../../src/utils/appMode.ts","../../src/utils/rafBatch.ts","../../src/stores/executionStore.ts","../../src/platform/workflow/core/utils/pendingWarnings.ts","../../src/platform/workflow/core/utils/workflowToClipboardItems.ts","../../src/scripts/defaultGraph.ts","../../src/stores/domWidgetStore.ts","../../src/stores/appModeStore.ts","../../src/platform/settings/missingWarningVisibility.ts","../../src/platform/nodeReplacement/missingNodesErrorStore.ts","../../src/stores/templateInputDownloadStore.ts","../../src/platform/missingMedia/missingMediaStore.ts","../../src/schemas/colorPaletteSchema.ts","../../src/services/colorPaletteService.ts","../../src/stores/workspace/bottomPanelStore.ts","../../src/stores/workspaceStore.ts","../../src/platform/workflow/core/services/workflowService.ts","../../src/renderer/core/canvas/useCanvasScheduler.ts","../../src/workbench/extensions/agent/stores/agent/creditTransitionNoticeState.ts","../../src/workbench/extensions/agent/stores/agent/agentPanelStore.ts","../../src/composables/canvas/visibleCanvasViewport.ts","../../src/composables/canvas/useSelectedLiteGraphItems.ts","../../src/utils/syncUtil.ts","../../src/stores/userFileStore.ts","../../src/platform/workflow/management/stores/comfyWorkflow.ts","../../src/platform/workflow/templates/types/template.ts","../../src/stores/subgraphStore.ts","../../src/composables/graph/useSubgraphOperations.ts","../../src/composables/functional/useChainCallback.ts","../../src/base/wheelGestures.ts","../../src/renderer/core/canvas/useCanvasInteractions.ts","../../src/scripts/domWidget.ts","../../src/composables/node/useNodeAnimatedImage.ts","../../src/scripts/ui/imagePreview.ts","../../src/utils/imageUtil.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useImagePreviewWidget.ts","../../src/composables/node/canvasImagePreviewTypes.ts","../../src/composables/node/useNodeCanvasImagePreview.ts","../../src/platform/telemetry/imageFailureDiagnostics.ts","../../src/composables/node/useNodeImage.ts","../../src/core/graph/subgraph/promotionUtils.ts","../../src/core/graph/widgets/dynamicGroupDiagnostics.ts","../../src/core/graph/widgets/dynamicGroupWidget.ts","../../src/core/graph/widgets/dynamicWidgets.ts","../../src/renderer/extensions/vueNodes/widgets/utils/forwardMiddleButtonToCanvas.ts","../../src/renderer/extensions/vueNodes/widgets/utils/multilineTextarea.ts","../../src/services/subgraphPseudoWidgetCache.ts","../../src/scripts/clipspace.ts","../../src/utils/nodeTitleUtil.ts","../../src/stores/workspace/favoritedWidgetsStore.ts","../../src/stores/workspace/rightSidePanelStore.ts","../../src/core/graph/widgets/controlWidgetMarker.ts","../../src/types/simplifiedWidget.ts","../../src/core/graph/widgets/valueControl.ts","../../src/core/graph/widgets/valueControlWidgets.ts","../../src/schemas/nodeDef/nodeDefSchemaV2.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useBooleanWidget.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useBoundingBoxWidget.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useCurveWidget.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useChartWidget.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useColorWidget.ts","../../src/components/ui/multi-select/MultiSelectContent.vue","../../src/components/ui/multi-select/MultiSelectContent.vue","../../src/components/ui/multi-select/MultiSelectTrigger.vue","../../src/components/ui/multi-select/MultiSelectTrigger.vue","../../src/components/ui/multi-select/MultiSelect.vue","../../src/components/ui/multi-select/MultiSelect.vue","../../src/components/graph/widgets/MultiSelectWidget.vue","../../src/components/graph/widgets/MultiSelectWidget.vue","../../src/core/graph/widgets/comboWidgetInventory.ts","../../src/platform/assets/constants/assetEvents.ts","../../src/platform/assets/schemas/assetSchema.ts","../../src/platform/assets/mappings/modelNodeMappings.ts","../../src/utils/widgetBinding.ts","../../src/stores/modelToNodeStore.ts","../../src/platform/assets/services/assetService.ts","../../src/platform/assets/composables/useAssetBrowserDialog.ts","../../src/platform/assets/utils/createAssetWidget.ts","../../src/platform/assets/schemas/assetMetadataSchema.ts","../../src/utils/resultItem.ts","../../src/utils/resultItemUrl.ts","../../src/platform/assets/composables/media/assetMappers.ts","../../src/utils/pagedList.ts","../../src/utils/requestUtil.ts","../../src/platform/assets/composables/useAssetsQuery.ts","../../src/stores/resultItemParsing.ts","../../src/lib/litegraph/src/contextMenuCompat.ts","../../src/constants/coreMenuCommands.ts","../../src/stores/menuItemStore.ts","../../src/services/extensionService.ts","../../src/services/jobOutputCache.ts","../../src/stores/queueStore.ts","../../src/platform/tasks/services/taskService.ts","../../src/stores/assetDownloadStore.ts","../../src/stores/assetsStore.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useRemoteWidget.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useComboWidget.ts","../../src/renderer/extensions/compositor/components/types.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useCompositorWidget.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useFloatWidget.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useGalleriaWidget.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useBoundingBoxesWidget.ts","../../src/extensions/core/lightInfo/types.ts","../../src/extensions/core/lightInfo/lightsValue.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useLightInfoWidget.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useColorsWidget.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useImageCompareWidget.ts","../../src/platform/assets/schemas/mediaAssetSchema.ts","../../src/utils/eventUtils.ts","../../src/composables/node/useNodeDragAndDrop.ts","../../src/composables/node/useNodeFileInput.ts","../../src/composables/node/useNodePaste.ts","../../src/composables/node/useNodeImageUpload.ts","../../src/types/nodeDefAugmentation.ts","../../src/utils/mediaUploadUtil.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useImageUploadWidget.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useIntWidget.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useMarkdownWidget.ts","../../src/renderer/extensions/vueNodes/widgets/composables/usePainterWidget.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useRangeWidget.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useResolutionPreviewWidget.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useStringWidget.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useTextareaWidget.ts","../../src/renderer/extensions/vueNodes/widgets/composables/useVideoEditWidget.ts","../../src/scripts/errorNodeWidgets.ts","../../src/scripts/widgets.ts","../../src/stores/widgetStore.ts","../../src/utils/coreMediaMenuActionUtils.ts","../../src/workbench/utils/nodeDefOrderingUtil.ts","../../src/services/litegraphService.ts","../../src/stores/subgraphNavigationStore.ts","../../src/scripts/changeTracker.ts","../../src/platform/workflow/management/stores/workflowStore.ts","../../src/composables/useAppMode.ts","../../src/renderer/core/canvas/canvasStore.ts","../../src/platform/missingModel/missingModelStore.ts","../../src/stores/executionErrorStore.ts"],"sourcesContent":["import { defineStore } from 'pinia'\n\nexport type AutoQueueMode =\n  | 'disabled'\n  | 'change'\n  | 'instant-idle'\n  | 'instant-running'\n\nexport function isInstantMode(\n  mode: AutoQueueMode\n): mode is 'instant-idle' | 'instant-running' {\n  return mode === 'instant-idle' || mode === 'instant-running'\n}\n\nexport function isInstantRunningMode(\n  mode: AutoQueueMode\n): mode is 'instant-running' {\n  return mode === 'instant-running'\n}\n\nexport const useQueueSettingsStore = defineStore('queueSettingsStore', {\n  state: () => ({\n    mode: 'disabled' as AutoQueueMode,\n    batchCount: 1\n  })\n})\n","import { groupBy, partition } from 'es-toolkit'\n\nimport type { LGraph } from '@/lib/litegraph/src/litegraph'\nimport type { NodeError } from '@/platform/remote/comfyui/types'\nimport { tryNormalizeNodeExecutionId } from '@/types/nodeIdentification'\nimport type { NodeExecutionId } from '@/types/nodeIdentification'\nimport { isNodeLevelValidationError } from '@/utils/executionErrorUtil'\nimport type { NodeValidationError } from '@/utils/executionErrorUtil'\nimport { getNodeByExecutionId } from '@/utils/graphTraversalUtil'\nimport { isSubgraph } from '@/utils/typeGuardUtil'\n\nexport interface LiftedErrorExtraInfo {\n  input_name: string\n  source_execution_id: string\n  source_input_name: string\n}\n\nexport interface LiftedSurface {\n  hostExecId: NodeExecutionId\n  hostInputName: string\n}\n\ninterface ErrorPlacement {\n  kind: 'own' | 'lifted'\n  targetExecId: string\n  error: NodeValidationError\n}\n\nexport function getLiftedErrorSource(\n  error: NodeValidationError\n): LiftedErrorExtraInfo | null {\n  const extraInfo = error.extra_info\n  if (!extraInfo) return null\n\n  const { input_name, source_execution_id, source_input_name } = extraInfo\n  if (\n    typeof input_name !== 'string' ||\n    typeof source_execution_id !== 'string' ||\n    typeof source_input_name !== 'string'\n  ) {\n    return null\n  }\n\n  return { input_name, source_execution_id, source_input_name }\n}\n\nfunction getHostExecutionId(executionId: string): NodeExecutionId | null {\n  const separatorIndex = executionId.lastIndexOf(':')\n  if (separatorIndex <= 0) return null\n  return tryNormalizeNodeExecutionId(executionId.slice(0, separatorIndex))\n}\n\n/**\n * Boundary surfaces that expose `(executionId, inputName)`, innermost first.\n * Walks one host per level and stops at the last resolvable surface, so an\n * unresolvable deeper host falls back to the shallower one (fail-open).\n */\nexport function resolveLiftChain(\n  rootGraph: LGraph,\n  executionId: string,\n  inputName: string\n): LiftedSurface[] {\n  const chain: LiftedSurface[] = []\n  let currentExecId = executionId\n  let currentInputName = inputName\n\n  for (;;) {\n    const node = getNodeByExecutionId(rootGraph, currentExecId)\n    const graph = node?.graph\n    if (!node || !graph || !isSubgraph(graph)) break\n\n    const slot = node.inputs.find((input) => input.name === currentInputName)\n    if (slot?.link == null) break\n\n    const subgraphInput = graph.getLink(slot.link)?.resolve(graph).subgraphInput\n    if (!subgraphInput) break\n\n    const hostExecId = getHostExecutionId(currentExecId)\n    if (!hostExecId || !getNodeByExecutionId(rootGraph, hostExecId)) break\n\n    chain.push({ hostExecId, hostInputName: subgraphInput.name })\n    currentExecId = hostExecId\n    currentInputName = subgraphInput.name\n  }\n\n  return chain\n}\n\nfunction createEmptyNodeError(nodeError: NodeError): NodeError {\n  return {\n    ...nodeError,\n    errors: []\n  }\n}\n\n// Lifted host entries use the host title for display; SubgraphNode.type is a UUID.\nfunction createLiftedHostEntry(\n  rootGraph: LGraph,\n  hostExecId: string\n): NodeError {\n  return {\n    class_type:\n      getNodeByExecutionId(rootGraph, hostExecId)?.title ?? hostExecId,\n    dependent_outputs: [],\n    errors: []\n  }\n}\n\nfunction toErrorPlacement(\n  rootGraph: LGraph,\n  executionId: string,\n  error: NodeValidationError\n): ErrorPlacement {\n  const inputName = error.extra_info?.input_name\n  const surface =\n    inputName && !isNodeLevelValidationError(error)\n      ? resolveLiftChain(rootGraph, executionId, inputName).at(-1)\n      : undefined\n\n  if (!inputName || !surface) {\n    return {\n      kind: 'own',\n      targetExecId: executionId,\n      error\n    }\n  }\n\n  const liftedExtraInfo: LiftedErrorExtraInfo = {\n    input_name: surface.hostInputName,\n    source_execution_id: executionId,\n    source_input_name: inputName\n  }\n\n  return {\n    kind: 'lifted',\n    targetExecId: surface.hostExecId,\n    error: {\n      ...error,\n      extra_info: {\n        ...error.extra_info,\n        ...liftedExtraInfo\n      }\n    }\n  }\n}\n\nexport function liftNodeErrorsToBoundary(\n  rootGraph: LGraph,\n  nodeErrors: Record<string, NodeError>\n): Record<string, NodeError> {\n  const output: Record<string, NodeError> = {}\n  const placements = Object.entries(nodeErrors).flatMap(\n    ([executionId, nodeError]) =>\n      nodeError.errors.map((error) =>\n        toErrorPlacement(rootGraph, executionId, error)\n      )\n  )\n\n  for (const [executionId, nodeError] of Object.entries(nodeErrors)) {\n    if (nodeError.errors.length === 0) {\n      output[executionId] = createEmptyNodeError(nodeError)\n    }\n  }\n\n  const placementsByTarget = groupBy(\n    placements,\n    (placement) => placement.targetExecId\n  )\n\n  for (const [targetExecId, targetPlacements] of Object.entries(\n    placementsByTarget\n  )) {\n    const existingEntry = Object.hasOwn(nodeErrors, targetExecId)\n      ? nodeErrors[targetExecId]\n      : undefined\n    const baseEntry = existingEntry\n      ? createEmptyNodeError(existingEntry)\n      : createLiftedHostEntry(rootGraph, targetExecId)\n\n    const [ownErrors, liftedErrors] = partition(\n      targetPlacements,\n      (placement) => placement.kind === 'own'\n    )\n\n    output[targetExecId] = {\n      ...baseEntry,\n      errors: [...ownErrors, ...liftedErrors].map(\n        (placement) => placement.error\n      )\n    }\n  }\n\n  return output\n}\n","import type { MissingMediaCandidate } from '@/platform/missingMedia/types'\nimport type { MissingModelCandidate } from '@/platform/missingModel/types'\nimport type { NodeExecutionId } from '@/types/nodeIdentification'\nimport type { PromotedWidgetExecutionSource } from '@/core/graph/subgraph/promotedWidgetTypes'\nimport { getLiftedErrorSource } from '@/core/graph/subgraph/liftNodeErrorsToBoundary'\nimport type { LiftedErrorExtraInfo } from '@/core/graph/subgraph/liftNodeErrorsToBoundary'\nimport {\n  isImageNotLoadedValidationError,\n  isMissingNodePromptError\n} from '@/utils/executionErrorUtil'\nimport type { NodeValidationError } from '@/utils/executionErrorUtil'\n\nimport type { PromptError } from '@/platform/remote/comfyui/types'\n\nexport type MissingResourceAbsorption = 'missing_model' | 'missing_media'\n\nfunction normalizePath(value: string): string {\n  return value.replace(/[\\\\/]+/g, '/').replace(/\\/+$/, '')\n}\n\nfunction matchesReceivedValue(\n  receivedValue: unknown,\n  candidateName: string\n): boolean {\n  if (receivedValue == null) return false\n\n  return normalizePath(String(receivedValue)) === normalizePath(candidateName)\n}\n\nfunction isEligibleValidationError(error: NodeValidationError): boolean {\n  return (\n    error.type === 'value_not_in_list' || isImageNotLoadedValidationError(error)\n  )\n}\n\nfunction matchesErrorNodeId(\n  candidateNodeIds: readonly (string | number | null | undefined)[],\n  liftedSource: LiftedErrorExtraInfo | null,\n  nodeId: NodeExecutionId\n): boolean {\n  const errorNodeIds = [nodeId, liftedSource?.source_execution_id]\n    .filter((id) => id != null)\n    .map(String)\n\n  return candidateNodeIds.some(\n    (candidateId) =>\n      candidateId != null && errorNodeIds.includes(String(candidateId))\n  )\n}\n\nfunction matchesErrorInputName(\n  candidateNodeIds: readonly (string | number | null | undefined)[],\n  candidateInputName: string,\n  errorInputName: string | undefined,\n  liftedSource: LiftedErrorExtraInfo | null\n): boolean {\n  if (candidateInputName === errorInputName) return true\n  if (!liftedSource) return false\n\n  return (\n    candidateInputName === liftedSource.source_input_name &&\n    candidateNodeIds.some(\n      (id) => id != null && String(id) === liftedSource.source_execution_id\n    )\n  )\n}\n\nfunction matchesPromotedSource(\n  source: PromotedWidgetExecutionSource,\n  error: NodeValidationError,\n  nodeId: NodeExecutionId\n): boolean {\n  if (String(source.executionId) !== String(nodeId)) return false\n  return source.widgetName === error.extra_info?.input_name\n}\n\nfunction matchesCandidate(\n  candidateNodeIds: readonly (string | number | null | undefined)[],\n  candidateInputName: string,\n  candidateName: string,\n  isMissing: boolean | undefined,\n  error: NodeValidationError,\n  nodeId: NodeExecutionId,\n  promotedSources: readonly PromotedWidgetExecutionSource[] = []\n): boolean {\n  if (isMissing !== true) return false\n  // Checked before the host-identity gate: an unlifted interior error never\n  // carries the host id the candidate is keyed by.\n  if (\n    promotedSources.some((source) =>\n      matchesPromotedSource(source, error, nodeId)\n    )\n  ) {\n    return true\n  }\n\n  const liftedSource = getLiftedErrorSource(error)\n  if (!matchesErrorNodeId(candidateNodeIds, liftedSource, nodeId)) {\n    return false\n  }\n\n  if (\n    matchesErrorInputName(\n      candidateNodeIds,\n      candidateInputName,\n      error.extra_info?.input_name,\n      liftedSource\n    )\n  ) {\n    return true\n  }\n  // Value equality alone is too weak a signal when the error names an input:\n  // a same-valued sibling widget's genuinely blocking error must stay red.\n  if (error.extra_info?.input_name != null) return false\n  return matchesReceivedValue(error.extra_info?.received_value, candidateName)\n}\n\nfunction matchesMissingModel(\n  candidate: MissingModelCandidate,\n  error: NodeValidationError,\n  nodeId: NodeExecutionId\n): boolean {\n  return matchesCandidate(\n    [candidate.sourceExecutionId, candidate.nodeId],\n    candidate.widgetName,\n    candidate.name,\n    candidate.isMissing,\n    error,\n    nodeId,\n    candidate.promotedSources\n  )\n}\n\nfunction matchesMissingMedia(\n  candidate: MissingMediaCandidate,\n  error: NodeValidationError,\n  nodeId: NodeExecutionId\n): boolean {\n  return matchesCandidate(\n    [candidate.nodeId],\n    candidate.widgetName,\n    candidate.name,\n    candidate.isMissing,\n    error,\n    nodeId,\n    candidate.promotedSources\n  )\n}\n\nexport function classifyValidationErrorAbsorption(\n  missingModels: readonly MissingModelCandidate[] | null,\n  missingMedia: readonly MissingMediaCandidate[] | null,\n  error: NodeValidationError,\n  nodeId: NodeExecutionId\n): MissingResourceAbsorption | null {\n  if (!isEligibleValidationError(error)) return null\n\n  if (\n    missingModels?.some((candidate) =>\n      matchesMissingModel(candidate, error, nodeId)\n    )\n  ) {\n    return 'missing_model'\n  }\n  if (\n    missingMedia?.some((candidate) =>\n      matchesMissingMedia(candidate, error, nodeId)\n    )\n  ) {\n    return 'missing_media'\n  }\n  return null\n}\n\nexport function isMissingNodePromptErrorAbsorbed(\n  promptError: PromptError | null,\n  hasMissingNodes: boolean\n): boolean {\n  return isMissingNodePromptError(promptError) && hasMissingNodes\n}\n","import type { MissingMediaCandidate } from '@/platform/missingMedia/types'\nimport type { MissingModelCandidate } from '@/platform/missingModel/types'\nimport { tryNormalizeNodeExecutionId } from '@/types/nodeIdentification'\nimport type { NodeExecutionId } from '@/types/nodeIdentification'\nimport type { NodeValidationError } from '@/utils/executionErrorUtil'\n\nimport type { ExecutionErrorWsMessage } from '@/platform/remote/comfyui/execution/types'\nimport type { NodeError, PromptError } from '@/platform/remote/comfyui/types'\nimport {\n  classifyValidationErrorAbsorption,\n  isMissingNodePromptErrorAbsorbed\n} from './missingResourceAbsorption'\nimport type { MissingResourceAbsorption } from './missingResourceAbsorption'\n\nexport interface ErrorSeverityInput {\n  promptError: PromptError | null\n  executionError: ExecutionErrorWsMessage | null\n  nodeErrors: Record<string, NodeError> | null\n  missingModels: readonly MissingModelCandidate[] | null\n  missingMedia: readonly MissingMediaCandidate[] | null\n  hasMissingNodes: boolean\n}\n\nexport interface ErrorClassification {\n  promptError: {\n    error: PromptError\n    isAbsorbed: boolean\n  } | null\n  executionError: {\n    error: ExecutionErrorWsMessage\n    rawNodeId: string | undefined\n    nodeId: NodeExecutionId | null\n  } | null\n  nodeErrors: {\n    rawNodeId: string\n    nodeId: NodeExecutionId | null\n    nodeError: NodeError\n    errors: {\n      error: NodeValidationError\n      absorption: MissingResourceAbsorption | null\n    }[]\n  }[]\n  hasBlockingError: boolean\n}\n\nexport function classifyPanelErrors(\n  input: ErrorSeverityInput\n): ErrorClassification {\n  const promptError = input.promptError\n    ? {\n        error: input.promptError,\n        isAbsorbed: isMissingNodePromptErrorAbsorbed(\n          input.promptError,\n          input.hasMissingNodes\n        )\n      }\n    : null\n\n  const executionNodeId = input.executionError?.node_id\n  const rawExecutionNodeId =\n    executionNodeId == null ? undefined : String(executionNodeId)\n  const executionError = input.executionError\n    ? {\n        error: input.executionError,\n        rawNodeId: rawExecutionNodeId,\n        nodeId:\n          rawExecutionNodeId === undefined\n            ? null\n            : tryNormalizeNodeExecutionId(rawExecutionNodeId)\n      }\n    : null\n\n  const nodeErrors = Object.entries(input.nodeErrors ?? {}).map(\n    ([rawNodeId, nodeError]) => {\n      const nodeId = tryNormalizeNodeExecutionId(rawNodeId)\n      return {\n        rawNodeId,\n        nodeId,\n        nodeError,\n        errors: nodeError.errors.map((error) => ({\n          error,\n          absorption: nodeId\n            ? classifyValidationErrorAbsorption(\n                input.missingModels,\n                input.missingMedia,\n                error,\n                nodeId\n              )\n            : null\n        }))\n      }\n    }\n  )\n\n  const hasBlockingNodeError = nodeErrors.some(({ errors }) =>\n    errors.some(({ absorption }) => !absorption)\n  )\n\n  return {\n    promptError,\n    executionError,\n    nodeErrors,\n    hasBlockingError:\n      (promptError !== null && !promptError.isAbsorbed) ||\n      executionError !== null ||\n      hasBlockingNodeError\n  }\n}\n","import type { Ref } from 'vue'\nimport { computed, watch } from 'vue'\n\nimport type { LGraph, LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { useMissingModelStore } from '@/platform/missingModel/missingModelStore'\nimport type { useMissingMediaStore } from '@/platform/missingMedia/missingMediaStore'\nimport type { useMissingNodesErrorStore } from '@/platform/nodeReplacement/missingNodesErrorStore'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useApp } from '@/scripts/appInstance'\nimport type { NodeError } from '@/platform/remote/comfyui/types'\nimport { getParentExecutionIds } from '@/types/nodeIdentification'\nimport { hasErrorForSlot } from '@/utils/executionErrorUtil'\nimport { forEachNode, getNodeByExecutionId } from '@/utils/graphTraversalUtil'\n\nfunction setNodeHasErrors(node: LGraphNode, hasErrors: boolean): void {\n  if (node.has_errors === hasErrors) return\n  const oldValue = node.has_errors\n  node.has_errors = hasErrors\n  node.graph?.trigger('node:property:changed', {\n    type: 'node:property:changed',\n    nodeId: node.id,\n    property: 'has_errors',\n    oldValue,\n    newValue: hasErrors\n  })\n}\n\n/**\n * Single-pass reconciliation of node error flags.\n * Collects the set of nodes that should have errors, then walks all nodes\n * once, setting each flag exactly once. This avoids the redundant\n * true→false→true transition (and duplicate events) that a clear-then-apply\n * approach would cause.\n */\nfunction reconcileNodeErrorFlags(\n  rootGraph: LGraph,\n  nodeErrors: Record<string, NodeError> | null,\n  missingModelExecIds: Set<string>,\n  missingMediaExecIds: Set<string> = new Set(),\n  missingNodeExecIds: Set<string> = new Set()\n): void {\n  // Collect nodes and slot info that should be flagged\n  // Includes both error-owning nodes and their ancestor containers\n  const flaggedNodes = new Set<LGraphNode>()\n  const errorsByNode = new Map<LGraphNode, NodeError['errors']>()\n\n  if (nodeErrors) {\n    for (const [executionId, nodeError] of Object.entries(nodeErrors)) {\n      const node = getNodeByExecutionId(rootGraph, executionId)\n      if (!node) continue\n\n      flaggedNodes.add(node)\n      errorsByNode.set(node, [\n        ...(errorsByNode.get(node) ?? []),\n        ...nodeError.errors\n      ])\n\n      for (const parentId of getParentExecutionIds(executionId)) {\n        const parentNode = getNodeByExecutionId(rootGraph, parentId)\n        if (parentNode) flaggedNodes.add(parentNode)\n      }\n    }\n  }\n\n  for (const execId of missingModelExecIds) {\n    const node = getNodeByExecutionId(rootGraph, execId)\n    if (node) flaggedNodes.add(node)\n  }\n\n  for (const execId of missingMediaExecIds) {\n    const node = getNodeByExecutionId(rootGraph, execId)\n    if (node) flaggedNodes.add(node)\n  }\n  for (const execId of missingNodeExecIds) {\n    const node = getNodeByExecutionId(rootGraph, execId)\n    if (node) flaggedNodes.add(node)\n  }\n\n  forEachNode(rootGraph, (node) => {\n    setNodeHasErrors(node, flaggedNodes.has(node))\n\n    const ownErrors = errorsByNode.get(node)\n    for (const slot of node.inputs) {\n      slot.hasErrors =\n        !!slot.name && !!ownErrors && hasErrorForSlot(ownErrors, slot.name)\n    }\n  })\n}\n\nexport function useNodeErrorFlagSync(\n  nodeErrors: Ref<Record<string, NodeError> | null>,\n  missingModelStore: ReturnType<typeof useMissingModelStore>,\n  missingMediaStore: ReturnType<typeof useMissingMediaStore>,\n  missingNodesStore: ReturnType<typeof useMissingNodesErrorStore>\n): () => void {\n  const settingStore = useSettingStore()\n  const showErrorsTab = computed(() =>\n    settingStore.get('Comfy.RightSidePanel.ShowErrorsTab')\n  )\n\n  const stop = watch(\n    [\n      nodeErrors,\n      () => missingModelStore.missingModelNodeIds,\n      () => missingMediaStore.missingMediaNodeIds,\n      () => missingNodesStore.missingAncestorExecutionIds,\n      showErrorsTab\n    ],\n    () => {\n      const rootGraph = useApp().rootGraphOrUndefined\n      if (!rootGraph) return\n      // Legacy (LGraphNode) only: suppress missing-resource error flags\n      // when the Errors tab is hidden, since legacy nodes lack the per-widget\n      // red highlight that Vue nodes use to indicate *why* a node has errors.\n      // Vue nodes compute hasAnyError independently and are unaffected.\n      reconcileNodeErrorFlags(\n        rootGraph,\n        nodeErrors.value,\n        showErrorsTab.value\n          ? missingModelStore.missingModelAncestorExecutionIds\n          : new Set(),\n        showErrorsTab.value\n          ? missingMediaStore.missingMediaAncestorExecutionIds\n          : new Set(),\n        // Placeholders for missing nodes are flagged at creation regardless\n        // of the Errors tab, so keep that and let only the nodes warning\n        // setting clear them.\n        missingNodesStore.missingAncestorExecutionIds\n      )\n    },\n    { flush: 'post' }\n  )\n  return stop\n}\n","import type { ComfyWorkflowJSON } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { generateUUID, isValidUuid } from '@/utils/formatUtil'\n\ntype WorkflowWithId = ComfyWorkflowJSON & { id: string }\n\nfunction hasWorkflowId(\n  workflowData: ComfyWorkflowJSON\n): workflowData is WorkflowWithId {\n  return isValidUuid(workflowData.id)\n}\n\nexport function getLegacyWorkflowId(\n  id: string | undefined\n): string | undefined {\n  return id && !isValidUuid(id) ? id : undefined\n}\n\nexport function ensureWorkflowId(\n  workflowData: ComfyWorkflowJSON,\n  fallbackId?: string\n): WorkflowWithId {\n  if (hasWorkflowId(workflowData)) return workflowData\n  return {\n    ...workflowData,\n    id: isValidUuid(fallbackId) ? fallbackId : generateUUID()\n  }\n}\n\nexport function areWorkflowIdsEquivalent(\n  existingId: string | undefined,\n  incomingId: string | undefined,\n  existingLegacyId?: string\n): boolean {\n  if (isValidUuid(existingId) && isValidUuid(incomingId)) {\n    return existingId.toLowerCase() === incomingId.toLowerCase()\n  }\n\n  const incomingLegacyId = getLegacyWorkflowId(incomingId)\n  if (incomingLegacyId) {\n    return (\n      incomingLegacyId === existingLegacyId || incomingLegacyId === existingId\n    )\n  }\n\n  return !existingId || !incomingId\n}\n","/**\n * V2 Draft Cache - Pure functions for draft index manipulation.\n *\n * This module provides immutable operations on the draft index structure.\n * All functions return new objects rather than mutating inputs.\n */\n\nimport type { DraftEntryMeta, DraftIndexV2 } from './draftTypes'\nimport { MAX_DRAFTS } from './draftTypes'\nimport { hashPath } from './hashUtil'\n\n/**\n * Creates an empty draft index.\n */\nexport function createEmptyIndex(): DraftIndexV2 {\n  return {\n    v: 2,\n    updatedAt: Date.now(),\n    order: [],\n    entries: {}\n  }\n}\n\n/**\n * Moves a draft key to the end of the LRU order (most recently used).\n */\nexport function touchOrder(order: string[], draftKey: string): string[] {\n  const filtered = order.filter((key) => key !== draftKey)\n  return [...filtered, draftKey]\n}\n\n/**\n * Adds or updates a draft entry in the index.\n * Handles LRU eviction if over the limit.\n *\n * @returns Object with updated index and list of evicted draft keys\n */\nexport function upsertEntry(\n  index: DraftIndexV2,\n  path: string,\n  meta: Omit<DraftEntryMeta, 'path'>,\n  limit: number = MAX_DRAFTS\n): { index: DraftIndexV2; evicted: string[] } {\n  const draftKey = hashPath(path)\n  const effectiveLimit = Math.max(1, limit)\n\n  const entries = {\n    ...index.entries,\n    [draftKey]: { ...meta, path }\n  }\n\n  const touchedOrder = touchOrder(index.order, draftKey)\n  const evicted: string[] = []\n\n  let evictCount = 0\n  while (touchedOrder.length - evictCount > effectiveLimit) {\n    const oldest = touchedOrder[evictCount]\n    if (oldest && oldest !== draftKey) {\n      delete entries[oldest]\n      evicted.push(oldest)\n    }\n    evictCount++\n  }\n\n  const finalOrder = touchedOrder.slice(evictCount)\n\n  return {\n    index: {\n      v: 2,\n      updatedAt: Date.now(),\n      order: finalOrder,\n      entries\n    },\n    evicted\n  }\n}\n\n/**\n * Removes a draft entry from the index.\n *\n * @returns Object with updated index and the removed draft key (if any)\n */\nexport function removeEntry(\n  index: DraftIndexV2,\n  path: string\n): { index: DraftIndexV2; removedKey: string | null } {\n  const draftKey = hashPath(path)\n\n  if (!(draftKey in index.entries)) {\n    return { index, removedKey: null }\n  }\n\n  const entries = { ...index.entries }\n  delete entries[draftKey]\n\n  return {\n    index: {\n      v: 2,\n      updatedAt: Date.now(),\n      order: index.order.filter((key) => key !== draftKey),\n      entries\n    },\n    removedKey: draftKey\n  }\n}\n\n/**\n * Moves a draft from one path to another (rename operation).\n * Updates index recency only; callers keep the payload timestamp unchanged.\n *\n * @returns Object with updated index and keys involved\n */\nexport function moveEntry(\n  index: DraftIndexV2,\n  oldPath: string,\n  newPath: string,\n  newName: string\n): { index: DraftIndexV2; oldKey: string; newKey: string } | null {\n  const oldKey = hashPath(oldPath)\n  const newKey = hashPath(newPath)\n\n  const entriesByKey: Partial<Record<string, DraftEntryMeta>> = index.entries\n  const oldEntry = entriesByKey[oldKey]\n  if (!oldEntry) return null\n  if (oldKey !== newKey && entriesByKey[newKey]) return null\n\n  const entries = { ...index.entries }\n  delete entries[oldKey]\n\n  entries[newKey] = {\n    ...oldEntry,\n    path: newPath,\n    name: newName,\n    updatedAt: Date.now()\n  }\n\n  const order = index.order\n    .filter((key) => key !== oldKey && key !== newKey)\n    .concat(newKey)\n\n  return {\n    index: {\n      v: 2,\n      updatedAt: Date.now(),\n      order,\n      entries\n    },\n    oldKey,\n    newKey\n  }\n}\n\n/**\n * Gets the most recently used draft key.\n */\nexport function getMostRecentKey(index: DraftIndexV2): string | null {\n  return index.order.length > 0 ? index.order[index.order.length - 1] : null\n}\n\n/**\n * Gets entry metadata by path.\n */\nexport function getEntryByPath(\n  index: DraftIndexV2,\n  path: string\n): DraftEntryMeta | null {\n  const draftKey = hashPath(path)\n  return index.entries[draftKey] ?? null\n}\n\n/**\n * Removes entries from index that don't have corresponding payloads.\n * Used for index/payload drift recovery.\n *\n * @param index - The draft index\n * @param existingPayloadKeys - Set of draft keys that have payloads in storage\n * @returns Updated index with orphaned entries removed\n */\nexport function removeOrphanedEntries(\n  index: DraftIndexV2,\n  existingPayloadKeys: Set<string>\n): DraftIndexV2 {\n  const entries: Record<string, DraftEntryMeta> = {}\n  const order: string[] = []\n  const entriesByKey: Partial<Record<string, DraftEntryMeta>> = index.entries\n\n  for (const key of index.order) {\n    const entry = entriesByKey[key]\n    if (existingPayloadKeys.has(key) && entry) {\n      entries[key] = entry\n      order.push(key)\n    }\n  }\n\n  return {\n    v: 2,\n    updatedAt: Date.now(),\n    order,\n    entries\n  }\n}\n","/**\n * V2 Workflow Draft Store\n *\n * Uses per-draft keys in localStorage instead of a single blob.\n * Handles LRU eviction and quota management.\n */\n\nimport { defineStore } from 'pinia'\nimport { ref } from 'vue'\n\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useApp } from '@/scripts/appInstance'\n\nimport type { DraftIndexV2 } from '../base/draftTypes'\nimport { MAX_DRAFTS } from '../base/draftTypes'\nimport {\n  createEmptyIndex,\n  getEntryByPath,\n  getMostRecentKey,\n  moveEntry,\n  removeEntry,\n  removeOrphanedEntries,\n  touchOrder,\n  upsertEntry\n} from '../base/draftCacheV2'\nimport { hashPath } from '../base/hashUtil'\nimport { getWorkspaceId } from '../base/storageKeys'\nimport {\n  deleteOrphanPayloads,\n  deletePayload,\n  deletePayloads,\n  getPayloadKeys,\n  isStorageAvailable,\n  markStorageUnavailable,\n  readIndex,\n  readPayload,\n  writeIndex,\n  writePayload\n} from '../base/storageIO'\n\ninterface DraftMeta {\n  name: string\n  isTemporary: boolean\n}\n\ninterface LoadPersistedWorkflowOptions {\n  preferredPath?: string | null\n  fallbackToLatestDraft?: boolean\n}\n\nexport const useWorkflowDraftStoreV2 = defineStore('workflowDraftV2', () => {\n  // In-memory cache of the index per workspace (synced with localStorage)\n  // Key is workspaceId, value is the cached index\n  const indexCacheByWorkspace = ref<Record<string, DraftIndexV2>>({})\n\n  /**\n   * Gets the current workspace ID fresh (not cached).\n   * This ensures operations use the correct workspace after switches.\n   */\n  function currentWorkspaceId(): string {\n    return getWorkspaceId()\n  }\n\n  /**\n   * Loads the index from localStorage or creates empty.\n   */\n  function loadIndex(): DraftIndexV2 {\n    const workspaceId = currentWorkspaceId()\n\n    const cached = getCachedIndex(workspaceId)\n    if (cached) return cached\n\n    const stored = readIndex(workspaceId)\n    if (stored) {\n      // Clean up any index/payload drift\n      const payloadKeys = new Set(getPayloadKeys(workspaceId))\n      const cleaned = removeOrphanedEntries(stored, payloadKeys)\n      indexCacheByWorkspace.value[workspaceId] = cleaned\n\n      // Also clean up orphan payloads\n      const indexKeys = new Set(cleaned.order)\n      deleteOrphanPayloads(workspaceId, indexKeys)\n\n      return cleaned\n    }\n\n    const emptyIndex = createEmptyIndex()\n    indexCacheByWorkspace.value[workspaceId] = emptyIndex\n    return emptyIndex\n  }\n\n  function getCachedIndex(workspaceId: string): DraftIndexV2 | null {\n    return indexCacheByWorkspace.value[workspaceId]\n  }\n\n  /**\n   * Persists the current index to localStorage.\n   */\n  function persistIndex(index: DraftIndexV2): boolean {\n    const workspaceId = currentWorkspaceId()\n    indexCacheByWorkspace.value[workspaceId] = index\n    return writeIndex(workspaceId, index)\n  }\n\n  /**\n   * Saves a draft (data + metadata).\n   * Primes index cache, writes payload, then persists updated index.\n   */\n  function saveDraft(path: string, data: string, meta: DraftMeta): boolean {\n    if (!isStorageAvailable()) return false\n\n    const workspaceId = currentWorkspaceId()\n    const draftKey = hashPath(path)\n    const now = Date.now()\n\n    // Prime the index cache before writing payload.\n    // loadIndex() runs orphan cleanup on cache miss, which would\n    // delete a payload written before the index is updated.\n    const index = loadIndex()\n\n    // Write payload before persisting the updated index\n    const payloadWritten = writePayload(workspaceId, draftKey, {\n      data,\n      updatedAt: now\n    })\n\n    if (!payloadWritten) {\n      // Quota exceeded - try eviction loop\n      return handleQuotaExceeded(path, data, meta)\n    }\n    const { index: newIndex, evicted } = upsertEntry(\n      index,\n      path,\n      { ...meta, updatedAt: now },\n      MAX_DRAFTS\n    )\n\n    if (!persistIndex(newIndex)) {\n      deletePayload(workspaceId, draftKey)\n      persistIndex(index)\n      return false\n    }\n\n    deletePayloads(workspaceId, evicted)\n    return true\n  }\n\n  /**\n   * Handles quota exceeded by evicting oldest drafts until write succeeds.\n   *\n   * Tolerates index/payload desync: orphaned `order` keys with no matching\n   * entry in `entries` are stripped in-place and the loop continues, rather\n   * than bailing out and leaving evictable drafts behind.\n   *\n   * Recovery writes (`persistIndex(currentIndex)` after a failed write) are\n   * best-effort; their return value is intentionally ignored because there\n   * is no useful action to take when the recovery itself also fails — the\n   * caller will already see `false` and surface the toast. A subsequent\n   * `saveDraft` will re-converge the index via `removeOrphanedEntries`.\n   */\n  function handleQuotaExceeded(\n    path: string,\n    data: string,\n    meta: DraftMeta\n  ): boolean {\n    const workspaceId = currentWorkspaceId()\n    const draftKey = hashPath(path)\n\n    let currentIndex = loadIndex()\n    let evictedCount = 0\n\n    while (currentIndex.order.length > 0) {\n      const oldestKey = currentIndex.order.find((key) => key !== draftKey)\n      if (!oldestKey) break\n\n      const oldestEntry = currentIndex.entries[oldestKey]\n      if (!getIndexEntry(currentIndex, oldestKey)) {\n        currentIndex = stripOrderKey(currentIndex, oldestKey)\n        continue\n      }\n\n      const result = removeEntry(currentIndex, oldestEntry.path)\n      currentIndex = result.index\n      if (result.removedKey) {\n        deletePayload(workspaceId, result.removedKey)\n        evictedCount++\n      }\n\n      const now = Date.now()\n      if (writePayload(workspaceId, draftKey, { data, updatedAt: now })) {\n        const { index: finalIndex } = upsertEntry(\n          currentIndex,\n          path,\n          { ...meta, updatedAt: now },\n          MAX_DRAFTS\n        )\n        if (!persistIndex(finalIndex)) {\n          deletePayload(workspaceId, draftKey)\n          persistIndex(currentIndex)\n          return false\n        }\n        return true\n      }\n    }\n\n    persistIndex(currentIndex)\n    reportQuotaExhausted(currentIndex, evictedCount, payloadByteSize(data))\n    markStorageUnavailable()\n    return false\n  }\n\n  function getIndexEntry(\n    index: DraftIndexV2,\n    key: string\n  ): DraftIndexV2['entries'][string] | undefined {\n    return index.entries[key]\n  }\n\n  /**\n   * Approximates the UTF-8 byte size of the envelope `writePayload` actually\n   * stores. We hard-code `updatedAt: 0` rather than the real timestamp because\n   * the missing ~12 bytes are noise compared to the kilobyte-scale workflow\n   * payload this telemetry exists to measure.\n   */\n  function payloadByteSize(data: string): number {\n    return new TextEncoder().encode(JSON.stringify({ data, updatedAt: 0 }))\n      .length\n  }\n\n  function stripOrderKey(index: DraftIndexV2, orphanKey: string): DraftIndexV2 {\n    return {\n      ...index,\n      updatedAt: Date.now(),\n      order: index.order.filter((key) => key !== orphanKey)\n    }\n  }\n\n  function reportQuotaExhausted(\n    finalIndex: DraftIndexV2,\n    evicted: number,\n    payloadBytes: number\n  ): void {\n    reportError(\n      new Error('localStorage quota exhausted after full draft eviction'),\n      {\n        surface: 'graph',\n        errorType: 'storage_quota_exhausted',\n        level: 'warning',\n        tags: { store: 'workflowDraftStoreV2' },\n        context: {\n          evictedDrafts: evicted,\n          remainingDrafts: finalIndex.order.length,\n          incomingPayloadBytes: payloadBytes\n        }\n      }\n    )\n  }\n\n  /**\n   * Removes a draft.\n   */\n  function removeDraft(path: string): void {\n    const workspaceId = currentWorkspaceId()\n    const index = loadIndex()\n    const { index: newIndex, removedKey } = removeEntry(index, path)\n\n    if (removedKey) {\n      deletePayload(workspaceId, removedKey)\n      persistIndex(newIndex)\n    }\n  }\n\n  /**\n   * Moves a draft from one path to another (rename).\n   */\n  function moveDraft(oldPath: string, newPath: string, name: string): void {\n    const workspaceId = currentWorkspaceId()\n    const index = loadIndex()\n    const result = moveEntry(index, oldPath, newPath, name)\n\n    if (result) {\n      const oldPayload = readPayload(workspaceId, result.oldKey)\n      if (oldPayload) {\n        const written = writePayload(workspaceId, result.newKey, {\n          data: oldPayload.data,\n          updatedAt: oldPayload.updatedAt\n        })\n        if (!written) return\n\n        if (!persistIndex(result.index)) {\n          deletePayload(workspaceId, result.newKey)\n          return\n        }\n        deletePayload(workspaceId, result.oldKey)\n      }\n    }\n  }\n\n  /**\n   * Gets draft data by path.\n   */\n  function getDraft(path: string): {\n    data: string\n    name: string\n    isTemporary: boolean\n    updatedAt: number\n  } | null {\n    const workspaceId = currentWorkspaceId()\n    const index = loadIndex()\n    const entry = getEntryByPath(index, path)\n    if (!entry) return null\n\n    const draftKey = hashPath(path)\n    const payload = readPayload(workspaceId, draftKey)\n    if (!payload) {\n      // Payload missing - clean up index\n      removeDraft(path)\n      return null\n    }\n\n    return {\n      data: payload.data,\n      name: entry.name,\n      isTemporary: entry.isTemporary,\n      updatedAt: payload.updatedAt\n    }\n  }\n\n  /**\n   * Marks a draft as recently used without rewriting its payload.\n   */\n  function markDraftUsed(path: string): void {\n    const index = loadIndex()\n    const entry = getEntryByPath(index, path)\n    if (!entry) return\n\n    const draftKey = hashPath(path)\n    persistIndex({\n      ...index,\n      updatedAt: Date.now(),\n      order: touchOrder(index.order, draftKey)\n    })\n  }\n\n  /**\n   * Gets the most recent draft path.\n   */\n  function getMostRecentPath(): string | null {\n    const index = loadIndex()\n    const key = getMostRecentKey(index)\n    if (!key) return null\n\n    return getIndexEntry(index, key)?.path ?? null\n  }\n\n  /**\n   * Tries to load workflow data into the graph.\n   */\n  async function tryLoadGraph(\n    payload: string | null,\n    workflowName: string | null,\n    onFailure?: () => void\n  ): Promise<boolean> {\n    if (!payload) return false\n    try {\n      const workflow = JSON.parse(payload)\n      await useApp().loadGraphData(workflow, true, true, workflowName)\n      return true\n    } catch (err) {\n      console.error('Failed to load persisted workflow', err)\n      onFailure?.()\n      return false\n    }\n  }\n\n  /**\n   * Loads a draft into the graph.\n   */\n  async function loadDraft(path: string): Promise<boolean> {\n    const draft = getDraft(path)\n    if (!draft) return false\n\n    const loaded = await tryLoadGraph(draft.data, draft.name, () => {\n      removeDraft(path)\n    })\n    if (loaded) {\n      // Direct persisted-draft restores do not go through ComfyWorkflow.load().\n      markDraftUsed(path)\n    }\n\n    return loaded\n  }\n\n  /**\n   * Loads a persisted workflow with fallback chain.\n   */\n  async function loadPersistedWorkflow(\n    options: LoadPersistedWorkflowOptions\n  ): Promise<boolean> {\n    const { preferredPath, fallbackToLatestDraft = false } = options\n\n    // 1. Try preferred path\n    if (preferredPath && (await loadDraft(preferredPath))) {\n      return true\n    }\n\n    // 2. Fall back to most recent draft\n    if (fallbackToLatestDraft) {\n      const mostRecent = getMostRecentPath()\n      if (mostRecent && (await loadDraft(mostRecent))) {\n        return true\n      }\n    }\n\n    return false\n  }\n\n  /**\n   * Resets the store (clears in-memory cache for current workspace).\n   */\n  function reset(): void {\n    const workspaceId = currentWorkspaceId()\n    delete indexCacheByWorkspace.value[workspaceId]\n  }\n\n  return {\n    saveDraft,\n    removeDraft,\n    moveDraft,\n    markDraftUsed,\n    getDraft,\n    getMostRecentPath,\n    loadPersistedWorkflow,\n    reset\n  }\n})\n","import type { ReadOnlyRect } from '@/lib/litegraph/src/interfaces'\n\ninterface PositionableItem {\n  pos?: ArrayLike<number>\n  size?: ArrayLike<number>\n}\n\nexport interface PositionExtents {\n  minX: number\n  minY: number\n  maxX: number\n  maxY: number\n}\n\nexport function calculatePositionExtents(\n  items: Iterable<PositionableItem>\n): PositionExtents | null {\n  let minX = Infinity\n  let minY = Infinity\n  let maxX = -Infinity\n  let maxY = -Infinity\n  for (const item of items) {\n    if (!item.pos || !item.size) continue\n    const x = item.pos[0]\n    const y = item.pos[1]\n    const width = item.size[0]\n    const height = item.size[1]\n    if (![x, y, width, height].every(Number.isFinite)) continue\n    minX = Math.min(minX, x)\n    minY = Math.min(minY, y)\n    maxX = Math.max(maxX, x + width)\n    maxY = Math.max(maxY, y + height)\n  }\n  return minX === Infinity ? null : { minX, minY, maxX, maxY }\n}\n\nexport function createPositionBounds(\n  items: Iterable<PositionableItem>,\n  padding: number\n): ReadOnlyRect | null {\n  if (!Number.isFinite(padding)) return null\n  const extents = calculatePositionExtents(items)\n  if (!extents) return null\n  const { minX, minY, maxX, maxY } = extents\n  return [\n    minX - padding,\n    minY - padding,\n    maxX - minX + padding * 2,\n    maxY - minY + padding * 2\n  ]\n}\n","import { calculatePositionExtents } from '@/utils/positionBounds'\n\n/**\n * Spatial bounds calculations for node layouts\n */\n\ninterface SpatialBounds {\n  minX: number\n  minY: number\n  maxX: number\n  maxY: number\n  width: number\n  height: number\n}\n\nexport interface PositionedNode {\n  pos: [number, number]\n  size: [number, number]\n}\n\n/**\n * Calculate the spatial bounding box of positioned nodes\n */\nexport function calculateNodeBounds(\n  nodes: PositionedNode[]\n): SpatialBounds | null {\n  const extents = calculatePositionExtents(nodes)\n  if (!extents) return null\n  const { minX, minY, maxX, maxY } = extents\n\n  return {\n    minX,\n    minY,\n    maxX,\n    maxY,\n    width: maxX - minX,\n    height: maxY - minY\n  }\n}\n\n/**\n * Enforce minimum viewport dimensions for better visualization\n */\nexport function enforceMinimumBounds(\n  bounds: SpatialBounds,\n  minWidth: number = 2500,\n  minHeight: number = 2000\n): SpatialBounds {\n  let { minX, minY, maxX, maxY, width, height } = bounds\n\n  if (width < minWidth) {\n    const padding = (minWidth - width) / 2\n    minX -= padding\n    maxX += padding\n    width = minWidth\n  }\n\n  if (height < minHeight) {\n    const padding = (minHeight - height) / 2\n    minY -= padding\n    maxY += padding\n    height = minHeight\n  }\n\n  return { minX, minY, maxX, maxY, width, height }\n}\n\n/**\n * Calculate the scale factor to fit bounds within a viewport\n */\nexport function calculateMinimapScale(\n  bounds: SpatialBounds,\n  viewportWidth: number,\n  viewportHeight: number,\n  padding: number = 0.9\n): number {\n  if (bounds.width === 0 || bounds.height === 0) {\n    return 1\n  }\n\n  const scaleX = viewportWidth / bounds.width\n  const scaleY = viewportHeight / bounds.height\n\n  return Math.min(scaleX, scaleY) * padding\n}\n","{\n  \"id\": \"arc\",\n  \"name\": \"Arc\",\n  \"colors\": {\n    \"node_slot\": {\n      \"BOOLEAN\": \"\",\n      \"CLIP\": \"#eacb8b\",\n      \"CLIP_VISION\": \"#A8DADC\",\n      \"CLIP_VISION_OUTPUT\": \"#ad7452\",\n      \"CONDITIONING\": \"#cf876f\",\n      \"CONTROL_NET\": \"#00d78d\",\n      \"CONTROL_NET_WEIGHTS\": \"\",\n      \"FLOAT\": \"\",\n      \"GLIGEN\": \"\",\n      \"IMAGE\": \"#80a1c0\",\n      \"IMAGEUPLOAD\": \"\",\n      \"INT\": \"\",\n      \"LATENT\": \"#b38ead\",\n      \"LATENT_KEYFRAME\": \"\",\n      \"MASK\": \"#a3bd8d\",\n      \"MODEL\": \"#8978a7\",\n      \"SAMPLER\": \"\",\n      \"SIGMAS\": \"\",\n      \"STRING\": \"\",\n      \"STYLE_MODEL\": \"#C2FFAE\",\n      \"T2I_ADAPTER_WEIGHTS\": \"\",\n      \"TAESD\": \"#DCC274\",\n      \"TIMESTEP_KEYFRAME\": \"\",\n      \"UPSCALE_MODEL\": \"\",\n      \"VAE\": \"#be616b\"\n    },\n    \"litegraph_base\": {\n      \"BACKGROUND_IMAGE\": \"data:image/png;base64,\",\n      \"CLEAR_BACKGROUND_COLOR\": \"#2b2f38\",\n      \"NODE_TITLE_COLOR\": \"#b2b7bd\",\n      \"NODE_SELECTED_TITLE_COLOR\": \"#FFF\",\n      \"NODE_TEXT_COLOR\": \"#AAA\",\n      \"NODE_DEFAULT_COLOR\": \"#2b2f38\",\n      \"NODE_DEFAULT_BGCOLOR\": \"#242730\",\n      \"NODE_DEFAULT_BOXCOLOR\": \"#6e7581\",\n      \"NODE_DEFAULT_SHAPE\": 2,\n      \"NODE_BOX_OUTLINE_COLOR\": \"#FFF\",\n      \"NODE_BYPASS_BGCOLOR\": \"#FF00FF\",\n      \"NODE_ERROR_COLOUR\": \"#E00\",\n      \"DEFAULT_SHADOW_COLOR\": \"rgba(0,0,0,0.5)\",\n      \"WIDGET_BGCOLOR\": \"#2b2f38\",\n      \"WIDGET_OUTLINE_COLOR\": \"#6e7581\",\n      \"WIDGET_TEXT_COLOR\": \"#DDD\",\n      \"WIDGET_SECONDARY_TEXT_COLOR\": \"#b2b7bd\",\n      \"WIDGET_DISABLED_TEXT_COLOR\": \"#5c626d\",\n      \"LINK_COLOR\": \"#9A9\",\n      \"EVENT_LINK_COLOR\": \"#A86\",\n      \"CONNECTING_LINK_COLOR\": \"#AFA\"\n    },\n    \"comfy_base\": {\n      \"fg-color\": \"#fff\",\n      \"bg-color\": \"#2b2f38\",\n      \"comfy-menu-bg\": \"#242730\",\n      \"comfy-menu-secondary-bg\": \"#22252E\",\n      \"comfy-input-bg\": \"#2b2f38\",\n      \"input-text\": \"#ddd\",\n      \"descrip-text\": \"#b2b7bd\",\n      \"drag-text\": \"#ccc\",\n      \"error-text\": \"#ff4444\",\n      \"border-color\": \"#6e7581\",\n      \"tr-even-bg-color\": \"#2b2f38\",\n      \"tr-odd-bg-color\": \"#242730\",\n      \"content-bg\": \"#6e7581\",\n      \"content-fg\": \"#fff\",\n      \"content-hover-bg\": \"#2b2f38\",\n      \"content-hover-fg\": \"#fff\",\n      \"bar-shadow\": \"rgba(8, 8, 8, 0.75) 0 0 0.5rem\"\n    }\n  }\n}\n","{\n  \"id\": \"dark\",\n  \"name\": \"Dark (Default)\",\n  \"colors\": {\n    \"node_slot\": {\n      \"CLIP\": \"#FFD500\",\n      \"CLIP_VISION\": \"#A8DADC\",\n      \"CLIP_VISION_OUTPUT\": \"#ad7452\",\n      \"CONDITIONING\": \"#FFA931\",\n      \"CONTROL_NET\": \"#6EE7B7\",\n      \"IMAGE\": \"#64B5F6\",\n      \"LATENT\": \"#FF9CF9\",\n      \"MASK\": \"#81C784\",\n      \"MODEL\": \"#B39DDB\",\n      \"STYLE_MODEL\": \"#C2FFAE\",\n      \"VAE\": \"#FF6E6E\",\n      \"NOISE\": \"#B0B0B0\",\n      \"GUIDER\": \"#66FFFF\",\n      \"SAMPLER\": \"#ECB4B4\",\n      \"SIGMAS\": \"#CDFFCD\",\n      \"TAESD\": \"#DCC274\"\n    },\n    \"litegraph_base\": {\n      \"BACKGROUND_IMAGE\": \"data:image/png;base64,\",\n      \"CLEAR_BACKGROUND_COLOR\": \"#141414\",\n      \"NODE_TITLE_COLOR\": \"#999\",\n      \"NODE_SELECTED_TITLE_