",\n      \"comfy-menu-hover-bg\": \"#ccc\",\n      \"comfy-menu-secondary-bg\": \"#EEE\",\n      \"comfy-input-bg\": \"#C9C9C9\",\n      \"input-text\": \"#222\",\n      \"descrip-text\": \"#444\",\n      \"drag-text\": \"#555\",\n      \"error-text\": \"#F44336\",\n      \"border-color\": \"#888\",\n      \"tr-even-bg-color\": \"#f9f9f9\",\n      \"tr-odd-bg-color\": \"#fff\",\n      \"content-bg\": \"#e0e0e0\",\n      \"content-fg\": \"#222\",\n      \"content-hover-bg\": \"#adadad\",\n      \"content-hover-fg\": \"#222\",\n      \"bar-shadow\": \"rgba(16, 16, 16, 0.25) 0 0 0.5rem\",\n      \"interface-panel-box-shadow\": \"1px 1px 8px 0 rgba(0, 0, 0, 0.2)\",\n      \"interface-panel-drop-shadow\": \"1px 1px 4px rgba(0, 0, 0, 0.4)\",\n      \"interface-floating-panel-shadow\": \"0 2px 16px 0 rgba(0, 0, 0, 0.2)\",\n      \"interface-panel-hover-surface\": \"var(--color-gray-200)\",\n      \"interface-panel-selected-surface\": \"color-mix(in srgb, var(--interface-panel-surface) 78%, var(--contrast-mix-color))\",\n      \"contrast-mix-color\": \"#000\"\n    }\n  }\n}\n","{\n  \"id\": \"nord\",\n  \"name\": \"Nord\",\n  \"colors\": {\n    \"node_slot\": {\n      \"BOOLEAN\": \"\",\n      \"CLIP\": \"#eacb8b\",\n      \"CLIP_VISION\": \"#A8DADC\",\n      \"CLIP_VISION_OUTPUT\": \"#ad7452\",\n      \"CONDITIONING\": \"#cf876f\",\n      \"CONTROL_NET\": \"#00d78d\",\n      \"CONTROL_NET_WEIGHTS\": \"\",\n      \"FLOAT\": \"\",\n      \"GLIGEN\": \"\",\n      \"IMAGE\": \"#80a1c0\",\n      \"IMAGEUPLOAD\": \"\",\n      \"INT\": \"\",\n      \"LATENT\": \"#b38ead\",\n      \"LATENT_KEYFRAME\": \"\",\n      \"MASK\": \"#a3bd8d\",\n      \"MODEL\": \"#8978a7\",\n      \"SAMPLER\": \"\",\n      \"SIGMAS\": \"\",\n      \"STRING\": \"\",\n      \"STYLE_MODEL\": \"#C2FFAE\",\n      \"T2I_ADAPTER_WEIGHTS\": \"\",\n      \"TAESD\": \"#DCC274\",\n      \"TIMESTEP_KEYFRAME\": \"\",\n      \"UPSCALE_MODEL\": \"\",\n      \"VAE\": \"#be616b\"\n    },\n    \"litegraph_base\": {\n      \"BACKGROUND_IMAGE\": \"data:image/png;base64,\",\n      \"CLEAR_BACKGROUND_COLOR\": \"#212732\",\n      \"NODE_TITLE_COLOR\": \"#999\",\n      \"NODE_SELECTED_TITLE_COLOR\": \"#e5eaf0\",\n      \"NODE_TEXT_COLOR\": \"#bcc2c8\",\n      \"NODE_DEFAULT_COLOR\": \"#2e3440\",\n      \"NODE_DEFAULT_BGCOLOR\": \"#161b22\",\n      \"NODE_DEFAULT_BOXCOLOR\": \"#545d70\",\n      \"NODE_DEFAULT_SHAPE\": 2,\n      \"NODE_BOX_OUTLINE_COLOR\": \"#e5eaf0\",\n      \"NODE_BYPASS_BGCOLOR\": \"#FF00FF\",\n      \"NODE_ERROR_COLOUR\": \"#E00\",\n      \"DEFAULT_SHADOW_COLOR\": \"rgba(0,0,0,0.5)\",\n      \"WIDGET_BGCOLOR\": \"#2e3440\",\n      \"WIDGET_OUTLINE_COLOR\": \"#545d70\",\n      \"WIDGET_TEXT_COLOR\": \"#bcc2c8\",\n      \"WIDGET_SECONDARY_TEXT_COLOR\": \"#999\",\n      \"WIDGET_DISABLED_TEXT_COLOR\": \"#545d70\",\n      \"LINK_COLOR\": \"#9A9\",\n      \"EVENT_LINK_COLOR\": \"#A86\",\n      \"CONNECTING_LINK_COLOR\": \"#AFA\"\n    },\n    \"comfy_base\": {\n      \"fg-color\": \"#e5eaf0\",\n      \"bg-color\": \"#2e3440\",\n      \"comfy-menu-bg\": \"#161b22\",\n      \"comfy-menu-secondary-bg\": \"#14181F\",\n      \"comfy-input-bg\": \"#2e3440\",\n      \"input-text\": \"#bcc2c8\",\n      \"descrip-text\": \"#999\",\n      \"drag-text\": \"#ccc\",\n      \"error-text\": \"#ff4444\",\n      \"border-color\": \"#545d70\",\n      \"tr-even-bg-color\": \"#2e3440\",\n      \"tr-odd-bg-color\": \"#161b22\",\n      \"content-bg\": \"#545d70\",\n      \"content-fg\": \"#e5eaf0\",\n      \"content-hover-bg\": \"#2e3440\",\n      \"content-hover-fg\": \"#e5eaf0\",\n      \"bar-shadow\": \"rgba(0, 0, 0, 0.75) 0 0 0.5rem\"\n    }\n  }\n}\n","{\n  \"id\": \"solarized\",\n  \"name\": \"Solarized\",\n  \"colors\": {\n    \"node_slot\": {\n      \"CLIP\": \"#2AB7CA\",\n      \"CLIP_VISION\": \"#6c71c4\",\n      \"CLIP_VISION_OUTPUT\": \"#859900\",\n      \"CONDITIONING\": \"#d33682\",\n      \"CONTROL_NET\": \"#d1ffd7\",\n      \"IMAGE\": \"#5940bb\",\n      \"LATENT\": \"#268bd2\",\n      \"MASK\": \"#CCC9E7\",\n      \"MODEL\": \"#dc322f\",\n      \"STYLE_MODEL\": \"#1a998a\",\n      \"UPSCALE_MODEL\": \"#054A29\",\n      \"VAE\": \"#facfad\"\n    },\n    \"litegraph_base\": {\n      \"NODE_TITLE_COLOR\": \"#fdf6e3\",\n      \"NODE_SELECTED_TITLE_COLOR\": \"#A9D400\",\n      \"NODE_TEXT_COLOR\": \"#657b83\",\n      \"NODE_DEFAULT_COLOR\": \"#094656\",\n      \"NODE_DEFAULT_BGCOLOR\": \"#073642\",\n      \"NODE_DEFAULT_BOXCOLOR\": \"#839496\",\n      \"NODE_DEFAULT_SHAPE\": 2,\n      \"NODE_BOX_OUTLINE_COLOR\": \"#fdf6e3\",\n      \"NODE_BYPASS_BGCOLOR\": \"#FF00FF\",\n      \"NODE_ERROR_COLOUR\": \"#E00\",\n      \"DEFAULT_SHADOW_COLOR\": \"rgba(0,0,0,0.5)\",\n      \"WIDGET_BGCOLOR\": \"#002b36\",\n      \"WIDGET_OUTLINE_COLOR\": \"#839496\",\n      \"WIDGET_TEXT_COLOR\": \"#fdf6e3\",\n      \"WIDGET_SECONDARY_TEXT_COLOR\": \"#93a1a1\",\n      \"WIDGET_DISABLED_TEXT_COLOR\": \"#657b83\",\n      \"LINK_COLOR\": \"#2aa198\",\n      \"EVENT_LINK_COLOR\": \"#268bd2\",\n      \"CONNECTING_LINK_COLOR\": \"#859900\"\n    },\n    \"comfy_base\": {\n      \"fg-color\": \"#fdf6e3\",\n      \"bg-color\": \"#002b36\",\n      \"comfy-menu-bg\": \"#073642\",\n      \"comfy-menu-secondary-bg\": \"#06323D\",\n      \"comfy-input-bg\": \"#002b36\",\n      \"input-text\": \"#93a1a1\",\n      \"descrip-text\": \"#586e75\",\n      \"drag-text\": \"#839496\",\n      \"error-text\": \"#dc322f\",\n      \"border-color\": \"#657b83\",\n      \"tr-even-bg-color\": \"#002b36\",\n      \"tr-odd-bg-color\": \"#073642\",\n      \"content-bg\": \"#657b83\",\n      \"content-fg\": \"#fdf6e3\",\n      \"content-hover-bg\": \"#002b36\",\n      \"content-hover-fg\": \"#fdf6e3\",\n      \"bar-shadow\": \"rgba(16, 16, 16, 0.5) 0 0 0.5rem\"\n    }\n  }\n}\n","import arc from '@/assets/palettes/arc.json' with { type: 'json' }\nimport dark from '@/assets/palettes/dark.json' with { type: 'json' }\nimport github from '@/assets/palettes/github.json' with { type: 'json' }\nimport light from '@/assets/palettes/light.json' with { type: 'json' }\nimport nord from '@/assets/palettes/nord.json' with { type: 'json' }\nimport solarized from '@/assets/palettes/solarized.json' with { type: 'json' }\nimport type {\n  ColorPalettes,\n  CompletedPalette\n} from '@/schemas/colorPaletteSchema'\n\nexport const CORE_COLOR_PALETTES: ColorPalettes = {\n  dark,\n  light,\n  solarized,\n  arc,\n  nord,\n  github\n} as const\n\nexport const DEFAULT_COLOR_PALETTE: CompletedPalette = dark\nexport const DEFAULT_DARK_COLOR_PALETTE: CompletedPalette = dark\nexport const DEFAULT_LIGHT_COLOR_PALETTE: CompletedPalette = light\n","import { defineStore } from 'pinia'\nimport { computed, ref } from 'vue'\n\nimport {\n  CORE_COLOR_PALETTES,\n  DEFAULT_COLOR_PALETTE,\n  DEFAULT_DARK_COLOR_PALETTE,\n  DEFAULT_LIGHT_COLOR_PALETTE\n} from '@/constants/coreColorPalettes'\nimport type {\n  ColorPalettes,\n  CompletedPalette,\n  Palette\n} from '@/schemas/colorPaletteSchema'\n\nexport const useColorPaletteStore = defineStore('colorPalette', () => {\n  const customPalettes = ref<ColorPalettes>({})\n  const activePaletteId = ref<string>(DEFAULT_COLOR_PALETTE.id)\n\n  const palettesLookup = computed<Partial<ColorPalettes>>(() => ({\n    ...CORE_COLOR_PALETTES,\n    ...customPalettes.value\n  }))\n\n  const palettes = computed(() =>\n    Object.values(palettesLookup.value).filter(\n      (palette): palette is Palette => palette !== undefined\n    )\n  )\n  const completedActivePalette = computed(() => {\n    const activePalette =\n      palettesLookup.value[activePaletteId.value] ?? DEFAULT_COLOR_PALETTE\n    return completePalette(activePalette)\n  })\n\n  const addCustomPalette = (palette: Palette) => {\n    if (palette.id in palettesLookup.value) {\n      throw new Error(`Palette with id ${palette.id} already exists`)\n    }\n\n    customPalettes.value[palette.id] = palette\n    activePaletteId.value = palette.id\n  }\n\n  const deleteCustomPalette = (id: string) => {\n    if (!(id in customPalettes.value)) {\n      throw new Error(`Palette with id ${id} does not exist`)\n    }\n\n    delete customPalettes.value[id]\n    activePaletteId.value = CORE_COLOR_PALETTES.dark.id\n  }\n\n  const isCustomPalette = (id: string) => {\n    return id in customPalettes.value\n  }\n\n  /**\n   * Completes the palette with default values for missing colors.\n   *\n   * @param palette - The palette to complete.\n   * @returns The completed palette.\n   */\n  const completePalette = (palette: Palette): CompletedPalette => {\n    // Set comfy-menu-secondary-bg to comfy-menu-bg if not set\n    if (\n      palette.colors.comfy_base['comfy-menu-bg'] &&\n      !palette.colors.comfy_base['comfy-menu-secondary-bg']\n    ) {\n      palette.colors.comfy_base['comfy-menu-secondary-bg'] =\n        palette.colors.comfy_base['comfy-menu-bg']\n    }\n\n    const defaultPalette = palette.light_theme\n      ? DEFAULT_LIGHT_COLOR_PALETTE\n      : DEFAULT_DARK_COLOR_PALETTE\n\n    return {\n      ...palette,\n      colors: {\n        ...palette.colors,\n        node_slot: {\n          ...defaultPalette.colors.node_slot,\n          ...palette.colors.node_slot\n        },\n        litegraph_base: {\n          ...defaultPalette.colors.litegraph_base,\n          ...palette.colors.litegraph_base\n        },\n        comfy_base: {\n          ...defaultPalette.colors.comfy_base,\n          ...palette.colors.comfy_base\n        }\n      }\n    }\n  }\n\n  return {\n    // State\n    customPalettes,\n    activePaletteId,\n\n    // Getters\n    palettesLookup,\n    palettes,\n    completedActivePalette,\n\n    // Actions\n    isCustomPalette,\n    addCustomPalette,\n    deleteCustomPalette,\n    completePalette\n  }\n})\n","import type { LGraph } from '@/lib/litegraph/src/litegraph'\nimport { calculateNodeBounds } from '@/renderer/core/spatial/boundsCalculator'\nimport { useLinkStore } from '@/stores/linkStore'\nimport { graphScopeOf } from '@/types/graphScopeId'\nimport { createNodeLocatorId } from '@/types/nodeIdentification'\n\nimport type {\n  MinimapBounds,\n  MinimapGroupData,\n  MinimapLinkData,\n  MinimapNodeData,\n  MinimapNodeProgressStates\n} from '../types'\n\nexport class MinimapDataSource {\n  constructor(\n    private readonly graph: LGraph | null,\n    private readonly nodeProgressStates: MinimapNodeProgressStates = {}\n  ) {}\n\n  private nodes: MinimapNodeData[] | null = null\n\n  getNodes(): MinimapNodeData[] {\n    this.nodes ??= this.buildNodes()\n    return this.nodes\n  }\n\n  private buildNodes(): MinimapNodeData[] {\n    const graph = this.graph\n    if (!graph) return []\n\n    const nodeProgressStates = this.nodeProgressStates\n    const containingSubgraphId = graph.isRootGraph ? null : graph.id\n\n    return graph._nodes.map((node) => {\n      const [width, height] = node.renderingSize\n      const locatorId = createNodeLocatorId(containingSubgraphId, node.id)\n      const executionState = Object.hasOwn(nodeProgressStates, locatorId)\n        ? nodeProgressStates[locatorId].state\n        : null\n\n      return {\n        id: node.id,\n        x: node.pos[0],\n        y: node.pos[1],\n        width,\n        height,\n        bgcolor: node.bgcolor,\n        mode: node.mode,\n        hasErrors: node.has_errors,\n        executionState\n      }\n    })\n  }\n\n  getLinks(): MinimapLinkData[] {\n    const graph = this.graph\n    if (!graph) return []\n\n    const linkStore = useLinkStore()\n    const scope = graphScopeOf(graph)\n    const links: MinimapLinkData[] = []\n    const nodeMap = new Map(this.getNodes().map((node) => [node.id, node]))\n\n    for (const link of linkStore.graphTopologies(scope)) {\n      const sourceNode = nodeMap.get(link.originNodeId)\n      const targetNode = nodeMap.get(link.targetNodeId)\n      if (!sourceNode || !targetNode) continue\n\n      links.push({\n        sourceNode,\n        targetNode,\n        sourceSlot: link.originSlot,\n        targetSlot: link.targetSlot\n      })\n    }\n\n    return links\n  }\n\n  getGroups(): MinimapGroupData[] {\n    return (\n      this.graph?._groups.map((group) => ({\n        x: group.pos[0],\n        y: group.pos[1],\n        width: group.size[0],\n        height: group.size[1],\n        color: group.color\n      })) ?? []\n    )\n  }\n\n  getBounds(): MinimapBounds {\n    return (\n      calculateNodeBounds(\n        this.getNodes().map((node) => ({\n          pos: [node.x, node.y],\n          size: [node.width, node.height]\n        }))\n      ) ?? {\n        minX: 0,\n        minY: 0,\n        maxX: 100,\n        maxY: 100,\n        width: 100,\n        height: 100\n      }\n    )\n  }\n\n  getNodeCount(): number {\n    return this.graph?._nodes.length ?? 0\n  }\n\n  hasData(): boolean {\n    return this.getNodeCount() > 0\n  }\n}\n","import type { LGraph } from '@/lib/litegraph/src/litegraph'\nimport { LGraphEventMode } from '@/lib/litegraph/src/litegraph'\nimport { useColorPaletteStore } from '@/stores/workspace/colorPaletteStore'\nimport { adjustColor } from '@/utils/colorUtil'\n\nimport { MinimapDataSource } from './data/MinimapDataSource'\nimport type {\n  MinimapNodeData,\n  MinimapNodeExecutionState,\n  MinimapRenderContext\n} from './types'\n\nexport const MINIMAP_DECORATION_POP_MS = 260\n\n/**\n * Get theme-aware colors for the minimap\n */\nfunction getMinimapColors() {\n  const colorPaletteStore = useColorPaletteStore()\n  const palette = colorPaletteStore.completedActivePalette\n  const isLightTheme = palette.light_theme\n\n  return {\n    nodeColor: isLightTheme ? '#3DA8E099' : '#0B8CE999',\n    nodeColorDefault: isLightTheme ? '#D9D9D9' : '#353535',\n    linkColor: isLightTheme ? '#616161' : '#B3B3B3',\n    slotColor: isLightTheme ? '#616161' : '#B3B3B3',\n    groupColor: isLightTheme ? '#A2D3EC' : '#1F547A',\n    groupColorDefault: isLightTheme ? '#283640' : '#B3C1CB',\n    bypassColor: isLightTheme ? '#DBDBDB' : '#4B184B',\n    errorColor: '#FF0000',\n    runningColor: '#00FF00',\n    successColor: '#239B23',\n    activityOutlineColor:\n      palette.colors.litegraph_base.NODE_SELECTED_TITLE_COLOR,\n    isLightTheme\n  }\n}\n\n/**\n * Get node color based on settings and node properties (Single Responsibility)\n */\nfunction getNodeColor(\n  node: MinimapNodeData,\n  settings: MinimapRenderContext['settings'],\n  colors: ReturnType<typeof getMinimapColors>\n): string {\n  if (settings.renderBypass && node.mode === LGraphEventMode.BYPASS) {\n    return colors.bypassColor\n  }\n\n  if (settings.nodeColors) {\n    if (node.bgcolor) {\n      return colors.isLightTheme\n        ? adjustColor(node.bgcolor, { lightness: 0.5 })\n        : node.bgcolor\n    }\n    return colors.nodeColorDefault\n  }\n\n  return colors.nodeColor\n}\n\n/**\n * Render groups on the minimap\n */\nfunction renderGroups(\n  ctx: CanvasRenderingContext2D,\n  dataSource: MinimapDataSource,\n  offsetX: number,\n  offsetY: number,\n  context: MinimapRenderContext,\n  colors: ReturnType<typeof getMinimapColors>\n) {\n  const groups = dataSource.getGroups()\n  if (groups.length === 0) return\n\n  for (const group of groups) {\n    const x = (group.x - context.bounds.minX) * context.scale + offsetX\n    const y = (group.y - context.bounds.minY) * context.scale + offsetY\n    const w = group.width * context.scale\n    const h = group.height * context.scale\n\n    let color = colors.groupColor\n\n    if (context.settings.nodeColors) {\n      color = group.color ?? colors.groupColorDefault\n\n      if (colors.isLightTheme) {\n        color = adjustColor(color, { opacity: 0.5 })\n      }\n    }\n\n    ctx.fillStyle = color\n    ctx.fillRect(x, y, w, h)\n  }\n}\n\nfunction renderNodeDecorations(\n  ctx: CanvasRenderingContext2D,\n  nodes: readonly MinimapNodeData[],\n  offsetX: number,\n  offsetY: number,\n  context: MinimapRenderContext,\n  colors: ReturnType<typeof getMinimapColors>\n) {\n  const decorations = new Map(\n    (context.decorations ?? []).map((decoration) => [\n      decoration.target.nodeId,\n      decoration\n    ])\n  )\n  if (decorations.size === 0) return\n\n  const now = context.now ?? performance.now()\n  ctx.fillStyle = colors.nodeColor\n  ctx.strokeStyle = colors.activityOutlineColor\n  ctx.lineWidth = 1\n  for (const node of nodes) {\n    const decoration = decorations.get(node.id)\n    if (!decoration) continue\n    const elapsed = Math.max(0, now - (decoration.enteredAt ?? now))\n    const progress =\n      decoration.enter === 'pop'\n        ? Math.min(1, elapsed / MINIMAP_DECORATION_POP_MS)\n        : 1\n    const eased = 1 - (1 - progress) ** 3\n    const x = (node.x - context.bounds.minX) * context.scale + offsetX\n    const y = (node.y - context.bounds.minY) * context.scale + offsetY\n    const width = Math.max(2, node.width * context.scale * eased)\n    const height = Math.max(2, node.height * context.scale * eased)\n    const centerX = x + (node.width * context.scale) / 2\n    const centerY = y + (node.height * context.scale) / 2\n    ctx.fillRect(centerX - width / 2, centerY - height / 2, width, height)\n    ctx.strokeRect(centerX - width / 2, centerY - height / 2, width, height)\n  }\n}\n\n/**\n * Render nodes on the minimap with performance optimizations\n */\nfunction renderNodes(\n  ctx: CanvasRenderingContext2D,\n  dataSource: MinimapDataSource,\n  offsetX: number,\n  offsetY: number,\n  context: MinimapRenderContext,\n  colors: ReturnType<typeof getMinimapColors>\n) {\n  const nodes = dataSource.getNodes()\n  if (nodes.length === 0) return\n\n  ctx.save()\n\n  // Group nodes by color for batch rendering (performance optimization)\n  const nodesByColor = new Map<\n    string,\n    Array<{\n      x: number\n      y: number\n      w: number\n      h: number\n      hasErrors?: boolean\n      executionState?: MinimapNodeExecutionState | null\n    }>\n  >()\n\n  for (const node of nodes) {\n    const x = (node.x - context.bounds.minX) * context.scale + offsetX\n    const y = (node.y - context.bounds.minY) * context.scale + offsetY\n    const w = node.width * context.scale\n    const h = node.height * context.scale\n\n    const color = getNodeColor(node, context.settings, colors)\n\n    if (!nodesByColor.has(color)) {\n      nodesByColor.set(color, [])\n    }\n\n    nodesByColor.get(color)!.push({\n      x,\n      y,\n      w,\n      h,\n      hasErrors: node.hasErrors,\n      executionState: node.executionState\n    })\n  }\n\n  // Batch render nodes by color\n  for (const [color, nodes] of nodesByColor) {\n    ctx.fillStyle = color\n    for (const node of nodes) {\n      ctx.fillRect(node.x, node.y, node.w, node.h)\n    }\n  }\n\n  renderNodeDecorations(ctx, nodes, offsetX, offsetY, context, colors)\n\n  ctx.lineWidth = 0.3\n  for (const nodes of nodesByColor.values()) {\n    for (const node of nodes) {\n      if (node.hasErrors && context.settings.renderError) {\n        ctx.strokeStyle = colors.errorColor\n        ctx.strokeRect(node.x, node.y, node.w, node.h)\n      } else if (node.executionState === 'running') {\n        ctx.strokeStyle = colors.runningColor\n        ctx.strokeRect(node.x, node.y, node.w, node.h)\n      } else if (node.executionState === 'finished') {\n        ctx.strokeStyle = colors.successColor\n        ctx.strokeRect(node.x, node.y, node.w, node.h)\n      } else if (\n        node.executionState === 'error' &&\n        context.settings.renderError\n      ) {\n        ctx.strokeStyle = colors.errorColor\n        ctx.strokeRect(node.x, node.y, node.w, node.h)\n      }\n    }\n  }\n\n  ctx.restore()\n}\n\n/**\n * Render connections on the minimap\n */\nfunction renderConnections(\n  ctx: CanvasRenderingContext2D,\n  dataSource: MinimapDataSource,\n  offsetX: number,\n  offsetY: number,\n  context: MinimapRenderContext,\n  colors: ReturnType<typeof getMinimapColors>\n) {\n  const links = dataSource.getLinks()\n  if (links.length === 0) return\n\n  ctx.strokeStyle = colors.linkColor\n  ctx.lineWidth = 0.3\n\n  const slotRadius = Math.max(context.scale, 0.5)\n  const connections: Array<{\n    x1: number\n    y1: number\n    x2: number\n    y2: number\n  }> = []\n\n  for (const link of links) {\n    const x1 =\n      (link.sourceNode.x - context.bounds.minX) * context.scale + offsetX\n    const y1 =\n      (link.sourceNode.y - context.bounds.minY) * context.scale + offsetY\n    const x2 =\n      (link.targetNode.x - context.bounds.minX) * context.scale + offsetX\n    const y2 =\n      (link.targetNode.y - context.bounds.minY) * context.scale + offsetY\n\n    const outputX = x1 + link.sourceNode.width * context.scale\n    const outputY = y1 + link.sourceNode.height * context.scale * 0.2\n    const inputX = x2\n    const inputY = y2 + link.targetNode.height * context.scale * 0.2\n\n    // Draw connection line\n    ctx.beginPath()\n    ctx.moveTo(outputX, outputY)\n    ctx.lineTo(inputX, inputY)\n    ctx.stroke()\n\n    connections.push({ x1: outputX, y1: outputY, x2: inputX, y2: inputY })\n  }\n\n  // Render connection slots on top\n  ctx.fillStyle = colors.slotColor\n  for (const conn of connections) {\n    // Output slot\n    ctx.beginPath()\n    ctx.arc(conn.x1, conn.y1, slotRadius, 0, Math.PI * 2)\n    ctx.fill()\n\n    // Input slot\n    ctx.beginPath()\n    ctx.arc(conn.x2, conn.y2, slotRadius, 0, Math.PI * 2)\n    ctx.fill()\n  }\n}\n\n/**\n * Render a graph to a minimap canvas\n */\nexport function renderMinimapToCanvas(\n  canvas: HTMLCanvasElement,\n  graph: LGraph,\n  context: MinimapRenderContext\n) {\n  const ctx = canvas.getContext('2d')\n  if (!ctx) return\n\n  // Clear canvas\n  ctx.clearRect(0, 0, context.width, context.height)\n\n  const dataSource = new MinimapDataSource(graph, context.nodeProgressStates)\n\n  // Fast path for empty graph\n  if (!dataSource.hasData()) {\n    return\n  }\n\n  const colors = getMinimapColors()\n  const offsetX = (context.width - context.bounds.width * context.scale) / 2\n  const offsetY = (context.height - context.bounds.height * context.scale) / 2\n\n  // Render in correct order: groups -> links -> nodes\n  if (context.settings.showGroups) {\n    renderGroups(ctx, dataSource, offsetX, offsetY, context, colors)\n  }\n\n  if (context.settings.showLinks) {\n    renderConnections(ctx, dataSource, offsetX, offsetY, context, colors)\n  }\n\n  renderNodes(ctx, dataSource, offsetX, offsetY, context, colors)\n}\n","import type { LGraph } from '@/lib/litegraph/src/litegraph'\nimport {\n  calculateMinimapScale,\n  calculateNodeBounds\n} from '@/renderer/core/spatial/boundsCalculator'\n\nimport { renderMinimapToCanvas } from '../../extensions/minimap/minimapCanvasRenderer'\n\n/**\n * Render a graph to a thumbnail data URL.\n * Used by workflow thumbnail generation.\n */\nexport function createGraphThumbnail(\n  graph: LGraph | null | undefined\n): string | null {\n  if (!graph || graph._nodes.length === 0) {\n    return null\n  }\n\n  const width = 250\n  const height = 200\n\n  // Calculate bounds using spatial calculator\n  const bounds = calculateNodeBounds(graph._nodes)\n  if (!bounds) {\n    return null\n  }\n\n  const scale = calculateMinimapScale(bounds, width, height)\n\n  // Create detached canvas\n  const canvas = document.createElement('canvas')\n  canvas.width = width\n  canvas.height = height\n\n  // Render the minimap\n  renderMinimapToCanvas(canvas, graph, {\n    bounds,\n    scale,\n    settings: {\n      nodeColors: true,\n      showLinks: false,\n      showGroups: true,\n      renderBypass: false,\n      renderError: false\n    },\n    width,\n    height\n  })\n\n  const dataUrl = canvas.toDataURL()\n\n  // Explicit cleanup (optional but good practice)\n  const ctx = canvas.getContext('2d')\n  if (ctx) {\n    ctx.clearRect(0, 0, width, height)\n  }\n\n  return dataUrl\n}\n","import { ref } from 'vue'\n\nimport type { LGraph } from '@/lib/litegraph/src/litegraph'\nimport type { ComfyWorkflow } from '@/platform/workflow/management/stores/workflowStore'\n\nimport { createGraphThumbnail } from './graphThumbnailRenderer'\n\n// Store thumbnails for each workflow\nconst workflowThumbnails = ref<Map<string, string>>(new Map())\n\nexport const useWorkflowThumbnail = () => {\n  /**\n   * Capture a thumbnail of the given graph\n   */\n  const createMinimapPreview = (\n    graph: LGraph | null | undefined\n  ): Promise<string | null> => {\n    try {\n      const thumbnailDataUrl = createGraphThumbnail(graph)\n      return Promise.resolve(thumbnailDataUrl)\n    } catch (error) {\n      console.error('Failed to capture canvas thumbnail:', error)\n      return Promise.resolve(null)\n    }\n  }\n\n  /**\n   * Store a thumbnail of the given graph for a workflow\n   */\n  const storeThumbnail = async (\n    workflow: ComfyWorkflow,\n    graph: LGraph | null | undefined\n  ) => {\n    const thumbnail = await createMinimapPreview(graph)\n    if (thumbnail) {\n      // Clean up existing thumbnail if it exists\n      const existingThumbnail = workflowThumbnails.value.get(workflow.key)\n      if (existingThumbnail) {\n        URL.revokeObjectURL(existingThumbnail)\n      }\n      workflowThumbnails.value.set(workflow.key, thumbnail)\n    }\n  }\n\n  /**\n   * Get a thumbnail for a workflow\n   */\n  const getThumbnail = (workflowKey: string): string | undefined => {\n    return workflowThumbnails.value.get(workflowKey)\n  }\n\n  /**\n   * Clear a thumbnail for a workflow\n   */\n  const clearThumbnail = (workflowKey: string) => {\n    const thumbnail = workflowThumbnails.value.get(workflowKey)\n    if (thumbnail) {\n      URL.revokeObjectURL(thumbnail)\n    }\n    workflowThumbnails.value.delete(workflowKey)\n  }\n\n  /**\n   * Clear all thumbnails\n   */\n  const clearAllThumbnails = () => {\n    for (const thumbnail of workflowThumbnails.value.values()) {\n      URL.revokeObjectURL(thumbnail)\n    }\n    workflowThumbnails.value.clear()\n  }\n\n  /**\n   * Move a thumbnail from one workflow key to another (useful for workflow renaming)\n   */\n  const moveWorkflowThumbnail = (oldKey: string, newKey: string) => {\n    // Don't do anything if moving to the same key\n    if (oldKey === newKey) return\n\n    const thumbnail = workflowThumbnails.value.get(oldKey)\n    if (thumbnail) {\n      workflowThumbnails.value.set(newKey, thumbnail)\n      workflowThumbnails.value.delete(oldKey)\n    }\n  }\n\n  return {\n    createMinimapPreview,\n    storeThumbnail,\n    getThumbnail,\n    clearThumbnail,\n    clearAllThumbnails,\n    moveWorkflowThumbnail,\n    workflowThumbnails\n  }\n}\n","export const LAYER_EDITOR_DIALOG_KEY = 'global-layer-editor'\n","import type { SerializedNodeId } from '@/types/nodeId'\n\nexport interface FlattenableWorkflowNode {\n  id: SerializedNodeId\n  type: string\n  mode?: number\n  widgets_values?: readonly unknown[] | Record<string, unknown>\n  properties?: Record<string, unknown>\n}\n\nexport interface FlattenableWorkflowGraph {\n  nodes?: readonly FlattenableWorkflowNode[]\n  definitions?: {\n    subgraphs?: readonly unknown[]\n  }\n}\n\nexport interface FlattenableSubgraphDefinition {\n  id: string\n  name: string\n  nodes: readonly FlattenableWorkflowNode[]\n  definitions?: {\n    subgraphs?: readonly FlattenableSubgraphDefinition[]\n  }\n}\n\nfunction isFlattenableWorkflowNode(\n  value: unknown\n): value is FlattenableWorkflowNode {\n  if (value === null || typeof value !== 'object') return false\n  const candidate = value as Record<string, unknown>\n  return (\n    (typeof candidate.id === 'string' || typeof candidate.id === 'number') &&\n    typeof candidate.type === 'string'\n  )\n}\n\nfunction parseWorkflowNodes(\n  nodes: readonly unknown[]\n): readonly FlattenableWorkflowNode[] | undefined {\n  return nodes.every(isFlattenableWorkflowNode) ? nodes : undefined\n}\n\nfunction subgraphDefinitionSource(definition: unknown):\n  | {\n      id: string\n      name: string\n      nodes: unknown[]\n      source: Record<string, unknown>\n    }\n  | undefined {\n  if (definition === null || typeof definition !== 'object') return\n  const candidate = definition as Record<string, unknown>\n  if (\n    typeof candidate.id !== 'string' ||\n    typeof candidate.name !== 'string' ||\n    !Array.isArray(candidate.nodes) ||\n    !('inputNode' in candidate) ||\n    !('outputNode' in candidate)\n  )\n    return\n  return {\n    id: candidate.id,\n    name: candidate.name,\n    nodes: candidate.nodes,\n    source: candidate\n  }\n}\n\nexport function parseFlattenableSubgraphDefinitions(\n  definitions: readonly unknown[],\n  parseNodes: (\n    nodes: readonly unknown[]\n  ) => readonly FlattenableWorkflowNode[] | undefined = parseWorkflowNodes\n): FlattenableSubgraphDefinition[] {\n  const copies = new Map<object, FlattenableSubgraphDefinition>()\n  const pending: Array<{\n    clone: FlattenableSubgraphDefinition\n    source: Record<string, unknown>\n  }> = []\n\n  function parse(\n    definition: unknown\n  ): FlattenableSubgraphDefinition | undefined {\n    const candidate = subgraphDefinitionSource(definition)\n    if (!candidate) return\n    const existing = copies.get(candidate.source)\n    if (existing) return existing\n    const nodes = parseNodes(candidate.nodes)\n    if (!nodes) return\n    const clone: FlattenableSubgraphDefinition = {\n      id: candidate.id,\n      name: candidate.name,\n      nodes\n    }\n    copies.set(candidate.source, clone)\n    pending.push({ clone, source: candidate.source })\n    return clone\n  }\n\n  const result = definitions.flatMap((definition) => {\n    const parsed = parse(definition)\n    return parsed ? [parsed] : []\n  })\n  for (let entry = pending.pop(); entry; entry = pending.pop()) {\n    const definitions = entry.source.definitions\n    if (\n      definitions !== null &&\n      typeof definitions === 'object' &&\n      'subgraphs' in definitions &&\n      Array.isArray(definitions.subgraphs)\n    )\n      entry.clone.definitions = {\n        subgraphs: definitions.subgraphs.flatMap((definition) => {\n          const parsed = parse(definition)\n          return parsed ? [parsed] : []\n        })\n      }\n  }\n  return result\n}\n\n/**\n * Builds a map from subgraph definition ID to all execution path prefixes\n * where that definition is instantiated in the workflow.\n *\n * \"def-A\" -> [\"5\", \"10\"] for each container node instantiating that subgraph definition.\n */\nexport function buildSubgraphExecutionPaths(\n  rootNodes: readonly FlattenableWorkflowNode[],\n  allSubgraphDefs: readonly FlattenableSubgraphDefinition[]\n): Map<string, string[]> {\n  const subgraphDefMap = new Map(allSubgraphDefs.map((s) => [s.id, s]))\n  const pathMap = new Map<string, string[]>()\n  const visited = new Set<string>()\n\n  function build(\n    nodes: readonly FlattenableWorkflowNode[],\n    parentPrefix: string\n  ) {\n    for (const n of nodes) {\n      if (typeof n.type !== 'string' || !subgraphDefMap.has(n.type)) continue\n      if (visited.has(n.type)) continue\n\n      const path = parentPrefix ? `${parentPrefix}:${n.id}` : String(n.id)\n      const existing = pathMap.get(n.type)\n      if (existing) {\n        existing.push(path)\n      } else {\n        pathMap.set(n.type, [path])\n      }\n\n      visited.add(n.type)\n\n      const innerDef = subgraphDefMap.get(n.type)\n      if (innerDef) {\n        build(innerDef.nodes, path)\n      }\n\n      visited.delete(n.type)\n    }\n  }\n\n  build(rootNodes, '')\n  return pathMap\n}\n\n/**\n * Recursively collect all subgraph definitions from root and nested levels.\n */\nexport function collectSubgraphDefinitions(\n  rootDefs: readonly FlattenableSubgraphDefinition[]\n): FlattenableSubgraphDefinition[] {\n  const result: FlattenableSubgraphDefinition[] = []\n  const seen = new Set<string>()\n  const levels = [rootDefs[Symbol.iterator]()]\n\n  while (levels.length) {\n    const next = levels[levels.length - 1].next()\n    if (next.done) {\n      levels.pop()\n      continue\n    }\n    const def = next.value\n    if (seen.has(def.id)) continue\n    seen.add(def.id)\n    result.push(def)\n\n    const nestedSubgraphs = def.definitions?.subgraphs\n    if (nestedSubgraphs?.length) levels.push(nestedSubgraphs[Symbol.iterator]())\n  }\n\n  return result\n}\n\nexport function collectReachableSubgraphDefinitions(\n  rootNodes: readonly FlattenableWorkflowNode[],\n  allSubgraphDefs: readonly FlattenableSubgraphDefinition[]\n): FlattenableSubgraphDefinition[] {\n  const byId = new Map(\n    collectSubgraphDefinitions(allSubgraphDefs).map((def) => [def.id, def])\n  )\n  const reached = new Map<string, FlattenableSubgraphDefinition>()\n  const pending = [...rootNodes]\n  for (let node = pending.pop(); node; node = pending.pop()) {\n    const def = byId.get(node.type)\n    if (!def || reached.has(def.id)) continue\n    reached.set(def.id, def)\n    pending.push(...def.nodes)\n  }\n  return [...reached.values()]\n}\n\n/**\n * Flatten all workflow nodes (root + subgraphs) into a single array.\n * Each node's `id` is prefixed with its execution path (e.g. node \"3\" inside container \"11\" -> \"11:3\").\n */\nexport function flattenWorkflowNodes(\n  graphData: FlattenableWorkflowGraph\n): Readonly<FlattenableWorkflowNode>[] {\n  const rootNodes = graphData.nodes ?? []\n  const allDefs = collectSubgraphDefinitions(\n    parseFlattenableSubgraphDefinitions(graphData.definitions?.subgraphs ?? [])\n  )\n  const pathMap = buildSubgraphExecutionPaths(rootNodes, allDefs)\n\n  const allNodes: FlattenableWorkflowNode[] = [...rootNodes]\n\n  const subgraphDefMap = new Map(allDefs.map((s) => [s.id, s]))\n  for (const [defId, paths] of pathMap.entries()) {\n    const def = subgraphDefMap.get(defId)\n    if (!def?.nodes) continue\n    for (const prefix of paths) {\n      for (const node of def.nodes) {\n        allNodes.push({\n          ...node,\n          id: `${prefix}:${node.id}`\n        })\n      }\n    }\n  }\n\n  return allNodes\n}\n","import {\n  INSUFFICIENT_CREDITS_CATALOG_ID,\n  SIGN_IN_REQUIRED_CATALOG_ID,\n  SUBSCRIPTION_REQUIRED_CATALOG_ID,\n  SUBSCRIPTION_UPGRADE_REQUIRED_CATALOG_ID,\n  WORKSPACE_INSUFFICIENT_CREDITS_CATALOG_ID\n} from './catalogIds'\nimport type { RuntimeErrorInfo } from './runtimeErrorMatcher'\nimport { resolveRuntimeCatalogMatch } from './runtimeErrorMatcher'\n\n// Account preconditions are gating states (sign-in, subscription, credits) that\n// must open their own modal instead of surfacing as a workflow error. They are\n// excluded from the error panel and the error count.\nexport type AccountPrecondition = 'sign_in' | 'subscription' | 'credits'\n\nconst CATALOG_ID_TO_PRECONDITION = new Map<string, AccountPrecondition>([\n  [SIGN_IN_REQUIRED_CATALOG_ID, 'sign_in'],\n  [SUBSCRIPTION_REQUIRED_CATALOG_ID, 'subscription'],\n  [SUBSCRIPTION_UPGRADE_REQUIRED_CATALOG_ID, 'subscription'],\n  [INSUFFICIENT_CREDITS_CATALOG_ID, 'credits'],\n  [WORKSPACE_INSUFFICIENT_CREDITS_CATALOG_ID, 'credits']\n])\n\nexport function preconditionForCatalogId(\n  catalogId: string | undefined\n): AccountPrecondition | undefined {\n  if (!catalogId) return undefined\n  return CATALOG_ID_TO_PRECONDITION.get(catalogId)\n}\n\nexport function isAccountPreconditionCatalogId(\n  catalogId: string | undefined\n): boolean {\n  return preconditionForCatalogId(catalogId) !== undefined\n}\n\n// Classifies a single runtime error payload into the account precondition it\n// represents, or `undefined` when it is an ordinary workflow error.\nexport function resolveAccountPrecondition(\n  info: RuntimeErrorInfo\n): AccountPrecondition | undefined {\n  const match = resolveRuntimeCatalogMatch(info)\n  return preconditionForCatalogId(match?.catalogId)\n}\n","import type { ResultItem } from '@/platform/remote/comfyui/execution/types'\nimport type { ResultItemType } from '@/schemas/resultItemTypeSchema'\n\nconst IMPLICIT_ASSET_ROOT = 'input'\nconst ANNOTATION_SUFFIX = /\\s*\\[(input|output|temp)\\]\\s*$/i\n\nconst hasAnnotation = (filepath: string): boolean =>\n  ANNOTATION_SUFFIX.test(filepath)\n\nconst createAnnotation = (\n  filepath: string,\n  rootFolder = IMPLICIT_ASSET_ROOT\n): string =>\n  !hasAnnotation(filepath) && rootFolder !== IMPLICIT_ASSET_ROOT\n    ? ` [${rootFolder}]`\n    : ''\n\nconst createPath = (filename: string, subfolder = ''): string =>\n  subfolder ? `${subfolder}/${filename}` : filename\n\ntype AnnotatedPathOptions = {\n  rootFolder?: ResultItemType\n  subfolder?: string\n}\n\nexport function parseAnnotatedPath(\n  filepath: string,\n  fallbackRoot: string = IMPLICIT_ASSET_ROOT\n): { filepath: string; rootFolder: string } {\n  const match = ANNOTATION_SUFFIX.exec(filepath)\n  if (!match) return { filepath, rootFolder: fallbackRoot }\n\n  const annotation = match[1].toLowerCase()\n  return {\n    filepath: filepath.slice(0, match.index),\n    rootFolder:\n      annotation === 'output' || annotation === 'temp'\n        ? annotation\n        : IMPLICIT_ASSET_ROOT\n  }\n}\n\n/** Creates annotated filepath in format used by folder_paths.py */\nexport function createAnnotatedPath(item: ResultItem): string\nexport function createAnnotatedPath(\n  item: string,\n  options?: AnnotatedPathOptions\n): string\nexport function createAnnotatedPath(\n  item: string | ResultItem,\n  options: AnnotatedPathOptions = {}\n): string {\n  const { rootFolder = IMPLICIT_ASSET_ROOT, subfolder } = options\n  if (typeof item === 'string')\n    return `${createPath(item, subfolder)}${createAnnotation(item, rootFolder)}`\n  const filename = item.filename ?? ''\n  return `${createPath(filename, item.subfolder)}${createAnnotation(\n    filename,\n    item.type\n  )}`\n}\n","/**\n * Node Z-Index Management Composable\n *\n * Provides focused functionality for managing node layering through z-index.\n * Integrates with the layout system to ensure proper visual ordering.\n */\nimport type { NodeId } from '@/types/nodeId'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useLayoutMutations } from '@/renderer/core/layout/operations/layoutMutations'\nimport { LayoutSource } from '@/renderer/core/layout/types'\n\nexport function useNodeZIndex() {\n  const layoutMutations = useLayoutMutations(LayoutSource.Vue)\n  const canvasStore = useCanvasStore()\n\n  function bringNodeToFront(nodeId: NodeId) {\n    const { currentGraph } = canvasStore\n    if (!currentGraph) return\n\n    layoutMutations.setNodeOrder(currentGraph, nodeId, 'front')\n  }\n\n  return {\n    bringNodeToFront\n  }\n}\n","import { every, filter, head, isEmpty, isEqual, map } from 'es-toolkit/compat'\n\nimport type { ColorOption, LGraph } from '@/lib/litegraph/src/litegraph'\nimport type { ExecutedWsMessage } from '@/platform/remote/comfyui/execution/types'\nimport {\n  LGraphCanvas,\n  LGraphGroup,\n  LGraphNode,\n  LiteGraph,\n  isColorable\n} from '@/lib/litegraph/src/litegraph'\nimport type {\n  ExportedSubgraph,\n  ISerialisableNodeInput,\n  ISerialisedGraph\n} from '@/lib/litegraph/src/types/serialisation'\nimport type {\n  IBaseWidget,\n  IComboWidget,\n  WidgetCallbackOptions\n} from '@/lib/litegraph/src/types/widgets'\nimport type { InputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport { inputSpecTree } from '@/schemas/nodeDef/inputSpecTree'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useNodeZIndex } from '@/renderer/extensions/vueNodes/composables/useNodeZIndex'\nimport { useApp } from '@/scripts/appInstance'\nimport { t } from '@/i18n'\nimport { parseNodeLocatorId } from '@/types/nodeIdentification'\nimport type { SerializedNodeId } from '@/types/nodeId'\nimport { UNASSIGNED_NODE_ID, parseNodeId } from '@/types/nodeId'\nimport type { WidgetId } from '@/types/widgetId'\nimport { ensureUniqueWidgetNames, widgetId } from '@/types/widgetId'\n\ntype ImageNode = LGraphNode & { imgs: HTMLImageElement[] | undefined }\ntype VideoNode = LGraphNode & {\n  videoContainer: HTMLElement | undefined\n  imgs: HTMLVideoElement[] | undefined\n}\n\n/**\n * Extract & Promisify Litegraph.createNode to allow for positioning\n * @param canvas\n * @param name\n */\nexport async function createNode(\n  canvas: LGraphCanvas,\n  name: string\n): Promise<LGraphNode | null> {\n  if (!name) {\n    return null\n  }\n  if (isSelectOnly(canvas)) {\n    return null\n  }\n\n  const {\n    graph,\n    graph_mouse: [posX, posY]\n  } = canvas\n  const newNode = LiteGraph.createNode(name)\n  await new Promise((r) => setTimeout(r, 0))\n\n  if (newNode && graph) {\n    newNode.pos = [posX, posY]\n    const addedNode = graph.add(newNode) ?? null\n\n    if (addedNode) {\n      useNodeZIndex().bringNodeToFront(addedNode.id)\n      graph.change()\n    }\n    return addedNode\n  } else {\n    useToast().warning(t('assetBrowser.failedToCreateNode'))\n    return null\n  }\n}\n\nexport function isImageNode(node: LGraphNode | undefined): node is ImageNode {\n  if (!node) return false\n  return (\n    node.previewMediaType === 'image' ||\n    (node.previewMediaType !== 'video' && !!node.imgs?.length)\n  )\n}\n\nexport function isVideoNode(node: LGraphNode | undefined): node is VideoNode {\n  if (!node) return false\n  return node.previewMediaType === 'video' || !!node.videoContainer\n}\n\n/**\n * Check if output data indicates animated content (animated webp/png or video).\n */\nexport function isAnimatedOutput(\n  output: Pick<ExecutedWsMessage['output'], 'animated'> | undefined\n): boolean {\n  return !!output?.animated?.find(Boolean)\n}\n\n/**\n * Check if output data indicates video content (animated but not webp/png).\n */\nexport function isVideoOutput(\n  output: ExecutedWsMessage['output'] | undefined\n): boolean {\n  if (!isAnimatedOutput(output)) return false\n\n  const isAnimatedWebp = output?.images?.some((img) =>\n    img.filename?.endsWith('.webp')\n  )\n  const isAnimatedPng = output?.images?.some((img) =>\n    img.filename?.endsWith('.png')\n  )\n  return !isAnimatedWebp && !isAnimatedPng\n}\n\nexport function isAudioNode(node: LGraphNode | undefined): boolean {\n  return !!node && node.previewMediaType === 'audio'\n}\n\nexport function resolveComboValues(widget: IComboWidget): (string | number)[] {\n  const values = widget.options.values\n  if (typeof values === 'function') return values(widget)\n  if (Array.isArray(values)) return values\n  return Object.keys(values)\n}\n\nexport function addToComboValues(\n  widget: Pick<IComboWidget, 'options'>,\n  value: string\n) {\n  const values = widget.options.values\n  if (Array.isArray(values) && !values.includes(value)) {\n    values.push(value)\n  }\n}\n\n/**\n * True while the canvas is a picking surface rather than an editable one: its\n * own `selectOnly` flag is set, or the interaction mode the application\n * injected reads select-only (ADR-CANVAS-INTERACTION-0035).\n *\n * The canvas pointer and key dispatch and the command store read the mode\n * themselves. The document-level paste, drop and history listeners guard with\n * this helper, so a new document-level edit path has to opt in.\n */\nexport const isSelectOnly = (canvas: LGraphCanvas | undefined): boolean =>\n  canvas?.selectOnly === true\n\nexport const isLGraphNode = (item: unknown): item is LGraphNode => {\n  return item instanceof LGraphNode\n}\n\nexport const isLGraphGroup = (item: unknown): item is LGraphGroup => {\n  return item instanceof LGraphGroup\n}\n\n/**\n * Get the color option of all canvas items if they are all the same.\n * @param items - The items to get the color option of.\n * @returns The color option of the item.\n */\nexport const getItemsColorOption = (items: unknown[]): ColorOption | null => {\n  const validItems = filter(items, isColorable)\n  if (isEmpty(validItems)) return null\n\n  const colorOptions = map(validItems, (item) => item.getColorOption())\n\n  return every(colorOptions, (option) => isEqual(option, head(colorOptions)))\n    ? head(colorOptions)!\n    : null\n}\n\nexport function executeWidgetsCallback(\n  nodes: LGraphNode[],\n  callbackName: 'onRemove' | 'beforeQueued' | 'afterQueued',\n  options?: WidgetCallbackOptions\n) {\n  for (const node of nodes) {\n    for (const widget of node.widgets ?? []) {\n      widget[callbackName]?.(options)\n    }\n  }\n}\n\n/**\n * Since frontend version 1.16, forceInput input is no longer treated\n * as widget. So we need to remove the dummy widget value serialized\n * from workflows prior to v1.16.\n * Ref: https://github.com/Comfy-Org/ComfyUI_frontend/pull/3326\n *\n * @param nodeDef the node definition\n * @param widgets the widgets on the node instance (from node definition)\n * @param widgetsValues the widgets values to populate the node during configuration\n * @returns the widgets values without the dummy widget values\n */\nexport function migrateWidgetsValues<TWidgetValue>(\n  inputDefs: Record<string, InputSpec>,\n  widgets: IBaseWidget[],\n  widgetsValues: TWidgetValue[]\n): TWidgetValue[] {\n  if (\n    Object.values(inputDefs).some((input) =>\n      inputSpecTree(input).some((spec) => spec.type === 'COMFY_DYNAMICGROUP_V3')\n    )\n  )\n    return widgetsValues\n\n  const widgetNames = new Set(widgets.map((w) => w.name))\n  const originalWidgetsInputs = Object.values(inputDefs).filter(\n    (input) => widgetNames.has(input.name) || input.forceInput\n  )\n  const skippedWidgetNames = new Set(\n    map(\n      filter(widgets, (widget) => widget.serialize === false),\n      (widget) => widget.name\n    )\n  )\n\n  const widgetIndexHasForceInput = originalWidgetsInputs.flatMap((input) => {\n    if (skippedWidgetNames.has(input.name)) return []\n    return input.control_after_generate\n      ? [!!input.forceInput, false]\n      : [!!input.forceInput]\n  })\n\n  const serializableWidgetCount = filter(\n    widgets,\n    (widget) => widget.serialize !== false\n  ).length\n  if (\n    !widgetIndexHasForceInput.includes(true) &&\n    widgetsValues.length === serializableWidgetCount\n  ) {\n    return widgetsValues\n  }\n\n  const compactedWidgetValues = filter(\n    widgetsValues,\n    (_, index) => widgets[index]?.serialize !== false\n  )\n  const alignedWidgetValues =\n    compactedWidgetValues.length === widgetIndexHasForceInput.length\n      ? compactedWidgetValues\n      : widgetsValues.length === widgetIndexHasForceInput.length\n        ? widgetsValues\n        : undefined\n\n  if (!alignedWidgetValues) return widgetsValues\n\n  return filter(\n    alignedWidgetValues,\n    (_, index) => !widgetIndexHasForceInput[index]\n  )\n}\n\n/**\n * Compress widget input slots by removing all unconnected widget input slots.\n * This should match the serialization format of legacy widget conversion.\n *\n * @param graph - The graph to compress widget input slots for.\n * @throws If an infinite loop is detected.\n */\nexport function compressWidgetInputSlots(graph: ISerialisedGraph) {\n  for (const node of graph.nodes) {\n    node.inputs = node.inputs?.filter(matchesLegacyApi)\n\n    for (const [inputIndex, input] of node.inputs?.entries() ?? []) {\n      if (input.link) {\n        const link = graph.links.find((link) => link[0] === input.link)\n        if (link) {\n          link[4] = inputIndex\n        }\n      }\n    }\n  }\n\n  compressSubgraphWidgetInputSlots(graph.definitions?.subgraphs)\n}\n\nfunction matchesLegacyApi(input: ISerialisableNodeInput) {\n  return !(input.widget && input.link === null && !input.label)\n}\n\n/**\n * Duplication to handle the legacy link arrays in the root workflow.\n * @see compressWidgetInputSlots\n * @param subgraph The subgraph to compress widget input slots for.\n */\nfunction compressSubgraphWidgetInputSlots(\n  subgraphs: ExportedSubgraph[] | undefined,\n  visited = new WeakSet<ExportedSubgraph>()\n) {\n  if (!subgraphs) return\n\n  for (const subgraph of subgraphs) {\n    if (visited.has(subgraph)) throw new Error('Infinite loop detected')\n    visited.add(subgraph)\n\n    if (subgraph.nodes) {\n      for (const node of subgraph.nodes) {\n        node.inputs = node.inputs?.filter(matchesLegacyApi)\n\n        if (!subgraph.links) continue\n\n        for (const [inputIndex, input] of node.inputs?.entries() ?? []) {\n          if (input.link) {\n            const link = subgraph.links.find((link) => link.id === input.link)\n            if (link) link.target_slot = inputIndex\n          }\n        }\n      }\n    }\n\n    compressSubgraphWidgetInputSlots(subgraph.definitions?.subgraphs, visited)\n  }\n}\n\nexport function getLinkTypeColor(typeName: string): string {\n  return LGraphCanvas.link_type_colors[typeName] ?? LiteGraph.LINK_COLOR\n}\n\nexport function resolveNode(\n  nodeId: SerializedNodeId,\n  graph: LGraph | null | undefined = useApp().rootGraph\n): LGraphNode | undefined {\n  const parsedNodeId = parseNodeId(nodeId)\n  if (!graph || !parsedNodeId) return undefined\n  const found = graph.getNodeById(parsedNodeId)\n  if (found) return found\n  for (const sg of graph.subgraphs.values()) {\n    const node = sg.getNodeById(parsedNodeId)\n    if (node) return node\n  }\n  return undefined\n}\nexport function resolveNodeWidget(\n  nodeId: SerializedNodeId,\n  widgetName?: string,\n  graph: LGraph = useApp().rootGraph\n): [LGraphNode, IBaseWidget] | [LGraphNode] | [] {\n  if (widgetName && typeof nodeId === 'string') {\n    const locator = parseNodeLocatorId(nodeId)\n    if (locator?.subgraphUuid) {\n      const host = graph.getNodeById(locator.localNodeId)\n      if (host?.isSubgraphNode()) {\n        const widget = host.widgets.find((w) => w.name === widgetName)\n        return widget ? [host, widget] : []\n      }\n    }\n  }\n\n  const parsedNodeId = parseNodeId(nodeId)\n  if (!parsedNodeId) return []\n\n  const node = graph.getNodeById(parsedNodeId)\n  if (!widgetName) return node ? [node] : []\n  if (node) {\n    const widget = node.widgets?.find((w) => w.name === widgetName)\n    return widget ? [node, widget] : []\n  }\n\n  return []\n}\n\nexport function getWidgetIdForNode(\n  node: LGraphNode,\n  widget: Pick<IBaseWidget, 'name' | 'widgetId'>\n): WidgetId | undefined {\n  if (widget.widgetId) return widget.widgetId\n  const graphId = node.graph?.rootGraph.id\n  const nodeId = parseNodeId(node.id)\n  if (!graphId || !nodeId || nodeId === UNASSIGNED_NODE_ID) return undefined\n  const liveEntry = [...mapLiveWidgetsById(node)].find(\n    ([, candidate]) => candidate === widget\n  )\n  if (liveEntry) return liveEntry[0]\n  return widgetId(graphId, nodeId, widget.name)\n}\n\n/**\n * Maps a node's live widgets to their {@link WidgetId}. Building the map once\n * lets callers resolve widgets by id in O(1) instead of rescanning.\n */\nexport function mapLiveWidgetsById(\n  node: LGraphNode\n): Map<WidgetId, IBaseWidget> {\n  const byId = new Map<WidgetId, IBaseWidget>()\n  const widgets = node.widgets ?? []\n  const distinctWidgets = [...new Set(widgets)]\n  const namesAreUnique = ensureUniqueWidgetNames(distinctWidgets)\n  const graphId = node.graph?.rootGraph.id\n  const nodeId = parseNodeId(node.id)\n  const usedNames = new Set<string>()\n  const reservedNames = new Set(distinctWidgets.map(({ name }) => name))\n  for (const widget of distinctWidgets) {\n    let name = widget.name\n    if (!namesAreUnique && usedNames.has(name)) {\n      let suffix = 1\n      while (\n        usedNames.has(`${name}#${suffix}`) ||\n        reservedNames.has(`${name}#${suffix}`)\n      ) {\n        suffix++\n      }\n      name = `${name}#${suffix}`\n    }\n    usedNames.add(name)\n    const id =\n      widget.widgetId ??\n      (graphId && nodeId && nodeId !== UNASSIGNED_NODE_ID\n        ? widgetId(graphId, nodeId, name)\n        : undefined)\n    if (id) byId.set(id, widget)\n  }\n  return byId\n}\n\nexport function isLoad3dNode(node: LGraphNode) {\n  return (\n    node.type && (node.type === 'Load3D' || node.type === 'Load3DAnimation')\n  )\n}\n","import type {\n  NodeExecutionOutput,\n  ResultItem\n} from '@/platform/remote/comfyui/execution/types'\n\ntype InputPreviewOutput = Pick<NodeExecutionOutput, 'images'> & {\n  images: ResultItem[]\n}\n\nexport function isInputPreviewOutput(\n  output: Pick<NodeExecutionOutput, 'images'> | undefined\n): output is InputPreviewOutput {\n  const images = output?.images\n  return (\n    Array.isArray(images) &&\n    images.length > 0 &&\n    images.every((image) => image.type === 'input')\n  )\n}\n","const objectUrlRefCounts = new Map<string, number>()\n\nconst isBlobUrl = (url: string) => url.startsWith('blob:')\n\nexport function createSharedObjectUrl(blob: Blob): string {\n  const url = URL.createObjectURL(blob)\n  objectUrlRefCounts.set(url, 1)\n  return url\n}\n\nexport function retainSharedObjectUrl(url: string | undefined): void {\n  if (!url || !isBlobUrl(url)) return\n  objectUrlRefCounts.set(url, (objectUrlRefCounts.get(url) ?? 0) + 1)\n}\n\nexport function releaseSharedObjectUrl(url: string | undefined): void {\n  if (!url || !isBlobUrl(url)) return\n\n  const currentCount = objectUrlRefCounts.get(url)\n  if (currentCount === undefined || currentCount <= 1) {\n    objectUrlRefCounts.delete(url)\n    URL.revokeObjectURL(url)\n    return\n  }\n\n  objectUrlRefCounts.set(url, currentCount - 1)\n}\n","import { useTimeoutFn } from '@vueuse/core'\nimport { mapKeys } from 'es-toolkit'\nimport { defineStore } from 'pinia'\nimport { ref } from 'vue'\n\nimport type {\n  LGraph,\n  LGraphNode,\n  SubgraphNode\n} from '@/lib/litegraph/src/litegraph'\nimport { LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport type {\n  ExecutedWsMessage,\n  ResultItem\n} from '@/platform/remote/comfyui/execution/types'\nimport type { ResultItemType } from '@/schemas/resultItemTypeSchema'\nimport { api } from '@/scripts/api'\nimport { useApp } from '@/scripts/appInstance'\nimport { clone } from '@/scripts/utils'\nimport { createNodeLocatorId } from '@/types/nodeIdentification'\nimport type { NodeExecutionId, NodeLocatorId } from '@/types/nodeIdentification'\nimport type { NodeId } from '@/types/nodeId'\nimport { parseAnnotatedPath } from '@/utils/createAnnotatedPath'\nimport { parseFilePath } from '@/utils/formatUtil'\nimport { executionIdToNodeLocatorId } from '@/utils/graphTraversalUtil'\nimport {\n  isAnimatedOutput,\n  isVideoNode,\n  resolveNode\n} from '@/utils/litegraphUtil'\nimport { isInputPreviewOutput } from '@/utils/nodeOutputUtil'\nimport {\n  releaseSharedObjectUrl,\n  retainSharedObjectUrl\n} from '@/utils/objectUrlUtil'\n\nconst PREVIEW_REVOKE_DELAY_MS = 400\n\nconst createOutputs = (\n  filenames: string[],\n  type: ResultItemType,\n  isAnimated: boolean\n): ExecutedWsMessage['output'] => {\n  return {\n    images: filenames.map((image) => ({ type, ...parseFilePath(image) })),\n    animated: filenames.map((image) => {\n      const { filepath } = parseAnnotatedPath(image, type)\n      return (\n        isAnimated && (filepath.endsWith('.webp') || filepath.endsWith('.png'))\n      )\n    })\n  }\n}\n\ninterface SetOutputOptions {\n  merge?: boolean\n}\n\ntype NodePreviewMap = Partial<Record<string, string[]>>\ntype RuntimeOutput = Pick<ExecutedWsMessage['output'], 'animated'> & {\n  images?: (ResultItem | null)[]\n}\n\nexport const useNodeOutputStore = defineStore('nodeOutput', () => {\n  const workflowStore = useWorkflowStore()\n  const { nodeIdToNodeLocatorId, nodeToNodeLocatorId } = workflowStore\n  const scheduledRevoke: Partial<Record<NodeLocatorId, { stop: () => void }>> =\n    {}\n  const latestPreview = ref<string[]>([])\n  /**\n   * Previews belonging to open-but-inactive workflows, keyed by workflow path.\n   * The stash owns the object URL retain taken when the previews were set.\n   */\n  const stashedPreviews = new Map<string, NodePreviewMap>()\n\n  function scheduleRevoke(locator: NodeLocatorId, cb: () => void) {\n    scheduledRevoke[locator]?.stop()\n\n    const { stop } = useTimeoutFn(() => {\n      delete scheduledRevoke[locator]\n      cb()\n    }, PREVIEW_REVOKE_DELAY_MS)\n\n    scheduledRevoke[locator] = { stop }\n  }\n\n  const nodeOutputs = ref<Partial<Record<string, ExecutedWsMessage['output']>>>(\n    {\n      ...useApp().nodeOutputs\n    }\n  )\n  const nodePreviewImages = ref<NodePreviewMap>(\n    Object.fromEntries(\n      Object.entries(useApp().nodePreviewImages).flatMap(([id, urls]) =>\n        urls ? [[id, [...urls]]] : []\n      )\n    )\n  )\n\n  function getNodeOutputs(\n    node: LGraphNode\n  ): ExecutedWsMessage['output'] | undefined {\n    return nodeOutputs.value[nodeToNodeLocatorId(node)]\n  }\n\n  function getNodePreviews(node: LGraphNode): string[] | undefined {\n    return nodePreviewImages.value[nodeToNodeLocatorId(node)]\n  }\n\n  const isImageOutputs = (\n    node: LGraphNode,\n    outputs: RuntimeOutput\n  ): boolean => {\n    if (isAnimatedOutput(outputs) || isVideoNode(node)) return false\n\n    const images = outputs.images?.filter((image) => image !== null)\n    if (!images?.length) return false\n\n    if (images.some((image) => image.filename?.toLowerCase().endsWith('.svg')))\n      return false\n\n    return true\n  }\n\n  function getPreviewParam(\n    node: LGraphNode,\n    outputs: ExecutedWsMessage['output']\n  ): string {\n    return isImageOutputs(node, outputs) ? useApp().getPreviewFormatParam() : ''\n  }\n\n  function buildImageUrls(\n    node: LGraphNode,\n    outputs: ExecutedWsMessage['output'] | undefined\n  ): string[] | undefined {\n    if (!outputs?.images?.length) return\n\n    const rand = useApp().getRandParam()\n    const previewParam = getPreviewParam(node, outputs)\n\n    return outputs.images.map((image) => {\n      const filename = image.filename ?? ''\n      const { filepath, rootFolder } = parseAnnotatedPath(filename, image.type)\n      const params = new URLSearchParams({\n        ...image,\n        filename: node.comfyClass === 'LoadImageOutput' ? filename : filepath,\n        type: rootFolder\n      })\n      return api.apiURL(`/view?${params}${previewParam}${rand}`)\n    })\n  }\n\n  function getNodeImageUrls(node: LGraphNode): string[] | undefined {\n    const previews = getNodePreviews(node)\n    if (previews?.length) return previews\n\n    return buildImageUrls(node, getNodeOutputs(node))\n  }\n\n  function getNodeOutputByExecutionId(\n    executionId: NodeExecutionId\n  ): ExecutedWsMessage['output'] | undefined {\n    const locatorId = executionIdToNodeLocatorId(\n      useApp().rootGraph,\n      executionId\n    )\n    if (!locatorId) return undefined\n    return nodeOutputs.value[locatorId]\n  }\n\n  function getNodePreviewImagesByExecutionId(\n    executionId: NodeExecutionId\n  ): string[] | undefined {\n    const locatorId = executionIdToNodeLocatorId(\n      useApp().rootGraph,\n      executionId\n    )\n    if (!locatorId) return undefined\n    return nodePreviewImages.value[locatorId]\n  }\n\n  function getNodeImageUrlsByExecutionId(\n    executionId: NodeExecutionId,\n    node: LGraphNode\n  ): string[] | undefined {\n    const previews = getNodePreviewImagesByExecutionId(executionId)\n    if (previews?.length) return previews\n\n    return buildImageUrls(node, getNodeOutputByExecutionId(executionId))\n  }\n\n  function setOutputsByLocatorId(\n    nodeLocatorId: NodeLocatorId,\n    outputs: ExecutedWsMessage['output'] | ResultItem | null | undefined,\n    options: SetOutputOptions = {}\n  ) {\n    if (outputs == null) return\n\n    const incomingImages = 'images' in outputs ? outputs.images : undefined\n    const hasIncomingImages =\n      Array.isArray(incomingImages) && incomingImages.length > 0\n    const existingOutput = nodeOutputs.value[nodeLocatorId]\n    if (!hasIncomingImages && isInputPreviewOutput(existingOutput)) {\n      outputs = {\n        ...outputs,\n        images: existingOutput.images\n      }\n    }\n\n    if (options.merge && existingOutput) {\n      const mergedOutput = { ...existingOutput }\n      for (const [key, newValue] of Object.entries(outputs)) {\n        const existingValue = existingOutput[key]\n\n        if (Array.isArray(existingValue) && Array.isArray(newValue)) {\n          mergedOutput[key] = existingValue.concat(newValue)\n        } else {\n          mergedOutput[key] = newValue\n        }\n      }\n      nodeOutputs.value[nodeLocatorId] = mergedOutput\n      useApp().nodeOutputs[nodeLocatorId] = clone(mergedOutput)\n      return\n    }\n\n    nodeOutputs.value[nodeLocatorId] = outputs\n    useApp().nodeOutputs[nodeLocatorId] = clone(outputs)\n  }\n\n  function setNodeOutputs(\n    node: LGraphNode | null | undefined,\n    filenames: string | string[] | ResultItem,\n    {\n      folder = 'input',\n      isAnimated = false\n    }: { folder?: ResultItemType; isAnimated?: boolean } = {}\n  ) {\n    if (!filenames || !node) return\n\n    const locatorId = nodeToNodeLocatorId(node)\n    if (!locatorId) return\n    if (typeof filenames === 'string') {\n      setOutputsByLocatorId(\n        locatorId,\n        createOutputs([filenames], folder, isAnimated)\n      )\n    } else if (!Array.isArray(filenames)) {\n      setOutputsByLocatorId(locatorId, filenames)\n    } else {\n      const resultItems = createOutputs(filenames, folder, isAnimated)\n      if (!resultItems.images?.length) return\n      setOutputsByLocatorId(locatorId, resultItems)\n    }\n  }\n\n  function setNodeOutputImages(\n    node: LGraphNode,\n    images: NonNullable<ExecutedWsMessage['output']['images']>\n  ) {\n    const locatorId = nodeToNodeLocatorId(node)\n    if (!locatorId) return\n\n    setOutputsByLocatorId(locatorId, {\n      ...nodeOutputs.value[locatorId],\n      images\n    })\n    node.images = images\n  }\n\n  /**\n   * Replaces a node's output with exactly these images, dropping any media\n   * metadata the previous output carried. `animated`, `video` and friends are\n   * parallel to the images they were produced with, so an editor that rewrites\n   * the image list wholesale must not inherit them.\n   */\n  function replaceNodeOutputImages(\n    node: LGraphNode,\n    images: NonNullable<ExecutedWsMessage['output']['images']>\n  ) {\n    if (!images.length) return\n\n    const locatorId = nodeToNodeLocatorId(node)\n    if (!locatorId) return\n\n    revokePreviewsByLocatorId(locatorId)\n    setOutputsByLocatorId(locatorId, { images })\n    node.images = images\n  }\n\n  function setNodeOutputsByExecutionId(\n    executionId: NodeExecutionId,\n    outputs: ExecutedWsMessage['output'] | ResultItem,\n    options: SetOutputOptions = {}\n  ) {\n    const nodeLocatorId = executionIdToNodeLocatorId(\n      useApp().rootGraph,\n      executionId\n    )\n    if (!nodeLocatorId) return\n    setOutputsByLocatorId(nodeLocatorId, outputs, options)\n  }\n\n  function setNodePreviewsByExecutionId(\n    executionId: NodeExecutionId,\n    previewImages: string[]\n  ) {\n    const nodeLocatorId = executionIdToNodeLocatorId(\n      useApp().rootGraph,\n      executionId\n    )\n    if (!nodeLocatorId) return\n    setNodePreviewsByLocatorId(nodeLocatorId, previewImages)\n    latestPreview.value = [...previewImages]\n  }\n\n  function setNodePreviewsByLocatorId(\n    nodeLocatorId: NodeLocatorId,\n    previewImages: string[]\n  ) {\n    const existingPreviews = nodePreviewImages.value[nodeLocatorId]\n    scheduledRevoke[nodeLocatorId]?.stop()\n    delete scheduledRevoke[nodeLocatorId]\n    if (existingPreviews) {\n      for (const url of existingPreviews) {\n        releaseSharedObjectUrl(url)\n      }\n    }\n    for (const url of previewImages) {\n      retainSharedObjectUrl(url)\n    }\n    nodePreviewImages.value[nodeLocatorId] = [...previewImages]\n    useApp().nodePreviewImages[nodeLocatorId] = [...previewImages]\n  }\n\n  function setNodePreviewsByNodeId(nodeId: NodeId, previewImages: string[]) {\n    setNodePreviewsByLocatorId(nodeIdToNodeLocatorId(nodeId), previewImages)\n  }\n\n  function revokePreviewsByExecutionId(executionId: NodeExecutionId) {\n    const nodeLocatorId = executionIdToNodeLocatorId(\n      useApp().rootGraph,\n      executionId\n    )\n    if (!nodeLocatorId) return\n    scheduleRevoke(nodeLocatorId, () =>\n      revokePreviewsByLocatorId(nodeLocatorId)\n    )\n  }\n\n  function revokePreviewsByLocatorId(nodeLocatorId: NodeLocatorId) {\n    const previews = nodePreviewImages.value[nodeLocatorId]\n    if (!previews) return\n\n    for (const url of previews) {\n      releaseSharedObjectUrl(url)\n    }\n\n    delete nodePreviewImages.value[nodeLocatorId]\n    delete useApp().nodePreviewImages[nodeLocatorId]\n  }\n\n  function releasePreviewUrls(previews: NodePreviewMap) {\n    for (const urls of Object.values(previews)) {\n      if (!urls) continue\n\n      for (const url of urls) {\n        releaseSharedObjectUrl(url)\n      }\n    }\n  }\n\n  function revokeAllPreviews() {\n    releasePreviewUrls(nodePreviewImages.value)\n    nodePreviewImages.value = {}\n    useApp().nodePreviewImages = {}\n  }\n\n  /** Release the previews held for a workflow that is going away. */\n  function discardPreviewsForWorkflow(workflowPath: string) {\n    const stashed = stashedPreviews.get(workflowPath)\n    if (!stashed) return\n\n    stashedPreviews.delete(workflowPath)\n    releasePreviewUrls(stashed)\n  }\n\n  function discardClosedWorkflowPreviews() {\n    const openPaths = new Set(workflowStore.openWorkflows.map((wf) => wf.path))\n    for (const path of Array.from(stashedPreviews.keys())) {\n      if (!openPaths.has(path)) discardPreviewsForWorkflow(path)\n    }\n  }\n\n  /**\n   * Move the live previews into the stash so `app.clean()` cannot revoke them\n   * while `workflowPath` is loaded out of the editor. Preview frames arrive\n   * over the websocket and cannot be re-fetched, so releasing their object\n   * URLs on a tab switch loses them for good.\n   */\n  function stashPreviewsForWorkflow(workflowPath: string) {\n    discardClosedWorkflowPreviews()\n    discardPreviewsForWorkflow(workflowPath)\n\n    const previews = nodePreviewImages.value\n    if (Object.keys(previews).length) {\n      stashedPreviews.set(workflowPath, previews)\n    }\n    nodePreviewImages.value = {}\n    useApp().nodePreviewImages = {}\n  }\n\n  function restorePreviewsForWorkflow(workflowPath: string | undefined) {\n    if (!workflowPath) return\n\n    const stashed = stashedPreviews.get(workflowPath)\n    if (!stashed) return\n    stashedPreviews.delete(workflowPath)\n\n    const live = nodePreviewImages.value\n    const superseded: Record<string, string[]> = {}\n    for (const [nodeLocatorId, urls] of Object.entries(stashed)) {\n      if (!urls) continue\n\n      // A preview that arrived while the graph was loading wins; the stashed\n      // copy for that node then has no owner left to release it.\n      if (live[nodeLocatorId]) superseded[nodeLocatorId] = urls\n      else live[nodeLocatorId] = urls\n    }\n    releasePreviewUrls(superseded)\n    nodePreviewImages.value = { ...live }\n    useApp().nodePreviewImages = clone(nodePreviewImages.value)\n  }\n\n  function revokeSubgraphPreviews(subgraphNode: SubgraphNode, graph: LGraph) {\n    revokePreviewsByLocatorId(\n      createNodeLocatorId(graph.isRootGraph ? null : graph.id, subgraphNode.id)\n    )\n    for (const node of subgraphNode.subgraph.nodes) {\n      revokePreviewsByLocatorId(\n        createNodeLocatorId(subgraphNode.subgraph.id, node.id)\n      )\n    }\n  }\n\n  function removeOutputsByLocatorId(nodeLocatorId: NodeLocatorId) {\n    const hadOutputs = !!nodeOutputs.value[nodeLocatorId]\n    delete nodeOutputs.value[nodeLocatorId]\n    delete useApp().nodeOutputs[nodeLocatorId]\n\n    const previews = nodePreviewImages.value[nodeLocatorId]\n    if (previews) {\n      for (const url of previews) {\n        releaseSharedObjectUrl(url)\n      }\n      delete nodePreviewImages.value[nodeLocatorId]\n      delete useApp().nodePreviewImages[nodeLocatorId]\n    }\n\n    return hadOutputs\n  }\n\n  function removeNodeOutputs(nodeId: NodeId) {\n    const nodeLocatorId = nodeIdToNodeLocatorId(nodeId)\n    if (!nodeLocatorId) return false\n    return removeOutputsByLocatorId(nodeLocatorId)\n  }\n\n  function removeNodeOutputsForNode(node: LGraphNode) {\n    return removeOutputsByLocatorId(nodeToNodeLocatorId(node))\n  }\n\n  function snapshotOutputs(): Record<string, ExecutedWsMessage['output']> {\n    return Object.fromEntries(\n      Object.entries(nodeOutputs.value).flatMap(([id, output]) =>\n        output ? [[id, clone(output)]] : []\n      )\n    )\n  }\n\n  function replaceOutputsFromLegacy(\n    outputs: Partial<Record<string, ExecutedWsMessage['output']>>\n  ) {\n    const parsedOutputs = mapKeys(\n      outputs,\n      (_, id) => executionIdToNodeLocatorId(useApp().rootGraph, id) ?? id\n    )\n    nodeOutputs.value = { ...parsedOutputs }\n  }\n\n  function setOutputFromLegacy(\n    id: string,\n    output: ExecutedWsMessage['output']\n  ): void {\n    const locatorId = executionIdToNodeLocatorId(useApp().rootGraph, id) ?? id\n    nodeOutputs.value[locatorId] = { ...output }\n  }\n\n  function removeOutputFromLegacy(id: string): void {\n    const locatorId = executionIdToNodeLocatorId(useApp().rootGraph, id) ?? id\n    delete nodeOutputs.value[locatorId]\n  }\n\n  function restoreOutputs(\n    outputs: Partial<Record<string, ExecutedWsMessage['output']>>\n  ) {\n    replaceOutputsFromLegacy(outputs)\n    useApp().nodeOutputs = snapshotOutputs()\n  }\n\n  function refreshNodeOutputs(node: LGraphNode) {\n    const locatorId = nodeToNodeLocatorId(node)\n    if (!locatorId) return\n\n    const outputs = nodeOutputs.value[locatorId]\n    if (!outputs) return\n\n    nodeOutputs.value[locatorId] = { ...outputs }\n  }\n\n  function resetAllOutputsAndPreviews() {\n    nodeOutputs.value = {}\n    useApp().nodeOutputs = {}\n    revokeAllPreviews()\n  }\n\n  function syncLegacyNodeImgs(\n    nodeId: NodeId,\n    element: HTMLImageElement,\n    activeIndex: number = 0\n  ) {\n    if (!LiteGraph.vueNodesMode) return\n\n    const node = resolveNode(nodeId)\n    if (!node) return\n\n    node.imgs = [element]\n    node.imageIndex = activeIndex\n\n    const outputs = getNodeOutputs(node)\n    if (outputs?.images) node.images = outputs.images\n  }\n\n  return {\n    getNodeOutputs,\n    getNodeImageUrls,\n    getNodeImageUrlsByExecutionId,\n    getNodeOutputByExecutionId,\n    getNodePreviewImagesByExecutionId,\n    getNodePreviews,\n    getPreviewParam,\n\n    setNodeOutputs,\n    setNodeOutputImages,\n    replaceNodeOutputImages,\n    setNodeOutputsByExecutionId,\n    setNodePreviewsByExecutionId,\n    setNodePreviewsByLocatorId,\n    setNodePreviewsByNodeId,\n    refreshNodeOutputs,\n    syncLegacyNodeImgs,\n\n    revokePreviewsByExecutionId,\n    revokePreviewsByLocatorId,\n    revokeAllPreviews,\n    revokeSubgraphPreviews,\n    stashPreviewsForWorkflow,\n    restorePreviewsForWorkflow,\n    discardPreviewsForWorkflow,\n    removeNodeOutputs,\n    removeNodeOutputsForNode,\n    snapshotOutputs,\n    replaceOutputsFromLegacy,\n    setOutputFromLegacy,\n    removeOutputFromLegacy,\n    restoreOutputs,\n    resetAllOutputsAndPreviews,\n\n    nodeOutputs,\n    nodePreviewImages,\n    latestPreview\n  }\n})\n","import { defineStore } from 'pinia'\nimport { computed, readonly, ref, watch } from 'vue'\n\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport type { JobId } from '@/platform/remote/comfyui/execution/types'\nimport {\n  releaseSharedObjectUrl,\n  retainSharedObjectUrl\n} from '@/utils/objectUrlUtil'\n\ntype PromptPreviewMap = Record<JobId, string>\ninterface NodePromptPreview {\n  url: string\n  nodeId?: string\n}\n\nexport const useJobPreviewStore = defineStore('jobPreview', () => {\n  const settingStore = useSettingStore()\n  const nodePreviewsByPromptId = ref<Record<JobId, NodePromptPreview>>({})\n\n  const previewMethod = computed(() =>\n    settingStore.get('Comfy.Execution.PreviewMethod')\n  )\n  const isPreviewEnabled = computed(() => previewMethod.value !== 'none')\n\n  const previewsByPromptId = computed(() => {\n    const result: PromptPreviewMap = {}\n    for (const [k, v] of Object.entries(nodePreviewsByPromptId.value)) {\n      result[k] = v.url\n    }\n    return result\n  })\n\n  function setPreviewUrl(\n    promptId: JobId | undefined,\n    url: string,\n    nodeId?: string\n  ) {\n    if (!promptId || !isPreviewEnabled.value) return\n    const current = nodePreviewsByPromptId.value[promptId]\n    if (promptId in nodePreviewsByPromptId.value) {\n      if (current.url === url) return\n      releaseSharedObjectUrl(current.url)\n    }\n    retainSharedObjectUrl(url)\n    nodePreviewsByPromptId.value = {\n      ...nodePreviewsByPromptId.value,\n      [promptId]: { url, nodeId }\n    }\n  }\n\n  function clearPreview(promptId: JobId | undefined) {\n    if (!promptId) return\n    if (!(promptId in nodePreviewsByPromptId.value)) return\n    const current = nodePreviewsByPromptId.value[promptId]\n    releaseSharedObjectUrl(current.url)\n    const next = { ...nodePreviewsByPromptId.value }\n    delete next[promptId]\n    nodePreviewsByPromptId.value = next\n  }\n\n  function clearAllPreviews() {\n    for (const { url } of Object.values(nodePreviewsByPromptId.value)) {\n      releaseSharedObjectUrl(url)\n    }\n    nodePreviewsByPromptId.value = {}\n  }\n\n  watch(isPreviewEnabled, (enabled) => {\n    if (!enabled) clearAllPreviews()\n  })\n\n  return {\n    nodePreviewsByPromptId: readonly(nodePreviewsByPromptId),\n    previewsByPromptId,\n    isPreviewEnabled,\n    setPreviewUrl,\n    clearPreview,\n    clearAllPreviews\n  }\n})\n","export type AppMode =\n  | 'graph'\n  | 'app'\n  | 'builder:inputs'\n  | 'builder:outputs'\n  | 'builder:arrange'\n\nexport type ViewMode = 'graph' | 'app'\n\ntype WorkflowModeSource = {\n  activeMode: AppMode | null\n  initialMode: AppMode | null | undefined\n}\n\nexport function getWorkflowMode(\n  workflow: WorkflowModeSource | null | undefined\n): AppMode {\n  return workflow?.activeMode ?? workflow?.initialMode ?? 'graph'\n}\n\nexport function isAppModeValue(mode: AppMode): boolean {\n  return mode === 'app' || mode === 'builder:arrange'\n}\n","export function createRafBatch(run: () => void) {\n  let rafId: number | null = null\n\n  const schedule = () => {\n    if (rafId != null) return\n    rafId = requestAnimationFrame(() => {\n      rafId = null\n      run()\n    })\n  }\n\n  const cancel = () => {\n    if (rafId != null) {\n      cancelAnimationFrame(rafId)\n      rafId = null\n    }\n  }\n\n  const flush = () => {\n    if (rafId == null) return\n    cancelAnimationFrame(rafId)\n    rafId = null\n    run()\n  }\n\n  const isScheduled = () => rafId != null\n\n  return { schedule, cancel, flush, isScheduled }\n}\n\n/**\n * Last-write-wins RAF coalescer. Buffers the latest value and applies it\n * on the next animation frame, coalescing multiple pushes into a single\n * reactive update.\n *\n * Pass a `label` to emit `performance.mark` events in dev mode so the\n * batching benefit is visible in the browser profiler under that name.\n */\nexport function createRafCoalescer<T>(\n  apply: (value: T) => void,\n  label?: string\n) {\n  let hasPending = false\n  let pendingValue: T | undefined\n  let droppedCount = 0\n\n  const batch = createRafBatch(() => {\n    if (!hasPending) return\n    const value = pendingValue as T\n    if (import.meta.env.DEV && label) {\n      performance.mark(`${label}:apply`, {\n        detail: { dropped: droppedCount }\n      })\n    }\n    droppedCount = 0\n    hasPending = false\n    pendingValue = undefined\n    apply(value)\n  })\n\n  const push = (value: T) => {\n    if (hasPending) droppedCount++\n    pendingValue = value\n    hasPending = true\n    batch.schedule()\n  }\n\n  const cancel = () => {\n    droppedCount = 0\n    hasPending = false\n    pendingValue = undefined\n    batch.cancel()\n  }\n\n  return { push, cancel, isScheduled: batch.isScheduled }\n}\n","import { createEventHook } from '@vueuse/core'\nimport { defineStore } from 'pinia'\nimport { computed, ref, shallowRef, watch } from 'vue'\n\nimport { useAppMode } from '@/composables/useAppMode'\nimport { isCloud } from '@/platform/distribution/types'\nimport { resolveAccountPrecondition } from '@/platform/errorCatalog/accountPreconditionRouting'\nimport { useTelemetry } from '@/platform/telemetry'\nimport type {\n  WorkflowExecutionContext,\n  WorkflowExecutionFailureReason,\n  WorkflowExecutionIntent\n} from '@/platform/telemetry/types'\nimport type { ComfyWorkflow } from '@/platform/workflow/management/stores/workflowStore'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport type {\n  ComfyApiWorkflow,\n  WorkflowId\n} from '@/platform/workflow/validation/schemas/workflowSchema'\nimport type {\n  ExecutedWsMessage,\n  ExecutionCachedWsMessage,\n  ExecutionErrorWsMessage,\n  ExecutionInterruptedWsMessage,\n  ExecutionStartWsMessage,\n  ExecutionSuccessWsMessage,\n  JobId,\n  NodeProgressState,\n  NotificationWsMessage,\n  ProgressStateWsMessage,\n  ProgressWsMessage\n} from '@/platform/remote/comfyui/execution/types'\nimport { api } from '@/scripts/api'\nimport { useApp } from '@/scripts/appInstance'\nimport { useNodeOutputStore } from '@/stores/nodeOutputStore'\nimport { useJobPreviewStore } from '@/stores/jobPreviewStore'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport { tryNormalizeNodeExecutionId } from '@/types/nodeIdentification'\nimport type { NodeLocatorId } from '@/types/nodeIdentification'\nimport type { AppMode } from '@/utils/appMode'\nimport { isAppModeValue } from '@/utils/appMode'\nimport { classifyCloudValidationError } from '@/utils/executionErrorUtil'\nimport { executionIdToNodeLocatorId } from '@/utils/graphTraversalUtil'\nimport { createRafCoalescer } from '@/utils/rafBatch'\n\ntype RuntimeExecutionError = Omit<\n  ExecutionErrorWsMessage,\n  'node_id' | 'traceback'\n> & {\n  node_id?: ExecutionErrorWsMessage['node_id'] | null\n  traceback?: ExecutionErrorWsMessage['traceback'] | null\n}\n\ninterface ExecutionNodeInfo {\n  title?: string | null\n  type?: string | null\n}\n\nexport interface QueuedJob {\n  /**\n   * The nodes that are queued to be executed. The key is the node id and the\n   * value is a boolean indicating if the node has been executed.\n   */\n  nodes: Record<string, boolean>\n  startTime?: number\n  submissionAcceptedAt?: number\n  executionStartedAt?: number\n  outcomeTracked?: boolean\n  workflowContext?: WorkflowExecutionContext\n  workflowExecutionIntent?: WorkflowExecutionIntent\n  /**\n   * The workflow that is queued to be executed\n   */\n  workflow?: ComfyWorkflow\n  /**\n   * Queue-time node metadata keyed by execution ID.\n   * This stays stable even if the user switches workflows or edits the canvas.\n   */\n  nodeLookup?: Record<string, ExecutionNodeInfo>\n  /**\n   * Share attribution snapshotted at queue time. Read this instead of\n   * `workflow.shareId`, which can gain attribution after the job was queued.\n   */\n  shareId?: string\n  /**\n   * View-mode attribution snapshotted at queue time, so mode switches during\n   * the run don't misattribute completion events.\n   */\n  viewMode?: AppMode\n  isAppMode?: boolean\n}\n\nconst defaultWorkflowExecutionIntent: WorkflowExecutionIntent = {\n  trigger_source: 'unknown'\n}\n\nfunction buildExecutionNodeLookup(\n  promptOutput: ComfyApiWorkflow\n): Record<string, ExecutionNodeInfo> {\n  return Object.fromEntries(\n    Object.entries(promptOutput).map(([executionId, node]) => [\n      executionId,\n      {\n        title: node._meta?.title ?? node.class_type,\n        type: node.class_type\n      }\n    ])\n  )\n}\n\n/**\n * Maximum number of job entries retained in {@link nodeProgressStatesByJob}.\n * When exceeded, the oldest entries (by insertion order) are evicted to\n * prevent unbounded memory growth in long-running sessions.\n */\nexport const MAX_PROGRESS_JOBS = 1000\n\nexport type WorkflowExecutionStatus = 'running' | 'completed' | 'failed'\n\ninterface WorkflowStatusUpdate {\n  status: WorkflowExecutionStatus\n  executionStartedAt?: number\n  endTime?: number\n  failureReason?: WorkflowExecutionFailureReason\n  showStatus?: boolean\n}\n\ninterface PendingExecutionError {\n  detail: ExecutionErrorWsMessage\n  endTime: number\n}\n\nexport const WORKFLOW_STATUS_I18N_KEYS: Record<\n  WorkflowExecutionStatus,\n  string\n> = {\n  running: 'g.running',\n  completed: 'g.completed',\n  failed: 'g.failed'\n}\n\nexport const useExecutionStore = defineStore('execution', () => {\n  const workflowStore = useWorkflowStore()\n  const executionErrorStore = useExecutionErrorStore()\n  const { mode, isAppMode } = useAppMode()\n\n  const clientId = ref<string | null>(null)\n  const activeJobId = ref<JobId | null>(null)\n  const queuedJobs = ref<Record<JobId, QueuedJob>>({})\n  const jobReset = createEventHook<QueuedJob>()\n  // This is the progress of all nodes in the currently executing workflow\n  const nodeProgressStates = ref<Record<string, NodeProgressState>>({})\n  const nodeProgressStatesByJob = ref<\n    Record<JobId, Record<string, NodeProgressState>>\n  >({})\n\n  /**\n   * Map of job ID to workflow ID for quick lookup across the app.\n   */\n  const jobIdToWorkflowId = ref<Map<JobId, WorkflowId>>(new Map())\n\n  /**\n   * Map of job ID to workflow file path in the current session.\n   * Only populated for jobs that are queued in this browser tab.\n   */\n  const jobIdToSessionWorkflowPath = shallowRef<Map<JobId, string>>(new Map())\n  const jobIdToWorkflowInstanceId = new Map<JobId, string>()\n\n  const initializingJobIds = ref<Set<JobId>>(new Set())\n\n  const workflowStatus = shallowRef<\n    Map<ComfyWorkflow, WorkflowExecutionStatus>\n  >(new Map())\n\n  const jobIdToWorkflow = new Map<string, ComfyWorkflow>()\n\n  // Buffers statuses arriving before storeJob attaches the workflow.\n  // FIFO-capped to bound growth if a matching storeJob never fires.\n  const pendingWorkflowStatusByJobId = new Map<string, WorkflowStatusUpdate>()\n  const pendingExecutionErrorsByJobId = new Map<string, PendingExecutionError>()\n\n  function bufferPendingWorkflowStatus(\n    jobId: string,\n    update: WorkflowStatusUpdate\n  ) {\n    const existing = pendingWorkflowStatusByJobId.get(jobId)\n    const executionStartedAt =\n      update.executionStartedAt ??\n      queuedJobs.value[jobId]?.executionStartedAt ??\n      existing?.executionStartedAt\n    pendingWorkflowStatusByJobId.delete(jobId)\n    pendingWorkflowStatusByJobId.set(jobId, {\n      ...update,\n      ...(executionStartedAt !== undefined && { executionStartedAt })\n    })\n    while (pendingWorkflowStatusByJobId.size > MAX_PROGRESS_JOBS) {\n      const oldest = pendingWorkflowStatusByJobId.keys().next().value\n      if (oldest === undefined) break\n      pendingWorkflowStatusByJobId.delete(oldest)\n    }\n  }\n\n  function bufferPendingExecutionError(error: PendingExecutionError) {\n    const jobId = error.detail.prompt_id\n    pendingExecutionErrorsByJobId.delete(jobId)\n    pendingExecutionErrorsByJobId.set(jobId, error)\n    while (pendingExecutionErrorsByJobId.size > MAX_PROGRESS_JOBS) {\n      const oldest = pendingExecutionErrorsByJobId.keys().next().value\n      if (oldest === undefined) break\n      pendingExecutionErrorsByJobId.delete(oldest)\n    }\n  }\n\n  function mutateStatus(\n    mutator: (map: Map<ComfyWorkflow, WorkflowExecutionStatus>) => void\n  ) {\n    const next = new Map(workflowStatus.value)\n    mutator(next)\n    workflowStatus.value = next\n  }\n\n  function applyWorkflowStatus(\n    workflow: ComfyWorkflow,\n    status: WorkflowExecutionStatus\n  ) {\n    // A late terminal event can arrive after the tab closed; don't resurrect\n    // an entry (which also pins the workflow ref) for a closed workflow.\n    if (!workflowStore.isOpen(workflow)) return\n    mutateStatus((m) => m.set(workflow, status))\n  }\n\n  function trackExecutionOutcome(\n    jobId: string,\n    { status, endTime, failureReason }: WorkflowStatusUpdate\n  ) {\n    if (status === 'running' || endTime === undefined) return\n    if (!(jobId in queuedJobs.value)) return\n    const queuedJob = queuedJobs.value[jobId]\n    const startTime = queuedJob.startTime\n    const workflowExecutionIntent = queuedJob.workflowExecutionIntent\n    if (\n      queuedJob.outcomeTracked ||\n      startTime === undefined ||\n      workflowExecutionIntent === undefined\n    )\n      return\n\n    queuedJob.outcomeTracked = true\n    const metadata = {\n      startTime,\n      ...workflowExecutionIntent,\n      ...(queuedJob.submissionAcceptedAt !== undefined && {\n        submissionAcceptedAt: queuedJob.submissionAcceptedAt\n      }),\n      ...(queuedJob.executionStartedAt !== undefined && {\n        executionStartedAt: queuedJob.executionStartedAt\n      }),\n      endTime,\n      ...(queuedJob.workflowContext && {\n        workflowContext: queuedJob.workflowContext\n      })\n    }\n    const telemetry = useTelemetry()\n    if (status === 'completed') {\n      telemetry?.trackExecutionOutcome({\n        ...metadata,\n        success: true,\n        failureReason: ''\n      })\n      return\n    }\n    telemetry?.trackExecutionOutcome({\n      ...metadata,\n      success: false,\n      failureReason: failureReason ?? 'execution_failed'\n    })\n  }\n\n  function setWorkflowStatus(jobId: string, update: WorkflowStatusUpdate) {\n    const workflow = jobIdToWorkflow.get(jobId)\n    if (!workflow) {\n      bufferPendingWorkflowStatus(jobId, update)\n      return\n    }\n    if (update.showStatus !== false) {\n      applyWorkflowStatus(workflow, update.status)\n    }\n    trackExecutionOutcome(jobId, update)\n  }\n\n  function clearWorkflowStatus(workflow: ComfyWorkflow) {\n    if (!workflowStatus.value.has(workflow)) return\n    mutateStatus((m) => m.delete(workflow))\n  }\n\n  function getWorkflowStatus(\n    workflow: ComfyWorkflow | undefined | null\n  ): WorkflowExecutionStatus | undefined {\n    if (!workflow) return undefined\n    return workflowStatus.value.get(workflow)\n  }\n\n  // Prune statuses for workflows that have been closed.\n  watch(\n    () => workflowStore.openWorkflows,\n    (openWorkflows) => {\n      if (workflowStatus.value.size === 0) return\n      const openSet = new Set(openWorkflows)\n      const filtered = new Map(\n        [...workflowStatus.value].filter(([w]) => openSet.has(w))\n      )\n      if (filtered.size !== workflowStatus.value.size) {\n        workflowStatus.value = filtered\n      }\n    }\n  )\n\n  /**\n   * Cache for executionIdToNodeLocatorId lookups.\n   * Avoids redundant graph traversals during a single execution run.\n   * Cleared at execution start and end to ensure fresh graph state.\n   */\n  const executionIdToLocatorCache = new Map<string, NodeLocatorId | undefined>()\n\n  function cachedExecutionIdToLocator(\n    executionId: string\n  ): NodeLocatorId | undefined {\n    if (executionIdToLocatorCache.has(executionId)) {\n      return executionIdToLocatorCache.get(executionId)\n    }\n    const locatorId = executionIdToNodeLocatorId(\n      useApp().rootGraph,\n      executionId\n    )\n    executionIdToLocatorCache.set(executionId, locatorId)\n    return locatorId\n  }\n\n  const mergeExecutionProgressStates = (\n    currentState: NodeProgressState | undefined,\n    newState: NodeProgressState\n  ): NodeProgressState => {\n    if (currentState === undefined) {\n      return newState\n    }\n\n    const mergedState = { ...currentState }\n    if (mergedState.state === 'error') {\n      return mergedState\n    } else if (newState.state === 'running') {\n      const newPerc = newState.max > 0 ? newState.value / newState.max : 0.0\n      const oldPerc =\n        mergedState.max > 0 ? mergedState.value / mergedState.max : 0.0\n      if (\n        mergedState.state !== 'running' ||\n        oldPerc === 0.0 ||\n        newPerc < oldPerc\n      ) {\n        mergedState.value = newState.value\n        mergedState.max = newState.max\n      }\n      mergedState.state = 'running'\n    }\n\n    return mergedState\n  }\n\n  const nodeLocationProgressStates = computed<\n    Record<NodeLocatorId, NodeProgressState>\n  >(() => {\n    const result: Record<NodeLocatorId, NodeProgressState> = {}\n\n    const states = nodeProgressStates.value // Apparently doing this inside `Object.entries` causes issues\n    for (const state of Object.values(states)) {\n      const parts = String(state.display_node_id).split(':')\n      for (let i = 0; i < parts.length; i++) {\n        const executionId = parts.slice(0, i + 1).join(':')\n        const locatorId = cachedExecutionIdToLocator(executionId)\n        if (!locatorId) continue\n\n        result[locatorId] = mergeExecutionProgressStates(\n          result[locatorId],\n          state\n        )\n      }\n    }\n\n    return result\n  })\n\n  // Easily access all currently executing node IDs\n  const executingNodeIds = computed<string[]>(() => {\n    return Object.entries(nodeProgressStates.value)\n      .filter(([_, state]) => state.state === 'running')\n      .map(([nodeId, _]) => nodeId)\n  })\n\n  // @deprecated For backward compatibility - stores the primary executing node ID\n  const executingNodeId = computed<string | null>(() => {\n    return executingNodeIds.value[0] ?? null\n  })\n\n  const uniqueExecutingNodeIdStrings = computed(\n    () => new Set(executingNodeIds.value.map(String))\n  )\n\n  // For backward compatibility - returns the primary executing node info\n  const executingNode = computed<ExecutionNodeInfo | null>(() => {\n    if (!executingNodeId.value) return null\n\n    return activeJob.value?.nodeLookup?.[executingNodeId.value] ?? null\n  })\n\n  // This is the progress of the currently executing node (for backward compatibility)\n  const _executingNodeProgress = ref<ProgressWsMessage | null>(null)\n  const executingNodeProgress = computed(() =>\n    _executingNodeProgress.value\n      ? _executingNodeProgress.value.value / _executingNodeProgress.value.max\n      : null\n  )\n\n  const activeJob = computed<QueuedJob | undefined>(\n    () => queuedJobs.value[activeJobId.value ?? '']\n  )\n\n  const totalNodesToExecute = computed<number>(() => {\n    if (!activeJob.value) return 0\n    return Object.values(activeJob.value.nodes).length\n  })\n\n  const isIdle = computed<boolean>(() => !activeJobId.value)\n\n  const nodesExecuted = computed<number>(() => {\n    if (!activeJob.value) return 0\n    return Object.values(activeJob.value.nodes).filter(Boolean).length\n  })\n\n  const executionProgress = computed<number>(() => {\n    if (!activeJob.value) return 0\n    const total = totalNodesToExecute.value\n    const done = nodesExecuted.value\n    return total > 0 ? done / total : 0\n  })\n\n  function bindExecutionEvents() {\n    api.addEventListener('notification', handleNotification)\n    api.addEventListener('execution_start', handleExecutionStart)\n    api.addEventListener('execution_cached', handleExecutionCached)\n    api.addEventListener('execution_interrupted', handleExecutionInterrupted)\n    api.addEventListener('execution_success', handleExecutionSuccess)\n    api.addEventListener('executed', handleExecuted)\n    api.addEventListener('executing', handleExecuting)\n    api.addEventListener('progress', handleProgress)\n    api.addEventListener('progress_state', handleProgressState)\n    api.addEventListener('status', handleStatus)\n    api.addEventListener('execution_error', handleExecutionError)\n  }\n\n  function unbindExecutionEvents() {\n    api.removeEventListener('notification', handleNotification)\n    api.removeEventListener('execution_start', handleExecutionStart)\n    api.removeEventListener('execution_cached', handleExecutionCached)\n    api.removeEventListener('execution_interrupted', handleExecutionInterrupted)\n    api.removeEventListener('execution_success', handleExecutionSuccess)\n    api.removeEventListener('executed', handleExecuted)\n    api.removeEventListener('executing', handleExecuting)\n    api.removeEventListener('progress', handleProgress)\n    api.removeEventListener('progress_state', handleProgressState)\n    api.removeEventListener('status', handleStatus)\n    api.removeEventListener('execution_error', handleExecutionError)\n\n    if (workflowStatus.value.size > 0) workflowStatus.value = new Map()\n    pendingWorkflowStatusByJobId.clear()\n    pendingExecutionErrorsByJobId.clear()\n    jobIdToWorkflow.clear()\n\n    cancelPendingProgressUpdates()\n  }\n\n  function handleExecutionStart(e: CustomEvent<ExecutionStartWsMessage>) {\n    executionIdToLocatorCache.clear()\n    activeJobId.value = e.detail.prompt_id\n    queuedJobs.value[activeJobId.value] ??= { nodes: {} }\n    clearInitializationByJobId(activeJobId.value)\n\n    // Ensure path mapping exists — execution_start can arrive via WebSocket\n    // before the HTTP response from queuePrompt triggers storeJob.\n    if (!jobIdToSessionWorkflowPath.value.has(activeJobId.value)) {\n      const workflow = queuedJobs.value[activeJobId.value]?.workflow\n      if (workflow) {\n        ensureSessionWorkflowPath(\n          activeJobId.value,\n          workflow.path,\n          workflow.instanceId\n        )\n      }\n    }\n    executionErrorStore.clearExecutionStartErrors(\n      runErrorKeyForJob(activeJobId.value)\n    )\n    queuedJobs.value[activeJobId.value].executionStartedAt ??= performance.now()\n    setWorkflowStatus(activeJobId.value, {\n      status: 'running',\n      executionStartedAt: queuedJobs.value[activeJobId.value].executionStartedAt\n    })\n  }\n\n  function handleExecutionCached(e: CustomEvent<ExecutionCachedWsMessage>) {\n    if (!activeJob.value) return\n    for (const n of e.detail.nodes) {\n      activeJob.value.nodes[n] = true\n    }\n  }\n\n  function handleExecutionInterrupted(\n    e: CustomEvent<ExecutionInterruptedWsMessage>\n  ) {\n    const jobId = e.detail.prompt_id\n    pendingExecutionErrorsByJobId.delete(jobId)\n    setWorkflowStatus(jobId, {\n      status: 'failed',\n      endTime: performance.now(),\n      failureReason: 'execution_interrupted',\n      showStatus: false\n    })\n    const workflow = jobIdToWorkflow.get(jobId)\n    if (workflow) clearWorkflowStatus(workflow)\n    if (activeJobId.value) clearInitializationByJobId(activeJobId.value)\n    resetExecutionState(jobId)\n  }\n\n  function handleExecuted(e: CustomEvent<ExecutedWsMessage>) {\n    if (!activeJob.value) return\n    activeJob.value.nodes[e.detail.node] = true\n  }\n\n  function handleExecutionSuccess(e: CustomEvent<ExecutionSuccessWsMessage>) {\n    const jobId = e.detail.prompt_id\n    pendingExecutionErrorsByJobId.delete(jobId)\n    setWorkflowStatus(jobId, {\n      status: 'completed',\n      endTime: performance.now()\n    })\n    const queuedJob = queuedJobs.value[jobId]\n    const telemetry = useTelemetry()\n    if (jobId in queuedJobs.value) {\n      telemetry?.trackExecutionSuccess({\n        jobId\n      })\n      if (queuedJob.shareId) {\n        telemetry?.trackSharedWorkflowRun({\n          job_id: jobId,\n          share_id: queuedJob.shareId,\n          view_mode: queuedJob.viewMode ?? mode.value,\n          is_app_mode: queuedJob.isAppMode ?? isAppMode.value\n        })\n      }\n    }\n    resetExecutionState(jobId)\n  }\n\n  function handleExecuting(e: CustomEvent<string | number | null>): void {\n    progressCoalescer.cancel()\n    if (e.detail == null) progressStateCoalescer.cancel()\n\n    // Clear the current node progress when a new node starts executing\n    _executingNodeProgress.value = null\n\n    if (!activeJob.value) return\n\n    // Update the executing nodes list\n    if (e.detail == null) {\n      activeJobId.value = null\n    }\n  }\n\n  /**\n   * Evicts the oldest entries from {@link nodeProgressStatesByJob} when the\n   * map exceeds {@link MAX_PROGRESS_JOBS}, preventing unbounded memory\n   * growth in long-running sessions.\n   *\n   * Relies on ES2015+ object key insertion order: the first keys returned\n   * by `Object.keys` are the oldest entries.\n   *\n   * @example\n   * ```ts\n   * // Given 105 entries, evicts the 5 oldest:\n   * evictOldProgressJobs()\n   * Object.keys(nodeProgressStatesByJob.value).length // => 100\n   * ```\n   */\n  function evictOldProgressJobs() {\n    const current = nodeProgressStatesByJob.value\n    const keys = Object.keys(current)\n    if (keys.length <= MAX_PROGRESS_JOBS) return\n\n    const pruned: Record<string, Record<string, NodeProgressState>> = {}\n    const keysToKeep = keys.slice(keys.length - MAX_PROGRESS_JOBS)\n    for (const key of keysToKeep) {\n      pruned[key] = current[key]\n    }\n    nodeProgressStatesByJob.value = pruned\n  }\n\n  const progressStateCoalescer = createRafCoalescer<ProgressStateWsMessage>(\n    applyProgressState,\n    'raf:progress_state'\n  )\n\n  function handleProgressState(e: CustomEvent<ProgressStateWsMessage>) {\n    progressStateCoalescer.push(e.detail)\n  }\n\n  function applyProgressState(detail: ProgressStateWsMessage) {\n    const { nodes, prompt_id: jobId } = detail\n\n    // Revoke previews for nodes that are starting to execute\n    const previousForJob =\n      jobId in nodeProgressStatesByJob.value\n        ? nodeProgressStatesByJob.value[jobId]\n        : {}\n    for (const nodeId in nodes) {\n      const nodeState = nodes[nodeId]\n      if (nodeState.state === 'running' && !(nodeId in previousForJob)) {\n        // This node just started executing, revoke its previews\n        // Note that we're doing the *actual* node id instead of the display node id\n        // here intentionally. That way, we don't clear the preview every time a new node\n        // within an expanded graph starts executing.\n        const { revokePreviewsByExecutionId } = useNodeOutputStore()\n        const executionId = tryNormalizeNodeExecutionId(nodeId)\n        if (executionId) revokePreviewsByExecutionId(executionId)\n      }\n    }\n\n    // Update the progress states for all nodes\n    nodeProgressStatesByJob.value = {\n      ...nodeProgressStatesByJob.value,\n      [jobId]: nodes\n    }\n    evictOldProgressJobs()\n    nodeProgressStates.value = nodes\n\n    // If we have progress for the currently executing node, update it for backwards compatibility\n    if (executingNodeId.value) {\n      const nodeState = Object.hasOwn(nodes, executingNodeId.value)\n        ? nodes[executingNodeId.value]\n        : undefined\n      if (!nodeState) return\n      _executingNodeProgress.value = {\n        value: nodeState.value,\n        max: nodeState.max,\n        prompt_id: nodeState.prompt_id,\n        node: nodeState.display_node_id || nodeState.node_id\n      }\n    }\n  }\n\n  const progressCoalescer = createRafCoalescer<ProgressWsMessage>((detail) => {\n    _executingNodeProgress.value = detail\n  }, 'raf:progress')\n\n  function handleProgress(e: CustomEvent<ProgressWsMessage>) {\n    progressCoalescer.push(e.detail)\n  }\n\n  function cancelPendingProgressUpdates() {\n    progressCoalescer.cancel()\n    progressStateCoalescer.cancel()\n  }\n\n  function handleStatus() {\n    if (api.clientId) {\n      clientId.value = api.clientId\n\n      // Once we've received the clientId we no longer need to listen\n      api.removeEventListener('status', handleStatus)\n    }\n  }\n\n  /**\n   * Queue and history polling supply a workflow id but no path, so the open\n   * workflow carrying that root graph provides it. Two open workflows can share\n   * a root graph id — an imported copy of one already on screen — and those runs\n   * belong to different error buckets, so an ambiguous match resolves to\n   * nothing rather than the wrong workflow.\n   */\n  function openWorkflowPathForGraph(graphId: WorkflowId): string | undefined {\n    const matches = workflowStore.openWorkflows.filter(\n      (w) => (w.activeState?.id ?? w.initialState?.id) === graphId\n    )\n    return matches.length === 1 ? matches[0].path : undefined\n  }\n\n  /**\n   * Run-error key of the workflow that produced `jobId`, for filing its errors\n   * against that workflow rather than whichever one is currently on screen.\n   *\n   * `jobIdToWorkflow` only covers jobs queued by this browser session and is\n   * purged the moment a run ends, so `jobIdToWorkflowId` — also populated from\n   * queue and history polling — backs it up for jobs from a previous page load.\n   *\n   * `null` means the job cannot be attributed to one known workflow, so\n   * recording is suppressed rather than assigning it to whichever workflow is\n   * currently visible.\n   */\n  function runErrorKeyForJob(jobId: string): string | null {\n    const workflow = jobIdToWorkflow.get(jobId)\n    const graphId =\n      workflow?.activeState?.id ??\n      workflow?.initialState?.id ??\n      jobIdToWorkflowId.value.get(jobId)\n    if (graphId === undefined) return null\n\n    const path =\n      workflow?.path ??\n      jobIdToSessionWorkflowPath.value.get(jobId) ??\n      openWorkflowPathForGraph(graphId)\n    if (path === undefined) return null\n\n    return executionErrorStore.runErrorKey(graphId, path)\n  }\n\n  function handleExecutionError(e: CustomEvent<ExecutionErrorWsMessage>) {\n    const endTime = performance.now()\n    // Resolved up front: resetExecutionState() drops the job's workflow entry\n    // before the handlers below record anything.\n    const runErrorKey = runErrorKeyForJob(e.detail.prompt_id)\n    if (runErrorKey === null) {\n      bufferPendingExecutionError({ detail: e.detail, endTime })\n      resetExecutionState(e.detail.prompt_id)\n      return\n    }\n\n    processExecutionError(e.detail, runErrorKey, endTime)\n  }\n\n  function processExecutionError(\n    detail: ExecutionErrorWsMessage,\n    runErrorKey: string,\n    endTime: number\n  ) {\n    setWorkflowStatus(detail.prompt_id, {\n      status: 'failed',\n      endTime,\n      failureReason: 'execution_failed',\n      showStatus: false\n    })\n    useTelemetry()?.trackExecutionError({\n      jobId: detail.prompt_id,\n      nodeId: String(detail.node_id),\n      nodeType: detail.node_type,\n      error: detail.exception_message\n    })\n\n    if (isCloud) {\n      // Cloud wraps validation errors (400) in exception_message as embedded JSON.\n      // Pre-flight validation isn't a runtime failure — no badge.\n      if (handleCloudValidationError(detail, runErrorKey)) {\n        executionErrorStore.showExecutionError(detail, runErrorKey)\n        return\n      }\n    }\n\n    // Account preconditions (sign-in, subscription, credits) open their own\n    // modal and must stay out of the error panel and error count.\n    if (handleAccountPreconditionError(detail)) return\n\n    // Service-level errors (e.g. \"Job has stagnated\") have no associated node.\n    if (handleServiceLevelError(detail, runErrorKey)) {\n      executionErrorStore.showExecutionError(detail, runErrorKey)\n      return\n    }\n\n    setWorkflowStatus(detail.prompt_id, {\n      status: 'failed',\n      endTime,\n      failureReason: 'execution_failed'\n    })\n    executionErrorStore.recordExecutionError(detail, runErrorKey)\n    executionErrorStore.showExecutionError(detail, runErrorKey)\n    clearInitializationByJobId(detail.prompt_id)\n    resetExecutionState(detail.prompt_id)\n  }\n\n  function handleAccountPreconditionError(\n    detail: ExecutionErrorWsMessage\n  ): boolean {\n    const precondition = resolveAccountPrecondition({\n      exceptionType: detail.exception_type,\n      exceptionMessage: detail.exception_message\n    })\n    if (!precondition) return false\n\n    const workflow = jobIdToWorkflow.get(detail.prompt_id)\n    if (workflow) clearWorkflowStatus(workflow)\n    clearInitializationByJobId(detail.prompt_id)\n    resetExecutionState(detail.prompt_id)\n    return true\n  }\n\n  function handleServiceLevelError(\n    detail: RuntimeExecutionError,\n    runErrorKey: string | null | undefined\n  ): boolean {\n    const { node_id: nodeId } = detail\n    if (nodeId !== null && nodeId !== undefined && String(nodeId) !== '')\n      return false\n\n    clearInitializationByJobId(detail.prompt_id)\n    resetExecutionState(detail.prompt_id)\n    executionErrorStore.recordPromptError(\n      {\n        type: detail.exception_type || 'error',\n        message: detail.exception_type\n          ? `${detail.exception_type}: ${detail.exception_message}`\n          : detail.exception_message || '',\n        details: detail.traceback?.join('\\n') ?? ''\n      },\n      runErrorKey\n    )\n    return true\n  }\n\n  function handleCloudValidationError(\n    detail: ExecutionErrorWsMessage,\n    runErrorKey: string | null | undefined\n  ): boolean {\n    const result = classifyCloudValidationError(detail.exception_message)\n    if (!result) return false\n\n    clearInitializationByJobId(detail.prompt_id)\n    resetExecutionState(detail.prompt_id)\n\n    if (result.kind === 'nodeErrors') {\n      executionErrorStore.recordNodeErrors(result.nodeErrors, runErrorKey)\n    } else {\n      executionErrorStore.recordPromptError(result.promptError, runErrorKey)\n    }\n    return true\n  }\n\n  /**\n   * Notification handler used for frontend/cloud initialization tracking.\n   * Marks a job as initializing when cloud notifies it is waiting for a machine.\n   */\n  function handleNotification(e: CustomEvent<NotificationWsMessage>) {\n    const payload = e.detail\n    const text = payload.value || ''\n    const id = payload.id ? payload.id : ''\n    if (!id) return\n    // Until cloud implements a proper message\n    if (text.includes('Waiting for a machine')) {\n      const next = new Set(initializingJobIds.value)\n      next.add(id)\n      initializingJobIds.value = next\n    }\n  }\n\n  function clearInitializationByJobId(jobId: JobId | null) {\n    if (!jobId) return\n    if (!initializingJobIds.value.has(jobId)) return\n    const next = new Set(initializingJobIds.value)\n    next.delete(jobId)\n    initializingJobIds.value = next\n  }\n\n  function clearInitializationByJobIds(jobIds: JobId[]) {\n    if (!jobIds.length) return\n    const current = initializingJobIds.value\n    const toRemove = jobIds.filter((id) => current.has(id))\n    if (!toRemove.length) return\n    const next = new Set(current)\n    for (const id of toRemove) {\n      next.delete(id)\n    }\n    initializingJobIds.value = next\n  }\n\n  function reconcileInitializingJobs(activeJobIds: Set<JobId>) {\n    const orphaned = [...initializingJobIds.value].filter(\n      (id) => !activeJobIds.has(id)\n    )\n    clearInitializationByJobIds(orphaned)\n  }\n\n  /**\n   * Clears the active job if the server's queue snapshot doesn't list it.\n   * Used after WS reconnect to recover from stale state when a job finished\n   * during the disconnect window.\n   */\n  function clearActiveJobIfStale(activeJobIds: Set<JobId>) {\n    const id = activeJobId.value\n    if (id && !activeJobIds.has(id)) resetExecutionState(id)\n  }\n\n  function isJobInitializing(jobId: JobId | number | undefined): boolean {\n    if (!jobId) return false\n    return initializingJobIds.value.has(String(jobId))\n  }\n\n  /**\n   * Reset execution-related state after a run completes or is stopped.\n   */\n  function resetExecutionState(jobIdParam?: JobId | null) {\n    cancelPendingProgressUpdates()\n\n    executionIdToLocatorCache.clear()\n    nodeProgressStates.value = {}\n    const jobId = jobIdParam ?? activeJobId.value ?? null\n    const runErrorKey = jobId ? runErrorKeyForJob(jobId) : undefined\n    if (jobId) {\n      const map = { ...nodeProgressStatesByJob.value }\n      delete map[jobId]\n      nodeProgressStatesByJob.value = map\n      useJobPreviewStore().clearPreview(jobId)\n      jobIdToWorkflow.delete(jobId)\n      if (jobId in queuedJobs.value)\n        void jobReset.trigger(queuedJobs.value[jobId])\n    }\n    if (jobId) delete queuedJobs.value[jobId]\n    activeJobId.value = null\n    _executingNodeProgress.value = null\n    executionErrorStore.clearPromptError(runErrorKey)\n  }\n\n  function storeJob({\n    nodes,\n    id,\n    promptOutput,\n    startTime,\n    submissionAcceptedAt,\n    workflow,\n    mode,\n    workflowContext,\n    workflowExecutionIntent = defaultWorkflowExecutionIntent\n  }: {\n    nodes: string[]\n    id: JobId\n    promptOutput: ComfyApiWorkflow\n    startTime?: number\n    submissionAcceptedAt?: number\n    workflow: ComfyWorkflow\n    mode: AppMode\n    workflowContext?: WorkflowExecutionContext\n    workflowExecutionIntent?: WorkflowExecutionIntent\n  }) {\n    queuedJobs.value[id] ??= { nodes: {} }\n    const queuedJob = queuedJobs.value[id]\n    queuedJob.nodes = {\n      ...nodes.reduce((p: Record<string, boolean>, n) => {\n        p[n] = false\n        return p\n      }, {}),\n      ...queuedJob.nodes\n    }\n    queuedJob.nodeLookup = buildExecutionNodeLookup(promptOutput)\n    queuedJob.startTime = startTime\n    queuedJob.submissionAcceptedAt = submissionAcceptedAt\n    queuedJob.workflowContext = workflowContext\n    queuedJob.workflowExecutionIntent = workflowExecutionIntent\n    queuedJob.workflow = workflow\n    jobIdToWorkflow.set(id, workflow)\n    queuedJob.shareId = workflow.shareId\n    queuedJob.viewMode = mode\n    queuedJob.isAppMode = isAppModeValue(mode)\n    const wid = workflow.activeState?.id ?? workflow.initialState?.id\n    if (wid) {\n      jobIdToWorkflowId.value.set(id, wid)\n    }\n    if (workflow.path) {\n      ensureSessionWorkflowPath(id, workflow.path, workflow.instanceId)\n    }\n    flushPendingWorkflowStatus(id, workflow)\n    flushPendingExecutionError(id)\n  }\n\n  function flushPendingExecutionError(jobId: string) {\n    const pending = pendingExecutionErrorsByJobId.get(jobId)\n    if (!pending) return\n\n    const runErrorKey = runErrorKeyForJob(jobId)\n    if (runErrorKey === null) return\n\n    pendingExecutionErrorsByJobId.delete(jobId)\n    processExecutionError(pending.detail, runErrorKey, pending.endTime)\n  }\n\n  function flushPendingWorkflowStatus(\n    jobId: string,\n    workflow: ComfyWorkflow | undefined\n  ) {\n    const pending = pendingWorkflowStatusByJobId.get(jobId)\n    if (pending === undefined || !workflow) return\n    pendingWorkflowStatusByJobId.delete(jobId)\n    queuedJobs.value[jobId].executionStartedAt = pending.executionStartedAt\n    // Don't let a stale 'running' overwrite a terminal status already set.\n    if (pending.status === 'running' && workflowStatus.value.has(workflow))\n      return\n    if (pending.showStatus !== false) {\n      applyWorkflowStatus(workflow, pending.status)\n    }\n    trackExecutionOutcome(jobId, pending)\n    if (pending.status === 'running' || activeJobId.value === jobId) return\n    delete queuedJobs.value[jobId]\n    jobIdToWorkflow.delete(jobId)\n  }\n\n  // ~0.65 MB at capacity (32 char GUID key + 50 char path value)\n  const MAX_SESSION_PATH_ENTRIES = 4000\n\n  function ensureSessionWorkflowPath(\n    jobId: JobId,\n    path: string,\n    workflowInstanceId?: string\n  ) {\n    if (workflowInstanceId) {\n      jobIdToWorkflowInstanceId.set(jobId, workflowInstanceId)\n    }\n    if (jobIdToSessionWorkflowPath.value.get(jobId) === path) return\n    const next = new Map(jobIdToSessionWorkflowPath.value)\n    next.set(jobId, path)\n    while (next.size > MAX_SESSION_PATH_ENTRIES) {\n      const oldest = next.keys().next().value\n      if (oldest !== undefined) {\n        next.delete(oldest)\n        jobIdToWorkflowInstanceId.delete(oldest)\n      } else break\n    }\n    jobIdToSessionWorkflowPath.value = next\n  }\n\n  function rewriteSessionWorkflowPaths(\n    workflowInstanceId: string,\n    newPath: string\n  ) {\n    let next: Map<string, string> | undefined\n    for (const [jobId, path] of jobIdToSessionWorkflowPath.value) {\n      if (path === newPath) continue\n      if (jobIdToWorkflowInstanceId.get(jobId) !== workflowInstanceId) continue\n      next ??= new Map(jobIdToSessionWorkflowPath.value)\n      next.set(jobId, newPath)\n    }\n    if (next) jobIdToSessionWorkflowPath.value = next\n  }\n\n  workflowStore.onWorkflowRenamed((workflow) =>\n    rewriteSessionWorkflowPaths(workflow.instanceId, workflow.path)\n  )\n\n  /**\n   * Register or update a mapping from job ID to workflow ID.\n   */\n  function registerJobWorkflowIdMapping(jobId: JobId, workflowId: WorkflowId) {\n    if (!jobId || !workflowId) return\n    jobIdToWorkflowId.value.set(jobId, workflowId)\n    flushPendingExecutionError(jobId)\n  }\n\n  /**\n   * Convert a NodeLocatorId to an execution context ID\n   * @param locatorId The NodeLocatorId\n   * @returns The execution ID or null if conversion fails\n   */\n  const nodeLocatorIdToExecutionId = (\n    locatorId: NodeLocatorId\n  ): string | null => {\n    const executionId = workflowStore.nodeLocatorIdToNodeExecutionId(locatorId)\n    return executionId\n  }\n\n  const runningJobIds = computed<JobId[]>(() => {\n    const result: JobId[] = []\n    for (const [pid, nodes] of Object.entries(nodeProgressStatesByJob.value)) {\n      if (Object.values(nodes).some((n) => n.state === 'running')) {\n        result.push(pid)\n      }\n    }\n    return result\n  })\n\n  const runningWorkflowCount = computed<number>(\n    () => runningJobIds.value.length\n  )\n\n  const isActiveWorkflowRunning = computed(() => {\n    if (!activeJobId.value) return false\n    const path = workflowStore.activeWorkflow?.path\n    if (!path) return false\n    return jobIdToSessionWorkflowPath.value.get(activeJobId.value) === path\n  })\n\n  return {\n    isIdle,\n    clientId,\n    activeJobId,\n    queuedJobs,\n    executingNodeId,\n    executingNodeIds,\n    activeJob,\n    totalNodesToExecute,\n    nodesExecuted,\n    executionProgress,\n    executingNode,\n    executingNodeProgress,\n    nodeProgressStates,\n    nodeLocationProgressStates,\n    nodeProgressStatesByJob,\n    runningJobIds,\n    runningWorkflowCount,\n    initializingJobIds,\n    isActiveWorkflowRunning,\n    isJobInitializing,\n    clearInitializationByJobId,\n    clearInitializationByJobIds,\n    reconcileInitializingJobs,\n    clearActiveJobIfStale,\n    bindExecutionEvents,\n    unbindExecutionEvents,\n    onJobReset: jobReset.on,\n    storeJob,\n    registerJobWorkflowIdMapping,\n    uniqueExecutingNodeIdStrings,\n    // Raw executing progress data for backward compatibility in ComfyApp.\n    _executingNodeProgress,\n    // NodeLocatorId conversion helpers\n    nodeLocatorIdToExecutionId,\n    jobIdToWorkflowId,\n    jobIdToSessionWorkflowPath,\n    ensureSessionWorkflowPath,\n    getWorkflowStatus,\n    clearWorkflowStatus\n  }\n})\n","import { uniqBy } from 'es-toolkit'\n\nimport type {\n  ComfyWorkflow,\n  PendingWarnings\n} from '@/platform/workflow/management/stores/comfyWorkflow'\nimport type { MissingNodeType } from '@/platform/nodeReplacement/types'\n\nconst emptyToUndefined = <T>(arr: T[] | undefined): T[] | undefined =>\n  arr?.length ? arr : undefined\n\nfunction getMissingNodeKey(node: MissingNodeType): string {\n  if (typeof node === 'string') return `string:${node}`\n  if (node.nodeId != null) return `nodeId:${String(node.nodeId)}`\n  return `type:${node.type}`\n}\n\nexport function dedupeMissingNodeTypes(\n  types: readonly MissingNodeType[]\n): MissingNodeType[] {\n  return uniqBy(types, getMissingNodeKey)\n}\n\nexport function removePendingMissingNodeTypesByType(\n  currentTypes: readonly MissingNodeType[] | undefined,\n  typesToRemove: readonly string[]\n): MissingNodeType[] {\n  const removeSet = new Set(typesToRemove)\n  return dedupeMissingNodeTypes(\n    (currentTypes ?? []).filter((node) => {\n      const nodeType = typeof node === 'string' ? node : node.type\n      return !removeSet.has(nodeType)\n    })\n  )\n}\n\nexport function removePendingMissingNodeTypesByNodeId(\n  currentTypes: readonly MissingNodeType[] | undefined,\n  nodeId: string\n): MissingNodeType[] {\n  return dedupeMissingNodeTypes(\n    (currentTypes ?? []).filter(\n      (node) =>\n        typeof node === 'string' ||\n        node.nodeId == null ||\n        String(node.nodeId) !== nodeId\n    )\n  )\n}\n\nexport function removePendingMissingNodeTypesByExecutionIdPrefix(\n  currentTypes: readonly MissingNodeType[] | undefined,\n  prefix: string\n): MissingNodeType[] {\n  return dedupeMissingNodeTypes(\n    (currentTypes ?? []).filter((node) => {\n      if (typeof node === 'string' || node.nodeId == null) return true\n      return !String(node.nodeId).startsWith(prefix)\n    })\n  )\n}\n\nexport function normalizePendingWarnings(\n  warnings: PendingWarnings | null | undefined\n): PendingWarnings | null {\n  if (!warnings) return null\n\n  const normalized: PendingWarnings = {\n    missingNodeTypes: emptyToUndefined(warnings.missingNodeTypes),\n    missingModelCandidates: emptyToUndefined(warnings.missingModelCandidates),\n    missingMediaCandidates: emptyToUndefined(warnings.missingMediaCandidates)\n  }\n\n  return Object.values(normalized).some(Boolean) ? normalized : null\n}\n\nexport function updatePendingWarnings(\n  workflow: Pick<ComfyWorkflow, 'pendingWarnings'> | null | undefined,\n  updates: Partial<PendingWarnings>\n) {\n  if (!workflow) return\n\n  workflow.pendingWarnings = normalizePendingWarnings({\n    ...workflow.pendingWarnings,\n    ...updates\n  })\n}\n","import type {\n  ClipboardItems,\n  ExportedSubgraph,\n  ISerialisedGraph,\n  SerialisableGraph,\n  SerialisableLLink,\n  SerialisableReroute\n} from '@/lib/litegraph/src/types/serialisation'\n\ntype LegacyWorkflowGraph = Omit<ISerialisedGraph, 'links'> & {\n  links?: ISerialisedGraph['links']\n}\n\nexport function workflowToClipboardItems(\n  workflow: LegacyWorkflowGraph | SerialisableGraph\n): ClipboardItems {\n  const graph = structuredClone(workflow)\n\n  return {\n    nodes: graph.nodes ?? [],\n    groups: (graph.groups ?? []).map((group) => ({\n      ...group,\n      id: group.id\n    })),\n    reroutes: getReroutes(graph),\n    links: getLinks(graph),\n    subgraphs: flattenSubgraphs(graph.definitions?.subgraphs ?? [])\n  }\n}\n\nfunction getLinks(\n  graph: LegacyWorkflowGraph | SerialisableGraph\n): SerialisableLLink[] {\n  if (graph.version !== 0.4) return graph.links ?? []\n\n  const presentation = graph.extra?.linkPresentation\n  const parentIds = new Map<number, number | undefined>(\n    graph.extra?.linkExtensions?.map(({ id: extensionId, parentId }) => [\n      Number(extensionId),\n      parentId\n    ])\n  )\n  return (graph.links ?? []).map(\n    ([id, origin_id, origin_slot, target_id, target_slot, type]) => {\n      const link: SerialisableLLink = {\n        id,\n        origin_id,\n        origin_slot,\n        target_id,\n        target_slot,\n        type,\n        parentId: parentIds.get(id)\n      }\n      const entry = presentation?.[id]\n      if (entry?.hidden === true) link.hidden = true\n      if (typeof entry?.label === 'string') link.label = entry.label\n      return link\n    }\n  )\n}\n\nfunction getReroutes(\n  graph: LegacyWorkflowGraph | SerialisableGraph\n): SerialisableReroute[] {\n  const reroutes =\n    graph.version === 0.4 ? graph.extra?.reroutes : graph.reroutes\n\n  return (reroutes ?? []).map((reroute) => ({\n    ...reroute,\n    linkIds: reroute.linkIds\n  }))\n}\n\nfunction flattenSubgraphs(definitions: ExportedSubgraph[]): ExportedSubgraph[] {\n  const result: ExportedSubgraph[] = []\n  const visited = new Set<string>()\n\n  function visit(subgraph: ExportedSubgraph): void {\n    if (visited.has(subgraph.id)) return\n    visited.add(subgraph.id)\n\n    const nested = subgraph.definitions?.subgraphs ?? []\n    delete subgraph.definitions\n    result.push(subgraph)\n    nested.forEach(visit)\n  }\n\n  definitions.forEach(visit)\n  return result\n}\n","import type { ComfyWorkflowJSON } from '@/platform/workflow/validation/schemas/workflowSchema'\n\nconst testDefaultGraph: ComfyWorkflowJSON = {\n  last_node_id: 9,\n  last_link_id: 9,\n  nodes: [\n    {\n      id: 7,\n      type: 'CLIPTextEncode',\n      pos: [413, 389],\n      size: [425.27801513671875, 180.6060791015625],\n      flags: {},\n      order: 3,\n      mode: 0,\n      inputs: [{ name: 'clip', type: 'CLIP', link: 5 }],\n      outp