\n        secondTabText: 'Send Back',\n        secondTabOffset: 80,\n        secondTabWidth: 65\n      },\n      widgets_values: [1024, 1024, 1]\n    },\n    {\n      id: 69,\n      type: 'ModelSamplingAuraFlow',\n      pos: [220.00001082534345, 110.00000596546897],\n      size: [310, 104],\n      flags: {},\n      order: 6,\n      mode: 0,\n      inputs: [\n        {\n          name: 'model',\n          type: 'MODEL',\n          link: 72\n        }\n      ],\n      outputs: [\n        {\n          name: 'MODEL',\n          type: 'MODEL',\n          slot_index: 0,\n          links: [75]\n        }\n      ],\n      properties: {\n        'Node name for S&R': 'ModelSamplingAuraFlow',\n        cnr_id: 'comfy-core',\n        ver: '0.3.64',\n        enableTabs: false,\n        tabWidth: 65,\n        tabXOffset: 10,\n        hasSecondTab: false,\n        secondTabText: 'Send Back',\n        secondTabOffset: 80,\n        secondTabWidth: 65\n      },\n      widgets_values: [3]\n    },\n    {\n      id: 70,\n      type: 'KSampler',\n      pos: [659.9998200904802, 319.9999392082668],\n      size: [315, 341.3125],\n      flags: {},\n      order: 7,\n      mode: 0,\n      inputs: [\n        {\n          name: 'model',\n          type: 'MODEL',\n          link: 75\n        },\n        {\n          name: 'positive',\n          type: 'CONDITIONING',\n          link: 76\n        },\n        {\n          name: 'negative',\n          type: 'CONDITIONING',\n          link: 82\n        },\n        {\n          name: 'latent_image',\n          type: 'LATENT',\n          link: 78\n        }\n      ],\n      outputs: [\n        {\n          name: 'LATENT',\n          type: 'LATENT',\n          slot_index: 0,\n          links: [73]\n        }\n      ],\n      properties: {\n        'Node name for S&R': 'KSampler',\n        cnr_id: 'comfy-core',\n        ver: '0.3.64',\n        enableTabs: false,\n        tabWidth: 65,\n        tabXOffset: 10,\n        hasSecondTab: false,\n        secondTabText: 'Send Back',\n        secondTabOffset: 80,\n        secondTabWidth: 65\n      },\n      widgets_values: [42, 'fixed', 8, 1, 'res_multistep', 'simple', 1]\n    },\n    {\n      id: 71,\n      type: 'CLIPTextEncode',\n      pos: [170.00001082534345, 520.0000536491848],\n      size: [405.46875, 140],\n      flags: {},\n      order: 5,\n      mode: 0,\n      inputs: [\n        {\n          name: 'clip',\n          type: 'CLIP',\n          link: 81\n        }\n      ],\n      outputs: [\n        {\n          name: 'CONDITIONING',\n          type: 'CONDITIONING',\n          links: [82]\n        }\n      ],\n      properties: {\n        'Node name for S&R': 'CLIPTextEncode',\n        cnr_id: 'comfy-core',\n        ver: '0.3.73',\n        enableTabs: false,\n        tabWidth: 65,\n        tabXOffset: 10,\n        hasSecondTab: false,\n        secondTabText: 'Send Back',\n        secondTabOffset: 80,\n        secondTabWidth: 65\n      },\n      widgets_values: [\n        'low quality, bad anatomy, extra digits, missing digits, extra limbs, missing limbs'\n      ]\n    }\n  ],\n  links: [\n    [72, 66, 0, 69, 0, 'MODEL'],\n    [73, 70, 0, 65, 0, 'LATENT'],\n    [74, 63, 0, 65, 1, 'VAE'],\n    [75, 69, 0, 70, 0, 'MODEL'],\n    [76, 67, 0, 70, 1, 'CONDITIONING'],\n    [78, 68, 0, 70, 3, 'LATENT'],\n    [79, 62, 0, 67, 0, 'CLIP'],\n    [80, 65, 0, 9, 0, 'IMAGE'],\n    [81, 62, 0, 71, 0, 'CLIP'],\n    [82, 71, 0, 70, 2, 'CONDITIONING']\n  ],\n  groups: [],\n  config: {},\n  extra: {\n    ds: {\n      scale: 0.9,\n      offset: [416, 110]\n    }\n  },\n  version: 0.4\n}\n\nexport const defaultGraph: ComfyWorkflowJSON =\n  import.meta.env.VITE_USE_LEGACY_DEFAULT_GRAPH === 'true'\n    ? testDefaultGraph\n    : prodDefaultGraph\n\nexport const defaultGraphJSON = JSON.stringify(defaultGraph)\n\nexport const blankGraph: ComfyWorkflowJSON = {\n  last_node_id: 0,\n  last_link_id: 0,\n  nodes: [],\n  links: [],\n  groups: [],\n  config: {},\n  extra: {},\n  version: 0.4\n}\n","/**\n * Stores all DOM widgets that are used in the canvas.\n */\nimport { defineStore } from 'pinia'\nimport { computed, markRaw, ref } from 'vue'\nimport type { Raw } from 'vue'\n\nimport type { PositionConfig } from '@/types/positionConfig'\nimport type { BaseDOMWidget } from '@/scripts/domWidget'\n\nexport interface DomWidgetState extends PositionConfig {\n  // Raw widget instance\n  widget: Raw<BaseDOMWidget>\n  visible: boolean\n  readonly: boolean\n  zIndex: number\n  /** If the widget belongs to the current graph/subgraph. */\n  active: boolean\n}\n\nexport const useDomWidgetStore = defineStore('domWidget', () => {\n  const widgetStates = ref<Map<string, DomWidgetState>>(new Map())\n\n  const activeWidgetStates = computed(() =>\n    [...widgetStates.value.values()].filter((state) => state.active)\n  )\n  const inactiveWidgetStates = computed(() =>\n    [...widgetStates.value.values()].filter((state) => !state.active)\n  )\n\n  function registerWidget<V extends object | string>(widget: BaseDOMWidget<V>) {\n    widgetStates.value.set(widget.id, {\n      widget: markRaw(widget) as unknown as Raw<BaseDOMWidget>,\n      visible: true,\n      readonly: false,\n      zIndex: 0,\n      pos: [0, 0],\n      size: [0, 0],\n      active: true\n    })\n  }\n\n  function unregisterWidget(widgetId: string) {\n    widgetStates.value.delete(widgetId)\n  }\n\n  function activateWidget(widgetId: string) {\n    const state = widgetStates.value.get(widgetId)\n    if (state) state.active = true\n  }\n\n  function deactivateWidget(widgetId: string) {\n    const state = widgetStates.value.get(widgetId)\n    if (state) state.active = false\n  }\n\n  function setWidget(widget: BaseDOMWidget) {\n    const state = widgetStates.value.get(widget.id)\n    if (!state) return\n    state.active = true\n    state.widget = widget\n  }\n\n  function clear() {\n    widgetStates.value.clear()\n  }\n\n  return {\n    widgetStates,\n    activeWidgetStates,\n    inactiveWidgetStates,\n    registerWidget,\n    unregisterWidget,\n    activateWidget,\n    deactivateWidget,\n    setWidget,\n    clear\n  }\n})\n","import { defineStore } from 'pinia'\nimport { ref, computed, watch } from 'vue'\nimport { useEventListener } from '@vueuse/core'\n\nimport { useAppMode } from '@/composables/useAppMode'\nimport { SubgraphNode } from '@/lib/litegraph/src/subgraph/SubgraphNode'\nimport type {\n  InputWidgetConfig,\n  LinearData,\n  LinearInput\n} from '@/platform/workflow/management/stores/comfyWorkflow'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useSidebarTabStore } from '@/stores/workspace/sidebarTabStore'\nimport { useApp } from '@/scripts/appInstance'\nimport type { ComfyApp } from '@/types/comfy'\nimport { ChangeTracker } from '@/scripts/changeTracker'\nimport { resolveSubgraphInputTarget } from '@/core/graph/subgraph/resolveSubgraphInputTarget'\nimport type { LGraph } from '@/lib/litegraph/src/litegraph'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport {\n  getWidgetIdForNode,\n  resolveNode,\n  resolveNodeWidget\n} from '@/utils/litegraphUtil'\nimport { parseNodeId } from '@/types/nodeId'\nimport type { NodeId } from '@/types/nodeId'\nimport type { WidgetId } from '@/types/widgetId'\nimport { isWidgetId, parseWidgetId } from '@/types/widgetId'\nimport type { ViewMode } from '@/utils/appMode'\n\nfunction findWidgetByEntityId(\n  rootGraph: LGraph,\n  widgetId: WidgetId\n): IBaseWidget | undefined {\n  for (const node of rootGraph.nodes) {\n    const widget = node.widgets?.find(\n      (w) => getWidgetIdForNode(node, w) === widgetId\n    )\n    if (widget) return widget\n  }\n  return undefined\n}\n\nexport function nodeTypeValidForApp(type: string) {\n  return !['Note', 'MarkdownNote'].includes(type)\n}\n\nexport const useAppModeStore = defineStore('appMode', () => {\n  const { getCanvas } = useCanvasStore()\n  const settingStore = useSettingStore()\n  const workflowStore = useWorkflowStore()\n  const { mode, setMode, isAppMode, isBuilderMode, isSelectMode } = useAppMode()\n\n  const showVueNodeSwitchPopup = ref(false)\n\n  const viewMode = computed<ViewMode>(() => (isAppMode.value ? 'app' : 'graph'))\n\n  /**\n   * Frame-lagged mirror of {@link viewMode} driving the view-mode toggle's\n   * segment morph. The two-frame lag lets a toggle that mounts mid-switch\n   * render the previous mode first, then animate in. Kept in the store so it\n   * outlives the graph-mode toggle unmounting as the app toggle replaces it.\n   */\n  const displayViewMode = ref<ViewMode>(viewMode.value)\n  let outerFrame: number | undefined\n  let innerFrame: number | undefined\n  watch(viewMode, (next) => {\n    if (outerFrame !== undefined) cancelAnimationFrame(outerFrame)\n    if (innerFrame !== undefined) cancelAnimationFrame(innerFrame)\n    outerFrame = requestAnimationFrame(() => {\n      innerFrame = requestAnimationFrame(() => {\n        displayViewMode.value = next\n      })\n    })\n  })\n\n  const selectedInputs = ref<LinearInput[]>([])\n  const selectedOutputs = ref<NodeId[]>([])\n  const hasOutputs = computed(() => !!selectedOutputs.value.length)\n  const hasNodes = computed(() => {\n    // Nodes are not reactive, so trigger recomputation when workflow changes\n    void workflowStore.activeWorkflow\n    void mode.value\n    const app = useApp()\n    return app.isGraphReady && app.rootGraph.nodes.length > 0\n  })\n\n  function pruneLinearData(data: Partial<LinearData> | undefined): {\n    inputs: LinearInput[]\n    outputs: NodeId[]\n  } {\n    const rawInputs = data?.inputs ?? []\n    const rawOutputs = data?.outputs ?? []\n    const app = useApp()\n    const rootGraph = app.isGraphReady ? app.rootGraph : undefined\n    if (!rootGraph) {\n      return {\n        inputs: rawInputs,\n        outputs: rawOutputs.flatMap((nodeId) => {\n          const parsedNodeId = parseNodeId(nodeId)\n          return parsedNodeId ? [parsedNodeId] : []\n        })\n      }\n    }\n    return {\n      inputs: rawInputs\n        .map((input) => upgradeAndValidateInput(input, rootGraph))\n        .filter((entry): entry is LinearInput => entry !== null),\n      outputs: rawOutputs.flatMap((nodeId) => {\n        const parsedNodeId = parseNodeId(nodeId)\n        if (!parsedNodeId) return []\n        return ChangeTracker.isLoadingGraph || resolveNode(parsedNodeId)\n          ? [parsedNodeId]\n          : []\n      })\n    }\n  }\n\n  function buildEntry(\n    widgetId: WidgetId,\n    name: string,\n    config: InputWidgetConfig | undefined\n  ): LinearInput {\n    return config === undefined ? [widgetId, name] : [widgetId, name, config]\n  }\n\n  function upgradeAndValidateInput(\n    input: LinearInput,\n    rootGraph: ComfyApp['rootGraph']\n  ): LinearInput | null {\n    const [storedId, widgetName, config] = input\n\n    if (typeof storedId === 'string' && isWidgetId(storedId)) {\n      const widget = findWidgetByEntityId(rootGraph, storedId)\n      if (widget) return buildEntry(storedId, widgetName, config)\n      const { nodeId } = parseWidgetId(storedId)\n      if (rootGraph.getNodeById(nodeId)) {\n        return buildEntry(storedId, widgetName, config)\n      }\n      return null\n    }\n\n    if (typeof storedId === 'string' && storedId.includes(':')) {\n      const [, widget] = resolveNodeWidget(storedId, widgetName)\n      if (!widget?.widgetId) return null\n      return buildEntry(widget.widgetId, widgetName, config)\n    }\n\n    const directNodeId = parseNodeId(storedId)\n    const directNode = directNodeId ? rootGraph.getNodeById(directNodeId) : null\n    const directWidget = directNode?.widgets?.find((w) => w.name === widgetName)\n    if (directNode && directWidget) {\n      const derivedId = getWidgetIdForNode(directNode, directWidget)\n      if (derivedId) return buildEntry(derivedId, widgetName, config)\n    }\n\n    const matches: LinearInput[] = rootGraph.nodes.flatMap((node) => {\n      if (!(node instanceof SubgraphNode)) return []\n      return node.inputs.flatMap((inputSlot): LinearInput[] => {\n        if (!inputSlot.widgetId) return []\n        const target = resolveSubgraphInputTarget(node, inputSlot.name)\n        if (\n          target?.nodeId !== String(storedId) ||\n          target.widgetName !== widgetName\n        ) {\n          return []\n        }\n        return [buildEntry(inputSlot.widgetId, inputSlot.name, config)]\n      })\n    })\n    if (matches.length === 1) return matches[0]\n    if (matches.length > 1) {\n      console.warn(\n        '[appModeStore] dropping ambiguous legacy selectedInput tuple',\n        { storedId, widgetName }\n      )\n      return null\n    }\n\n    console.warn(\n      '[appModeStore] dropping legacy selectedInput tuple — no canonical identity available',\n      { storedId, widgetName }\n    )\n    return null\n  }\n\n  function warnOnUninterpretableAppConfig(\n    data: Partial<LinearData> | undefined,\n    resolvedInputs: LinearInput[],\n    resolvedOutputs: NodeId[]\n  ) {\n    if (ChangeTracker.isLoadingGraph) return\n\n    const app = useApp()\n    if (!app.isGraphReady || !app.rootGraph.nodes.length) return\n\n    const hadConfig = !!(data?.inputs?.length || data?.outputs?.length)\n    if (!hadConfig || resolvedInputs.length || resolvedOutputs.length) return\n\n    console.warn(\n      '[appModeStore] app config could not be interpreted; no inputs or outputs resolved from linearData',\n      {\n        inputs: data.inputs,\n        outputs: data.outputs\n      }\n    )\n  }\n\n  function loadSelections(data: Partial<LinearData> | undefined) {\n    const { inputs, outputs } = pruneLinearData(data)\n    selectedInputs.value = inputs\n    selectedOutputs.value = outputs\n    warnOnUninterpretableAppConfig(data, inputs, outputs)\n  }\n\n  function resetSelectedToWorkflow() {\n    const { activeWorkflow } = workflowStore\n    if (!activeWorkflow) return\n\n    const source =\n      activeWorkflow.changeTracker.activeState.extra?.linearData ??\n      activeWorkflow.initialState.extra?.linearData\n    loadSelections(source)\n  }\n\n  useEventListener(\n    () => {\n      const app = useApp()\n      return app.isGraphReady ? app.rootGraph.events : undefined\n    },\n    'configured',\n    resetSelectedToWorkflow\n  )\n\n  watch(\n    () =>\n      isBuilderMode.value\n        ? { inputs: selectedInputs.value, outputs: selectedOutputs.value }\n        : null,\n    (data) => {\n      if (!data || ChangeTracker.isLoadingGraph) return\n      if (!useApp().isGraphReady) return\n      const graph = useApp().rootGraph\n      const extra = graph.extra\n      extra.linearData = {\n        inputs: [...data.inputs],\n        outputs: [...data.outputs]\n      }\n      workflowStore.activeWorkflow?.changeTracker.captureCanvasState()\n    },\n    { deep: true }\n  )\n\n  let unwatchReadOnly: (() => void) | undefined\n  function enforceReadOnly(inSelect: boolean) {\n    const canvas = getCanvas()\n    canvas.read_only = inSelect\n    unwatchReadOnly?.()\n    if (inSelect)\n      unwatchReadOnly = watch(\n        () => canvas.read_only,\n        () => (canvas.read_only = true)\n      )\n  }\n\n  function autoEnableVueNodes(inSelect: boolean) {\n    if (!inSelect) return\n    if (!settingStore.get('Comfy.VueNodes.Enabled')) {\n      void settingStore.set('Comfy.VueNodes.Enabled', true)\n\n      if (!settingStore.get('Comfy.AppBuilder.VueNodeSwitchDismissed')) {\n        showVueNodeSwitchPopup.value = true\n      }\n    }\n  }\n\n  watch(isSelectMode, (inSelect) => {\n    enforceReadOnly(inSelect)\n    autoEnableVueNodes(inSelect)\n  })\n\n  function enterBuilder() {\n    resetSelectedToWorkflow()\n\n    useSidebarTabStore().activeSidebarTabId = null\n\n    setMode(\n      mode.value === 'app' && hasOutputs.value\n        ? 'builder:arrange'\n        : 'builder:inputs'\n    )\n  }\n\n  function exitBuilder() {\n    resetSelectedToWorkflow()\n    setMode('graph')\n  }\n\n  function removeSelectedInput(widget: IBaseWidget) {\n    const targetEntityId = widget.widgetId\n    if (!targetEntityId) return\n    const index = selectedInputs.value.findIndex(\n      ([id]) => id === targetEntityId\n    )\n    if (index !== -1) selectedInputs.value.splice(index, 1)\n  }\n\n  function updateInputConfig(widget: IBaseWidget, config: InputWidgetConfig) {\n    const targetEntityId = widget.widgetId\n    if (!targetEntityId) return\n    const index = selectedInputs.value.findIndex(\n      ([id]) => id === targetEntityId\n    )\n    if (index === -1) return\n    const [id, type, options] = selectedInputs.value[index]\n    selectedInputs.value.splice(index, 1, [id, type, { ...options, ...config }])\n  }\n\n  return {\n    enterBuilder,\n    exitBuilder,\n    hasNodes,\n    hasOutputs,\n    loadSelections,\n    pruneLinearData,\n    removeSelectedInput,\n    resetSelectedToWorkflow,\n    selectedInputs,\n    selectedOutputs,\n    updateInputConfig,\n    showVueNodeSwitchPopup,\n    viewMode,\n    displayViewMode\n  }\n})\n","import { useSettingStore } from '@/platform/settings/settingStore'\n\nconst MISSING_WARNING_SETTING_IDS = {\n  nodes: 'Comfy.Workflow.ShowMissingNodesWarning',\n  models: 'Comfy.ErrorSystem.ShowMissingModels',\n  media: 'Comfy.Workflow.ShowMissingMediaWarning'\n} as const\n\ntype MissingWarningKind = keyof typeof MISSING_WARNING_SETTING_IDS\n\ntype VisibilitySettingId =\n  | 'Comfy.RightSidePanel.ShowErrorsTab'\n  | (typeof MISSING_WARNING_SETTING_IDS)[MissingWarningKind]\n\n/** A setting that is not registered yet reads as enabled. */\nfunction enabledByDefault(value: boolean | undefined): boolean {\n  return value ?? true\n}\n\nfunction isEnabled(id: VisibilitySettingId): boolean {\n  return enabledByDefault(useSettingStore().get(id))\n}\n\nexport function isIssuesTabEnabled(): boolean {\n  return isEnabled('Comfy.RightSidePanel.ShowErrorsTab')\n}\n\nexport function isMissingWarningVisible(kind: MissingWarningKind): boolean {\n  return isEnabled(MISSING_WARNING_SETTING_IDS[kind])\n}\n","import { defineStore } from 'pinia'\nimport { computed, ref } from 'vue'\n\nimport { st } from '@/i18n'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { isCloud } from '@/platform/distribution/types'\nimport { isMissingWarningVisible } from '@/platform/settings/missingWarningVisibility'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport {\n  dedupeMissingNodeTypes,\n  removePendingMissingNodeTypesByExecutionIdPrefix,\n  removePendingMissingNodeTypesByNodeId,\n  removePendingMissingNodeTypesByType\n} from '@/platform/workflow/core/utils/pendingWarnings'\nimport { useApp } from '@/scripts/appInstance'\nimport type { MissingNodeType } from '@/platform/nodeReplacement/types'\nimport { getAncestorExecutionIds } from '@/types/nodeIdentification'\nimport type { NodeExecutionId } from '@/types/nodeIdentification'\nimport { getExecutionIdByNode } from '@/utils/graphTraversalUtil'\n\ninterface MissingNodesError {\n  message: string\n  nodeTypes: MissingNodeType[]\n}\n\nexport const useMissingNodesErrorStore = defineStore(\n  'missingNodesError',\n  () => {\n    const missingNodesError = ref<MissingNodesError | null>(null)\n\n    /** Error to display; `null` while the missing nodes warning is off. */\n    const visibleMissingNodesError = computed(() =>\n      isMissingWarningVisible('nodes') ? missingNodesError.value : null\n    )\n\n    function setMissingNodeTypes(types: MissingNodeType[]) {\n      if (!types.length) {\n        missingNodesError.value = null\n        return\n      }\n      const uniqueTypes = dedupeMissingNodeTypes(types)\n      missingNodesError.value = {\n        message: isCloud\n          ? st(\n              'rightSidePanel.missingNodePacks.unsupportedTitle',\n              'Unsupported Node Packs'\n            )\n          : st('rightSidePanel.missingNodePacks.title', 'Missing Node Packs'),\n        nodeTypes: uniqueTypes\n      }\n    }\n\n    /** Set missing node types. Returns true if the Errors tab and the missing nodes warning are enabled and types were set. */\n    function surfaceMissingNodes(types: MissingNodeType[]): boolean {\n      setMissingNodeTypes(types)\n      return (\n        hasMissingNodes.value &&\n        useSettingStore().get('Comfy.RightSidePanel.ShowErrorsTab')\n      )\n    }\n\n    function removeMissingNodesByNodeId(nodeId: string) {\n      if (!missingNodesError.value) return\n      const remaining = removePendingMissingNodeTypesByNodeId(\n        missingNodesError.value.nodeTypes,\n        nodeId\n      )\n      setMissingNodeTypes(remaining)\n    }\n\n    /**\n     * Remove all object-type entries whose nodeId starts with `prefix`.\n     * String entries (group nodes) have no nodeId and are preserved.\n     *\n     * Intended for clearing all interior errors when a subgraph container\n     * is removed. Callers are expected to pass `${execId}:` (with trailing\n     * colon) so that sibling IDs sharing a numeric prefix are not matched.\n     */\n    function removeMissingNodesByPrefix(prefix: string) {\n      if (!missingNodesError.value) return\n      const remaining = removePendingMissingNodeTypesByExecutionIdPrefix(\n        missingNodesError.value.nodeTypes,\n        prefix\n      )\n      setMissingNodeTypes(remaining)\n    }\n\n    /** Remove specific node types from the missing nodes list (e.g. after replacement). */\n    function removeMissingNodesByType(typesToRemove: string[]) {\n      if (!missingNodesError.value) return\n      const remaining = removePendingMissingNodeTypesByType(\n        missingNodesError.value.nodeTypes,\n        typesToRemove\n      )\n      setMissingNodeTypes(remaining)\n    }\n\n    const hasMissingNodes = computed(() => !!visibleMissingNodesError.value)\n\n    const missingNodeCount = computed(\n      () => visibleMissingNodesError.value?.nodeTypes.length ?? 0\n    )\n\n    /**\n     * Set of all execution ID prefixes derived from missing node execution IDs,\n     * including the missing nodes themselves.\n     *\n     * Example: missing node at \"65:70:63\" → Set { \"65\", \"65:70\", \"65:70:63\" }\n     */\n    const missingAncestorExecutionIds = computed<Set<NodeExecutionId>>(() => {\n      const ids = new Set<NodeExecutionId>()\n      const error = visibleMissingNodesError.value\n      if (!error) return ids\n\n      for (const nodeType of error.nodeTypes) {\n        if (typeof nodeType === 'string') continue\n        if (nodeType.nodeId == null) continue\n        for (const id of getAncestorExecutionIds(String(nodeType.nodeId))) {\n          ids.add(id)\n        }\n      }\n\n      return ids\n    })\n\n    /** True if the node has a missing node inside it at any nesting depth. */\n    function isContainerWithMissingNode(node: LGraphNode): boolean {\n      if (!useApp().isGraphReady) return false\n      const execId = getExecutionIdByNode(useApp().rootGraph, node)\n      if (!execId) return false\n      return missingAncestorExecutionIds.value.has(execId)\n    }\n\n    return {\n      missingNodesError,\n      visibleMissingNodesError,\n      setMissingNodeTypes,\n      surfaceMissingNodes,\n      removeMissingNodesByNodeId,\n      removeMissingNodesByPrefix,\n      removeMissingNodesByType,\n      hasMissingNodes,\n      missingNodeCount,\n      missingAncestorExecutionIds,\n      isContainerWithMissingNode\n    }\n  }\n)\n","import type { ComfyTemplateInputDownloadProgress } from '@comfyorg/comfyui-desktop-bridge-types'\nimport { defineStore } from 'pinia'\nimport { computed, shallowReactive } from 'vue'\n\ninterface TrackedTemplateInputDownload {\n  downloadId: string\n  filename: string\n  progress: number | null\n  status: 'pending' | 'downloading' | 'paused' | 'completed'\n}\n\nfunction normalizeProgress(progress: number): number | null {\n  return Number.isFinite(progress) && progress >= 0 && progress <= 1\n    ? progress\n    : null\n}\n\nexport const useTemplateInputDownloadStore = defineStore(\n  'templateInputDownload',\n  () => {\n    const downloadsById = shallowReactive(\n      new Map<string, TrackedTemplateInputDownload>()\n    )\n    const previewRevisions = shallowReactive(new Map<string, number>())\n    const completedIds = new Set<string>()\n\n    const downloads = computed(() => [...downloadsById.values()])\n    const blockingFilenames = computed(\n      () => new Set(downloads.value.map(({ filename }) => filename))\n    )\n\n    function updateProgress(progress: ComfyTemplateInputDownloadProgress) {\n      const { downloadId, filename, status } = progress\n      if (status === 'error' || status === 'cancelled') {\n        downloadsById.delete(downloadId)\n        return\n      }\n\n      // A finished id never goes back to pending or downloading. A late event\n      // would re-add a record `completeGraphSync` can no longer clear, leaving\n      // the filename blocked for good.\n      if (completedIds.has(downloadId)) return\n\n      if (status === 'completed') {\n        completedIds.add(downloadId)\n        previewRevisions.set(\n          filename,\n          (previewRevisions.get(filename) ?? 0) + 1\n        )\n      }\n\n      downloadsById.set(downloadId, {\n        downloadId,\n        filename,\n        progress: normalizeProgress(progress.progress),\n        status\n      })\n    }\n\n    function completeGraphSync(filenames: readonly string[]) {\n      const completed = new Set(filenames)\n      for (const [downloadId, download] of downloadsById) {\n        if (\n          download.status === 'completed' &&\n          completed.has(download.filename)\n        ) {\n          downloadsById.delete(downloadId)\n        }\n      }\n    }\n\n    function previewRevision(filename: string): number {\n      return previewRevisions.get(filename) ?? 0\n    }\n\n    function clear() {\n      downloadsById.clear()\n      previewRevisions.clear()\n      completedIds.clear()\n    }\n\n    return {\n      downloads,\n      blockingFilenames,\n      updateProgress,\n      completeGraphSync,\n      previewRevision,\n      clear\n    }\n  }\n)\n","import { defineStore } from 'pinia'\nimport { computed, ref } from 'vue'\n\n// oxlint-disable-next-line comfy/no-restricted-paths\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useApp } from '@/scripts/appInstance'\nimport type { MissingMediaCandidate } from '@/platform/missingMedia/types'\nimport { isMissingWarningVisible } from '@/platform/settings/missingWarningVisibility'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useTemplateInputDownloadStore } from '@/stores/templateInputDownloadStore'\nimport { getAncestorExecutionIds } from '@/types/nodeIdentification'\nimport type { NodeExecutionId, NodeLocatorId } from '@/types/nodeIdentification'\nimport { getActiveGraphNodeIds } from '@/utils/graphTraversalUtil'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\n\n/**\n * Missing media error state.\n * Separated from executionErrorStore to keep domain boundaries clean.\n * The executionErrorStore composes from this store for aggregate error flags.\n */\nexport const useMissingMediaStore = defineStore('missingMedia', () => {\n  const canvasStore = useCanvasStore()\n  const templateInputDownloadStore = useTemplateInputDownloadStore()\n\n  const missingMediaCandidates = ref<MissingMediaCandidate[] | null>(null)\n\n  /** Candidates to display; `null` while the missing media warning is off. */\n  const visibleMissingMediaCandidates = computed(() =>\n    isMissingWarningVisible('media') ? missingMediaCandidates.value : null\n  )\n\n  /** Visible candidates the user can still act on, excluding in-flight template input downloads. */\n  const actionableMissingMediaCandidates = computed(() =>\n    (visibleMissingMediaCandidates.value ?? []).filter(\n      ({ name }) => !templateInputDownloadStore.blockingFilenames.has(name)\n    )\n  )\n\n  const hasMissingMedia = computed(\n    () => actionableMissingMediaCandidates.value.length > 0\n  )\n\n  const missingMediaCount = computed(\n    () => actionableMissingMediaCandidates.value.length\n  )\n\n  const missingMediaNodeIds = computed(\n    () =>\n      new Set(\n        actionableMissingMediaCandidates.value.map((m) => String(m.nodeId))\n      )\n  )\n\n  /** `nodeId::widgetName` keys, so per-widget render lookups stay O(1). */\n  const missingMediaWidgetKeys = computed<Set<string>>(() => {\n    const keys = new Set<string>()\n    for (const candidate of actionableMissingMediaCandidates.value) {\n      keys.add(`${String(candidate.nodeId)}::${candidate.widgetName}`)\n    }\n    return keys\n  })\n\n  /**\n   * Set of all execution ID prefixes derived from missing media node IDs,\n   * including the missing media nodes themselves.\n   */\n  const missingMediaAncestorExecutionIds = computed<Set<NodeExecutionId>>(\n    () => {\n      const ids = new Set<NodeExecutionId>()\n      for (const nodeId of missingMediaNodeIds.value) {\n        for (const id of getAncestorExecutionIds(nodeId)) {\n          ids.add(id)\n        }\n      }\n      return ids\n    }\n  )\n\n  const activeMissingMediaGraphIds = computed<Set<string>>(() => {\n    const rootGraph = useApp().rootGraphOrUndefined\n    if (!rootGraph) return new Set()\n    return getActiveGraphNodeIds(\n      rootGraph,\n      canvasStore.currentGraph ?? rootGraph,\n      missingMediaAncestorExecutionIds.value\n    )\n  })\n\n  let _verificationAbortController: AbortController | null = null\n\n  function createVerificationAbortController(): AbortController {\n    _verificationAbortController?.abort()\n    _verificationAbortController = new AbortController()\n    return _verificationAbortController\n  }\n\n  function setMissingMedia(media: MissingMediaCandidate[]) {\n    missingMediaCandidates.value = media.length ? media : null\n  }\n\n  function hasMissingMediaOnNode(nodeLocatorId: NodeLocatorId): boolean {\n    const executionId =\n      useWorkflowStore().nodeLocatorIdToNodeExecutionId(nodeLocatorId)\n    return executionId ? missingMediaNodeIds.value.has(executionId) : false\n  }\n\n  function isContainerWithMissingMedia(node: LGraphNode): boolean {\n    return activeMissingMediaGraphIds.value.has(String(node.id))\n  }\n\n  function isWidgetMissingMedia(\n    nodeId: NodeExecutionId,\n    widgetName: string\n  ): boolean {\n    return missingMediaWidgetKeys.value.has(`${String(nodeId)}::${widgetName}`)\n  }\n\n  function removeMissingMediaByWidget(nodeId: string, widgetName: string) {\n    if (!missingMediaCandidates.value) return\n    missingMediaCandidates.value = missingMediaCandidates.value.filter(\n      (m) => !(String(m.nodeId) === nodeId && m.widgetName === widgetName)\n    )\n    if (!missingMediaCandidates.value.length)\n      missingMediaCandidates.value = null\n  }\n\n  function removeMissingMediaByNodeId(nodeId: string) {\n    if (!missingMediaCandidates.value) return\n    missingMediaCandidates.value = missingMediaCandidates.value.filter(\n      (m) => String(m.nodeId) !== nodeId\n    )\n    if (!missingMediaCandidates.value.length)\n      missingMediaCandidates.value = null\n  }\n\n  /**\n   * Remove all candidates whose nodeId starts with `prefix`.\n   *\n   * Intended for clearing all interior errors when a subgraph container is\n   * removed. Callers are expected to pass `${execId}:` (with trailing\n   * colon) so that sibling IDs sharing a numeric prefix (e.g. `\"705\"` vs\n   * `\"70\"`) are not matched.\n   */\n  function removeMissingMediaByPrefix(prefix: string) {\n    if (!missingMediaCandidates.value) return\n    const remaining: MissingMediaCandidate[] = []\n    for (const m of missingMediaCandidates.value) {\n      // Preserve candidates without a nodeId; they cannot belong to any\n      // subgraph scope. The type marks nodeId as required, but defensive\n      // handling matches the rest of the missing-media code.\n      const nodeId: unknown = m.nodeId\n      if (nodeId == null) {\n        remaining.push(m)\n        continue\n      }\n      if (!String(nodeId).startsWith(prefix)) {\n        remaining.push(m)\n      }\n    }\n    if (remaining.length === missingMediaCandidates.value.length) return\n    missingMediaCandidates.value = remaining.length ? remaining : null\n  }\n\n  function addMissingMedia(media: MissingMediaCandidate[]) {\n    if (!media.length) return\n    const existing = missingMediaCandidates.value ?? []\n    const existingKeys = new Set(\n      existing.map((m) => `${String(m.nodeId)}::${m.widgetName}::${m.name}`)\n    )\n    const newMedia = media.filter(\n      (m) =>\n        !existingKeys.has(`${String(m.nodeId)}::${m.widgetName}::${m.name}`)\n    )\n    if (!newMedia.length) return\n    missingMediaCandidates.value = [...existing, ...newMedia]\n  }\n\n  function clearMissingMedia() {\n    _verificationAbortController?.abort()\n    _verificationAbortController = null\n    missingMediaCandidates.value = null\n  }\n\n  return {\n    missingMediaCandidates,\n    visibleMissingMediaCandidates,\n    hasMissingMedia,\n    missingMediaCount,\n    missingMediaNodeIds,\n    missingMediaAncestorExecutionIds,\n    activeMissingMediaGraphIds,\n\n    hasMissingMediaOnNode,\n    setMissingMedia,\n    addMissingMedia,\n    removeMissingMediaByWidget,\n    removeMissingMediaByNodeId,\n    removeMissingMediaByPrefix,\n    clearMissingMedia,\n    createVerificationAbortController,\n\n    isContainerWithMissingMedia,\n    isWidgetMissingMedia\n  }\n})\n","import { z } from 'zod'\n\nimport { RenderShape } from '@/lib/litegraph/src/types/globalEnums'\n\nconst nodeSlotSchema = z.object({\n  CLIP: z.string(),\n  CLIP_VISION: z.string(),\n  CLIP_VISION_OUTPUT: z.string(),\n  CONDITIONING: z.string(),\n  CONTROL_NET: z.string(),\n  IMAGE: z.string(),\n  LATENT: z.string(),\n  MASK: z.string(),\n  MODEL: z.string(),\n  STYLE_MODEL: z.string(),\n  VAE: z.string(),\n  NOISE: z.string(),\n  GUIDER: z.string(),\n  SAMPLER: z.string(),\n  SIGMAS: z.string(),\n  TAESD: z.string()\n})\n\nconst litegraphBaseSchema = z.object({\n  BACKGROUND_IMAGE: z.string(),\n  CLEAR_BACKGROUND_COLOR: z.string(),\n  NODE_TITLE_COLOR: z.string(),\n  NODE_SELECTED_TITLE_COLOR: z.string(),\n  NODE_TEXT_COLOR: z.string(),\n  NODE_TEXT_HIGHLIGHT_COLOR: z.string(),\n  NODE_DEFAULT_COLOR: z.string(),\n  NODE_DEFAULT_BGCOLOR: z.string(),\n  NODE_DEFAULT_BOXCOLOR: z.string(),\n  NODE_DEFAULT_SHAPE: z.union([\n    z.literal(RenderShape.BOX),\n    z.literal(RenderShape.ROUND),\n    z.literal(RenderShape.CARD),\n    // Legacy palettes have string field for NODE_DEFAULT_SHAPE.\n    z.string()\n  ]),\n  NODE_BOX_OUTLINE_COLOR: z.string(),\n  NODE_BYPASS_BGCOLOR: z.string(),\n  NODE_ERROR_COLOUR: z.string(),\n  DEFAULT_SHADOW_COLOR: z.string(),\n  WIDGET_BGCOLOR: z.string(),\n  WIDGET_OUTLINE_COLOR: z.string(),\n  WIDGET_TEXT_COLOR: z.string(),\n  WIDGET_SECONDARY_TEXT_COLOR: z.string(),\n  WIDGET_DISABLED_TEXT_COLOR: z.string(),\n  LINK_COLOR: z.string(),\n  EVENT_LINK_COLOR: z.string(),\n  CONNECTING_LINK_COLOR: z.string(),\n  BADGE_FG_COLOR: z.string(),\n  BADGE_BG_COLOR: z.string()\n})\n\nexport const comfyBaseSchema = z.object({\n  ['fg-color']: z.string(),\n  ['bg-color']: z.string(),\n  ['bg-img']: z.string().optional(),\n  ['comfy-menu-bg']: z.string(),\n  ['comfy-menu-secondary-bg']: z.string(),\n  ['comfy-input-bg']: z.string(),\n  ['input-text']: z.string(),\n  ['descrip-text']: z.string(),\n  ['drag-text']: z.string(),\n  ['error-text']: z.string(),\n  ['border-color']: z.string(),\n  ['tr-even-bg-color']: z.string(),\n  ['tr-odd-bg-color']: z.string(),\n  ['content-bg']: z.string(),\n  ['content-fg']: z.string(),\n  ['content-hover-bg']: z.string(),\n  ['content-hover-fg']: z.string(),\n  ['bar-shadow']: z.string(),\n  ['contrast-mix-color']: z.string().optional(),\n  ['interface-stroke']: z.string().optional(),\n  ['interface-panel-surface']: z.string().optional(),\n  ['interface-panel-box-shadow']: z.string().optional(),\n  ['interface-panel-drop-shadow']: z.string().optional(),\n  ['interface-floating-panel-shadow']: z.string().optional(),\n  ['interface-panel-hover-surface']: z.string().optional(),\n  ['interface-panel-selected-surface']: z.string().optional(),\n  ['interface-button-hover-surface']: z.string().optional()\n})\n\nconst colorsSchema = z.object({\n  node_slot: nodeSlotSchema,\n  litegraph_base: litegraphBaseSchema,\n  comfy_base: comfyBaseSchema\n})\n\nconst partialColorsSchema = z.object({\n  node_slot: nodeSlotSchema.partial(),\n  litegraph_base: litegraphBaseSchema.partial(),\n  comfy_base: comfyBaseSchema.partial()\n})\n\n// Palette in the wild can have custom metadata fields such as 'version'.\nexport const paletteSchema = z\n  .object({\n    id: z.string(),\n    name: z.string(),\n    colors: partialColorsSchema,\n    light_theme: z.boolean().optional()\n  })\n  .passthrough()\n\nconst completedPaletteSchema = z\n  .object({\n    id: z.string(),\n    name: z.string(),\n    colors: colorsSchema\n  })\n  .passthrough()\n\nexport type Colors = z.infer<typeof colorsSchema>\nexport type Palette = z.infer<typeof paletteSchema>\nexport type CompletedPalette = z.infer<typeof completedPaletteSchema>\nexport type ColorPalettes = Record<string, Palette>\n","import { toRaw } from 'vue'\nimport { z } from 'zod'\nimport { fromZodError } from 'zod-validation-error'\n\nimport { downloadBlob } from '@/base/common/downloadUtil'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { LGraphCanvas, LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { paletteSchema, comfyBaseSchema } from '@/schemas/colorPaletteSchema'\nimport type { Colors, Palette } from '@/schemas/colorPaletteSchema'\nimport { useApp } from '@/scripts/appInstance'\nimport { uploadFile } from '@/scripts/utils'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { useColorPaletteStore } from '@/stores/workspace/colorPaletteStore'\n\nconst THEME_PROPERTY_MAP = {\n  NODE_BOX_OUTLINE_COLOR: 'component-node-border',\n  NODE_DEFAULT_BGCOLOR: 'component-node-background',\n  NODE_DEFAULT_BOXCOLOR: 'node-component-header-icon',\n  NODE_DEFAULT_COLOR: 'node-component-header-surface',\n  NODE_TITLE_COLOR: 'node-component-header',\n  WIDGET_BGCOLOR: 'component-node-widget-background',\n  WIDGET_TEXT_COLOR: 'component-node-foreground'\n} as const satisfies Partial<Record<keyof Colors['litegraph_base'], string>>\n\nexport const useColorPaletteService = () => {\n  const colorPaletteStore = useColorPaletteStore()\n  const settingStore = useSettingStore()\n  const nodeDefStore = useNodeDefStore()\n  const {\n    toastErrorHandler,\n    wrapWithErrorHandling,\n    wrapWithErrorHandlingAsync\n  } = useErrorHandling()\n\n  /**\n   * Validates the palette against the zod schema.\n   *\n   * @param data - The palette to validate.\n   * @returns The validated palette.\n   */\n  const validateColorPalette = (data: unknown): Palette => {\n    const result = paletteSchema.safeParse(data)\n    if (result.success) return result.data\n\n    throw fromZodError(result.error)\n  }\n\n  const persistCustomColorPalettes = async () => {\n    await settingStore.set(\n      'Comfy.CustomColorPalettes',\n      colorPaletteStore.customPalettes\n    )\n  }\n\n  /**\n   * Deletes a custom color palette.\n   *\n   * @param colorPaletteId - The ID of the color palette to delete.\n   */\n  const deleteCustomColorPalette = async (colorPaletteId: string) => {\n    colorPaletteStore.deleteCustomPalette(colorPaletteId)\n    await persistCustomColorPalettes()\n  }\n\n  /**\n   * Adds a custom color palette.\n   *\n   * @param colorPalette - The palette to add.\n   */\n  const addCustomColorPalette = async (colorPalette: Palette) => {\n    validateColorPalette(colorPalette)\n    colorPaletteStore.addCustomPalette(colorPalette)\n    await persistCustomColorPalettes()\n  }\n\n  /**\n   * Sets the colors of node slots and links.\n   *\n   * @param linkColorPalette - The palette to set.\n   */\n  const loadLinkColorPalette = (linkColorPalette: Colors['node_slot']) => {\n    const types = Object.fromEntries(\n      Array.from(nodeDefStore.nodeDataTypes).map((type) => [type, ''])\n    )\n    Object.assign(\n      useApp().canvas.default_connection_color_byType,\n      types,\n      linkColorPalette\n    )\n    Object.assign(LGraphCanvas.link_type_colors, types, linkColorPalette)\n  }\n\n  function validThemeProp(\n    propertyMaybe: unknown\n  ): propertyMaybe is keyof typeof THEME_PROPERTY_MAP {\n    return (\n      (propertyMaybe as keyof typeof THEME_PROPERTY_MAP) in THEME_PROPERTY_MAP\n    )\n  }\n\n  function loadLinkColorPaletteForVueNodes(\n    linkColorPalette: Colors['node_slot']\n  ) {\n    const rootStyle = document.documentElement.style\n\n    for (const dataType of nodeDefStore.nodeDataTypes) {\n      const cssVar = `color-datatype-${dataType}`\n\n      const valueMaybe = linkColorPalette[dataType as keyof Colors['node_slot']]\n      if (valueMaybe) {\n        rootStyle.setProperty(`--${cssVar}`, valueMaybe)\n      } else {\n        rootStyle.removeProperty(`--${cssVar}`)\n      }\n    }\n  }\n\n  function loadLitegraphForVueNodes(\n    palette: Colors['litegraph_base'],\n    colorPaletteId: string\n  ) {\n    const rootStyle = document.documentElement.style\n\n    for (const themeVar of Object.keys(THEME_PROPERTY_MAP)) {\n      if (!validThemeProp(themeVar)) {\n        continue\n      }\n      const cssVar = THEME_PROPERTY_MAP[themeVar]\n      if (colorPaletteId === 'dark' || colorPaletteId === 'light') {\n        rootStyle.removeProperty(`--${cssVar}`)\n        continue\n      }\n      const valueMaybe = palette[themeVar]\n      if (valueMaybe) {\n        rootStyle.setProperty(`--${cssVar}`, valueMaybe)\n      } else {\n        rootStyle.removeProperty(`--${cssVar}`)\n      }\n    }\n  }\n\n  /**\n   * Loads the LiteGraph color palette.\n   *\n   * @param liteGraphColorPalette - The palette to set.\n   */\n  const loadLiteGraphColorPalette = (palette: Colors['litegraph_base']) => {\n    // Sets the colors of the LiteGraph objects\n    useApp().canvas.node_title_color = palette.NODE_TITLE_COLOR\n    useApp().canvas.default_link_color = palette.LINK_COLOR\n    const backgroundImage = settingStore.get('Comfy.Canvas.BackgroundImage')\n    if (backgroundImage) {\n      useApp().canvas.clear_background_color = 'transparent'\n    } else {\n      useApp().canvas.background_image = palette.BACKGROUND_IMAGE\n      useApp().canvas.clear_background_color = palette.CLEAR_BACKGROUND_COLOR\n    }\n    useApp().canvas._pattern = undefined\n\n    if (typeof palette.NODE_DEFAULT_SHAPE === 'string')\n      console.warn(\n        `litegraph_base.NODE_DEFAULT_SHAPE only accepts [${[\n          LiteGraph.BOX_SHAPE,\n          LiteGraph.ROUND_SHAPE,\n          LiteGraph.CARD_SHAPE\n        ].join(', ')}] but got ${palette.NODE_DEFAULT_SHAPE}`\n      )\n\n    const default_shape =\n      typeof palette.NODE_DEFAULT_SHAPE === 'string'\n        ? LiteGraph.ROUND_SHAPE\n        : palette.NODE_DEFAULT_SHAPE\n    const sanitizedPalette: Partial<typeof LiteGraph> = {\n      ...palette,\n      NODE_DEFAULT_SHAPE: default_shape\n    }\n\n    Object.assign(LiteGraph, sanitizedPalette)\n  }\n\n  /**\n   * Gets optional keys from a Zod schema object.\n   *\n   * @param schema - The Zod schema object to analyze.\n   * @returns Array of optional key names.\n   */\n  const getOptionalKeys = (schema: z.ZodObject<z.ZodRawShape>) => {\n    const optionalKeys: string[] = []\n    const shape = schema.shape\n\n    for (const [key, value] of Object.entries(shape)) {\n      if (value instanceof z.ZodOptional || value instanceof z.ZodDefault) {\n        optionalKeys.push(key)\n      }\n    }\n\n    return optionalKeys\n  }\n  const optionalComfyBaseKeys = getOptionalKeys(comfyBaseSchema)\n\n  /**\n   * Loads the Comfy color palette.\n   *\n   * @param comfyColorPalette - The palette to set.\n   */\n  const loadComfyColorPalette = (\n    comfyColorPalette: Colors['comfy_base'],\n    isLightTheme: boolean\n  ) => {\n    const rootStyle = document.documentElement.style\n    for (const [key, value] of Object.entries(comfyColorPalette)) {\n      rootStyle.setProperty('--' + key, value)\n    }\n\n    for (const optionalKey of optionalComfyBaseKeys) {\n      if (!(optionalKey in comfyColorPalette)) {\n        rootStyle.setProperty(\n          '--' + optionalKey,\n          `var(--palette-${optionalKey})`\n        )\n      }\n    }\n\n    const backgroundImage = settingStore.get('Comfy.Canvas.BackgroundImage')\n    if (backgroundImage) {\n      rootStyle.setProperty('--bg-img', `url('${backgroundImage}')`)\n    } else {\n      rootStyle.removeProperty('--bg-img')\n    }\n\n    try {\n      const splashBg = isLightTheme ? '#FFFFFF' : comfyColorPalette['bg-color']\n      localStorage.setItem('comfy-splash-bg', splashBg)\n      localStorage.setItem('comfy-splash-fg', comfyColorPalette['fg-color'])\n    } catch (_) {\n      /* empty */\n    }\n  }\n\n  /**\n   * Loads the color palette.\n   *\n   * @param colorPaletteId - The ID of the color palette to load.\n   */\n  const loadColorPalette = async (colorPaletteId: string) => {\n    const colorPalette = colorPaletteStore.palettesLookup[colorPaletteId]\n    if (!colorPalette) {\n      toastErrorHandler(new Error(`Color palette ${colorPaletteId} not found`))\n      return\n    }\n\n    const completedPalette = colorPaletteStore.completePalette(colorPalette)\n    loadLinkColorPalette(completedPalette.colors.node_slot)\n    loadLiteGraphColorPalette(completedPalette.colors.litegraph_base)\n    loadLitegraphForVueNodes(\n      completedPalette.colors.litegraph_base,\n      colorPaletteId\n    )\n    loadLinkColorPaletteForVueNodes(completedPalette.colors.node_slot)\n    loadComfyColorPalette(\n      completedPalette.colors.comfy_base,\n      completedPalette.light_theme === true\n    )\n    useApp().canvas.setDirty(true, true)\n\n    colorPaletteStore.activePaletteId = colorPaletteId\n  }\n\n  /**\n   * Exports a color palette.\n   *\n   * @param colorPaletteId - The ID of the color palette to export.\n   */\n  const exportColorPalette = (colorPaletteId: string) => {\n    const colorPalette = colorPaletteStore.palettesLookup[colorPaletteId]\n    if (!colorPalette) {\n      toastErrorHandler(new Error(`Color palette ${colorPaletteId} not found`))\n      return\n    }\n    downloadBlob(\n      colorPalette.id + '.json',\n      new Blob([JSON.stringify(toRaw(colorPalette), null, 2)], {\n        type: 'application/json'\n      })\n    )\n  }\n\n  /**\n   * Imports a color palette.\n   *\n   * @returns The imported palette.\n   */\n  const importColorPalette = async () => {\n    const file = await uploadFile('application/json')\n    const text = await file.text()\n    const palette = JSON.parse(text)\n    await addCustomColorPalette(palette)\n    return palette\n  }\n\n  return {\n    getActiveColorPalette: () => colorPaletteStore.completedActivePalette,\n    addCustomColorPalette: wrapWithErrorHandlingAsync(addCustomColorPalette),\n    deleteCustomColorPalette: wrapWithErrorHandlingAsync(\n      deleteCustomColorPalette\n    ),\n    loadColorPalette: wrapWithErrorHandlingAsync(loadColorPalette),\n    exportColorPalette: wrapWithErrorHandling(exportColorPalette),\n    importColorPalette: wrapWithErrorHandlingAsync(importColorPalette)\n  }\n}\n","import { defineStore } from 'pinia'\nimport { computed, ref } from 'vue'\n\nimport { useCommandStore } from '@/stores/commandStore'\nimport type { ComfyExtension } from '@/types/comfy'\nimport type { BottomPanelExtension } from '@/types/extensionTypes'\n\ntype PanelType = 'terminal' | 'shortcuts'\n\ninterface PanelState {\n  tabs: BottomPanelExtension[]\n  activeTabId: string\n  visible: boolean\n}\n\nexport const useBottomPanelStore = defineStore('bottomPanel', () => {\n  // Multi-panel state\n  const panels = ref<Record<PanelType, PanelState>>({\n    terminal: { tabs: [], activeTabId: '', visible: false },\n    shortcuts: { tabs: [], activeTabId: '', visible: false }\n  })\n\n  const activePanel = ref<PanelType | null>(null)\n\n  // Computed properties for active panel\n  const activePanelState = computed(() =>\n    activePanel.value ? panels.value[activePanel.value] : null\n  )\n\n  const activeBottomPanelTab = computed<BottomPanelExtension | null>(() => {\n    const state = activePanelState.value\n    if (!state) return null\n    return state.tabs.find((tab) => tab.id === state.activeTabId) ?? null\n  })\n\n  const bottomPanelVisible = computed({\n    get: () => !!activePanel.value,\n    set: (visible: boolean) => {\n      if (!visible) {\n        activePanel.value = null\n      }\n    }\n  })\n  const bottomPanelTabs = computed(() => activePanelState.value?.tabs ?? [])\n  const activeBottomPanelTabId = computed({\n    get: () => activePanelState.value?.activeTabId ?? '',\n    set: (tabId: string) => {\n      const state = activePanelState.value\n      if (state) {\n        state.activeTabId = tabId\n      }\n    }\n  })\n\n  const togglePanel = (panelType: PanelType) => {\n    const panel = panels.value[panelType]\n    if (panel.tabs.length === 0) return\n\n    if (activePanel.value === panelType) {\n      // Hide current panel\n      activePanel.value = null\n    } else {\n      // Show target panel\n      activePanel.value = panelType\n      if (!panel.activeTabId && panel.tabs.length > 0) {\n        panel.activeTabId = panel.tabs[0].id\n      }\n    }\n  }\n\n  const toggleBottomPanel = () => {\n    // Toggles the terminal panel if available, otherwise falls back to shortcuts\n    // Terminal tabs are loaded asynchronously, so may not be available immediately\n    const terminalPanel = panels.value.terminal\n    if (terminalPanel.tabs.length > 0) {\n      togglePanel('terminal')\n    } else {\n      // Terminal tabs not loaded yet - fall back to shortcuts panel\n      // If no panel is open, open shortcuts\n      // If shortcuts is already open, close it\n      // If another panel is open (shouldn't happen), switch to shortcuts\n      togglePanel('shortcuts')\n    }\n  }\n\n  const setActiveTab = (tabId: string) => {\n    const state = activePanelState.value\n    if (state) {\n      state.activeTabId = tabId\n    }\n  }\n\n  const toggleBottomPanelTab = (tabId: string) => {\n    // Find which panel contains this tab\n    for (const [panelType, panel] of Object.entries(panels.value)) {\n      const tab = panel.tabs.find((t) => t.id === tabId)\n      if (tab) {\n        if (activePanel.value === panelType && panel.activeTabId === tabId) {\n          activePanel.value = null\n        } else {\n          activePanel.value = panelType as PanelType\n          panel.activeTabId = tabId\n        }\n        return\n      }\n    }\n  }\n  const registerBottomPanelTab = (tab: BottomPanelExtension) => {\n    const targetPanel = tab.targetPanel ?? 'terminal'\n    const panel = panels.value[targetPanel]\n\n    panel.tabs = [...panel.tabs, tab]\n    if (panel.tabs.length === 1) {\n      panel.activeTabId = tab.id\n    }\n\n    const tabName = tab.title || tab.titleKey || tab.id\n    useCommandStore().registerCommand({\n      id: `Workspace.ToggleBottomPanelTab.${tab.id}`,\n      icon: 'pi pi-list',\n      label: `Toggle ${tabName} Bottom Panel`,\n      category: 'view-controls' as const,\n      function: () => toggleBottomPanelTab(tab.id),\n      source: 'System'\n    })\n  }\n\n  const registerExtensionBottomPanelTabs = (extension: ComfyExtension) => {\n    if (extension.bottomPanelTabs) {\n      extension.bottomPanelTabs.forEach(registerBottomPanelTab)\n    }\n  }\n\n  return {\n    // Multi-panel API\n    panels,\n    activePanel,\n    togglePanel,\n\n    bottomPanelVisible,\n    toggleBottomPanel,\n    bottomPanelTabs,\n    activeBottomPanelTab,\n    activeBottomPanelTabId,\n    setActiveTab,\n    toggleBottomPanelTab,\n    registerBottomPanelTab,\n    registerExtensionBottomPanelTabs\n  }\n})\n","import { useMagicKeys } from '@vueuse/core'\nimport { defineStore } from 'pinia'\nimport { computed, ref } from 'vue'\n\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport type { Settings } from '@/platform/settings/types'\nimport { useColorPaletteService } from '@/services/colorPaletteService'\nimport { useExtensionDialogService } from '@/services/dialogService'\nimport type {\n  SidebarTabExtension,\n  ToastManager,\n  ToastMessageOptions\n} from '@/types/extensionTypes'\nimport { renderMarkdownToHtml } from '@/utils/markdownRendererUtil'\n\nimport { useApiKeyAuthStore } from './apiKeyAuthStore'\nimport { useCommandStore } from './commandStore'\nimport { useExecutionErrorStore } from './executionErrorStore'\nimport { useAuthStore } from './authStore'\nimport { useQueueSettingsStore } from './queueSettingsStore'\nimport { useBottomPanelStore } from './workspace/bottomPanelStore'\nimport { useSidebarTabStore } from './workspace/sidebarTabStore'\n\nconst legacySeverityKinds = new Map<\n  string,\n  'error' | 'info' | 'success' | 'warning'\n>([\n  ['contrast', 'info'],\n  ['error', 'error'],\n  ['info', 'info'],\n  ['secondary', 'info'],\n  ['success', 'success'],\n  ['warn', 'warning'],\n  ['warning', 'warning']\n])\n\nfunction workspaceStoreSetup() {\n  const spinner = ref(false)\n  const { shift: shiftDown } = useMagicKeys()\n  /**\n   * Whether the workspace is in focus mode.\n   * When in focus mode, only the graph editor is visible.\n   */\n  const focusMode = ref(false)\n\n  const toastStore = useToast()\n  let reportedWarningSeverity = false\n  function reportWarningSeverity() {\n    if (reportedWarningSeverity) return\n    reportedWarningSeverity = true\n    reportError(new Error('toast.add received severity \"warning\"'), {\n      surface: 'platform',\n      errorType: 'deprecated_toast_warning_severity',\n      level: 'warning'\n    })\n  }\n  const toast: ToastManager = {\n    add: (message: ToastMessageOptions) => {\n      const severity: string = message.severity ?? 'info'\n      if (severity === 'warning') reportWarningSeverity()\n      const kind = legacySeverityKinds.get(severity)\n      if (!kind) {\n        console.error(`toast.add: unsupported severity \"${severity}\"`)\n        return\n      }\n      toastStore[kind](message.summary ?? message.detail ?? '', {\n        closable: message.closable,\n        description: message.summary === undefined ? undefined : message.detail,\n        duration: message.life || undefined\n      })\n    },\n    addAlert: (message) => toastStore.warning(message),\n    dismiss: toastStore.dismiss,\n    dismissAll: toastStore.dismissAll,\n    error: toastStore.error,\n    info: toastStore.info,\n    loading: toastStore.loading,\n    success: toastStore.success,\n    warning: toastStore.warning\n  }\n  const queueSettings = computed(() => useQueueSettingsStore())\n  const command = computed(() => ({\n    commands: useCommandStore().commands,\n    execute: useCommandStore().execute\n  }))\n  const sidebarTab = computed(() => useSidebarTabStore())\n  const setting = computed(() => ({\n    settings: useSettingStore().settingsById,\n    // Allow generic key access to settings as custom nodes may add their\n    // own settings which is not tracked by the `Setting` schema.\n    // oxlint-disable-next-line typescript/no-unnecessary-type-parameters\n    get: <T = unknown>(key: string): T | undefined =>\n      useSettingStore().get(key as keyof Settings) as T | undefined,\n    set: (key: string, value: unknown) =>\n      useSettingStore().set(\n        key as keyof Settings,\n        value as Settings[keyof Settings]\n      )\n  }))\n  const workflow = computed(() => useWorkflowStore())\n  const colorPalette = useColorPaletteService()\n  const dialog = computed(() => useExtensionDialogService())\n  const bottomPanel = useBottomPanelStore()\n\n  const authStore = useAuthStore()\n  const apiKeyStore = useApiKeyAuthStore()\n\n  const isApiKeyLogin = computed(() => apiKeyStore.isAuthenticated)\n  const isLoggedIn = computed(\n    () => isApiKeyLogin.value || authStore.isAuthenticated\n  )\n  const partialUserStore = {\n    isLoggedIn\n  }\n\n  /**\n   * Registers a sidebar tab.\n   * @param tab The sidebar tab to register.\n   * @deprecated Use `sidebarTab.registerSidebarTab` instead.\n   */\n  function registerSidebarTab(tab: SidebarTabExtension) {\n    sidebarTab.value.registerSidebarTab(tab)\n  }\n\n  /**\n   * Unregisters a sidebar tab.\n   * @param id The id of the sidebar tab to unregister.\n   * @deprecated Use `sidebarTab.unregisterSidebarTab` instead.\n   */\n  function unregisterSidebarTab(id: string) {\n    sidebarTab.value.unregisterSidebarTab(id)\n  }\n\n  /**\n   * Gets all registered sidebar tabs.\n   * @returns All registered sidebar tabs.\n   * @deprecated Use `sidebarTab.sidebarTabs` instead.\n   */\n  function getSidebarTabs(): SidebarTabExtension[] {\n    return sidebarTab.value.sidebarTabs\n  }\n\n  const executionErrorStore = useExecutionErrorStore()\n\n  return {\n    spinner,\n    shiftDown,\n    focusMode,\n    toggleFocusMode: () => {\n      focusMode.value = !focusMode.value\n    },\n    toast,\n    queueSettings,\n    command,\n    sidebarTab,\n    setting,\n    workflow,\n    colorPalette,\n    dialog,\n    bottomPanel,\n    user: partialUserStore,\n\n    // Execution error state (read-only, exposed for custom extensions)\n    lastNodeErrors: computed(() => executionErrorStore.lastNodeErrors),\n    lastExecutionError: computed(() => executionErrorStore.lastExecutionError),\n\n    registerSidebarTab,\n    unregisterSidebarTab,\n    getSidebarTabs,\n    renderMarkdownToHtml\n  }\n}\n\nexport const useWorkspaceStore = defineStore('workspace', workspaceStoreSetup)\n","import { toRaw } from 'vue'\n\nimport { downloadBlob } from '@/base/common/downloadUtil'\nimport { t } from '@/i18n'\nimport type { Point, SerialisableGraph } from '@/lib/litegraph/src/litegraph'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport {\n  normalizePendingWarnings,\n  updatePendingWarnings\n} from '@/platform/workflow/core/utils/pendingWarnings'\nimport { workflowToClipboardItems } from '@/platform/workflow/core/utils/workflowToClipboardItems'\nimport {\n  areWorkflowIdsEquivalent,\n  ensureWorkflowId,\n  getLegacyWorkflowId\n} from '@/platform/workflow/core/utils/workflowId'\nimport { useWorkflowDraftStoreV2 } from '@/platform/workflow/persistence/stores/workflowDraftStoreV2'\nimport {\n  ComfyWorkflow,\n  useWorkflowStore\n} from '@/platform/workflow/management/stores/workflowStore'\nimport { useTelemetry } from '@/platform/telemetry'\nimport type { ComfyWorkflowJSON } from '@/platform/workflow/validation/schemas/workflowSchema'\n// oxlint-disable-next-line comfy/no-restricted-paths\nimport { useWorkflowThumbnail } from '@/renderer/core/thumbnail/useWorkflowThumbnail'\nimport { useApp } from '@/scripts/appInstance'\nimport { blankGraph, defaultGraph } from '@/scripts/defaultGraph'\nimport { useDialogService } from '@/services/dialogService'\nimport { useAppMode } from '@/composables/useAppMode'\nimport { useDomWidgetStore } from '@/stores/domWidgetStore'\nimport { useAppModeStore } from '@/stores/appModeStore'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport { useNodeOutputStore } from '@/stores/nodeOutputStore'\nimport { useSubgraphNavigationStore } from '@/stores/subgraphNavigationStore'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useMissingNodesErrorStore } from '@/platform/nodeReplacement/missingNodesErrorStore'\nimport { useMissingModelStore } from '@/platform/missingModel/missingModelStore'\nimport { useMissingMediaStore } from '@/platform/missingMedia/missingMediaStore'\nimport { useWorkspaceStore } from '@/stores/workspaceStore'\nimport {\n  appendJsonExt,\n  appendWorkflowJsonExt,\n  generateUUID\n} from '@/utils/formatUtil'\nimport type { AppMode } from '@/utils/appMode'\nimport type { UUID } from '@/utils/uuid'\nimport { ensureNonZeroUuid, zeroUuid } from '@/utils/uuid'\n\nfunction linearModeToAppMode(linearMode: unknown): AppMode | null {\n  if (typeof linearMode !== 'boolean') return null\n  return linearMode ? 'app' : 'graph'\n}\n\n/**\n * Returns the root graph id to scope run errors by, minting one when the graph\n * carries the zero id. Every caller passes `rootGraph.serialize()` as\n * `workflowData`, and `app.clean()` mints a fresh root id before `loadApiJson`\n * and `importA1111` populate the graph, so the zero id only survives here when\n * something upstream skipped both. The id is written back into `workflowData`\n * only in that zero-id case, so a `configure()`-based load (where\n * `rootGraph.id` already came from `workflowData.id`) can never have this\n * rewrite the incoming workflow's identity to a stale graph's id.\n */\nfunction adoptRootGraphId(workflowData: ComfyWorkflowJSON): UUID | null {\n  if (!useApp().isGraphReady) return null\n\n  const rootGraph = useApp().rootGraph\n  if (rootGraph.id === zeroUuid) {\n    workflowData.id = ensureNonZeroUuid(rootGraph)\n  }\n  return rootGraph.id\n}\n\n// TRANSITIONAL (decision log D14): deletable when ECS scopes workflow\n// loading per document; the contract tests transfer.\nlet workflowLoadTail: Promise<unknown> = Promise.resolve()\nlet pendingWorkflowLoads = 0\nconst pendingWorkflowLoadsByPath = new Map<string, Promise<unknown>>()\n// Object identity, not path: a mid-close rename would strand a path key.\nconst closingWorkflowCounts = new Map<ComfyWorkflow, number>()\n\n/** The registry key: raw instance, so reactive proxies and raw references agree. */\nfunction closingKey(workflow: ComfyWorkflow): ComfyWorkflow {\n  return toRaw(workflow)\n}\n\n/**\n * The id to fall back to when incoming workflow data carries none.\n *\n * Deliberately takes `ComfyWorkflow` rather than `LoadedComfyWorkflow`:\n * `LoadedComfyWorkflow` declares `activeState` non-null, but it is produced by\n * an unchecked `this as this & LoadedComfyWorkflow` cast over a getter that\n * still returns `this.changeTracker?.activeState ?? null`. Reading through the\n * nullable base contract is what makes the optional chain honest rather than\n * redundant. Returning `undefined` is safe: `ensureWorkflowId` generates a\n * fresh UUID for an absent or invalid fallback.\n *\n * Without this, activation threw `TypeError: Cannot read properties of null\n * (reading 'id')` (SEN-5, Sentry CLOUD-FRONTEND-PROD-1MB) — and it threw even\n * when the incoming data already had a valid id, because the argument is\n * evaluated before `ensureWorkflowId` can ignore it.\n */\nfunction activeStateFallbackId(workflow: ComfyWorkflow): string | undefined {\n  return workflow.activeState?.id\n}\n\n/** @internal Test-only: clears the module-level load queue between tests. */\nexport function resetWorkflowLoadQueueForTests(): {\n  pendingLoads: number\n  closingCount: number\n  pendingPaths: number\n} {\n  const drained = {\n    pendingLoads: pendingWorkflowLoads,\n    closingCount: closingWorkflowCounts.size,\n    pendingPaths: pendingWorkflowLoadsByPath.size\n  }\n  workflowLoadTail = Promise.resolve()\n  pendingWorkflowLoads = 0\n  pendingWorkflowLoadsByPath.clear()\n  closingWorkflowCounts.clear()\n  return drained\n}\n\nfunction queueWorkflowLoad<T>(\n  load: () => Promise<T>,\n  workflowPath?: string\n): Promise<T> {\n  pendingWorkflowLoads++\n  const result = workflowLoadTail.then(load)\n  const settledResult = result\n    .catch((error) => {\n      // Keep fire-and-forget load failures observable.\n      reportError(error, {\n        surface: 'graph',\n        errorType: 'workflow_load_failure'\n      })\n      return undefined\n    })\n    .finally(() => {\n      pendingWorkflowLoads--\n      if (\n        workflowPath &&\n        pendingWorkflowLoadsByPath.get(workflowPath) === settledResult\n      ) {\n        pendingWorkflowLoadsByPath.delete(workflowPath)\n      }\n    })\n  workflowLoadTail = settledResult\n  if (workflowPath) {\n    pendingWorkflowLoadsByPath.set(workflowPath, settledResult)\n  }\n  return result\n}\n\nexport const useWorkflowService = () => {\n  const settingStore = useSettingStore()\n  const workflowStore = useWorkflowStore()\n  const toast = useToast()\n  const dialogService = useDialogService()\n  const workflowThumbnail = useWorkflowThumbnail()\n  const domWidgetStore = useDomWidgetStore()\n  const missingNodesErrorStore = useMissingNodesErrorStore()\n  const workflowDraftStore = useWorkflowDraftStoreV2()\n\n  const showFailedToSaveDraftToast = () => {\n    toast.error(t('g.error'), {\n      description: t('toastMessages.failedToSaveDraft')\n    })\n  }\n\n  const persistActiveWorkflowDraft = (activeWorkflow: ComfyWorkflow) => {\n    if (!settingStore.get('Comfy.Workflow.Persist') || !activeWorkflow.path) {\n      return\n    }\n\n    const activeState = activeWorkflow.activeState\n    if (!activeState) return\n\n    try {\n      const saved = workflowDraftStore.saveDraft(\n        activeWorkflow.path,\n        JSON.stringify(activeState),\n        {\n          name: activeWorkflow.key,\n          isTemporary: activeWorkflow.isTemporary\n        }\n      )\n\n      if (!saved) {\n        showFailedToSaveDraftToast()\n      }\n    } catch (err) {\n      console.error('Failed to persist active workflow draft', err)\n      showFailedToSaveDraftToast()\n    }\n  }\n\n  function confirmOverwrite(targetPath: string) {\n    return dialogService.confirm({\n      title: t('sideToolbar.workflowTab.confirmOverwriteTitle'),\n      type: 'overwrite',\n      message: t('sideToolbar.workflowTab.confirmOverwrite'),\n      itemList: [targetPath]\n    })\n  }\n\n  async function getFilename(defaultName: string): Promise<string | null> {\n    if (settingStore.get('Comfy.PromptFilename')) {\n      let filename = await dialogService.prompt({\n        title: t('workflowService.exportWorkflow'),\n        message: t('workflowService.enterFilenamePrompt'),\n        defaultValue: defaultName\n      })\n      if (!filename) return null\n      if (!filename.toLowerCase().endsWith('.json')) {\n        filename += '.json'\n      }\n      return filename\n    }\n    return defaultName\n  }\n\n  /**\n   * Adds scale and offset from litegraph canvas to the workflow JSON.\n   * @param workflow The workflow to add the view restore data to\n   */\n  function addViewRestore(workflow: ComfyWorkflowJSON) {\n    if (!settingStore.get('Comfy.EnableWorkflowViewRestore')) return\n\n    const { offset, scale } = useApp().canvas.ds\n    const [x, y] = offset\n\n    workflow.extra ??= {}\n    workflow.extra.ds = { scale, offset: [x, y] }\n  }\n\n  /**\n   * Export the current workflow as a JSON file\n   * @param filename The filename to save the workflow as\n   * @param promptProperty The property of the prompt to export\n   */\n  const exportWorkflow = async (\n    filename: string,\n    promptProperty: 'workflow' | 'output'\n  ): Promise<void> => {\n    const workflow = workflowStore.activeWorkflow\n    if (workflow?.path) {\n      filename = workflow.filename\n    }\n    const p = await useApp().graphToPrompt()\n\n    addViewRestore(p.workflow)\n    const json = JSON.stringify(p[promptProperty], null, 2)\n    const blob = new Blob([json], { type: 'application/json' })\n    const file = await getFilename(filename)\n    if (!file) return\n    downloadBlob(file, blob)\n  }\n  /**\n   * Save a workflow as a new file\n   * @param workflow The workflow to save\n   * @param options.filename Pre-supplied filename (skips the prompt dialog)\n   */\n  const saveWorkflowAs = async (\n    workflow: ComfyWorkflow,\n    options: { filename?: string; isApp?: boolean } = {}\n  ): Promise<boolean> => {\n    const newFilename = options.filename ?? (await workflow.promptSave())\n    if (!newFilename) return false\n\n    const isApp = options.isApp ?? workflow.initialMode === 'app'\n    const newPath =\n      workflow.directory + '/' + appendWorkflowJsonExt(newFilename, isApp)\n    const existingWorkflow = workflowStore.getWorkflowByPath(newPath)\n\n    const isSelfOverwrite =\n      existingWorkflow?.path === workflow.path && !existingWorkflow.isTemporary\n\n    if (existingWorkflow && !existingWorkflow.isTemporary) {\n      if ((await confirmOverwrite(newPath)) !== true) return false\n\n      if (!isSelfOverwrite) {\n        const deleted = await deleteWorkflow(existingWorkflow, true)\n        if (!deleted) return false\n      }\n    }\n\n    if (isSelfOverwrite) {\n      workflow.changeTracker?.prepareForSave()\n      // Call workflowStore.saveWorkflow directly: saveWorkflowAs emits its own is_new:true event below, so delegating to saveWorkflow() would also fire is_new:false and run prepareForSave a second time.\n      await workflowStore.saveWorkflow(workflow)\n    } else {\n      let target: ComfyWorkflow\n      if (workflow.isTemporary) {\n        await renameWorkflow(workflow, newPath)\n        target = workflow\n      } else {\n        target = workflowStore.saveAs(workflow, newPath)\n        await openWorkflow(target)\n      }\n\n      if (options.isApp !== undefined) {\n        useApp().rootGraph.extra.linearMode = isApp\n        target.initialMode = isApp ? 'app' : 'graph'\n      }\n      target.changeTracker?.prepareForSave()\n      await workflowStore.saveWorkflow(target)\n    }\n\n    useTelemetry()?.trackWorkflowSaved({ is_app: isApp, is_new: true })\n    return true\n  }\n\n  /**\n   * Save a workflow\n   * @param workflow The workflow to save\n   */\n  const saveWorkflow = async (workflow: ComfyWorkflow): Promise<boolean> => {\n    if (workflow.isTemporary) {\n      return await saveWorkflowAs(workflow)\n    }\n\n    workflow.changeTracker?.prepareForSave()\n    const isApp = workflow.initialMode === 'app'\n    const expectedPath =\n      workflow.directory + '/' + appendWorkflowJsonExt(workflow.filename, isApp)\n    if (workflow.path !== expectedPath) {\n      const existing = workflowStore.getWorkflowByPath(expectedPath)\n      if (existing && !existing.isTemporary) {\n        if ((await confirmOverwrite(expectedPath)) !== true) {\n          await workflowStore.saveWorkflow(workflow)\n          return true\n        }\n        await deleteWorkflow(existing, true)\n      }\n      await renameWorkflow(workflow, expectedPath)\n      toast.info(\n        t(\n          isApp\n            ? 'workflowService.savedAsApp'\n            : 'workflowService.savedAsWorkflow'\n        ),\n        { duration: 3000 }\n      )\n    }\n\n    await workflowStore.saveWorkflow(workflow)\n    useTelemetry()?.trackWorkflowSaved({ is_app: isApp, is_new: false })\n    return true\n  }\n\n  /**\n   * Load the default workflow\n   */\n  const loadDefaultWorkflow = () =>\n    queueWorkflowLoad(() => useApp().loadGraphData(defaultGraph))\n\n  /**\n   * Load a blank workflow\n   */\n  const loadBlankWorkflow = () =>\n    queueWorkflowLoad(() => useApp().loadGraphData(blankGraph))\n\n  /**\n   * Reload the current workflow\n   * This is used to refresh the node definitions update, e.g. when the locale changes.\n   */\n  const reloadCurrentWorkflow = async () => {\n    const workflow = workflowStore.activeWorkflow\n    if (workflow) {\n      await openWorkflow(workflow, { force: true })\n    }\n  }\n\n  /**\n   * Open a workflow in the current workspace\n   * @param workflow The workflow to open\n   * @param options The options for opening the workflow\n   * @returns false when the graph load reported failure (the error dialog was\n   * shown and the workflow never painted) or when the open was skipped because\n   * the workflow is mid-close; true otherwise\n   */\n  /**\n   * A failed replacement load leaves the shared root graph cleaned or\n   * partially configured while the previous workflow stays selected\n   * (16075 review). Repaint the retained workflow from its just-saved\n   * state so selection, canvas, and change tracking agree again. No\n   * retry loop: a failure here leaves the first failure's dialog\n   * standing.\n   */\n  const restoreRetainedWorkflow = async (failed: ComfyWorkflow) => {\n    const retained = getActiveWorkflow()\n    if (!retained || retained.path === failed.path || !retained.isLoaded) return\n\n    await useApp().loadGraphData(\n      toRaw(retained.activeState) as ComfyWorkflowJSON,\n      /* clean=*/ true,\n      /* restore_view=*/ true,\n      retained,\n      {\n        checkForRerouteMigration: false,\n        deferWarnings: true,\n        skipAssetScans: true\n      }\n    )\n  }\n\n  function getActiveWorkflow(): ComfyWorkflow | null {\n    return workflowStore.activeWorkflow\n  }\n\n  // A superseded open leaves the workflow as it found it. A saved file drops\n  // what it fetched, including a draft's modified mark, so a later save cannot\n  // write an empty graph; a temporary one has no remote copy to refetch, so it\n  // keeps its content, as closing it does.\n  function discardSupersededLoad(\n    workflow: ComfyWorkflow,\n    wasModified: boolean\n  ): void {\n    if (workflow.isTemporary) return\n    workflow.unload()\n    workflow.isModified = wasModified\n  }\n\n  const openWorkflow = (\n    workflow: ComfyWorkflow,\n    options: {\n      force?: boolean\n      navigationIntentId?: number\n      isCurrent?: () => boolean\n    } = {}\n  ): Promise<boolean> => {\n    if (options.isCurrent?.() === false) return Promise.resolve(false)\n    if (closingWorkflowCounts.has(closingKey(workflow)))\n      return Promise.resolve(false)\n    if (\n      pendingWorkflowLoads === 0 &&\n      workflowStore.isActive(workflow) &&\n      !options.force\n    ) {\n      return Promise.resolve(true)\n    }\n\n    const navigationIntentId =\n      options.navigationIntentId ??\n      useSubgraphNavigationStore().beginWorkflowNavigation()\n    return queueWorkflowLoad(async () => {\n      try {\n        if (options.isCurrent?.() === false) {\n          useSubgraphNavigationStore().endWorkflowNavigation(navigationIntentId)\n          return false\n        }\n        const loadFromRemote = !workflow.isLoaded\n        const wasModified = workflow.isModified\n        if (loadFromRemote) {\n          await workflow.load()\n        }\n        if (options.isCurrent?.() === false) {\n          if (loadFromRemote) discardSupersededLoad(workflow, wasModified)\n          useSubgraphNavigationStore().endWorkflowNavigation(navigationIntentId)\n          return false\n        }\n\n        const loaded = await useApp().loadGraphData(\n          toRaw(workflow.activeState) as ComfyWorkflowJSON,\n          /* clean=*/ true,\n          /* restore_view=*/ true,\n          workflow,\n          {\n            checkForRerouteMigration: false,\n            deferWarnings: true,\n            skipAssetScans: !loadFromRemote && !options.force,\n            workflowNavigationId: navigationIntentId\n          }\n        )\n        if (loaded === false) {\n          // Same invariant as the catch: a failed load's intent must not\n          // stay newest (guarded no-op when the publish already superseded).\n          useSubgraphNavigationStore().endWorkflowNavigation(navigationIntentId)\n          await restoreRetainedWorkflow(workflow)\n          return false\n        }\n        showPendingWarnings(undefined, {\n          silent: !loadFromRemote && !options.force\n        })\n        return true\n      } catch (error) {\n        // A failed load's intent must not stay newest (suppresses the survivor's hash).\n        useSubgraphNavigationStore().endWorkflowNavigation(navigationIntentId)\n        throw error\n      }\n    }, workflow.path)\n  }\n\n  /**\n   * Close a workflow with confirmation if there are unsaved changes\n   * @param workflow The workflow to close\n   * @returns true if the workflow was closed; false if the user\n   * cancelled or the replacement/default load reported failure (the\n   * workflow then stays open with its draft intact)\n   */\n  const closeWorkflow = async (\n    workflow: ComfyWorkflow,\n    options: { warnIfUnsaved: boolean; hint?: string } = {\n      warnIfUnsaved: true\n    }\n  ): Promise<boolean> => {\n    if (workflow.isModified && options.warnIfUnsaved) {\n      const confirmed = await dialogService.confirm({\n        title: t('sideToolbar.workflowTab.dirtyCloseTitle'),\n        type: 'dirtyClose',\n        message: t('sideToolbar.workflowTab.dirtyClose'),\n        itemList: [workflow.path],\n        hint: options.hint,\n        denyLabel: t('sideToolbar.workflowTab.dirtyCloseAnyway')\n      })\n      // Cancel\n      if (confirmed === null) return false\n\n      if (confirmed) {\n        const saved = await saveWorkflow(workflow)\n        if (!saved) return false\n      }\n    }\n\n    // Captured once: a mid-close rename mutates workflow.path in place.\n    const closingPath = workflow.path\n    const closing = closingKey(workflow)\n    closingWorkflowCounts.set(\n      closing,\n      (closingWorkflowCounts.get(closing) ?? 0) + 1\n    )\n    try {\n      const wasActive = workflowStore.isActive(workflow)\n      const pendingWorkflowLoad = pendingWorkflowLoadsByPath.get(closingPath)\n      if (!wasActive && pendingWorkflowLoad) await pendingWorkflowLoad\n      if (\n        wasActive ||\n        (pendingWorkflowLoad && workflowStore.isActive(workflow))\n      ) {\n        // Bounded drain: quiesce for the replacement decision without letting\n        // a hot enqueue stream starve the close.\n        for (let spins = 0; spins < 16; spins++) {\n          const observedOpenTail = workflowLoadTail\n          await observedOpenTail\n          if (observedOpenTail === workflowLoadTail) break\n        }\n      }\n\n      // If this is the active workflow, load the most recent workflow from history\n      if (workflowStore.isActive(workflow)) {\n        const mostRecentWorkflow = workflowStore.getMostRecentWorkflow()\n        let replacementWorkflow =\n          mostRecentWorkflow &&\n          !closingWorkflowCounts.has(closingKey(mostRecentWorkflow))\n            ? mostRecentWorkflow\n            : undefined\n        for (\n          let shift = 1;\n          !replacementWorkflow && shift < workflowStore.openWorkflows.length;\n          shift++\n        ) {\n          const candidate = workflowStore.openedWorkflowIndexShift(shift)\n          if (candidate && !closingWorkflowCounts.has(closingKey(candidate))) {\n            replacementWorkflow = candidate\n          }\n        }\n        // `=== false` on purpose: only an EXPLICIT failure report aborts\n        // the close (a real configure failure resolves false - the dialog\n        // path); a rejection still propagates as before.\n        if (replacementWorkflow) {\n          if (!(await openWorkflow(replacementWorkflow))) return false\n        } else {\n          if ((await loadDefaultWorkflow()) === false) return false\n        }\n      } else if (\n        // Read live, post-drain: the awaits above can change the answer.\n        workflowStore.openWorkflows.length > 0 &&\n        workflowStore.openWorkflows.every((open) =>\n          closingWorkflowCounts.has(closingKey(open))\n        )\n      ) {\n        if ((await loadDefaultWorkflow()) === false) return false\n      }\n\n      await workflowStore.closeWorkflow(workflow)\n      // Only after the close is real: a still-open tab keeps its draft.\n      workflowDraftStore.removeDraft(closingPath)\n      useNodeOutputStore().discardPreviewsForWorkflow(closingPath)\n      return true\n    } finally {\n      const remainingCloses = closingWorkflowCounts.get(closing) ?? 0\n      if (remainingCloses <= 1) {\n        closingWorkflowCounts.delete(closing)\n      } else {\n        closingWorkflowCounts.set(closing, remainingCloses - 1)\n      }\n    }\n  }\n\n  const renameWorkflow = async (workflow: ComfyWorkflow, newPath: string) => {\n    const oldPath = workflow.path\n    const graphId = workflow.activeState?.id\n    await workflowStore.renameWorkflow(workflow, newPath)\n    if (graphId) {\n      useExecutionErrorStore().moveRunErrors(graphId, oldPath, workflow.path)\n    }\n  }\n\n  /**\n   * Delete a workflow\n   * @param workflow The workflow to delete\n   * @returns `true` if the workflow was deleted; `false` if the user\n   * cancelled or the close was aborted by a failed replacement load\n   */\n  const deleteWorkflow = async (\n    workflow: ComfyWorkflow,\n    silent = false\n  ): Promise<boolean> => {\n    const bypassConfirm = !settingStore.get('Comfy.Workflow.ConfirmDelete')\n    let confirmed: boolean | null = bypassConfirm || silent\n\n    if (!confirmed) {\n      confirmed = await dialogService.confirm({\n        title: t('sideToolbar.workflowTab.confirmDeleteTitle'),\n        type: 'delete',\n        message: t('sideToolbar.workflowTab.confirmDelete'),\n        itemList: [workflow.path]\n      })\n      if (!confirmed) return false\n    }\n\n    if (workflowStore.isOpen(workflow)) {\n      const closed = await closeWorkflow(workflow, {\n        warnIfUnsaved: !confirmed\n      })\n      if (!closed) return false\n    }\n    await workflowStore.deleteWorkflow(workflow)\n    if (!silent) {\n      toast.info(t('sideToolbar.workflowTab.deleted'), { duration: 1000 })\n    }\n    return true\n  }\n\n  /**\n   * This method is called before loading a new graph.\n   * There are 3 major functions that loads a new graph to the graph editor:\n   * 1. loadGraphData\n   * 2. loadApiJson\n   * 3. importA1111\n   *\n   * This function is used to save the current workflow states before loading\n   * a new graph.\n   */\n  const beforeLoadNewGraph = (suppressWorkflowReset = true) => {\n    // Use workspaceStore here as it is patched in unit tests.\n    const workflowStore = useWorkspaceStore().workflow\n    const activeWorkflow = workflowStore.activeWorkflow\n    if (activeWorkflow) {\n      activeWorkflow.changeTracker.deactivate()\n      persistActiveWorkflowDraft(activeWorkflow)\n      // Cache missing model/media/node state for restore on tab switch.\n      // Always overwrite to reflect the current store state (e.g. after\n      // muting a node cleared its errors).\n      const modelCandidates = useMissingModelStore().missingModelCandidates\n      const mediaCandidates = useMissingMediaStore().missingMediaCandidates\n      const nodeTypes = missingNodesErrorStore.missingNodesError?.nodeTypes\n      updatePendingWarnings(activeWorkflow, {\n        missingNodeTypes: nodeTypes?.length ? [...nodeTypes] : undefined,\n        missingModelCandidates: modelCandidates ?? undefined,\n        missingMediaCandidates: mediaCandidates ?? undefined\n      })\n\n      // Hand the previews to the store before `app.clean()` revokes them\n      useNodeOutputStore().stashPreviewsForWorkflow(activeWorkflow.path)\n\n      // Capture thumbnail before loading new graph\n      void workflowThumbnail.storeThumbnail(\n        activeWorkflow,\n        workflowStore.activeSubgraph || useApp().canvasOrUndefined?.graph\n      )\n      domWidgetStore.clear()\n\n      // Save subgraph viewport before the canvas gets overwritten\n      useSubgraphNavigationStore().saveCurrentViewport(suppressWorkflowReset)\n    }\n  }\n\n  /**\n   * Set the active workflow after the new graph is loaded.\n   *\n   * The call relationship is\n   * useWorkflowService().openWorkflow -> app.loadGraphData -> useWorkflowService().afterLoadNewGraph\n   * app.loadApiJson -> useWorkflowService().afterLoadNewGraph\n   * app.importA1111 -> useWorkflowService().afterLoadNewGraph\n   *\n   * @param value The value to set as the active workflow.\n   * @param workflowData The initial workflow data loaded to the graph editor.\n   */\n  const afterLoadNewGraph = async (\n    value: string | ComfyWorkflow | null,\n    workflowData: ComfyWorkflowJSON,\n    shareId?: string\n  ) => {\n    const graphState = useApp().rootGraphOrUndefined?.state\n    await activateLoadedWorkflow(value, workflowData, shareId)\n    if (graphState !== useApp().rootGraphOrUndefined?.state) return\n    useNodeOutputStore().restorePreviewsForWorkflow(\n      useWorkspaceStore().workflow.activeWorkflow?.path\n    )\n  }\n\n  const activateLoadedWorkflow = async (\n    value: string | ComfyWorkflow | null,\n    workflowData: ComfyWorkflowJSON,\n    shareId?: string\n  ) => {\n    const graphState = useApp().rootGraphOrUndefined?.state\n    const workflowStore = useWorkspaceStore().workflow\n    const { isAppMode } = useAppMode()\n    const wasAppMode = isAppMode.value\n    const rootGraphId = adoptRootGraphId(workflowData)\n\n    function activateRunErrors(workflow: ComfyWorkflow) {\n      useExecutionErrorStore().setActiveGraph(rootGraphId, workflow.path)\n    }\n\n    // Determine the initial app mode for fresh loads from serialized state.\n    // null means linearMode was never explicitly set (not builder-saved).\n    const freshLoadMode = linearModeToAppMode(workflowData.extra?.linearMode)\n    useAppModeStore().loadSelections(workflowData.extra?.linearData)\n\n    function trackIfEnteringApp(workflow: ComfyWorkflow) {\n      if (!wasAppMode && workflow.initialMode === 'app') {\n        useTelemetry()?.trackEnterLinear({ source: 'workflow' })\n      }\n    }\n\n    if (value === null || typeof value === 'string') {\n      // Check if a persisted workflow with this path exists\n      if (value) {\n        const fullPath = ComfyWorkflow.basePath + appendJsonExt(value)\n        const existingWorkflow = workflowStore.getWorkflowByPath(fullPath)\n\n        // Reuse an existing workflow when this is a restoration case\n        // (persisted but currently unloaded) or an idempotent repeated load\n        // of the currently active same-path workflow.\n        //\n        // This prevents accidental duplicate tabs when startup/load flows\n        // invoke loadGraphData more than once for the same workflow name.\n        const existingId = existingWorkflow?.activeState?.id\n        const isSameActiveWorkflowLoad =\n          !!existingWorkflow &&\n          workflowStore.isActive(existingWorkflow) &&\n          (existingWorkflow.isTemporary ||\n            areWorkflowIdsEquivalent(\n              existingId,\n              workflowData.id,\n              existingWorkflow.legacyId\n            ))\n\n        if (\n          existingWorkflow &&\n          ((existingWorkflow.isPersisted && !existingWorkflow.isLoaded) ||\n            isSameActiveWorkflowLoad)\n        ) {\n          const loadedWorkflow =\n            await workflowStore.openWorkflow(existingWorkflow)\n          if (graphState !== useApp().rootGraphOrUndefined?.state) return\n          activateRunErrors(loadedWorkflow)\n          if (loadedWorkflow.initialMode === undefined) {\n            // Prefer the file's linearMode over the draft's since the file\n            // is the authoritative saved state.\n            loadedWorkflow.initialMode =\n              linearModeToAppMode(\n                loadedWorkflow.initialState.extra?.linearMode\n              ) ?? freshLoadMode\n            trackIfEnteringApp(loadedWorkflow)\n          }\n          if (shareId) {\n            loadedWorkflow.shareId = shareId\n          }\n          loadedWorkflow.legacyId ??= getLegacyWorkflowId(workflowData.id)\n          loadedWorkflow.changeTracker.reset(\n            ensureWorkflowId(\n              workflowData,\n              activeStateFallbackId(loadedWorkflow)\n            )\n          )\n          loadedWorkflow.changeTracker.restore()\n          return\n        }\n      }\n\n      const tempWorkflow = workflowStore.createNewTemporary(\n        value ? appendJsonExt(value) : undefined,\n        workflowData\n      )\n      tempWorkflow.initialMode = freshLoadMode\n      if (shareId) {\n        tempWorkflow.shareId = shareId\n      }\n      trackIfEnteringApp(tempWorkflow)\n      const loadedWorkflow = await workflowStore.openWorkflow(tempWorkflow)\n      if (graphState !== useApp().rootGraphOrUndefined?.state) return\n      activateRunErrors(loadedWorkflow)\n      return\n    }\n\n    const loadedWorkflow = await workflowStore.openWorkflow(value)\n    if (graphState !== useApp().rootGraphOrUndefined?.state) return\n    activateRunErrors(loadedWorkflow)\n    if (shareId) {\n      loadedWorkflow.shareId = shareId\n    }\n    if (loadedWorkflow.initialMode === undefined) {\n      loadedWorkflow.initialMode = freshLoadMode\n      trackIfEnteringApp(loadedWorkflow)\n    }\n    loadedWorkflow.legacyId ??= getLegacyWorkflowId(workflowData.id)\n    loadedWorkflow.changeTracker.reset(\n      ensureWorkflowId(workflowData, activeStateFallbackId(loadedWorkflow))\n    )\n    loadedWorkflow.changeTracker.restore()\n  }\n\n  /**\n   * Insert the given workflow into the current graph editor.\n   */\n  const insertWorkflow = async (\n    workflow: ComfyWorkflow,\n    options: { position?: Point } = {}\n  ) => {\n    const canvas = useApp().canvas\n    const graph = canvas.graph\n    const loadedWorkflow = await workflow.load()\n    if (useApp().canvas !== canvas || canvas.graph !== graph) {\n      const replacementKind = useApp().canvas !== canvas ? 'canvas' : 'graph'\n      reportError(\n        new Error(\n          'insertWorkflow aborted: canvas or graph was replaced while the workflow loaded'\n        ),\n        {\n          surface: 'graph',\n          errorType: 'workflow_insert_aborted_canvas_changed',\n          level: 'warning',\n          tags: {\n            failure_kind: 'degraded',\n            feature_area: 'workflow',\n            operation: 'insert',\n            outcome: 'degraded',\n            assert_mode: 'soft'\n          },\n          context: { replacement_kind: replacementKind }\n        }\n      )\n      return\n    }\n    const workflowJSON = toRaw(loadedWorkflow.initialState)\n    // unknown conversion: ComfyWorkflowJSON is stricter than LiteGraph's\n    // serialisation schema.\n    const items = workflowToClipboardItems(\n      workflowJSON as unknown as SerialisableGraph\n    )\n    canvas._deserializeItems(items, options)\n  }\n\n  const loadNextOpenedWorkflow = async () => {\n    const nextWorkflow = workflowStore.openedWorkflowIndexShift(1)\n    if (nextWorkflow) {\n      await openWorkflow(nextWorkflow)\n    }\n  }\n\n  const loadPreviousOpenedWorkflow = async () => {\n    const previousWorkflow = workflowStore.openedWorkflowIndexShift(-1)\n    if (previousWorkflow) {\n      await openWorkflow(previousWorkflow)\n    }\n  }\n\n  /**\n   * Takes an existing workflow and duplicates it with a new name\n   */\n  const duplicateWorkflow = async (workflow: ComfyWorkflow) => {\n    if (!workflow.isLoaded) await workflow.load()\n    const state = JSON.parse(JSON.stringify(workflow.activeState))\n    // Ensure duplicates are always treated as distinct workflows.\n    if (state) state.id = generateUUID()\n    const suffix = workflow.isPersisted ? ' (Copy)' : ''\n    // Remove the suffix `(2)` or similar\n    const filename = workflow.filename.replace(/\\s*\\(\\d+\\)$/, '') + suffix\n    const duplicate = workflowStore.createNewTemporary(\n      appendJsonExt(filename),\n      state\n    )\n\n    await queueWorkflowLoad(() =>\n      useApp().loadGraphData(state, true, true, duplicate)\n    )\n  }\n\n  /**\n   * Show and clear any pending warnings (missing nodes/models) stored on the\n   * active workflow. Called after a workflow becomes visible so dialogs don't\n   * overlap with subsequent loads.\n   */\n  function showPendingWarnings(\n    workflow?: ComfyWorkflow | null,\n    options?: { silent?: boolean }\n  ) {\n    const wf = workflow ?? workflowStore.activeWorkflow\n    if (!wf) return\n\n    const { missingNodeTypes, missingModelCandidates, missingMediaCandidates } =\n      wf.pendingWarnings ?? {}\n\n    // Always sync missing nodes store (clear when empty).\n    if (\n      missingNodesErrorStore.surfaceMissingNodes(missingNodeTypes ?? []) &&\n      !options?.silent\n    ) {\n      useExecutionErrorStore().showErrorOverlay()\n    }\n    if (missingModelCandidates?.length) {\n      useMissingModelStore().setMissingModels(missingModelCandidates)\n    }\n    if (missingMediaCandidates?.length) {\n      useMissingMediaStore().setMissingMedia(missingMediaCandidates)\n    }\n\n    // Keep cache for future tab switches\n    if (\n      missingNodeTypes?.length ||\n      missingModelCandidates?.length ||\n      missingMediaCandidates?.length\n    ) {\n      wf.pendingWarnings = normalizePendingWarnings({\n        missingNodeTypes,\n        missingModelCandidates,\n        missingMediaCandidates\n      })\n    } else {\n      wf.pendingWarnings = null\n    }\n  }\n\n  return {\n    exportWorkflow,\n    saveWorkflowAs,\n    saveWorkflow,\n    loadDefaultWorkflow,\n    loadBlankWorkflow,\n    reloadCurrentWorkflow,\n    openWorkflow,\n    closeWorkflow,\n    renameWorkflow,\n    deleteWorkflow,\n    insertWorkflow,\n    loadNextOpenedWorkflow,\n    loadPreviousOpenedWorkflow,\n    duplicateWorkflow,\n    showPendingWarnings,\n    afterLoadNewGraph,\n    beforeLoadNewGraph\n  }\n}\n","import { createSharedComposable } from '@vueuse/core'\n\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { reportError } from '@/platform/telemetry/reportError'\n\ninterface CanvasOperationBase {\n  element?: HTMLCanvasElement\n  run: () => void\n}\n\ntype CanvasOperation =\n  | (CanvasOperationBase & { key?: never; isCurrent?: never })\n  | (CanvasOperationBase & { key: string; isCurrent: () => boolean })\n\nexport interface CanvasScheduler {\n  /** Run an op now when its canvas is visible, otherwise queue it. */\n  schedule(operation: CanvasOperation): void\n  /** Run every queued op whose canvas is now visible; keep the rest queued. */\n  flush(): void\n  /** Discard the pending operation with this key. */\n  cancel(key: string): void\n}\n\nexport function createCanvasScheduler(): CanvasScheduler {\n  const canvasStore = useCanvasStore()\n  const queue: CanvasOperation[] = []\n\n  function targetOf(operation: CanvasOperation): HTMLCanvasElement | undefined {\n    return operation.element ?? canvasStore.canvas?.canvas\n  }\n\n  function isVisible(element: HTMLCanvasElement | undefined): boolean {\n    return (\n      element?.offsetParent != null &&\n      element.offsetWidth > 0 &&\n      element.offsetHeight > 0\n    )\n  }\n\n  function isStale(operation: CanvasOperation): boolean {\n    if (operation.isCurrent?.() === false) return true\n    const { element } = operation\n    return Boolean(\n      element && element !== canvasStore.canvas?.canvas && !element.isConnected\n    )\n  }\n\n  function run(operation: CanvasOperation): void {\n    try {\n      operation.run()\n    } catch (error) {\n      reportError(error, {\n        errorType: 'canvas_scheduled_operation_failed',\n        surface: 'graph'\n      })\n    }\n  }\n\n  function flush(): void {\n    for (const operation of queue.splice(0)) {\n      if (isStale(operation)) continue\n      if (isVisible(targetOf(operation))) run(operation)\n      else queue.push(operation)\n    }\n  }\n\n  function schedule(operation: CanvasOperation): void {\n    if (operation.isCurrent?.() === false) return\n\n    const existingIndex = operation.key\n      ? queue.findIndex(({ key }) => key === operation.key)\n      : -1\n    if (existingIndex === -1) queue.push(operation)\n    else queue[existingIndex] = operation\n\n    if (isVisible(targetOf(operation))) flush()\n  }\n\n  function cancel(key: string): void {\n    const index = queue.findIndex((operation) => operation.key === key)\n    if (index !== -1) queue.splice(index, 1)\n  }\n\n  return { schedule, flush, cancel }\n}\n\nexport const useCanvasScheduler = createSharedComposable(createCanvasScheduler)\n","export type CreditTransitionNoticePhase =\n  | 'idle'\n  | 'armed'\n  | 'shown'\n  | 'dismissed'\n\nexport type CreditTransitionNoticeState =\n  | {\n      identity: string\n      scopedHasFunds: boolean\n      phase: 'idle' | 'dismissed'\n    }\n  | {\n      identity: string\n      scopedHasFunds: false\n      phase: 'armed' | 'shown'\n    }\n\nexport type CreditTransitionNoticeEvent =\n  | { type: 'scopedRead'; identity: string; scopedHasFunds: boolean }\n  | { type: 'shown'; identity: string }\n  | { type: 'dismissed'; identity: string }\n\nfunction reduceScopedRead(\n  state: CreditTransitionNoticeState | null,\n  identity: string,\n  scopedHasFunds: boolean\n): CreditTransitionNoticeState {\n  if (state === null || state.identity !== identity || scopedHasFunds)\n    return { identity, scopedHasFunds, phase: 'idle' }\n  if (state.phase === 'dismissed') return { ...state, scopedHasFunds }\n  const phase = state.scopedHasFunds ? 'armed' : state.phase\n  return { ...state, scopedHasFunds, phase }\n}\n\nexport function reduceCreditTransitionNotice(\n  state: CreditTransitionNoticeState | null,\n  event: CreditTransitionNoticeEvent\n): CreditTransitionNoticeState | null {\n  if (event.type === 'scopedRead')\n    return reduceScopedRead(state, event.identity, event.scopedHasFunds)\n  if (state === null || state.identity !== event.identity) return state\n  switch (event.type) {\n    case 'shown':\n      return state.phase === 'armed' ? { ...state, phase: 'shown' } : state\n    case 'dismissed':\n      return { ...state, phase: 'dismissed' }\n    default:\n      return event satisfies never\n  }\n}\n\nexport function isCreditTransitionNoticeShown(\n  state: CreditTransitionNoticeState | null,\n  identity: string\n): boolean {\n  if (state === null || state.identity !== identity) return false\n  return state.phase === 'armed' || state.phase === 'shown'\n}\n","import { useEventListener, useLocalStorage, useWindowSize } from '@vueuse/core'\nimport { clamp } from 'es-toolkit'\nimport { defineStore } from 'pinia'\nimport { computed, readonly, ref, shallowRef, toRaw, watch } from 'vue'\n\nimport {\n  SIDEBAR_MIN_WIDTH,\n  SIDE_TOOLBAR_WIDTH\n} from '@/constants/splitterConstants'\nimport { useTelemetry } from '@/platform/telemetry'\nimport type {\n  AgentPanelCloseSource,\n  AgentPanelOpenedMetadata\n} from '@/platform/telemetry/types'\nimport type { ComfyWorkflow } from '@/platform/workflow/management/stores/comfyWorkflow'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { api } from '@/scripts/api'\n\nimport type {\n  CreditTransitionNoticeEvent,\n  CreditTransitionNoticeState\n} from './creditTransitionNoticeState'\nimport { reduceCreditTransitionNotice } from './creditTransitionNoticeState'\n\nconst PANEL_MIN_WIDTH = 420\nconst PANEL_MAX_WIDTH = 960\nconst OPEN_STORAGE_KEY = 'Comfy.AgentPanel.open'\nconst DISCOVERED_STORAGE_KEY = 'Comfy.AgentPanel.discovered'\n\ntype TargetTracking =\n  | { mode: 'uninitialized' }\n  | { mode: 'following' }\n  | { mode: 'restoring' }\n  | { mode: 'retained'; workflow: ComfyWorkflow }\n  | {\n      mode: 'retained'\n      workflow: null\n      closedPath?: never\n      unavailable?: never\n    }\n  | {\n      mode: 'retained'\n      workflow: null\n      closedPath: string\n      unavailable?: never\n    }\n  | {\n      mode: 'retained'\n      workflow: null\n      closedPath?: never\n      unavailable: true\n    }\n\nexport type AgentPanelView =\n  | { screen: 'chat' }\n  | {\n      screen: 'history'\n      previousThreadId: string | null\n      selection:\n        | { status: 'idle' }\n        | { status: 'loading' | 'failed'; id: string }\n    }\n\nexport const useAgentPanelStore = defineStore('agentPanel', () => {\n  const enabled = ref(false)\n  const consentAccepted = ref(false)\n  // writeDefaults false: no storage key planted for flag-off users.\n  const isOpen = useLocalStorage(OPEN_STORAGE_KEY, false, {\n    writeDefaults: false\n  })\n  /** Whether the panel has ever been shown to this user, on any visit. */\n  const hasEverOpened = useLocalStorage(DISCOVERED_STORAGE_KEY, false, {\n    writeDefaults: false\n  })\n  const gateSettled = ref(false)\n  const view = shallowRef<AgentPanelView>({ screen: 'chat' })\n  const flagsSettled = computed(() => api.serverFeatureFlagsSettled.value)\n  const maximized = ref(false)\n  const draggedWidth = ref(PANEL_MIN_WIDTH)\n  /**\n   * Width the workspace left of the panel needs: the side toolbar, plus the\n   * sidebar when one is open. The layout that owns those keeps it current, so\n   * the panel gives way the moment it would meet the sidebar.\n   */\n  const reservedWorkspaceWidth = ref(SIDE_TOOLBAR_WIDTH + SIDEBAR_MIN_WIDTH)\n  const reportedExhaustionIdentity = ref<string | null>(null)\n  const reportedFreeUseExposure = ref(false)\n  const reportedFreeUseImpression = ref(false)\n  const creditTransitionNotice = shallowRef<CreditTransitionNoticeState | null>(\n    null\n  )\n  const dismissedSelectionSignature = ref<string | null>(null)\n  const workflowStore = useWorkflowStore()\n  const targetTracking = ref<TargetTracking>({ mode: 'uninitialized' })\n  const followsVisibleWorkflow = computed(\n    () => targetTracking.value.mode === 'following'\n  )\n  const selectedWorkflow = computed(() => {\n    const target = targetTracking.value\n    if (target.mode === 'following') return workflowStore.activeWorkflow\n    return target.mode === 'retained' ? target.workflow : null\n  })\n  const targetUnavailable = computed(\n    () =>\n      targetTracking.value.mode === 'retained' &&\n      targetTracking.value.workflow === null &&\n      targetTracking.value.unavailable === true\n  )\n  const canRestoreWorkflow = computed(\n    () => targetTracking.value.mode === 'restoring'\n  )\n\n  function beginWorkflowRestoration(): void {\n    targetTracking.value = { mode: 'restoring' }\n  }\n\n  function interruptHistorySelection(): void {\n    if (\n      view.value.screen === 'history' &&\n      view.value.selection.status === 'loading'\n    )\n      view.value = {\n        ...view.value,\n        selection: { status: 'failed', id: view.value.selection.id }\n      }\n  }\n\n  function initializeTargetTracking(hasThread: boolean): void {\n    if (targetTracking.value.mode !== 'uninitialized') return\n    targetTracking.value = { mode: hasThread ? 'restoring' : 'following' }\n  }\n\n  function retainWorkflowTarget(): void {\n    if (targetTracking.value.mode === 'retained') return\n    setWorkflowTarget(selectedWorkflow.value)\n  }\n\n  function startFollowingVisibleWorkflow(): void {\n    targetTracking.value = { mode: 'following' }\n  }\n\n  function setWorkflowTarget(workflow: ComfyWorkflow | null): void {\n    targetTracking.value =\n      workflow === null\n        ? { mode: 'retained', workflow: null }\n        : { mode: 'retained', workflow }\n  }\n\n  function markWorkflowTargetUnavailable(): void {\n    targetTracking.value = {\n      mode: 'retained',\n      workflow: null,\n      unavailable: true\n    }\n  }\n\n  function detachClosedTarget(workflow: ComfyWorkflow): void {\n    targetTracking.value = workflow.isTemporary\n      ? { mode: 'retained', workflow: null }\n      : { mode: 'retained', workflow: null, closedPath: workflow.path }\n  }\n\n  // Only a retained target can become detached. A following target belongs to\n  // the editor, including its replacement when the visible tab closes.\n  watch(\n    () => [targetTracking.value, ...workflowStore.openWorkflows],\n    () => {\n      const target = targetTracking.value\n      if (target.mode !== 'retained') return\n      if (target.workflow !== null) {\n        if (!workflowStore.openWorkflows.includes(target.workflow))\n          detachClosedTarget(target.workflow)\n      } else if (\n        workflowStore.openWorkflows.some(\n          ({ path }) => path === target.closedPath\n        )\n      )\n        setWorkflowTarget(null)\n    }\n  )\n\n  function isRetainedTarget(workflow: ComfyWorkflow): boolean {\n    const target = targetTracking.value\n    if (target.mode !== 'retained') return false\n    return target.workflow === null\n      ? target.closedPath === workflow.path\n      : toRaw(target.workflow) === toRaw(workflow)\n  }\n\n  function followClosedTargetRename(oldPath: string, newPath: string): void {\n    const target = targetTracking.value\n    if (\n      target.mode === 'retained' &&\n      target.workflow === null &&\n      target.closedPath === oldPath\n    )\n      targetTracking.value = {\n        mode: 'retained',\n        workflow: null,\n        closedPath: newPath\n      }\n  }\n\n  workflowStore.$onAction(({ name, args, after }) => {\n    if (name === 'deleteWorkflow') {\n      const [workflow] = args\n      if (!workflow.isTemporary)\n        after(() => {\n          if (isRetainedTarget(workflow)) markWorkflowTargetUnavailable()\n        })\n    } else if (name === 'renameWorkflow') {\n      const [workflow] = args\n      const oldPath = workflow.path\n      after(() => followClosedTargetRename(oldPath, workflow.path))\n    }\n  })\n\n  let openedAt: number | null = null\n  // Guards the pagehide teardown report below: true once this open epoch has\n  // reported a close, so a bfcache-frozen page that fires pagehide again\n  // (background/resume/close) can't emit a second overlapping duration for\n  // the same openedAt. A fresh epoch (open(), or the watcher below) resets it.\n  let teardownReported = false\n\n  function startOpenEpoch(): void {\n    openedAt = Date.now()\n    teardownReported = false\n    reportedFreeUseExposure.value = false\n    reportedFreeUseImpression.value = false\n  }\n\n  const isVisible = computed(() => enabled.value && isOpen.value)\n\n  watch(isVisible, (visible) => {\n    if (!visible) {\n      openedAt = null\n      return\n    }\n    hasEverOpened.value = true\n    if (openedAt !== null) return\n    startOpenEpoch()\n    useTelemetry()?.trackAgentPanelOpened({ source: 'restored' })\n  })\n\n  const { width: windowWidth } = useWindowSize()\n\n  /**\n   * Falls below `PANEL_MIN_WIDTH` when the window leaves less room than that.\n   * A panel narrower than its minimum still beats one that leaves the window.\n   */\n  const maxWidth = computed(() =>\n    clamp(windowWidth.value - reservedWorkspaceWidth.value, 0, PANEL_MAX_WIDTH)\n  )\n\n  /**\n   * The rendered width. Narrowing the window clamps it; widening restores the\n   * width the user asked for, so a maximized panel never leaves the viewport.\n   */\n  const width = computed(() =>\n    Math.min(\n      maxWidth.value,\n      maximized.value ? PANEL_MAX_WIDTH : draggedWidth.value\n    )\n  )\n  const requestedWidth = computed(() =>\n    maximized.value ? PANEL_MAX_WIDTH : draggedWidth.value\n  )\n  const isOverlay = computed(\n    () =>\n      windowWidth.value <= requestedWidth.value + reservedWorkspaceWidth.value\n  )\n\n  const isMaximized = computed(() => maximized.value)\n\n  function open(\n    source: AgentPanelOpenedMetadata['source'] = 'topbar_button'\n  ): void {\n    if (isOpen.value) return\n    isOpen.value = true\n    startOpenEpoch()\n    useTelemetry()?.trackAgentPanelOpened({ source })\n  }\n\n  function close(source: AgentPanelCloseSource): void {\n    if (!isOpen.value) return\n    isOpen.value = false\n    const openDurationMs = openedAt === null ? null : Date.now() - openedAt\n    openedAt = null\n    useTelemetry()?.trackAgentPanelClosed({\n      source,\n      open_duration_ms: openDurationMs\n    })\n  }\n\n  function suppressRestoredOpen(): void {\n    if (!isOpen.value || isVisible.value) return\n    isOpen.value = false\n    openedAt = null\n  }\n\n  // pagehide is the reliable teardown signal on tab close/reload and even on\n  // some mobile Safari backgrounding, where nothing else is guaranteed to\n  // fire again. Reports the open duration without mutating isOpen/local\n  // storage, so the localStorage-backed restore-on-reload behaviour\n  // (FE-1284/PM-648) is untouched.\n  useEventListener(window, 'pagehide', () => {\n    if (!isVisible.value || openedAt === null || teardownReported) return\n    teardownReported = true\n    useTelemetry()?.trackAgentPanelClosed({\n      source: 'pagehide',\n      open_duration_ms: Date.now() - openedAt\n    })\n  })\n\n  // A bfcache restore resumes this same frozen interval rather than starting\n  // a new one, so the pagehide report above already closed it out. Starting\n  // a fresh interval here keeps a later close()/pagehide measuring only the\n  // time since resume, instead of re-including (and double counting) the\n  // span already reported.\n  useEventListener(window, 'pageshow', (event: PageTransitionEvent) => {\n    if (!event.persisted || !isVisible.value) return\n    openedAt = Date.now()\n    teardownReported = false\n  })\n\n  function toggle(): void {\n    if (isOpen.value) close('topbar_button')\n    else open()\n  }\n\n  function setReservedWorkspaceWidth(px: number): void {\n    reservedWorkspaceWidth.value = Math.max(0, px)\n  }\n\n  function setWidth(px: number): void {\n    maximized.value = false\n    draggedWidth.value = clamp(px, PANEL_MIN_WIDTH, PANEL_MAX_WIDTH)\n  }\n\n  function toggleMaximize(): void {\n    maximized.value = !maximized.value\n    if (!maximized.value) draggedWidth.value = PANEL_MIN_WIDTH\n  }\n\n  function dispatchCreditTransitionNotice(\n    event: CreditTransitionNoticeEvent\n  ): boolean {\n    const before = creditTransitionNotice.value\n    creditTransitionNotice.value = reduceCreditTransitionNotice(before, event)\n    return creditTransitionNotice.value !== before\n  }\n\n  function observeAgentScopedFunds(\n    identity: string,\n    scopedHasFunds: boolean\n  ): void {\n    dispatchCreditTransitionNotice({\n      type: 'scopedRead',\n      identity,\n      scopedHasFunds\n    })\n  }\n\n  function claimCreditTransitionNoticeImpression(identity: string): boolean {\n    return dispatchCreditTransitionNotice({\n      type: 'shown',\n      identity\n    })\n  }\n\n  function dismissCreditTransitionNotice(identity: string): void {\n    dispatchCreditTransitionNotice({ type: 'dismissed', identity })\n  }\n\n  return {\n    enabled,\n    consentAccepted,\n    isOpen,\n    isVisible,\n    hasEverOpened,\n    gateSettled,\n    view,\n    interruptHistorySelection,\n    flagsSettled,\n    reportedExhaustionIdentity,\n    reportedFreeUseExposure,\n    reportedFreeUseImpression,\n    creditTransitionNotice: readonly(creditTransitionNotice),\n    observeAgentScopedFunds,\n    claimCreditTransitionNoticeImpression,\n    dismissCreditTransitionNotice,\n    width,\n    requestedWidth,\n    isOverlay,\n    isMaximized,\n    dismissedSelectionSignature,\n    open,\n    targetTracking,\n    followsVisibleWorkflow,\n    initializeTargetTracking,\n    retainWorkflowTarget,\n    startFollowingVisibleWorkflow,\n    selectedWorkflow,\n    targetUnavailable,\n    markWorkflowTargetUnavailable,\n    canRestoreWorkflow,\n    beginWorkflowRestoration,\n    setWorkflowTarget,\n    toggle,\n    close,\n    suppressRestoredOpen,\n    setWidth,\n    setReservedWorkspaceWidth,\n    toggleMaximize\n  }\n})\n","import type { ReadOnlyRect } from '@/lib/litegraph/src/interfaces'\nimport type { LGraphCanvas } from '@/lib/litegraph/src/litegraph'\nimport { useAgentPanelStore } from '@/workbench/extensions/agent/stores/agent/agentPanelStore'\n\nexport function visibleCanvasViewport(\n  canvas: Pick<LGraphCanvas, 'ds'>\n): ReadOnlyRect {\n  const panel = useAgentPanelStore()\n  const [width, height] = canvas.ds.getViewportSize()\n  const coveredWidth = panel.isVisible ? panel.width : 0\n  const uncoveredWidth = width - coveredWidth\n  return [0, 0, uncoveredWidth > 0 ? uncoveredWidth : width, height]\n}\n","import { uniq } from 'es-toolkit'\n\nimport type { LGraphNode, Positionable } from '@/lib/litegraph/src/litegraph'\nimport { LGraphEventMode, Reroute } from '@/lib/litegraph/src/litegraph'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { collectFromNodes } from '@/utils/graphTraversalUtil'\nimport { isLGraphGroup, isLGraphNode } from '@/utils/litegraphUtil'\n\n/**\n * Composable for handling selected LiteGraph items filtering and operations.\n * This provides utilities for working with selected items on the canvas,\n * including filtering out items that should not be included in selection operations.\n */\nexport function useSelectedLiteGraphItems() {\n  const canvasStore = useCanvasStore()\n\n  /**\n   * Items that should not show in the selection overlay are ignored.\n   * @param item - The item to check.\n   * @returns True if the item should be ignored, false otherwise.\n   */\n  const isIgnoredItem = (item: Positionable): boolean => {\n    return item instanceof Reroute\n  }\n\n  /**\n   * Filter out items that should not show in the selection overlay.\n   * @param items - The Set of items to filter.\n   * @returns The filtered Set of items.\n   */\n  const filterSelectableItems = (\n    items: Set<Positionable>\n  ): Set<Positionable> => {\n    const result = new Set<Positionable>()\n    for (const item of items) {\n      if (!isIgnoredItem(item)) {\n        result.add(item)\n      }\n    }\n    return result\n  }\n\n  /**\n   * Get the filtered selected items from the canvas.\n   * @returns The filtered Set of selected items.\n   */\n  const getSelectableItems = (): Set<Positionable> => {\n    const { selectedItems } = canvasStore.getCanvas()\n    return filterSelectableItems(selectedItems)\n  }\n\n  /**\n   * Check if there are any selectable items.\n   * @returns True if there are selectable items, false otherwise.\n   */\n  const hasSelectableItems = (): boolean => {\n    return getSelectableItems().size > 0\n  }\n\n  /**\n   * Check if there are multiple selectable items.\n   * @returns True if there are multiple selectable items, false otherwise.\n   */\n  const hasMultipleSelectableItems = (): boolean => {\n    return getSelectableItems().size > 1\n  }\n\n  /**\n   * The top-level selected nodes from the canonical selection set.\n   * Shallow — does NOT expand subgraph children, unlike {@link getSelectedNodes}.\n   * Mode toggles use this so they apply to the selected subgraph node, not its\n   * descendants. Returns `[]` when the canvas is not yet available, preserving\n   * the prior null-tolerance for callers wired to early-firing commands.\n   */\n  const getSelectedNodesShallow = (): LGraphNode[] =>\n    uniq(\n      [...(canvasStore.canvas?.selectedItems ?? [])].flatMap((item) => {\n        if (isLGraphNode(item)) return [item]\n        if (isLGraphGroup(item)) return [...item.children].filter(isLGraphNode)\n        return []\n      })\n    )\n\n  /**\n   * Get only the selected nodes (LGraphNode instances) from the canvas.\n   * This filters out other types of selected items like groups or reroutes.\n   * If a selected node is a subgraph, this also includes all nodes within it.\n   * @returns Array of selected LGraphNode instances and their descendants.\n   */\n  const getSelectedNodes = (): LGraphNode[] => {\n    const nodeArray = getSelectedNodesShallow()\n\n    const hasSubgraphs = nodeArray.some(\n      (node) => node.isSubgraphNode() && node.subgraph\n    )\n    if (!hasSubgraphs) return nodeArray\n\n    return collectFromNodes(nodeArray)\n  }\n\n  /**\n   * True iff every selected node is in `mode`. Mirrors the predicate used by\n   * {@link toggleSelectedNodesMode} so labels match the toggle's effect.\n   * An empty selection returns `false` (no node is in the mode).\n   */\n  const areAllSelectedNodesInMode = (mode: LGraphEventMode): boolean => {\n    const selectedNodeArray = getSelectedNodesShallow()\n    return (\n      selectedNodeArray.length > 0 &&\n      selectedNodeArray.every((node) => node.mode === mode)\n    )\n  }\n\n  /**\n   * Toggle the execution mode of all selected nodes\n   *\n   * - If any nodes are not already the specified node mode → all are set to specified mode\n   * - Otherwise → set all nodes to ALWAYS\n   *\n   * @param mode - The LGraphEventMode to toggle to (e.g., NEVER for mute, BYPASS for bypass)\n   */\n  const toggleSelectedNodesMode = (mode: LGraphEventMode): void => {\n    const selectedNodeArray = getSelectedNodesShallow()\n    const newModeForSelectedNode = areAllSelectedNodesInMode(mode)\n      ? LGraphEventMode.ALWAYS\n      : mode\n\n    for (const selectedNode of selectedNodeArray)\n      selectedNode.mode = newModeForSelectedNode\n  }\n\n  return {\n    isIgnoredItem,\n    filterSelectableItems,\n    getSelectableItems,\n    hasSelectableItems,\n    hasMultipleSelectableItems,\n    getSelectedNodes,\n    areAllSelectedNodesInMode,\n    toggleSelectedNodesMode\n  }\n}\n","import { api } from '@/scripts/api'\nimport type { UserDataFullInfo } from '@/platform/remote/comfyui/types'\n\n/**\n * Sync entities from the API to the entityByPath map.\n * @param dir The directory to sync from\n * @param entityByPath The map to sync to\n * @param createEntity A function to create an entity from a file\n * @param updateEntity A function to update an entity from a file\n * @param exclude A function to exclude an entity\n * @param beforeDelete Called before deleting an entity that no longer exists\n * remotely. Return false to keep the entity.\n */\nexport async function syncEntities<T>(\n  dir: string,\n  entityByPath: Record<string, T>,\n  createEntity: (file: UserDataFullInfo & { path: string }) => T,\n  updateEntity: (entity: T, file: UserDataFullInfo & { path: string }) => void,\n  exclude: (file: T) => boolean = () => false,\n  beforeDelete: (entity: T, path: string) => boolean = () => true\n) {\n  const files = (await api.listUserDataFullInfo(dir)).map((file) => ({\n    ...file,\n    path: dir ? `${dir}/${file.path}` : file.path\n  }))\n\n  for (const file of files) {\n    const existingEntity = entityByPath[file.path]\n\n    if (!existingEntity) {\n      // New entity, add it to the map\n      entityByPath[file.path] = createEntity(file)\n    } else if (exclude(existingEntity)) {\n      // Entity has been excluded, skip it\n      continue\n    } else {\n      // Entity has been modified, update its properties\n      updateEntity(existingEntity, file)\n    }\n  }\n\n  // Remove entities that no longer exist\n  for (const [path, entity] of Object.entries(entityByPath)) {\n    if (exclude(entity)) continue\n    if (!files.some((file) => file.path === path)) {\n      if (!beforeDelete(entity, path)) continue\n      delete entityByPath[path]\n    }\n  }\n}\n","import { defineStore } from 'pinia'\nimport { computed, ref } from 'vue'\n\nimport type { UserDataFullInfo } from '@/platform/remote/comfyui/types'\nimport { api } from '@/scripts/api'\nimport type { TreeExplorerNode } from '@/types/treeExplorerTypes'\nimport { getPathDetails } from '@/utils/formatUtil'\nimport { syncEntities } from '@/utils/syncUtil'\nimport { buildTree } from '@/utils/treeUtil'\n\n/**\n * Normalizes a timestamp value that may be either a number (milliseconds)\n * or an ISO 8601 string (from Go's time.Time JSON serialization) into\n * a consistent millisecond timestamp.\n */\nfunction normalizeTimestamp(value: number | string): number {\n  if (typeof value === 'string') {\n    const ms = new Date(value).getTime()\n    return Number.isNaN(ms) ? Date.now() : ms\n  }\n  return value\n}\n\n/**\n * Represents a file in the user's data directory.\n */\nexport class UserFile {\n  /**\n   * Various path components.\n   * Example:\n   * - path: 'dir/file.txt'\n   * - directory: 'dir'\n   * - fullFilename: 'file.txt'\n   * - filename: 'file'\n   * - suffix: 'txt'\n   */\n  directory: string\n  fullFilename: string\n  filename: string\n  suffix: string | null\n\n  isLoading: boolean = false\n  content: string | null = null\n  originalContent: string | null = null\n\n  constructor(\n    /**\n     * Path relative to ComfyUI/user/ directory.\n     */\n    public path: string,\n    /**\n     * Last modified timestamp.\n     */\n    public lastModified: number,\n    /**\n     * File size in bytes. -1 for temporary files.\n     */\n    public size: number\n  ) {\n    const details = getPathDetails(path)\n    this.directory = details.directory\n    this.fullFilename = details.fullFilename\n    this.filename = details.filename\n    this.suffix = details.suffix\n  }\n\n  updatePath(newPath: string) {\n    const details = getPathDetails(newPath)\n    this.path = newPath\n    this.directory = details.directory\n    this.fullFilename = details.fullFilename\n    this.filename = details.filename\n    this.suffix = details.suffix\n  }\n\n  static createTemporary(path: string): UserFile {\n    return new UserFile(path, Date.now(), -1)\n  }\n\n  get isTemporary() {\n    return this.size === -1\n  }\n\n  get isPersisted() {\n    return !this.isTemporary\n  }\n\n  get key(): string {\n    return this.path\n  }\n\n  get isLoaded() {\n    return this.content !== null\n  }\n\n  get isModified() {\n    return this.content !== this.originalContent\n  }\n\n  /**\n   * Loads the file content from the remote storage.\n   */\n  async load({\n    force = false\n  }: { force?: boolean } = {}): Promise<LoadedUserFile> {\n    if (this.isTemporary || (!force && this.isLoaded))\n      return this as LoadedUserFile\n\n    this.isLoading = true\n    const resp = await api.getUserData(this.path)\n    if (resp.status !== 200) {\n      throw new Error(\n        `Failed to load file '${this.path}': ${resp.status} ${resp.statusText}`\n      )\n    }\n    this.content = await resp.text()\n    this.originalContent = this.content\n    this.isLoading = false\n    return this as LoadedUserFile\n  }\n\n  /**\n   * Unloads the file content from memory\n   */\n  unload(): void {\n    this.content = null\n    this.originalContent = null\n    this.isLoading = false\n  }\n\n  async saveAs(newPath: string): Promise<UserFile> {\n    const tempFile = this.isTemporary ? this : UserFile.createTemporary(newPath)\n    tempFile.content = this.content\n    await tempFile.save()\n    return tempFile\n  }\n\n  /**\n   * Saves the file to the remote storage.\n   * @param force Whether to force the save even if the file is not modified.\n   */\n  async save({ force = false }: { force?: boolean } = {}): Promise<UserFile> {\n    if (this.isPersisted && !this.isModified && !force) return this\n\n    const resp = await api.storeUserData(this.path, this.content, {\n      overwrite: this.isPersisted,\n      throwOnError: true,\n      full_info: true\n    })\n\n    // Note: Backend supports full_info=true feature after\n    // https://github.com/comfyanonymous/ComfyUI/pull/5446\n    const updatedFile = (await resp.json()) as string | UserDataFullInfo\n    if (typeof updatedFile === 'object') {\n      this.lastModified = normalizeTimestamp(updatedFile.modified)\n      this.size = updatedFile.size\n    }\n    this.originalContent = this.content\n    return this\n  }\n\n  async delete(): Promise<void> {\n    if (this.isTemporary) return\n\n    const resp = await api.deleteUserData(this.path)\n    if (resp.status !== 204) {\n      throw new Error(\n        `Failed to delete file '${this.path}': ${resp.status} ${resp.statusText}`\n      )\n    }\n  }\n\n  async rename(newPath: string): Promise<UserFile> {\n    if (this.isTemporary) {\n      this.updatePath(newPath)\n      return this\n    }\n\n    const resp = await api.moveUserData(this.path, newPath)\n    if (resp.status !== 200) {\n      throw new Error(\n        `Failed to rename file '${this.path}': ${resp.status} ${resp.statusText}`\n      )\n    }\n    this.updatePath(newPath)\n    // Note: Backend supports full_info=true feature after\n    // https://github.com/comfyanonymous/ComfyUI/pull/5446\n    const updatedFile = (await resp.json()) as string | UserDataFullInfo\n    if (typeof updatedFile === 'object') {\n      this.lastModified = normalizeTimestamp(updatedFile.modified)\n      this.size = updatedFile.size\n    }\n    return this\n  }\n}\n\ninterface LoadedUserFile extends UserFile {\n  isLoaded: true\n  originalContent: string\n  content: string\n}\n\nexport const useUserFileStore = defineStore('userFile', () => {\n  const userFilesByPath = ref<Record<string, UserFile>>({})\n\n  const userFiles = computed(() => Object.values(userFilesByPath.value))\n  const modifiedFiles = computed(() =>\n    userFiles.value.filter((file: UserFile) => file.isModified)\n  )\n  const loadedFiles = computed(() =>\n    userFiles.value.filter((file: UserFile) => file.isLoaded)\n  )\n\n  const fileTree = computed<TreeExplorerNode<UserFile>>(() =>\n    buildTree<UserFile>(userFiles.value, (userFile: UserFile) =>\n      userFile.path.split('/')\n    )\n  )\n\n  /**\n   * Syncs the files in the given directory with the API.\n   * @param dir The directory to sync.\n   */\n  const syncFiles = async (dir: string = '') => {\n    await syncEntities(\n      dir,\n      userFilesByPath.value,\n      (file) => new UserFile(file.path, file.modified, file.size),\n      (existingFile, file) => {\n        existingFile.lastModified = file.modified\n        existingFile.size = file.size\n        existingFile.unload()\n      }\n    )\n  }\n\n  return {\n    userFiles,\n    modifiedFiles,\n    loadedFiles,\n    fileTree,\n    syncFiles\n  }\n})\n","import { markRaw } from 'vue'\n\nimport { assert } from '@/base/assert'\nimport type { ExecutedWsMessage } from '@/platform/remote/comfyui/execution/types'\nimport { UserFile } from '@/stores/userFileStore'\nimport type { ComfyWorkflowJSON } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport type { MissingModelCandidate } from '@/platform/missingModel/types'\nimport type { MissingMediaCandidate } from '@/platform/missingMedia/types'\nimport type { MissingNodeType } from '@/platform/nodeReplacement/types'\nimport type { NodeLocatorId } from '@/types/nodeIdentification'\nimport type { SerializedNodeId } from '@/types/nodeId'\nimport type { AppMode } from '@/utils/appMode'\nimport type { WidgetId } from '@/types/widgetId'\nimport { generateUUID } from '@/utils/formatUtil'\n\nexport interface InputWidgetConfig {\n  height?: number\n  description?: string\n}\n\ntype LinearInputId = WidgetId | NodeLocatorId | SerializedNodeId\ntype LinearOutputNodeId = SerializedNodeId\nexport type LinearInput = [LinearInputId, string, InputWidgetConfig?]\n\nexport interface LinearData {\n  inputs: LinearInput[]\n  outputs: LinearOutputNodeId[]\n}\n\nexport interface PendingWarnings {\n  missingNodeTypes?: MissingNodeType[]\n  missingModelCandidates?: MissingModelCandidate[]\n  missingMediaCandidates?: MissingMediaCandidate[]\n}\n\n/**\n * Undo/redo history of a loaded workflow. Implemented by\n * `ChangeTracker` in `@/scripts/changeTracker`; declared here so the\n * workflow model stays independent of the canvas runtime.\n */\nexport interface WorkflowChangeTracker {\n  workflow: ComfyWorkflow\n  initialState: ComfyWorkflowJSON\n  activeState: ComfyWorkflowJSON\n  undoQueue: ComfyWorkflowJSON[]\n  redoQueue: ComfyWorkflowJSON[]\n  changeCount: number\n  _restoringState: boolean\n  ds?: { scale: number; offset: [number, number] }\n  nodeOutputs?: Partial<Record<string, ExecutedWsMessage['output']>>\n  reset(state?: ComfyWorkflowJSON): void\n  store(): void\n  deactivate(): void\n  prepareForSave(): void\n  restore(): void\n  updateModified(previousState?: ComfyWorkflowJSON): void\n  captureCanvasState(): void\n  checkState(): void\n  updateState(\n    source: ComfyWorkflowJSON[],\n    target: ComfyWorkflowJSON[]\n  ): Promise<void>\n  undo(): Promise<void>\n  redo(): Promise<void>\n  undoRedo(e: KeyboardEvent, selectOnly?: boolean): Promise<true | undefined>\n  beforeChange(): void\n  afterChange(): void\n}\n\ninterface WorkflowDraft {\n  data: string\n  updatedAt: number\n}\n\n/**\n * Runtime services a workflow needs while loading and saving. Registered by\n * the workflow store so this module does not depend on the change tracker,\n * draft persistence, or settings.\n */\nexport interface WorkflowRuntime {\n  createChangeTracker(\n    workflow: ComfyWorkflow,\n    initialState: ComfyWorkflowJSON\n  ): WorkflowChangeTracker\n  getDraft(path: string): WorkflowDraft | null\n  removeDraft(path: string): void\n  markDraftUsed(path: string): void\n  isDraftPersistenceEnabled(): boolean\n  promptSave(workflow: ComfyWorkflow): Promise<string | null>\n}\n\nlet registeredRuntime: WorkflowRuntime | null = null\n\nexport function registerWorkflowRuntime(runtime: WorkflowRuntime): void {\n  registeredRuntime = runtime\n}\n\nfunction workflowRuntime(): WorkflowRuntime {\n  assert(\n    registeredRuntime,\n    'Workflow runtime not registered; import the workflow store first'\n  )\n  return registeredRuntime\n}\n\n/** i18n keys for the dialog shown when a workflow is saved without a name. */\nexport interface SaveNamePrompt {\n  title: string\n  message: string\n}\n\nexport class ComfyWorkflow extends UserFile {\n  static readonly basePath: string = 'workflows/'\n  readonly tintCanvasBg?: string\n  /** Unique, stable identity for this workflow instance in the current session. */\n  readonly instanceId = generateUUID()\n\n  /**\n   * The change tracker for the workflow. Non-reactive raw object.\n   */\n  changeTracker: WorkflowChangeTracker | null = null\n  /**\n   * Whether the workflow has been modified comparing to the initial state.\n   */\n  _isModified: boolean = false\n  /**\n   * Warnings deferred from load time, shown when the workflow is first focused.\n   */\n  pendingWarnings: PendingWarnings | null = null\n  /**\n   * Initial app mode derived from the serialized workflow (extra.linearMode).\n   * - `undefined`: not yet resolved (first load hasn't happened)\n   * - `null`: resolved, but no mode was set (never builder-saved)\n   * - `AppMode`: resolved to a specific mode\n   */\n  initialMode: AppMode | null | undefined = undefined\n  /**\n   * Current app mode set by the user during the session.\n   * Takes precedence over initialMode when present.\n   */\n  activeMode: AppMode | null = null\n  shareId?: string\n  legacyId?: string\n  readonly saveNamePrompt: SaveNamePrompt = {\n    title: 'workflowService.saveWorkflow',\n    message: 'workflowService.enterFilenamePrompt'\n  }\n  /**\n   * @param options The path, modified, and size of the workflow.\n   * Note: path is the full path, including the 'workflows/' prefix.\n   */\n  constructor(options: { path: string; modified: number; size: number }) {\n    super(options.path, options.modified, options.size)\n  }\n\n  override get key() {\n    return this.path.substring(ComfyWorkflow.basePath.length)\n  }\n\n  get activeState(): ComfyWorkflowJSON | null {\n    return this.changeTracker?.activeState ?? null\n  }\n\n  get initialState(): ComfyWorkflowJSON | null {\n    return this.changeTracker?.initialState ?? null\n  }\n\n  override get isLoaded(): boolean {\n    return this.changeTracker !== null\n  }\n\n  override get isModified(): boolean {\n    return this._isModified\n  }\n\n  override set isModified(value: boolean) {\n    this._isModified = value\n  }\n\n  /**\n   * Load the workflow content from remote storage. Directly returns the loaded\n   * workflow if the content is already loaded.\n   *\n   * @param force Whether to force loading the content even if it is already loaded.\n   * @returns this\n   */\n  override async load({ force = false }: { force?: boolean } = {}): Promise<\n    this & LoadedComfyWorkflow\n  > {\n    if (!force && this.isLoaded && this.changeTracker) {\n      return this as this & LoadedComfyWorkflow\n    }\n\n    const runtime = workflowRuntime()\n    let draft =\n      !force && runtime.isDraftPersistenceEnabled()\n        ? runtime.getDraft(this.path)\n        : null\n    let draftState: ComfyWorkflowJSON | null = null\n    let draftContent: string | null = null\n\n    if (draft) {\n      if (draft.updatedAt < this.lastModified) {\n        runtime.removeDraft(this.path)\n        draft = null\n      }\n    }\n\n    if (draft) {\n      try {\n        draftState = JSON.parse(draft.data)\n        draftContent = draft.data\n      } catch (err) {\n        console.warn('Failed to parse workflow draft, clearing it', err)\n        runtime.removeDraft(this.path)\n      }\n    }\n\n    await super.load({ force })\n\n    if (this.originalContent == null) {\n      throw new Error(\n        `[ASSERT] Workflow content should be loaded for '${this.path}'`\n      )\n    }\n    if (this.originalContent.trim().length === 0) {\n      throw new Error(`Workflow content is empty for '${this.path}'`)\n    }\n\n    const initialState = JSON.parse(this.originalContent)\n    this.changeTracker = markRaw(\n      runtime.createChangeTracker(this, initialState)\n    )\n    if (draftState && draftContent) {\n      this.changeTracker.activeState = draftState\n      this.content = draftContent\n      this._isModified = true\n      // Saved-workflow draft overlay path; direct persisted-draft restores\n      // are touched in workflowDraftStoreV2.loadDraft().\n      runtime.markDraftUsed(this.path)\n    }\n    return this as this & LoadedComfyWorkflow\n  }\n\n  override unload(): void {\n    this.changeTracker = null\n    this.activeMode = null\n    super.unload()\n  }\n\n  override async save() {\n    this.content = JSON.stringify(this.activeState)\n    // Force save to ensure the content is updated in remote storage incase\n    // the isModified state is screwed by changeTracker.\n    const ret = await super.save({ force: true })\n    this.changeTracker?.reset()\n    this.isModified = false\n    workflowRuntime().removeDraft(this.path)\n    return ret\n  }\n\n  /**\n   * Save the workflow as a new file.\n   * @param path The path to save the workflow to. Note: with 'workflows/' prefix.\n   * @returns this\n   */\n  override async saveAs(path: string) {\n    this.content = JSON.stringify(this.activeState)\n    const result = await super.saveAs(path)\n    workflowRuntime().removeDraft(path)\n    return result\n  }\n\n  async promptSave(): Promise<string | null> {\n    return workflowRuntime().promptSave(this)\n  }\n}\n\nexport interface LoadedComfyWorkflow extends ComfyWorkflow {\n  isLoaded: true\n  originalContent: string\n  content: string\n  changeTracker: WorkflowChangeTracker\n  initialState: ComfyWorkflowJSON\n  activeState: ComfyWorkflowJSON\n}\n","import type { TemplateInput } from '../schemas/templateSchema'\n\nexport interface LogoInfo {\n  /** Provider name(s) matching index_logo.json. String for single, array for stacked logos. */\n  provider: string | string[]\n  /** Tailwind positioning classes */\n  position?: string\n}\n\nexport interface TemplateInfo {\n  name: string\n  io?: { inputs?: TemplateInput[] }\n  /**\n   * Optional title which is used as the fallback if the name is not in the locales dictionary.\n   */\n  title?: string\n  tutorialUrl?: string\n  mediaType: string\n  mediaSubtype: string\n  thumbnailVariant?: string\n  description: string\n  localizedTitle?: string\n  localizedDescription?: string\n  isEssential?: boolean\n  /**\n   * Whether App Mode is this template's default view, from the workflow's own\n   * `extra.linearMode`. Supplied by `templates/index.json`; absent means a node\n   * graph. Do not fall back to the `.app` filename suffix, which is wrong in\n   * both directions (see the App badge in WorkflowTemplateSelectorDialog).\n   */\n  isApp?: boolean\n  sourceModule?: string\n  tags?: string[]\n  models?: string[]\n  date?: string\n  useCase?: string\n  license?: string\n  /**\n   * Estimated VRAM requirement in bytes.\n   */\n  vram?: number\n  size?: number\n  /**\n   * Whether this template uses open source models. When false, indicates partner/API node templates.\n   */\n  openSource?: boolean\n  /**\n   * Array of custom node package IDs required for this template (from Custom Node Registry).\n   * Templates with this field will be hidden on local installations temporarily.\n   */\n  requiresCustomNodes?: string[]\n  /**\n   * Curator override applied to search relevance and the \"Recommended\" sort.\n   * Anything from -5 to 5, and an absent value, is neutral; promotion starts at\n   * 6 and demotion at -6, both saturating at a magnitude of 1000.\n   * See docs/TEMPLATE_RANKING.md.\n   */\n  searchRank?: number\n  /**\n   * Usage score based on real world usage statistics.\n   * Used for popular templates sort and for \"Recommended\" sort boost.\n   */\n  usage?: number\n  /**\n   * Manage template's visibility across different distributions by specifying which distributions it should be included on.\n   * If not specified, the template will be included on all distributions.\n   */\n  includeOnDistributions?: TemplateIncludeOnDistributionEnum[]\n  /**\n   * Logo overlays to display on the template thumbnail.\n   */\n  logos?: LogoInfo[]\n}\n\nexport enum TemplateIncludeOnDistributionEnum {\n  Cloud = 'cloud',\n  Local = 'local',\n  Desktop = 'desktop',\n  Mac = 'mac',\n  Windows = 'windows'\n}\n\nexport interface WorkflowTemplates {\n  moduleName: string\n  templates: TemplateInfo[]\n  title: string\n  localizedTitle?: string\n  category?: string\n  type?: string\n  icon?: string\n  isEssential?: boolean\n}\n\nexport interface TemplateGroup {\n  label: string\n  icon?: string\n  modules: WorkflowTemplates[]\n}\n\nexport type TemplateTypeFilter = 'all' | 'nodeGraph' | 'apps'\n","import { defineStore } from 'pinia'\n\nimport { t } from '@/i18n'\nimport { SubgraphNode } from '@/lib/litegraph/src/litegraph'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport type { LoadedComfyWorkflow } from '@/platform/workflow/management/stores/comfyWorkflow'\nimport { ComfyWorkflow } from '@/platform/workflow/management/stores/comfyWorkflow'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport type {\n  ComfyNode,\n  ComfyWorkflowJSON\n} from '@/platform/workflow/validation/schemas/workflowSchema'\nimport type { SerializedNodeId } from '@/types/nodeId'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport type { NodeError } from '@/platform/remote/comfyui/types'\nimport type {\n  ComfyNodeDef as ComfyNodeDefV1,\n  InputSpec\n} from '@/schemas/nodeDefSchema'\nimport { isCloud, isDesktop } from '@/platform/distribution/types'\nimport { TemplateIncludeOnDistributionEnum } from '@/platform/workflow/templates/types/template'\nimport { api } from '@/scripts/api'\nimport type { GlobalSubgraphData } from '@/scripts/api'\nimport { useDialogService } from '@/services/dialogService'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport { ComfyNodeDefImpl, useNodeDefStore } from '@/stores/nodeDefStore'\nimport type { UserFile } from '@/stores/userFileStore'\nimport { BLUEPRINT_TYPE_PREFIX } from '@/utils/blueprintUtils'\nimport { getErrorMessage } from '@/utils/errorUtil'\n\nasync function confirmOverwrite(name: string): Promise<boolean | null> {\n  return await useDialogService().confirm({\n    title: t('subgraphStore.overwriteBlueprintTitle'),\n    type: 'overwriteBlueprint',\n    message: t('subgraphStore.overwriteBlueprint'),\n    itemList: [name]\n  })\n}\n\nexport const useSubgraphStore = defineStore('subgraph', () => {\n  class SubgraphBlueprint extends ComfyWorkflow {\n    static override readonly basePath = 'subgraphs/'\n    override readonly tintCanvasBg = '#22227740'\n\n    hasPromptedSave: boolean = false\n\n    constructor(\n      options: { path: string; modified: number; size: number },\n      confirmFirstSave: boolean = false\n    ) {\n      super(options)\n      this.hasPromptedSave = !confirmFirstSave\n    }\n\n    validateSubgraph() {\n      if (!this.activeState?.definitions)\n        throw new Error(\n          'The root graph of a subgraph blueprint must consist of only a single subgraph node'\n        )\n      const { subgraphs } = this.activeState.definitions\n      const { nodes } = this.activeState\n      //Instanceof doesn't function as nodes are serialized\n      function isSubgraphNode(node: ComfyNode) {\n        return subgraphs.some((s) => s.id === node.type)\n      }\n      if (nodes.length == 1 && isSubgraphNode(nodes[0])) return\n      const errors: Record<SerializedNodeId, NodeError> = {}\n      //mark errors for all but first subgraph node\n      let firstSubgraphFound = false\n      for (let i = 0; i < nodes.length; i++) {\n        if (!firstSubgraphFound && isSubgraphNode(nodes[i])) {\n          firstSubgraphFound = true\n          continue\n        }\n        errors[nodes[i].id] = {\n          errors: [],\n          class_type: nodes[i].type,\n          dependent_outputs: []\n        }\n      }\n      useExecutionErrorStore().recordNodeErrors(errors)\n      useCanvasStore().getCanvas().draw(true, true)\n      throw new Error(\n        'The root graph of a subgraph blueprint must consist of only a single subgraph node'\n      )\n    }\n\n    override async save(): Promise<UserFile> {\n      this.validateSubgraph()\n      if (\n        !this.hasPromptedSave &&\n        useSettingStore().get('Comfy.Workflow.WarnBlueprintOverwrite')\n      ) {\n        if (!(await confirmOverwrite(this.filename))) return this\n        this.hasPromptedSave = true\n      }\n      // Extract metadata from subgraph.extra to workflow.extra before saving\n      this.extractMetadataToWorkflowExtra()\n      const ret = await super.save()\n      // Force reload to update initialState with saved metadata\n      registerNodeDef(await this.load({ force: true }), {\n        category: 'Subgraph Blueprints/User'\n      })\n      return ret\n    }\n\n    /**\n     * Moves all properties (except workflowRendererVersion) from subgraph.extra\n     * to workflow.extra, then removes from subgraph.extra to avoid duplication.\n     */\n    private extractMetadataToWorkflowExtra(): void {\n      if (!this.activeState) return\n      const subgraph = this.activeState.definitions?.subgraphs[0]\n      if (!subgraph?.extra) return\n\n      const sgExtra = subgraph.extra as Record<string, unknown>\n      const workflowExtra = (this.activeState.extra ??= {}) as Record<\n        string,\n        unknown\n      >\n\n      for (const key of Object.keys(sgExtra)) {\n        if (key === 'workflowRendererVersion') continue\n        workflowExtra[key] = sgExtra[key]\n        delete sgExtra[key]\n      }\n    }\n\n    override async saveAs(path: string) {\n      this.validateSubgraph()\n      this.hasPromptedSave = true\n      // Extract metadata from subgraph.extra to workflow.extra before saving\n      this.extractMetadataToWorkflowExtra()\n      const ret = await super.saveAs(path)\n      // Force reload to update initialState with saved metadata\n      registerNodeDef(await this.load({ force: true }), {\n        category: 'Subgraph Blueprints/User'\n      })\n      return ret\n    }\n    override async load({ force = false }: { force?: boolean } = {}): Promise<\n      this & LoadedComfyWorkflow\n    > {\n      if (!force && this.isLoaded) return await super.load({ force })\n      const loaded = await super.load({ force })\n      const st = loaded.activeState\n      const sg = (st.definitions?.subgraphs ?? []).find(\n        (sg) => sg.id == st.nodes[0].type\n      )\n      if (!sg)\n        throw new Error(\n          'Loaded subgraph blueprint does not contain valid subgraph'\n        )\n      sg.name = st.nodes[0].title = this.filename\n\n      // Copy blueprint metadata from workflow extra to subgraph extra\n      // so it's available when editing via canvas.subgraph.extra\n      if (st.extra) {\n        const sgExtra = (sg.extra ??= {}) as Record<string, unknown>\n        for (const [key, value] of Object.entries(st.extra)) {\n          if (key === 'workflowRendererVersion') continue\n          sgExtra[key] = value\n        }\n      }\n\n      return loaded\n    }\n    override readonly saveNamePrompt = {\n      title: 'subgraphStore.saveBlueprint',\n      message: 'subgraphStore.blueprintNamePrompt'\n    }\n    override unload(): void {\n      //Skip unloading. Even if a workflow is closed after editing,\n      //it must remain loaded in order to be added to the graph\n    }\n  }\n  const subgraphCache: Record<string, LoadedComfyWorkflow> = {}\n  const nodeDefStore = useNodeDefStore()\n  const canvasStore = useCanvasStore()\n  async function fetchSubgraphs() {\n    async function loadBlueprint(options: {\n      path: string\n      modified: number\n      size: number\n    }): Promise<void> {\n      options.path = SubgraphBlueprint.basePath + options.path\n      const bp = await new SubgraphBlueprint(options, true).load()\n      useWorkflowStore().attachWorkflow(bp)\n      registerNodeDef(bp, { category: 'Subgraph Blueprints/User' })\n    }\n    async function loadInstalledBlueprints() {\n      async function loadGlobalBlueprint([k, v]: [string, GlobalSubgraphData]) {\n        const data = await v.data\n        if (typeof data !== 'string' || data.trim().length === 0) {\n          throw new Error(\n            `Global blueprint '${v.name}' (${k}) returned empty content`\n          )\n        }\n        const path = SubgraphBlueprint.basePath + v.name + '.json'\n        const blueprint = new SubgraphBlueprint({\n          path,\n          modified: Date.now(),\n          size: -1\n        })\n        blueprint.originalContent = blueprint.content = data\n        blueprint.filename = v.name\n        useWorkflowStore().attachWorkflow(blueprint)\n        const loaded = await blueprint.load()\n        const category = v.info.category\n          ? `Subgraph Blueprints/${v.info.category}`\n          : undefined\n        registerNodeDef(\n          loaded,\n          {\n            display_name: v.name,\n            ...(category && { category }),\n            ...(v.essentials_category && {\n              essentials_category: v.essentials_category\n            }),\n            search_aliases: v.info.search_aliases,\n            isGlobal: true\n          },\n          k\n        )\n      }\n      const subgraphs = await api.getGlobalSubgraphs()\n      const currentDistribution: TemplateIncludeOnDistributionEnum = isCloud\n        ? TemplateIncludeOnDistributionEnum.Cloud\n        : isDesktop\n          ? TemplateIncludeOnDistributionEnum.Desktop\n          : TemplateIncludeOnDistributionEnum.Local\n      const filteredEntries = Object.entries(subgraphs).filter(([, v]) => {\n        if (!isCloud && (v.info.requiresCustomNodes?.length ?? 0) > 0)\n          return false\n        if (\n          (v.info.includeOnDistributions?.length ?? 0) > 0 &&\n          !v.info.includeOnDistributions!.includes(currentDistribution)\n        )\n          return false\n        return true\n      })\n      return Promise.allSettled(filteredEntries.map(loadGlobalBlueprint))\n    }\n\n    const userSubs = (\n      await api.listUserDataFullInfo(SubgraphBlueprint.basePath)\n    ).filter((f) => f.path.endsWith('.json'))\n    const [globalResult, ...userResults] = await Promise.allSettled([\n      loadInstalledBlueprints(),\n      ...userSubs.map(loadBlueprint)\n    ])\n    const globalResults =\n      globalResult.status === 'fulfilled' ? globalResult.value : []\n    const settled = [...globalResults, ...userResults]\n\n    const errors = settled.filter((i) => 'reason' in i).map((i) => i.reason)\n    errors.forEach((e) => console.error('Failed to load subgraph blueprint', e))\n    if (errors.length > 0) {\n      useToast().error(t('subgraphStore.loadFailure'), {\n        description:\n          errors.length > 3\n            ? `x${errors.length}`\n            : errors\n                .map((e) => getErrorMessage(e) ?? t('g.unknownError'))\n                .join(', ')\n      })\n    }\n  }\n  function registerNodeDef(\n    workflow: LoadedComfyWorkflow,\n    overrides: Partial<ComfyNodeDefV1> = {},\n    name: string = workflow.filename\n  ) {\n    const subgraphNode = workflow.changeTracker.initialState.nodes[0]\n    subgraphNode.inputs ??= []\n    subgraphNode.outputs ??= []\n    //NOTE: Types are cast to string. This is only used for input coloring on previews\n    const inputs = Object.fromEntries(\n      subgraphNode.inputs.map((i) => [\n        i.name,\n        [`${i.type}`, undefined] satisfies InputSpec\n      ])\n    )\n    const workflowExtra = workflow.initialState.extra\n    const description =\n      workflowExtra?.BlueprintDescription ??\n      workflow.initialState.definitions?.subgraphs[0].description ??\n      'User generated subgraph blueprint'\n    const search_aliases = workflowExtra?.BlueprintSearchAliases\n    const subgraphDefCategory =\n      workflow.initialState.definitions?.subgraphs[0]?.category\n    const subgraphDefEssentialsCategory =\n      workflow.initialState.definitions?.subgraphs[0]?.essentials_category\n    const category = subgraphDefCategory\n      ? `Subgraph Blueprints/${subgraphDefCategory}`\n      : 'Subgraph Blueprints'\n    const nodedefv1: ComfyNodeDefV1 = {\n      input: { required: inputs },\n      output: subgraphNode.outputs.map((o) => `${o.type}`),\n      output_name: subgraphNode.outputs.map((o) => o.name),\n      name: BLUEPRINT_TYPE_PREFIX + name,\n      display_name: name,\n      description,\n      category,\n      output_node: false,\n      python_module: 'blueprint',\n      search_aliases,\n      essentials_category: subgraphDefEssentialsCategory,\n      ...overrides\n    }\n    nodeDefStore.registerBlueprintNodeDef(new ComfyNodeDefImpl(nodedefv1))\n    subgraphCache[name] = workflow\n  }\n  async function publishSubgraph(providedName?: string) {\n    const canvas = canvasStore.getCanvas()\n    const subgraphNode = [...canvas.selectedItems][0]\n    if (\n      canvas.selectedItems.size !== 1 ||\n      !(subgraphNode instanceof SubgraphNode)\n    )\n      throw new TypeError('Must have single SubgraphNode selected to publish')\n\n    const { nodes = [], subgraphs = [] } = canvas._serializeItems([\n      subgraphNode\n    ])\n    if (nodes.length != 1) {\n      throw new TypeError('Must have single SubgraphNode selected to publish')\n    }\n\n    //create minimal workflow\n    const workflowData = {\n      revision: 0,\n      last_node_id: subgraphNode.id,\n      last_link_id: 0,\n      nodes,\n      links: [] as never[],\n      version: 0.4,\n      definitions: { subgraphs }\n    }\n    //prompt name\n    const name =\n      providedName ??\n      (await useDialogService().prompt({\n        title: t('subgraphStore.saveBlueprint'),\n        message: t('subgraphStore.blueprintNamePrompt'),\n        defaultValue: subgraphNode.title\n      }))\n    if (!name) return\n    if (\n      nodeDefStore.blueprintNodeDefsByName.has(BLUEPRINT_TYPE_PREFIX + name) &&\n      !(await confirmOverwrite(name))\n    )\n      //User has chosen not to overwrite.\n      return\n\n    //upload file\n    const path = SubgraphBlueprint.basePath + name + '.json'\n    const workflow = new SubgraphBlueprint({\n      path,\n      size: -1,\n      modified: Date.now()\n    })\n    workflow.originalContent = JSON.stringify(workflowData)\n    const loadedWorkflow = await workflow.load()\n    //Mark non-temporary\n    workflow.size = 1\n    await workflow.save()\n    //add to files list?\n    useWorkflowStore().attachWorkflow(loadedWorkflow)\n    useToast().success(t('subgraphStore.publishSuccess'), {\n      description: t('subgraphStore.publishSuccessMessage'),\n      duration: 4000\n    })\n  }\n  async function editBlueprint(nodeType: string) {\n    const name = nodeType.slice(BLUEPRINT_TYPE_PREFIX.length)\n    if (!(name in subgraphCache))\n      //As loading is blocked on in startup, this can likely be changed to invalid type\n      throw new Error('not yet loaded')\n    useWorkflowStore().attachWorkflow(subgraphCache[name])\n    await useWorkflowService().openWorkflow(subgraphCache[name])\n    const canvas = useCanvasStore().getCanvas()\n    if (canvas.graph && 'subgraph' in canvas.graph.nodes[0])\n      canvas.setGraph(canvas.graph.nodes[0].subgraph)\n  }\n  function getBlueprint(nodeType: string): ComfyWorkflowJSON {\n    const name = nodeType.slice(BLUEPRINT_TYPE_PREFIX.length)\n    if (!(name in subgraphCache))\n      //As loading is blocked on in startup, this can likely be changed to invalid type\n      throw new Error('not yet loaded')\n    return structuredClone(subgraphCache[name].changeTracker.initialState)\n  }\n  async function deleteBlueprint(nodeType: string) {\n    const name = nodeType.slice(BLUEPRINT_TYPE_PREFIX.length)\n    if (!(name in subgraphCache)) throw new Error('not yet loaded')\n\n    if (isGlobalBlueprint(name)) {\n      useToast().warning(t('subgraphStore.cannotDeleteGlobal'), {\n        duration: 4000\n      })\n      return\n    }\n\n    if (\n      !(await useDialogService().confirm({\n        title: t('subgraphStore.confirmDeleteTitle'),\n        type: 'delete',\n        message: t('subgraphStore.confirmDelete'),\n        itemList: [name]\n      }))\n    )\n      return\n\n    await subgraphCache[name].delete()\n    delete subgraphCache[name]\n    nodeDefStore.removeBlueprintNodeDef(nodeType)\n  }\n  function isSubgraphBlueprint(\n    workflow: unknown\n  ): workflow is SubgraphBlueprint {\n    return workflow instanceof SubgraphBlueprint\n  }\n\n  function isGlobalBlueprint(name: string): boolean {\n    const nodeDef = nodeDefStore.blueprintNodeDefsByName.get(\n      BLUEPRINT_TYPE_PREFIX + name\n    )\n    return nodeDef !== undefined && nodeDef.isGlobal === true\n  }\n\n  function isUserBlueprint(nodeType?: string): boolean {\n    if (!nodeType?.startsWith(BLUEPRINT_TYPE_PREFIX)) return false\n    const name = nodeType.slice(BLUEPRINT_TYPE_PREFIX.length)\n    return name in subgraphCache && !isGlobalBlueprint(name)\n  }\n\n  return {\n    deleteBlueprint,\n    editBlueprint,\n    fetchSubgraphs,\n    getBlueprint,\n    isGlobalBlueprint,\n    isSubgraphBlueprint,\n    isUserBlueprint,\n    publishSubgraph\n  }\n})\n","import { useSelectedLiteGraphItems } from '@/composables/canvas/useSelectedLiteGraphItems'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { t } from '@/i18n'\nimport { SubgraphNode } from '@/lib/litegraph/src/litegraph'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useNodeOutputStore } from '@/stores/nodeOutputStore'\nimport { useSubgraphStore } from '@/stores/subgraphStore'\n\n/**\n * Composable for handling subgraph-related operations\n */\nexport function useSubgraphOperations() {\n  const { getSelectedNodes } = useSelectedLiteGraphItems()\n  const canvasStore = useCanvasStore()\n  const workflowStore = useWorkflowStore()\n  const nodeOutputStore = useNodeOutputStore()\n  const subgraphStore = useSubgraphStore()\n  const toast = useToast()\n\n  const convertToSubgraph = () => {\n    const canvas = canvasStore.getCanvas()\n    const graph = canvas.subgraph ?? canvas.graph\n    if (!graph) {\n      return null\n    }\n\n    const res = graph.convertToSubgraph(canvas.selectedItems)\n    const { node } = res\n    canvas.select(node)\n    // Trigger change tracking\n    workflowStore.activeWorkflow?.changeTracker.captureCanvasState()\n  }\n\n  const doUnpack = (\n    subgraphNodes: SubgraphNode[],\n    skipMissingNodes: boolean\n  ) => {\n    const canvas = canvasStore.getCanvas()\n    const graph = canvas.subgraph ?? canvas.graph\n    if (!graph) return\n\n    let changed = false\n    let refused = false\n    for (const subgraphNode of subgraphNodes) {\n      if (!graph.unpackSubgraph(subgraphNode, { skipMissingNodes })) {\n        refused = true\n        continue\n      }\n      nodeOutputStore.revokeSubgraphPreviews(subgraphNode, graph)\n      changed = true\n    }\n    if (refused) {\n      toast.error(t('g.error'), {\n        description: t('g.subgraphUnpackFailed')\n      })\n    }\n    if (changed) {\n      workflowStore.activeWorkflow?.changeTracker.captureCanvasState()\n    }\n  }\n\n  const unpackSubgraph = () => {\n    const canvas = canvasStore.getCanvas()\n    const graph = canvas.subgraph ?? canvas.graph\n\n    if (!graph) {\n      return\n    }\n\n    const selectedItems = Array.from(canvas.selectedItems)\n    const subgraphNodes = selectedItems.filter(\n      (item): item is SubgraphNode => item instanceof SubgraphNode\n    )\n\n    if (subgraphNodes.length === 0) {\n      return\n    }\n    doUnpack(subgraphNodes, true)\n  }\n\n  const addSubgraphToLibrary = async () => {\n    const selectedItems = Array.from(canvasStore.selectedItems)\n    const subgraphNodes = selectedItems.filter(\n      (item): item is SubgraphNode => item instanceof SubgraphNode\n    )\n    if (subgraphNodes.length !== 1) {\n      return\n    }\n    await subgraphStore.publishSubgraph()\n  }\n\n  const isSubgraphSelected = (): boolean => {\n    const selectedItems = Array.from(canvasStore.selectedItems)\n    return selectedItems.some((item) => item instanceof SubgraphNode)\n  }\n\n  const hasSelectableNodes = (): boolean => {\n    return getSelectedNodes().length > 0\n  }\n\n  return {\n    convertToSubgraph,\n    unpackSubgraph,\n    addSubgraphToLibrary,\n    isSubgraphSelected,\n    hasSelectableNodes\n  }\n}\n","/**\n * Chain multiple callbacks together.\n *\n * @param originalCallback - The original callback to chain.\n * @param callbacks - The callbacks to chain.\n * @returns A new callback that chains the original callback with the callbacks.\n */\nexport function useChainCallback<O, T>(\n  originalCallback: T | undefined,\n  ...callbacks: NonNullable<T> extends (this: O, ...args: infer P) => unknown\n    ? ((this: O, ...args: P) => void)[]\n    : never\n) {\n  type Args = NonNullable<T> extends (...args: infer P) => unknown ? P : never\n  type Ret = NonNullable<T> extends (...args: unknown[]) => infer R ? R : never\n\n  return function (this: O, ...args: Args) {\n    if (typeof originalCallback === 'function') {\n      ;(originalCallback as (this: O, ...args: Args) => Ret).call(this, ...args)\n    }\n    for (const callback of callbacks) {\n      callback.call(this, ...args)\n    }\n  } as (this: O, ...args: Args) => Ret\n}\n","/**\n * Wheel events whose browser default would break the editing experience.\n * On macOS trackpads:\n *   - `ctrl/meta + wheel` (pinch-zoom) triggers page-level zoom, which\n *     pushes fixed-position UI (e.g. ComfyActionbar) off-screen with no\n *     recovery short of a page reload.\n *   - Horizontal-dominant wheel (two-finger horizontal swipe) triggers\n *     back/forward navigation, which leaves the workflow.\n *\n * Equal `|deltaX| == |deltaY|` (including idle 0/0 frames between meaningful\n * trackpad samples) intentionally falls on the false branch so native\n * vertical scroll wins on a tie.\n *\n * Components that intercept wheel events should suppress the default for\n * these gestures even when they otherwise let the browser scroll natively.\n */\nexport const isCanvasGestureWheel = (event: WheelEvent): boolean =>\n  event.ctrlKey ||\n  event.metaKey ||\n  Math.abs(event.deltaX) > Math.abs(event.deltaY)\n","import { computed } from 'vue'\n\nimport {\n  isMiddleButtonEvent,\n  isMiddleButtonHeld,\n  isMiddlePointerInput\n} from '@/base/pointerUtils'\nimport { isCanvasGestureWheel } from '@/base/wheelGestures'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\n\n/**\n * Composable for handling canvas interactions from Vue components.\n * This provides a unified way to forward events to the LiteGraph canvas.\n */\nexport function useCanvasInteractions() {\n  const settingStore = useSettingStore()\n  const canvasStore = useCanvasStore()\n\n  const isStandardNavMode = computed(\n    () => settingStore.get('Comfy.Canvas.NavigationMode') === 'standard'\n  )\n\n  /**\n   * Whether Vue node components should handle pointer events.\n   * Returns false when canvas is in read-only/panning mode (e.g., space key held for panning).\n   */\n  const shouldHandleNodePointerEvents = computed(() => !canvasStore.isReadOnly)\n\n  /**\n   * Returns true if the wheel event target is inside an element that should\n   * capture wheel events AND that element (or a descendant) currently has focus.\n   *\n   * This allows two-finger panning to continue over inputs until the user has\n   * actively focused the widget, at which point the widget can consume scroll.\n   */\n  const wheelCapturedByFocusedElement = (event: WheelEvent): boolean => {\n    const target = event.target as HTMLElement | null\n    const captureElement = target?.closest('[data-capture-wheel=\"true\"]')\n    const active = document.activeElement\n\n    return !!(captureElement && active && captureElement.contains(active))\n  }\n\n  /**\n   * Forward to canvas when the event is not consumed by a focused widget,\n   * or when it is a canvas gesture (which must override widget consumption\n   * to prevent destructive browser defaults).\n   */\n  const shouldForwardWheelEvent = (event: WheelEvent): boolean =>\n    !wheelCapturedByFocusedElement(event) || isCanvasGestureWheel(event)\n\n  /**\n   * Handles wheel events from UI components that should be forwarded to canvas\n   * when appropriate (e.g., Ctrl+wheel for zoom, two-finger pan in standard\n   * mode; all wheel events in legacy mode).\n   */\n  const handleWheel = (event: WheelEvent) => {\n    if (!shouldForwardWheelEvent(event)) return\n\n    // In standard mode, only canvas gestures (zoom/pan) are forwarded;\n    // vertical wheel falls through so the document/widget scrolls normally.\n    // The re-check is intentional and NOT redundant with shouldForwardWheelEvent:\n    // that function also returns true for unfocused vertical wheel (its\n    // `!wheelCapturedByFocusedElement` branch), which here must stay native.\n    if (isStandardNavMode.value) {\n      if (isCanvasGestureWheel(event)) forwardEventToCanvas(event)\n      return\n    }\n\n    // In legacy mode, all forwardable wheel events go to canvas for zoom/pan.\n    forwardEventToCanvas(event)\n  }\n\n  /**\n   * Handles pointer events from media elements that should potentially\n   * be forwarded to canvas (e.g., space+drag for panning)\n   */\n  const forwardMiddlePointerIfNeeded = (\n    event: PointerEvent,\n    isMiddleInput: (event: PointerEvent) => boolean\n  ) => {\n    if (isMiddleInput(event)) {\n      forwardEventToCanvas(event)\n      return true\n    }\n\n    return false\n  }\n\n  const handleLeftButtonReadOnlyPointer = (event: PointerEvent) => {\n    if (canvasStore.canvas?.read_only && event.buttons === 1) {\n      event.preventDefault()\n      event.stopPropagation()\n      forwardEventToCanvas(event)\n    }\n  }\n\n  const handlePointerDown = (event: PointerEvent) => {\n    if (forwardMiddlePointerIfNeeded(event, isMiddlePointerInput)) return\n    handleLeftButtonReadOnlyPointer(event)\n  }\n\n  const handlePointerMove = (event: PointerEvent) => {\n    if (forwardMiddlePointerIfNeeded(event, isMiddleButtonHeld)) return\n    handleLeftButtonReadOnlyPointer(event)\n  }\n\n  const handlePointerUp = (event: PointerEvent) => {\n    if (forwardMiddlePointerIfNeeded(event, isMiddleButtonEvent)) return\n    handleLeftButtonReadOnlyPointer(event)\n  }\n\n  /**\n   * Forwards an event to the LiteGraph canvas\n   */\n  const forwardEventToCanvas = (\n    event: WheelEvent | PointerEvent | MouseEvent\n  ) => {\n    // Honor wheel capture only when the element is focused\n    if (event instanceof WheelEvent && !shouldForwardWheelEvent(event)) return\n\n    const canvasEl = canvasStore.canvas?.canvas\n    if (!canvasEl) return\n    event.preventDefault()\n    event.stopPropagation()\n\n    if (event instanceof WheelEvent) {\n      const { clientX, clientY, deltaX, deltaY, ctrlKey, metaKey, shiftKey } =\n        event\n      canvasEl.dispatchEvent(\n        new WheelEvent('wheel', {\n          clientX,\n          clientY,\n          deltaX,\n          deltaY,\n          ctrlKey,\n          metaKey,\n          shiftKey\n        })\n      )\n      return\n    }\n\n    if (event instanceof PointerEvent) {\n      canvasEl.dispatchEvent(new PointerEvent(event.type, event))\n      return\n    }\n\n    canvasEl.dispatchEvent(new MouseEvent(event.type, event))\n  }\n\n  return {\n    handleWheel,\n    handlePointerDown,\n    handlePointerMove,\n    handlePointerUp,\n    forwardEventToCanvas,\n    shouldHandleNodePointerEvents\n  }\n}\n","import { toRaw } from 'vue'\nimport type { Component } from 'vue'\n\nimport { useChainCallback } from '@/composables/functional/useChainCallback'\n// LegacyWidget is imported from its own module, not the barrel: the barrel\n// exports it after SubgraphNode, so a litegraph-internal importer of this file\n// would hit its TDZ. LGraphNode/LiteGraph must stay barrel-sourced — a direct\n// LGraphNode import re-triggers the LGraph<->Subgraph cycle.\nimport { LGraphNode, LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport { wasWidgetRefused } from '@/lib/litegraph/src/node/widgetsView'\nimport type {\n  IBaseWidget,\n  IWidgetOptions\n} from '@/lib/litegraph/src/types/widgets'\nimport { LegacyWidget } from '@/lib/litegraph/src/widgets/LegacyWidget'\nimport type { InputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport { useDomWidgetStore } from '@/stores/domWidgetStore'\nimport { generateUUID } from '@/utils/formatUtil'\n\nexport interface BaseDOMWidget<\n  V extends object | string = object | string\n> extends IBaseWidget<V, string, DOMWidgetOptions<V>> {\n  // ICustomWidget properties\n  type: string\n  options: DOMWidgetOptions<V>\n  value: V\n  callback?: (value: V) => void\n\n  // BaseDOMWidget properties\n  /** The unique ID of the widget. */\n  readonly id: string\n  /** The node that the widget belongs to. */\n  readonly node: LGraphNode\n  /** Whether the widget is visible. */\n  isVisible(): boolean\n  /** The margin of the widget. */\n  margin: number\n}\n\n/**\n * A DOM widget that wraps a custom HTML element as a litegraph widget.\n */\nexport interface DOMWidget<\n  T extends HTMLElement,\n  V extends object | string\n> extends BaseDOMWidget<V> {\n  element: T\n  /**\n   * @deprecated Legacy property used by some extensions for customtext\n   * (textarea) widgets. Use {@link element} instead as it provides the same\n   * functionality and works for all DOMWidget types.\n   */\n  inputEl?: T\n}\n\n/**\n * Additional props that can be passed to component widgets.\n * These are in addition to the standard props that are always provided:\n * - modelValue: The widget's value (handled by v-model)\n * - widget: Reference to the widget instance\n * - onUpdate:modelValue: The update handler for v-model\n */\ntype ComponentWidgetCustomProps = Record<string, unknown>\n\n/**\n * Standard props that are handled separately by DomWidget.vue and should be\n * omitted when defining custom props for component widgets\n */\nexport type ComponentWidgetStandardProps =\n  | 'modelValue'\n  | 'widget'\n  | 'onUpdate:modelValue'\n\n/**\n * A DOM widget that wraps a Vue component as a litegraph widget.\n */\nexport interface ComponentWidget<\n  V extends object | string,\n  P extends ComponentWidgetCustomProps = ComponentWidgetCustomProps\n> extends BaseDOMWidget<V> {\n  readonly component: Component\n  readonly inputSpec: InputSpec\n  readonly props?: P\n}\n\nexport interface DOMWidgetOptions<\n  V extends object | string\n> extends IWidgetOptions {\n  /**\n   * Whether to render a placeholder rectangle when zoomed out.\n   */\n  hideOnZoom?: boolean\n  selectOn?: string[]\n  onHide?: (widget: BaseDOMWidget<V>) => void\n  getValue?: () => V\n  setValue?: (value: V) => void\n  getMinHeight?: () => number\n  getMaxHeight?: () => number\n  getHeight?: () => string | number\n  onDraw?: (widget: BaseDOMWidget<V>) => void\n  margin?: number\n  /**\n   * @deprecated Use `afterResize` instead. This callback is a legacy API\n   * that fires before resize happens, but it is no longer supported. Now it\n   * fires after resize happens.\n   * The resize logic has been upstreamed to litegraph in\n   * https://github.com/Comfy-Org/ComfyUI_frontend/pull/2557\n   */\n  beforeResize?: (this: BaseDOMWidget<V>, node: LGraphNode) => void\n  afterResize?: (this: BaseDOMWidget<V>, node: LGraphNode) => void\n}\n\nexport const isDOMWidget = <T extends HTMLElement, V extends object | string>(\n  widget: IBaseWidget\n): widget is DOMWidget<T, V> => 'element' in widget && !!widget.element\n\nexport const isComponentWidget = <V extends object | string>(\n  widget: IBaseWidget\n): widget is ComponentWidget<V> => 'component' in widget && !!widget.component\n\ntype BaseDOMWidgetInit<V extends object | string> = Pick<\n  BaseDOMWidget<V>,\n  'node' | 'name' | 'type' | 'options'\n>\n\ntype DOMWidgetInit<\n  T extends HTMLElement,\n  V extends object | string\n> = BaseDOMWidgetInit<V> & Pick<DOMWidget<T, V>, 'element'>\n\ntype ComponentWidgetInit<\n  V extends object | string,\n  P extends ComponentWidgetCustomProps\n> = Omit<BaseDOMWidgetInit<V>, 'type'> & {\n  type?: string\n} & Pick<ComponentWidget<V, P>, 'component' | 'inputSpec' | 'props'>\n\nabstract class BaseDOMWidgetImpl<V extends object | string>\n  extends LegacyWidget<IBaseWidget<V, string, DOMWidgetOptions<V>>>\n  implements BaseDOMWidget<V>\n{\n  static readonly DEFAULT_MARGIN = 10\n  declare callback?: (value: V) => void\n\n  readonly id: string\n\n  constructor(obj: BaseDOMWidgetInit<V>) {\n    const { node, name, type, options } = obj\n    super({ y: 0, name, type, options }, node)\n\n    this.id = generateUUID()\n  }\n\n  override get value(): V {\n    return this.options.getValue?.() ?? ('' as V)\n  }\n\n  override set value(v: V) {\n    this.options.setValue?.(v)\n    this.callback?.(this.value)\n  }\n\n  get margin(): number {\n    return this.options.margin ?? BaseDOMWidgetImpl.DEFAULT_MARGIN\n  }\n\n  isVisible(): boolean {\n    return (\n      !this.hidden && !this.computedDisabled && this.node.isWidgetVisible(this)\n    )\n  }\n\n  override draw(\n    ctx: CanvasRenderingContext2D,\n    _node: LGraphNode,\n    widget_width: number,\n    y: number,\n    widget_height: number,\n    lowQuality?: boolean\n  ): void {\n    const isVisible = this.isVisible()\n\n    if (this.options.hideOnZoom && lowQuality && isVisible) {\n      // Draw a placeholder rectangle\n      const originalFillStyle = ctx.fillStyle\n      ctx.beginPath()\n      ctx.fillStyle = LiteGraph.WIDGET_BGCOLOR\n      ctx.rect(\n        this.margin,\n        y + this.margin,\n        widget_width - this.margin * 2,\n        (this.computedHeight ?? widget_height) - 2 * this.margin\n      )\n      ctx.fill()\n      ctx.fillStyle = originalFillStyle\n    } else {\n      if (!isVisible) {\n        this.options.onDraw?.(this)\n        return\n      }\n    }\n    this.options.onDraw?.(this)\n  }\n\n  override onRemove(): void {\n    useDomWidgetStore().unregisterWidget(this.id)\n  }\n}\n\nexport class DOMWidgetImpl<T extends HTMLElement, V extends object | string>\n  extends BaseDOMWidgetImpl<V>\n  implements DOMWidget<T, V>\n{\n  override readonly element: T\n\n  constructor(obj: DOMWidgetInit<T, V>) {\n    super(obj)\n    this.element = obj.element\n  }\n\n  override createCopyForNode(node: LGraphNode): this {\n    const Widget = this.constructor as new (init: DOMWidgetInit<T, V>) => this\n    const cloned = new Widget({\n      node,\n      name: this.name,\n      type: this.type,\n      element: this.element,\n      options: this.options\n    })\n    cloned.value = this.value\n    // Preserve the Y position from the original widget to maintain proper positioning\n    // when widgets are promoted through subgraph nesting\n    cloned.y = this.y\n    return cloned\n  }\n\n  /** Extract DOM widget size info */\n  override computeLayoutSize() {\n    if (this.type === 'hidden') {\n      return {\n        minHeight: 0,\n        maxHeight: 0,\n        minWidth: 0\n      }\n    }\n\n    const styles = getComputedStyle(this.element)\n    let minHeight =\n      this.options.getMinHeight?.() ??\n      parseInt(styles.getPropertyValue('--comfy-widget-min-height'))\n    const maxHeight =\n      this.options.getMaxHeight?.() ??\n      parseInt(styles.getPropertyValue('--comfy-widget-max-height'))\n\n    const prefHeight: string | number =\n      this.options.getHeight?.() ??\n      styles.getPropertyValue('--comfy-widget-height')\n\n    const isPercentageHeight =\n      typeof prefHeight === 'string' && prefHeight.endsWith('%')\n    if (!isPercentageHeight && isNaN(minHeight)) {\n      minHeight =\n        typeof prefHeight === 'number' ? prefHeight : parseInt(prefHeight)\n    }\n\n    return {\n      minHeight: isNaN(minHeight) ? 50 : minHeight,\n      maxHeight: isNaN(maxHeight) ? undefined : maxHeight,\n      minWidth: 0\n    }\n  }\n}\n\nexport class ComponentWidgetImpl<\n  V extends object | string,\n  P extends ComponentWidgetCustomProps = ComponentWidgetCustomProps\n>\n  extends BaseDOMWidgetImpl<V>\n  implements ComponentWidget<V, P>\n{\n  readonly component: Component\n  readonly inputSpec: InputSpec\n  readonly props?: P\n\n  constructor(obj: ComponentWidgetInit<V, P>) {\n    super({\n      type: 'custom',\n      ...obj\n    })\n    this.component = obj.component\n    this.inputSpec = obj.inputSpec\n    this.props = obj.props\n  }\n\n  override createCopyForNode(node: LGraphNode): this {\n    const Widget = this.constructor as new (\n      init: ComponentWidgetInit<V, P>\n    ) => this\n    const cloned = new Widget({\n      node,\n      name: this.name,\n      type: this.type,\n      component: this.component,\n      inputSpec: this.inputSpec,\n      props: this.props,\n      options: this.options\n    })\n    cloned.value = this.value\n    // Preserve the Y position from the original widget to maintain proper positioning\n    // when widgets are promoted through subgraph nesting\n    cloned.y = this.y\n    return cloned\n  }\n\n  override computeLayoutSize() {\n    const minHeight = this.options.getMinHeight?.() ?? 50\n    const maxHeight = this.options.getMaxHeight?.()\n    return {\n      minHeight,\n      maxHeight,\n      minWidth: 0\n    }\n  }\n\n  override serializeValue(): V {\n    return toRaw(this.value)\n  }\n}\n\nexport const addWidget = (node: LGraphNode, widget: BaseDOMWidget) => {\n  node.addCustomWidget(widget)\n\n  if (wasWidgetRefused(node, widget)) return\n\n  if (node.graph) {\n    useDomWidgetStore().registerWidget(widget)\n  }\n\n  node.onAdded = useChainCallback(node.onAdded, () => {\n    if (wasWidgetRefused(node, widget)) return\n    useDomWidgetStore().registerWidget(widget)\n  })\n\n  node.onRemoved = useChainCallback(node.onRemoved, () => {\n    widget.onRemove?.()\n  })\n\n  node.onResize = useChainCallback(node.onResize, () => {\n    widget.options.beforeResize?.call(widget, node)\n    widget.options.afterResize?.call(widget, node)\n  })\n}\n\nLGraphNode.prototype.addDOMWidget = function <\n  T extends HTMLElement,\n  V extends object | string\n>(\n  this: LGraphNode,\n  name: string,\n  type: string,\n  element: T,\n  options: DOMWidgetOptions<V> = {}\n): DOMWidget<T, V> {\n  const widget = new DOMWidgetImpl({\n    node: this,\n    name,\n    type,\n    element,\n    options: { hideOnZoom: true, ...options }\n  })\n  // Note: Before `LGraphNode.configure` is called, `this.id` is always `-1`.\n  addWidget(this, widget as unknown as BaseDOMWidget)\n\n  // Workaround for https://github.com/Comfy-Org/ComfyUI_frontend/issues/2493\n  // Some custom nodes are explicitly expecting getter and setter of `value`\n  // property to be on instance instead of prototype.\n  Object.defineProperty(widget, 'value', {\n    get(this: DOMWidgetImpl<T, V>): V {\n      return this.options.getValue?.() ?? ('' as V)\n    },\n    set(this: DOMWidgetImpl<T, V>, v: V) {\n      this.options.setValue?.(v)\n      this.callback?.(this.value)\n    }\n  })\n\n  return widget\n}\n","import { useChainCallback } from '@/composables/functional/useChainCallback'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { useCanvasInteractions } from '@/renderer/core/canvas/useCanvasInteractions'\nimport { isDOMWidget } from '@/scripts/domWidget'\n\nexport const ANIM_PREVIEW_WIDGET = '$$comfy_animation_preview'\n\n/**\n * Composable for handling animated image previews in nodes\n */\nexport function useNodeAnimatedImage() {\n  /**\n   * Shows animated image preview for a node\n   * @param node The graph node to show the preview for\n   */\n  function showAnimatedPreview(node: LGraphNode) {\n    if (!node.imgs?.length) return\n    if (!node.widgets) return\n\n    const widgetIdx = node.widgets.findIndex(\n      (w) => w.name === ANIM_PREVIEW_WIDGET\n    )\n\n    node.imgs[0].classList.value = 'block size-full object-contain'\n    if (widgetIdx > -1) {\n      // Replace content in existing widget\n      const widget = node.widgets[widgetIdx]\n      if (!isDOMWidget(widget)) return\n      widget.element.replaceChildren(node.imgs[0])\n    } else {\n      // Create new widget\n      const element = document.createElement('div')\n      element.appendChild(node.imgs[0])\n      const widget = node.addDOMWidget(ANIM_PREVIEW_WIDGET, 'img', element, {\n        hideOnZoom: false,\n        surfaces: { canvas: 'shown', vueNode: 'never', panel: 'never' }\n      })\n      node.overIndex = 0\n\n      // Add event listeners for canvas interactions\n      const {\n        handleWheel,\n        handlePointerDown,\n        handlePointerMove,\n        handlePointerUp,\n        forwardEventToCanvas\n      } = useCanvasInteractions()\n      node.imgs[0].style.pointerEvents = 'none'\n      const controller = new AbortController()\n      const { signal } = controller\n      element.addEventListener('wheel', handleWheel, { signal })\n      element.addEventListener('pointermove', handlePointerMove, { signal })\n      element.addEventListener('pointerup', handlePointerUp, { signal })\n      element.addEventListener(\n        'pointerdown',\n        (e) =>\n          e.button !== 2 ? handlePointerDown(e) : forwardEventToCanvas(e),\n        { capture: true, signal }\n      )\n\n      widget.onRemove = useChainCallback(widget.onRemove, () => {\n        controller.abort()\n      })\n      widget.serialize = false\n      widget.serializeValue = () => undefined\n    }\n  }\n\n  /**\n   * Removes animated image preview from a node\n   * @param node The graph node to remove the preview from\n   */\n  function removeAnimatedPreview(node: LGraphNode) {\n    if (!node.widgets) return\n\n    const widgetIdx = node.widgets.findIndex(\n      (w) => w.name === ANIM_PREVIEW_WIDGET\n    )\n\n    if (widgetIdx > -1) {\n      node.widgets[widgetIdx].onRemove?.()\n      node.widgets.splice(widgetIdx, 1)\n    }\n  }\n\n  return {\n    showAnimatedPreview,\n    removeAnimatedPreview\n  }\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\n\nimport { useApp } from '@/scripts/appInstance'\nimport { $el } from './utils'\n\nexport function calculateImageGrid(\n  imgs: Pick<HTMLImageElement, 'naturalWidth' | 'naturalHeight'>[],\n  dw: number,\n  dh: number\n): {\n  cellWidth: number\n  cellHeight: number\n  cols: number\n  rows: number\n  shiftX: number\n} {\n  let best = 0\n  const w = imgs[0].naturalWidth\n  const h = imgs[0].naturalHeight\n  const numImages = imgs.length\n\n  let cellWidth = 0\n  let cellHeight = 0\n  let cols = 0\n  let rows = 0\n  let shiftX = 0\n  // compact style\n  for (let c = 1; c <= numImages; c++) {\n    const r = Math.ceil(numImages / c)\n    const cW = dw / c\n    const cH = dh / r\n    const scaleX = cW / w\n    const scaleY = cH / h\n\n    const scale = Math.min(scaleX, scaleY, 1)\n    const imageW = w * scale\n    const imageH = h * scale\n    const area = imageW * imageH * numImages\n\n    if (area > best) {\n      best = area\n      cellWidth = imageW\n      cellHeight = imageH\n      cols = c\n      rows = r\n      shiftX = c * ((cW - imageW) / 2)\n    }\n  }\n\n  return { cellWidth, cellHeight, cols, rows, shiftX }\n}\n\n/** @knipIgnoreUnusedButUsedByCustomNodes */\nexport function createImageHost(node: LGraphNode) {\n  const el = $el('div.comfy-img-preview')\n  let currentImgs: HTMLImageElement[] | undefined\n  let first = true\n\n  function updateSize() {\n    if (currentImgs) {\n      let elH = el.clientHeight\n      if (first) {\n        first = false\n        // On first run, if we are small then grow a bit\n        if (elH < 190) {\n          elH = 190\n        }\n        el.style.setProperty('--comfy-widget-min-height', elH.toString())\n      } else {\n        el.style.setProperty('--comfy-widget-min-height', null)\n      }\n\n      const nw = node.size[0]\n      const { cellWidth, cellHeight } = calculateImageGrid(\n        currentImgs,\n        nw - 20,\n        elH\n      )\n      el.style.setProperty('--comfy-img-preview-width', `${cellWidth}px`)\n      el.style.setProperty('--comfy-img-preview-height', `${cellHeight}px`)\n    }\n  }\n  return {\n    el,\n    getCurrentImage() {\n      return currentImgs?.[0]\n    },\n    updateImages(imgs: HTMLImageElement[]) {\n      if (imgs !== currentImgs) {\n        if (currentImgs == null) {\n          requestAnimationFrame(() => {\n            updateSize()\n          })\n        }\n        el.replaceChildren(...imgs)\n        currentImgs = imgs\n        node.onResize?.(node.size)\n        node.graph?.setDirtyCanvas(true, true)\n      }\n    },\n    getHeight() {\n      updateSize()\n    },\n    onDraw() {\n      // Element from point uses a hittest find elements so we need to toggle pointer events\n      el.style.pointerEvents = 'all'\n      const over = document.elementFromPoint(\n        useApp().canvas.mouse[0],\n        useApp().canvas.mouse[1]\n      )\n      el.style.pointerEvents = 'none'\n\n      if (!over) return\n      // Set the overIndex so Open Image etc work\n      const idx =\n        over instanceof HTMLImageElement\n          ? (currentImgs?.indexOf(over) ?? -1)\n          : -1\n      node.overIndex = idx\n    }\n  }\n}\n","import { appendCloudResParam } from '@/platform/distribution/cloudPreviewUtil'\nimport { parseAnnotatedPath } from '@/utils/createAnnotatedPath'\n\nconst GRID_THUMBNAIL_PREVIEW_FORMAT = 'webp;75'\n\n/**\n * Converts a full-resolution `/api/view` image URL into a lightweight\n * thumbnail URL for small on-node grid cells: server-resized on cloud (`res`)\n * and re-encoded to a compact format on every backend (`preview`). Non-view\n * URLs, SVGs (the server cannot rasterize them into a preview), and URLs that\n * already request a preview are returned unchanged.\n */\nexport function getGridThumbnailUrl(url: string): string {\n  if (!url) return url\n  let parsed: URL\n  try {\n    parsed = new URL(url, window.location.origin)\n  } catch {\n    return url\n  }\n  if (!parsed.pathname.endsWith('/view')) return url\n\n  const { searchParams } = parsed\n  const filename = searchParams.get('filename') ?? undefined\n  const isSvg = !!filename && filename.toLowerCase().endsWith('.svg')\n  appendCloudResParam(searchParams, filename)\n  if (!isSvg && !searchParams.has('preview'))\n    searchParams.set('preview', GRID_THUMBNAIL_PREVIEW_FORMAT)\n\n  return url.startsWith('http')\n    ? parsed.toString()\n    : `${parsed.pathname}${parsed.search}`\n}\n\n/**\n * Parses an image widget value like \"subfolder/filename [type]\" into its parts.\n */\nexport function parseImageWidgetValue(raw: string): {\n  filename: string\n  subfolder: string\n  type: string\n} {\n  const { filepath, rootFolder: type } = parseAnnotatedPath(raw)\n  let value = filepath\n  let subfolder = ''\n  const slashIndex = value.lastIndexOf('/')\n  if (slashIndex !== -1) {\n    subfolder = value.slice(0, slashIndex)\n    value = value.slice(slashIndex + 1)\n  }\n  return { filename: value, subfolder, type }\n}\n\nexport const is_all_same_aspect_ratio = (imgs: HTMLImageElement[]): boolean => {\n  if (!imgs.length || imgs.length === 1) return true\n\n  const ratio = imgs[0].naturalWidth / imgs[0].naturalHeight\n\n  for (let i = 1; i < imgs.length; i++) {\n    const this_ratio = imgs[i].naturalWidth / imgs[i].naturalHeight\n    if (ratio != this_ratio) return false\n  }\n\n  return true\n}\n\nexport const fitDimensionsToNodeWidth = (\n  width: number,\n  height: number,\n  nodeWidth: number,\n  minHeight: number = 64\n): { minHeight: number; minWidth: number } => {\n  const intrinsicAspectRatio = width / height\n  if (!intrinsicAspectRatio || isNaN(intrinsicAspectRatio))\n    return { minHeight: 0, minWidth: 0 }\n\n  // Set min. height s.t. image spans node's x-axis while maintaining aspect ratio\n  const minWidth = nodeWidth\n  const calculatedHeight = Math.max(minWidth / intrinsicAspectRatio, minHeight)\n\n  return { minHeight: calculatedHeight, minWidth }\n}\n","import { BaseWidget, LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport type { CanvasPointer, LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type {\n  IBaseWidget,\n  IWidgetOptions\n} from '@/lib/litegraph/src/types/widgets'\nimport type { DrawWidgetOptions } from '@/lib/litegraph/src/widgets/BaseWidget'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport type { InputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport { useApp } from '@/scripts/appInstance'\nimport { calculateImageGrid } from '@/scripts/ui/imagePreview'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\nimport { is_all_same_aspect_ratio } from '@/utils/imageUtil'\n\n/**\n * Workaround for Chrome GPU bug:\n * When Chrome is maximized with GPU acceleration and high DPR, calling\n * drawImage(canvas) + drawImage(img) in the same frame causes severe\n * performance degradation (FPS drops to 2-10, memory spikes ~18GB).\n *\n * Solution: Defer image rendering using queueMicrotask to separate\n * the two drawImage calls into different tasks.\n *\n * Note: As tested, requestAnimationFrame delays rendering to the next frame,\n * causing visible image flickering. queueMicrotask executes within the same\n * frame, avoiding flicker while still separating the drawImage calls.\n */\nlet deferredImageRenders: Array<() => void> = []\nlet deferredRenderScheduled = false\n\nfunction scheduleDeferredImageRender() {\n  if (deferredRenderScheduled) return\n  deferredRenderScheduled = true\n\n  queueMicrotask(() => {\n    const renders = deferredImageRenders\n    deferredImageRenders = []\n    deferredRenderScheduled = false\n\n    for (const render of renders) {\n      render()\n    }\n  })\n}\n\nconst TWO_PI = Math.PI * 2\nconst SPINNER_ARC_LENGTH = Math.PI * 1.5\n\nfunction renderUploadSpinner(\n  ctx: CanvasRenderingContext2D,\n  node: LGraphNode,\n  shiftY: number,\n  computedHeight: number | undefined\n) {\n  const dw = node.size[0]\n  const dh = computedHeight ?? 220\n  const centerX = dw / 2\n  const centerY = shiftY + dh / 2\n  const radius = 16\n  const angle = ((Date.now() % 1000) / 1000) * TWO_PI\n\n  ctx.save()\n  ctx.strokeStyle = LiteGraph.NODE_TEXT_COLOR\n  ctx.lineWidth = 3\n  ctx.lineCap = 'round'\n  ctx.beginPath()\n  ctx.arc(centerX, centerY, radius, angle, angle + SPINNER_ARC_LENGTH)\n  ctx.stroke()\n  ctx.restore()\n\n  // Schedule next frame to keep spinner animating continuously.\n  // Only runs while node.isUploading is true (checked by caller).\n  node.graph?.setDirtyCanvas(true)\n}\n\nconst renderPreview = (\n  ctx: CanvasRenderingContext2D,\n  node: LGraphNode,\n  shiftY: number,\n  computedHeight: number | undefined,\n  imgs: HTMLImageElement[],\n  width: number\n) => {\n  if (node.isUploading) {\n    renderUploadSpinner(ctx, node, shiftY, computedHeight)\n    return\n  }\n\n  const canvas = useCanvasStore().getCanvas()\n  const mouse = canvas.graph_mouse\n\n  if (!canvas.pointer_is_down && node.pointerDown) {\n    if (\n      mouse[0] === node.pointerDown.pos[0] &&\n      mouse[1] === node.pointerDown.pos[1]\n    ) {\n      node.imageIndex = node.pointerDown.index\n    }\n    node.pointerDown = null\n  }\n\n  if (imgs.length === 0) return\n\n  let { imageIndex } = node\n  const numImages = imgs.length\n  if (numImages === 1 && !imageIndex) {\n    // This skips the thumbnail render section below\n    node.imageIndex = imageIndex = 0\n  }\n\n  const settingStore = useSettingStore()\n  const allowImageSizeDraw = settingStore.get('Comfy.Node.AllowImageSizeDraw')\n  const IMAGE_TEXT_SIZE_TEXT_HEIGHT = allowImageSizeDraw ? 15 : 0\n  const dw = width\n  const dh = computedHeight ? computedHeight - IMAGE_TEXT_SIZE_TEXT_HEIGHT : 0\n\n  if (imageIndex == null) {\n    // No image selected; draw thumbnails of all\n    let cellWidth: number\n    let cellHeight: number\n    let shiftX: number\n    let cell_padding: number\n    let cols: number\n\n    const compact_mode = is_all_same_aspect_ratio(imgs)\n    if (!compact_mode) {\n      // use rectangle cell style and border line\n      cell_padding = 2\n      // Prevent infinite canvas2d scale-up\n      const largestDimension = imgs.reduce(\n        (acc, current) =>\n          Math.max(acc, current.naturalWidth, current.naturalHeight),\n        0\n      )\n      const fakeImgs = []\n      fakeImgs.length = imgs.length\n      fakeImgs[0] = {\n        naturalWidth: largestDimension,\n        naturalHeight: largestDimension\n      }\n      ;({ cellWidth, cellHeight, cols, shiftX } = calculateImageGrid(\n        fakeImgs,\n        dw,\n        dh\n      ))\n    } else {\n      cell_padding = 0\n      ;({ cellWidth, cellHeight, cols, shiftX } = calculateImageGrid(\n        imgs,\n        dw,\n        dh\n      ))\n    }\n\n    let anyHovered = false\n    node.imageRects = []\n    for (let i = 0; i < numImages; i++) {\n      const img = imgs[i]\n      const row = Math.floor(i / cols)\n      const col = i % cols\n      const x = col * cellWidth + shiftX\n      const y = row * cellHeight + shiftY\n      if (!anyHovered) {\n        anyHovered = LiteGraph.isInsideRectangle(\n          mouse[0],\n          mouse[1],\n          x + node.pos[0],\n          y + node.pos[1],\n          cellWidth,\n          cellHeight\n        )\n        if (anyHovered) {\n          node.overIndex = i\n          let value = 110\n          if (canvas.pointer_is_down) {\n            if (!node.pointerDown || node.pointerDown.index !== i) {\n              node.pointerDown = { index: i, pos: [...mouse] }\n            }\n            value = 125\n          }\n          ctx.filter = `contrast(${value}%) brightness(${value}%)`\n          canvas.canvas.style.cursor = 'pointer'\n        }\n      }\n      node.imageRects.push([x, y, cellWidth, cellHeight])\n\n      const wratio = cellWidth / img.width\n      const hratio = cellHeight / img.height\n      const ratio = Math.min(wratio, hratio)\n\n      const imgHeight = ratio * img.height\n      const imgY = row * cellHeight + shiftY + (cellHeight - imgHeight) / 2\n      const imgWidth = ratio * img.width\n      const imgX = col * cellWidth + shiftX + (cellWidth - imgWidth) / 2\n\n      // Defer image rendering to work around Chrome GPU bug\n      const transform = ctx.getTransform()\n      const filter = ctx.filter\n      const drawParams = {\n        img,\n        x: imgX + cell_padding,\n        y: imgY + cell_padding,\n        w: imgWidth - cell_padding * 2,\n        h: imgHeight - cell_padding * 2\n      }\n      deferredImageRenders.push(() => {\n        if (!drawParams.img.naturalWidth || !drawParams.img.naturalHeight)\n          return\n        ctx.save()\n        ctx.setTransform(transform)\n        ctx.filter = filter\n        ctx.drawImage(\n          drawParams.img,\n          drawParams.x,\n          drawParams.y,\n          drawParams.w,\n          drawParams.h\n        )\n        ctx.restore()\n      })\n      scheduleDeferredImageRender()\n\n      if (!compact_mode) {\n        // rectangle cell and border line style\n        ctx.strokeStyle = '#8F8F8F'\n        ctx.lineWidth = 1\n        ctx.strokeRect(\n          x + cell_padding,\n          y + cell_padding,\n          cellWidth - cell_padding * 2,\n          cellHeight - cell_padding * 2\n        )\n      }\n\n      ctx.filter = 'none'\n    }\n\n    if (!anyHovered) {\n      node.pointerDown = null\n      node.overIndex = null\n    }\n\n    return\n  }\n  // Draw individual\n  const img = imgs.at(imageIndex)\n  if (!img) return\n  let w = img.naturalWidth\n  let h = img.naturalHeight\n\n  const scaleX = dw / w\n  const scaleY = dh / h\n  const scale = Math.min(scaleX, scaleY, 1)\n\n  w *= scale\n  h *= scale\n\n  const x = (dw - w) / 2\n  const y = (dh - h) / 2 + shiftY\n\n  // Defer image rendering to work around Chrome GPU bug\n  const transform = ctx.getTransform()\n  deferredImageRenders.push(() => {\n    if (!img.naturalWidth || !img.naturalHeight) return\n    ctx.save()\n    ctx.setTransform(transform)\n    ctx.drawImage(img, x, y, w, h)\n    ctx.restore()\n  })\n  scheduleDeferredImageRender()\n\n  // Draw image size text below the image\n  if (allowImageSizeDraw) {\n    ctx.fillStyle = LiteGraph.NODE_TEXT_COLOR\n    ctx.textAlign = 'center'\n    ctx.font = '10px sans-serif'\n    const sizeText = `${Math.round(img.naturalWidth)} × ${Math.round(img.naturalHeight)}`\n    const textY = y + h + 10\n    ctx.fillText(sizeText, x + w / 2, textY)\n  }\n\n  const drawButton = (\n    x: number,\n    y: number,\n    sz: number,\n    text: string\n  ): boolean => {\n    const hovered = LiteGraph.isInsideRectangle(\n      mouse[0],\n      mouse[1],\n      x + node.pos[0],\n      y + node.pos[1],\n      sz,\n      sz\n    )\n    let fill = '#333'\n    let textFill = '#fff'\n    let isClicking = false\n    if (hovered) {\n      canvas.canvas.style.cursor = 'pointer'\n      if (canvas.pointer_is_down) {\n        fill = '#1e90ff'\n        isClicking = true\n      } else {\n        fill = '#eee'\n        textFill = '#000'\n      }\n    }\n\n    deferredImageRenders.push(() => {\n      ctx.save()\n      ctx.setTransform(transform)\n      ctx.fillStyle = fill\n      ctx.beginPath()\n      ctx.roundRect(x, y, sz, sz, [4])\n      ctx.fill()\n      ctx.fillStyle = textFill\n      ctx.font = '12px Inter, sans-serif'\n      ctx.textAlign = 'center'\n      ctx.fillText(text, x + 15, y + 20)\n      ctx.restore()\n    })\n\n    return isClicking\n  }\n\n  if (!(numImages > 1)) return\n\n  const imageNum = (node.imageIndex ?? 0) + 1\n  if (drawButton(dw - 40, dh + shiftY - 40, 30, `${imageNum}/${numImages}`)) {\n    const i = imageNum >= numImages ? 0 : imageNum\n    if (!node.pointerDown || node.pointerDown.index !== i) {\n      node.pointerDown = { index: i, pos: [...mouse] }\n    }\n  }\n\n  if (drawButton(dw - 40, shiftY + 10, 30, `x`)) {\n    if (!node.pointerDown || node.pointerDown.index !== null) {\n      node.pointerDown = { index: null, pos: [...mouse] }\n    }\n  }\n}\n\nclass ImagePreviewWidget extends BaseWidget {\n  constructor(\n    node: LGraphNode,\n    name: string,\n    options: IWidgetOptions<string | object>\n  ) {\n    const widget: IBaseWidget = {\n      name,\n      options,\n      type: 'custom',\n      /** Dummy value to satisfy type requirements. */\n      value: '',\n      y: 0\n    }\n    super(widget, node)\n\n    // Don't serialize the widget value\n    this.serialize = false\n  }\n\n  override drawWidget(\n    ctx: CanvasRenderingContext2D,\n    options: DrawWidgetOptions\n  ): void {\n    const imgs = options.previewImages ?? this.node.imgs ?? []\n    renderPreview(\n      ctx,\n      this.node,\n      this.y,\n      this.computedHeight,\n      imgs,\n      options.width\n    )\n  }\n\n  override createCopyForNode(node: LGraphNode): this {\n    const copy = new ImagePreviewWidget(\n      node,\n      this.name,\n      this.options as IWidgetOptions<string | object>\n    ) as this\n    copy.value = this.value\n    return copy\n  }\n\n  override onPointerDown(pointer: CanvasPointer, node: LGraphNode): boolean {\n    pointer.onDragStart = () => {\n      const { canvas } = useApp()\n      const { graph } = canvas\n      canvas.emitBeforeChange()\n      graph?.beforeChange()\n      // Ensure that dragging is properly cleaned up, on success or failure.\n      pointer.finally = () => {\n        canvas.isDragging = false\n        graph?.afterChange()\n        canvas.emitAfterChange()\n      }\n\n      canvas.processSelect(node, pointer.eDown)\n      canvas.isDragging = true\n    }\n\n    pointer.onDragEnd = (e) => {\n      const { canvas } = useApp()\n      if (e.shiftKey || LiteGraph.alwaysSnapToGrid)\n        canvas.graph?.snapToGrid(canvas.selectedItems)\n\n      canvas.setDirty(true, true)\n    }\n\n    return true\n  }\n\n  override onClick(): void {}\n\n  override computeLayoutSize() {\n    return {\n      minHeight: 220,\n      minWidth: 1\n    }\n  }\n}\n\nexport const useImagePreviewWidget = () => {\n  const widgetConstructor: ComfyWidgetConstructorV2 = (\n    node: LGraphNode,\n    inputSpec: InputSpec\n  ) => {\n    return node.addCustomWidget(\n      new ImagePreviewWidget(node, inputSpec.name, {\n        serialize: false,\n        surfaces: { canvas: 'shown', vueNode: 'never', panel: 'never' }\n      })\n    )\n  }\n\n  return widgetConstructor\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/litegraph'\n\nexport const CANVAS_IMAGE_PREVIEW_WIDGET = '$$canvas-image-preview'\n\nconst CANVAS_IMAGE_PREVIEW_NODE_TYPES = new Set([\n  'KSampler',\n  'KSamplerAdvanced',\n  'PreviewImage',\n  'SaveImage',\n  'GLSLShader'\n])\n\nexport function supportsVirtualCanvasImagePreview(node: LGraphNode): boolean {\n  return CANVAS_IMAGE_PREVIEW_NODE_TYPES.has(node.type)\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { useImagePreviewWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useImagePreviewWidget'\n\nimport { CANVAS_IMAGE_PREVIEW_WIDGET } from '@/composables/node/canvasImagePreviewTypes'\n\n/**\n * Composable for handling canvas image previews in nodes\n */\nexport function useNodeCanvasImagePreview() {\n  const imagePreviewWidget = useImagePreviewWidget()\n  /**\n   * Shows canvas image preview for a node\n   * @param node The graph node to show the preview for\n   */\n  function showCanvasImagePreview(node: LGraphNode) {\n    if (!node.imgs?.length) return\n\n    if (node.isSubgraphNode()) return\n\n    if (!node.widgets?.find((w) => w.name === CANVAS_IMAGE_PREVIEW_WIDGET)) {\n      imagePreviewWidget(node, {\n        type: 'IMAGE_PREVIEW',\n        name: CANVAS_IMAGE_PREVIEW_WIDGET\n      })\n    }\n  }\n\n  /**\n   * Removes canvas image preview from a node\n   * @param node The graph node to remove the preview from\n   */\n  function removeCanvasImagePreview(node: LGraphNode) {\n    if (!node.widgets) return\n\n    const widgetIdx = node.widgets.findIndex(\n      (w) => w.name === CANVAS_IMAGE_PREVIEW_WIDGET\n    )\n\n    if (widgetIdx > -1) {\n      node.widgets[widgetIdx].onRemove?.()\n      node.widgets.splice(widgetIdx, 1)\n    }\n  }\n\n  return {\n    showCanvasImagePreview,\n    removeCanvasImagePreview\n  }\n}\n","import type { ImageLoadFailureMetadata } from '@/platform/telemetry/types'\n\n/**\n * An `<img>` `error` event carries no status, no headers and no body — the\n * browser tells you it failed and nothing else. That is why FE-1595 needed the\n * reporting artist's Network tab: `app:image_load_failed` fired on every broken\n * preview but could not say whether the cause was an expired session cookie\n * (401), a missing output (404), or a dropped connection.\n *\n * So we re-request the same URL once, only after a failure, and report the\n * status the browser would not give us. The probe is deliberately cheap and\n * deliberately incapable of making things worse:\n *\n * - `Range: bytes=0-0` asks for a single byte, so a probe of a 20MB output does\n *   not re-download it. Servers that ignore `Range` answer 200 with the body,\n *   which is why the response is never read.\n * - `credentials: 'include'` mirrors how the browser sent the original `<img>`\n *   request. Probing without it would send no cookie and manufacture the very\n *   401 we are trying to measure.\n * - Failures resolve to `probe_failed`/`probe_blocked` rather than throwing. A\n *   diagnostic must never become the second error in the report.\n */\n\n/** Probes are capped per page so a node retrying a missing file in a loop cannot amplify. */\nconst MAX_PROBES_PER_PAGE = 20\n\n/**\n * A probe that outlives this is worth less than the request it occupies. Kept\n * short because the report is emitted after it: a long budget turns every\n * failed image into a window where a page unload loses the event entirely.\n */\nconst PROBE_TIMEOUT_MS = 2_000\n\nlet probesIssued = 0\n\n/** Test seam — the cap is module state that would otherwise leak across cases. */\nexport function resetImageFailureProbesForTest(): void {\n  probesIssued = 0\n}\n\n/**\n * `type` in an `/api/view` URL distinguishes a generated output from a user\n * upload. A 404 on `output` means the result expired or was swept; a 404 on\n * `input` means the upload never landed. They are different bugs and the\n * current event cannot tell them apart.\n */\nfunction resourceKind(url: URL): ImageLoadFailureMetadata['resource_kind'] {\n  const type = url.searchParams.get('type')\n  if (type === 'output' || type === 'input' || type === 'temp') return type\n  return url.searchParams.has('filename') ? 'unspecified' : 'not_api_view'\n}\n\n/**\n * The filename shape separates \"a generation we produced\" from \"a template\n * asset we ship\". Template thumbnails 404ing is a packaging bug on our side;\n * a hashed output 404ing is a retention/lifecycle bug. Reporting the shape\n * rather than the name keeps user-authored filenames out of telemetry.\n */\nfunction filenameKind(url: URL): ImageLoadFailureMetadata['filename_kind'] {\n  const filename = url.searchParams.get('filename')\n  if (!filename) return 'none'\n  if (filename.startsWith('template-')) return 'template'\n  if (/^[0-9a-f]{64}\\./i.test(filename)) return 'content_hash'\n  return 'named'\n}\n\n/**\n * Resolves if the page starts going away, so a pending probe cannot hold the\n * report hostage. Never resolves otherwise — it only ever loses the race.\n *\n * The caller aborts `signal` once the race settles. Without that the listener\n * outlives every probe that wins, and this runs on *every* failed image —\n * including those past the probe cap, where a node retrying a missing file can\n * produce hundreds in one session.\n */\nfunction abandonOnUnload(\n  signal: AbortSignal\n): Promise<Pick<ImageLoadFailureMetadata, 'probe_outcome'>> {\n  return new Promise((resolve) => {\n    window.addEventListener(\n      'pagehide',\n      () => resolve({ probe_outcome: 'probe_abandoned' }),\n      { once: true, signal }\n    )\n  })\n}\n\nasync function probeStatus(\n  src: string\n): Promise<Pick<ImageLoadFailureMetadata, 'status' | 'probe_outcome'>> {\n  if (probesIssued >= MAX_PROBES_PER_PAGE) {\n    return { probe_outcome: 'probe_capped' }\n  }\n  probesIssued += 1\n\n  try {\n    const response = await fetch(src, {\n      method: 'GET',\n      credentials: 'include',\n      headers: { Range: 'bytes=0-0' },\n      // Our own status is the finding. Following a redirect would report the\n      // status of wherever `/api/view` sent us — a signed storage URL answering\n      // 200 or 403 on its own terms — and attribute it to our endpoint.\n      redirect: 'manual',\n      signal: AbortSignal.timeout(PROBE_TIMEOUT_MS)\n    })\n    // A manual-redirect response is opaque: status reads 0 and no header is\n    // legible. That the endpoint redirected is still the answer, so it gets its\n    // own outcome rather than being reported as a status of 0.\n    if (response.type === 'opaqueredirect') {\n      return { probe_outcome: 'probe_redirected' }\n    }\n    // The body is never read: `Range` already bounded it, and cancelling here\n    // releases the connection instead of buffering an image we will not show.\n    // A cancel on an already-errored body rejects, and an unhandled rejection\n    // becomes a spurious Sentry report — so it is swallowed explicitly.\n    void response.body?.cancel().catch(() => {})\n    return { status: response.status, probe_outcome: 'probed' }\n  } catch (error) {\n    // An opaque/CORS/offline failure is itself the finding: the request never\n    // reached a server that could answer, so no status exists to report.\n    return {\n      probe_outcome:\n        error instanceof DOMException && error.name === 'TimeoutError'\n          ? 'probe_timeout'\n          : 'probe_failed'\n    }\n  }\n}\n\n/**\n * Builds the metadata for one failed preview. Never throws and never rejects.\n *\n * `page_age_ms` is the field that would have identified FE-1595 on its own: the\n * session-cookie bug could only strike a page open longer than the cookie's\n * 2-hour life, so an auth-caused failure population skews old while a 404\n * population does not. It is page age, not session age — a reload mints a fresh\n * cookie, which is exactly the boundary that matters.\n */\nexport async function describeImageLoadFailure(\n  src: string\n): Promise<ImageLoadFailureMetadata> {\n  const base: ImageLoadFailureMetadata = {\n    source: 'node_image_preview',\n    page_age_ms: Math.round(performance.now()),\n    online: navigator.onLine,\n    resource_kind: 'not_api_view',\n    filename_kind: 'none',\n    probe_outcome: 'probe_blocked'\n  }\n\n  // An empty src is not a malformed URL — it resolves to the page itself, so\n  // probing it would re-request the HTML document and report a 200 for an image\n  // that never loaded. Reject it before parsing.\n  if (!src.trim()) return { ...base, probe_outcome: 'invalid_src' }\n\n  let url: URL\n  try {\n    url = new URL(src, window.location.href)\n  } catch {\n    // A malformed src never reached the network, so there is nothing to probe\n    // and the shape fields would be fabrications.\n    return { ...base, probe_outcome: 'invalid_src' }\n  }\n\n  const shape = {\n    ...base,\n    resource_kind: resourceKind(url),\n    filename_kind: filenameKind(url),\n    same_origin: url.origin === window.location.origin\n  }\n\n  // Cross-origin images are opaque to `fetch` without CORS, so a probe would\n  // report our own failure rather than the server's answer.\n  if (!shape.same_origin) return shape\n\n  // The report is emitted after the probe resolves, so a page unload mid-probe\n  // would drop the event — the diagnostic would cost us the very failure it\n  // describes. Losing the status is survivable; losing the report is not.\n  const settled = new AbortController()\n  try {\n    return {\n      ...shape,\n      ...(await Promise.race([\n        probeStatus(src),\n        abandonOnUnload(settled.signal)\n      ]))\n    }\n  } finally {\n    // Drops the pagehide listener whichever side won.\n    settled.abort()\n  }\n}\n","import { useChainCallback } from '@/composables/functional/useChainCallback'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { useCanvasInteractions } from '@/renderer/core/canvas/useCanvasInteractions'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { describeImageLoadFailure } from '@/platform/telemetry/imageFailureDiagnostics'\nimport type { ImageLoadFailureMetadata } from '@/platform/telemetry/types'\nimport { useNodeOutputStore } from '@/stores/nodeOutputStore'\nimport { getHdrPreviewUrl } from '@/utils/hdrFormatUtil'\nimport { fitDimensionsToNodeWidth } from '@/utils/imageUtil'\n\nconst VIDEO_WIDGET_NAME = 'video-preview'\nconst VIDEO_DEFAULT_OPTIONS = {\n  playsInline: true,\n  controls: true,\n  loop: true\n} as const\nconst MEDIA_LOAD_TIMEOUT = 8192\nconst MAX_RETRIES = 1\nconst DEFAULT_VIDEO_SIZE = 256\n\ntype MediaElement = HTMLImageElement | HTMLVideoElement\n\ninterface NodePreviewOptions<T extends MediaElement> {\n  loadElement: (url: string) => Promise<T | null>\n  onLoaded?: (elements: T[]) => void\n  onFailedLoading?: () => void\n  /** Which canvas surface this is, so the failure can be attributed. */\n  telemetrySource: Extract<\n    ImageLoadFailureMetadata['source'],\n    'canvas_node_image' | 'canvas_node_video'\n  >\n}\n\ninterface ShowPreviewOptions {\n  /** If true, blocks new loading operations until the current operation is complete. */\n  block?: boolean\n}\n\nconst createContainer = () => {\n  const container = document.createElement('div')\n  container.classList.add('comfy-img-preview')\n  return container\n}\n\nconst createTimeout = (ms: number) =>\n  new Promise<null>((resolve) => setTimeout(() => resolve(null), ms))\n\n/** Distinguishes \"the load stalled\" from \"the load was rejected\"; both otherwise yield `null`. */\nconst MEDIA_LOAD_TIMED_OUT = Symbol('media-load-timed-out')\n\nconst useNodePreview = <T extends MediaElement>(\n  node: LGraphNode,\n  options: NodePreviewOptions<T>\n) => {\n  const { loadElement, onLoaded, onFailedLoading, telemetrySource } = options\n  const nodeOutputStore = useNodeOutputStore()\n\n  const loadElementWithTimeout = async (\n    url: string,\n    retryCount = 0\n  ): Promise<T | null> => {\n    // A stalled load and a rejected one both arrive here as `null`, so the\n    // timeout resolves a sentinel instead: a 401 and an 8s hang are different\n    // problems and must not collapse into the same event. The sentinel is\n    // compared rather than a flag set from the timeout's callback — that flag\n    // would record \"the timeout eventually fired\", which is true even when the\n    // load lost the race by milliseconds.\n    const raced = await Promise.race([\n      loadElement(url),\n      createTimeout(MEDIA_LOAD_TIMEOUT).then(() => MEDIA_LOAD_TIMED_OUT)\n    ])\n    const timedOut = raced === MEDIA_LOAD_TIMED_OUT\n    const result: T | null = timedOut ? null : (raced as T | null)\n\n    if (result === null && retryCount < MAX_RETRIES) {\n      return loadElementWithTimeout(url, retryCount + 1)\n    }\n\n    if (result === null) {\n      // Reported once per URL, after retries are spent — a report per attempt\n      // would inflate the count by exactly `MAX_RETRIES + 1`.\n      void describeImageLoadFailure(url).then((diagnostics) => {\n        useTelemetry()?.trackImageLoadFailed({\n          ...diagnostics,\n          source: telemetrySource,\n          attempts: retryCount + 1,\n          timed_out: timedOut\n        })\n      })\n    }\n\n    return result\n  }\n\n  const loadElements = async (urls: string[]) =>\n    Promise.all(urls.map((url) => loadElementWithTimeout(url)))\n\n  /**\n   * Displays media element(s) on the node.\n   */\n  function showPreview(options: ShowPreviewOptions = {}) {\n    if (node.isLoading) return\n\n    const outputUrls = nodeOutputStore.getNodeImageUrls(node)\n    if (!outputUrls?.length) return\n\n    if (options.block) node.isLoading = true\n\n    loadElements(outputUrls)\n      .then((elements) => {\n        const validElements = elements.filter(\n          (el): el is NonNullable<Awaited<T>> => el !== null\n        )\n        if (validElements.length) {\n          onLoaded?.(validElements)\n          node.graph?.setDirtyCanvas(true)\n        }\n      })\n      .catch(() => {\n        onFailedLoading?.()\n      })\n      .finally(() => {\n        node.isLoading = false\n      })\n  }\n\n  return {\n    showPreview\n  }\n}\n\n/**\n * Attaches a preview image to a node.\n */\nexport const useNodeImage = (node: LGraphNode, callback?: () => void) => {\n  node.previewMediaType = 'image'\n\n  const loadElement = (url: string): Promise<HTMLImageElement | null> =>\n    new Promise((resolve) => {\n      const img = new Image()\n      img.onload = () => resolve(img)\n      img.onerror = () => resolve(null)\n      const previewUrl = getHdrPreviewUrl(url)\n      if (previewUrl) img.dataset.fileUrl = url\n      img.src = previewUrl ?? url\n    })\n\n  const onLoaded = (elements: HTMLImageElement[]) => {\n    node.imageIndex = null\n    node.imgs = elements\n    callback?.()\n  }\n\n  return useNodePreview(node, {\n    loadElement,\n    onLoaded,\n    telemetrySource: 'canvas_node_image',\n    onFailedLoading: () => {\n      node.imgs = undefined\n    }\n  })\n}\n\n/**\n * Attaches a preview video to a node.\n */\nexport const useNodeVideo = (node: LGraphNode, callback?: () => void) => {\n  node.previewMediaType = 'video'\n  let minHeight = DEFAULT_VIDEO_SIZE\n  let minWidth = DEFAULT_VIDEO_SIZE\n\n  const { handleWheel, handlePointerDown, handlePointerMove } =\n    useCanvasInteractions()\n\n  const setMinDimensions = (video: HTMLVideoElement) => {\n    const { minHeight: calculatedHeight, minWidth: calculatedWidth } =\n      fitDimensionsToNodeWidth(\n        video.videoWidth,\n        video.videoHeight,\n        node.size[0] || DEFAULT_VIDEO_SIZE\n      )\n\n    minWidth = calculatedWidth\n    minHeight = calculatedHeight\n  }\n\n  const loadElement = (url: string): Promise<HTMLVideoElement | null> =>\n    new Promise((resolve) => {\n      const video = document.createElement('video')\n      Object.assign(video, VIDEO_DEFAULT_OPTIONS)\n\n      video.onloadeddata = () => {\n        setMinDimensions(video)\n        resolve(video)\n      }\n      video.onerror = () => resolve(null)\n      video.src = url\n    })\n\n  const addVideoDomWidget = (container: HTMLElement) => {\n    const hasWidget = node.widgets?.some((w) => w.name === VIDEO_WIDGET_NAME)\n    if (!hasWidget) {\n      const widget = node.addDOMWidget(VIDEO_WIDGET_NAME, 'video', container, {\n        surfaces: { canvas: 'shown', vueNode: 'never', panel: 'never' },\n        hideOnZoom: false\n      })\n      widget.serialize = false\n      widget.computeLayoutSize = () => ({\n        minHeight,\n        minWidth\n      })\n\n      const controller = new AbortController()\n      const { signal } = controller\n      container.addEventListener('wheel', handleWheel, { signal })\n      container.addEventListener('pointermove', handlePointerMove, { signal })\n      container.addEventListener('pointerdown', handlePointerDown, { signal })\n\n      widget.onRemove = useChainCallback(widget.onRemove, () => {\n        controller.abort()\n      })\n    }\n  }\n\n  const onLoaded = (videoElements: HTMLVideoElement[]) => {\n    const videoElement = videoElements[0]\n\n    if (!node.videoContainer) {\n      node.videoContainer = createContainer()\n      addVideoDomWidget(node.videoContainer)\n    }\n\n    node.videoContainer.replaceChildren(videoElement)\n    callback?.()\n  }\n\n  return useNodePreview(node, {\n    loadElement,\n    onLoaded,\n    telemetrySource: 'canvas_node_video',\n    onFailedLoading: () => {\n      node.videoContainer = undefined\n    }\n  })\n}\n","import cloneDeep from 'es-toolkit/compat/cloneDeep'\nimport { addBreadcrumb } from '@sentry/vue'\nimport type { PromotedWidgetSource } from '@/core/graph/subgraph/promotedWidgetTypes'\nimport { t } from '@/i18n'\nimport type { IContextMenuValue } from '@/lib/litegraph/src/litegraph'\nimport { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { SubgraphNode } from '@/lib/litegraph/src/subgraph/SubgraphNode'\nimport type { LinkId } from '@/types/linkId'\nimport { reorderSubgraphInputs } from '@/lib/litegraph/src/subgraph/subgraphUtils'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport { nextUniqueName } from '@/lib/litegraph/src/strings'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport {\n  CANVAS_IMAGE_PREVIEW_WIDGET,\n  supportsVirtualCanvasImagePreview\n} from '@/composables/node/canvasImagePreviewTypes'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useLitegraphService } from '@/services/litegraphService'\nimport {\n  getPreviewExposureHostLocator,\n  usePreviewExposureStore\n} from '@/stores/previewExposureStore'\nimport { useSubgraphNavigationStore } from '@/stores/subgraphNavigationStore'\nimport { UNASSIGNED_NODE_ID, toNodeId } from '@/types/nodeId'\nimport type { SerializedNodeId } from '@/types/nodeId'\nimport type { WidgetId } from '@/types/widgetId'\nimport { widgetId } from '@/types/widgetId'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\n\ntype PartialNode = Pick<LGraphNode, 'title' | 'id' | 'type'>\ntype RuntimeWidget = Omit<IBaseWidget, 'options'> &\n  Partial<Pick<IBaseWidget, 'options'>>\n\nexport type WidgetItem = [LGraphNode, IBaseWidget]\nexport { CANVAS_IMAGE_PREVIEW_WIDGET }\n\nfunction isLinkedPromotion(\n  subgraphNode: SubgraphNode,\n  sourceNodeId: SerializedNodeId,\n  sourceWidgetName: string\n): boolean {\n  return (\n    findHostInputForPromotion(subgraphNode, sourceNodeId, sourceWidgetName) !==\n    undefined\n  )\n}\n\nexport function findHostInputForPromotion(\n  subgraphNode: SubgraphNode,\n  rawSourceNodeId: SerializedNodeId,\n  sourceWidgetName: string\n) {\n  const sourceNodeId = toNodeId(rawSourceNodeId)\n  return subgraphNode.inputs.find((input) => {\n    const source = input._subgraphSlot\n      ? resolvePromotionSource(subgraphNode, input._subgraphSlot)\n      : undefined\n    return (\n      source?.sourceNodeId === sourceNodeId &&\n      source.sourceWidgetName === sourceWidgetName\n    )\n  })\n}\n\n/**\n * Host-first resolver for promoted widget value keys.\n *\n * Anchors on the host `SubgraphNode.inputs` (which own the promoted `widgetId`\n * per ADR-SUBGRAPH-PROMOTION-0009) and walks host -> interior only to key each host widget by the\n * interior source it projects. Consumers that discover an interior source can\n * then look up the host value key without a per-source reverse walk.\n */\nexport function createPromotedHostWidgetIdLookup(\n  subgraphNode: SubgraphNode\n): (\n  sourceNodeId: SerializedNodeId,\n  sourceWidgetName: string\n) => WidgetId | undefined {\n  const key = (nodeId: SerializedNodeId, name: string): string =>\n    `${toNodeId(nodeId)}\\u0000${name}`\n\n  const hostWidgetIdBySource = new Map<string, WidgetId>()\n  for (const input of subgraphNode.inputs) {\n    const hostWidgetId = input.widgetId\n    const subgraphSlot = input._subgraphSlot\n    if (!hostWidgetId || !subgraphSlot) continue\n\n    const source = resolvePromotionSource(subgraphNode, subgraphSlot)\n    if (!source) continue\n\n    hostWidgetIdBySource.set(\n      key(source.sourceNodeId, source.sourceWidgetName),\n      hostWidgetId\n    )\n  }\n\n  return (sourceNodeId, sourceWidgetName) =>\n    hostWidgetIdBySource.get(key(sourceNodeId, sourceWidgetName))\n}\n\nfunction resolvePromotionSource(\n  subgraphNode: SubgraphNode,\n  subgraphInput: { linkIds: readonly LinkId[] }\n): PromotedWidgetSource | undefined {\n  for (const linkId of subgraphInput.linkIds) {\n    const link = subgraphNode.subgraph.getLink(linkId)\n    if (!link) continue\n\n    const { inputNode, input: targetInput } = link.resolve(\n      subgraphNode.subgraph\n    )\n    if (!inputNode || !targetInput) continue\n\n    if (inputNode.isSubgraphNode()) {\n      return {\n        sourceNodeId: inputNode.id,\n        sourceWidgetName: targetInput.name\n      }\n    }\n\n    const targetWidget = inputNode.getWidgetFromSlot(targetInput)\n    if (!targetWidget) continue\n\n    return {\n      sourceNodeId: inputNode.id,\n      sourceWidgetName: targetWidget.name\n    }\n  }\n}\n\nexport function reorderSubgraphInputsByName(\n  subgraphNode: SubgraphNode,\n  orderedInputNames: readonly string[]\n): void {\n  const order = new Map(\n    orderedInputNames.map((name, index) => [name, index] as const)\n  )\n  const byOrder = <T extends { name: string }>(left: T, right: T) => {\n    const leftOrder = order.get(left.name) ?? Number.MAX_SAFE_INTEGER\n    const rightOrder = order.get(right.name) ?? Number.MAX_SAFE_INTEGER\n    return leftOrder - rightOrder\n  }\n\n  const orderedIndices = subgraphNode.subgraph.inputs\n    .map((input, index) => ({ input, index }))\n    .sort((left, right) => byOrder(left.input, right.input))\n    .map(({ index }) => index)\n  applySubgraphInputOrder(subgraphNode, orderedIndices)\n}\n\nexport function reorderSubgraphInputsByWidgetOrder(\n  subgraphNode: SubgraphNode,\n  orderedWidgets: readonly Pick<IBaseWidget, 'widgetId'>[]\n): void {\n  const remainingIndices = new Set(subgraphNode.inputs.keys())\n  const orderedIndices = orderedWidgets.flatMap((orderedWidget) => {\n    for (const index of remainingIndices) {\n      if (isSamePromotedInput(subgraphNode, index, orderedWidget)) {\n        remainingIndices.delete(index)\n        return [index]\n      }\n    }\n    return []\n  })\n\n  for (const index of remainingIndices) orderedIndices.push(index)\n\n  applySubgraphInputOrder(subgraphNode, orderedIndices)\n}\n\nfunction applySubgraphInputOrder(\n  subgraphNode: SubgraphNode,\n  orderedIndices: readonly number[]\n): void {\n  const widgetValues = subgraphNode.inputs.map((input) => {\n    const id = input.widgetId\n    if (!id) return undefined\n    return useWidgetValueStore().getWidget(id)?.value\n  })\n\n  reorderSubgraphInputs(subgraphNode, orderedIndices)\n  useWidgetValueStore().setNodeWidgetOrder(\n    subgraphNode.rootGraph.id,\n    subgraphNode.id,\n    subgraphNode.inputs.flatMap((input) =>\n      input.widgetId ? [input.widgetId] : []\n    )\n  )\n\n  for (const [newIndex, oldIndex] of orderedIndices.entries()) {\n    const value = widgetValues[oldIndex]\n    const id = subgraphNode.inputs[newIndex]?.widgetId\n    if (value === undefined || !id) continue\n    useWidgetValueStore().setValue(id, value)\n  }\n}\n\nfunction isSamePromotedInput(\n  subgraphNode: SubgraphNode,\n  inputIndex: number,\n  orderedWidget: Pick<IBaseWidget, 'widgetId'>\n): boolean {\n  const input = subgraphNode.inputs.at(inputIndex)\n  const linkedInput = input?._subgraphSlot\n  if (!input || !linkedInput) return false\n\n  for (const linkId of linkedInput.linkIds) {\n    const link = subgraphNode.subgraph.getLink(linkId)\n    if (!link) continue\n\n    const { inputNode, input: targetInput } = link.resolve(\n      subgraphNode.subgraph\n    )\n    if (!inputNode || !targetInput) continue\n\n    const targetWidget = inputNode.getWidgetFromSlot(targetInput)\n    if (targetWidget === orderedWidget) return true\n\n    if (input.widgetId && input.widgetId === orderedWidget.widgetId) return true\n  }\n\n  return false\n}\n\nfunction isPreviewExposed(\n  subgraphNode: SubgraphNode,\n  source: PromotedWidgetSource\n): boolean {\n  const hostLocator = getPreviewExposureHostLocator(subgraphNode)\n  if (!hostLocator) return false\n  return usePreviewExposureStore()\n    .getExposures(subgraphNode.rootGraph.id, hostLocator)\n    .some(\n      (exposure) =>\n        exposure.sourceNodeId === source.sourceNodeId &&\n        exposure.sourcePreviewName === source.sourceWidgetName\n    )\n}\n\nexport function isWidgetPromotedOnSubgraphNode(\n  subgraphNode: SubgraphNode,\n  source: PromotedWidgetSource,\n  widget?: IBaseWidget\n): boolean {\n  if (widget && isPreviewPseudoWidget(widget))\n    return isPreviewExposed(subgraphNode, source)\n  return (\n    isLinkedPromotion(\n      subgraphNode,\n      source.sourceNodeId,\n      source.sourceWidgetName\n    ) || isPreviewExposed(subgraphNode, source)\n  )\n}\n\nfunction toPromotionSource(\n  node: PartialNode,\n  widget: IBaseWidget\n): PromotedWidgetSource {\n  return {\n    sourceNodeId: node.id,\n    sourceWidgetName: widget.name\n  }\n}\n\nexport function refreshPromotedWidgetRendering(parents: SubgraphNode[]): void {\n  for (const parent of parents) {\n    parent.expandToFitContent()\n    parent.setDirtyCanvas(true, true)\n  }\n  useCanvasStore().canvas?.setDirty(true, true)\n}\n\ntype CanonicalPromotionResult =\n  | { ok: true }\n  | { ok: false; reason: 'missingSourceSlot' | 'connectFailed' }\n\nexport function promoteValueWidgetViaSubgraphInput(\n  subgraphNode: SubgraphNode,\n  sourceNode: LGraphNode,\n  sourceWidget: IBaseWidget\n): CanonicalPromotionResult {\n  const sourceWidgetName = sourceWidget.name\n  if (isLinkedPromotion(subgraphNode, sourceNode.id, sourceWidgetName)) {\n    return { ok: true }\n  }\n\n  const sourceSlot = sourceNode.getSlotFromWidget(sourceWidget)\n  if (!sourceSlot) return { ok: false, reason: 'missingSourceSlot' }\n\n  const existingNames = subgraphNode.subgraph.inputs.map((input) => input.name)\n  const inputName = nextUniqueName(sourceWidgetName, existingNames)\n  const subgraphInput = subgraphNode.subgraph.addInput(\n    inputName,\n    // oxlint-disable-next-line typescript/no-unnecessary-condition -- legacy extension slots may omit type at runtime\n    String(sourceSlot.type ?? '*')\n  )\n  subgraphInput.label = sourceSlot.label\n  const link = subgraphInput.connect(sourceSlot, sourceNode)\n  if (!link) {\n    subgraphNode.subgraph.removeInput(subgraphInput)\n    return { ok: false, reason: 'connectFailed' }\n  }\n\n  const hostInput = subgraphNode.inputs.find(\n    (input) => input._subgraphSlot === subgraphInput\n  )\n  if (hostInput) {\n    hostInput.label = sourceSlot.label\n    if (hostInput.widgetId && sourceSlot.label)\n      useWidgetValueStore().setLabel(hostInput.widgetId, sourceSlot.label)\n  }\n\n  seedNestedPromotedInputState(subgraphNode, subgraphInput.name, sourceSlot)\n\n  return { ok: true }\n}\n\nexport function seedNestedPromotedInputState(\n  subgraphNode: SubgraphNode,\n  inputName: string,\n  sourceSlot: { widgetId?: WidgetId; label?: string }\n): void {\n  if (!sourceSlot.widgetId) return\n  if (subgraphNode.id === UNASSIGNED_NODE_ID) return\n\n  const hostInput = subgraphNode.inputs.find(\n    (input) => input._subgraphSlot?.name === inputName\n  )\n  if (!hostInput || hostInput.widgetId) return\n\n  const store = useWidgetValueStore()\n  const sourceState = store.getWidget(sourceSlot.widgetId)\n  const sourceVisibility = store.getWidgetVisibility(sourceSlot.widgetId)\n  if (!sourceState || !sourceVisibility) return\n  const visibility = cloneDeep(sourceVisibility)\n  visibility.suppression.byConnection = false\n\n  const id = widgetId(subgraphNode.rootGraph.id, subgraphNode.id, inputName)\n  hostInput.widget ??= { name: inputName }\n  hostInput.widget.name = inputName\n  const registered = store.registerWidget(\n    id,\n    {\n      type: sourceState.type,\n      value: sourceState.value,\n      options: cloneDeep(sourceState.options),\n      label: hostInput.label ?? sourceSlot.label ?? inputName,\n      serialize: sourceState.serialize,\n      disabled: sourceState.disabled\n    },\n    store.getWidgetRenderState(sourceSlot.widgetId) ?? {},\n    visibility\n  )\n  if (!registered) {\n    delete hostInput.widget\n    delete hostInput.widgetId\n    hostInput._widget = undefined\n    return\n  }\n\n  hostInput.widgetId = id\n}\n\nfunction promotePreviewViaExposure(\n  subgraphNode: SubgraphNode,\n  sourceNode: LGraphNode,\n  sourcePreviewName: string\n): void {\n  const store = usePreviewExposureStore()\n  const rootGraphId = subgraphNode.rootGraph.id\n  const hostLocator = getPreviewExposureHostLocator(subgraphNode)\n  if (!hostLocator) return\n  const existing = store\n    .getExposures(rootGraphId, hostLocator)\n    .some(\n      (exposure) =>\n        exposure.sourceNodeId === String(sourceNode.id) &&\n        exposure.sourcePreviewName === sourcePreviewName\n    )\n  if (existing) return\n\n  store.addExposure(rootGraphId, hostLocator, {\n    sourceNodeId: sourceNode.id,\n    sourcePreviewName\n  })\n}\n\nconst PREVIEW_WIDGET_TYPES = new Set(['preview', 'video', 'audioUI'])\n\nexport function isPreviewPseudoWidget(widget: RuntimeWidget): boolean {\n  if (widget.name.startsWith('$$')) return true\n  if (widget.serialize !== false && widget.options?.serialize !== false)\n    return false\n  if (typeof widget.type === 'string' && PREVIEW_WIDGET_TYPES.has(widget.type))\n    return true\n  return false\n}\n\nexport function promoteWidget(\n  node: PartialNode,\n  widget: IBaseWidget,\n  parents: SubgraphNode[]\n) {\n  const source = toPromotionSource(node, widget)\n  if (!(node instanceof LGraphNode)) return\n  for (const parent of parents) {\n    if (isPreviewPseudoWidget(widget)) {\n      promotePreviewViaExposure(parent, node, source.sourceWidgetName)\n      continue\n    }\n    const result = promoteValueWidgetViaSubgraphInput(parent, node, widget)\n    if (!result.ok) {\n      addBreadcrumb({\n        category: 'subgraph',\n        level: 'warning',\n        message: `Failed to promote widget \"${source.sourceWidgetName}\" on node ${node.id}: ${result.reason}`\n      })\n    }\n  }\n  refreshPromotedWidgetRendering(parents)\n  addBreadcrumb({\n    category: 'subgraph',\n    message: `Promoted widget \"${source.sourceWidgetName}\" on node ${node.id}`,\n    level: 'info'\n  })\n}\n\n/**\n * Removes the host input projecting a linked promotion identified by source.\n * Returns true when an input was found and demoted.\n */\nfunction demotePromotedInput(\n  subgraphNode: SubgraphNode,\n  source: PromotedWidgetSource\n): boolean {\n  const hostInput = findHostInputForPromotion(\n    subgraphNode,\n    source.sourceNodeId,\n    source.sourceWidgetName\n  )\n  const linkedInput = hostInput?._subgraphSlot\n  if (!linkedInput) return false\n  const hostWidgetId = hostInput.widgetId\n\n  if (subgraphNode.isInputConnected(subgraphNode.inputs.indexOf(hostInput))) {\n    linkedInput.disconnect()\n  } else {\n    subgraphNode.subgraph.removeInput(linkedInput)\n  }\n  if (hostWidgetId) useWidgetValueStore().deleteWidget(hostWidgetId)\n  return true\n}\n\nexport function demoteWidget(\n  node: PartialNode,\n  widget: IBaseWidget,\n  parents: SubgraphNode[]\n) {\n  const source = toPromotionSource(node, widget)\n  for (const parent of parents) {\n    if (demotePromotedInput(parent, source)) continue\n\n    if (isPreviewPseudoWidget(widget)) {\n      const previewStore = usePreviewExposureStore()\n      const hostLocator = getPreviewExposureHostLocator(parent)\n      if (!hostLocator) continue\n      const exposure = previewStore\n        .getExposures(parent.rootGraph.id, hostLocator)\n        .find(\n          (entry) =>\n            entry.sourceNodeId === source.sourceNodeId &&\n            entry.sourcePreviewName === source.sourceWidgetName\n        )\n      if (exposure) {\n        previewStore.removeExposure(\n          parent.rootGraph.id,\n          hostLocator,\n          exposure.name\n        )\n        continue\n      }\n    }\n  }\n  refreshPromotedWidgetRendering(parents)\n  addBreadcrumb({\n    category: 'subgraph',\n    message: `Demoted widget \"${source.sourceWidgetName}\" on node ${node.id}`,\n    level: 'info'\n  })\n}\n\nfunction getParentNodes(): SubgraphNode[] {\n  const { navigationStack } = useSubgraphNavigationStore()\n  const subgraph = navigationStack.at(-1)\n  if (!subgraph) {\n    useToast().error(t('g.error'), {\n      description: t('subgraphStore.promoteOutsideSubgraph')\n    })\n    return []\n  }\n  const parentGraph = navigationStack.at(-2) ?? subgraph.rootGraph\n  return parentGraph.nodes.filter(\n    (node): node is SubgraphNode =>\n      node.type === subgraph.id && node.isSubgraphNode()\n  )\n}\n\nexport function addWidgetPromotionOptions(\n  options: (IContextMenuValue | null)[],\n  widget: IBaseWidget,\n  node: LGraphNode\n) {\n  const parents = getParentNodes()\n  const source = toPromotionSource(node, widget)\n  const promotableParents = parents.filter(\n    (parent) => !isWidgetPromotedOnSubgraphNode(parent, source, widget)\n  )\n  if (promotableParents.length > 0)\n    options.unshift({\n      content: t('subgraphStore.promoteWidget', {\n        name: widget.label ?? widget.name\n      }),\n      callback: () => {\n        promoteWidget(node, widget, promotableParents)\n        widget.callback?.(widget.value)\n      }\n    })\n  else {\n    options.unshift({\n      content: t('subgraphStore.unpromoteWidget', {\n        name: widget.label ?? widget.name\n      }),\n      callback: () => {\n        demoteWidget(node, widget, parents)\n        widget.callback?.(widget.value)\n      }\n    })\n  }\n}\n\nexport function tryToggleWidgetPromotion() {\n  const canvas = useCanvasStore().getCanvas()\n  const [x, y] = canvas.graph_mouse\n  const node = canvas.graph?.getNodeOnPos(x, y, canvas.visible_nodes)\n  if (!node) return\n  const widget = node.getWidgetOnPos(x, y, true)\n  const parents = getParentNodes()\n  if (!parents.length || !widget) return\n  const source = toPromotionSource(node, widget)\n  const promotableParents = parents.filter(\n    (parent) => !isWidgetPromotedOnSubgraphNode(parent, source, widget)\n  )\n  if (promotableParents.length > 0)\n    promoteWidget(node, widget, promotableParents)\n  else demoteWidget(node, widget, parents)\n}\n\nconst recommendedNodes = [\n  'CLIPTextEncode',\n  'LoadImage',\n  'SaveImage',\n  'PreviewImage'\n]\nconst recommendedWidgetNames = ['seed']\nexport function isRecommendedWidget([node, widget]: WidgetItem) {\n  return (\n    !widget.computedDisabled &&\n    (recommendedNodes.includes(node.type) ||\n      recommendedWidgetNames.includes(widget.name))\n  )\n}\n\nfunction supportsVirtualPreviewWidget(node: LGraphNode): boolean {\n  return supportsVirtualCanvasImagePreview(node)\n}\n\nfunction createVirtualCanvasImagePreviewWidget(): IBaseWidget {\n  return {\n    name: CANVAS_IMAGE_PREVIEW_WIDGET,\n    type: 'IMAGE_PREVIEW',\n    options: { serialize: false },\n    serialize: false,\n    y: 0,\n    computedDisabled: false\n  }\n}\n\nexport function getPromotableWidgets(node: LGraphNode): IBaseWidget[] {\n  const widgets = [...(node.widgets ?? [])]\n\n  const hasCanvasPreviewWidget = widgets.some(\n    (widget) => widget.name === CANVAS_IMAGE_PREVIEW_WIDGET\n  )\n  const supportsVirtualPreview = supportsVirtualPreviewWidget(node)\n  if (!hasCanvasPreviewWidget && supportsVirtualPreview) {\n    widgets.push(createVirtualCanvasImagePreviewWidget())\n  }\n\n  return widgets\n}\n\nfunction nodeWidgets(n: LGraphNode): WidgetItem[] {\n  return getPromotableWidgets(n).map((w: IBaseWidget) => [n, w])\n}\n\nexport function autoExposeKnownPreviewNodes(subgraphNode: SubgraphNode): void {\n  if (subgraphNode.properties.previewExposures !== undefined) return\n  const { updatePreviews } = useLitegraphService()\n  const interiorNodes = subgraphNode.subgraph.nodes\n  for (const node of interiorNodes) {\n    node.updateComputedDisabled()\n\n    const hasPreviewWidget = () =>\n      node.widgets?.some(isPreviewPseudoWidget) ?? false\n\n    function promotePreviewWidget() {\n      const widget = node.widgets?.find(isPreviewPseudoWidget)\n      if (!widget) return\n      promotePreviewViaExposure(subgraphNode, node, widget.name)\n    }\n    promotePreviewWidget()\n\n    if (hasPreviewWidget()) continue\n\n    if (supportsVirtualCanvasImagePreview(node)) {\n      promotePreviewViaExposure(subgraphNode, node, CANVAS_IMAGE_PREVIEW_WIDGET)\n      continue\n    }\n\n    requestAnimationFrame(() => updatePreviews(node, promotePreviewWidget))\n  }\n}\n\nexport function promoteRecommendedWidgets(subgraphNode: SubgraphNode) {\n  autoExposeKnownPreviewNodes(subgraphNode)\n  const interiorNodes = subgraphNode.subgraph.nodes\n  const filteredWidgets: WidgetItem[] = interiorNodes\n    .flatMap(nodeWidgets)\n    .filter(isRecommendedWidget)\n    .filter(([, widget]) => !isPreviewPseudoWidget(widget))\n  for (const [n, w] of filteredWidgets) {\n    const result = promoteValueWidgetViaSubgraphInput(subgraphNode, n, w)\n    if (!result.ok) {\n      addBreadcrumb({\n        category: 'subgraph',\n        level: 'warning',\n        message: `Failed to promote widget \"${w.name}\" on node ${n.id}: ${result.reason}`\n      })\n    }\n  }\n  subgraphNode.expandToFitContent()\n}\n\nexport function pruneDisconnected(subgraphNode: SubgraphNode) {\n  const subgraph = subgraphNode.subgraph\n  const removedEntries: PromotedWidgetSource[] = []\n\n  const staleInputs = subgraph.inputs.filter((input) => {\n    const source = resolvePromotionSource(subgraphNode, input)\n    if (source) return false\n\n    const hostInput = subgraphNode.inputs.find(\n      (entry) => entry._subgraphSlot === input\n    )\n    if (!hostInput?.widgetId && !hostInput?._widget) return false\n\n    removedEntries.push({\n      sourceNodeId: subgraphNode.id,\n      sourceWidgetName: input.name\n    })\n    return true\n  })\n\n  for (const input of staleInputs) {\n    subgraph.removeInput(input)\n  }\n\n  if (removedEntries.length > 0 && import.meta.env.DEV) {\n    console.warn(\n      '[subgraphInputs] Pruned disconnected promoted widget inputs',\n      removedEntries,\n      {\n        graphId: subgraphNode.rootGraph.id,\n        subgraphNodeId: subgraphNode.id\n      }\n    )\n  }\n\n  refreshPromotedWidgetRendering([subgraphNode])\n  addBreadcrumb({\n    category: 'subgraph',\n    message: `Pruned ${removedEntries.length} disconnected promoted widget input(s) from subgraph node ${subgraphNode.id}`,\n    level: 'info'\n  })\n}\n\nexport function hasUnpromotedWidgets(subgraphNode: SubgraphNode): boolean {\n  if (subgraphNode.isDetached) return false\n  const { subgraph } = subgraphNode\n\n  return subgraph.nodes.some((interiorNode) =>\n    getPromotableWidgets(interiorNode).some(\n      (widget) =>\n        !widget.computedDisabled &&\n        !isWidgetPromotedOnSubgraphNode(\n          subgraphNode,\n          {\n            sourceNodeId: interiorNode.id,\n            sourceWidgetName: widget.name\n          },\n          widget\n        )\n    )\n  )\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport { isCloud } from '@/platform/distribution/types'\nimport { isHostTelemetryEnabled } from '@/platform/telemetry/hostTelemetryEnabled'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { isSubgraph } from '@/utils/typeGuardUtil'\n\ntype RowOperation = 'add_row' | 'remove_row' | 'remote_apply'\n\nconst controllers = new WeakSet<IBaseWidget>()\nconst reported = new Set<string>()\nlet remoteRowCountNode: LGraphNode | undefined\n\nexport function markDynamicGroupController(widget: IBaseWidget): void {\n  controllers.add(widget)\n}\n\n/** True for the hidden widget whose value is a DynamicGroup's row count. */\nexport function isDynamicGroupController(widget: IBaseWidget): boolean {\n  return controllers.has(widget)\n}\n\n/**\n * Runs a remote row count write to `node`. A refusal on that node inside it is\n * reported once, as the remote mismatch, not also as a local row change.\n */\nexport function applyRemoteDynamicGroupRowCount(\n  node: LGraphNode,\n  write: () => void\n): void {\n  const previous = remoteRowCountNode\n  remoteRowCountNode = node\n  try {\n    write()\n  } finally {\n    remoteRowCountNode = previous\n  }\n}\n\n/** Whether a controller holds the row count its setter derives from `value`. */\nexport function reachesDynamicGroupRowCount(\n  widget: IBaseWidget,\n  value: unknown\n): boolean {\n  if (typeof value !== 'number' || !Number.isFinite(value)) return false\n  return widget.value === Math.max(widget.options.min ?? 0, Math.trunc(value))\n}\n\nfunction reportRowCount(\n  node: LGraphNode,\n  operation: RowOperation,\n  counts: { requested: number | null; actual: number },\n  report: {\n    message: string\n    errorType: string\n    surface: 'graph' | 'agent'\n    level?: 'warning'\n    tags?: Record<string, string>\n  }\n): void {\n  const key = `${report.errorType}:${node.type}:${operation}`\n  if (!(isCloud || isHostTelemetryEnabled()) || reported.has(key)) return\n  reported.add(key)\n  reportError(new Error(report.message), {\n    errorType: report.errorType,\n    surface: report.surface,\n    level: report.level,\n    tags: {\n      ...report.tags,\n      node_type: node.type,\n      operation,\n      in_subgraph: isSubgraph(node.graph)\n    },\n    context: counts\n  })\n}\n\n/** Reports a local DynamicGroup row change that left a different row count. */\nexport function reportDynamicGroupRowRefusal(\n  node: LGraphNode,\n  operation: 'add_row' | 'remove_row',\n  requested: number,\n  actual: number\n): void {\n  if (remoteRowCountNode === node) return\n  reportRowCount(\n    node,\n    operation,\n    { requested, actual },\n    {\n      message: 'Refused a DynamicGroup row change',\n      errorType: 'failure_resizing_dynamic_group_rows',\n      surface: 'graph',\n      level: 'warning'\n    }\n  )\n}\n\n/** Reports a remote DynamicGroup row count the live group did not reach. */\nexport function reportRemoteDynamicGroupRowMismatch(\n  node: LGraphNode,\n  requested: unknown,\n  actual: number,\n  tags: Record<string, string>\n): void {\n  reportRowCount(\n    node,\n    'remote_apply',\n    { requested: typeof requested === 'number' ? requested : null, actual },\n    {\n      message: 'Remote DynamicGroup row count did not apply',\n      errorType: 'agent_graph_dynamic_group_rows_mismatch',\n      surface: 'agent',\n      tags\n    }\n  )\n}\n","import { t } from '@/i18n'\nimport { SUBGRAPH_INPUT_ID } from '@/lib/litegraph/src/constants'\nimport type { LGraph, Subgraph } from '@/lib/litegraph/src/LGraph'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport type { SubgraphNode } from '@/lib/litegraph/src/subgraph/SubgraphNode'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport { VueOnlyWidget } from '@/lib/litegraph/src/widgets/VueOnlyWidget'\nimport {\n  captureInputLayout,\n  inputLink,\n  replaceNodeInputs\n} from '@/lib/litegraph/src/node/slotLinks'\nimport {\n  getWidgetIds,\n  resolveNodeRootGraphId\n} from '@/lib/litegraph/src/utils/widget'\nimport { transformInputSpecV1ToV2 } from '@/schemas/nodeDef/migration'\nimport type { InputSpec } from '@/schemas/nodeDefSchema'\nimport { zDynamicGroupInputSpec } from '@/schemas/nodeDefSchema'\nimport { useLitegraphService } from '@/services/litegraphService'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\nimport { deriveWidgetSurfaces } from '@/types/widgetVisibility'\nimport { mapUniqueNodes } from '@/utils/graphTraversalUtil'\nimport { isSubgraph } from '@/utils/typeGuardUtil'\n\nimport {\n  markDynamicGroupController,\n  reportDynamicGroupRowRefusal\n} from './dynamicGroupDiagnostics'\n\nexport function dynamicGroupWidget(\n  node: LGraphNode,\n  inputName: string,\n  inputData: InputSpec\n) {\n  const {\n    min,\n    max,\n    template,\n    group_name = inputName\n  } = zDynamicGroupInputSpec.parse(inputData)[1]\n  const fields = { ...template.required, ...template.optional }\n  const store = useWidgetValueStore()\n  const { addNodeInput } = useLitegraphService()\n  const controller: IBaseWidget = node.addCustomWidget({\n    name: inputName,\n    type: 'number',\n    value: min,\n    y: 0,\n    hidden: true,\n    options: { min, max, socketless: true, serialize: false }\n  })\n  markDynamicGroupController(controller)\n  node.addCustomWidget(\n    new DynamicGroupNoticeWidget(\n      {\n        name: `${inputName}.$notice`,\n        label: group_name,\n        type: 'dynamic_group_notice',\n        value: undefined,\n        y: 0,\n        serialize: false,\n        options: {\n          socketless: true,\n          serialize: false,\n          surfaces: { canvas: 'shown', vueNode: 'never', panel: 'never' }\n        }\n      },\n      node\n    )\n  )\n  const initialCount = controller.value\n  let rowCount = 0\n  const add: IBaseWidget = node.addCustomWidget({\n    name: `${inputName}.$add`,\n    label: t('dynamicGroup.add', { group: group_name }),\n    type: 'button',\n    value: undefined,\n    y: 0,\n    serialize: false,\n    options: {\n      socketless: true,\n      serialize: false,\n      iconClass: 'icon-[lucide--plus]',\n      surfaces: { canvas: 'never', vueNode: 'shown', panel: 'shown' }\n    },\n    callback: () =>\n      changeRows(() => {\n        if (rows().length < max) controller.value = rows().length + 1\n      })\n  })\n\n  function rows() {\n    return (node.widgets ?? []).filter(\n      (widget) =>\n        widget.type === 'dynamic_group_row' &&\n        widget.name.startsWith(`${inputName}.`)\n    )\n  }\n\n  function publish() {\n    const headers = rows()\n    rowCount = headers.length\n    headers.forEach((header, index) => {\n      header.label = t('dynamicGroup.row', {\n        group: group_name,\n        index: index + 1\n      })\n      header.options.disabled = headers.length <= min\n    })\n    add.options.disabled = headers.length >= max\n    if (controller.widgetId) store.setValue(controller.widgetId, headers.length)\n    const graphId = resolveNodeRootGraphId(node)\n    if (graphId && node.widgets)\n      store.setNodeWidgetOrder(graphId, node.id, getWidgetIds(node.widgets))\n  }\n\n  function changeRows(change: () => void) {\n    const graph = node.graph\n    graph?.beforeChange()\n    graph?.canvasAction((canvas) => canvas.emitBeforeChange())\n    try {\n      change()\n      node.setSize([node.size[0], node.computeSize([...node.size])[1]])\n    } finally {\n      graph?.afterChange()\n      graph?.canvasAction((canvas) => canvas.emitAfterChange())\n      node.setDirtyCanvas(true, true)\n    }\n  }\n\n  function removeRow(index: number, hosts = createPromotionHostLookup()) {\n    if (!node.widgets) return false\n    const prefix = `${inputName}.${index}`\n    const removed = node.widgets.filter(\n      (widget) => widget.name === prefix || widget.name.startsWith(`${prefix}.`)\n    )\n    if (!removed.length) return false\n    if (!removeRowInputs(prefix, hosts)) return false\n    for (const widget of removed.reverse()) {\n      if (node.widgets.includes(widget)) node.removeWidget(widget)\n    }\n    for (const header of rows()) {\n      const oldPrefix = header.name\n      const row = Number(oldPrefix.slice(inputName.length + 1))\n      if (row <= index) continue\n      const newPrefix = `${inputName}.${row - 1}`\n      renameRow(oldPrefix, newPrefix, hosts)\n    }\n    return true\n  }\n\n  function removeRowInputs(prefix: string, hosts: PromotionHostLookup) {\n    const previous = captureInputLayout(node)\n    const inputs = previous.inputs.filter(\n      (input) => !input.name.startsWith(`${prefix}.`)\n    )\n    const graph = node.graph\n    const promotedInputs = new Set(\n      previous.inputs.flatMap((input) => {\n        const link = previous.links.get(input)\n        return isSubgraph(graph) &&\n          !inputs.includes(input) &&\n          link?.origin_id === SUBGRAPH_INPUT_ID\n          ? [graph.inputs[link.origin_slot]]\n          : []\n      })\n    )\n    const result = replaceNodeInputs(\n      node,\n      previous,\n      inputs,\n      previous.links,\n      true\n    )\n    if (!result.ok) return false\n    for (const link of node.graph?.floatingLinks.values() ?? []) {\n      if (link.target_id !== node.id) continue\n      const slot = inputs.indexOf(previous.inputs[link.target_slot])\n      if (slot === -1) node.graph?.removeFloatingLink(link)\n      else link.target_slot = slot\n    }\n    previous.inputs.forEach((input, slot) => {\n      if (!inputs.includes(input)) node.onInputRemoved?.(slot, input)\n    })\n    if (isSubgraph(graph))\n      for (const input of promotedInputs)\n        disconnectOrphanedPromotion(graph, graph.inputs.indexOf(input), hosts)\n    return true\n  }\n\n  function fieldLabel(\n    index: number,\n    field: string,\n    row = t('dynamicGroup.row', { group: group_name, index: index + 1 })\n  ) {\n    return `${row} ${fields[field][1]?.display_name ?? field}`\n  }\n\n  function renameRowLabels(\n    oldIndex: number,\n    newIndex: number,\n    hosts: PromotionHostLookup,\n    rowLabel?: string\n  ) {\n    for (const field of Object.keys(fields)) {\n      const name = `${inputName}.${newIndex}.${field}`\n      const slot = node.findInputSlot(name)\n      const input = slot === -1 ? undefined : node.inputs[slot]\n      const previous =\n        input?.localized_name ?? fieldLabel(oldIndex, field, rowLabel)\n      const next = fieldLabel(newIndex, field)\n      const widget = node.widgets?.find((widget) => widget.name === name)\n      if (widget?.label === previous) widget.label = next\n      if (!input) continue\n      if (input.label === previous) input.label = next\n      input.localized_name = next\n      renamePromotedInputLabel(node, slot, previous, next, hosts)\n    }\n  }\n\n  function renameRowWidgets(oldPrefix: string, newPrefix: string) {\n    for (const widget of node.widgets ?? []) {\n      if (widget.name !== oldPrefix && !widget.name.startsWith(`${oldPrefix}.`))\n        continue\n      const name = newPrefix + widget.name.slice(oldPrefix.length)\n      widget.name = name\n      if (\n        widget.name === name &&\n        widget.serialize !== false &&\n        widget.type !== 'button' &&\n        widget.widgetId\n      )\n        store.announceValue(widget.widgetId)\n    }\n  }\n\n  function renameRow(\n    oldPrefix: string,\n    newPrefix: string,\n    hosts: PromotionHostLookup\n  ) {\n    const rowLabel = rows().find((row) => row.name === oldPrefix)?.label\n    renameRowWidgets(oldPrefix, newPrefix)\n    for (const input of node.inputs) {\n      if (!input.name.startsWith(`${oldPrefix}.`)) continue\n      input.name = newPrefix + input.name.slice(oldPrefix.length)\n      if (input.widget) input.widget.name = input.name\n    }\n    renameRowLabels(\n      Number(oldPrefix.slice(inputName.length + 1)),\n      Number(newPrefix.slice(inputName.length + 1)),\n      hosts,\n      rowLabel\n    )\n  }\n\n  function addRow(index: number, hosts: PromotionHostLookup) {\n    const previousSize: [number, number] = [...node.size]\n    const start = node.widgets?.length ?? 0\n    const previous = captureInputLayout(node)\n    const header: IBaseWidget = node.addCustomWidget({\n      name: `${inputName}.${index}`,\n      type: 'dynamic_group_row',\n      value: undefined,\n      y: 0,\n      serialize: false,\n      options: {\n        socketless: true,\n        serialize: false,\n        surfaces: { canvas: 'never', vueNode: 'shown', panel: 'shown' }\n      },\n      callback: () => {\n        if (rows().length <= min) return\n        changeRows(() => {\n          const requested = rows().length - 1\n          if (!removeRow(Number(header.name.slice(inputName.length + 1))))\n            reportDynamicGroupRowRefusal(\n              node,\n              'remove_row',\n              requested,\n              rows().length\n            )\n          publish()\n        })\n      }\n    })\n    addRowFields(index, hosts)\n    const addedInputs = node.inputs.splice(previous.inputs.length)\n    const inputs = [\n      ...previous.inputs,\n      ...addedInputs.filter(\n        (added) => !previous.inputs.some((input) => input.name === added.name)\n      )\n    ]\n    const result = replaceNodeInputs(node, previous, inputs, previous.links)\n    if (!result.ok) {\n      for (const widget of (node.widgets?.slice(start) ?? []).reverse())\n        node.removeWidget(widget)\n      node.setSize(previousSize)\n      return false\n    }\n    for (const addedInput of addedInputs) {\n      const existing = previous.inputs.find(\n        (input) => input.name === addedInput.name\n      )\n      if (existing) existing.widget = addedInput.widget\n    }\n    const widgets = node.widgets\n    if (!widgets) return false\n    const added = widgets.splice(start)\n    widgets.splice(widgets.indexOf(add), 0, ...added)\n    return true\n  }\n\n  function updateInputLabel(\n    name: string,\n    label: string,\n    hosts: PromotionHostLookup\n  ) {\n    const slot = node.findInputSlot(name)\n    if (slot === -1) return\n    const input = node.inputs[slot]\n    const previous = input.localized_name\n    if (!input.label || input.label === previous) input.label = label\n    input.localized_name = label\n    if (previous) renamePromotedInputLabel(node, slot, previous, label, hosts)\n    return input\n  }\n\n  function addRowFields(index: number, hosts: PromotionHostLookup) {\n    for (const [fields, isOptional] of [\n      [template.required, false],\n      [template.optional, true]\n    ] as const) {\n      for (const [field, spec] of Object.entries(fields ?? {})) {\n        const name = `${inputName}.${index}.${field}`\n        const refreshed = useNodeDefStore().getInputSpecForWidget(node, name)\n        const fieldStart = node.widgets?.length ?? 0\n        addNodeInput(node, {\n          ...(refreshed ??\n            transformInputSpecV1ToV2(spec, { name, isOptional })),\n          display_name: fieldLabel(index, field)\n        })\n        const input = updateInputLabel(name, fieldLabel(index, field), hosts)\n        let auxiliaryIndex = 0\n        node.widgets?.slice(fieldStart).forEach((widget) => {\n          const options = widget.options\n          options.surfaces = {\n            ...deriveWidgetSurfaces(widget),\n            canvas: 'never'\n          }\n          widget.options = options\n          if (widget.name === name) {\n            if (input?.label) widget.label = input.label\n            return\n          }\n          widget.label ??= widget.name\n          widget.name = `${name}.${auxiliaryIndex++}`\n        })\n      }\n    }\n  }\n\n  function announceAddedValues(existing: Set<IBaseWidget>) {\n    for (const widget of node.widgets ?? []) {\n      if (\n        !existing.has(widget) &&\n        widget.serialize !== false &&\n        widget.type !== 'button' &&\n        widget.widgetId\n      )\n        store.announceValue(widget.widgetId)\n    }\n  }\n\n  function validateSavedRowCount(value: number, requested: number) {\n    const graphId = resolveNodeRootGraphId(node)\n    if (!graphId) return\n    const widgets = node.widgets ?? []\n    const position = widgets\n      .filter((widget) => widget.serialize !== false)\n      .indexOf(controller)\n    const restored = store.getRestoredWidgetValue(\n      graphId,\n      node.id,\n      inputName,\n      position\n    )\n    if (restored?.value !== value) return\n    const savedValueCount = store.getRestoredWidgetValueCount(graphId, node.id)\n    if (requested > Math.max(max, savedValueCount ?? 0))\n      throw new RangeError(\n        `Invalid saved row count for DynamicGroup '${inputName}'`\n      )\n  }\n\n  Object.defineProperty(controller, 'value', {\n    get: () => rowCount,\n    set(value: unknown) {\n      if (typeof value !== 'number' || !Number.isFinite(value)) return\n      const requested = Math.max(0, Math.trunc(value))\n      validateSavedRowCount(value, requested)\n      const count = Math.max(min, requested)\n      const hosts = createPromotionHostLookup()\n      for (let index = rows().length - 1; index >= count; index--) {\n        if (!removeRow(index, hosts)) break\n      }\n      const existing = new Set(node.widgets)\n      while (rows().length < count) {\n        if (!addRow(rows().length, hosts)) break\n      }\n      publish()\n      announceAddedValues(existing)\n      if (rowCount !== count)\n        reportDynamicGroupRowRefusal(\n          node,\n          rowCount > count ? 'remove_row' : 'add_row',\n          count,\n          rowCount\n        )\n    }\n  })\n  controller.value = initialCount\n  return { widget: controller }\n}\n\ntype PromotionHostLookup = (subgraph: Subgraph) => SubgraphNode[]\n\nfunction createPromotionHostLookup(): PromotionHostLookup {\n  let hosts: Map<Subgraph, SubgraphNode[]> | undefined\n  return (subgraph) => {\n    if (!hosts) {\n      hosts = new Map()\n      for (const host of mapUniqueNodes(subgraph.rootGraph, (node) =>\n        node.isSubgraphNode() ? node : undefined\n      )) {\n        const instances = hosts.get(host.subgraph) ?? []\n        instances.push(host)\n        hosts.set(host.subgraph, instances)\n      }\n    }\n    return hosts.get(subgraph) ?? []\n  }\n}\n\nfunction renamePromotedInputLabel(\n  node: LGraphNode,\n  slot: number,\n  previous: string,\n  next: string,\n  hosts: PromotionHostLookup\n) {\n  const graph = node.graph\n  if (!isSubgraph(graph)) return\n  const link = inputLink(graph, node.id, slot)\n  if (link?.origin_id !== SUBGRAPH_INPUT_ID) return\n  const promoted = graph.inputs[link.origin_slot]\n  if (promoted.label !== previous) return\n  graph.renameInput(promoted, next)\n  for (const host of hosts(graph))\n    renamePromotedInputLabel(host, link.origin_slot, previous, next, hosts)\n}\n\nfunction disconnectOrphanedPromotion(\n  graph: LGraph | Subgraph | null,\n  slot: number,\n  hosts: PromotionHostLookup\n) {\n  if (!isSubgraph(graph) || graph.inputs[slot]?.linkIds.length !== 0) return\n  const input = graph.inputs[slot]\n  for (const host of hosts(graph)) {\n    removeFloatingHostLinks(host, slot)\n    const link = host.graph && inputLink(host.graph, host.id, slot)\n    if (!link) continue\n    host.disconnectInput(slot)\n    if (link.origin_id === SUBGRAPH_INPUT_ID)\n      disconnectOrphanedPromotion(host.graph, link.origin_slot, hosts)\n  }\n  graph.removeInput(input)\n  if (!graph.inputs.includes(input)) removeFloatingLinksFrom(graph, slot)\n}\n\nfunction removeFloatingLinksFrom(graph: Subgraph, slot: number) {\n  for (const link of graph.floatingLinks.values()) {\n    if (link.origin_id !== SUBGRAPH_INPUT_ID) continue\n    if (link.origin_slot === slot) graph.removeFloatingLink(link)\n    else if (link.origin_slot > slot) link.origin_slot--\n  }\n}\n\nfunction removeFloatingHostLinks(host: SubgraphNode, slot: number) {\n  for (const link of host.graph?.floatingLinks.values() ?? [])\n    if (link.target_id === host.id && link.target_slot === slot)\n      host.graph?.removeFloatingLink(link)\n}\n\nclass DynamicGroupNoticeWidget extends VueOnlyWidget<IBaseWidget> {\n  protected get vueOnlyLabel(): string {\n    return this.label ?? this.name\n  }\n}\n","import { remove } from 'es-toolkit'\nimport { shallowReactive } from 'vue'\n\nimport { assert } from '@/base/assert'\nimport { useChainCallback } from '@/composables/functional/useChainCallback'\nimport type { ISlotType } from '@/lib/litegraph/src/interfaces'\nimport type { INodeInputSlot } from '@/lib/litegraph/src/types/slots'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport type { LLink } from '@/lib/litegraph/src/LLink'\nimport { commonType } from '@/lib/litegraph/src/utils/type'\nimport {\n  getWidgetIds,\n  resolveNodeRootGraphId\n} from '@/lib/litegraph/src/utils/widget'\nimport { transformInputSpecV1ToV2 } from '@/schemas/nodeDef/migration'\nimport type { ComboInputSpec, InputSpec } from '@/schemas/nodeDefSchema'\nimport type { InputSpec as InputSpecV2 } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport {\n  zAutogrowOptions,\n  zDynamicComboInputSpec,\n  zMatchTypeOptions\n} from '@/schemas/nodeDefSchema'\nimport { useLitegraphService } from '@/services/litegraphService'\nimport { useApp } from '@/scripts/appInstance'\nimport type { ComfyApp } from '@/types/comfy'\nimport {\n  captureInputLayout,\n  replaceNodeInputs\n} from '@/lib/litegraph/src/node/slotLinks'\nimport type { InputLayoutSnapshot } from '@/lib/litegraph/src/node/slotLinks'\nimport { useLinkStore } from '@/stores/linkStore'\nimport { graphScopeOf } from '@/types/graphScopeId'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\nimport type { WidgetValue } from '@/types/simplifiedWidget'\nimport { widgetId } from '@/types/widgetId'\nimport { dynamicGroupWidget } from './dynamicGroupWidget'\n\ntype MatchTypeNode = LGraphNode &\n  Pick<Required<LGraphNode>, 'onConnectionsChange'> & {\n    comfyDynamic: { matchType: Record<string, Record<string, string>> }\n  }\ntype AutogrowNode = LGraphNode &\n  Pick<Required<LGraphNode>, 'onConnectionsChange' | 'widgets'> & {\n    comfyDynamic: {\n      autogrow: Record<\n        string,\n        {\n          min: number\n          max: number\n          inputSpecs: InputSpecV2[]\n          prefix?: string\n          names?: string[]\n        }\n      >\n    }\n  }\n\nfunction commitMutatedInputs(\n  node: LGraphNode,\n  previous: InputLayoutSnapshot,\n  assignments: ReadonlyMap<INodeInputSlot, LLink>\n) {\n  const finalInputs = [...node.inputs]\n  node.inputs.splice(0, node.inputs.length, ...previous.inputs)\n  return replaceNodeInputs(node, previous, finalInputs, assignments)\n}\n\nfunction syncNodeWidgetOrder(node: LGraphNode) {\n  const graphId = resolveNodeRootGraphId(node)\n  if (!graphId || !node.widgets) return\n  useWidgetValueStore().setNodeWidgetOrder(\n    graphId,\n    node.id,\n    getWidgetIds(node.widgets)\n  )\n}\n\nfunction ensureWidgetForInput(node: LGraphNode, input: INodeInputSlot) {\n  node.widgets ??= []\n  const { widget } = input\n  if (widget && node.widgets.some((w) => w.name === widget.name)) return\n  node.widgets.push({\n    draw(ctx, _n, _w, y) {\n      ctx.save()\n      ctx.fillStyle = LiteGraph.NODE_TEXT_COLOR\n      ctx.fillText(input.label ?? input.name, 20, y + 15)\n      ctx.restore()\n    },\n    name: input.name,\n    options: {},\n    serialize: false,\n    type: 'shim',\n    y: 0\n  })\n  input.alwaysVisible = true\n  input.widget = { name: input.name }\n}\n\nfunction dynamicComboWidget(\n  node: LGraphNode,\n  inputName: string,\n  untypedInputData: InputSpec,\n  appArg: ComfyApp,\n  widgetName?: string\n) {\n  const { addNodeInput } = useLitegraphService()\n  const { deleteWidget } = useWidgetValueStore()\n  const parseResult = zDynamicComboInputSpec.safeParse(untypedInputData)\n  if (!parseResult.success) throw new Error('invalid DynamicCombo spec')\n  const inputData = parseResult.data\n  const options = Object.fromEntries(\n    inputData[1].options.map(({ key, inputs }) => [key, inputs])\n  )\n  const subSpec: ComboInputSpec = [Object.keys(options), {}]\n  const result = useApp().widgets.COMBO(\n    node,\n    inputName,\n    subSpec,\n    appArg,\n    widgetName\n  )\n  assert(\n    result && 'widget' in result && result.widget,\n    'COMBO widget constructor returned no widget'\n  )\n  const { widget, minWidth, minHeight } = result\n  const removedWidgetValues = new Map<\n    string | undefined,\n    Map<string, { type: string; value: WidgetValue }>\n  >()\n  let activeOption = widget.value as string | undefined\n  function isInGroup(e: { name: string }): boolean {\n    return e.name.startsWith(inputName + '.')\n  }\n  function restoreRemovedValues(\n    value: string | undefined,\n    widgetNames: string[]\n  ) {\n    const widgets = node.widgets\n    if (!widgets) return\n    const graphId = resolveNodeRootGraphId(node)\n    const removedValues = removedWidgetValues.get(value)\n    const names = new Set(widgetNames)\n    for (const name of removedValues?.keys() ?? []) names.add(name)\n    for (const name of names) {\n      const addedWidget = widgets.find((widget) => widget.name === name)\n      if (!addedWidget) continue\n      const removed = removedValues?.get(name)\n      const positionalIndex = widgets\n        .filter((widget) => widget.serialize !== false)\n        .indexOf(addedWidget)\n      const restored =\n        graphId && positionalIndex >= 0\n          ? useWidgetValueStore().getRestoredWidgetValue(\n              graphId,\n              node.id,\n              name,\n              positionalIndex\n            )\n          : undefined\n      if (!restored && removed?.type === addedWidget.type) {\n        addedWidget.value = removed.value\n      }\n    }\n  }\n  const updateWidgets = (value?: string) => {\n    if (!node.widgets) throw new Error('Not Reachable')\n    const newSpec = value ? options[value] : undefined\n    const removedOption = activeOption\n    activeOption = value\n\n    const previous = captureInputLayout(node)\n    const inputLinks = new Map(previous.links)\n    const removedInputs = remove(node.inputs, isInGroup)\n    for (const widget of remove(node.widgets, isInGroup)) {\n      const optionValues = removedWidgetValues.get(removedOption) ?? new Map()\n      optionValues.set(widget.name, {\n        type: widget.type,\n        value: widget.value\n      })\n      removedWidgetValues.set(removedOption, optionValues)\n      widget.onRemove?.()\n      if (widget.widgetId) deleteWidget(widget.widgetId)\n    }\n\n    if (!newSpec) {\n      const result = commitMutatedInputs(node, previous, inputLinks)\n      if (!result.ok) return\n      syncNodeWidgetOrder(node)\n      return\n    }\n\n    const insertionPoint = node.widgets.findIndex((w) => w === widget) + 1\n    const startingLength = node.widgets.length\n    const startingInputLength = node.inputs.length\n\n    if (insertionPoint === 0)\n      throw new Error(\"Dynamic widget doesn't exist on node\")\n    const inputTypes: (Record<string, InputSpec> | undefined)[] = [\n      newSpec.required,\n      newSpec.optional\n    ]\n    inputTypes.forEach((inputType, idx) => {\n      for (const key in inputType ?? {}) {\n        const name = `${widget.name}.${key}`\n        const specToAdd = transformInputSpecV1ToV2(inputType![key], {\n          name,\n          isOptional: idx !== 0\n        })\n        specToAdd.display_name = key\n        addNodeInput(node, specToAdd)\n      }\n    })\n\n    const inputInsertionPoint =\n      node.inputs.findIndex((i) => i.name === widget.name) + 1\n    const addedWidgets = node.widgets.splice(startingLength)\n    const addedWidgetNames = addedWidgets.map(({ name }) => name)\n    node.widgets.splice(insertionPoint, 0, ...addedWidgets)\n    syncNodeWidgetOrder(node)\n    if (inputInsertionPoint === 0) {\n      if (\n        addedWidgets.length === 0 &&\n        node.inputs.length !== startingInputLength\n      )\n        //input is inputOnly, but lacks an insertion point\n        throw new Error('Failed to find input socket for ' + widget.name)\n      const result = commitMutatedInputs(node, previous, inputLinks)\n      if (!result.ok) return\n      restoreRemovedValues(value, addedWidgetNames)\n      return\n    }\n    const addedInputs = node.inputs\n      .splice(startingInputLength)\n      .map((addedInput) => {\n        const existingInput = node.inputs.findIndex(\n          (existingInput) => addedInput.name === existingInput.name\n        )\n        return existingInput === -1\n          ? addedInput\n          : node.inputs.splice(existingInput, 1)[0]\n      })\n    //assume existing inputs are in correct order\n    node.inputs.splice(inputInsertionPoint, 0, ...addedInputs)\n\n    for (const input of removedInputs) {\n      const replacement = node.inputs.find((item) => item.name === input.name)\n      const link = inputLinks.get(input)\n      if (replacement && link) inputLinks.set(replacement, link)\n    }\n    const result = commitMutatedInputs(node, previous, inputLinks)\n    if (!result.ok) return\n    //A callback can grow the group it lands on, shifting every input after\n    //it, so the slot captured before the batch is stale for later entries.\n    for (const { input, link } of result.replacements) {\n      const slot = node.inputs.indexOf(input)\n      if (slot === -1) continue\n      node.onConnectionsChange?.(LiteGraph.INPUT, slot, true, link, input)\n    }\n    restoreRemovedValues(value, addedWidgetNames)\n\n    if (!node.graph) return\n    node._setConcreteSlots()\n    node.arrange()\n    node.graph.setDirtyCanvas(true, true)\n  }\n  //Refit height on the callback channel: interaction fires it after the value\n  //setter, while configure (load, clone, paste) only fires the setter and must\n  //keep the serialised height.\n  widget.callback = useChainCallback(widget.callback, () => {\n    node.size = [node.size[0], node.computeSize([...node.size])[1]]\n    node.graph?.setDirtyCanvas(true, true)\n  })\n  //A little hacky, but onConfigure won't work.\n  //It fires too late and is overly disruptive\n  let widgetValue = widget.value\n  const getState = () => {\n    const graphId = resolveNodeRootGraphId(node)\n    if (!graphId) return undefined\n    return useWidgetValueStore().getWidget(\n      widgetId(graphId, node.id, widget.name)\n    )\n  }\n  Object.defineProperty(widget, 'value', {\n    get() {\n      return getState()?.value ?? widgetValue\n    },\n    set(value) {\n      const state = getState()\n      if (state) state.value = value\n      widgetValue = value\n      updateWidgets(value)\n    }\n  })\n  widget.value = widgetValue\n  return { widget, minWidth, minHeight }\n}\n\nexport const dynamicWidgets = {\n  COMFY_DYNAMICCOMBO_V3: dynamicComboWidget,\n  COMFY_DYNAMICGROUP_V3: dynamicGroupWidget\n}\nconst dynamicInputs: Record<\n  string,\n  (node: LGraphNode, inputSpec: InputSpecV2) => void\n> = {\n  COMFY_AUTOGROW_V3: applyAutogrow,\n  COMFY_MATCHTYPE_V3: applyMatchType\n}\n\nexport function applyDynamicInputs(\n  node: LGraphNode,\n  inputSpec: InputSpecV2\n): boolean {\n  if (!(inputSpec.type in dynamicInputs)) return false\n  //TODO: move parsing/validation of inputSpec here?\n  dynamicInputs[inputSpec.type](node, inputSpec)\n  return true\n}\n\nfunction changeOutputType(\n  node: LGraphNode,\n  slot: number,\n  combinedType: ISlotType\n) {\n  const output = node.outputs[slot]\n  if (output.type === combinedType) return\n  output.type = combinedType\n\n  //check and potentially remove links\n  if (!node.graph) return\n  const topologies = useLinkStore().getOutputSlotLinks(\n    graphScopeOf(node.graph),\n    node.id,\n    slot\n  )\n  for (const topology of topologies) {\n    const link = node.graph.getLink(topology.id)\n    if (!link) continue\n    const { input, inputNode, subgraphOutput } = link.resolve(node.graph)\n    const inputType = (input ?? subgraphOutput)?.type\n    if (!inputType) continue\n    const keep = LiteGraph.isValidConnection(combinedType, inputType)\n    if (!keep && subgraphOutput) subgraphOutput.disconnect()\n    else if (!keep && inputNode) inputNode.disconnectInput(link.target_slot)\n    if (input && inputNode?.onConnectionsChange)\n      inputNode.onConnectionsChange(\n        LiteGraph.INPUT,\n        link.target_slot,\n        keep,\n        link,\n        input\n      )\n  }\n}\n\nfunction withComfyMatchType(node: LGraphNode): asserts node is MatchTypeNode {\n  if (node.comfyDynamic?.matchType) return\n  node.comfyDynamic ??= {}\n  node.comfyDynamic.matchType = {}\n\n  const outputGroups = node.constructor.nodeData?.output_matchtypes\n  node.onConnectionsChange = useChainCallback(\n    node.onConnectionsChange,\n    function (\n      this: MatchTypeNode,\n      contype: ISlotType,\n      slot: number,\n      iscon: boolean,\n      linf: LLink | null | undefined\n    ) {\n      const input = this.inputs.at(slot)\n      const { graph } = this\n      if (contype !== LiteGraph.INPUT || !graph || !input) return\n      if (useApp().configuringGraph) return\n      const [matchKey, matchGroup] = Object.entries(\n        this.comfyDynamic.matchType\n      ).find(([, group]) => input.name in group) ?? ['', undefined]\n      if (!matchGroup) return\n      if (iscon && linf) {\n        const { output, subgraphInput } = linf.resolve(graph)\n        const connectingType = (output ?? subgraphInput)?.type\n        if (connectingType) linf.type = connectingType\n      }\n      //NOTE: inputs contains input\n      const groupInputs: INodeInputSlot[] = node.inputs.filter(\n        (inp) => inp.name in matchGroup\n      )\n      const connectedTypes = groupInputs.map((inp) => {\n        const link = this.getInputLink(this.inputs.indexOf(inp))\n        if (!link) return '*'\n        const { output, subgraphInput } = link.resolve(graph)\n        return (output ?? subgraphInput)?.type ?? '*'\n      })\n      //An input slot can accept a connection that is\n      // - Compatible with original type\n      // - Compatible with all other input types\n      //An output slot can output\n      // - Only what every input can output\n      groupInputs.forEach((input, idx) => {\n        const otherConnected = [\n          ...connectedTypes.slice(0, idx),\n          ...connectedTypes.slice(idx + 1)\n        ]\n        const combinedType = commonType(\n          ...otherConnected,\n          matchGroup[input.name]\n        )\n        if (!combinedType) throw new Error('invalid connection')\n        input.type = combinedType\n      })\n      const outputType = commonType(...connectedTypes)\n      if (!outputType) throw new Error('invalid connection')\n      this.outputs.forEach((_output, idx) => {\n        if (!(outputGroups?.[idx] == matchKey)) return\n        changeOutputType(this, idx, outputType)\n      })\n      graph.setDirtyCanvas(true, true)\n    }\n  )\n}\n\nfunction applyMatchType(node: LGraphNode, inputSpec: InputSpecV2) {\n  const { addNodeInput } = useLitegraphService()\n  const name = inputSpec.name\n  const parseResult = zMatchTypeOptions.safeParse(inputSpec)\n  if (!parseResult.success) {\n    console.warn(\n      `Unparseable COMFY_MATCHTYPE_V3 spec for input \"${name}\"; falling back to a wildcard socket.`,\n      parseResult.error.issues\n    )\n    addNodeInput(node, { ...inputSpec, type: '*' })\n    return\n  }\n  const matchTypeSpec = parseResult.data\n\n  const { allowed_types, template_id } = matchTypeSpec.template\n  const typedSpec = { ...inputSpec, type: allowed_types }\n  addNodeInput(node, typedSpec)\n  withComfyMatchType(node)\n  node.comfyDynamic.matchType[template_id] ??= {}\n  node.comfyDynamic.matchType[template_id][name] = allowed_types\n\n  //TODO: instead apply on output add?\n  //ensure outputs get updated\n  const index = node.inputs.length - 1\n  requestAnimationFrame(() => {\n    const input = node.inputs.at(index)\n    if (!input || !node.graph) return\n    node.inputs[index] = shallowReactive(input)\n    const existingLink = node.getInputLink(index)\n    node.onConnectionsChange(\n      LiteGraph.INPUT,\n      index,\n      !!existingLink,\n      existingLink ?? undefined,\n      input\n    )\n  })\n}\n\nfunction autogrowOrdinalToName(\n  ordinal: number,\n  key: string,\n  groupName: string,\n  node: AutogrowNode\n) {\n  const {\n    names,\n    prefix = '',\n    inputSpecs\n  } = node.comfyDynamic.autogrow[groupName]\n  const baseName = names\n    ? names[ordinal]\n    : (inputSpecs.length == 1 ? prefix : key) + ordinal\n  return { name: `${groupName}.${baseName}`, display_name: baseName }\n}\n\nfunction addAutogrowGroup(\n  ordinal: number,\n  groupName: string,\n  node: AutogrowNode\n) {\n  const { addNodeInput } = useLitegraphService()\n  const { max, min, inputSpecs } = node.comfyDynamic.autogrow[groupName]\n  if (ordinal >= max) return\n\n  const previous = captureInputLayout(node)\n  const inputLinks = new Map(previous.links)\n  const namedSpecs = inputSpecs.map((input) => ({\n    ...input,\n    isOptional: ordinal >= min || input.isOptional,\n    ...autogrowOrdinalToName(ordinal, input.name, groupName, node)\n  }))\n\n  const newInputs = namedSpecs.map((namedSpec) => {\n    addNodeInput(node, namedSpec)\n    const input = node.inputs.splice(node.inputs.length - 1, 1)[0]\n    if (inputSpecs.length !== 1) ensureWidgetForInput(node, input)\n    return input\n  })\n\n  for (const newInput of newInputs) {\n    for (const existingInput of remove(\n      node.inputs,\n      (inp) => inp.name === newInput.name\n    )) {\n      const link = inputLinks.get(existingInput)\n      if (link && !inputLinks.has(newInput)) inputLinks.set(newInput, link)\n      if (existingInput.label) newInput.label = existingInput.label\n    }\n  }\n\n  const targetName = autogrowOrdinalToName(\n    ordinal - 1,\n    inputSpecs.at(-1)!.name,\n    groupName,\n    node\n  ).name\n  const lastIndex = node.inputs.findLastIndex((inp) =>\n    inp.name.startsWith(targetName)\n  )\n  const insertionIndex = lastIndex === -1 ? node.inputs.length : lastIndex + 1\n  node.inputs.splice(insertionIndex, 0, ...newInputs)\n  const result = commitMutatedInputs(node, previous, inputLinks)\n  if (!result.ok) return\n  node.graph?.setDirtyCanvas(true, true)\n}\n\nconst ORDINAL_REGEX = /\\d+$/\n\nfunction resolveAutogrowOrdinal(\n  inputName: string,\n  groupName: string,\n  node: AutogrowNode\n): number | undefined {\n  const name = inputName.slice(groupName.length + 1)\n  const { names } = node.comfyDynamic.autogrow[groupName]\n  if (names) {\n    const index = names.indexOf(name)\n    return index === -1 ? undefined : index\n  }\n  const match = name.match(ORDINAL_REGEX)\n  return match ? parseInt(match[0]) : undefined\n}\nfunction autogrowInputConnected(index: number, node: AutogrowNode) {\n  const input = node.inputs.at(index)\n  if (!input) return\n  const groupName = input.name.slice(0, input.name.lastIndexOf('.'))\n  const lastInput = node.inputs.findLast((inp) =>\n    inp.name.startsWith(groupName + '.')\n  )\n  const ordinal = resolveAutogrowOrdinal(input.name, groupName, node)\n  if (\n    !lastInput ||\n    ordinal == undefined ||\n    (ordinal !== resolveAutogrowOrdinal(lastInput.name, groupName, node) &&\n      !useApp().configuringGraph)\n  )\n    return\n  addAutogrowGroup(ordinal + 1, groupName, node)\n}\n\nfunction hasAutogrowGroups(node: LGraphNode): node is AutogrowNode {\n  return !!node.comfyDynamic?.autogrow\n}\n\n/**\n * The live autogrow group `name` belongs to, from the node's own\n * `comfyDynamic.autogrow` registration -- real provenance from\n * `applyAutogrow`/`addAutogrowGroup`, rather than inferred from the name's\n * shape. Confirms membership with `resolveAutogrowOrdinal`, the same check\n * growth and shrink use, so a name that merely starts with a group's prefix\n * without resolving to one of its members doesn't false-match. Undefined\n * when the node has no autogrow groups, or `name` isn't a member of any of\n * them.\n */\nexport function liveAutogrowGroupOf(\n  node: LGraphNode,\n  name: string\n): string | undefined {\n  if (!hasAutogrowGroups(node)) return undefined\n  for (const groupName of Object.keys(node.comfyDynamic.autogrow)) {\n    if (!name.startsWith(`${groupName}.`)) continue\n    if (resolveAutogrowOrdinal(name, groupName, node) !== undefined) {\n      return groupName\n    }\n  }\n  return undefined\n}\n\nfunction highestAutogrowOrdinal(node: AutogrowNode, groupName: string): number {\n  let highest = -1\n  for (const input of node.inputs) {\n    if (!input.name.startsWith(`${groupName}.`)) continue\n    const ordinal = resolveAutogrowOrdinal(input.name, groupName, node)\n    if (ordinal !== undefined && ordinal > highest) highest = ordinal\n  }\n  return highest\n}\n\n/**\n * Grows the autogrow group `name` belongs to until the node holds an input by\n * that name, and returns its live index. A local connect onto a slot the bound\n * document has not seen mints a `grow` op (`docOpMinter.mintConnect`); this is\n * the read leg of that exchange, for a slot the host grew whose live\n * counterpart does not exist yet. Growth starts above the group's highest live\n * ordinal, so the slots already carrying links are left alone. Undefined when\n * `name` belongs to no autogrow group of this node, or the group's `max` stops\n * short of it.\n */\nexport function growAutogrowInput(\n  node: LGraphNode,\n  name: string\n): number | undefined {\n  if (!hasAutogrowGroups(node)) return undefined\n  const groupName = liveAutogrowGroupOf(node, name)\n  if (groupName === undefined) return undefined\n  const ordinal = resolveAutogrowOrdinal(name, groupName, node)\n  if (ordinal === undefined) return undefined\n  for (\n    let next = highestAutogrowOrdinal(node, groupName) + 1;\n    next <= ordinal;\n    next++\n  ) {\n    addAutogrowGroup(next, groupName, node)\n  }\n  const index = node.inputs.findIndex((input) => input.name === name)\n  return index === -1 ? undefined : index\n}\n\nfunction autogrowInputDisconnected(index: number, node: AutogrowNode) {\n  const input = node.inputs.at(index)\n  if (!input) return\n  //The slot was reconnected before this deferred compaction ran (e.g. a\n  //connect/disconnect/reconnect sequence in immediate succession); the\n  //compaction is stale and must not run against the slot's new link.\n  if (node.getInputLink(index)) return\n  const groupName = input.name.slice(0, input.name.lastIndexOf('.'))\n  const autogrowGroup = Object.hasOwn(node.comfyDynamic.autogrow, groupName)\n    ? node.comfyDynamic.autogrow[groupName]\n    : undefined\n  if (!autogrowGroup) return\n\n  const { min, inputSpecs } = autogrowGroup\n  const ordinal = resolveAutogrowOrdinal(input.name, groupName, node)\n  if (ordinal == undefined || ordinal + 1 < min) return\n\n  //resolve all inputs in group\n  const groupInputs = node.inputs.filter(\n    (inp) =>\n      inp.name.startsWith(groupName + '.') &&\n      inp.name.lastIndexOf('.') === groupName.length\n  )\n  const stride = inputSpecs.length\n  if (stride + index >= node.inputs.length) return\n  if (groupInputs.length % stride !== 0) {\n    console.error('Failed to group multi-input autogrow inputs')\n    return\n  }\n  node.graph?.setDirtyCanvas(true, true)\n  const previous = captureInputLayout(node)\n  const inputLinks = new Map(previous.links)\n  const transplants: { input: INodeInputSlot; link: LLink }[] = []\n\n  for (let column = 0; column < stride; column++) {\n    for (\n      let bubbleOrdinal = ordinal * stride + column;\n      bubbleOrdinal + stride < groupInputs.length;\n      bubbleOrdinal += stride\n    ) {\n      const input = groupInputs[bubbleOrdinal]\n      const donor = groupInputs[bubbleOrdinal + stride]\n      const link = inputLinks.get(donor)\n      inputLinks.delete(input)\n      inputLinks.delete(donor)\n      if (link) {\n        inputLinks.set(input, link)\n        transplants.push({ input, link })\n      }\n    }\n  }\n\n  const removalChecks = groupInputs.slice(min * stride)\n  let i\n  for (i = removalChecks.length - stride; i >= 0; i -= stride) {\n    if (\n      removalChecks.slice(i, i + stride).some((input) => inputLinks.has(input))\n    )\n      break\n  }\n  const toRemove = removalChecks.slice(i + stride * 2)\n  const finalInputs = node.inputs.filter((input) => !toRemove.includes(input))\n  const result = replaceNodeInputs(node, previous, finalInputs, inputLinks)\n  if (!result.ok) return\n\n  for (const { input, link } of transplants) {\n    const slot = node.inputs.indexOf(input)\n    if (slot === -1) continue\n    node.onConnectionsChange(LiteGraph.INPUT, slot, true, link, input)\n  }\n  for (const input of toRemove) {\n    const widgetName = input.widget?.name\n    if (!widgetName) continue\n    for (const widget of remove(node.widgets, (w) => w.name === widgetName)) {\n      widget.onRemove?.()\n      if (widget.widgetId) useWidgetValueStore().deleteWidget(widget.widgetId)\n    }\n    syncNodeWidgetOrder(node)\n  }\n  node.size = [node.size[0], node.computeSize([...node.size])[1]]\n}\n\nfunction withComfyAutogrow(node: LGraphNode): asserts node is AutogrowNode {\n  if (node.comfyDynamic?.autogrow) return\n  node.comfyDynamic ??= {}\n  node.comfyDynamic.autogrow = {}\n\n  let pendingConnection: number | undefined\n  //Whether the input-side `connect` event for `pendingConnection` has\n  //already fired. `connectSlots` (LGraphNode.ts) calls `onConnectInput`\n  //synchronously before it does anything else, then - only when the slot\n  //is replacing an existing link (a real swap) - fires the *disconnect*\n  //event for the old link before the *connect* event for the new one, all\n  //in the same synchronous call. So a disconnect that arrives for\n  //`pendingConnection` before its connect event has been seen is the\n  //synchronous tail of that swap. A disconnect that arrives *after* the\n  //connect event has already fired is a separate, later operation (e.g.\n  //the user - or an agent applying CRDT ops with no render yield between\n  //them - immediately disconnecting the slot it just connected) and must\n  //not be mistaken for a swap just because it lands within the same\n  //rAF-bounded window (PM-1496).\n  let pendingConnectionSeen = false\n  //Which slot, if any, is mid a same-slot swap: `connectSlots` just fired\n  //that slot's disconnect (the swap's tail, detected above) and its\n  //matching connect event is expected synchronously right after. Scoped\n  //to a single slot - not node-wide - so a genuine connect on a\n  //*different* slot of this node in between is never mistaken for the\n  //swap's own connect and silently dropped. Cleared deterministically by\n  //the connection lifecycle itself (the matching connect event) rather\n  //than solely by a frame boundary, so it cannot stay armed indefinitely\n  //while `requestAnimationFrame` is suspended (e.g. a hidden background\n  //tab); the frame-boundary reset below is only a defensive fallback.\n  let swappingSlot: number | undefined\n\n  const originalOnConnectInput = node.onConnectInput\n  node.onConnectInput = function (slot: number, ...args) {\n    pendingConnection = slot\n    pendingConnectionSeen = false\n    requestAnimationFrame(() => {\n      pendingConnection = undefined\n      pendingConnectionSeen = false\n    })\n    return originalOnConnectInput?.apply(this, [slot, ...args]) ?? true\n  }\n\n  node.onConnectionsChange = useChainCallback(\n    node.onConnectionsChange,\n    function (\n      this: AutogrowNode,\n      contype: ISlotType,\n      slot: number,\n      iscon: boolean,\n      linf: LLink | null | undefined\n    ) {\n      const input = this.inputs.at(slot)\n      if (contype !== LiteGraph.INPUT || !input) return\n      //Return if input isn't known autogrow\n      const key = input.name.slice(0, input.name.lastIndexOf('.'))\n      const autogrowGroup = Object.hasOwn(this.comfyDynamic.autogrow, key)\n        ? this.comfyDynamic.autogrow[key]\n        : undefined\n      if (!autogrowGroup) return\n      if (useApp().configuringGraph && input.widget)\n        ensureWidgetForInput(node, input)\n      if (iscon) {\n        if (pendingConnection === slot) pendingConnectionSeen = true\n        if (swappingSlot === slot) {\n          swappingSlot = undefined\n          return\n        }\n        if (!linf) return\n        autogrowInputConnected(slot, this)\n      } else {\n        if (pendingConnection === slot && !pendingConnectionSeen) {\n          swappingSlot = slot\n          requestAnimationFrame(() => {\n            if (swappingSlot === slot) swappingSlot = undefined\n          })\n          return\n        }\n        requestAnimationFrame(() => autogrowInputDisconnected(slot, this))\n      }\n    }\n  )\n}\nfunction applyAutogrow(node: LGraphNode, inputSpecV2: InputSpecV2) {\n  withComfyAutogrow(node)\n\n  const parseResult = zAutogrowOptions.safeParse(inputSpecV2)\n  if (!parseResult.success) throw new Error('invalid Autogrow spec')\n  const inputSpec = parseResult.data\n  const { input, min = 1, names, prefix, max = 100 } = inputSpec.template\n\n  const inputTypes: (Record<string, InputSpec> | undefined)[] = [\n    input.required,\n    input.optional\n  ]\n  const inputsV2 = inputTypes.flatMap((inputType, index) =>\n    Object.entries(inputType ?? {}).map(([name, v]) =>\n      transformInputSpecV1ToV2(v, { name, isOptional: index === 1 })\n    )\n  )\n  node.comfyDynamic.autogrow[inputSpecV2.name] = {\n    names,\n    min,\n    max: names?.length ?? max,\n    prefix,\n    inputSpecs: inputsV2\n  }\n  for (let i = 0; i === 0 || i < min + 1; i++)\n    addAutogrowGroup(i, inputSpecV2.name, node)\n}\n","import {\n  isMiddleButtonEvent,\n  isMiddleButtonHeld,\n  isMiddlePointerInput\n} from '@/base/pointerUtils'\nimport { useApp } from '@/scripts/appInstance'\n\nexport function forwardMiddleButtonToCanvas(\n  inputEl: HTMLElement,\n  signal: AbortSignal\n): void {\n  inputEl.addEventListener(\n    'pointerdown',\n    (event) => {\n      if (isMiddlePointerInput(event)) useApp().canvas.processMouseDown(event)\n    },\n    { signal }\n  )\n\n  inputEl.addEventListener(\n    'pointermove',\n    (event) => {\n      if (isMiddleButtonHeld(event)) useApp().canvas.processMouseMove(event)\n    },\n    { signal }\n  )\n\n  inputEl.addEventListener(\n    'pointerup',\n    (event) => {\n      if (isMiddleButtonEvent(event)) useApp().canvas.processMouseUp(event)\n    },\n    { signal }\n  )\n}\n","import { useChainCallback } from '@/composables/functional/useChainCallback'\nimport type { INodeInputSlot, LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { forwardMiddleButtonToCanvas } from '@/renderer/extensions/vueNodes/widgets/utils/forwardMiddleButtonToCanvas'\nimport { useApp } from '@/scripts/appInstance'\nimport { DOMWidgetImpl, isDOMWidget } from '@/scripts/domWidget'\nimport type { BaseDOMWidget } from '@/scripts/domWidget'\nimport { useDomWidgetStore } from '@/stores/domWidgetStore'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\nimport type { WidgetId } from '@/types/widgetId'\n\nconst TRACKPAD_DETECTION_THRESHOLD = 50\n\n/** Creates the `<textarea>` element backing a `customtext` multiline widget. */\nexport function createMultilineInputElement(\n  value: string,\n  placeholder: string\n): HTMLTextAreaElement {\n  const element = document.createElement('textarea')\n  element.className = 'comfy-multiline-input'\n  element.dataset.testid = 'dom-widget-textarea'\n  element.value = value\n  element.placeholder = placeholder\n  element.spellcheck = useSettingStore().get('Comfy.TextareaWidget.Spellcheck')\n  return element\n}\n\n/**\n * Wires textarea value propagation, trackpad gestures, and middle-button canvas\n * panning onto a `customtext` DOM widget, torn down via the widget's `onRemove`.\n */\nexport function bindMultilineTextareaWidget(\n  widget: BaseDOMWidget<string>,\n  element: HTMLTextAreaElement\n): void {\n  const controller = new AbortController()\n  const { signal } = controller\n\n  element.addEventListener(\n    'input',\n    () => {\n      widget.value = element.value\n      widget.callback?.(widget.value)\n    },\n    { signal }\n  )\n\n  forwardMiddleButtonToCanvas(element, signal)\n\n  element.addEventListener(\n    'wheel',\n    (event: WheelEvent) => {\n      const gesturesEnabled = useSettingStore().get(\n        'LiteGraph.Pointer.TrackpadGestures'\n      )\n      const deltaX = event.deltaX\n      const deltaY = event.deltaY\n\n      const canScrollY = element.scrollHeight > element.clientHeight\n      const isHorizontal = Math.abs(deltaX) > Math.abs(deltaY)\n\n      // Prevent pinch zoom from zooming the page\n      if (event.ctrlKey) {\n        event.preventDefault()\n        event.stopPropagation()\n        useApp().canvas.processMouseWheel(event)\n        return\n      }\n\n      // Detect if this is likely a trackpad gesture vs mouse wheel\n      // Trackpads usually have deltaX or smaller deltaY values (< TRACKPAD_DETECTION_THRESHOLD)\n      // Mouse wheels typically have larger discrete deltaY values (>= TRACKPAD_DETECTION_THRESHOLD)\n      const isLikelyTrackpad =\n        Math.abs(deltaX) > 0 || Math.abs(deltaY) < TRACKPAD_DETECTION_THRESHOLD\n\n      // Trackpad gestures: when enabled, trackpad panning goes to canvas\n      if (gesturesEnabled && isLikelyTrackpad) {\n        event.preventDefault()\n        event.stopPropagation()\n        useApp().canvas.processMouseWheel(event)\n        return\n      }\n\n      // When gestures disabled: horizontal always goes to canvas (no horizontal scroll in textarea)\n      if (isHorizontal) {\n        event.preventDefault()\n        event.stopPropagation()\n        useApp().canvas.processMouseWheel(event)\n        return\n      }\n\n      // Vertical scrolling when gestures disabled: let textarea scroll if scrollable\n      if (canScrollY) {\n        event.stopPropagation()\n        return\n      }\n\n      // If textarea can't scroll vertically, pass to canvas\n      event.preventDefault()\n      useApp().canvas.processMouseWheel(event)\n    },\n    { signal }\n  )\n\n  widget.onRemove = useChainCallback(widget.onRemove, () => {\n    controller.abort()\n  })\n}\n\ninterface PromotedMultilineWidgetContext {\n  subgraphNode: LGraphNode\n  input: INodeInputSlot\n  widgetId: WidgetId\n  sourceWidget: Readonly<IBaseWidget>\n}\n\n/**\n * Builds the promoted textarea as a host-owned DOM widget, registered directly\n * with the DOM widget store since `SubgraphNode.widgets` is a projected getter.\n * Returns undefined to fall back to the store-backed projection.\n */\nexport function createPromotedMultilineWidget(\n  context: PromotedMultilineWidgetContext\n): IBaseWidget | undefined {\n  const { subgraphNode, input, widgetId, sourceWidget } = context\n\n  // Only materialize once the host node is settled in its graph; clone/configure\n  // run with a transient id and would leak duplicate DOM widgets.\n  const graph = subgraphNode.graph\n  if (!graph || graph.getNodeById(subgraphNode.id) !== subgraphNode)\n    return undefined\n  if (!isDOMWidget(sourceWidget)) return undefined\n  if (!(sourceWidget.element instanceof HTMLTextAreaElement)) return undefined\n\n  const widgetStore = useWidgetValueStore()\n\n  const readValue = (): string => {\n    const value = widgetStore.getWidget(widgetId)?.value\n    return typeof value === 'string' ? value : ''\n  }\n\n  const element = createMultilineInputElement(\n    readValue(),\n    input.label ?? input.name\n  )\n\n  const widget = new DOMWidgetImpl<HTMLTextAreaElement, string>({\n    node: subgraphNode,\n    name: input.name,\n    type: 'customtext',\n    element,\n    options: {\n      hideOnZoom: true,\n      minNodeSize: [400, 200],\n      getValue: readValue,\n      setValue: (value: string) => {\n        element.value = value\n        widgetStore.setValue(widgetId, value)\n      }\n    }\n  })\n\n  bindMultilineTextareaWidget(widget, element)\n  useDomWidgetStore().registerWidget(widget)\n\n  return widget\n}\n","import type { PromotedWidgetSource } from '@/core/graph/subgraph/promotedWidgetTypes'\nimport type { NodeId } from '@/types/nodeId'\n\nexport interface SubgraphPseudoWidget {\n  name: string\n}\n\nexport interface SubgraphPseudoWidgetNode<\n  TWidget extends SubgraphPseudoWidget\n> {\n  id: string | number\n  widgets?: TWidget[]\n}\n\ninterface SubgraphPseudoWidgetCacheEntry<\n  TNode extends SubgraphPseudoWidgetNode<TWidget>,\n  TWidget extends SubgraphPseudoWidget\n> {\n  sourceNodeId: NodeId\n  sourceWidgetName: string\n  node: TNode\n}\n\nexport interface SubgraphPseudoWidgetCache<\n  TNode extends SubgraphPseudoWidgetNode<TWidget>,\n  TWidget extends SubgraphPseudoWidget\n> {\n  promotions: readonly PromotedWidgetSource[]\n  entries: SubgraphPseudoWidgetCacheEntry<TNode, TWidget>[]\n  nodes: TNode[]\n}\n\ninterface ResolveSubgraphPseudoWidgetCacheArgs<\n  TNode extends SubgraphPseudoWidgetNode<TWidget>,\n  TWidget extends SubgraphPseudoWidget\n> {\n  cache: SubgraphPseudoWidgetCache<TNode, TWidget> | null\n  promotions: readonly PromotedWidgetSource[]\n  getNodeById: (nodeId: NodeId) => TNode | undefined\n  isPreviewPseudoWidget: (widget: TWidget) => boolean\n}\n\ninterface ResolveSubgraphPseudoWidgetCacheResult<\n  TNode extends SubgraphPseudoWidgetNode<TWidget>,\n  TWidget extends SubgraphPseudoWidget\n> {\n  cache: SubgraphPseudoWidgetCache<TNode, TWidget>\n  nodes: TNode[]\n}\n\nfunction isPseudoPromotion<TWidget extends SubgraphPseudoWidget>(\n  widgetName: string,\n  widgets: TWidget[] | undefined,\n  isPreviewPseudoWidget: (widget: TWidget) => boolean\n): boolean {\n  const widget = widgets?.find((candidate) => candidate.name === widgetName)\n  if (widget) return isPreviewPseudoWidget(widget)\n  return widgetName.startsWith('$$')\n}\n\nfunction isCacheStillValid<\n  TNode extends SubgraphPseudoWidgetNode<TWidget>,\n  TWidget extends SubgraphPseudoWidget\n>(\n  cache: SubgraphPseudoWidgetCache<TNode, TWidget>,\n  getNodeById: (nodeId: NodeId) => TNode | undefined,\n  isPreviewPseudoWidget: (widget: TWidget) => boolean\n): boolean {\n  return cache.entries.every((entry) => {\n    const currentNode = getNodeById(entry.sourceNodeId)\n    if (!currentNode || currentNode !== entry.node) return false\n    return isPseudoPromotion(\n      entry.sourceWidgetName,\n      currentNode.widgets,\n      isPreviewPseudoWidget\n    )\n  })\n}\n\nexport function resolveSubgraphPseudoWidgetCache<\n  TNode extends SubgraphPseudoWidgetNode<TWidget>,\n  TWidget extends SubgraphPseudoWidget\n>(\n  args: ResolveSubgraphPseudoWidgetCacheArgs<TNode, TWidget>\n): ResolveSubgraphPseudoWidgetCacheResult<TNode, TWidget> {\n  const { cache, promotions, getNodeById, isPreviewPseudoWidget } = args\n\n  if (\n    cache &&\n    cache.promotions === promotions &&\n    isCacheStillValid(cache, getNodeById, isPreviewPseudoWidget)\n  )\n    return { cache, nodes: cache.nodes }\n\n  const entries = promotions.flatMap((promotion) => {\n    const node = getNodeById(promotion.sourceNodeId)\n    if (!node) return []\n    if (\n      !isPseudoPromotion(\n        promotion.sourceWidgetName,\n        node.widgets,\n        isPreviewPseudoWidget\n      )\n    )\n      return []\n    return [{ ...promotion, node }]\n  })\n\n  const nextCache: SubgraphPseudoWidgetCache<TNode, TWidget> = {\n    promotions,\n    entries,\n    nodes: entries.map((entry) => entry.node)\n  }\n  return {\n    cache: nextCache,\n    nodes: nextCache.nodes\n  }\n}\n","import type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { ResultItem } from '@/platform/remote/comfyui/execution/types'\nimport { useApp } from '@/scripts/appInstance'\nimport { useNodeOutputStore } from '@/stores/nodeOutputStore'\n\nexport type Clipspace = {\n  widgets?: Pick<IBaseWidget, 'type' | 'name' | 'value'>[] | null\n  imgs?: HTMLImageElement[] | null\n  original_imgs?: HTMLImageElement[] | null\n  images?: ResultItem[] | null\n  selectedIndex: number\n  img_paste_mode: string\n  paintedIndex: number\n  combinedIndex?: number\n}\n\n/**\n * Content clipboard shared by the mask editor and clipspace extensions.\n * `ComfyApp` exposes it as static members for custom-node compatibility.\n */\nexport const clipspace: {\n  current: Clipspace | null\n  invalidateHandler: (() => void) | null\n  returnNode: LGraphNode | null\n  maskEditorIsOpened: (() => boolean) | null\n} = {\n  current: null,\n  invalidateHandler: null,\n  returnNode: null,\n  maskEditorIsOpened: null\n}\n\nexport function copyToClipspace(node: LGraphNode) {\n  let widgets = null\n  if (node.widgets) {\n    widgets = node.widgets.map(({ type, name, value }) => ({\n      type,\n      name,\n      value\n    }))\n  }\n\n  let imgs = undefined\n  let orig_imgs = undefined\n  if (node.imgs != undefined) {\n    imgs = []\n    orig_imgs = []\n\n    for (let i = 0; i < node.imgs.length; i++) {\n      imgs[i] = new Image()\n      imgs[i].src = node.imgs[i].src\n      orig_imgs[i] = imgs[i]\n    }\n  }\n\n  let selectedIndex = 0\n  if (node.imageIndex) {\n    selectedIndex = node.imageIndex\n  }\n\n  const paintedIndex = imgs ? imgs.length + 1 : 1\n  const combinedIndex = imgs ? imgs.length + 2 : 2\n\n  // for vueNodes mode\n  const images = useNodeOutputStore().getNodeOutputs(node)?.images\n\n  clipspace.current = {\n    widgets: widgets,\n    imgs: imgs,\n    original_imgs: orig_imgs,\n    images: images,\n    selectedIndex: selectedIndex,\n    img_paste_mode: 'selected', // reset to default im_paste_mode state on copy action\n    paintedIndex: paintedIndex,\n    combinedIndex: combinedIndex\n  }\n\n  clipspace.returnNode = null\n\n  if (clipspace.invalidateHandler) {\n    clipspace.invalidateHandler()\n  }\n}\n\nexport function pasteFromClipspace(node: LGraphNode) {\n  if (clipspace.current) {\n    // image paste\n    let combinedImgSrc: string | undefined\n    if (\n      clipspace.current.combinedIndex !== undefined &&\n      clipspace.current.imgs &&\n      clipspace.current.combinedIndex < clipspace.current.imgs.length\n    ) {\n      combinedImgSrc =\n        clipspace.current.imgs[clipspace.current.combinedIndex].src\n    }\n    const selectedImage =\n      clipspace.current.images?.[clipspace.current.selectedIndex]\n    if (clipspace.current.images) {\n      if (clipspace.current.img_paste_mode !== 'selected') {\n        useNodeOutputStore().setNodeOutputImages(node, clipspace.current.images)\n      } else if (selectedImage) {\n        useNodeOutputStore().setNodeOutputImages(node, [selectedImage])\n      }\n    }\n    if (clipspace.current.imgs && node.imgs) {\n      // deep-copy to cut link with clipspace\n      if (clipspace.current['img_paste_mode'] == 'selected') {\n        const selectedPreview = clipspace.current.imgs.at(\n          clipspace.current.selectedIndex\n        )\n        if (clipspace.current.selectedIndex >= 0 && selectedPreview) {\n          const img = new Image()\n          img.src = selectedPreview.src\n          node.imgs = [img]\n          node.imageIndex = 0\n        }\n      } else {\n        const imgs = []\n        for (let i = 0; i < clipspace.current.imgs.length; i++) {\n          imgs[i] = new Image()\n          imgs[i].src = clipspace.current.imgs[i].src\n          node.imgs = imgs\n        }\n      }\n    }\n\n    // Paste the RGB canvas if paintedindex exists\n    if (clipspace.current.imgs?.[clipspace.current.paintedIndex] && node.imgs) {\n      const paintedImg = new Image()\n      paintedImg.src =\n        clipspace.current.imgs[clipspace.current.paintedIndex].src\n      node.imgs.push(paintedImg) // Add the RGB canvas to the node's images\n    }\n\n    // Store only combined image inside the node if it exists\n    if (node.imgs && combinedImgSrc) {\n      const combinedImg = new Image()\n      combinedImg.src = combinedImgSrc\n      node.imgs = [combinedImg]\n    }\n\n    if (node.widgets) {\n      if (selectedImage) {\n        const index = node.widgets.findIndex((obj) => obj.name === 'image')\n        if (index >= 0) {\n          if (\n            node.widgets[index].type != 'image' &&\n            typeof node.widgets[index].value == 'string' &&\n            selectedImage.filename\n          ) {\n            node.widgets[index].value =\n              (selectedImage.subfolder ? selectedImage.subfolder + '/' : '') +\n              selectedImage.filename +\n              (selectedImage.type ? ` [${selectedImage.type}]` : '')\n          } else {\n            node.widgets[index].value = selectedImage\n          }\n        }\n      }\n      if (clipspace.current.widgets) {\n        clipspace.current.widgets.forEach(({ type, name, value }) => {\n          const prop = node.widgets?.find(\n            (obj) => obj.type === type && obj.name === name\n          )\n          if (prop && prop.type != 'button') {\n            const valueObj = value as Record<string, unknown> | undefined\n            if (\n              prop.type != 'image' &&\n              typeof prop.value == 'string' &&\n              valueObj?.filename\n            ) {\n              const resultItem = value as ResultItem\n              prop.value =\n                (resultItem.subfolder ? resultItem.subfolder + '/' : '') +\n                resultItem.filename +\n                (resultItem.type ? ` [${resultItem.type}]` : '')\n            } else {\n              prop.value = value\n              prop.callback?.(value)\n            }\n          }\n        })\n      }\n    }\n\n    useApp().canvas.setDirty(true)\n  }\n}\n","import { resolveNodeDefText } from '@/i18n'\n\ntype NodeTitleInfo = {\n  title?: string | number | null\n  type?: string | number | null\n}\n\ntype ResolveNodeDisplayNameOptions = {\n  emptyLabel: string\n  untitledLabel: string\n}\n\nexport function resolveNodeDisplayName(\n  node: NodeTitleInfo | null | undefined,\n  options: ResolveNodeDisplayNameOptions\n): string {\n  if (!node) return options.emptyLabel\n\n  const title = (node.title ?? '').toString().trim()\n  if (title.length > 0) return title\n\n  const nodeType = (node.type ?? '').toString().trim() || options.untitledLabel\n  return resolveNodeDefText('display_name', nodeType)\n}\n","import { defineStore } from 'pinia'\nimport { computed, ref, watch } from 'vue'\n\nimport { st } from '@/i18n'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { useApp } from '@/scripts/appInstance'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { isNodeLocatorId } from '@/types/nodeIdentification'\nimport type { NodeLocatorId } from '@/types/nodeIdentification'\nimport { parseNodeId } from '@/types/nodeId'\nimport { getNodeByLocatorId } from '@/utils/graphTraversalUtil'\nimport { resolveNodeDisplayName } from '@/utils/nodeTitleUtil'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\n\n/**\n * Unique identifier for a favorited widget.\n * Combines node locator ID and widget name to locate a widget in the graph.\n */\ninterface FavoritedWidgetId {\n  /** The node locator ID in the graph */\n  nodeLocatorId: NodeLocatorId\n  /** The widget name on the node */\n  widgetName: string\n}\n\n/**\n * A favorited widget with its resolved runtime instance.\n * The widget instance may be null if the node or widget no longer exists.\n */\ninterface FavoritedWidget extends FavoritedWidgetId {\n  /** The resolved node instance (null if node was deleted) */\n  node: LGraphNode | null\n  /** The resolved widget instance (null if widget no longer exists) */\n  widget: IBaseWidget | null\n  /** Display label for the favorited item */\n  label: string\n}\n\nexport interface ValidFavoritedWidget extends FavoritedWidget {\n  node: LGraphNode\n  widget: IBaseWidget\n}\n\n/**\n * Storage format for persisted favorited widgets.\n * Stored in workflow.extra.favoritedWidgets.\n */\ninterface FavoritedWidgetStorage {\n  /** Array of favorited widget identifiers */\n  favorites: FavoritedWidgetId[]\n}\n\n/**\n * Store for managing favorited/starred widgets.\n *\n * Favorited widgets can be accessed and edited from the right side panel\n * without needing to select the corresponding node. This store manages:\n * - Persisting favorited widget IDs per workflow\n * - Resolving widget IDs to actual widget instances\n * - Handling cases where nodes/widgets are deleted\n *\n * Design decisions:\n * - Scope: Per-workflow (not global user preference)\n * - Identifier: node locator ID + widget.name\n * - Persistence: Stored in workflow.extra.favoritedWidgets (serialized with workflow)\n * - Future: Can be extended for Linear Mode\n */\nexport const useFavoritedWidgetsStore = defineStore('favoritedWidgets', () => {\n  const workflowStore = useWorkflowStore()\n  const canvasStore = useCanvasStore()\n\n  /** In-memory array of favorited widget IDs, ordered for display */\n  const favoritedIds = ref<string[]>([])\n\n  // TODO(ADR-SUBGRAPH-PROMOTION-0009): key favorites by the host-scoped WidgetId instead of\n  // (nodeLocatorId, widgetName). That drops the isShownOnParents/favoriteNode\n  // indirection for promoted widgets. Deferred: needs a one-time migration of\n  // the persisted workflow.extra.favoritedWidgets format.\n  /**\n   * Generate a unique string key for a favorited widget ID.\n   */\n  function getFavoriteKey(id: FavoritedWidgetId): string {\n    return JSON.stringify([id.nodeLocatorId, id.widgetName])\n  }\n\n  /**\n   * Parse a favorite key back into a FavoritedWidgetId.\n   */\n  function parseFavoriteKey(key: string): FavoritedWidgetId | null {\n    try {\n      const [nodeLocatorId, widgetName] = JSON.parse(key) as [string, string]\n      if (!isNodeLocatorId(nodeLocatorId) || !widgetName) return null\n      return { nodeLocatorId, widgetName }\n    } catch {\n      const separatorIndex = key.indexOf(':')\n      if (separatorIndex === -1) return null\n      const nodeLocatorId = key.slice(0, separatorIndex)\n      const widgetName = key.slice(separatorIndex + 1)\n      if (!isNodeLocatorId(nodeLocatorId) || !widgetName) return null\n      return { nodeLocatorId, widgetName }\n    }\n  }\n\n  function normalizeFavoritedId(\n    id: FavoritedWidgetId | { nodeId?: unknown; widgetName?: unknown } | null\n  ): FavoritedWidgetId | null {\n    if (!id || !id.widgetName) return null\n\n    if ('nodeLocatorId' in id && id.nodeLocatorId) {\n      if (!isNodeLocatorId(id.nodeLocatorId)) return null\n      return {\n        nodeLocatorId: id.nodeLocatorId,\n        widgetName: id.widgetName\n      }\n    }\n\n    if ('nodeId' in id && id.nodeId !== undefined) {\n      const parsedNodeId = parseNodeId(id.nodeId)\n      if (!parsedNodeId) return null\n      return {\n        nodeLocatorId: workflowStore.nodeIdToNodeLocatorId(parsedNodeId),\n        widgetName: String(id.widgetName)\n      }\n    }\n\n    return null\n  }\n\n  function createFavoriteId(\n    node: LGraphNode,\n    widgetName: string\n  ): FavoritedWidgetId {\n    return {\n      nodeLocatorId: workflowStore.nodeToNodeLocatorId(node),\n      widgetName\n    }\n  }\n\n  /**\n   * Load favorited widgets from the current workflow's extra data.\n   */\n  function loadFromWorkflow() {\n    const graph = useApp().rootGraphOrUndefined\n    if (!graph) return\n\n    try {\n      const storedData = graph.extra.favoritedWidgets as\n        | FavoritedWidgetStorage\n        | undefined\n\n      if (storedData?.favorites) {\n        const normalized = storedData.favorites\n          .map((fav) => normalizeFavoritedId(fav))\n          .filter((fav): fav is FavoritedWidgetId => fav !== null)\n        favoritedIds.value = normalized.map(getFavoriteKey)\n      } else {\n        favoritedIds.value = []\n      }\n    } catch (error) {\n      console.error('Failed to load favorited widgets from workflow:', error)\n      favoritedIds.value = []\n    }\n  }\n\n  /**\n   * Save favorited widgets to the current workflow's extra data.\n   * Marks the workflow as modified.\n   */\n  function saveToWorkflow() {\n    const graph = useApp().rootGraphOrUndefined\n    if (!graph) return\n\n    try {\n      const favorites: FavoritedWidgetId[] = favoritedIds.value\n        .map(parseFavoriteKey)\n        .filter((id): id is FavoritedWidgetId => id !== null)\n\n      const data: FavoritedWidgetStorage = { favorites }\n\n      graph.extra.favoritedWidgets = data\n\n      // Mark the workflow as modified\n      canvasStore.canvas?.setDirty(true, true)\n    } catch (error) {\n      console.error('Failed to save favorited widgets to workflow:', error)\n    }\n  }\n\n  /**\n   * Resolve a favorited widget ID to its actual widget instance.\n   * Returns null if the node or widget no longer exists.\n   */\n  function resolveWidget(id: FavoritedWidgetId): FavoritedWidget {\n    const graph = useApp().rootGraphOrUndefined\n    if (!graph) {\n      return { ...id, node: null, widget: null, label: id.widgetName }\n    }\n\n    const node = getNodeByLocatorId(graph, id.nodeLocatorId)\n    if (!node) {\n      return {\n        ...id,\n        node: null,\n        widget: null,\n        label: `${id.widgetName} (node deleted)`\n      }\n    }\n\n    const widget = node.widgets?.find((w) => w.name === id.widgetName)\n    if (!widget) {\n      return {\n        ...id,\n        node,\n        widget: null,\n        label: `${id.widgetName} (widget not found)`\n      }\n    }\n\n    const fallbackNodeTitle = st('rightSidePanel.fallbackNodeTitle', 'Node')\n    const nodeTitle = resolveNodeDisplayName(node, {\n      emptyLabel: fallbackNodeTitle,\n      untitledLabel: fallbackNodeTitle\n    })\n    const widgetLabel = widget.label || widget.name\n    return {\n      ...id,\n      node,\n      widget,\n      label: `${nodeTitle} / ${widgetLabel}`\n    }\n  }\n\n  /**\n   * Get all favorited widgets with their resolved instances.\n   * Widgets that no longer exist will have null node/widget properties.\n   */\n  const favoritedWidgets = computed((): FavoritedWidget[] => {\n    return favoritedIds.value\n      .map(parseFavoriteKey)\n      .filter((id): id is FavoritedWidgetId => id !== null)\n      .map(resolveWidget)\n  })\n\n  /**\n   * Get only the valid favorited widgets (where both node and widget exist).\n   */\n  const validFavoritedWidgets = computed((): ValidFavoritedWidget[] => {\n    return favoritedWidgets.value.filter(\n      (fw) => fw.node !== null && fw.widget !== null\n    ) as ValidFavoritedWidget[]\n  })\n\n  /**\n   * Check if a widget is favorited.\n   */\n  function isFavorited(node: LGraphNode, widgetName: string): boolean {\n    return favoritedIds.value.includes(\n      getFavoriteKey(createFavoriteId(node, widgetName))\n    )\n  }\n\n  /**\n   * Add a widget to favorites.\n   */\n  function addFavorite(node: LGraphNode, widgetName: string) {\n    const key = getFavoriteKey(createFavoriteId(node, widgetName))\n    if (favoritedIds.value.includes(key)) return\n\n    favoritedIds.value.push(key)\n    saveToWorkflow()\n  }\n\n  /**\n   * Remove a widget from favorites.\n   */\n  function removeFavorite(node: LGraphNode, widgetName: string) {\n    const key = getFavoriteKey(createFavoriteId(node, widgetName))\n    const index = favoritedIds.value.indexOf(key)\n    if (index === -1) return\n\n    favoritedIds.value.splice(index, 1)\n    saveToWorkflow()\n  }\n\n  /**\n   * Toggle a widget's favorite status.\n   */\n  function toggleFavorite(node: LGraphNode, widgetName: string) {\n    if (isFavorited(node, widgetName)) {\n      removeFavorite(node, widgetName)\n    } else {\n      addFavorite(node, widgetName)\n    }\n  }\n\n  /**\n   * Clear all favorites for the current workflow.\n   */\n  function clearFavorites() {\n    favoritedIds.value = []\n    saveToWorkflow()\n  }\n\n  /**\n   * Remove invalid favorites (where node or widget no longer exists).\n   * Useful for cleanup after loading a workflow.\n   */\n  function pruneInvalidFavorites() {\n    const validKeys = validFavoritedWidgets.value.map((fw) =>\n      getFavoriteKey({\n        nodeLocatorId: fw.nodeLocatorId,\n        widgetName: fw.widgetName\n      })\n    )\n    const validSet = new Set(validKeys)\n\n    const filteredIds = favoritedIds.value.filter((key) => validSet.has(key))\n\n    if (filteredIds.length !== favoritedIds.value.length) {\n      favoritedIds.value = filteredIds\n      saveToWorkflow()\n    }\n  }\n\n  /**\n   * Reorder favorites based on the provided array of widgets.\n   * Used when dragging and dropping favorites to reorder them.\n   */\n  function reorderFavorites(reorderedWidgets: ValidFavoritedWidget[]) {\n    favoritedIds.value = reorderedWidgets.map((fw) =>\n      getFavoriteKey({\n        nodeLocatorId: fw.nodeLocatorId,\n        widgetName: fw.widgetName\n      })\n    )\n    saveToWorkflow()\n  }\n\n  // Watch for workflow changes and reload favorites from workflow.extra\n  watch(\n    () => workflowStore.activeWorkflow?.path,\n    () => {\n      loadFromWorkflow()\n    },\n    { immediate: true }\n  )\n\n  return {\n    // State\n    favoritedWidgets,\n    validFavoritedWidgets,\n\n    // Actions\n    isFavorited,\n    addFavorite,\n    removeFavorite,\n    toggleFavorite,\n    clearFavorites,\n    pruneInvalidFavorites,\n    reorderFavorites\n  }\n})\n","import { defineStore } from 'pinia'\nimport { computed, ref, watch } from 'vue'\n\nimport { useSettingStore } from '@/platform/settings/settingStore'\n\nexport type RightSidePanelTab =\n  | 'parameters'\n  | 'nodes'\n  | 'settings'\n  | 'info'\n  | 'subgraph'\n  | 'errors'\n\ntype RightSidePanelSection = 'advanced-inputs'\n\n/**\n * Store for managing the right side panel state.\n * This panel displays properties and settings for selected nodes.\n */\nexport const useRightSidePanelStore = defineStore('rightSidePanel', () => {\n  const settingStore = useSettingStore()\n\n  const isLegacyMenu = computed(\n    () => settingStore.get('Comfy.UseNewMenu') === 'Disabled'\n  )\n\n  const isOpen = computed({\n    get: () =>\n      !isLegacyMenu.value && settingStore.get('Comfy.RightSidePanel.IsOpen'),\n    set: (value: boolean) =>\n      settingStore.set('Comfy.RightSidePanel.IsOpen', value)\n  })\n  const activeTab = ref<RightSidePanelTab>('parameters')\n  const isEditingSubgraph = computed(() => activeTab.value === 'subgraph')\n  const focusedSection = ref<RightSidePanelSection | null>(null)\n  /**\n   * Graph node ID to focus in the errors tab.\n   * Set by SectionWidgets when the user clicks \"See Error\", consumed and\n   * cleared by TabErrors after expanding the relevant error group.\n   */\n  const focusedErrorNodeId = ref<string | null>(null)\n\n  // Auto-close panel when switching to legacy menu mode\n  watch(isLegacyMenu, (legacy) => {\n    if (legacy) {\n      void settingStore.set('Comfy.RightSidePanel.IsOpen', false)\n    }\n  })\n\n  function openPanel(tab?: RightSidePanelTab) {\n    if (isLegacyMenu.value) return\n    isOpen.value = true\n    if (tab) {\n      activeTab.value = tab\n    }\n  }\n\n  function closePanel() {\n    isOpen.value = false\n  }\n\n  function togglePanel() {\n    isOpen.value = !isOpen.value\n  }\n\n  /**\n   * Focus on a specific section in the right side panel.\n   * This will open the panel, switch to the parameters tab, and signal\n   * the component to expand and scroll to the section.\n   */\n  function focusSection(section: RightSidePanelSection) {\n    openPanel('parameters')\n    focusedSection.value = section\n  }\n\n  /**\n   * Clear the focused section after it has been handled.\n   */\n  function clearFocusedSection() {\n    focusedSection.value = null\n  }\n\n  return {\n    isOpen,\n    activeTab,\n    isEditingSubgraph,\n    focusedSection,\n    focusedErrorNodeId,\n    openPanel,\n    closePanel,\n    togglePanel,\n    focusSection,\n    clearFocusedSection\n  }\n})\n","export const IS_CONTROL_WIDGET = Symbol()\n","/**\n * Simplified widget interface for Vue-based node rendering\n * Removes all DOM manipulation and positioning concerns\n */\nimport type { InputSpec as InputSpecV2 } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type {\n  IBaseWidget,\n  IWidgetOptions\n} from '@/lib/litegraph/src/types/widgets'\nimport { IS_CONTROL_WIDGET } from '@/core/graph/widgets/controlWidgetMarker'\nimport type { NodeId } from '@/types/nodeId'\nimport type { NodeLocatorId } from '@/types/nodeIdentification'\n\nexport const CONTROL_OPTIONS = [\n  'fixed',\n  'increment',\n  'decrement',\n  'randomize'\n] as const\nexport type ControlOptions = (typeof CONTROL_OPTIONS)[number]\n\nexport function isControlOption(value: unknown): value is ControlOptions {\n  return CONTROL_OPTIONS.some((option) => option === value)\n}\n\n/** Valid types for widget values */\nexport type WidgetValue = string | number | boolean | object | undefined | null\n\nfunction normalizeControlOption(val: WidgetValue): ControlOptions {\n  if (isControlOption(val)) return val\n  return 'randomize'\n}\n\nexport type SafeControlWidget = {\n  value: ControlOptions\n  update: (value: WidgetValue) => void\n}\n\nexport function getControlWidget(\n  widget: IBaseWidget\n): SafeControlWidget | undefined {\n  const controlWidget = widget.linkedWidgets?.find((w) => w[IS_CONTROL_WIDGET])\n  if (!controlWidget) return\n  return {\n    value: normalizeControlOption(controlWidget.value),\n    update: (value) => (controlWidget.value = normalizeControlOption(value))\n  }\n}\n\nexport interface LinkedUpstreamInfo {\n  nodeId: NodeId\n  outputName?: string\n}\n\nexport interface SimplifiedWidget<\n  T extends WidgetValue = WidgetValue,\n  O extends IWidgetOptions = IWidgetOptions\n> {\n  /** Display name of the widget */\n  name: string\n\n  /** Widget type identifier (e.g., 'STRING', 'INT', 'COMBO') */\n  type: string\n\n  /** Current value of the widget */\n  value: T\n\n  borderStyle?: string\n\n  /** Callback fired when value changes */\n  callback?: (value: T) => void\n\n  /** Optional method to compute widget size requirements */\n  computeSize?: () => { minHeight: number; maxHeight?: number }\n\n  /** Localized display label (falls back to name if not provided) */\n  label?: string\n\n  displayLabel?: string\n\n  /** Widget options including filtered PrimeVue props */\n  options?: O\n\n  /** Override for use with subgraph promoted asset widgets*/\n  nodeType?: string\n\n  /** Optional serialization method for custom value handling */\n  serializeValue?: () => unknown\n\n  /** NodeLocatorId for the node that owns this widget's execution outputs */\n  nodeLocatorId?: NodeLocatorId\n\n  /** Optional input specification backing this widget */\n  spec?: InputSpecV2\n\n  tooltip?: string\n\n  controlWidget?: SafeControlWidget\n\n  linkedUpstream?: LinkedUpstreamInfo\n}\n\nexport interface SimplifiedControlWidget<\n  T extends WidgetValue = WidgetValue,\n  O extends IWidgetOptions = IWidgetOptions\n> extends SimplifiedWidget<T, O> {\n  controlWidget: SafeControlWidget\n}\n","import { isComboWidget } from '@/lib/litegraph/src/litegraph'\nimport type {\n  IBaseWidget,\n  IComboWidget\n} from '@/lib/litegraph/src/types/widgets'\nimport { findComboValueIndex } from '@/lib/litegraph/src/utils/widget'\nimport type { ControlOptions } from '@/types/simplifiedWidget'\nimport { isControlOption } from '@/types/simplifiedWidget'\n\nimport { IS_CONTROL_WIDGET } from './controlWidgetMarker'\n\ntype ValueControlMode = ControlOptions | 'increment-wrap'\n\nexport function isValueControlMode(value: unknown): value is ValueControlMode {\n  return isControlOption(value) || value === 'increment-wrap'\n}\n\nexport function nextValueForLinkedTarget(params: {\n  target: IBaseWidget\n  linkedWidgets: IBaseWidget[] | undefined\n  nodeId: unknown\n}): IBaseWidget['value'] | undefined {\n  const linked = params.linkedWidgets\n  if (!linked) return undefined\n\n  const controlWidget = linked.find(isValueControlWidget)\n  if (!controlWidget) return undefined\n\n  const comboFilter = linked.find(\n    (w) => w !== controlWidget && w.type === 'string'\n  )\n  const filterValue =\n    typeof comboFilter?.value === 'string' ? comboFilter.value : undefined\n\n  const mode = controlWidget.value as ValueControlMode\n  return computeNextControlledValue(params.target, mode, {\n    comboFilter: filterValue,\n    nodeId: params.nodeId\n  })\n}\n\nconst SAFE_INTEGER_MAX = 1125899906842624\nconst SAFE_INTEGER_MIN = -1125899906842624\n\nexport function isValueControlWidget(widget: IBaseWidget): boolean {\n  return (\n    (widget as Record<symbol, unknown>)[IS_CONTROL_WIDGET] === true &&\n    typeof widget.beforeQueued === 'function' &&\n    typeof widget.afterQueued === 'function'\n  )\n}\n\nfunction buildComboFilter(\n  filter: string | undefined,\n  nodeId?: unknown\n): ((item: string) => boolean) | undefined {\n  if (!filter) return undefined\n\n  if (filter.startsWith('/') && filter.endsWith('/')) {\n    try {\n      const regex = new RegExp(filter.substring(1, filter.length - 1))\n      return (item: string) => regex.test(item)\n    } catch (error) {\n      console.error(\n        'Error constructing RegExp filter for node ' + String(nodeId),\n        filter,\n        error\n      )\n    }\n  }\n\n  const lower = filter.toLocaleLowerCase()\n  return (item: string) => item.toLocaleLowerCase().includes(lower)\n}\n\nexport function computeNextControlledValue(\n  target: IBaseWidget,\n  mode: ValueControlMode,\n  options: { comboFilter?: string; nodeId?: unknown } = {}\n): IBaseWidget['value'] | undefined {\n  if (mode === 'fixed') return undefined\n\n  if (isComboWidget(target)) {\n    return computeNextComboValue(target, mode, options)\n  }\n\n  return computeNextNumberValue(target, mode)\n}\n\nfunction computeNextComboValue(\n  target: IComboWidget,\n  mode: ValueControlMode,\n  { comboFilter, nodeId }: { comboFilter?: string; nodeId?: unknown }\n): IBaseWidget['value'] | undefined {\n  const rawValues = target.options.values\n  if (!Array.isArray(rawValues)) return undefined\n\n  const allValues = rawValues.filter(\n    (value): value is string | number =>\n      typeof value === 'string' || typeof value === 'number'\n  )\n  const check = buildComboFilter(comboFilter, nodeId)\n  const values = check\n    ? allValues.filter((value) => check(String(value)))\n    : allValues\n\n  if (!values.length) {\n    if (allValues.length) {\n      console.warn(\n        'Filter for node ' + String(nodeId) + ' has filtered out all items',\n        comboFilter\n      )\n    }\n    return undefined\n  }\n\n  let currentIndex = findComboValueIndex(values, target.value)\n  const length = values.length\n\n  switch (mode) {\n    case 'increment':\n      currentIndex += 1\n      break\n    case 'increment-wrap':\n      currentIndex += 1\n      if (currentIndex >= length) currentIndex = 0\n      break\n    case 'decrement':\n      currentIndex -= 1\n      break\n    case 'randomize':\n      currentIndex = Math.floor(Math.random() * length)\n      break\n  }\n\n  currentIndex = Math.max(0, Math.min(length - 1, currentIndex))\n  return values[currentIndex]\n}\n\nfunction computeNextNumberValue(\n  target: IBaseWidget,\n  mode: ValueControlMode\n): number | undefined {\n  if (typeof target.value !== 'number') return undefined\n\n  const { min: rawMin = 0, max: rawMax = 1, step2 = 1 } = target.options\n  const max = Math.min(SAFE_INTEGER_MAX, rawMax)\n  const min = Math.max(SAFE_INTEGER_MIN, rawMin)\n  const range = (max - min) / step2\n\n  let next = target.value\n  switch (mode) {\n    case 'increment':\n    case 'increment-wrap':\n      next += step2\n      break\n    case 'decrement':\n      next -= step2\n      break\n    case 'randomize':\n      next = Math.floor(Math.random() * range) * step2 + min\n      break\n  }\n\n  return Math.min(Math.max(next, min), max)\n}\n","import { t } from '@/i18n'\nimport { isComboWidget } from '@/lib/litegraph/src/litegraph'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type {\n  IBaseWidget,\n  IComboWidget,\n  IStringWidget\n} from '@/lib/litegraph/src/types/widgets'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport type { InputSpec } from '@/schemas/nodeDefSchema'\nimport { CONTROL_OPTIONS } from '@/types/simplifiedWidget'\n\nimport { IS_CONTROL_WIDGET } from './controlWidgetMarker'\nimport { isValueControlMode, nextValueForLinkedTarget } from './valueControl'\n\nfunction controlValueRunBefore() {\n  return useSettingStore().get('Comfy.WidgetControlMode') === 'before'\n}\n\nexport function updateControlWidgetLabel(widget: IBaseWidget) {\n  if (controlValueRunBefore()) {\n    widget.label = t('g.control_before_generate')\n  } else {\n    widget.label = t('g.control_after_generate')\n  }\n}\n\nconst HAS_EXECUTED = Symbol()\n\n/**\n * `control_after_generate` is either a group-node widget name override or a\n * control mode that core's `io.ControlAfterGenerate` enum serialises into\n * `object_info`. Only a non-blank string that is not a mode is a name.\n */\nfunction controlAfterGenerateNameOverride(value: unknown): string | undefined {\n  if (typeof value !== 'string' || value.trim() === '') return undefined\n  return isValueControlMode(value) ? undefined : value\n}\n\nexport function addValueControlWidget(\n  node: LGraphNode,\n  targetWidget: IBaseWidget,\n  defaultValue?: string,\n  _values?: unknown,\n  widgetName?: string,\n  inputData?: InputSpec\n): IComboWidget {\n  const name =\n    controlAfterGenerateNameOverride(inputData?.[1]?.control_after_generate) ??\n    widgetName\n  const widgets = addValueControlWidgets(\n    node,\n    targetWidget,\n    defaultValue ?? 'randomize',\n    {\n      addFilterList: false,\n      controlAfterGenerateName: name\n    },\n    inputData\n  )\n  return widgets[0]\n}\n\ninterface ValueControlWidgetOptions {\n  addFilterList?: boolean\n  controlAfterGenerateName?: string\n  controlFilterListName?: string\n}\n\nexport function addValueControlWidgets(\n  node: LGraphNode,\n  targetWidget: IBaseWidget,\n  defaultValue?: string,\n  options: ValueControlWidgetOptions = {},\n  inputData?: InputSpec\n): [IComboWidget, ...IStringWidget[]] {\n  // `useIntWidget` forwards a group-node name override here as the mode.\n  const specNameOverride = controlAfterGenerateNameOverride(\n    inputData?.[1]?.control_after_generate\n  )\n  if (!defaultValue || defaultValue === specNameOverride) {\n    defaultValue = 'randomize'\n  }\n\n  const getName = (\n    defaultName: 'control_after_generate' | 'control_filter_list',\n    optionName: 'controlAfterGenerateName' | 'controlFilterListName'\n  ) => {\n    const nameOverride = options[optionName]\n    if (nameOverride) return nameOverride\n    const inputOptions = inputData?.[1]\n    const specValue = inputOptions?.[defaultName]\n    const defaultNameOverride =\n      defaultName === 'control_after_generate'\n        ? controlAfterGenerateNameOverride(specValue)\n        : typeof specValue === 'string'\n          ? specValue\n          : undefined\n    if (defaultNameOverride !== undefined) return defaultNameOverride\n    if (inputOptions?.control_prefix) {\n      return inputOptions.control_prefix + ' ' + defaultName\n    }\n    return defaultName\n  }\n\n  const valueControl = node.addWidget(\n    'combo',\n    getName('control_after_generate', 'controlAfterGenerateName'),\n    defaultValue,\n    function () {},\n    {\n      values: [...CONTROL_OPTIONS],\n      serialize: false, // Don't include this in prompt.\n      surfaces: { canvas: 'shown', vueNode: 'never', panel: 'never' }\n    }\n  ) as IComboWidget\n\n  valueControl.tooltip =\n    'Allows the linked widget to be changed automatically, for example randomizing the noise seed.'\n  valueControl[IS_CONTROL_WIDGET] = true\n  updateControlWidgetLabel(valueControl)\n  Object.defineProperty(valueControl, 'disabled', {\n    get: () => targetWidget.computedDisabled\n  })\n  const widgets: [IComboWidget, ...IStringWidget[]] = [valueControl]\n\n  const isCombo = isComboWidget(targetWidget)\n  let comboFilter: IStringWidget\n  if (isCombo) {\n    const values = valueControl.options.values\n    if (Array.isArray(values)) values.push('increment-wrap')\n  }\n  if (isCombo && options.addFilterList !== false) {\n    comboFilter = node.addWidget(\n      'string',\n      getName('control_filter_list', 'controlFilterListName'),\n      '',\n      function () {},\n      {\n        serialize: false // Don't include this in prompt.\n      }\n    ) as IStringWidget\n    updateControlWidgetLabel(comboFilter)\n    comboFilter.tooltip =\n      \"Allows for filtering the list of values when changing the value via the control generate mode. Allows for RegEx matches in the format /abc/ to only filter to values containing 'abc'.\"\n    Object.defineProperty(comboFilter, 'disabled', {\n      get: () => targetWidget.computedDisabled\n    })\n\n    widgets.push(comboFilter)\n  }\n\n  function applyWidgetControl() {\n    if (\n      node.inputs.some(\n        (input, index) =>\n          input.widget?.name === targetWidget.name &&\n          node.isInputConnected(index)\n      )\n    )\n      return\n\n    const next = nextValueForLinkedTarget({\n      target: targetWidget,\n      linkedWidgets: targetWidget.linkedWidgets,\n      nodeId: node.id\n    })\n    if (next === undefined) return\n\n    targetWidget.value = next\n    targetWidget.callback?.(next)\n  }\n\n  valueControl.beforeQueued = () => {\n    if (controlValueRunBefore()) {\n      // Don't run on first execution\n      if (valueControl[HAS_EXECUTED]) {\n        applyWidgetControl()\n      }\n    }\n    valueControl[HAS_EXECUTED] = true\n  }\n\n  valueControl.afterQueued = () => {\n    if (!controlValueRunBefore()) {\n      applyWidgetControl()\n    }\n  }\n\n  return widgets\n}\n","import { z } from 'zod'\n\nimport {\n  zBaseInputOptions,\n  zBooleanInputOptions,\n  zColorStop,\n  zComboInputOptions,\n  zFloatInputOptions,\n  zIntInputOptions,\n  zStringInputOptions\n} from '@/schemas/nodeDefSchema'\n\nconst zIntInputSpec = zIntInputOptions.extend({\n  type: z.literal('INT'),\n  name: z.string(),\n  isOptional: z.boolean().optional()\n})\n\nconst zFloatInputSpec = zFloatInputOptions.extend({\n  type: z.literal('FLOAT'),\n  name: z.string(),\n  isOptional: z.boolean().optional()\n})\n\nconst zBooleanInputSpec = zBooleanInputOptions.extend({\n  type: z.literal('BOOLEAN'),\n  name: z.string(),\n  isOptional: z.boolean().optional()\n})\n\nconst zStringInputSpec = zStringInputOptions.extend({\n  type: z.literal('STRING'),\n  name: z.string(),\n  isOptional: z.boolean().optional()\n})\n\nconst zComboInputSpec = zComboInputOptions.extend({\n  type: z.literal('COMBO'),\n  name: z.string(),\n  isOptional: z.boolean().optional()\n})\n\nconst zColorInputSpec = zBaseInputOptions.extend({\n  type: z.literal('COLOR'),\n  name: z.string(),\n  isOptional: z.boolean().optional(),\n  default: z.string().optional(),\n  options: z.object({ default: z.string().optional() }).optional()\n})\n\nconst zImageInputSpec = zBaseInputOptions.extend({\n  type: z.literal('IMAGE'),\n  name: z.string(),\n  isOptional: z.boolean().optional(),\n  options: z.record(z.string(), z.unknown()).optional()\n})\n\nconst zImageCompareInputSpec = zBaseInputOptions.extend({\n  type: z.literal('IMAGECOMPARE'),\n  name: z.string(),\n  isOptional: z.boolean().optional(),\n  options: z.record(z.string(), z.unknown()).optional()\n})\n\nconst zBoundingBoxInputSpec = zBaseInputOptions.extend({\n  type: z.literal('BOUNDING_BOX'),\n  name: z.string(),\n  isOptional: z.boolean().optional(),\n  component: z.enum(['ImageCrop']).optional(),\n  default: z\n    .object({\n      x: z.number(),\n      y: z.number(),\n      width: z.number(),\n      height: z.number()\n    })\n    .optional()\n})\n\nconst zMarkdownInputSpec = zBaseInputOptions.extend({\n  type: z.literal('MARKDOWN'),\n  name: z.string(),\n  isOptional: z.boolean().optional(),\n  default: z.string().optional()\n})\n\nconst zChartInputSpec = zBaseInputOptions.extend({\n  type: z.literal('CHART'),\n  name: z.string(),\n  isOptional: z.boolean().optional(),\n  chartType: z.enum(['bar', 'line']).optional(),\n  data: z.record(z.string(), z.unknown()).optional(),\n  options: z\n    .object({\n      type: z.enum(['bar', 'line']).optional(),\n      data: z.record(z.string(), z.unknown()).optional()\n    })\n    .optional()\n})\n\nconst zGalleriaInputSpec = zBaseInputOptions.extend({\n  type: z.literal('GALLERIA'),\n  name: z.string(),\n  isOptional: z.boolean().optional(),\n  images: z.array(z.string()).optional(),\n  options: z.object({ images: z.array(z.string()).optional() }).optional()\n})\n\nconst zColorsInputSpec = zBaseInputOptions.extend({\n  type: z.literal('COLORS'),\n  name: z.string(),\n  isOptional: z.boolean().optional(),\n  default: z.array(z.string()).optional()\n})\n\nconst zBoundingBoxesInputSpec = zBaseInputOptions.extend({\n  type: z.literal('BOUNDING_BOXES'),\n  name: z.string(),\n  isOptional: z.boolean().optional(),\n  default: z\n    .array(\n      z.object({\n        x: z.number(),\n        y: z.number(),\n        width: z.number(),\n        height: z.number(),\n        metadata: z.object({\n          type: z.enum(['obj', 'text']),\n          text: z.string(),\n          desc: z.string(),\n          palette: z.array(z.string())\n        })\n      })\n    )\n    .optional()\n})\n\nconst zTextareaInputSpec = zBaseInputOptions.extend({\n  type: z.literal('TEXTAREA'),\n  name: z.string(),\n  isOptional: z.boolean().optional(),\n  rows: z.number().optional(),\n  cols: z.number().optional(),\n  default: z.string().optional(),\n  options: z\n    .object({\n      rows: z.number().optional(),\n      cols: z.number().optional(),\n      default: z.string().optional()\n    })\n    .optional()\n})\n\nconst zCurvePoint = z.tuple([z.number(), z.number()])\n\nconst zCurveData = z.object({\n  points: z.array(zCurvePoint),\n  interpolation: z.enum(['monotone_cubic', 'linear'])\n})\n\nconst zCurveInputSpec = zBaseInputOptions.extend({\n  type: z.literal('CURVE'),\n  name: z.string(),\n  isOptional: z.boolean().optional(),\n  default: zCurveData.optional()\n})\n\nconst zRangeValue = z.object({\n  min: z.number(),\n  max: z.number(),\n  midpoint: z.number().optional()\n})\n\nconst zRangeInputSpec = zBaseInputOptions.extend({\n  type: z.literal('RANGE'),\n  name: z.string(),\n  isOptional: z.boolean().optional(),\n  default: zRangeValue.optional(),\n  display: z.enum(['plain', 'gradient', 'histogram']).optional(),\n  gradient_stops: z.array(zColorStop).optional(),\n  show_midpoint: z.boolean().optional(),\n  midpoint_scale: z.enum(['linear', 'gamma']).optional(),\n  value_min: z.number().optional(),\n  value_max: z.number().optional()\n})\n\nconst zVideoEditValue = z.object({\n  trim: z\n    .object({\n      start_time: z.number(),\n      duration: z.number()\n    })\n    .optional(),\n  crop: z\n    .object({\n      x: z.number(),\n      y: z.number(),\n      width: z.number(),\n      height: z.number()\n    })\n    .optional()\n})\n\nconst zVideoEditInputSpec = zBaseInputOptions.extend({\n  type: z.literal('VIDEO_EDIT'),\n  name: z.string(),\n  isOptional: z.boolean().optional(),\n  features: z.array(z.enum(['trim', 'crop'])).optional(),\n  default: zVideoEditValue.optional()\n})\n\nconst zResolutionPreviewInputSpec = zBaseInputOptions.extend({\n  type: z.literal('RESOLUTION_PREVIEW'),\n  name: z.string(),\n  isOptional: z.boolean().optional(),\n  ratio_widget: z.string().optional(),\n  megapixels_widget: z.string().optional(),\n  multiple_widget: z.string().optional()\n})\n\nconst zCustomInputSpec = zBaseInputOptions.extend({\n  type: z.string(),\n  name: z.string(),\n  isOptional: z.boolean().optional()\n})\n\nconst zInputSpec = z.union([\n  zIntInputSpec,\n  zFloatInputSpec,\n  zBooleanInputSpec,\n  zStringInputSpec,\n  zComboInputSpec,\n  zColorInputSpec,\n  zImageInputSpec,\n  zImageCompareInputSpec,\n  zBoundingBoxInputSpec,\n  zMarkdownInputSpec,\n  zChartInputSpec,\n  zGalleriaInputSpec,\n  zColorsInputSpec,\n  zBoundingBoxesInputSpec,\n  zTextareaInputSpec,\n  zCurveInputSpec,\n  zRangeInputSpec,\n  zVideoEditInputSpec,\n  zResolutionPreviewInputSpec,\n  zCustomInputSpec\n])\n\n// Output specs\nconst zOutputSpec = z.object({\n  index: z.number(),\n  name: z.string(),\n  type: z.string(),\n  is_list: z.boolean(),\n  options: z.array(z.any()).optional(),\n  tooltip: z.string().optional()\n})\n\n// Main node definition schema\nexport const zComfyNodeDef = z.object({\n  inputs: z.record(z.string(), zInputSpec),\n  outputs: z.array(zOutputSpec),\n  hidden: z.record(z.string(), z.unknown()).optional(),\n\n  name: z.string(),\n  display_name: z.string(),\n  description: z.string(),\n  help: z.string().optional(),\n  category: z.string(),\n  output_node: z.boolean(),\n  python_module: z.string(),\n  deprecated: z.boolean().optional(),\n  experimental: z.boolean().optional(),\n  dev_only: z.boolean().optional(),\n  api_node: z.boolean().optional()\n})\n\n// Export types\ntype IntInputSpec = z.infer<typeof zIntInputSpec>\ntype FloatInputSpec = z.infer<typeof zFloatInputSpec>\ntype BooleanInputSpec = z.infer<typeof zBooleanInputSpec>\ntype StringInputSpec = z.infer<typeof zStringInputSpec>\nexport type ComboInputSpec = z.infer<typeof zComboInputSpec>\nexport type ColorInputSpec = z.infer<typeof zColorInputSpec>\nexport type ImageCompareInputSpec = z.infer<typeof zImageCompareInputSpec>\nexport type BoundingBoxInputSpec = z.infer<typeof zBoundingBoxInputSpec>\nexport type ChartInputSpec = z.infer<typeof zChartInputSpec>\nexport type GalleriaInputSpec = z.infer<typeof zGalleriaInputSpec>\nexport type ColorsInputSpec = z.infer<typeof zColorsInputSpec>\nexport type BoundingBoxesInputSpec = z.infer<typeof zBoundingBoxesInputSpec>\nexport type TextareaInputSpec = z.infer<typeof zTextareaInputSpec>\nexport type CurveInputSpec = z.infer<typeof zCurveInputSpec>\nexport type RangeInputSpec = z.infer<typeof zRangeInputSpec>\nexport type VideoEditInputSpec = z.infer<typeof zVideoEditInputSpec>\nexport type ResolutionPreviewInputSpec = z.infer<\n  typeof zResolutionPreviewInputSpec\n>\nexport type CustomInputSpec = z.infer<typeof zCustomInputSpec>\n\nexport type InputSpec = z.infer<typeof zInputSpec>\nexport type OutputSpec = z.infer<typeof zOutputSpec>\nexport type ComfyNodeDef = z.infer<typeof zComfyNodeDef>\n\nexport const isIntInputSpec = (\n  inputSpec: InputSpec\n): inputSpec is IntInputSpec => {\n  return inputSpec.type === 'INT'\n}\n\nexport const isFloatInputSpec = (\n  inputSpec: InputSpec\n): inputSpec is FloatInputSpec => {\n  return inputSpec.type === 'FLOAT'\n}\n\nexport const isBooleanInputSpec = (\n  inputSpec: InputSpec\n): inputSpec is BooleanInputSpec => {\n  return inputSpec.type === 'BOOLEAN'\n}\n\nexport const isStringInputSpec = (\n  inputSpec: InputSpec\n): inputSpec is StringInputSpec => {\n  return inputSpec.type === 'STRING'\n}\n\nexport const isComboInputSpec = (\n  inputSpec: InputSpec\n): inputSpec is ComboInputSpec => {\n  return inputSpec.type === 'COMBO'\n}\n\nexport const isChartInputSpec = (\n  inputSpec: InputSpec\n): inputSpec is ChartInputSpec => {\n  return inputSpec.type === 'CHART'\n}\n\nexport const isColorInputSpec = (\n  inputSpec: InputSpec\n): inputSpec is ColorInputSpec => {\n  return inputSpec.type === 'COLOR'\n}\n\nexport const isTextareaInputSpec = (\n  inputSpec: InputSpec\n): inputSpec is TextareaInputSpec => {\n  return inputSpec.type === 'TEXTAREA'\n}\n\nexport const isGalleriaInputSpec = (\n  inputSpec: InputSpec\n): inputSpec is GalleriaInputSpec => {\n  return inputSpec.type === 'GALLERIA'\n}\n\nexport const isResolutionPreviewInputSpec = (\n  inputSpec: InputSpec\n): inputSpec is ResolutionPreviewInputSpec => {\n  return inputSpec.type === 'RESOLUTION_PREVIEW'\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { isBooleanInputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { InputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\n\nexport const useBooleanWidget = () => {\n  const widgetConstructor: ComfyWidgetConstructorV2 = (\n    node: LGraphNode,\n    inputSpec: InputSpec\n  ) => {\n    if (!isBooleanInputSpec(inputSpec)) {\n      throw new Error(`Invalid input data: ${inputSpec}`)\n    }\n\n    const defaultVal = inputSpec.default ?? false\n    const options = {\n      on: inputSpec.label_on,\n      off: inputSpec.label_off\n    }\n\n    return node.addWidget(\n      'toggle',\n      inputSpec.name,\n      defaultVal,\n      () => {},\n      options\n    )\n  }\n\n  return widgetConstructor\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type {\n  IBaseWidget,\n  IBoundingBoxWidget,\n  IImageCropWidget,\n  INumericWidget\n} from '@/lib/litegraph/src/types/widgets'\nimport type { Bounds } from '@/renderer/core/layout/types'\nimport type {\n  BoundingBoxInputSpec,\n  InputSpec as InputSpecV2\n} from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\n\nfunction isBoundingBoxLikeWidget(\n  widget: IBaseWidget\n): widget is IBoundingBoxWidget | IImageCropWidget {\n  return widget.type === 'boundingbox' || widget.type === 'imagecrop'\n}\n\nfunction isNumericWidget(widget: IBaseWidget): widget is INumericWidget {\n  return widget.type === 'number'\n}\n\nexport const useBoundingBoxWidget = (): ComfyWidgetConstructorV2 => {\n  return (\n    node: LGraphNode,\n    inputSpec: InputSpecV2\n  ): IBoundingBoxWidget | IImageCropWidget => {\n    const spec = inputSpec as BoundingBoxInputSpec\n    const { name, component } = spec\n    const defaultValue: Bounds = spec.default ?? {\n      x: 0,\n      y: 0,\n      width: 512,\n      height: 512\n    }\n\n    const widgetType = component === 'ImageCrop' ? 'imagecrop' : 'boundingbox'\n\n    const fields: (keyof Bounds)[] = ['x', 'y', 'width', 'height']\n    const subWidgets: INumericWidget[] = []\n\n    const rawWidget = node.addWidget(\n      widgetType,\n      name,\n      { ...defaultValue },\n      () => {\n        for (let i = 0; i < fields.length; i++) {\n          const field = fields[i]\n          const subWidget = subWidgets.at(i)\n          if (subWidget) {\n            subWidget.value = widget.value[field]\n          }\n        }\n      }\n    )\n\n    if (!isBoundingBoxLikeWidget(rawWidget)) {\n      throw new Error(`Unexpected widget type: ${rawWidget.type}`)\n    }\n\n    const widget = rawWidget\n\n    for (const field of fields) {\n      const subWidget = node.addWidget(\n        'number',\n        field,\n        defaultValue[field],\n        function (this: INumericWidget, v: number) {\n          this.value = Math.round(v)\n          widget.value[field] = this.value\n          widget.callback?.(widget.value)\n        },\n        {\n          min: field === 'width' || field === 'height' ? 1 : 0,\n          max: 8192,\n          step: 10,\n          step2: 1,\n          precision: 0,\n          serialize: false,\n          surfaces: { canvas: 'shown', vueNode: 'never', panel: 'never' }\n        }\n      )\n\n      if (!isNumericWidget(subWidget)) {\n        throw new Error(`Unexpected widget type: ${subWidget.type}`)\n      }\n\n      subWidgets.push(subWidget)\n    }\n\n    widget.linkedWidgets = subWidgets\n\n    return widget\n  }\n}\n","import type { CurveData } from '@/components/curve/types'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { ICurveWidget } from '@/lib/litegraph/src/types/widgets'\nimport type {\n  CurveInputSpec,\n  InputSpec as InputSpecV2\n} from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\n\nconst DEFAULT_CURVE_DATA: CurveData = {\n  points: [\n    [0, 0],\n    [1, 1]\n  ],\n  interpolation: 'monotone_cubic'\n}\n\nexport const useCurveWidget = (): ComfyWidgetConstructorV2 => {\n  return (node: LGraphNode, inputSpec: InputSpecV2): ICurveWidget => {\n    const spec = inputSpec as CurveInputSpec\n    const defaultValue: CurveData = spec.default\n      ? { ...spec.default, points: [...spec.default.points] }\n      : { ...DEFAULT_CURVE_DATA, points: [...DEFAULT_CURVE_DATA.points] }\n\n    const rawWidget = node.addWidget('curve', spec.name, defaultValue, () => {})\n\n    if (rawWidget.type !== 'curve') {\n      throw new Error(`Unexpected widget type: ${rawWidget.type}`)\n    }\n\n    return rawWidget as ICurveWidget\n  }\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { IChartWidget } from '@/lib/litegraph/src/types/widgets'\nimport { isChartInputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { InputSpec as InputSpecV2 } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\n\nexport const useChartWidget = (): ComfyWidgetConstructorV2 => {\n  return (node: LGraphNode, inputSpec: InputSpecV2): IChartWidget => {\n    if (!isChartInputSpec(inputSpec)) {\n      throw new Error('Invalid input spec for chart widget')\n    }\n\n    const { name, options } = inputSpec\n    const chartType = inputSpec.chartType ?? options?.type ?? 'line'\n    const data = inputSpec.data ?? options?.data ?? {}\n\n    const widgetOptions = { serialize: true, type: chartType }\n\n    const widget = node.addWidget(\n      'chart',\n      name,\n      data,\n      () => {},\n      widgetOptions\n    ) as IChartWidget\n\n    return widget\n  }\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { IColorWidget } from '@/lib/litegraph/src/types/widgets'\nimport { isColorInputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type {\n  ColorInputSpec,\n  InputSpec as InputSpecV2\n} from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\n\nexport const useColorWidget = (): ComfyWidgetConstructorV2 => {\n  return (node: LGraphNode, inputSpec: InputSpecV2): IColorWidget => {\n    if (!isColorInputSpec(inputSpec)) {\n      console.error('Invalid input spec for color widget')\n    }\n\n    const colorSpec = inputSpec as ColorInputSpec\n    const { name } = colorSpec\n    const defaultValue =\n      colorSpec.default ?? colorSpec.options?.default ?? '#000000'\n\n    const existing = node.widgets?.find(\n      (w): w is IColorWidget => w.name === name && w.type === 'color'\n    )\n    if (existing) return existing\n\n    const widget = node.addWidget('color', name, defaultValue, () => {}, {\n      serialize: true\n    }) as IColorWidget\n\n    return widget\n  }\n}\n","<template>\n  <ComboboxPortal>\n    <ComboboxContent\n      position=\"popper\"\n      :side-offset=\"8\"\n      align=\"start\"\n      :style=\"[popoverStyle, contentStyle, liftedContentStyle]\"\n      :class=\"cn(selectContentClass, 'flex flex-col')\"\n      @keydown=\"onKeydown\"\n      @focus-outside=\"preventFocusDismiss\"\n    >\n      <FocusScope class=\"contents\" @mount-auto-focus.prevent>\n        <div v-if=\"showSearchBox\" class=\"px-2 pt-2 pb-0\">\n          <div\n            class=\"flex items-center gap-2 rounded-lg border border-solid border-border-default px-3 py-1.5\"\n          >\n            <i\n              class=\"icon-[lucide--search] shrink-0 text-sm text-muted-foreground\"\n            />\n            <ComboboxInput\n              v-model=\"searchQuery\"\n              :placeholder=\"searchPlaceholder ?? t('g.search')\"\n              class=\"w-full border-none bg-transparent text-sm outline-none\"\n            />\n          </div>\n        </div>\n\n        <div\n          v-if=\"hasActions && actionsPlacement === 'header'\"\n          :class=\"actionsClass\"\n        >\n          <span\n            v-if=\"showSelectedCount\"\n            class=\"px-1 text-sm text-muted-foreground\"\n          >\n            {{ t('g.itemsSelected', { count: selectedItems.length }) }}\n          </span>\n          <Button\n            v-if=\"showClearButton\"\n            variant=\"textonly\"\n            size=\"md\"\n            @click.stop=\"selectedItems = []\"\n          >\n            {{ t('g.clearAll') }}\n          </Button>\n        </div>\n\n        <ComboboxViewport\n          :class=\"\n            cn(\n              'flex flex-col gap-0 p-0 text-sm',\n              'scrollbar-custom overflow-y-auto',\n              'min-w-(--reka-combobox-trigger-width)'\n            )\n          \"\n          :style=\"{ maxHeight: `min(${listMaxHeight}, 50vh)` }\"\n        >\n          <ComboboxItem\n            v-for=\"opt in filteredOptions\"\n            :key=\"opt.value\"\n            :value=\"opt\"\n            :class=\"cn('group', selectItemVariants({ layout: 'multi' }))\"\n          >\n            <div\n              class=\"flex size-4 shrink-0 items-center justify-center rounded-sm transition-all duration-200 group-data-[state=checked]:bg-primary-background group-data-[state=unchecked]:bg-secondary-background [&>span]:flex\"\n            >\n              <ComboboxItemIndicator>\n                <i\n                  class=\"icon-[lucide--check] text-xs font-bold text-base-foreground\"\n                />\n              </ComboboxItemIndicator>\n            </div>\n            <span>{{ opt.name }}</span>\n          </ComboboxItem>\n          <ComboboxEmpty :class=\"selectEmptyMessageClass\">\n            {{ t('g.noResultsFound') }}\n          </ComboboxEmpty>\n        </ComboboxViewport>\n\n        <div\n          v-if=\"hasActions && actionsPlacement === 'footer'\"\n          :class=\"actionsClass\"\n        >\n          <span\n            v-if=\"showSelectedCount\"\n            class=\"px-1 text-sm text-muted-foreground\"\n          >\n            {{ t('g.itemsSelected', { count: selectedItems.length }) }}\n          </span>\n          <Button\n            v-if=\"showClearButton\"\n            variant=\"textonly\"\n            size=\"md\"\n            @click.stop=\"selectedItems = []\"\n          >\n            {{ t('g.clearAll') }}\n          </Button>\n        </div>\n      </FocusScope>\n    </ComboboxContent>\n  </ComboboxPortal>\n</template>\n\n<script setup lang=\"ts\">\nimport type { FocusOutsideEvent } from 'reka-ui'\nimport {\n  ComboboxContent,\n  ComboboxEmpty,\n  ComboboxInput,\n  ComboboxItem,\n  ComboboxItemIndicator,\n  ComboboxPortal,\n  ComboboxViewport,\n  FocusScope\n} from 'reka-ui'\nimport { computed } from 'vue'\nimport type { StyleValue } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport type { SelectOption } from '@/components/ui/select/types'\nimport { useSelectSearch } from '@/components/ui/select/useSelectSearch'\n\nimport {\n  selectContentClass,\n  selectEmptyMessageClass,\n  selectItemVariants,\n  stopEscapeToDocument\n} from '@comfyorg/design-system/select.variants'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  options,\n  showSearchBox,\n  showSelectedCount,\n  showClearButton,\n  actionsPlacement,\n  searchPlaceholder,\n  listMaxHeight,\n  popoverStyle,\n  contentStyle,\n  liftedContentStyle\n} = defineProps<{\n  options: SelectOption[]\n  showSearchBox: boolean\n  showSelectedCount: boolean\n  showClearButton: boolean\n  actionsPlacement: 'header' | 'footer'\n  searchPlaceholder?: string\n  listMaxHeight: string\n  popoverStyle: StyleValue\n  contentStyle?: StyleValue\n  liftedContentStyle: StyleValue\n}>()\n\nconst emit = defineEmits<{\n  escape: []\n}>()\n\nconst selectedItems = defineModel<SelectOption[]>({ required: true })\nconst searchQuery = defineModel<string>('searchQuery', { required: true })\n\nconst { t } = useI18n()\nconst hasActions = computed(() => showSelectedCount || showClearButton)\nconst actionsClass = computed(() =>\n  cn(\n    'flex shrink-0 items-center justify-between',\n    actionsPlacement === 'header'\n      ? 'mt-2 border-b border-border-default px-2 pb-4'\n      : '-mx-2 mt-2 border-t border-border-default px-4 pt-3 pb-1'\n  )\n)\nconst searchResults = useSelectSearch(searchQuery, () => options)\nconst filteredOptions = computed(() => {\n  if (!searchQuery.value.trim()) return options\n\n  const selectedButNotInResults = selectedItems.value.filter(\n    (item) => !searchResults.value.some(({ value }) => value === item.value)\n  )\n  return [...selectedButNotInResults, ...searchResults.value]\n})\n\nfunction onKeydown(event: KeyboardEvent) {\n  if (event.key !== 'Escape') return\n\n  stopEscapeToDocument(event)\n  emit('escape')\n}\n\nfunction preventFocusDismiss(event: FocusOutsideEvent) {\n  event.preventDefault()\n}\n</script>\n","<template>\n  <ComboboxPortal>\n    <ComboboxContent\n      position=\"popper\"\n      :side-offset=\"8\"\n      align=\"start\"\n      :style=\"[popoverStyle, contentStyle, liftedContentStyle]\"\n      :class=\"cn(selectContentClass, 'flex flex-col')\"\n      @keydown=\"onKeydown\"\n      @focus-outside=\"preventFocusDismiss\"\n    >\n      <FocusScope class=\"contents\" @mount-auto-focus.prevent>\n        <div v-if=\"showSearchBox\" class=\"px-2 pt-2 pb-0\">\n          <div\n            class=\"flex items-center gap-2 rounded-lg border border-solid border-border-default px-3 py-1.5\"\n          >\n            <i\n              class=\"icon-[lucide--search] shrink-0 text-sm text-muted-foreground\"\n            />\n            <ComboboxInput\n              v-model=\"searchQuery\"\n              :placeholder=\"searchPlaceholder ?? t('g.search')\"\n              class=\"w-full border-none bg-transparent text-sm outline-none\"\n            />\n          </div>\n        </div>\n\n        <div\n          v-if=\"hasActions && actionsPlacement === 'header'\"\n          :class=\"actionsClass\"\n        >\n          <span\n            v-if=\"showSelectedCount\"\n            class=\"px-1 text-sm text-muted-foreground\"\n          >\n            {{ t('g.itemsSelected', { count: selectedItems.length }) }}\n          </span>\n          <Button\n            v-if=\"showClearButton\"\n            variant=\"textonly\"\n            size=\"md\"\n            @click.stop=\"selectedItems = []\"\n          >\n            {{ t('g.clearAll') }}\n          </Button>\n        </div>\n\n        <ComboboxViewport\n          :class=\"\n            cn(\n              'flex flex-col gap-0 p-0 text-sm',\n              'scrollbar-custom overflow-y-auto',\n              'min-w-(--reka-combobox-trigger-width)'\n            )\n          \"\n          :style=\"{ maxHeight: `min(${listMaxHeight}, 50vh)` }\"\n        >\n          <ComboboxItem\n            v-for=\"opt in filteredOptions\"\n            :key=\"opt.value\"\n            :value=\"opt\"\n            :class=\"cn('group', selectItemVariants({ layout: 'multi' }))\"\n          >\n            <div\n              class=\"flex size-4 shrink-0 items-center justify-center rounded-sm transition-all duration-200 group-data-[state=checked]:bg-primary-background group-data-[state=unchecked]:bg-secondary-background [&>span]:flex\"\n            >\n              <ComboboxItemIndicator>\n                <i\n                  class=\"icon-[lucide--check] text-xs font-bold text-base-foreground\"\n                />\n              </ComboboxItemIndicator>\n            </div>\n            <span>{{ opt.name }}</span>\n          </ComboboxItem>\n          <ComboboxEmpty :class=\"selectEmptyMessageClass\">\n            {{ t('g.noResultsFound') }}\n          </ComboboxEmpty>\n        </ComboboxViewport>\n\n        <div\n          v-if=\"hasActions && actionsPlacement === 'footer'\"\n          :class=\"actionsClass\"\n        >\n          <span\n            v-if=\"showSelectedCount\"\n            class=\"px-1 text-sm text-muted-foreground\"\n          >\n            {{ t('g.itemsSelected', { count: selectedItems.length }) }}\n          </span>\n          <Button\n            v-if=\"showClearButton\"\n            variant=\"textonly\"\n            size=\"md\"\n            @click.stop=\"selectedItems = []\"\n          >\n            {{ t('g.clearAll') }}\n          </Button>\n        </div>\n      </FocusScope>\n    </ComboboxContent>\n  </ComboboxPortal>\n</template>\n\n<script setup lang=\"ts\">\nimport type { FocusOutsideEvent } from 'reka-ui'\nimport {\n  ComboboxContent,\n  ComboboxEmpty,\n  ComboboxInput,\n  ComboboxItem,\n  ComboboxItemIndicator,\n  ComboboxPortal,\n  ComboboxViewport,\n  FocusScope\n} from 'reka-ui'\nimport { computed } from 'vue'\nimport type { StyleValue } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport type { SelectOption } from '@/components/ui/select/types'\nimport { useSelectSearch } from '@/components/ui/select/useSelectSearch'\n\nimport {\n  selectContentClass,\n  selectEmptyMessageClass,\n  selectItemVariants,\n  stopEscapeToDocument\n} from '@comfyorg/design-system/select.variants'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  options,\n  showSearchBox,\n  showSelectedCount,\n  showClearButton,\n  actionsPlacement,\n  searchPlaceholder,\n  listMaxHeight,\n  popoverStyle,\n  contentStyle,\n  liftedContentStyle\n} = defineProps<{\n  options: SelectOption[]\n  showSearchBox: boolean\n  showSelectedCount: boolean\n  showClearButton: boolean\n  actionsPlacement: 'header' | 'footer'\n  searchPlaceholder?: string\n  listMaxHeight: string\n  popoverStyle: StyleValue\n  contentStyle?: StyleValue\n  liftedContentStyle: StyleValue\n}>()\n\nconst emit = defineEmits<{\n  escape: []\n}>()\n\nconst selectedItems = defineModel<SelectOption[]>({ required: true })\nconst searchQuery = defineModel<string>('searchQuery', { required: true })\n\nconst { t } = useI18n()\nconst hasActions = computed(() => showSelectedCount || showClearButton)\nconst actionsClass = computed(() =>\n  cn(\n    'flex shrink-0 items-center justify-between',\n    actionsPlacement === 'header'\n      ? 'mt-2 border-b border-border-default px-2 pb-4'\n      : '-mx-2 mt-2 border-t border-border-default px-4 pt-3 pb-1'\n  )\n)\nconst searchResults = useSelectSearch(searchQuery, () => options)\nconst filteredOptions = computed(() => {\n  if (!searchQuery.value.trim()) return options\n\n  const selectedButNotInResults = selectedItems.value.filter(\n    (item) => !searchResults.value.some(({ value }) => value === item.value)\n  )\n  return [...selectedButNotInResults, ...searchResults.value]\n})\n\nfunction onKeydown(event: KeyboardEvent) {\n  if (event.key !== 'Escape') return\n\n  stopEscapeToDocument(event)\n  emit('escape')\n}\n\nfunction preventFocusDismiss(event: FocusOutsideEvent) {\n  event.preventDefault()\n}\n</script>\n","<template>\n  <ComboboxAnchor as-child>\n    <ComboboxTrigger\n      v-bind=\"$attrs\"\n      :aria-label=\"label || fallbackLabel\"\n      :class=\"\n        cn(\n          selectTriggerVariants({\n            size,\n            border: selectedItems.length ? 'active' : 'none'\n          }),\n          className\n        )\n      \"\n    >\n      <div\n        class=\"flex flex-1 items-center overflow-hidden py-2 pl-2 whitespace-nowrap\"\n      >\n        <span\n          v-if=\"selectedItems.length === 0\"\n          :class=\"size === 'md' ? 'text-xs' : 'text-sm'\"\n        >\n          {{ label }}\n        </span>\n        <slot v-else :selected=\"selectedItems\">\n          <span class=\"truncate text-sm\">\n            {{ selectedItems.map(({ name }) => name).join(', ') }}\n          </span>\n        </slot>\n        <span\n          v-if=\"selectedItems.length\"\n          :class=\"\n            cn(\n              'pointer-events-none absolute -top-1.5 -right-1.5 z-10',\n              selectCountBadgeClass\n            )\n          \"\n        >\n          {{ selectedItems.length }}\n        </span>\n      </div>\n      <div :class=\"selectDropdownClass\">\n        <i class=\"icon-[lucide--chevron-down] text-muted-foreground\" />\n      </div>\n    </ComboboxTrigger>\n  </ComboboxAnchor>\n</template>\n\n<script setup lang=\"ts\">\nimport { ComboboxAnchor, ComboboxTrigger } from 'reka-ui'\n\nimport {\n  selectCountBadgeClass,\n  selectDropdownClass,\n  selectTriggerVariants\n} from '@comfyorg/design-system/select.variants'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport type { ClassValue } from '@comfyorg/tailwind-utils'\nimport type { SelectOption } from '@/components/ui/select/types'\n\ndefineOptions({ inheritAttrs: false })\n\nconst {\n  class: className,\n  label,\n  fallbackLabel,\n  selectedItems,\n  size\n} = defineProps<{\n  class?: ClassValue\n  label?: string\n  fallbackLabel: string\n  selectedItems: SelectOption[]\n  size: 'lg' | 'md'\n}>()\n</script>\n","<template>\n  <ComboboxAnchor as-child>\n    <ComboboxTrigger\n      v-bind=\"$attrs\"\n      :aria-label=\"label || fallbackLabel\"\n      :class=\"\n        cn(\n          selectTriggerVariants({\n            size,\n            border: selectedItems.length ? 'active' : 'none'\n          }),\n          className\n        )\n      \"\n    >\n      <div\n        class=\"flex flex-1 items-center overflow-hidden py-2 pl-2 whitespace-nowrap\"\n      >\n        <span\n          v-if=\"selectedItems.length === 0\"\n          :class=\"size === 'md' ? 'text-xs' : 'text-sm'\"\n        >\n          {{ label }}\n        </span>\n        <slot v-else :selected=\"selectedItems\">\n          <span class=\"truncate text-sm\">\n            {{ selectedItems.map(({ name }) => name).join(', ') }}\n          </span>\n        </slot>\n        <span\n          v-if=\"selectedItems.length\"\n          :class=\"\n            cn(\n              'pointer-events-none absolute -top-1.5 -right-1.5 z-10',\n              selectCountBadgeClass\n            )\n          \"\n        >\n          {{ selectedItems.length }}\n        </span>\n      </div>\n      <div :class=\"selectDropdownClass\">\n        <i class=\"icon-[lucide--chevron-down] text-muted-foreground\" />\n      </div>\n    </ComboboxTrigger>\n  </ComboboxAnchor>\n</template>\n\n<script setup lang=\"ts\">\nimport { ComboboxAnchor, ComboboxTrigger } from 'reka-ui'\n\nimport {\n  selectCountBadgeClass,\n  selectDropdownClass,\n  selectTriggerVariants\n} from '@comfyorg/design-system/select.variants'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport type { ClassValue } from '@comfyorg/tailwind-utils'\nimport type { SelectOption } from '@/components/ui/select/types'\n\ndefineOptions({ inheritAttrs: false })\n\nconst {\n  class: className,\n  label,\n  fallbackLabel,\n  selectedItems,\n  size\n} = defineProps<{\n  class?: ClassValue\n  label?: string\n  fallbackLabel: string\n  selectedItems: SelectOption[]\n  size: 'lg' | 'md'\n}>()\n</script>\n","<template>\n  <ComboboxRoot\n    v-model=\"selectedItems\"\n    v-model:open=\"isOpen\"\n    multiple\n    by=\"value\"\n    :disabled\n    ignore-filter\n    :reset-search-term-on-select=\"false\"\n  >\n    <MultiSelectTrigger\n      v-bind=\"attrsWithoutClass\"\n      :class=\"attrsClass\"\n      :label\n      :fallback-label=\"t('g.multiSelectDropdown')\"\n      :selected-items=\"selectedItems\"\n      :size\n    >\n      <template v-if=\"$slots.value\" #default=\"{ selected }\">\n        <slot name=\"value\" :selected />\n      </template>\n    </MultiSelectTrigger>\n\n    <MultiSelectContent\n      v-model=\"selectedItems\"\n      v-model:search-query=\"searchQuery\"\n      :options\n      :show-search-box\n      :show-selected-count\n      :show-clear-button\n      :actions-placement\n      :search-placeholder\n      :list-max-height\n      :popover-style\n      :content-style\n      :lifted-content-style\n      @escape=\"isOpen = false\"\n    />\n  </ComboboxRoot>\n</template>\n\n<script setup lang=\"ts\">\nimport { ComboboxRoot } from 'reka-ui'\nimport { ref } from 'vue'\nimport type { StyleValue } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport MultiSelectContent from '@/components/ui/multi-select/MultiSelectContent.vue'\nimport MultiSelectTrigger from '@/components/ui/multi-select/MultiSelectTrigger.vue'\n\nimport type { SelectOption } from '@/components/ui/select/types'\nimport { useAttrsClass } from '@/composables/useAttrsClass'\nimport { useModalLiftedZIndex } from '@/composables/useModalLiftedZIndex'\nimport { usePopoverSizing } from '@/composables/usePopoverSizing'\n\ndefineOptions({\n  inheritAttrs: false\n})\n\nconst { attrsClass, attrsWithoutClass } = useAttrsClass()\n\nconst {\n  label,\n  options = [],\n  size = 'lg',\n  disabled = false,\n  showSearchBox = false,\n  showSelectedCount = false,\n  showClearButton = false,\n  actionsPlacement = 'header',\n  searchPlaceholder,\n  listMaxHeight = '28rem',\n  popoverMinWidth,\n  popoverMaxWidth,\n  contentStyle\n} = defineProps<{\n  /** Input label shown on the trigger button */\n  label?: string\n  /** Available options */\n  options?: SelectOption[]\n  /** Trigger size: 'lg' (40px, Interface) or 'md' (32px, Node) */\n  size?: 'lg' | 'md'\n  /** Disable the select */\n  disabled?: boolean\n  /** Show search box in the panel header */\n  showSearchBox?: boolean\n  /** Show selected count text in the panel header */\n  showSelectedCount?: boolean\n  /** Show \"Clear all\" action in the panel header */\n  showClearButton?: boolean\n  actionsPlacement?: 'header' | 'footer'\n  /** Placeholder for the search input */\n  searchPlaceholder?: string\n  /** Maximum height of the dropdown panel (default: 28rem) */\n  listMaxHeight?: string\n  /** Minimum width of the popover (default: auto) */\n  popoverMinWidth?: string\n  /** Maximum width of the popover (default: auto) */\n  popoverMaxWidth?: string\n  contentStyle?: StyleValue\n}>()\n\nconst selectedItems = defineModel<SelectOption[]>({\n  required: true\n})\nconst searchQuery = defineModel<string>('searchQuery', { default: '' })\n\nconst { t } = useI18n()\nconst isOpen = ref(false)\nconst liftedContentStyle = useModalLiftedZIndex(isOpen)\n\nconst popoverStyle = usePopoverSizing({\n  minWidth: popoverMinWidth,\n  maxWidth: popoverMaxWidth\n})\n</script>\n","<template>\n  <ComboboxRoot\n    v-model=\"selectedItems\"\n    v-model:open=\"isOpen\"\n    multiple\n    by=\"value\"\n    :disabled\n    ignore-filter\n    :reset-search-term-on-select=\"false\"\n  >\n    <MultiSelectTrigger\n      v-bind=\"attrsWithoutClass\"\n      :class=\"attrsClass\"\n      :label\n      :fallback-label=\"t('g.multiSelectDropdown')\"\n      :selected-items=\"selectedItems\"\n      :size\n    >\n      <template v-if=\"$slots.value\" #default=\"{ selected }\">\n        <slot name=\"value\" :selected />\n      </template>\n    </MultiSelectTrigger>\n\n    <MultiSelectContent\n      v-model=\"selectedItems\"\n      v-model:search-query=\"searchQuery\"\n      :options\n      :show-search-box\n      :show-selected-count\n      :show-clear-button\n      :actions-placement\n      :search-placeholder\n      :list-max-height\n      :popover-style\n      :content-style\n      :lifted-content-style\n      @escape=\"isOpen = false\"\n    />\n  </ComboboxRoot>\n</template>\n\n<script setup lang=\"ts\">\nimport { ComboboxRoot } from 'reka-ui'\nimport { ref } from 'vue'\nimport type { StyleValue } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport MultiSelectContent from '@/components/ui/multi-select/MultiSelectContent.vue'\nimport MultiSelectTrigger from '@/components/ui/multi-select/MultiSelectTrigger.vue'\n\nimport type { SelectOption } from '@/components/ui/select/types'\nimport { useAttrsClass } from '@/composables/useAttrsClass'\nimport { useModalLiftedZIndex } from '@/composables/useModalLiftedZIndex'\nimport { usePopoverSizing } from '@/composables/usePopoverSizing'\n\ndefineOptions({\n  inheritAttrs: false\n})\n\nconst { attrsClass, attrsWithoutClass } = useAttrsClass()\n\nconst {\n  label,\n  options = [],\n  size = 'lg',\n  disabled = false,\n  showSearchBox = false,\n  showSelectedCount = false,\n  showClearButton = false,\n  actionsPlacement = 'header',\n  searchPlaceholder,\n  listMaxHeight = '28rem',\n  popoverMinWidth,\n  popoverMaxWidth,\n  contentStyle\n} = defineProps<{\n  /** Input label shown on the trigger button */\n  label?: string\n  /** Available options */\n  options?: SelectOption[]\n  /** Trigger size: 'lg' (40px, Interface) or 'md' (32px, Node) */\n  size?: 'lg' | 'md'\n  /** Disable the select */\n  disabled?: boolean\n  /** Show search box in the panel header */\n  showSearchBox?: boolean\n  /** Show selected count text in the panel header */\n  showSelectedCount?: boolean\n  /** Show \"Clear all\" action in the panel header */\n  showClearButton?: boolean\n  actionsPlacement?: 'header' | 'footer'\n  /** Placeholder for the search input */\n  searchPlaceholder?: string\n  /** Maximum height of the dropdown panel (default: 28rem) */\n  listMaxHeight?: string\n  /** Minimum width of the popover (default: auto) */\n  popoverMinWidth?: string\n  /** Maximum width of the popover (default: auto) */\n  popoverMaxWidth?: string\n  contentStyle?: StyleValue\n}>()\n\nconst selectedItems = defineModel<SelectOption[]>({\n  required: true\n})\nconst searchQuery = defineModel<string>('searchQuery', { default: '' })\n\nconst { t } = useI18n()\nconst isOpen = ref(false)\nconst liftedContentStyle = useModalLiftedZIndex(isOpen)\n\nconst popoverStyle = usePopoverSizing({\n  minWidth: popoverMinWidth,\n  maxWidth: popoverMaxWidth\n})\n</script>\n","<template>\n  <div>\n    <MultiSelect\n      v-model=\"selectedOptions\"\n      :options=\"options\"\n      show-search-box\n      :label=\"placeholder\"\n      class=\"w-full\"\n    >\n      <template v-if=\"inputSpec.multi_select?.chip\" #value=\"{ selected }\">\n        <div class=\"flex min-w-0 gap-1 overflow-hidden\">\n          <span\n            v-for=\"item in selected\"\n            :key=\"item.value\"\n            class=\"truncate rounded-sm bg-secondary-background px-1.5 py-0.5 text-xs\"\n          >\n            {{ item.name }}\n          </span>\n        </div>\n      </template>\n    </MultiSelect>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport MultiSelect from '@/components/ui/multi-select/MultiSelect.vue'\nimport type { SelectOption } from '@/components/ui/select/types'\nimport type { ComboInputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComponentWidget } from '@/scripts/domWidget'\n\nconst selectedItems = defineModel<string[]>({ required: true })\nconst { widget } = defineProps<{\n  widget: ComponentWidget<string[]>\n}>()\n\nconst inputSpec = widget.inputSpec as ComboInputSpec\nconst options = computed<SelectOption[]>(() =>\n  (inputSpec.options ?? []).map((value) => ({\n    name: String(value),\n    value: String(value)\n  }))\n)\nconst selectedOptions = computed({\n  get: () =>\n    options.value.filter(({ value }) =>\n      selectedItems.value.includes(String(value))\n    ),\n  set: (value: SelectOption[]) => {\n    selectedItems.value = value.map(({ value }) => String(value))\n  }\n})\nconst placeholder = inputSpec.multi_select?.placeholder ?? 'Select items'\n</script>\n","<template>\n  <div>\n    <MultiSelect\n      v-model=\"selectedOptions\"\n      :options=\"options\"\n      show-search-box\n      :label=\"placeholder\"\n      class=\"w-full\"\n    >\n      <template v-if=\"inputSpec.multi_select?.chip\" #value=\"{ selected }\">\n        <div class=\"flex min-w-0 gap-1 overflow-hidden\">\n          <span\n            v-for=\"item in selected\"\n            :key=\"item.value\"\n            class=\"truncate rounded-sm bg-secondary-background px-1.5 py-0.5 text-xs\"\n          >\n            {{ item.name }}\n          </span>\n        </div>\n      </template>\n    </MultiSelect>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport MultiSelect from '@/components/ui/multi-select/MultiSelect.vue'\nimport type { SelectOption } from '@/components/ui/select/types'\nimport type { ComboInputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComponentWidget } from '@/scripts/domWidget'\n\nconst selectedItems = defineModel<string[]>({ required: true })\nconst { widget } = defineProps<{\n  widget: ComponentWidget<string[]>\n}>()\n\nconst inputSpec = widget.inputSpec as ComboInputSpec\nconst options = computed<SelectOption[]>(() =>\n  (inputSpec.options ?? []).map((value) => ({\n    name: String(value),\n    value: String(value)\n  }))\n)\nconst selectedOptions = computed({\n  get: () =>\n    options.value.filter(({ value }) =>\n      selectedItems.value.includes(String(value))\n    ),\n  set: (value: SelectOption[]) => {\n    selectedItems.value = value.map(({ value }) => String(value))\n  }\n})\nconst placeholder = inputSpec.multi_select?.placeholder ?? 'Select items'\n</script>\n","import type { IComboWidget } from '@/lib/litegraph/src/types/widgets'\n\nexport type ComboWidgetInventoryStatus = 'loading' | 'ready' | 'error'\n\nexport interface ComboWidgetInventory {\n  getStatus(): ComboWidgetInventoryStatus\n  waitForSettled(signal?: AbortSignal): Promise<void>\n}\n\nconst inventories = new WeakMap<IComboWidget, ComboWidgetInventory>()\n\nexport function registerComboWidgetInventory(\n  widget: IComboWidget,\n  inventory: ComboWidgetInventory\n): void {\n  inventories.set(widget, inventory)\n}\n\nexport function getComboWidgetInventory(\n  widget: IComboWidget\n): ComboWidgetInventory | undefined {\n  return inventories.get(widget)\n}\n","/**\n * Wire-level websocket event the backend broadcasts when a seed scan's fast\n * (insert) phase completes — the moment newly scanned files' tags and loader\n * paths become queryable.\n */\nexport const ASSETS_SEED_FAST_COMPLETE_EVENT = 'assets.seed.fast_complete'\n","import {\n  zAsset as zIngestAsset,\n  zListAssetsResponse\n} from '@comfyorg/ingest-types/zod'\nimport { z } from 'zod'\n\n// Zod schemas for asset API validation matching ComfyUI Assets REST API spec\nconst zAsset = z.object({\n  ...zIngestAsset.shape,\n  created_at: z.iso.datetime({ local: true }),\n  hash: z.string().optional(),\n  id: z.string(),\n  last_access_time: z.iso.datetime({ local: true }).optional(),\n  preview_url: z.string().optional(),\n  size: zIngestAsset.shape.size.unwrap().transform(Number).optional(),\n  tags: zIngestAsset.shape.tags.default([]),\n  thumbnail_url: z.string().optional(),\n  updated_at: z.iso.datetime({ local: true }),\n  // The API sends `null` for unset metadata, which the generated `.optional()`\n  // shape rejects outright; normalize it to the one absent shape consumers know.\n  user_metadata: zIngestAsset.shape.user_metadata\n    .nullable()\n    .transform((value) => value ?? undefined)\n    .optional()\n})\n\nconst zAssetResponse = zListAssetsResponse\n  .pick({ total: true, has_more: true, next_cursor: true })\n  .extend({\n    assets: z.array(zAsset)\n  })\n\n// Zod schema for ModelFile to align with interface\nconst zModelFile = z.object({\n  name: z.string(),\n  pathIndex: z.number()\n})\n\nconst zValidationError = z.object({\n  code: z.string(),\n  message: z.string(),\n  field: z.string()\n})\n\nconst zValidationResult = z.object({\n  is_valid: z.boolean(),\n  errors: z.array(zValidationError).optional(),\n  warnings: z.array(zValidationError).optional()\n})\n\nconst zAssetMetadata = z.object({\n  content_length: z.number(),\n  final_url: z.string(),\n  content_type: z.string().optional(),\n  filename: z.string().optional(),\n  name: z.string().optional(),\n  tags: z.array(z.string()).optional(),\n  preview_url: z.string().optional(),\n  preview_image: z.string().optional(),\n  validation: zValidationResult.optional()\n})\n\nconst zAsyncUploadTask = z.object({\n  task_id: z.string(),\n  status: z.enum(['created', 'running', 'completed', 'failed']),\n  message: z.string().optional()\n})\n\nconst zAsyncUploadResponse = z.discriminatedUnion('type', [\n  z.object({ type: z.literal('sync'), asset: zAsset }),\n  z.object({ type: z.literal('async'), task: zAsyncUploadTask })\n])\n\n// Filename validation schema. Trim runs FIRST so the anchored checks see the\n// trimmed value — trailing-position trim let ' /etc/passwd' bypass the\n// absolute-path block.\nexport const assetFilenameSchema = z\n  .string()\n  .trim()\n  .min(1, 'Filename cannot be empty')\n  .regex(/^[^\\\\:*?\"<>|]+$/, 'Invalid filename characters') // Allow forward slashes, block backslashes and other unsafe chars\n  .regex(/^(?!\\/)/, 'Path must not be absolute')\n  // Traversal check is segment-aware: `..` as a whole path segment is\n  // blocked, while double dots inside a filename (`flux..v2.safetensors`)\n  // stay valid.\n  .refine(\n    (value) => !value.split('/').includes('..'),\n    'Path must not contain \"..\" segments'\n  )\n\n// Export schemas following repository patterns\nexport const assetItemSchema = zAsset\nexport const assetResponseSchema = zAssetResponse\nexport const asyncUploadResponseSchema = zAsyncUploadResponse\n\n/**\n * Identifier for a single asset record.\n *\n * Backed by `AssetItem.id` which the API serialises as a string. This alias\n * names that primitive at use sites (services, stores, composables) without\n * changing structural typing.\n */\nexport type AssetId = string\n\n// Export types derived from Zod schemas\nexport type AssetItem = z.infer<typeof zAsset>\nexport type AssetResponse = z.infer<typeof zAssetResponse>\nexport type AssetMetadata = z.infer<typeof zAssetMetadata>\nexport type AsyncUploadResponse = z.infer<typeof zAsyncUploadResponse>\nexport type ModelFile = z.infer<typeof zModelFile>\n\n/** Payload for updating an asset via PUT /assets/:id */\nexport type AssetUpdatePayload = Partial<\n  Pick<AssetItem, 'name' | 'tags' | 'user_metadata' | 'preview_id'>\n>\n\n/** User-editable metadata fields for model assets */\nconst zAssetUserMetadata = z.object({\n  name: z.string().optional(),\n  base_model: z.array(z.string()).optional(),\n  additional_tags: z.array(z.string()).optional(),\n  user_description: z.string().optional()\n})\n\nexport type AssetUserMetadata = z.infer<typeof zAssetUserMetadata>\n\nexport const tagsOperationResultSchema = z.object({\n  total_tags: z.array(z.string()),\n  added: z.array(z.string()).optional(),\n  removed: z.array(z.string()).optional(),\n  already_present: z.array(z.string()).optional(),\n  not_present: z.array(z.string()).optional()\n})\n\nexport type TagsOperationResult = z.infer<typeof tagsOperationResultSchema>\n\n// Legacy interface for backward compatibility (now aligned with Zod schema)\nexport interface ModelFolderInfo {\n  name: string\n  folders: string[]\n  /**\n   * The folder's raw registered extension allowlist from\n   * `/experiment/models`. An empty array means match-all; absent on older\n   * backends.\n   */\n  extensions?: string[]\n}\n","const loraStackFilename = /^loras\\.(?:0|[1-9]\\d*)\\.lora_name$/\n\n/**\n * Default mappings from model directories to loader nodes.\n *\n * Each entry maps a model folder (as it appears in the model browser)\n * to the node class that loads models from that folder and the\n * input name or pattern used to select the model widget.\n *\n * An empty key ('') means the node auto-loads models without a widget\n * selector, so no widget value is assigned when the node is added.\n *\n * Hierarchical fallback is handled by the store: \"a/b/c\" tries\n * \"a/b/c\" → \"a/b\" → \"a\", so registering a parent directory covers\n * all its children unless a more specific entry exists.\n *\n * Patterns enable the picker on every matching widget. Model drops populate\n * the first matching widget.\n *\n * Format: [modelDirectory, nodeClass, inputNameOrPattern]\n */\nexport const MODEL_NODE_MAPPINGS: ReadonlyArray<\n  readonly [string, string, string | RegExp]\n> = [\n  // Intentionally unmapped (widget values are model ids / HF repo ids, not\n  // asset filenames): rmbg, florence2, LLM/Qwen-VL/*, qwen-tts, diffusers\n  // (Kolors), BiRefNet, EVF-SAM, smol. onnx/human-parts has no assets.\n  // Also unmapped: segformer_b2_clothes, segformer_b3_clothes,\n  // segformer_b3_fashion, lama, layer_model, LLM/llava-llama-3-8b-*,\n  // LLM/Llama-3.2-3B-Instruct, LLM/Florence-2-large-PromptGen-v2.0\n  // (id widgets); sam3, sharp, BEN, BiRefNet/pth (node/widget names don't\n  // exist); depthanything, CogVideo/GGUF, checkpoints/dynamicrafter/*,\n  // transparent-background (asset names not accepted by the node's enum);\n  // interpolation, clip, onnx (empty or unreachable dirs).\n\n  // ---- ComfyUI core loaders ----\n  ['checkpoints', 'CheckpointLoaderSimple', 'ckpt_name'],\n  ['checkpoints', 'ImageOnlyCheckpointLoader', 'ckpt_name'],\n  ['loras', 'LoraLoader', 'lora_name'],\n  ['loras', 'LoraLoaderModelOnly', 'lora_name'],\n  ['loras', 'LoadLoraModel', loraStackFilename],\n  ['loras', 'LoadLoraTextEncoder', loraStackFilename],\n  ['vae', 'VAELoader', 'vae_name'],\n  ['controlnet', 'ControlNetLoader', 'control_net_name'],\n  ['diffusion_models', 'UNETLoader', 'unet_name'],\n  ['upscale_models', 'UpscaleModelLoader', 'model_name'],\n  ['style_models', 'StyleModelLoader', 'style_model_name'],\n  ['gligen', 'GLIGENLoader', 'gligen_name'],\n  ['clip_vision', 'CLIPVisionLoader', 'clip_name'],\n  ['text_encoders', 'CLIPLoader', 'clip_name'],\n  ['audio_encoders', 'AudioEncoderLoader', 'audio_encoder_name'],\n  ['model_patches', 'ModelPatchLoader', 'name'],\n  ['latent_upscale_models', 'LatentUpscaleModelLoader', 'model_name'],\n\n  // ---- AnimateDiff (comfyui-animatediff-evolved) ----\n  ['animatediff_models', 'ADE_LoadAnimateDiffModel', 'model_name'],\n  ['animatediff_motion_lora', 'ADE_AnimateDiffLoRALoader', 'name'],\n\n  // ---- Chatterbox TTS (ComfyUI-Fill-Nodes) ----\n  ['chatterbox/chatterbox', 'FL_ChatterboxTTS', ''],\n  ['chatterbox/chatterbox_turbo', 'FL_ChatterboxTurboTTS', ''],\n  ['chatterbox/chatterbox_multilingual', 'FL_ChatterboxMultilingualTTS', ''],\n  ['chatterbox/chatterbox_vc', 'FL_ChatterboxVC', ''],\n\n  // ---- SAM / SAM2 (comfyui-segment-anything-2, comfyui-impact-pack) ----\n  ['sam2', 'DownloadAndLoadSAM2Model', 'model'],\n  ['sams', 'SAMLoader', 'model_name'],\n\n  // ---- DepthAnything (comfyui-depthanythingv3) ----\n  ['depthanything3', 'DownloadAndLoadDepthAnythingV3Model', 'model'],\n\n  // ---- IP-Adapter (comfyui_ipadapter_plus) ----\n  ['ipadapter', 'IPAdapterModelLoader', 'ipadapter_file'],\n\n  // ---- NLF pose estimation (ComfyUI-WanVideoWrapper) ----\n  ['nlf', 'LoadNLFModel', 'nlf_model'],\n\n  // ---- FlashVSR video super-resolution (ComfyUI-FlashVSR_Ultra_Fast) ----\n  ['FlashVSR', 'FlashVSRNode', ''],\n  ['FlashVSR-v1.1', 'FlashVSRNode', ''],\n\n  // ---- SEEDVR2 video upscaling (comfyui-seedvr2) ----\n  ['SEEDVR2', 'SeedVR2LoadDiTModel', 'model'],\n\n  // ---- ChatGLM3 text encoder ----\n  ['LLM/checkpoints', 'LoadChatGLM3', 'chatglm3_checkpoint'],\n\n  // ---- LivePortrait (comfyui-liveportrait) ----\n  ['liveportrait', 'DownloadAndLoadLivePortraitModels', ''],\n\n  // ---- MimicMotion (ComfyUI-MimicMotionWrapper) ----\n  ['mimicmotion', 'DownloadAndLoadMimicMotionModel', 'model'],\n  ['dwpose', 'MimicMotionGetPoses', ''],\n\n  // ---- Face parsing (comfyui_face_parsing) ----\n  ['face_parsing', 'FaceParsingModelLoader(FaceParsing)', ''],\n\n  // ---- RIFE video frame interpolation (ComfyUI-RIFE) ----\n  ['rife', 'RIFE VFI', 'ckpt_name'],\n\n  // ---- UltraShape 3D model generation ----\n  ['UltraShape', 'UltraShapeLoadModel', 'checkpoint'],\n\n  // ---- Detection models (vitpose, yolo) ----\n  ['detection', 'OnnxDetectionModelLoader', 'yolo_model'],\n\n  // ---- CogVideoX (comfyui-cogvideoxwrapper) ----\n  ['CogVideo', 'DownloadAndLoadCogVideoModel', ''],\n  ['CogVideo/ControlNet', 'DownloadAndLoadCogVideoControlNet', ''],\n\n  // ---- DynamiCrafter (ComfyUI-DynamiCrafterWrapper) ----\n  ['checkpoints', 'DynamiCrafterModelLoader', 'ckpt_name'],\n  ['controlnet', 'DynamiCrafterCNLoader', 'ckpt_name'],\n\n  // ---- Inpaint (comfyui-inpaint-nodes) ----\n  ['inpaint', 'INPAINT_LoadInpaintModel', 'model_name'],\n  ['inpaint', 'INPAINT_LoadFooocusInpaint', 'head'],\n  ['inpaint', 'INPAINT_LoadFooocusInpaint', 'patch'],\n\n  // ---- YOLO object detection (comfyui_layerstyle) ----\n  ['yolo', 'LayerMask: ObjectDetectorYOLO8', 'yolo_model'],\n\n  // ---- MediaPipe face detection (comfyui-liveportrait) ----\n  ['mediapipe', 'LivePortraitLoadMediaPipeCropper', ''],\n\n  // ---- Superprompt text enhancement ----\n  ['superprompt-v1', 'Superprompt', ''],\n\n  // ---- ComfyUI core background removal (v0.21+) ----\n  ['background_removal', 'LoadBackgroundRemovalModel', 'bg_removal_name'],\n\n  // ---- ComfyUI core frame interpolation (v0.21+) ----\n  ['frame_interpolation', 'FrameInterpolationModelLoader', 'model_name'],\n\n  // ---- FILM frame interpolation (ComfyUI-Frame-Interpolation) ----\n  ['film', 'FILM VFI', 'ckpt_name'],\n  ['atm', 'ATM VFI', 'ckpt_name'],\n  ['momo', 'MOMO VFI', 'ckpt_name'],\n\n  // ---- Ultralytics YOLO detectors (ComfyUI-Impact-Pack) ----\n  // Intentionally NOT mapped to the asset-picker. The cloud asset-ingestion\n  // metadata for nested model folders (`ultralytics/bbox`, `ultralytics/segm`)\n  // still has the two known half-bugs described in #12075:\n  //   1. Tag lookup mismatch (cloud stores combined tags, picker queries split).\n  //   2. Submitted value mismatch (picker returns basenames, ingest expects\n  //      subdirectory-prefixed `bbox/<file>` / `segm/<file>`).\n  // PR #12151 re-added the bbox/segm entries before either half was fixed,\n  // reintroducing the FaceDetailer breakage. Until BE-689 lands the cloud-side\n  // fixes, leave these disabled so the node falls back to the static combo\n  // populated from `/api/object_info`.\n  // ['ultralytics/bbox', 'UltralyticsDetectorProvider', 'model_name'],\n  // ['ultralytics/segm', 'UltralyticsDetectorProvider', 'model_name'],\n\n  // ---- Mel-Band RoFormer audio separation (ComfyUI-MelBandRoFormer) ----\n  ['diffusion_models', 'MelBandRoFormerModelLoader', 'model_name'],\n\n  // ---- ComfyUI core geometry estimation (MoGe) ----\n  ['geometry_estimation', 'LoadMoGeModel', 'model_name'],\n\n  // ---- ComfyUI core optical flow (RAFT) ----\n  ['optical_flow', 'OpticalFlowLoader', 'model_name'],\n\n  // ---- WanVideo (ComfyUI-WanVideoWrapper) ----\n  ['loras', 'WanVideoLoraSelect', 'lora'],\n\n  // ---- LTX-Video IC-LoRA (ComfyUI-LTXVideo) ----\n  ['loras', 'LTXICLoRALoaderModelOnly', 'lora_name']\n] as const satisfies ReadonlyArray<readonly [string, string, string | RegExp]>\n","export interface WidgetValueBinding {\n  selector: string | RegExp\n  value: string\n}\n\nexport function matchesWidgetName(\n  name: string,\n  selector: string | RegExp\n): boolean {\n  return (\n    name !== '' &&\n    (typeof selector === 'string'\n      ? name === selector\n      : name.search(selector) !== -1)\n  )\n}\n","import { defineStore } from 'pinia'\nimport { computed, ref } from 'vue'\n\nimport { MODEL_NODE_MAPPINGS } from '@/platform/assets/mappings/modelNodeMappings'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { matchesWidgetName } from '@/utils/widgetBinding'\n\n/** Helper class that defines how to construct a node from a model. */\nexport class ModelNodeProvider {\n  /** The node definition to use for this model. */\n  public nodeDef: ComfyNodeDefImpl\n\n  /** The input name or pattern used to select the model widget. */\n  public key: string | RegExp\n\n  constructor(nodeDef: ComfyNodeDefImpl, key: string | RegExp) {\n    this.nodeDef = nodeDef\n    this.key = key\n  }\n}\n\n/** Service for mapping model types (by folder name) to nodes. */\nexport const useModelToNodeStore = defineStore('modelToNode', () => {\n  const modelToNodeMap = ref<Partial<Record<string, ModelNodeProvider[]>>>({})\n  const nodeDefStore = useNodeDefStore()\n  const haveDefaultsLoaded = ref(false)\n\n  const registeredNodeTypes = computed<\n    Partial<Record<string, string | RegExp>>\n  >(() =>\n    Object.fromEntries(\n      Object.values(modelToNodeMap.value)\n        .filter((providers) => providers !== undefined)\n        .flat()\n        .map((provider) => [provider.nodeDef.name, provider.key])\n    )\n  )\n\n  /** Internal computed for efficient reverse lookup: nodeType -> category */\n  const nodeTypeToCategory = computed(() => {\n    const lookup: Record<string, string> = {}\n    for (const [category, providers] of Object.entries(modelToNodeMap.value)) {\n      if (!providers) continue\n      for (const provider of providers) {\n        // Only store the first category for each node type (matches current assetService behavior)\n        if (!lookup[provider.nodeDef.name]) {\n          lookup[provider.nodeDef.name] = category\n        }\n      }\n    }\n    return lookup\n  })\n\n  /** Get set of all registered node types for efficient lookup */\n  function getRegisteredNodeTypes(): Partial<Record<string, string | RegExp>> {\n    registerDefaults()\n    return registeredNodeTypes.value\n  }\n\n  function isModelWidget(nodeType: string, widgetName: string): boolean {\n    const key = getRegisteredNodeTypes()[nodeType]\n    return key !== undefined && matchesWidgetName(widgetName, key)\n  }\n\n  /**\n   * Get the category for a given node type.\n   * Performs efficient O(1) lookup using cached reverse map.\n   * @param nodeType The node type name to find the category for\n   * @returns The category name, or undefined if not found\n   */\n  function getCategoryForNodeType(nodeType: string): string | undefined {\n    registerDefaults()\n\n    // Handle invalid input gracefully\n    if (!nodeType || typeof nodeType !== 'string') {\n      return undefined\n    }\n\n    return nodeTypeToCategory.value[nodeType]\n  }\n\n  /**\n   * Find providers for modelType with hierarchical fallback.\n   * Tries exact match first, then progressively shorter parent paths.\n   * e.g., \"a/b/c\" tries \"a/b/c\" → \"a/b\" → \"a\".\n   */\n  function findProvidersWithFallback(\n    modelType: string\n  ): ModelNodeProvider[] | undefined {\n    if (!modelType || typeof modelType !== 'string') {\n      return undefined\n    }\n\n    const segments = modelType.split('/')\n    for (let i = segments.length; i >= 1; i--) {\n      const path = segments.slice(0, i).join('/')\n      const providers = modelToNodeMap.value[path]\n      if (providers && providers.length > 0) return providers\n    }\n\n    return undefined\n  }\n\n  /**\n   * Get the node provider for the given model type name.\n   * Supports hierarchical lookups: if \"parent/child\" has no match, falls back to \"parent\".\n   * @param modelType The name of the model type to get the node provider for.\n   * @returns The node provider for the given model type name.\n   */\n  function getNodeProvider(modelType: unknown): ModelNodeProvider | undefined {\n    if (typeof modelType !== 'string') return undefined\n    registerDefaults()\n    return findProvidersWithFallback(modelType)?.[0]\n  }\n\n  /**\n   * Get the list of all valid node providers for the given model type name.\n   * Supports hierarchical lookups: if \"parent/child\" has no match, falls back to \"parent\".\n   * @param modelType The name of the model type to get the node providers for.\n   * @returns The list of all valid node providers for the given model type name.\n   */\n  function getAllNodeProviders(modelType: unknown): ModelNodeProvider[] {\n    if (typeof modelType !== 'string') return []\n    registerDefaults()\n    return findProvidersWithFallback(modelType) ?? []\n  }\n  /**\n   * Register a node provider for the given model type name.\n   * @param modelType The name of the model type to register the node provider for.\n   * @param nodeProvider The node provider to register.\n   */\n  function registerNodeProvider(\n    modelType: string,\n    nodeProvider:\n      | ModelNodeProvider\n      | { nodeDef: undefined; key: string | RegExp }\n  ) {\n    registerDefaults()\n    if (!nodeProvider.nodeDef) return\n    const providers = (modelToNodeMap.value[modelType] ??= [])\n    providers.push(nodeProvider)\n  }\n  /**\n   * Register a node provider for the given simple names.\n   * @param modelType The name of the model type to register the node provider for.\n   * @param nodeClass The node class name to register.\n   * @param key The key to use for the node input.\n   */\n  function quickRegister(\n    modelType: string,\n    nodeClass: string,\n    key: string | RegExp\n  ) {\n    registerNodeProvider(\n      modelType,\n      new ModelNodeProvider(nodeDefStore.nodeDefsByName[nodeClass], key)\n    )\n  }\n\n  function registerDefaults() {\n    if (haveDefaultsLoaded.value) {\n      return\n    }\n    if (Object.keys(nodeDefStore.nodeDefsByName).length === 0) {\n      return\n    }\n    haveDefaultsLoaded.value = true\n\n    for (const [modelType, nodeClass, key] of MODEL_NODE_MAPPINGS) {\n      quickRegister(modelType, nodeClass, key)\n    }\n  }\n\n  return {\n    modelToNodeMap,\n    getRegisteredNodeTypes,\n    isModelWidget,\n    getCategoryForNodeType,\n    getNodeProvider,\n    getAllNodeProviders,\n    registerNodeProvider,\n    quickRegister,\n    registerDefaults\n  }\n})\n","import { fromZodError } from 'zod-validation-error'\nimport { z } from 'zod'\n\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { st } from '@/i18n'\nimport { ASSETS_SEED_FAST_COMPLETE_EVENT } from '@/platform/assets/constants/assetEvents'\n\nimport {\n  assetFilenameSchema,\n  assetItemSchema,\n  assetResponseSchema,\n  asyncUploadResponseSchema,\n  tagsOperationResultSchema\n} from '@/platform/assets/schemas/assetSchema'\nimport type {\n  AssetId,\n  AssetItem,\n  AssetMetadata,\n  AssetResponse,\n  AssetUpdatePayload,\n  AsyncUploadResponse,\n  ModelFile,\n  TagsOperationResult\n} from '@/platform/assets/schemas/assetSchema'\nimport {\n  getAssetCategories,\n  getAssetFilename,\n  isModelTypeCovered\n} from '@/platform/assets/utils/assetMetadataUtils'\nimport { isCloud } from '@/platform/distribution/types'\nimport { api } from '@/scripts/api'\nimport { useModelToNodeStore } from '@/stores/modelToNodeStore'\nimport { parseErrorResponse } from '@/platform/remote/comfyui/errors'\n\nexport interface PaginationOptions {\n  limit?: number\n  offset?: number\n}\n\nexport interface AssetPaginationOptions extends PaginationOptions {\n  /**\n   * Opaque keyset cursor from a prior response's `next_cursor`. When set, the\n   * server resumes after that cursor and `offset` is ignored.\n   */\n  after?: string\n  signal?: AbortSignal\n}\n\ninterface AssetRequestOptions extends PaginationOptions {\n  includeTags: string[]\n  excludeTags?: string[]\n  includePublic?: boolean\n  after?: string\n  signal?: AbortSignal\n}\n\ninterface AssetExportOptions {\n  job_ids?: string[]\n  asset_ids?: AssetId[]\n  naming_strategy?:\n    | 'group_by_job_id'\n    | 'group_by_job_time'\n    | 'preserve'\n    | 'asset_id'\n  job_asset_name_filters?: Record<string, string[]>\n  include_previews?: boolean\n}\n\n/**\n * Maps CivitAI validation error codes to localized error messages\n */\nfunction getLocalizedErrorMessage(errorCode: string): string {\n  const errorMessages: Record<string, string> = {\n    // Validation errors\n    FILE_TOO_LARGE: st('assetBrowser.errorFileTooLarge', 'File too large'),\n    FORMAT_NOT_ALLOWED: st(\n      'assetBrowser.errorFormatNotAllowed',\n      'Format not allowed'\n    ),\n    UNSAFE_PICKLE_SCAN: st(\n      'assetBrowser.errorUnsafePickleScan',\n      'Unsafe pickle scan'\n    ),\n    UNSAFE_VIRUS_SCAN: st(\n      'assetBrowser.errorUnsafeVirusScan',\n      'Unsafe virus scan'\n    ),\n    MODEL_TYPE_NOT_SUPPORTED: st(\n      'assetBrowser.errorModelTypeNotSupported',\n      'Model type not supported'\n    ),\n\n    // HTTP 400 - Bad Request\n    INVALID_URL: st('assetBrowser.errorInvalidUrl', 'Please provide a URL.'),\n    INVALID_URL_FORMAT: st(\n      'assetBrowser.errorInvalidUrlFormat',\n      'The URL format is invalid. Please check and try again.'\n    ),\n    UNSUPPORTED_SOURCE: st(\n      'assetBrowser.errorUnsupportedSource',\n      'This URL is not supported. Only Hugging Face and Civitai URLs are allowed.'\n    ),\n\n    // HTTP 401 - Unauthorized\n    UNAUTHORIZED: st(\n      'assetBrowser.errorUnauthorized',\n      'Please sign in to continue.'\n    ),\n\n    // HTTP 422 - External Source Errors\n    USER_TOKEN_INVALID: st(\n      'assetBrowser.errorUserTokenInvalid',\n      'Your stored API token is invalid or expired. Please update your token in settings.'\n    ),\n    USER_TOKEN_ACCESS_DENIED: st(\n      'assetBrowser.errorUserTokenAccessDenied',\n      'Your API token does not have access to this resource. Please check your token permissions.'\n    ),\n    UNAUTHORIZED_SOURCE: st(\n      'assetBrowser.errorUnauthorizedSource',\n      'This resource requires authentication. Please add your API token in settings.'\n    ),\n    ACCESS_FORBIDDEN: st(\n      'assetBrowser.errorAccessForbidden',\n      'Access to this resource is forbidden.'\n    ),\n    RESOURCE_NOT_FOUND: st(\n      'assetBrowser.errorResourceNotFound',\n      'The file was not found. Please check the URL and try again.'\n    ),\n    RATE_LIMITED: st(\n      'assetBrowser.errorRateLimited',\n      'Too many requests. Please try again in a few minutes.'\n    ),\n    SOURCE_SERVER_ERROR: st(\n      'assetBrowser.errorSourceServerError',\n      'The source server is experiencing issues. Please try again later.'\n    ),\n    NETWORK_TIMEOUT: st(\n      'assetBrowser.errorNetworkTimeout',\n      'Request timed out. Please try again.'\n    ),\n    CONNECTION_REFUSED: st(\n      'assetBrowser.errorConnectionRefused',\n      'Unable to connect to the source. Please try again later.'\n    ),\n    INVALID_HOST: st(\n      'assetBrowser.errorInvalidHost',\n      'The source URL hostname could not be resolved.'\n    ),\n    NETWORK_ERROR: st(\n      'assetBrowser.errorNetworkError',\n      'A network error occurred. Please check your connection and try again.'\n    ),\n    REQUEST_CANCELLED: st(\n      'assetBrowser.errorRequestCancelled',\n      'Request was cancelled.'\n    ),\n    DOWNLOAD_CANCELLED: st(\n      'assetBrowser.errorDownloadCancelled',\n      'Download was cancelled.'\n    ),\n    METADATA_FETCH_FAILED: st(\n      'assetBrowser.errorMetadataFetchFailed',\n      'Failed to fetch file information from the source.'\n    ),\n    HTTP_ERROR: st(\n      'assetBrowser.errorHttpError',\n      'An error occurred while fetching metadata.'\n    ),\n\n    // HTTP 500 - Internal Server Errors\n    SERVICE_UNAVAILABLE: st(\n      'assetBrowser.errorServiceUnavailable',\n      'Service temporarily unavailable. Please try again later.'\n    ),\n    INTERNAL_ERROR: st(\n      'assetBrowser.errorInternalError',\n      'An unexpected error occurred. Please try again.'\n    )\n  }\n  return (\n    errorMessages[errorCode] ||\n    st('assetBrowser.errorUnknown', 'Unknown error') ||\n    'Unknown error'\n  )\n}\n\nconst ASSETS_ENDPOINT = '/assets'\nconst ASSETS_SEED_ENDPOINT = '/assets/seed'\nconst ASSETS_DOWNLOAD_ENDPOINT = '/assets/download'\nconst ASSETS_EXPORT_ENDPOINT = '/assets/export'\nconst DEFAULT_LIMIT = 500\n// Defensive backstop against a server that never signals exhaustion (e.g. an\n// unbounded stream of unique cursors); mirrors assetsStore's walk cap. At\n// DEFAULT_LIMIT per page this allows 500k assets per walk, so it only ever\n// trips on pathological pagination.\nconst MAX_PAGINATION_BATCHES = 1000\n\nexport const MODELS_TAG = 'models'\nexport const INPUT_TAG = 'input'\nexport const OUTPUT_TAG = 'output'\n/** Asset tag used by the backend for placeholder records that are not installed. */\nexport const MISSING_TAG = 'missing'\nconst DEFAULT_EXCLUDED_ASSET_TAGS = [MISSING_TAG]\nconst EMPTY_PAGE: AssetResponse = { assets: [], total: 0, has_more: false }\n\nconst uploadedAssetResponseSchema = assetItemSchema.extend({\n  created_new: z.boolean()\n})\n\nfunction normalizeAssetTags(tags: string[]): string[] {\n  return tags.map((tag) => tag.trim()).filter(Boolean)\n}\n\n/**\n * Orders loader paths as subdirectories before files at every level,\n * alphabetical within each group. The asset API returns models in storage\n * order, which would otherwise interleave root-level files with folder\n * contents in the sidebar tree.\n */\nfunction compareLoaderPaths(a: string, b: string): number {\n  const aSegments = a.split('/')\n  const bSegments = b.split('/')\n  const sharedDepth = Math.min(aSegments.length, bSegments.length)\n  for (let i = 0; i < sharedDepth; i++) {\n    const aIsFile = i === aSegments.length - 1\n    const bIsFile = i === bSegments.length - 1\n    if (aIsFile !== bIsFile) return aIsFile ? 1 : -1\n    const order = aSegments[i].localeCompare(bSegments[i], undefined, {\n      numeric: true\n    })\n    if (order !== 0) return order\n  }\n  return 0\n}\n\n/**\n * Validates asset response data using Zod schema\n */\nfunction validateAssetResponse(data: unknown): AssetResponse {\n  const result = assetResponseSchema.safeParse(data)\n  if (result.success) return result.data\n\n  const error = fromZodError(result.error)\n  throw new Error(`Invalid asset response against zod schema:\\n${error}`)\n}\n\nfunction validateUploadedAssetResponse(\n  data: unknown\n): AssetItem & { created_new: boolean } {\n  const result = uploadedAssetResponseSchema.safeParse(data)\n  if (result.success) {\n    return result.data\n  }\n\n  console.error('Invalid asset upload response:', fromZodError(result.error))\n  throw new Error(\n    st(\n      'assetBrowser.errorUploadFailed',\n      'Failed to upload asset. Please try again.'\n    )\n  )\n}\n\n/**\n * Private service for asset-related network requests\n * Not exposed globally - used internally by ComfyApi\n */\nfunction createAssetService() {\n  /**\n   * Model assets bucketed by folder category, built from a single walk of the\n   * `models` tag rather than a fetch per category. Shared by the folder list\n   * and per-folder listings so the sidebar loads every model in one pass.\n   */\n  let modelBuckets: Map<string, AssetItem[]> | null = null\n  let modelBucketsRequestId = 0\n  let pendingModelBuckets: Promise<Map<string, AssetItem[]>> | null = null\n  // The supports_model_type_tags value the cached buckets were built under.\n  // The flag arrives asynchronously over the websocket handshake, so a cache\n  // built before it lands (or surviving a reconnect that flips it) groups tags\n  // by the wrong scheme and must be discarded.\n  let modelBucketsMode: boolean | null = null\n\n  /**\n   * Discards the cached model buckets so the next read re-walks the models\n   * tag. Bumping the request id keeps a walk that was already in flight from\n   * repopulating the cache with pre-invalidation data.\n   */\n  function invalidateModelBuckets(): void {\n    modelBucketsRequestId++\n    modelBuckets = null\n    pendingModelBuckets = null\n  }\n\n  /**\n   * Handles API response with consistent error handling and Zod validation\n   */\n  async function handleAssetRequest(\n    options: AssetRequestOptions,\n    context: string\n  ): Promise<AssetResponse> {\n    const {\n      includeTags,\n      excludeTags = DEFAULT_EXCLUDED_ASSET_TAGS,\n      limit = DEFAULT_LIMIT,\n      offset,\n      after,\n      includePublic,\n      signal\n    } = options\n    const normalizedIncludeTags = normalizeAssetTags(includeTags)\n    const normalizedExcludeTags = normalizeAssetTags(excludeTags)\n\n    const queryParams = new URLSearchParams({\n      include_tags: normalizedIncludeTags.join(','),\n      limit: limit.toString()\n    })\n    if (normalizedExcludeTags.length > 0) {\n      queryParams.set('exclude_tags', normalizedExcludeTags.join(','))\n    }\n    // `after` (keyset cursor) takes precedence over `offset`; the server ignores\n    // `offset` when a cursor is supplied, so we avoid sending a redundant param.\n    if (after !== undefined) {\n      queryParams.set('after', after)\n    } else if (offset !== undefined && offset > 0) {\n      queryParams.set('offset', offset.toString())\n    }\n    if (includePublic !== undefined) {\n      queryParams.set('include_public', includePublic ? 'true' : 'false')\n    }\n\n    const url = `${ASSETS_ENDPOINT}?${queryParams.toString()}`\n    const res = signal\n      ? await api.fetchApi(url, { signal })\n      : await api.fetchApi(url)\n    if (!res.ok) {\n      throw new Error(\n        `Unable to load ${context}: Server returned ${res.status}. Please try again.`\n      )\n    }\n    const data = await res.json()\n    return validateAssetResponse(data)\n  }\n  /**\n   * Walks every `models`-tagged asset once and buckets each into the folder\n   * categories `getAssetCategories` resolves for it. A single asset lands in\n   * every category it is tagged with (e.g. a shared-root model in both\n   * `checkpoints` and `diffusion_models`); an asset covered by `model_type:`\n   * tags is grouped by those alone, so a legacy bare-tag twin left over from a\n   * partial re-tagging cannot also cross-list it into another folder. Which\n   * folders are actually shown is decided by `/experiment/models`; models with\n   * no category tag are dropped with a warning rather than hidden silently.\n   */\n  async function buildModelBuckets(\n    modelTypeMode: boolean\n  ): Promise<Map<string, AssetItem[]>> {\n    // Private-only, matching the legacy per-folder listing this walk\n    // replaces: the local sidebar never surfaced public/community assets.\n    const assets = await getAllAssetsByTag(MODELS_TAG, false)\n    const buckets = new Map<string, AssetItem[]>()\n\n    for (const asset of assets) {\n      const folders = [...new Set(getAssetCategories(asset, modelTypeMode))]\n\n      if (folders.length === 0) {\n        console.warn(\n          `Asset ${asset.id} (${asset.name}) is tagged '${MODELS_TAG}' but has no model category; skipping.`\n        )\n        continue\n      }\n\n      // On loader_path-contract backends a null loader_path marks an\n      // unloadable asset (e.g. an orphan): it must not mint a widget value,\n      // and `name` is deprecated for path semantics.\n      if (modelTypeMode && !asset.loader_path) {\n        console.warn(\n          `Asset ${asset.id} (${asset.name}) has no loader_path; skipping.`\n        )\n        continue\n      }\n\n      // The loader value flows into viewMetadata URLs and widget values, so a\n      // traversal-shaped path must not pass through even if the backend's own\n      // validation ever regresses.\n      const loaderValue = asset.loader_path ?? getAssetFilename(asset)\n      if (!assetFilenameSchema.safeParse(loaderValue).success) {\n        console.warn(\n          `Asset ${asset.id} (${asset.name}) has an unsafe loader path ('${loaderValue}'); skipping.`\n        )\n        continue\n      }\n\n      for (const folder of folders) {\n        const bucket = buckets.get(folder)\n        if (bucket) bucket.push(asset)\n        else buckets.set(folder, [asset])\n      }\n    }\n\n    for (const bucket of buckets.values()) {\n      bucket.sort((a, b) =>\n        compareLoaderPaths(\n          a.loader_path ?? getAssetFilename(a),\n          b.loader_path ?? getAssetFilename(b)\n        )\n      )\n    }\n\n    return buckets\n  }\n\n  /** Returns the memoized model buckets, walking the models tag on first read. */\n  async function loadModelBuckets(): Promise<Map<string, AssetItem[]>> {\n    const modelTypeMode = useFeatureFlags().flags.supportsModelTypeTags\n    // Discard a cache (or in-flight walk) built under a different flag value:\n    // the buckets would key tags by the wrong scheme otherwise.\n    if (modelBucketsMode !== modelTypeMode) invalidateModelBuckets()\n    if (modelBuckets) return modelBuckets\n    if (pendingModelBuckets) return pendingModelBuckets\n\n    modelBucketsMode = modelTypeMode\n    const requestId = ++modelBucketsRequestId\n    const walk = async () => {\n      try {\n        const buckets = await buildModelBuckets(modelTypeMode)\n        if (requestId === modelBucketsRequestId) {\n          modelBuckets = buckets\n        }\n        return buckets\n      } finally {\n        if (requestId === modelBucketsRequestId) {\n          pendingModelBuckets = null\n        }\n      }\n    }\n\n    pendingModelBuckets = walk()\n    return pendingModelBuckets\n  }\n\n  /**\n   * Gets the models in the specified folder from the single models walk.\n   * @param folder The folder to list models from, such as 'checkpoints'\n   * @returns The list of model filenames within the specified folder\n   */\n  async function getAssetModels(folder: string): Promise<ModelFile[]> {\n    const modelTypeMode = useFeatureFlags().flags.supportsModelTypeTags\n    const buckets = await loadModelBuckets()\n    const assets =\n      buckets.get(folder) ??\n      buckets\n        .get(folder.split('/')[0])\n        ?.filter(\n          (asset) =>\n            !(modelTypeMode && isModelTypeCovered(asset)) &&\n            asset.tags.some(\n              (tag) => tag === folder || tag.startsWith(`${folder}/`)\n            )\n        )\n\n    return (assets ?? []).map((asset) => ({\n      // `loader_path` is the category-relative path the loader widget expects\n      // and the source for the sidebar tree. Backends that predate it (bare-tag\n      // mode; today's cloud) fall back to the filename metadata — the same\n      // value the asset browser serializes — rather than `name`, which is a\n      // content hash on cloud.\n      name: asset.loader_path ?? getAssetFilename(asset),\n      // Asset records carry no root identity, so every model reports root 0.\n      // Known limitation on multi-root categories (extra_model_paths.yaml):\n      // preview reads target root 0 (wrong file or 404 for secondary-root\n      // files), and same-relative-path files in different roots collapse\n      // onto one sidebar row. Metadata is unaffected unless relative paths\n      // collide (/view_metadata searches roots in order without an index),\n      // as are loader widget values; lifting this needs the backend to carry\n      // root identity on assets.\n      pathIndex: 0\n    }))\n  }\n\n  /**\n   * Asks the backend to rescan the model roots on disk so newly added files\n   * become assets. Fire-and-forget: the scan's fast (insert) phase already\n   * writes the category tags and filenames the sidebar needs and is announced\n   * by an `assets.seed.fast_complete` websocket event. A 409 means a scan is\n   * already running, which will emit the same event, so it is not an error.\n   */\n  async function seedModelAssets(): Promise<void> {\n    const res = await api.fetchApi(ASSETS_SEED_ENDPOINT, {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ roots: ['models'] })\n    })\n    if (!res.ok && res.status !== 409) {\n      throw new Error(\n        `Unable to start asset scan: Server returned ${res.status}`\n      )\n    }\n  }\n\n  /**\n   * Subscribes to the backend's scan fast-phase completion broadcast — the\n   * moment newly scanned files' tags and loader paths become queryable. The\n   * wire-level event name is shared via `ASSETS_SEED_FAST_COMPLETE_EVENT`;\n   * consumers receive a callback and an unsubscribe function.\n   */\n  function onModelsScanned(callback: () => void | Promise<void>): () => void {\n    const handler = () => {\n      void callback()\n    }\n    api.addCustomEventListener(ASSETS_SEED_FAST_COMPLETE_EVENT, handler)\n    return () => {\n      api.removeCustomEventListener(ASSETS_SEED_FAST_COMPLETE_EVENT, handler)\n    }\n  }\n\n  /**\n   * Checks if a widget input should use the asset browser based on both input name and node comfyClass\n   *\n   * @param nodeType - The ComfyUI node comfyClass (e.g., 'CheckpointLoaderSimple', 'LoraLoader')\n   * @param widgetName - The name of the widget to check (e.g., 'ckpt_name')\n   * @returns true if this input should use asset browser\n   */\n  function isAssetBrowserEligible(\n    nodeType: string | undefined,\n    widgetName: string\n  ): boolean {\n    if (!nodeType || !widgetName) return false\n    return useModelToNodeStore().isModelWidget(nodeType, widgetName)\n  }\n\n  /**\n   * Whether widget-embedded asset pickers (canvas + Vue node model widgets) are\n   * enabled. Hardcoded to cloud: MODEL_NODE_MAPPINGS is only maintained for\n   * cloud asset tagging. NOT the asset-API gate — that is\n   * useFeatureFlags().flags.assetsEnabled.\n   */\n  function isWidgetAssetPickerEnabled(): boolean {\n    return isCloud\n  }\n\n  /**\n   * Checks if the asset browser should be used for a given node input.\n   * Combines the cloud environment check, user setting, and eligibility check.\n   *\n   * @param nodeType - The ComfyUI node comfyClass\n   * @param widgetName - The name of the widget to check\n   * @returns true if this input should use the asset browser\n   */\n  function shouldUseWidgetAssetPicker(\n    nodeType: string | undefined,\n    widgetName: string\n  ): boolean {\n    return (\n      isWidgetAssetPickerEnabled() &&\n      isAssetBrowserEligible(nodeType, widgetName)\n    )\n  }\n\n  /**\n   * Gets assets for a specific node type by finding the matching category\n   * and fetching all assets with that category tag\n   *\n   * @param nodeType - The ComfyUI node type (e.g., 'CheckpointLoaderSimple')\n   * @param options - Pagination options\n   * @param options.limit - Maximum number of assets to return (default: 500)\n   * @param options.offset - Number of assets to skip (default: 0)\n   * @returns Promise<AssetItem[]> - Full asset objects with preserved metadata\n   */\n  async function getAssetsForNodeType(\n    nodeType: string,\n    options: PaginationOptions = {}\n  ): Promise<AssetItem[]> {\n    const data = await getAssetsPageForNodeType(nodeType, options)\n\n    // Return full AssetItem[] objects (don't strip like getAssetModels does)\n    return data.assets\n  }\n\n  /**\n   * Gets one paginated asset response for a specific node type by finding the\n   * matching category and fetching assets with that category tag.\n   *\n   * Unlike {@link getAssetsForNodeType}, the full response envelope is\n   * returned so callers can drive keyset cursor pagination from\n   * `next_cursor`/`has_more`.\n   *\n   * @param nodeType - The ComfyUI node type (e.g., 'CheckpointLoaderSimple')\n   * @param options - Pagination options\n   * @param options.limit - Maximum number of assets to return (default: 500)\n   * @param options.offset - Number of assets to skip (ignored when `after` is set)\n   * @param options.after - Keyset cursor from a prior response's `next_cursor`\n   * @param options.signal - Optional abort signal for cancelling the request\n   * @returns Promise<AssetResponse> - Page of assets plus pagination metadata\n   */\n  async function getAssetsPageForNodeType(\n    nodeType: string,\n    {\n      limit = DEFAULT_LIMIT,\n      offset = 0,\n      after,\n      signal\n    }: AssetPaginationOptions = {}\n  ): Promise<AssetResponse> {\n    if (!nodeType || typeof nodeType !== 'string') {\n      return EMPTY_PAGE\n    }\n\n    // Find the category for this node type using efficient O(1) lookup\n    const modelToNodeStore = useModelToNodeStore()\n    const category = modelToNodeStore.getCategoryForNodeType(nodeType)\n\n    if (!category) {\n      return EMPTY_PAGE\n    }\n\n    // Fetch assets for this category using same API pattern as getAssetModels\n    return await handleAssetRequest(\n      { includeTags: [MODELS_TAG, category], limit, offset, after, signal },\n      `assets for ${nodeType}`\n    )\n  }\n\n  /**\n   * Gets complete details for a specific asset by ID\n   * Calls the detail endpoint which includes user_metadata and all fields\n   *\n   * @param id - The asset ID\n   * @returns Promise<AssetItem> - Complete asset object with user_metadata\n   */\n  async function getAssetDetails(id: AssetId): Promise<AssetItem> {\n    const res = await api.fetchApi(`${ASSETS_ENDPOINT}/${id}`)\n    if (!res.ok) {\n      throw new Error(\n        `Unable to load asset details for ${id}: Server returned ${res.status}. Please try again.`\n      )\n    }\n    const data = await res.json()\n\n    const result = assetItemSchema.safeParse(data)\n    if (result.success) return result.data\n\n    const error = fromZodError(result.error)\n    throw new Error(`Invalid asset response against zod schema:\\n${error}`)\n  }\n\n  /**\n   * Gets assets filtered by a specific tag\n   *\n   * @param tag - The tag to filter by (e.g., 'models', 'input')\n   * @param includePublic - Whether to include public assets (default: true)\n   * @param options - Pagination options\n   * @param options.limit - Maximum number of assets to return (default: 500)\n   * @param options.offset - Number of assets to skip (default: 0)\n   * @param options.signal - Optional abort signal for cancelling the request\n   * @returns Promise<AssetItem[]> - Full asset objects filtered by tag, excluding missing assets\n   */\n  async function getAssetsByTag(\n    tag: string,\n    includePublic: boolean = true,\n    {\n      limit = DEFAULT_LIMIT,\n      offset = 0,\n      after,\n      signal\n    }: AssetPaginationOptions = {}\n  ): Promise<AssetItem[]> {\n    const data = await getAssetsPageByTag(tag, includePublic, {\n      limit,\n      offset,\n      after,\n      signal\n    })\n\n    return data.assets\n  }\n\n  /**\n   * Gets one paginated asset response filtered by a specific tag.\n   */\n  async function getAssetsPageByTag(\n    tag: string,\n    includePublic: boolean = true,\n    {\n      limit = DEFAULT_LIMIT,\n      offset = 0,\n      after,\n      signal\n    }: AssetPaginationOptions = {}\n  ): Promise<AssetResponse> {\n    return await handleAssetRequest(\n      { includeTags: [tag], limit, offset, after, includePublic, signal },\n      `assets for tag ${tag}`\n    )\n  }\n\n  /**\n   * Gets every asset for a tag by walking paginated asset API responses.\n   *\n   * Uses keyset (cursor) pagination: each page is fetched with the prior\n   * response's `next_cursor`, which is stable under concurrent inserts/deletes\n   * and avoids the duplicate/skip drift that offset paging exhibits when the\n   * underlying set changes mid-walk. Falls back to terminating on `has_more`\n   * when the server omits `next_cursor`.\n   *\n   * @param tag - The tag to filter by (e.g., 'models', 'input')\n   * @param includePublic - Whether to include public assets (default: true)\n   * @param options - Pagination options\n   * @param options.limit - Page size for each request (default: 500)\n   * @param options.signal - Optional abort signal for cancelling requests\n   * @returns Promise<AssetItem[]> - Full asset objects filtered by tag\n   */\n  async function getAllAssetsByTag(\n    tag: string,\n    includePublic: boolean = true,\n    {\n      limit = DEFAULT_LIMIT,\n      signal\n    }: Pick<AssetPaginationOptions, 'limit' | 'signal'> = {}\n  ): Promise<AssetItem[]> {\n    const assets: AssetItem[] = []\n    const pageSize = limit > 0 ? limit : DEFAULT_LIMIT\n    let after: string | undefined\n    let batchCount = 0\n\n    for (;;) {\n      if (signal?.aborted) throw new DOMException('Aborted', 'AbortError')\n      if (batchCount++ >= MAX_PAGINATION_BATCHES) {\n        console.warn(\n          `Paginated walk for tag '${tag}' hit the ${MAX_PAGINATION_BATCHES}-batch backstop; returning a truncated listing.`\n        )\n        return assets\n      }\n\n      const data = await getAssetsPageByTag(tag, includePublic, {\n        limit: pageSize,\n        after,\n        signal\n      })\n      const batch = data.assets\n      if (batch.length === 0) {\n        return assets\n      }\n\n      assets.push(...batch)\n\n      // A server that returns a non-advancing cursor would loop forever.\n      if (!data.has_more || !data.next_cursor || data.next_cursor === after) {\n        return assets\n      }\n\n      after = data.next_cursor\n    }\n  }\n\n  /**\n   * Deletes an asset by ID\n   * Only available in cloud environment\n   *\n   * @param id - The asset ID (UUID)\n   * @returns Promise<void>\n   * @throws Error if deletion fails\n   */\n  async function deleteAsset(id: AssetId): Promise<void> {\n    const res = await api.fetchApi(`${ASSETS_ENDPOINT}/${id}`, {\n      method: 'DELETE'\n    })\n\n    if (!res.ok) {\n      throw new Error(\n        `Unable to delete asset ${id}: Server returned ${res.status}`\n      )\n    }\n  }\n\n  /**\n   * Update metadata of an asset by ID\n   * Only available in cloud environment\n   *\n   * @param id - The asset ID (UUID)\n   * @param newData - The data to update\n   * @returns Promise<AssetItem>\n   * @throws Error if update fails\n   */\n  async function updateAsset(\n    id: AssetId,\n    newData: AssetUpdatePayload\n  ): Promise<AssetItem> {\n    const res = await api.fetchApi(`${ASSETS_ENDPOINT}/${id}`, {\n      method: 'PUT',\n      headers: {\n        'Content-Type': 'application/json'\n      },\n      body: JSON.stringify(newData)\n    })\n\n    if (!res.ok) {\n      throw new Error(\n        `Unable to update asset ${id}: Server returned ${res.status}`\n      )\n    }\n\n    const newAsset = assetItemSchema.safeParse(await res.json())\n    if (newAsset.success) {\n      return newAsset.data\n    }\n\n    throw new Error(\n      `Unable to update asset ${id}: Invalid response - ${newAsset.error}`\n    )\n  }\n\n  /**\n   * Retrieves metadata from a download URL without downloading the file\n   *\n   * @param url - Download URL to retrieve metadata from (will be URL-encoded)\n   * @returns Promise with metadata including content_length, final_url, filename, etc.\n   * @throws Error if metadata retrieval fails\n   */\n  async function getAssetMetadata(url: string): Promise<AssetMetadata> {\n    const encodedUrl = encodeURIComponent(url)\n    const res = await api.fetchApi(\n      `${ASSETS_ENDPOINT}/remote-metadata?url=${encodedUrl}`\n    )\n\n    if (!res.ok) {\n      const { code } = await parseErrorResponse(res)\n      throw new Error(getLocalizedErrorMessage(code))\n    }\n\n    const data: AssetMetadata = await res.json()\n    if (data.validation?.is_valid === false) {\n      throw new Error(\n        getLocalizedErrorMessage(\n          data.validation.errors?.[0]?.code || 'UNKNOWN_ERROR'\n        )\n      )\n    }\n\n    return data\n  }\n\n  /**\n   * Uploads an asset by providing a URL to download from\n   *\n   * @param params - Upload parameters\n   * @param params.url - HTTP/HTTPS URL to download from\n   * @param params.name - Display name (determines extension)\n   * @param params.tags - Optional freeform tags\n   * @param params.user_metadata - Optional custom metadata object\n   * @param params.preview_id - Optional UUID for preview asset\n   * @returns Promise<AssetItem & { created_new: boolean }> - Asset object with created_new flag\n   * @throws Error if upload fails\n   */\n  async function uploadAssetFromUrl(params: {\n    url: string\n    name: string\n    tags?: string[]\n    user_metadata?: Record<string, unknown>\n    preview_id?: string\n  }): Promise<AssetItem & { created_new: boolean }> {\n    const res = await api.fetchApi(ASSETS_ENDPOINT, {\n      method: 'POST',\n      headers: {\n        'Content-Type': 'application/json'\n      },\n      body: JSON.stringify(params)\n    })\n\n    if (!res.ok) {\n      throw new Error(\n        st(\n          'assetBrowser.errorUploadFailed',\n          'Failed to upload asset. Please try again.'\n        )\n      )\n    }\n\n    const asset = validateUploadedAssetResponse(await res.json())\n    return asset\n  }\n\n  /**\n   * Uploads an asset from base64 data\n   *\n   * @param params - Upload parameters\n   * @param params.data - Base64 data URL (e.g., \"data:image/png;base64,...\")\n   * @param params.name - Display name (determines extension)\n   * @param params.tags - Optional freeform tags\n   * @param params.user_metadata - Optional custom metadata object\n   * @returns Promise<AssetItem & { created_new: boolean }> - Asset object with created_new flag\n   * @throws Error if upload fails\n   */\n  async function uploadAssetFromBase64(params: {\n    data: string\n    name: string\n    tags?: string[]\n    user_metadata?: Record<string, unknown>\n  }): Promise<AssetItem & { created_new: boolean }> {\n    // Validate that data is a data URL\n    if (!params.data || !params.data.startsWith('data:')) {\n      throw new Error(\n        'Invalid data URL: expected a string starting with \"data:\"'\n      )\n    }\n\n    // Convert base64 data URL to Blob\n    const blob = await fetch(params.data).then((r) => r.blob())\n\n    // Create FormData and append the blob\n    const formData = new FormData()\n    formData.append('file', blob, params.name)\n\n    if (params.tags) {\n      formData.append('tags', JSON.stringify(params.tags))\n    }\n\n    if (params.user_metadata) {\n      formData.append('user_metadata', JSON.stringify(params.user_metadata))\n    }\n\n    const res = await api.fetchApi(ASSETS_ENDPOINT, {\n      method: 'POST',\n      body: formData\n    })\n\n    if (!res.ok) {\n      throw new Error(\n        `Failed to upload asset from base64: ${res.status} ${res.statusText}`\n      )\n    }\n\n    const asset = validateUploadedAssetResponse(await res.json())\n    return asset\n  }\n\n  /**\n   * Add tags to an asset\n   * @param id - The asset ID (UUID)\n   * @param tags - Tags to add\n   * @returns Promise<TagsOperationResult>\n   */\n  async function addAssetTags(\n    id: string,\n    tags: string[]\n  ): Promise<TagsOperationResult> {\n    const res = await api.fetchApi(`${ASSETS_ENDPOINT}/${id}/tags`, {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ tags })\n    })\n\n    if (!res.ok) {\n      throw new Error(\n        `Unable to add tags to asset ${id}: Server returned ${res.status}`\n      )\n    }\n\n    const result = await res.json()\n    const parseResult = tagsOperationResultSchema.safeParse(result)\n    if (!parseResult.success) {\n      throw fromZodError(parseResult.error)\n    }\n    return parseResult.data\n  }\n\n  /**\n   * Remove tags from an asset\n   * @param id - The asset ID (UUID)\n   * @param tags - Tags to remove\n   * @returns Promise<TagsOperationResult>\n   */\n  async function removeAssetTags(\n    id: string,\n    tags: string[]\n  ): Promise<TagsOperationResult> {\n    const res = await api.fetchApi(`${ASSETS_ENDPOINT}/${id}/tags`, {\n      method: 'DELETE',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ tags })\n    })\n\n    if (!res.ok) {\n      throw new Error(\n        `Unable to remove tags from asset ${id}: Server returned ${res.status}`\n      )\n    }\n\n    const result = await res.json()\n    const parseResult = tagsOperationResultSchema.safeParse(result)\n    if (!parseResult.success) {\n      throw fromZodError(parseResult.error)\n    }\n    return parseResult.data\n  }\n\n  /**\n   * Uploads an asset asynchronously using the /api/assets/download endpoint\n   * Returns immediately with either the asset (if already exists) or a task to track\n   *\n   * @param params - Upload parameters\n   * @param params.source_url - HTTP/HTTPS URL to download from\n   * @param params.tags - Optional freeform tags\n   * @param params.user_metadata - Optional custom metadata object\n   * @param params.preview_id - Optional UUID for preview asset\n   * @returns Promise<AsyncUploadResponse> - Either sync asset or async task info\n   * @throws Error if upload fails\n   */\n  async function uploadAssetAsync(params: {\n    source_url: string\n    tags?: string[]\n    user_metadata?: Record<string, unknown>\n    preview_id?: string\n  }): Promise<AsyncUploadResponse> {\n    const res = await api.fetchApi(ASSETS_DOWNLOAD_ENDPOINT, {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(params)\n    })\n\n    if (!res.ok) {\n      throw new Error(\n        st(\n          'assetBrowser.errorUploadFailed',\n          'Failed to upload asset. Please try again.'\n        )\n      )\n    }\n\n    const data = await res.json()\n\n    if (res.status === 202) {\n      const result = asyncUploadResponseSchema.safeParse({\n        type: 'async',\n        task: data\n      })\n      if (!result.success) {\n        throw new Error(\n          st(\n            'assetBrowser.errorUploadFailed',\n            'Failed to parse async upload response. Please try again.'\n          )\n        )\n      }\n      return result.data\n    }\n\n    const result = asyncUploadResponseSchema.safeParse({\n      type: 'sync',\n      asset: data\n    })\n    if (!result.success) {\n      throw new Error(\n        st(\n          'assetBrowser.errorUploadFailed',\n          'Failed to parse sync upload response. Please try again.'\n        )\n      )\n    }\n    return result.data\n  }\n\n  async function createAssetExport(\n    params: AssetExportOptions\n  ): Promise<{ task_id: string; status: string; message?: string }> {\n    const res = await api.fetchApi(ASSETS_EXPORT_ENDPOINT, {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(params)\n    })\n\n    if (!res.ok) {\n      throw new Error(`Failed to create asset export: ${res.status}`)\n    }\n\n    return await res.json()\n  }\n\n  async function getExportDownloadUrl(\n    exportName: string\n  ): Promise<{ url: string; expires_at?: string }> {\n    const res = await api.fetchApi(`/assets/exports/${exportName}`)\n\n    if (!res.ok) {\n      throw new Error(`Failed to get export download URL: ${res.status}`)\n    }\n\n    return await res.json()\n  }\n\n  return {\n    getAssetModels,\n    invalidateModelBuckets,\n    onModelsScanned,\n    seedModelAssets,\n    isWidgetAssetPickerEnabled,\n    isAssetBrowserEligible,\n    shouldUseWidgetAssetPicker,\n    getAssetsForNodeType,\n    getAssetsPageForNodeType,\n    getAssetDetails,\n    getAssetsByTag,\n    getAssetsPageByTag,\n    getAllAssetsByTag,\n    deleteAsset,\n    updateAsset,\n    addAssetTags,\n    removeAssetTags,\n    getAssetMetadata,\n    uploadAssetFromUrl,\n    uploadAssetFromBase64,\n    uploadAssetAsync,\n    createAssetExport,\n    getExportDownloadUrl\n  }\n}\n\nexport const assetService = createAssetService()\n","import type { Component } from 'vue'\n\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport type { AssetBrowserModalProps } from '@/platform/assets/types/assetBrowserModalProps'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useDialogService } from '@/services/dialogService'\nimport { useDialogStore } from '@/stores/dialogStore'\n\ninterface ShowOptions {\n  /** ComfyUI node type for context (e.g., 'CheckpointLoaderSimple') */\n  nodeType: string\n  /** Widget input name (e.g., 'ckpt_name') */\n  inputName: string\n  /** Current selected asset value */\n  currentValue?: string\n  onAssetSelected?: (asset: AssetItem) => void\n}\n\ninterface BrowseOptions {\n  /** Asset type tag to filter by (e.g., 'models') */\n  assetType: string\n  /** Custom modal title (optional) */\n  title?: string\n  /** Called when asset selected */\n  onAssetSelected?: (asset: AssetItem) => void\n}\n\nconst DIALOG_KEY = 'global-asset-browser'\n\nlet assetBrowserModalComponent: Component<AssetBrowserModalProps> | undefined\n\nexport function registerAssetBrowserModalComponent(\n  component: Component<AssetBrowserModalProps>\n) {\n  assetBrowserModalComponent = component\n}\n\nexport const useAssetBrowserDialog = () => {\n  const dialogService = useDialogService()\n  const dialogStore = useDialogStore()\n\n  function openModal(props: AssetBrowserModalProps) {\n    if (!assetBrowserModalComponent) {\n      reportError(\n        new Error('Asset browser modal component is not registered'),\n        {\n          errorType: 'failure_opening_asset_browser_modal',\n          surface: 'assets'\n        }\n      )\n      return\n    }\n    dialogService.showLayoutDialog({\n      key: DIALOG_KEY,\n      component: assetBrowserModalComponent,\n      props\n    })\n  }\n\n  function hide() {\n    dialogStore.closeDialog({ key: DIALOG_KEY })\n  }\n\n  function show(props: ShowOptions) {\n    const handleAssetSelected = (asset: AssetItem) => {\n      props.onAssetSelected?.(asset)\n      hide()\n    }\n\n    openModal({\n      nodeType: props.nodeType,\n      onSelect: handleAssetSelected,\n      onClose: hide\n    })\n  }\n\n  function browse(options: BrowseOptions) {\n    const handleAssetSelected = (asset: AssetItem) => {\n      options.onAssetSelected?.(asset)\n      hide()\n    }\n\n    openModal({\n      showLeftPanel: true,\n      assetType: options.assetType,\n      title: options.title,\n      onSelect: handleAssetSelected,\n      onClose: hide\n    })\n  }\n\n  return { show, browse }\n}\n","import { fromZodError } from 'zod-validation-error'\n\nimport { t } from '@/i18n'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type {\n  IBaseWidget,\n  IWidgetAssetOptions\n} from '@/lib/litegraph/src/types/widgets'\nimport { useAssetBrowserDialog } from '@/platform/assets/composables/useAssetBrowserDialog'\nimport {\n  assetFilenameSchema,\n  assetItemSchema\n} from '@/platform/assets/schemas/assetSchema'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { getAssetFilename } from '@/platform/assets/utils/assetMetadataUtils'\n\ntype WidgetWithNode = IBaseWidget & { node: LGraphNode }\n\ninterface CreateAssetWidgetParams {\n  /** The node to add the widget to */\n  node: LGraphNode\n  /** The widget name */\n  widgetName: string\n  /** The node type to show in asset browser (may differ from node.comfyClass for PrimitiveNode) */\n  nodeTypeForBrowser: string\n  /** Input name for asset browser filtering (defaults to widgetName if not provided) */\n  inputNameForBrowser?: string\n  /** Default value for the widget */\n  defaultValue?: string\n}\n\ninterface CreateAssetWidgetOptionsParams {\n  widgetName: string\n  nodeTypeForBrowser: string\n  inputNameForBrowser?: string\n}\n\nfunction hasOwnerNode(widget: IBaseWidget): widget is WidgetWithNode {\n  return (\n    'node' in widget && typeof widget.node === 'object' && widget.node !== null\n  )\n}\n\nfunction createAssetWidgetOptions({\n  widgetName,\n  nodeTypeForBrowser,\n  inputNameForBrowser\n}: CreateAssetWidgetOptionsParams): IWidgetAssetOptions {\n  const inputName = inputNameForBrowser ?? widgetName\n  const assetBrowserDialog = useAssetBrowserDialog()\n\n  async function openModal(widget: IBaseWidget) {\n    const toast = useToast()\n\n    await assetBrowserDialog.show({\n      nodeType: nodeTypeForBrowser,\n      inputName,\n      currentValue: String(widget.value ?? ''),\n      onAssetSelected: (asset) => {\n        const validatedAsset = assetItemSchema.safeParse(asset)\n\n        if (!validatedAsset.success) {\n          console.error(\n            'Invalid asset item:',\n            fromZodError(validatedAsset.error).message\n          )\n          toast.error(t('assetBrowser.invalidAsset'), {\n            description: t('assetBrowser.invalidAssetDetail')\n          })\n          return\n        }\n\n        const filename = getAssetFilename(validatedAsset.data)\n        const validatedFilename = assetFilenameSchema.safeParse(filename)\n\n        if (!validatedFilename.success) {\n          console.error(\n            'Invalid asset filename:',\n            validatedFilename.error.issues,\n            'for asset:',\n            validatedAsset.data.id\n          )\n          toast.error(t('assetBrowser.invalidFilename'), {\n            description: t('assetBrowser.invalidFilenameDetail')\n          })\n          return\n        }\n\n        const oldValue = widget.value\n        widget.value = validatedFilename.data\n        widget.callback?.(widget.value)\n        if (hasOwnerNode(widget)) {\n          widget.node.onWidgetChanged?.(\n            widget.name,\n            validatedFilename.data,\n            oldValue,\n            widget\n          )\n        }\n        if (oldValue !== validatedFilename.data) {\n          useWorkflowStore().activeWorkflow?.changeTracker.captureCanvasState()\n        }\n      }\n    })\n  }\n\n  return {\n    openModal,\n    nodeType: nodeTypeForBrowser\n  }\n}\n\nexport function createAssetWidget(\n  params: CreateAssetWidgetParams\n): IBaseWidget {\n  const {\n    node,\n    widgetName,\n    nodeTypeForBrowser,\n    inputNameForBrowser,\n    defaultValue\n  } = params\n\n  const displayLabel = defaultValue ?? t('widgets.selectModel')\n  const options = createAssetWidgetOptions({\n    widgetName,\n    nodeTypeForBrowser,\n    inputNameForBrowser\n  })\n  return node.addWidget('asset', widgetName, displayLabel, () => {}, options)\n}\n","import type { ComfyWorkflowJSON } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\n\n/**\n * Metadata for output assets from queue store\n * Extends Record<string, unknown> for compatibility with AssetItem schema\n */\nexport interface OutputAssetMetadata extends Record<string, unknown> {\n  jobId: string\n  nodeId?: string | number\n  subfolder: string\n  executionTimeInSeconds?: number\n  format?: string\n  workflow?: ComfyWorkflowJSON\n  outputCount?: number\n  allOutputs?: AugmentedResultItem[]\n  assetId?: string\n}\n\n/**\n * Type guard to check if metadata is OutputAssetMetadata\n */\nfunction isOutputAssetMetadata(\n  metadata: Record<string, unknown> | undefined\n): metadata is OutputAssetMetadata {\n  return (\n    !!metadata &&\n    typeof metadata.jobId === 'string' &&\n    typeof metadata.subfolder === 'string'\n  )\n}\n\n/**\n * Safely extract output asset metadata\n */\nexport function getOutputAssetMetadata(\n  userMetadata: Record<string, unknown> | undefined\n): OutputAssetMetadata | null {\n  if (isOutputAssetMetadata(userMetadata)) {\n    return userMetadata\n  }\n  return null\n}\n","import type { ResultItem } from '@/platform/remote/comfyui/execution/types'\nimport type { SerializedNodeId } from '@/types/nodeId'\nimport { getMediaTypeFromFilename } from '@/utils/formatUtil'\n\nexport interface AugmentedResultItem extends ResultItem {\n  filename: string\n  mediaType: string\n  mediaTypeIsResolved?: boolean\n  nodeId: SerializedNodeId\n  subfolder: string\n  assetId?: string\n  display_name?: string\n  content?: string\n  format?: string\n  frame_rate?: number\n  url?: string\n  previewUrl?: string\n}\n\nconst isVideoBySuffix = (item: AugmentedResultItem): boolean =>\n  getMediaTypeFromFilename(item.filename) === 'video'\nconst isImageBySuffix = (item: AugmentedResultItem): boolean =>\n  getMediaTypeFromFilename(item.filename) === 'image'\nconst isAudioBySuffix = (item: AugmentedResultItem): boolean =>\n  getMediaTypeFromFilename(item.filename) === 'audio'\n\nconst hasResolvedMediaType = (item: AugmentedResultItem): boolean =>\n  item.mediaTypeIsResolved === true\n\nexport function isVhsFormat(item: AugmentedResultItem): boolean {\n  return !!item.format && !!item.frame_rate\n}\n\nexport function isVideoResult(item: AugmentedResultItem): boolean {\n  if (hasResolvedMediaType(item)) return item.mediaType === 'video'\n  const isVideoByType =\n    item.mediaType === 'video' || !!item.format?.startsWith('video/')\n  return (\n    isVideoBySuffix(item) ||\n    (isVideoByType && !isImageBySuffix(item) && !isAudioBySuffix(item))\n  )\n}\n\nexport function isImageResult(item: AugmentedResultItem): boolean {\n  if (hasResolvedMediaType(item)) return item.mediaType === 'images'\n  return (\n    isImageBySuffix(item) ||\n    (item.mediaType === 'images' &&\n      !isVideoBySuffix(item) &&\n      !isAudioBySuffix(item))\n  )\n}\n\nexport function isAudioResult(item: AugmentedResultItem): boolean {\n  if (hasResolvedMediaType(item)) return item.mediaType === 'audio'\n  const isAudioByType =\n    item.mediaType === 'audio' || !!item.format?.startsWith('audio/')\n  return (\n    isAudioBySuffix(item) ||\n    (isAudioByType && !isImageBySuffix(item) && !isVideoBySuffix(item))\n  )\n}\n\nexport function is3DResult(item: AugmentedResultItem): boolean {\n  return getMediaTypeFromFilename(item.filename) === '3D'\n}\n\nexport function isTextResult(item: AugmentedResultItem): boolean {\n  return (\n    item.mediaType === 'text' ||\n    getMediaTypeFromFilename(item.filename) === 'text'\n  )\n}\n\nexport function resultItemHtmlVideoType(\n  item: AugmentedResultItem\n): string | undefined {\n  if (item.filename.endsWith('.webm')) return 'video/webm'\n  if (item.filename.endsWith('.mp4')) return 'video/mp4'\n  if (item.filename.endsWith('.mov')) return 'video/quicktime'\n  if (isVhsFormat(item)) {\n    if (item.format?.endsWith('webm')) return 'video/webm'\n    if (item.format?.endsWith('mp4')) return 'video/mp4'\n  }\n  return undefined\n}\n\nexport function resultItemHtmlAudioType(\n  item: AugmentedResultItem\n): string | undefined {\n  if (item.filename.endsWith('.mp3')) return 'audio/mpeg'\n  if (item.filename.endsWith('.wav')) return 'audio/wav'\n  if (item.filename.endsWith('.ogg')) return 'audio/ogg'\n  if (item.filename.endsWith('.flac')) return 'audio/flac'\n  return undefined\n}\n\nexport function resultItemSupportsPreview(item: AugmentedResultItem): boolean {\n  return (\n    isImageResult(item) ||\n    isVideoResult(item) ||\n    isAudioResult(item) ||\n    is3DResult(item) ||\n    isTextResult(item)\n  )\n}\n\nexport function filterPreviewableResults(\n  items: readonly AugmentedResultItem[]\n): AugmentedResultItem[] {\n  return items.filter(resultItemSupportsPreview)\n}\n","import { appendCloudResParam } from '@/platform/distribution/cloudPreviewUtil'\nimport { api } from '@/scripts/api'\nimport { hdrPreviewAssetUrl, isHdrImageFilename } from '@/utils/hdrFormatUtil'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\nimport { isImageResult } from '@/utils/resultItem'\n\nfunction resultItemUrlParams(item: AugmentedResultItem): URLSearchParams {\n  const params = new URLSearchParams()\n  params.set('filename', item.filename)\n  params.set('type', item.type ?? '')\n  params.set('subfolder', item.subfolder)\n  if (item.format) params.set('format', item.format)\n  if (item.frame_rate) params.set('frame_rate', item.frame_rate.toString())\n  return params\n}\n\nexport function resultItemUrl(item: AugmentedResultItem): string {\n  if (item.url !== undefined) return item.url\n  if (!item.filename) return ''\n  return api.apiURL('/view?' + resultItemUrlParams(item))\n}\n\nexport function resultItemPreviewUrl(item: AugmentedResultItem): string {\n  if (item.previewUrl !== undefined) return item.previewUrl\n  if (item.preview_id && isHdrImageFilename(item.filename))\n    return hdrPreviewAssetUrl(item.preview_id)\n  if (!isImageResult(item)) return resultItemUrl(item)\n  const params = resultItemUrlParams(item)\n  appendCloudResParam(params, item.filename)\n  return api.apiURL('/view?' + params)\n}\n\nexport function resultItemVhsAdvancedPreviewUrl(\n  item: AugmentedResultItem\n): string {\n  return api.apiURL('/viewvideo?' + resultItemUrlParams(item))\n}\n\nexport function resultItemUrlWithTimestamp(item: AugmentedResultItem): string {\n  return `${resultItemUrl(item)}&t=${+new Date()}`\n}\n\nexport function findResultIndexByUrl(\n  items: readonly AugmentedResultItem[],\n  url?: string\n): number {\n  if (!url) return 0\n  const idx = items.findIndex((item) => resultItemUrl(item) === url)\n  return idx >= 0 ? idx : 0\n}\n","import type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport type { OutputAssetMetadata } from '@/platform/assets/schemas/assetMetadataSchema'\nimport { getOutputAssetMetadata } from '@/platform/assets/schemas/assetMetadataSchema'\nimport type { AssetContext } from '@/platform/assets/schemas/mediaAssetSchema'\nimport { appendCloudResParam } from '@/platform/distribution/cloudPreviewUtil'\nimport { api } from '@/scripts/api'\nimport type { TaskItemImpl } from '@/stores/queueStore'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\nimport { resultItemPreviewUrl, resultItemUrl } from '@/utils/resultItemUrl'\nimport {\n  getMediaTypeFromFilename,\n  isPreviewableMediaType\n} from '@/utils/formatUtil'\n\n/**\n * Extract asset type from tags array\n * @param tags The tags array from AssetItem\n * @returns The asset type ('input' or 'output')\n */\nexport function getAssetType(tags?: string[]): AssetContext['type'] {\n  const tag = tags?.[0]\n  if (tag === 'output') return 'output'\n  return 'input'\n}\n\n/**\n * Maps a TaskItemImpl output to an AssetItem format\n * @param taskItem The task item containing execution data\n * @param output The output from the task\n * @param useDisplayName Whether to truncate the filename for display\n * @returns AssetItem formatted object\n */\nexport function mapTaskOutputToAssetItem(\n  taskItem: TaskItemImpl,\n  output: AugmentedResultItem\n): AssetItem {\n  const metadata: OutputAssetMetadata = {\n    jobId: taskItem.jobId,\n    nodeId: output.nodeId,\n    subfolder: output.subfolder,\n    executionTimeInSeconds: taskItem.executionTimeInSeconds,\n    format: output.format,\n    create_time: taskItem.createTime\n  }\n\n  const executionTime = taskItem.executionStartTimestamp\n    ? new Date(taskItem.executionStartTimestamp).toISOString()\n    : new Date().toISOString()\n\n  return {\n    id: taskItem.jobId,\n    name: output.filename,\n    display_name: output.display_name,\n    size: 0,\n    created_at: executionTime,\n    updated_at: executionTime,\n    tags: ['output'],\n    thumbnail_url: resultItemPreviewUrl(output),\n    preview_url: resultItemUrl(output),\n    user_metadata: metadata\n  }\n}\n\nconst byCreatedAtAsc = (a: AssetItem, b: AssetItem): number =>\n  new Date(a.created_at).getTime() - new Date(b.created_at).getTime() ||\n  a.name.localeCompare(b.name)\n\nconst byCreatedAtDesc = (a: AssetItem, b: AssetItem): number =>\n  new Date(b.created_at).getTime() - new Date(a.created_at).getTime()\nconst byIsTemp = (a: AssetItem, b: AssetItem): number =>\n  Number(b.tags.includes('temp')) - Number(a.tags.includes('temp'))\n\nfunction flatAssetToResultItem(asset: AssetItem): AugmentedResultItem {\n  const metadata = getOutputAssetMetadata(asset.user_metadata)\n  const url = asset.preview_url ?? ''\n  return {\n    assetId: asset.id,\n    display_name: asset.display_name ?? undefined,\n    filename: asset.name,\n    format: metadata?.format,\n    mediaType: getMediaTypeFromFilename(asset.name),\n    nodeId: metadata?.nodeId ?? '',\n    subfolder: metadata?.subfolder ?? '',\n    type: asset.tags.includes('temp') ? 'temp' : 'output',\n    url,\n    previewUrl: asset.thumbnail_url ?? url\n  }\n}\n\n/**\n * Group flat per-file output assets into one asset per job, mirroring the\n * grouped shape produced from the history API: the group id is the job id and\n * user_metadata carries outputCount/allOutputs. Assets without output job\n * metadata pass through ungrouped.\n */\nexport function unflattenOutputAssets(\n  flatAssets: readonly AssetItem[]\n): AssetItem[] {\n  const assetsByJob = new Map<string, AssetItem[]>()\n  const ungrouped: AssetItem[] = []\n\n  for (const asset of flatAssets) {\n    const { job_id } = asset\n    if (!job_id) {\n      ungrouped.push(asset)\n      continue\n    }\n    const group = assetsByJob.get(job_id)\n    if (group) group.push(asset)\n    else assetsByJob.set(job_id, [asset])\n  }\n\n  const grouped = [...assetsByJob.entries()].map(([job_id, assets]) => {\n    const ordered = [...assets].sort(byCreatedAtAsc)\n    const representative =\n      [...ordered]\n        .sort(byIsTemp)\n        .findLast((asset) =>\n          isPreviewableMediaType(getMediaTypeFromFilename(asset.name))\n        ) ?? ordered.at(-1)!\n    return {\n      ...representative,\n      id: job_id,\n      created_at: ordered.at(-1)!.created_at,\n      user_metadata: {\n        jobId: job_id,\n        subfolder: '',\n        ...representative.user_metadata,\n        assetId: representative.id,\n        outputCount: ordered.length,\n        allOutputs: ordered.map(flatAssetToResultItem)\n      }\n    }\n  })\n\n  return [...grouped, ...ungrouped].sort(byCreatedAtDesc)\n}\n\n/**\n * Strips ComfyUI's trailing directory-type annotation (e.g. ` [input]`,\n * ` [output]`, `[temp]`) from a filename returned by the OSS internal\n * `/internal/files/{type}` endpoint. The annotation is part of the wire\n * format LoadImage-style widgets expect, but for the assets sidebar we\n * want the canonical on-disk filename so type detection / titles work.\n */\nfunction stripDirectoryAnnotation(filename: string): string {\n  return filename.replace(/\\s*\\[(?:input|output|temp)\\]\\s*$/i, '')\n}\n\n/**\n * Maps input directory file to AssetItem format\n * @param filename The filename\n * @param index File index for unique ID\n * @param directory The directory type\n * @returns AssetItem formatted object\n */\nexport function mapInputFileToAssetItem(\n  filename: string,\n  index: number,\n  directory: 'input' | 'output' = 'input'\n): AssetItem {\n  const cleanName = stripDirectoryAnnotation(filename)\n  const params = new URLSearchParams({ filename: cleanName, type: directory })\n  const preview_url = api.apiURL(`/view?${params}`)\n  appendCloudResParam(params, cleanName)\n\n  const created_at = new Date().toISOString()\n  return {\n    id: `${directory}-${index}-${cleanName}`,\n    name: cleanName,\n    size: 0,\n    created_at,\n    updated_at: created_at,\n    tags: [directory],\n    thumbnail_url: api.apiURL(`/view?${params}`),\n    preview_url\n  }\n}\n","import { computed, onScopeDispose, ref, toValue } from 'vue'\nimport type { MaybeRef } from 'vue'\n\nexport interface PagedList<T> {\n  hasMore: Readonly<MaybeRef<boolean>>\n  invalidate: (items?: string[]) => Promise<void>\n  isLoading: Readonly<MaybeRef<boolean>>\n  items: Readonly<MaybeRef<T[]>>\n  /** Returns whether pagination advanced. Page-walking callers must stop on false. */\n  loadMore: () => Promise<boolean>\n  loadNew: () => Promise<void>\n}\n\nexport class WrappedList<T, U> implements PagedList<U> {\n  readonly items: MaybeRef<U[]>\n  constructor(\n    private readonly childList: PagedList<T>,\n    private readonly transform: (items: readonly T[]) => U[]\n  ) {\n    this.items = computed(() => this.transform(toValue(this.childList.items)))\n  }\n  get hasMore() {\n    return this.childList.hasMore\n  }\n  async invalidate(stale?: string[]) {\n    await this.childList.invalidate(stale)\n  }\n  get isLoading() {\n    return this.childList.isLoading\n  }\n  loadMore() {\n    return this.childList.loadMore()\n  }\n  async loadNew() {\n    await this.childList.loadNew()\n  }\n}\n\ninterface CacheEntry<T> {\n  list: PagedList<T>\n  refCount: number\n}\ntype Cache<T> = Map<string, CacheEntry<T>>\n\nexport interface SharedPagedListState<TParams, TItem> {\n  readonly cache: Cache<TItem>\n  readonly factory: (params: TParams) => PagedList<TItem>\n  readonly paramKeyFn: (params: TParams) => string\n  readonly itemKeyFn: (item: TItem) => unknown\n}\n\nexport function getPagedList<TParams, TItem>(\n  params: TParams,\n  state: SharedPagedListState<TParams, TItem>\n): PagedList<TItem> {\n  const key = state.paramKeyFn(params)\n  const entry = state.cache.get(key) ?? {\n    list: state.factory(params),\n    refCount: 0\n  }\n  state.cache.set(key, entry)\n  entry.refCount++\n\n  onScopeDispose(() => --entry.refCount || state.cache.delete(key))\n  return new SharedPagedList(entry.list, state.cache, state.itemKeyFn)\n}\n\nclass SharedPagedList<T> implements PagedList<T> {\n  constructor(\n    private readonly childList: PagedList<T>,\n    private readonly cache: Cache<T>,\n    private readonly itemKeyFn: (item: T) => unknown\n  ) {}\n  overlapping(): PagedList<T>[] {\n    const snapshot = toValue(this.childList.items)\n    if (snapshot.length === 0) return [this.childList]\n\n    const staleKeys = new Set(snapshot.map(this.itemKeyFn))\n    return [...this.cache.values()]\n      .filter((e) =>\n        toValue(e.list.items).some((item) =>\n          staleKeys.has(this.itemKeyFn(item))\n        )\n      )\n      .map((e) => e.list)\n  }\n\n  get hasMore() {\n    return this.childList.hasMore\n  }\n  async invalidate(stale?: string[]) {\n    const toInvalidate = stale\n      ? [...this.cache.values()].map((l) => l.list)\n      : this.overlapping()\n    await Promise.all(toInvalidate.map((l) => l.invalidate(stale)))\n  }\n  get isLoading() {\n    return this.childList.isLoading\n  }\n  get items() {\n    return this.childList.items\n  }\n  loadMore() {\n    return this.childList.loadMore()\n  }\n  async loadNew() {\n    await Promise.all(this.overlapping().map((l) => l.loadNew()))\n  }\n}\n\ntype Runner = (signal: AbortSignal) => Promise<void>\nconst PREEMPT_KIND: unique symbol = Symbol()\ntype Kind = string | typeof PREEMPT_KIND\ninterface Task {\n  kind: Kind\n  promise: Promise<void>\n  resolve: () => void\n  start: () => void\n}\n\nexport function usePreemptableQueue() {\n  const queue: Task[] = []\n  const running = ref(false)\n  let controller = new AbortController()\n\n  function makeTask(kind: Kind, runner: Runner): Task {\n    let resolve!: () => void\n    const promise = new Promise<void>((r) => (resolve = r))\n\n    const start = () =>\n      runner(controller.signal)\n        .catch(() => undefined)\n        .then(resolve)\n    return { kind, promise, resolve, start }\n  }\n\n  function enqueue(kind: Kind, runner: Runner): Promise<void> {\n    if (queue[0]?.kind === PREEMPT_KIND) return queue[0].promise\n\n    const existing = queue.find((task) => task.kind === kind)\n    if (existing) return existing.promise\n\n    const task = makeTask(kind, runner)\n    queue.push(task)\n    if (queue.length === 1) void startQueue()\n    return task.promise\n  }\n\n  async function preempt(runner: () => Promise<void>): Promise<void> {\n    if (queue[0]?.kind === PREEMPT_KIND) return queue[0].promise\n\n    const task = makeTask(PREEMPT_KIND, runner)\n    controller.abort()\n    controller = new AbortController()\n    const active = queue.at(0)\n    const existing = queue.splice(0, queue.length, task)\n    if (active) {\n      await active.promise\n      queue.push(task)\n      for (const task of existing) task.resolve()\n    } else {\n      void startQueue()\n    }\n    await task.promise\n  }\n\n  async function startQueue() {\n    running.value = true\n    while (queue.length) {\n      await queue[0].start()\n      queue.shift()\n    }\n    running.value = false\n  }\n\n  return { enqueue, preempt, running }\n}\n","type ParamValue = string[] | string | number | boolean\ntype Params = Record<string, ParamValue | undefined>\n\nfunction sortedParams(params: Params = {}): Record<string, ParamValue> {\n  const keys = Object.keys(params).sort()\n  const obj: Record<string, ParamValue> = {}\n  for (const k of keys) {\n    const v = params[k]\n    if (v === undefined) continue\n    obj[k] = Array.isArray(v) ? [...v].sort((a, b) => a.localeCompare(b)) : v\n  }\n  return obj\n}\n\nexport function encodeParams(params: Params = {}) {\n  const sorted = sortedParams(params)\n  const parts = Object.entries(sorted).map(([key, value]) => {\n    const encoded = Array.isArray(value)\n      ? value.map(String).map(encodeURIComponent).join(',')\n      : encodeURIComponent(String(value))\n    return `${encodeURIComponent(key)}=${encoded}`\n  })\n  return parts.join('&')\n}\n","import { refAutoReset, until } from '@vueuse/core'\nimport { computed, ref } from 'vue'\nimport { fromZodError } from 'zod-validation-error'\nimport type { ListAssetsData } from '@comfyorg/ingest-types'\n\nimport { assetResponseSchema } from '@/platform/assets/schemas/assetSchema'\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport { api } from '@/scripts/api'\nimport { getPagedList, usePreemptableQueue } from '@/utils/pagedList'\nimport type { SharedPagedListState, PagedList } from '@/utils/pagedList'\nimport { encodeParams } from '@/utils/requestUtil'\n\ninterface QueryOptions {\n  onError?: (reason: string, error?: unknown) => void\n}\n\nconst BASE_PARAMS = {\n  include_public: false,\n  limit: 100,\n  sort: 'created_at',\n  tags_none: ['missing']\n} satisfies ListAssetsData['query']\n\nfunction assetsQueryInternal(\n  params: ListAssetsData['query'] = {},\n  options: QueryOptions = {}\n): PagedList<AssetItem> {\n  const onError = options.onError ?? console.error\n\n  let nextCursor: string | undefined\n  const seenCursors = new Set<string | undefined>()\n  let loadGeneration = 0\n  const morePages = ref(true)\n  const backingOff = refAutoReset(false, 2000)\n  const hasMore = computed(() => morePages.value && !backingOff.value)\n  const items = ref<AssetItem[]>([])\n\n  const { enqueue, preempt, running: isLoading } = usePreemptableQueue()\n  let loadMorePromise: Promise<boolean> | undefined\n  let invalidationQueue = Promise.resolve()\n  async function doLoadMore(signal?: AbortSignal) {\n    if (!hasMore.value) return\n    const requestedCursor = nextCursor ?? params.after\n    if (seenCursors.has(requestedCursor)) return\n\n    const assetResponse = await doQuery(\n      {\n        after: requestedCursor\n      },\n      signal\n    )\n    if (!assetResponse) return\n\n    const knownIds = new Set(items.value.map(({ id }) => id))\n    const newItems = assetResponse.assets.filter(({ id }) => {\n      if (knownIds.has(id)) return false\n      knownIds.add(id)\n      return true\n    })\n    seenCursors.add(requestedCursor)\n    nextCursor = assetResponse.next_cursor\n    morePages.value =\n      assetResponse.has_more &&\n      nextCursor !== undefined &&\n      !seenCursors.has(nextCursor)\n    items.value.push(...newItems)\n    loadGeneration++\n  }\n\n  function loadMore() {\n    if (!loadMorePromise) {\n      const startingGeneration = loadGeneration\n      const operation = enqueue('loadMore', doLoadMore).then(\n        () => loadGeneration > startingGeneration\n      )\n      loadMorePromise = operation.finally(() => {\n        loadMorePromise = undefined\n      })\n    }\n    return loadMorePromise\n  }\n\n  function loadNew() {\n    return enqueue('loadNew', async function (signal: AbortSignal) {\n      const knownIds = new Set(items.value.map((item) => item.id))\n      const seenIds = new Set(knownIds)\n      const newItems: AssetItem[] = []\n      let headCursor: string | undefined\n      const seenHeadCursors = new Set<string | undefined>()\n      for (;;) {\n        if (seenHeadCursors.has(headCursor)) break\n        seenHeadCursors.add(headCursor)\n\n        const query = headCursor\n          ? { after: headCursor }\n          : { after: headCursor, limit: 10 }\n        const assetResponse = await doQuery(query, signal)\n        if (!assetResponse) return\n\n        const { assets, has_more, next_cursor } = assetResponse\n        const reachedKnownId = assets.some((asset) => {\n          if (knownIds.has(asset.id)) return true\n          if (!seenIds.has(asset.id)) {\n            seenIds.add(asset.id)\n            newItems.push(asset)\n          }\n          return false\n        })\n        if (reachedKnownId || !has_more || next_cursor === undefined) break\n        headCursor = next_cursor\n      }\n      items.value.splice(0, 0, ...newItems)\n    })\n  }\n\n  async function applyInvalidation(stale?: string[]) {\n    if (stale) {\n      await preempt(() => Promise.resolve())\n      const ids = new Set(stale)\n      items.value = items.value.filter((item) => !ids.has(item.id))\n      return\n    }\n    await preempt(async () => {\n      morePages.value = true\n      nextCursor = undefined\n      seenCursors.clear()\n      items.value = []\n      await until(backingOff).toBe(false)\n      await doLoadMore()\n    })\n  }\n\n  function invalidate(stale?: string[]) {\n    const operation = invalidationQueue.then(() => applyInvalidation(stale))\n    invalidationQueue = operation\n    return operation\n  }\n\n  async function doQuery(\n    overrideParams: ListAssetsData['query'],\n    signal?: AbortSignal\n  ) {\n    const requestOptions = { signal }\n    const query = encodeParams({ ...BASE_PARAMS, ...params, ...overrideParams })\n    const resp = await api\n      .fetchApi(`/assets?${query}`, requestOptions)\n      .catch((e) => onError('asset fetch failed', e))\n\n    if (!resp) {\n      if (!signal?.aborted) backingOff.value = true\n      return\n    }\n    if (!resp.ok) {\n      onError('asset request failed', resp)\n      if (resp.status === 429 || resp.status >= 500) backingOff.value = true\n      else morePages.value = false\n      return\n    }\n\n    const jsonresp = await resp\n      .json()\n      .catch((e) => onError('failed to decode asset json response', e))\n    if (!jsonresp) {\n      morePages.value = false\n      return\n    }\n\n    const parseResult = assetResponseSchema.safeParse(jsonresp)\n    if (!parseResult.success) {\n      onError('Failed to parse asset response', fromZodError(parseResult.error))\n      morePages.value = false\n      return\n    }\n    return parseResult.data\n  }\n\n  void loadMore()\n  return {\n    hasMore,\n    invalidate,\n    isLoading,\n    items,\n    loadMore,\n    loadNew\n  }\n}\n\nconst sharedState: SharedPagedListState<ListAssetsData['query'], AssetItem> = {\n  cache: new Map(),\n  factory: assetsQueryInternal,\n  paramKeyFn: encodeParams,\n  itemKeyFn: (item) => item.id\n}\n\nexport function useAssetsQuery(\n  params: ListAssetsData['query']\n): PagedList<AssetItem> {\n  return getPagedList(params, sharedState)\n}\n\nexport async function invalidateAll() {\n  await Promise.all(\n    [...sharedState.cache.values()].map((e) => e.list.invalidate())\n  )\n}\n","import type {\n  NodeExecutionOutput,\n  ResultItem\n} from '@/platform/remote/comfyui/execution/types'\nimport { resultItemType } from '@/schemas/resultItemTypeSchema'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\n\nconst METADATA_KEYS = new Set(['animated', 'text'])\n\nfunction isUnknownArray(value: unknown): value is unknown[] {\n  return Array.isArray(value)\n}\n\n/**\n * Validates that an unknown value is a well-formed ResultItem.\n *\n * Requires `filename` (string) since it is needed for a valid URL.\n * `subfolder` is optional here — URL building falls back to ''.\n */\nfunction isResultItem(\n  item: unknown\n): item is ResultItem & { filename: string } {\n  if (!item || typeof item !== 'object' || Array.isArray(item)) return false\n\n  if (!('filename' in item) || typeof item.filename !== 'string') return false\n\n  if (\n    'type' in item &&\n    item.type !== undefined &&\n    !resultItemType.safeParse(item.type).success\n  ) {\n    return false\n  }\n\n  return true\n}\n\nexport function parseNodeOutput(\n  nodeId: string | number,\n  nodeOutput: NodeExecutionOutput | null | undefined\n): AugmentedResultItem[] {\n  if (!nodeOutput) return []\n\n  return Object.entries(nodeOutput).flatMap(([mediaType, items]) => {\n    if (METADATA_KEYS.has(mediaType) || !isUnknownArray(items)) return []\n    return items\n      .filter(isResultItem)\n      .map((item) => ({ subfolder: '', ...item, mediaType, nodeId }))\n  })\n}\n\nexport function parseTaskOutput(\n  taskOutput: Record<string, NodeExecutionOutput | null | undefined>\n): AugmentedResultItem[] {\n  return Object.entries(taskOutput).flatMap(([nodeId, nodeOutput]) =>\n    parseNodeOutput(nodeId, nodeOutput)\n  )\n}\n","import type { LGraphCanvas } from './LGraphCanvas'\nimport type { IContextMenuValue } from './types/contextMenu'\n\n/**\n * Simple compatibility layer for legacy getCanvasMenuOptions and getNodeMenuOptions monkey patches.\n */\ntype ContextMenuValueProvider = (\n  ...args: unknown[]\n) => (IContextMenuValue | null)[]\n\nclass LegacyMenuCompat {\n  private originalMethods = new Map<string, ContextMenuValueProvider>()\n  private hasWarned = new Set<string>()\n  private currentExtension: string | null = null\n  private isExtracting = false\n  private readonly wrapperMethods = new Map<string, ContextMenuValueProvider>()\n  private readonly preWrapperMethods = new Map<\n    string,\n    ContextMenuValueProvider\n  >()\n  private readonly wrapperInstalled = new Map<string, boolean>()\n\n  /**\n   * Set the name of the extension that is currently being set up.\n   * This allows us to track which extension is monkey-patching.\n   * @param extensionName The name of the extension\n   */\n  setCurrentExtension(extensionName: string | null) {\n    this.currentExtension = extensionName\n  }\n\n  /**\n   * Register a wrapper method that should NOT be treated as a legacy monkey-patch.\n   * @param methodName The method name\n   * @param wrapperFn The wrapper function\n   * @param preWrapperFn The method that existed before the wrapper\n   * @param prototype The prototype to verify wrapper installation\n   */\n  registerWrapper<K extends keyof LGraphCanvas>(\n    methodName: K,\n    wrapperFn: LGraphCanvas[K],\n    preWrapperFn: LGraphCanvas[K],\n    prototype?: LGraphCanvas\n  ) {\n    this.wrapperMethods.set(\n      methodName,\n      wrapperFn as unknown as ContextMenuValueProvider\n    )\n    this.preWrapperMethods.set(\n      methodName,\n      preWrapperFn as unknown as ContextMenuValueProvider\n    )\n    const isInstalled = prototype && prototype[methodName] === wrapperFn\n    this.wrapperInstalled.set(methodName, !!isInstalled)\n  }\n\n  /**\n   * Install compatibility layer to detect monkey-patching\n   * @param prototype The prototype to install on\n   * @param methodName The method name to track\n   */\n  install(prototype: LGraphCanvas, methodName: keyof LGraphCanvas) {\n    const originalMethod = prototype[methodName]\n    this.originalMethods.set(\n      methodName,\n      originalMethod as unknown as ContextMenuValueProvider\n    )\n\n    let currentImpl = originalMethod\n\n    Object.defineProperty(prototype, methodName, {\n      get() {\n        return currentImpl\n      },\n      set: (newImpl: LGraphCanvas[keyof LGraphCanvas]) => {\n        if (!newImpl) return\n        const fnKey = `${methodName as string}:${newImpl.toString().slice(0, 100)}`\n        if (!this.hasWarned.has(fnKey) && this.currentExtension) {\n          this.hasWarned.add(fnKey)\n\n          console.warn(\n            `%c[DEPRECATED]%c Monkey-patching ${methodName as string} is deprecated. (Extension: \"${this.currentExtension}\")\\n` +\n              `Please use the new context menu API instead.\\n\\n` +\n              `See: https://docs.comfy.org/custom-nodes/js/context-menu-migration`,\n            'color: orange; font-weight: bold',\n            'color: inherit'\n          )\n        }\n        currentImpl = newImpl\n      }\n    })\n  }\n\n  /**\n   * Extract items that were added by legacy monkey patches.\n   *\n   * Uses set-based diffing by reference to reliably detect additions regardless\n   * of item reordering or replacement. Items present in patchedItems but not in\n   * originalItems (by reference equality) are considered additions.\n   *\n   * Note: If a monkey patch removes items (patchedItems has fewer unique items\n   * than originalItems), a warning is logged but we still return any new items.\n   *\n   * @param methodName The method name that was monkey-patched\n   * @param context The context to call methods with\n   * @param args Arguments to pass to the methods\n   * @returns Array of menu items added by monkey patches\n   */\n  extractLegacyItems(\n    methodName: keyof LGraphCanvas,\n    context: LGraphCanvas,\n    ...args: unknown[]\n  ): (IContextMenuValue | null)[] {\n    if (this.isExtracting) return []\n\n    const originalMethod = this.originalMethods.get(methodName)\n    if (!originalMethod) return []\n\n    try {\n      this.isExtracting = true\n\n      const originalItems = originalMethod.apply(context, args) as\n        | (IContextMenuValue | null)[]\n        | undefined\n      if (!originalItems) return []\n\n      const currentMethod = context.constructor.prototype[methodName]\n      if (!currentMethod || currentMethod === originalMethod) return []\n\n      const registeredWrapper = this.wrapperMethods.get(methodName)\n      if (registeredWrapper && currentMethod === registeredWrapper) return []\n\n      const preWrapperMethod = this.preWrapperMethods.get(methodName)\n      const wrapperWasInstalled = this.wrapperInstalled.get(methodName)\n\n      const shouldSkipWrapper =\n        preWrapperMethod &&\n        wrapperWasInstalled &&\n        currentMethod !== preWrapperMethod\n\n      const methodToCall = shouldSkipWrapper ? preWrapperMethod : currentMethod\n\n      const patchedItems = methodToCall.apply(context, args) as\n        | (IContextMenuValue | null)[]\n        | undefined\n      if (!patchedItems) {\n        return []\n      }\n      // Use content-based diff to detect additions (not reference-based)\n      // Create composite keys from multiple properties to handle undefined content\n      const createItemKey = (item: IContextMenuValue): string => {\n        const parts = [\n          item.content ?? '',\n          item.title ?? '',\n          item.className ?? '',\n          item.property ?? '',\n          item.type ?? ''\n        ]\n        return parts.join('|')\n      }\n\n      const originalKeys = new Set(\n        originalItems\n          .filter(\n            (item): item is IContextMenuValue =>\n              item !== null && typeof item === 'object' && 'content' in item\n          )\n          .map(createItemKey)\n      )\n      const addedItems = patchedItems.filter((item) => {\n        if (item === null) return false\n        if (typeof item !== 'object' || !('content' in item)) return false\n        return !originalKeys.has(createItemKey(item))\n      })\n\n      // Warn if items were removed (patched has fewer original items than expected)\n      const patchedKeys = new Set(\n        patchedItems\n          .filter(\n            (item): item is IContextMenuValue =>\n              item !== null && typeof item === 'object' && 'content' in item\n          )\n          .map(createItemKey)\n      )\n      const removedCount = [...originalKeys].filter(\n        (key) => !patchedKeys.has(key)\n      ).length\n      if (removedCount > 0) {\n        console.warn(\n          `[Context Menu Compat] Monkey patch for ${methodName} removed ${removedCount} original menu item(s). ` +\n            `This may cause unexpected behavior.`\n        )\n      }\n\n      return addedItems\n    } catch (e) {\n      console.error('[Context Menu Compat] Failed to extract legacy items:', e)\n      return []\n    } finally {\n      this.isExtracting = false\n    }\n  }\n}\n\nexport const legacyMenuCompat = new LegacyMenuCompat()\n","import { isCloud } from '@/platform/distribution/types'\n\nexport const CORE_MENU_COMMANDS = [\n  [[], ['Comfy.NewBlankWorkflow']],\n  [[], []], // Separator after New\n  [['File'], ['Comfy.OpenWorkflow']],\n  [\n    ['File'],\n    [\n      'Comfy.SaveWorkflow',\n      'Comfy.SaveWorkflowAs',\n      'Comfy.ExportWorkflow',\n      'Comfy.ExportWorkflowAPI'\n    ]\n  ],\n  [['Edit'], ['Comfy.Undo', 'Comfy.Redo']],\n  [\n    ['Edit'],\n    [\n      'Comfy.Canvas.CopySelected',\n      'Comfy.Canvas.PasteFromClipboard',\n      'Comfy.Canvas.SelectAll'\n    ]\n  ],\n  [['Edit'], ['Comfy.ClearWorkflow']],\n  [['Edit'], ['Comfy.OpenClipspace']],\n  [\n    ['Edit'],\n    [\n      'Comfy.RefreshNodeDefinitions',\n      ...(isCloud\n        ? []\n        : [\n            'Comfy.Memory.UnloadModels',\n            'Comfy.Memory.UnloadModelsAndExecutionCache'\n          ])\n    ]\n  ],\n  [['View'], []],\n  [\n    ['Help'],\n    [\n      'Comfy.Help.OpenComfyUIIssues',\n      'Comfy.Help.OpenComfyUIDocs',\n      'Comfy.Help.OpenComfyOrgDiscord',\n      'Comfy.Help.OpenComfyUIForum'\n    ]\n  ],\n  [['Help'], ['Comfy.Help.AboutComfyUI', 'Comfy.ContactSupport']]\n]\n","import { whenever } from '@vueuse/core'\nimport { defineStore } from 'pinia'\nimport { ref } from 'vue'\n\nimport type { MenuItem, MenuItemAction } from '@/components/ui/menu/types'\nimport { CORE_MENU_COMMANDS } from '@/constants/coreMenuCommands'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport type { ComfyExtension } from '@/types/comfy'\n\nimport { useCommandStore } from './commandStore'\n\nexport interface CommandMenuItem extends MenuItemAction {\n  commandId: string\n}\n\nexport type AppMenuItem = MenuItem | CommandMenuItem\n\nexport const useMenuItemStore = defineStore('menuItem', () => {\n  const canvasStore = useCanvasStore()\n  const commandStore = useCommandStore()\n  const menuItems = ref<AppMenuItem[]>([])\n  const hasSeenLinear = ref(false)\n\n  whenever(\n    () => canvasStore.linearMode,\n    () => (hasSeenLinear.value = true),\n    { immediate: true, once: true }\n  )\n\n  const registerMenuGroup = (path: string[], items: AppMenuItem[]) => {\n    let currentLevel = menuItems.value\n\n    // Traverse the path, creating nodes if necessary\n    for (let i = 0; i < path.length; i++) {\n      const segment = path[i]\n      const foundIndex = currentLevel.findIndex(\n        (item) => item.label === segment\n      )\n      let found = currentLevel[foundIndex]\n\n      if (foundIndex === -1) {\n        // Create a new node if it doesn't exist\n        found = {\n          label: segment,\n          key: segment,\n          items: []\n        }\n        currentLevel.push(found)\n      }\n\n      if (!found.items) {\n        const { checked, command, radioGroup, separator, ...metadata } = found\n        found = { ...metadata, items: [] }\n        currentLevel[foundIndex] = found\n      }\n\n      // Move to the next level\n      currentLevel = found.items\n    }\n\n    if (currentLevel.length > 0) {\n      currentLevel.push({\n        separator: true\n      })\n    }\n    // Add the new items to the last level\n    currentLevel.push(...items)\n  }\n  function commandIdToMenuItem(commandId: string): CommandMenuItem {\n    const command = commandStore.getCommand(commandId)\n    return {\n      command: () => commandStore.execute(command.id),\n      label: command.menubarLabel,\n      icon: command.id === 'Comfy.NewBlankWorkflow' ? undefined : command.icon,\n      tooltip: command.tooltip,\n      commandId: command.id,\n      checked: command.active,\n      shortcut: () => command.keybinding?.combo.toString(),\n      pressAndHoldInterval:\n        command.id === 'Comfy.Canvas.ZoomIn' ||\n        command.id === 'Comfy.Canvas.ZoomOut'\n          ? 50\n          : undefined,\n      trailingIcon:\n        command.id === 'Comfy.NewBlankWorkflow' ? command.icon : undefined\n    }\n  }\n\n  const registerCommands = (path: string[], commandIds: string[]) => {\n    const items = commandIds.map(commandIdToMenuItem)\n    registerMenuGroup(path, items)\n  }\n\n  const loadExtensionMenuCommands = (extension: ComfyExtension) => {\n    if (!extension.menuCommands) {\n      return\n    }\n\n    const extensionCommandIds = new Set(\n      extension.commands?.map((command) => command.id) ?? []\n    )\n    extension.menuCommands.forEach((menuCommand) => {\n      const commands = menuCommand.commands.filter((command) =>\n        extensionCommandIds.has(command)\n      )\n      if (commands.length) {\n        registerCommands(menuCommand.path, commands)\n      }\n    })\n  }\n\n  const registerCoreMenuCommands = () => {\n    for (const [path, commands] of CORE_MENU_COMMANDS) {\n      registerCommands(path, commands)\n    }\n  }\n\n  return {\n    menuItems,\n    registerMenuGroup,\n    registerCommands,\n    loadExtensionMenuCommands,\n    registerCoreMenuCommands,\n    hasSeenLinear,\n    commandIdToMenuItem\n  }\n})\n","import { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { legacyMenuCompat } from '@/lib/litegraph/src/contextMenuCompat'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useExtensionStore } from '@/stores/extensionStore'\nimport { KeybindingImpl } from '@/platform/keybindings/keybinding'\nimport { useKeybindingStore } from '@/platform/keybindings/keybindingStore'\nimport { useMenuItemStore } from '@/stores/menuItemStore'\nimport { useWidgetStore } from '@/stores/widgetStore'\nimport { useBottomPanelStore } from '@/stores/workspace/bottomPanelStore'\nimport type { ComfyApp, ComfyExtension } from '@/types/comfy'\nimport type { AuthUserInfo } from '@/types/authTypes'\nimport { useApp } from '@/scripts/appInstance'\n\nfunction isPromiseLike(value: unknown): value is PromiseLike<unknown> {\n  return (\n    value instanceof Promise ||\n    (typeof value === 'object' &&\n      value !== null &&\n      typeof (value as { then?: unknown }).then === 'function')\n  )\n}\n\nexport const useExtensionService = () => {\n  const extensionStore = useExtensionStore()\n  const settingStore = useSettingStore()\n  const keybindingStore = useKeybindingStore()\n  const {\n    wrapWithErrorHandling,\n    wrapWithErrorHandlingAsync,\n    toastErrorHandler\n  } = useErrorHandling()\n\n  /**\n   * Register an extension with the app\n   * @param extension The extension to register\n   */\n  const registerExtension = (extension: ComfyExtension) => {\n    extensionStore.registerExtension(extension)\n\n    const addKeybinding = wrapWithErrorHandling(\n      keybindingStore.addDefaultKeybinding\n    )\n    const addSetting = wrapWithErrorHandling(settingStore.addSetting)\n\n    extension.keybindings?.forEach((keybinding) => {\n      addKeybinding(new KeybindingImpl(keybinding))\n    })\n    useCommandStore().loadExtensionCommands(extension)\n    useMenuItemStore().loadExtensionMenuCommands(extension)\n    extension.settings?.forEach(addSetting)\n    useBottomPanelStore().registerExtensionBottomPanelTabs(extension)\n    if (extension.getCustomWidgets) {\n      // TODO(huchenlei): We should deprecate the async return value of\n      // getCustomWidgets.\n      void (async () => {\n        if (extension.getCustomWidgets) {\n          const widgets = await extension.getCustomWidgets(useApp())\n          useWidgetStore().registerCustomWidgets(widgets)\n        }\n      })()\n    }\n\n    if (extension.onAuthUserResolved) {\n      const { onUserResolved } = useCurrentUser()\n      const handleUserResolved = wrapWithErrorHandlingAsync(\n        (user: AuthUserInfo) => extension.onAuthUserResolved?.(user, useApp()),\n        (error) => {\n          console.error('[Extension Auth Hook Error]', {\n            extension: extension.name,\n            hook: 'onAuthUserResolved',\n            error\n          })\n          toastErrorHandler(error)\n        }\n      )\n      onUserResolved((user) => {\n        void handleUserResolved(user)\n      })\n    }\n\n    if (extension.onAuthTokenRefreshed) {\n      const { onTokenRefreshed } = useCurrentUser()\n      const handleTokenRefreshed = wrapWithErrorHandlingAsync(\n        () => extension.onAuthTokenRefreshed?.(),\n        (error) => {\n          console.error('[Extension Auth Hook Error]', {\n            extension: extension.name,\n            hook: 'onAuthTokenRefreshed',\n            error\n          })\n          toastErrorHandler(error)\n        }\n      )\n      onTokenRefreshed(() => {\n        void handleTokenRefreshed()\n      })\n    }\n\n    if (extension.onAuthUserLogout) {\n      const { onUserLogout } = useCurrentUser()\n      const handleUserLogout = wrapWithErrorHandlingAsync(\n        () => extension.onAuthUserLogout?.(),\n        (error) => {\n          console.error('[Extension Auth Hook Error]', {\n            extension: extension.name,\n            hook: 'onAuthUserLogout',\n            error\n          })\n          toastErrorHandler(error)\n        }\n      )\n      onUserLogout(() => {\n        void handleUserLogout()\n      })\n    }\n  }\n\n  type RemoveLastAppParam<T> = T extends (\n    ...args: [...infer Rest, ComfyApp]\n  ) => infer R\n    ? (...args: Rest) => R\n    : T\n\n  type KnownExtensionMethods = Exclude<keyof ComfyExtension, number | symbol>\n\n  type ComfyExtensionMethod<T extends KnownExtensionMethods> =\n    ComfyExtension[T] extends (...args: unknown[]) => unknown\n      ? ComfyExtension[T]\n      : (...args: unknown[]) => unknown\n\n  type ComfyExtensionParamsWithoutApp<T extends KnownExtensionMethods> =\n    RemoveLastAppParam<ComfyExtensionMethod<T>>\n  /**\n   * Invoke an extension callback\n   * @param {keyof ComfyExtension} method The extension callback to execute\n   * @param  {unknown[]} args Any arguments to pass to the callback\n   * @returns\n   */\n  const invokeExtensions = <T extends KnownExtensionMethods>(\n    method: T,\n    ...args: Parameters<ComfyExtensionParamsWithoutApp<T>>\n  ) => {\n    const results: ReturnType<ComfyExtensionMethod<T>>[] = []\n    for (const ext of extensionStore.enabledExtensions) {\n      if (method in ext) {\n        try {\n          const fn = ext[method]\n          if (typeof fn === 'function') {\n            results.push(fn.call(ext, ...args, useApp()))\n          }\n        } catch (error) {\n          console.error(\n            `Error calling extension '${ext.name}' method '${method}'`,\n            { error },\n            { extension: ext },\n            { args }\n          )\n        }\n      }\n    }\n    return results\n  }\n\n  /**\n   * Invoke an async extension callback\n   * Each callback will be invoked concurrently, in extension order. Only\n   * extensions that define the callback do any work, and only promises that\n   * callbacks actually return are awaited (callbacks that return\n   * synchronously are never wrapped in a promise). The resolved array holds\n   * the results of the callbacks that ran, so it is not index-aligned with\n   * the extensions.\n   * @param {string} method The extension callback to execute\n   * @param  {...unknown} args Any arguments to pass to the callback\n   * @returns\n   */\n  const invokeExtensionsAsync = async <T extends KnownExtensionMethods>(\n    method: T,\n    ...args: Parameters<ComfyExtensionParamsWithoutApp<T>>\n  ) => {\n    const logError = (ext: ComfyExtension, error: unknown) =>\n      console.error(\n        `Error calling extension '${ext.name}' method '${method}'`,\n        { error },\n        { extension: ext },\n        { args }\n      )\n\n    // This runs once per node def per extension, so avoid allocating promises\n    // or closures for extensions that do not define the hook.\n    const pending: unknown[] = []\n    for (const ext of extensionStore.enabledExtensions) {\n      // The property read is inside the try so a throwing getter or Proxy trap\n      // only affects its own extension.\n      try {\n        const fn = ext[method]\n        if (typeof fn !== 'function') continue\n\n        if (method === 'setup') {\n          // Track the current extension for legacy compatibility\n          pending.push(\n            (async () => {\n              legacyMenuCompat.setCurrentExtension(ext.name)\n              try {\n                return await fn.call(ext, ...args, useApp())\n              } finally {\n                legacyMenuCompat.setCurrentExtension(null)\n              }\n            })().catch((error) => logError(ext, error))\n          )\n          continue\n        }\n\n        const result: unknown = fn.call(ext, ...args, useApp())\n        pending.push(\n          isPromiseLike(result)\n            ? Promise.resolve(result).catch((error) => logError(ext, error))\n            : result\n        )\n      } catch (error) {\n        logError(ext, error)\n      }\n    }\n    return await Promise.all(pending)\n  }\n\n  return {\n    registerExtension,\n    invokeExtensions,\n    invokeExtensionsAsync\n  }\n}\n","/**\n * @fileoverview Job output cache for caching and managing job data\n * @module services/jobOutputCache\n *\n * Centralizes job output and detail caching with LRU eviction.\n * Provides helpers for working with previewable outputs and workflows.\n */\n\nimport QuickLRU from '@alloc/quick-lru'\n\nimport type {\n  JobDetail,\n  JobOutputAsset\n} from '@/platform/remote/comfyui/jobs/jobTypes'\nimport {\n  extractApiPrompt,\n  extractWorkflow\n} from '@/platform/remote/comfyui/jobs/fetchJobs'\nimport type { ComfyWorkflowJSON } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport type { TaskOutput } from '@/platform/remote/comfyui/execution/types'\nimport { api } from '@/scripts/api'\nimport type { TaskItemImpl } from '@/stores/queueStore'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\nimport { findResultIndexByUrl } from '@/utils/resultItemUrl'\nimport { filterPreviewableResults } from '@/utils/resultItem'\nimport { parseTaskOutput } from '@/stores/resultItemParsing'\n\nconst MAX_TASK_CACHE_SIZE = 50\nconst MAX_JOB_DETAIL_CACHE_SIZE = 50\nconst MAX_JOB_ASSETS_CACHE_SIZE = 50\n\nconst taskCache = new QuickLRU<string, TaskItemImpl>({\n  maxSize: MAX_TASK_CACHE_SIZE\n})\nconst jobDetailCache = new QuickLRU<string, JobDetail>({\n  maxSize: MAX_JOB_DETAIL_CACHE_SIZE\n})\nconst jobAssetsCache = new QuickLRU<string, JobOutputAsset[]>({\n  maxSize: MAX_JOB_ASSETS_CACHE_SIZE\n})\nconst inFlightJobAssets = new Map<string, Promise<JobOutputAsset[]>>()\n\n// Track latest request to dedupe stale responses\nlet latestTaskRequestId: string | null = null\n\n// ===== Task Output Caching =====\n\nexport function findActiveIndex(\n  items: readonly AugmentedResultItem[],\n  url?: string\n): number {\n  return findResultIndexByUrl(items, url)\n}\n\n/**\n * Gets previewable outputs for a task, with lazy loading, caching, and request deduping.\n * Returns null if a newer request superseded this one while loading.\n */\nexport async function getOutputsForTask(\n  task: TaskItemImpl\n): Promise<AugmentedResultItem[] | null> {\n  const requestId = task.jobId\n  latestTaskRequestId = requestId\n\n  const outputsCount = task.outputsCount ?? 0\n  const needsLazyLoad = outputsCount > 1\n\n  if (!needsLazyLoad) {\n    return [...task.previewableOutputs]\n  }\n\n  const cached = taskCache.get(requestId)\n  if (cached) {\n    return [...cached.previewableOutputs]\n  }\n\n  try {\n    const loadedTask = await task.loadFullOutputs()\n\n    // Check if request was superseded while loading\n    if (latestTaskRequestId !== requestId) {\n      return null\n    }\n\n    taskCache.set(requestId, loadedTask)\n    return [...loadedTask.previewableOutputs]\n  } catch (error) {\n    if (latestTaskRequestId !== requestId) return null\n    console.warn('Failed to load full outputs, using preview:', error)\n    return [...task.previewableOutputs]\n  }\n}\n\nfunction getPreviewableOutputs(outputs?: TaskOutput): AugmentedResultItem[] {\n  if (!outputs) return []\n  return filterPreviewableResults(parseTaskOutput(outputs))\n}\n\nexport function getPreviewableOutputsFromJobDetail(\n  jobDetail?: JobDetail\n): AugmentedResultItem[] {\n  return getPreviewableOutputs(jobDetail?.outputs)\n}\n\n// ===== Job Detail Caching =====\n\nexport async function getJobDetail(\n  jobId: string\n): Promise<JobDetail | undefined> {\n  const cached = jobDetailCache.get(jobId)\n  if (cached) return cached\n\n  try {\n    const detail = await api.getJobDetail(jobId)\n    if (detail) {\n      jobDetailCache.set(jobId, detail)\n    }\n    return detail\n  } catch (error) {\n    console.warn('Failed to fetch job detail:', error)\n    return undefined\n  }\n}\n\n/**\n * Gets a job's output assets with LRU caching and in-flight request dedupe,\n * so N concurrent resolutions of the same job issue one network request.\n * Only complete, non-empty results are cached: an empty list usually means the\n * endpoint is unavailable or the assets are not yet persisted, and a truncated\n * one means a page failed mid-pagination. Caching either would pin an\n * under-resolved set until LRU eviction, long after the endpoint recovered.\n */\nexport async function getJobAssets(jobId: string): Promise<JobOutputAsset[]> {\n  const cached = jobAssetsCache.get(jobId)\n  if (cached) return cached\n\n  const inFlight = inFlightJobAssets.get(jobId)\n  if (inFlight) return inFlight\n\n  const request = api\n    .getJobAssets(jobId)\n    .then(({ assets, complete }) => {\n      if (complete && assets.length) jobAssetsCache.set(jobId, assets)\n      return assets\n    })\n    .finally(() => inFlightJobAssets.delete(jobId))\n  inFlightJobAssets.set(jobId, request)\n  return request\n}\n\nexport async function getJobWorkflow(\n  jobId: string\n): Promise<ComfyWorkflowJSON | undefined> {\n  const detail = await getJobDetail(jobId)\n  return await extractWorkflow(detail)\n}\n\n/**\n * The API-format graph a job stores, available only for jobs that embed no\n * editor workflow. Returned unvalidated — see `extractApiPrompt`.\n */\nexport async function getJobApiPrompt(jobId: string): Promise<unknown> {\n  const detail = await getJobDetail(jobId)\n  return extractApiPrompt(detail)\n}\n","import { defineStore } from 'pinia'\nimport { computed, ref, shallowRef, toRaw, toValue } from 'vue'\n\nimport { extractWorkflow } from '@/platform/remote/comfyui/jobs/fetchJobs'\nimport type {\n  APITaskType,\n  JobListItem,\n  TaskType\n} from '@/platform/remote/comfyui/jobs/jobTypes'\nimport type {\n  StatusWsMessageStatus,\n  TaskOutput\n} from '@/platform/remote/comfyui/execution/types'\nimport { api } from '@/scripts/api'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\nimport { filterPreviewableResults } from '@/utils/resultItem'\nimport { parseTaskOutput } from '@/stores/resultItemParsing'\nimport type { ComfyApp } from '@/types/comfy'\nimport { useExtensionService } from '@/services/extensionService'\nimport { getJobDetail } from '@/services/jobOutputCache'\nimport { useNodeOutputStore } from '@/stores/nodeOutputStore'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { tryNormalizeNodeExecutionId } from '@/types/nodeIdentification'\nimport { useSettingStore } from '@/platform/settings/settingStore'\n\nenum TaskItemDisplayStatus {\n  Running = 'Running',\n  Pending = 'Pending',\n  Completed = 'Completed',\n  Failed = 'Failed',\n  Cancelled = 'Cancelled'\n}\n\nfunction toAugmentedPreviewOutput(\n  previewOutput: NonNullable<JobListItem['preview_output']>\n): AugmentedResultItem {\n  return {\n    ...previewOutput,\n    filename: previewOutput.filename ?? '',\n    subfolder: previewOutput.subfolder ?? ''\n  }\n}\n\nexport class TaskItemImpl {\n  readonly job: JobListItem\n  readonly outputs: TaskOutput\n  readonly flatOutputs: ReadonlyArray<AugmentedResultItem>\n\n  constructor(\n    job: JobListItem,\n    outputs?: TaskOutput,\n    flatOutputs?: ReadonlyArray<AugmentedResultItem>\n  ) {\n    this.job = job\n    // If no outputs provided but job has preview_output, create synthetic outputs\n    // using the real nodeId and mediaType from the backend response\n    const effectiveOutputs =\n      outputs ??\n      (job.preview_output\n        ? {\n            [job.preview_output.nodeId]: {\n              [job.preview_output.mediaType]: [job.preview_output]\n            }\n          }\n        : {})\n    this.outputs = effectiveOutputs\n    this.flatOutputs =\n      flatOutputs ??\n      (!outputs && job.preview_output?.mediaType === 'text'\n        ? [toAugmentedPreviewOutput(job.preview_output)]\n        : this.calculateFlatOutputs())\n  }\n\n  calculateFlatOutputs(): ReadonlyArray<AugmentedResultItem> {\n    return parseTaskOutput(this.outputs)\n  }\n\n  /** All outputs that support preview (images, videos, audio, 3D, text) */\n  get previewableOutputs(): readonly AugmentedResultItem[] {\n    return filterPreviewableResults(this.flatOutputs)\n  }\n\n  get previewOutput(): AugmentedResultItem | undefined {\n    const previewable = this.previewableOutputs\n    // Prefer the last saved media file (most recent result) over temp previews\n    return (\n      previewable.findLast((output) => output.type === 'output') ??\n      previewable.at(-1)\n    )\n  }\n\n  // Derive taskType from job status\n  get taskType(): TaskType {\n    switch (this.job.status) {\n      case 'in_progress':\n        return 'Running'\n      case 'pending':\n        return 'Pending'\n      default:\n        return 'History'\n    }\n  }\n\n  get apiTaskType(): APITaskType {\n    switch (this.taskType) {\n      case 'Running':\n      case 'Pending':\n        return 'queue'\n      case 'History':\n        return 'history'\n    }\n  }\n\n  get key() {\n    return this.jobId + this.displayStatus\n  }\n\n  get jobId() {\n    return this.job.id\n  }\n\n  get outputsCount(): number | undefined {\n    return this.job.outputs_count ?? undefined\n  }\n\n  /** Absent on backends or jobs that predate this field. */\n  get previewableOutputsCount(): number | undefined {\n    return this.job.previewable_outputs_count ?? undefined\n  }\n\n  get status() {\n    return this.job.status\n  }\n\n  get errorMessage(): string | undefined {\n    return this.job.execution_error?.exception_message ?? undefined\n  }\n\n  get executionError() {\n    return this.job.execution_error ?? undefined\n  }\n\n  get workflowId(): string | undefined {\n    return this.job.workflow_id ?? undefined\n  }\n\n  get createTime(): number {\n    return this.job.create_time\n  }\n\n  get interrupted(): boolean {\n    return (\n      this.job.status === 'failed' &&\n      this.job.execution_error?.exception_type ===\n        'InterruptProcessingException'\n    )\n  }\n\n  get isHistory() {\n    return this.taskType === 'History'\n  }\n\n  get isRunning() {\n    return this.taskType === 'Running'\n  }\n\n  get displayStatus(): TaskItemDisplayStatus {\n    switch (this.job.status) {\n      case 'in_progress':\n        return TaskItemDisplayStatus.Running\n      case 'pending':\n        return TaskItemDisplayStatus.Pending\n      case 'completed':\n        return TaskItemDisplayStatus.Completed\n      case 'failed':\n        return TaskItemDisplayStatus.Failed\n      case 'cancelled':\n        return TaskItemDisplayStatus.Cancelled\n    }\n  }\n\n  get executionStartTimestamp() {\n    return this.job.execution_start_time ?? undefined\n  }\n\n  get executionEndTimestamp() {\n    return this.job.execution_end_time ?? undefined\n  }\n\n  get executionTime() {\n    if (!this.executionStartTimestamp || !this.executionEndTimestamp) {\n      return undefined\n    }\n    return this.executionEndTimestamp - this.executionStartTimestamp\n  }\n\n  get executionTimeInSeconds() {\n    return this.executionTime !== undefined\n      ? this.executionTime / 1000\n      : undefined\n  }\n\n  /**\n   * Loads full outputs for tasks that only have preview data\n   * Returns a new TaskItemImpl with full outputs and execution status\n   */\n  public async loadFullOutputs(): Promise<TaskItemImpl> {\n    // Only load for history tasks (caller checks outputsCount > 1)\n    if (!this.isHistory) {\n      return this\n    }\n    const jobDetail = await getJobDetail(this.jobId)\n\n    if (!jobDetail?.outputs) {\n      return this\n    }\n\n    // Create new TaskItemImpl with full outputs\n    return new TaskItemImpl(this.job, jobDetail.outputs)\n  }\n\n  public async loadWorkflow(app: ComfyApp) {\n    if (!this.isHistory) {\n      return\n    }\n\n    // Single fetch for both workflow and outputs (with caching)\n    const jobDetail = await getJobDetail(this.jobId)\n\n    const workflowData = await extractWorkflow(jobDetail)\n    if (!workflowData) {\n      return\n    }\n\n    await app.loadGraphData(toRaw(workflowData))\n\n    // Use full outputs from job detail, or fall back to existing outputs\n    const outputsToLoad = jobDetail?.outputs ?? this.outputs\n    const nodeOutputsStore = useNodeOutputStore()\n    const rawOutputs = toRaw(outputsToLoad)\n    for (const rawNodeExecutionId in rawOutputs) {\n      const nodeExecutionId = tryNormalizeNodeExecutionId(rawNodeExecutionId)\n      if (!nodeExecutionId) continue\n      nodeOutputsStore.setNodeOutputsByExecutionId(\n        nodeExecutionId,\n        rawOutputs[rawNodeExecutionId]\n      )\n    }\n    useExtensionService().invokeExtensions(\n      'onNodeOutputsUpdated',\n      app.nodeOutputs\n    )\n  }\n\n  public flatten(): TaskItemImpl[] {\n    if (this.displayStatus !== TaskItemDisplayStatus.Completed) {\n      return [this]\n    }\n\n    return this.flatOutputs.map(\n      (output: AugmentedResultItem, i: number) =>\n        new TaskItemImpl(\n          {\n            ...this.job,\n            id: `${this.jobId}-${i}`\n          },\n          {\n            [output.nodeId]: {\n              [output.mediaType]: [output]\n            }\n          },\n          [output]\n        )\n    )\n  }\n}\n\nexport const useQueueStore = defineStore('queue', () => {\n  // Use shallowRef because TaskItemImpl instances are immutable and arrays are\n  // replaced entirely (not mutated), so deep reactivity would waste performance\n  const runningTasks = shallowRef<TaskItemImpl[]>([])\n  const pendingTasks = shallowRef<TaskItemImpl[]>([])\n  const historyTasks = shallowRef<TaskItemImpl[]>([])\n  const hasFetchedHistorySnapshot = ref(false)\n  const maxHistoryItems = ref(64)\n  const isLoading = ref(false)\n\n  // Single-flight coalescing: at most one fetch in flight at a time.\n  // If update() is called while a fetch is running, the call is coalesced\n  // and a single re-fetch fires after the current one completes.\n  // This prevents both request spam and UI starvation (where a rapid stream\n  // of calls causes every response to be discarded by a stale-request guard).\n  const updateState = { inFlight: false, dirty: false }\n  const hasDirtyUpdate = () => updateState.dirty\n\n  const tasks = computed<TaskItemImpl[]>(\n    () =>\n      [\n        ...pendingTasks.value,\n        ...runningTasks.value,\n        ...historyTasks.value\n      ] as TaskItemImpl[]\n  )\n\n  const flatTasks = computed<TaskItemImpl[]>(() =>\n    tasks.value.flatMap((task: TaskItemImpl) => task.flatten())\n  )\n\n  const lastJobHistoryPriority = computed<number>(() =>\n    historyTasks.value.length ? historyTasks.value[0].job.priority : -1\n  )\n\n  const hasPendingTasks = computed<boolean>(() => pendingTasks.value.length > 0)\n  const activeJobsCount = computed(\n    () => pendingTasks.value.length + runningTasks.value.length\n  )\n\n  const update = async () => {\n    if (updateState.inFlight) {\n      updateState.dirty = true\n      return\n    }\n\n    updateState.inFlight = true\n    updateState.dirty = false\n    isLoading.value = true\n    try {\n      const [queueResult, historyResult] = await Promise.allSettled([\n        api.getQueue({ throwOnError: true }),\n        api.getHistory(maxHistoryItems.value)\n      ])\n\n      if (queueResult.status === 'fulfilled') {\n        const queue = queueResult.value\n        // API returns pre-sorted data (sort_by=create_time&order=desc)\n        runningTasks.value = queue.Running.map((job) => new TaskItemImpl(job))\n        pendingTasks.value = queue.Pending.map((job) => new TaskItemImpl(job))\n\n        const appearedTasks = [...pendingTasks.value, ...runningTasks.value]\n        const executionStore = useExecutionStore()\n        appearedTasks.forEach((task) => {\n          const jobIdString = task.jobId\n          const workflowId = task.workflowId\n          if (workflowId && jobIdString) {\n            executionStore.registerJobWorkflowIdMapping(jobIdString, workflowId)\n          }\n        })\n\n        const activeJobIds = new Set([\n          ...queue.Running.map((j) => j.id),\n          ...queue.Pending.map((j) => j.id)\n        ])\n        executionStore.reconcileInitializingJobs(activeJobIds)\n      } else {\n        console.error('Failed to fetch queue:', queueResult.reason)\n      }\n\n      if (historyResult.status === 'fulfilled') {\n        const history = historyResult.value\n        const currentHistory = toValue(historyTasks)\n\n        // Sort by create_time descending and limit to maxItems\n        const sortedHistory = [...history]\n          .sort((a, b) => b.create_time - a.create_time)\n          .slice(0, toValue(maxHistoryItems))\n\n        // Reuse existing TaskItemImpl instances or create new\n        // Must recreate if outputs_count changed (e.g., API started returning it)\n        const existingByJobId = new Map(\n          currentHistory.map((impl) => [impl.jobId, impl])\n        )\n\n        const nextHistoryTasks = sortedHistory.map((job) => {\n          const existing = existingByJobId.get(job.id)\n          if (!existing) return new TaskItemImpl(job)\n          // Recreate if outputs_count changed to ensure lazy loading works\n          if (\n            existing.outputsCount !== (job.outputs_count ?? undefined) ||\n            existing.previewableOutputsCount !==\n              (job.previewable_outputs_count ?? undefined)\n          ) {\n            return new TaskItemImpl(job)\n          }\n          return existing\n        })\n\n        const isHistoryUnchanged =\n          nextHistoryTasks.length === currentHistory.length &&\n          nextHistoryTasks.every(\n            (task, index) => task === currentHistory[index]\n          )\n\n        if (!isHistoryUnchanged) {\n          historyTasks.value = nextHistoryTasks\n        }\n        hasFetchedHistorySnapshot.value = true\n      } else {\n        console.error('Failed to fetch history:', historyResult.reason)\n      }\n    } finally {\n      isLoading.value = false\n      updateState.inFlight = false\n      if (hasDirtyUpdate()) {\n        void update()\n      }\n    }\n  }\n\n  const clear = async (\n    targets: ('queue' | 'history')[] = ['queue', 'history']\n  ) => {\n    if (targets.length === 0) {\n      return\n    }\n    await Promise.all(targets.map((type) => api.clearItems(type)))\n    await update()\n  }\n\n  const deleteTask = async (task: TaskItemImpl) => {\n    await api.deleteItem(task.apiTaskType, task.jobId)\n    await update()\n  }\n\n  return {\n    runningTasks,\n    pendingTasks,\n    historyTasks,\n    hasFetchedHistorySnapshot,\n    maxHistoryItems,\n    isLoading,\n\n    tasks,\n    flatTasks,\n    lastJobHistoryPriority,\n    hasPendingTasks,\n    activeJobsCount,\n\n    update,\n    clear,\n    delete: deleteTask\n  }\n})\n\nexport const useQueuePendingTaskCountStore = defineStore(\n  'queuePendingTaskCount',\n  {\n    state: () => ({\n      count: 0\n    }),\n    actions: {\n      update(e: CustomEvent<StatusWsMessageStatus | null>) {\n        const queueRemaining = e.detail?.exec_info?.queue_remaining\n        if (queueRemaining != null) this.count = queueRemaining\n      }\n    }\n  }\n)\n\nexport const useQueueUIStore = defineStore('queueUIStore', () => {\n  const settingStore = useSettingStore()\n\n  const isOverlayExpanded = computed({\n    get: () => settingStore.get('Comfy.Queue.History.Expanded'),\n    set: (value) => settingStore.set('Comfy.Queue.History.Expanded', value)\n  })\n\n  function toggleOverlay() {\n    isOverlayExpanded.value = !isOverlayExpanded.value\n  }\n\n  return { isOverlayExpanded, toggleOverlay }\n})\n","import { z } from 'zod'\nimport { fromZodError } from 'zod-validation-error'\n\nimport { zTaskResponse as zGeneratedTaskResponse } from '@comfyorg/ingest-types/zod'\n\nimport { api } from '@/scripts/api'\nimport { toError } from '@/utils/errorUtil'\n\nconst TASKS_ENDPOINT = '/tasks'\n\nconst zTaskStatus = z.union([\n  zGeneratedTaskResponse.shape.status,\n  z.literal('cancelled')\n])\n\nconst zTaskResponse = zGeneratedTaskResponse.extend({\n  // Cloud commit 13d6f5f9 adds cancellation before generated types can sync.\n  status: zTaskStatus\n})\n\n/**\n * Result payload of a `task:download_file` task.\n *\n * `/tasks` is shared by every task type, so `TaskResponse.result` stays the\n * generated opaque record and each caller parses the shape its own task type\n * produces. Narrowing `result` on the shared response instead makes `getTask`\n * reject every other task type's result, which silently disables\n * reconciliation for those callers.\n */\nconst zDownloadFileResult = z.object({\n  success: z.boolean(),\n  file_path: z.string().optional(),\n  bytes_downloaded: z.number().optional(),\n  content_type: z.string().optional(),\n  hash: z.string().optional(),\n  filename: z.string().optional(),\n  asset_id: z.string().optional(),\n  metadata: z.record(z.string(), z.unknown()).optional(),\n  error: z.string().optional()\n})\n\nexport type TaskResponse = z.infer<typeof zTaskResponse>\nexport type TaskStatus = TaskResponse['status']\nexport type TaskResult<T> = { ok: true; value: T } | { ok: false; error: Error }\nexport type DownloadFileResult = z.infer<typeof zDownloadFileResult>\n\n/** Returns the download-file result, or `undefined` if it is absent or malformed. */\nexport function parseDownloadFileResult(\n  result: unknown\n): DownloadFileResult | undefined {\n  const parsed = zDownloadFileResult.safeParse(result)\n  return parsed.success ? parsed.data : undefined\n}\n\n/**\n * Outcome of a cancellation request. Callers need these apart because each one\n * implies a different next step: wait for a terminal status, settle locally\n * because none is coming, or re-read the task's real status.\n */\nexport type CancelTaskOutcome =\n  /** The backend accepted it and will report a terminal status. */\n  | 'cancelling'\n  /** The task row is gone, so no terminal status will ever arrive. */\n  | 'missing'\n  /** The backend refused to cancel from the task's current state. */\n  | 'not-cancellable'\n\n/**\n * Identifier for a background task tracked by the `/tasks` API.\n *\n * Backed by `TaskResponse.id` which is `z.string().uuid()`. This alias names\n * that primitive at use sites without changing structural typing.\n */\nexport type TaskId = string\n\n/**\n * A `getTask` failure that proves the task row no longer exists, as opposed to\n * a transient failure worth retrying. Callers tracking a task that can never\n * reach a terminal status need to tell those apart to stop polling it.\n */\nexport class TaskNotFoundError extends Error {\n  constructor(taskId: TaskId) {\n    super(`Task not found: ${taskId}`)\n    this.name = 'TaskNotFoundError'\n  }\n}\n\nfunction createTaskService() {\n  async function getTask(taskId: TaskId): Promise<TaskResult<TaskResponse>> {\n    try {\n      const res = await api.fetchApi(\n        `${TASKS_ENDPOINT}/${encodeURIComponent(taskId)}`\n      )\n\n      if (!res.ok) {\n        return {\n          ok: false,\n          error:\n            res.status === 404\n              ? new TaskNotFoundError(taskId)\n              : new Error(`Failed to get task ${taskId}: ${res.status}`)\n        }\n      }\n\n      const data: unknown = await res.json()\n      const result = zTaskResponse.safeParse(data)\n\n      if (!result.success) {\n        return {\n          ok: false,\n          error: new Error(fromZodError(result.error).message)\n        }\n      }\n\n      return { ok: true, value: result.data }\n    } catch (error) {\n      return { ok: false, error: toError(error) }\n    }\n  }\n\n  async function cancelTask(\n    taskId: TaskId\n  ): Promise<TaskResult<CancelTaskOutcome>> {\n    try {\n      const res = await api.fetchApi(\n        `${TASKS_ENDPOINT}/${encodeURIComponent(taskId)}`,\n        { method: 'DELETE' }\n      )\n      if (res.status === 404) return { ok: true, value: 'missing' }\n      if (res.status === 409) return { ok: true, value: 'not-cancellable' }\n      if (!res.ok) {\n        // This message reaches a user-facing toast and telemetry, so the\n        // response body stays out of it: a 5xx from a gateway or reverse proxy\n        // is usually an HTML error page or a stack trace.\n        return {\n          ok: false,\n          error: new Error(`Failed to cancel task ${taskId}: ${res.status}`)\n        }\n      }\n      return { ok: true, value: 'cancelling' }\n    } catch (error) {\n      return { ok: false, error: toError(error) }\n    }\n  }\n\n  return { getTask, cancelTask }\n}\n\nexport const taskService = createTaskService()\n","import { useIntervalFn } from '@vueuse/core'\nimport { defineStore } from 'pinia'\nimport { computed, reactive, ref, watch } from 'vue'\n\nimport type {\n  DownloadFileResult,\n  TaskId,\n  TaskResponse,\n  TaskResult,\n  TaskStatus\n} from '@/platform/tasks/services/taskService'\nimport {\n  TaskNotFoundError,\n  parseDownloadFileResult,\n  taskService\n} from '@/platform/tasks/services/taskService'\nimport type { AssetDownloadWsMessage } from '@/platform/remote/comfyui/execution/types'\nimport { api } from '@/scripts/api'\nimport { t } from '@/i18n'\n\nexport type AssetDownloadStatus =\n  | TaskStatus\n  | 'cancellation_pending'\n  | 'cancellation_unconfirmed'\n\nconst activeStatuses = new Set<AssetDownloadStatus>(['created', 'running'])\nconst finishedStatuses = new Set<AssetDownloadStatus>([\n  'completed',\n  'failed',\n  'cancelled',\n  'cancellation_unconfirmed'\n])\nconst recheckableStatuses = new Set<AssetDownloadStatus>([\n  'created',\n  'running',\n  'failed',\n  'cancellation_pending'\n])\nconst reconcilableTaskStatuses = new Set<TaskStatus>([\n  'completed',\n  'failed',\n  'cancelled'\n])\nconst wireTaskStatuses = new Set<string>([\n  'created',\n  'running',\n  'completed',\n  'failed',\n  'cancelled'\n])\n\nfunction isDownloadActive(status: AssetDownloadStatus) {\n  return activeStatuses.has(status)\n}\n\nexport function isDownloadCancelled(status: AssetDownloadStatus) {\n  return (\n    status === 'cancellation_pending' ||\n    status === 'cancellation_unconfirmed' ||\n    status === 'cancelled'\n  )\n}\n\nfunction isDownloadFinished(status: AssetDownloadStatus) {\n  return finishedStatuses.has(status)\n}\n\nfunction isDownloadRecheckable(status: AssetDownloadStatus) {\n  return recheckableStatuses.has(status)\n}\n\nexport interface AssetDownload {\n  taskId: TaskId\n  assetName: string\n  bytesTotal: number\n  bytesDownloaded: number\n  progress: number\n  status: AssetDownloadStatus\n  lastUpdate: number\n  assetId?: string\n  error?: string\n  modelType?: string\n  acknowledged?: boolean\n  /**\n   * Reconciliation attempts made since this download entered\n   * `cancellation_pending` that did not produce a terminal task status.\n   */\n  cancellationReconcileAttempts?: number\n}\n\ninterface CompletedDownload {\n  taskId: TaskId\n  modelType: string\n  timestamp: number\n}\ninterface DismissedDownload {\n  modelType?: string\n  completionNotified: boolean\n}\nconst STALE_THRESHOLD_MS = 10_000\nconst POLL_INTERVAL_MS = 10_000\n/**\n * `cancellation_pending` is not a finished status, so the dialog withholds its\n * Close control while a download is in it. Bounding how long we wait for the\n * backend to confirm keeps a backend that accepts the DELETE and then never\n * reports a terminal status from pinning the toast open until a page reload.\n */\nconst MAX_CANCELLATION_RECONCILE_ATTEMPTS = 6\nconst MAX_TASK_NOT_FOUND_ATTEMPTS = 2\nconst MAX_FAILED_RECONCILE_ATTEMPTS = 30\nconst MAX_DISMISSED_DOWNLOADS = 256\n\nfunction generateDownloadTrackingPlaceholder(\n  taskId: TaskId,\n  modelType: string,\n  assetName: string\n): AssetDownload {\n  return {\n    taskId,\n    modelType,\n    assetName,\n    bytesTotal: 0,\n    bytesDownloaded: 0,\n    progress: 0,\n    status: 'created',\n    lastUpdate: Date.now()\n  }\n}\n\nfunction shouldIgnoreDownloadUpdate(\n  currentStatus: AssetDownloadStatus | undefined,\n  nextStatus: TaskStatus\n): boolean {\n  if (currentStatus === 'completed') return true\n  if (currentStatus === 'cancelled') return nextStatus !== 'completed'\n  if (currentStatus === 'cancellation_pending') {\n    return !reconcilableTaskStatuses.has(nextStatus)\n  }\n  if (currentStatus === 'cancellation_unconfirmed') {\n    return activeStatuses.has(nextStatus)\n  }\n  return false\n}\n\n/**\n * Settle a cancellation the backend will never confirm. `cancelled` is not\n * immutable in `shouldIgnoreDownloadUpdate`, so a later authoritative\n * `completed` still replaces it; the stale error from any premature `failed`\n * message is dropped because it no longer describes this entry.\n */\nfunction finalizeCancellation(download: AssetDownload) {\n  download.status = 'cancelled'\n  download.error = undefined\n  download.lastUpdate = Date.now()\n}\n\n/**\n * Record a reconciliation attempt that left a pending cancellation unresolved,\n * exposing an unconfirmed but dismissible state once the attempts are\n * exhausted. A later WebSocket completion can still replace it, but polling\n * stops once the bounded reconciliation window is exhausted.\n */\nfunction noteAuthoritativePendingCancellation(download: AssetDownload) {\n  if (download.status !== 'cancellation_pending') return\n\n  const attempts = (download.cancellationReconcileAttempts ?? 0) + 1\n  download.cancellationReconcileAttempts = attempts\n  if (attempts >= MAX_CANCELLATION_RECONCILE_ATTEMPTS) {\n    download.status = 'cancellation_unconfirmed'\n    download.lastUpdate = Date.now()\n  }\n}\n\nfunction resultValue<T>(value: T | undefined, fallback: T | undefined) {\n  return value === undefined ? fallback : value\n}\n\nfunction requiredResultValue<T>(value: T | undefined, fallback: T): T {\n  return value === undefined ? fallback : value\n}\n\nfunction createReconciledDownloadMessage(\n  download: AssetDownload,\n  task: TaskResponse\n): AssetDownloadWsMessage | undefined {\n  const result = parseDownloadFileResult(task.result)\n  // The task status is authoritative even when an older backend returns a\n  // result shape we cannot parse. Preserve the fields learned from the socket\n  // so the row can still settle instead of polling forever.\n  const reconciledResult: Partial<DownloadFileResult> = result ?? {}\n  const assetId = resultValue(reconciledResult.asset_id, download.assetId)\n  const assetName = requiredResultValue(\n    reconciledResult.filename,\n    download.assetName\n  )\n  const bytesDownloaded = requiredResultValue(\n    reconciledResult.bytes_downloaded,\n    download.bytesDownloaded\n  )\n  const error = resultValue(task.error_message, reconciledResult.error)\n  return {\n    task_id: download.taskId,\n    asset_id: assetId,\n    asset_name: assetName,\n    bytes_total: download.bytesTotal,\n    bytes_downloaded: bytesDownloaded,\n    progress: task.status === 'completed' ? 100 : download.progress,\n    status: task.status,\n    error\n  }\n}\n\nfunction canCancelDownload(\n  download: AssetDownload | undefined,\n  isCancelling: boolean\n) {\n  if (!download || isCancelling) return false\n  return activeStatuses.has(download.status) || download.status === 'failed'\n}\n\nfunction isSettledDownload(download: AssetDownload) {\n  return (\n    download.status === 'completed' ||\n    download.status === 'cancelled' ||\n    download.status === 'cancellation_unconfirmed'\n  )\n}\n\nfunction beginPendingCancellation(download: AssetDownload) {\n  download.status = 'cancellation_pending'\n  download.error = undefined\n  download.cancellationReconcileAttempts = 0\n  download.lastUpdate = Date.now()\n}\n\nfunction settleUnknownDownloadStatus(\n  existing: AssetDownload | undefined,\n  data: AssetDownloadWsMessage\n) {\n  if (\n    !existing ||\n    isSettledDownload(existing) ||\n    existing.status === 'cancellation_pending' ||\n    existing.status === 'failed'\n  )\n    return\n  existing.status = 'failed'\n  existing.error = data.error || `Unknown task status: ${data.status}`\n  existing.lastUpdate = Date.now()\n}\n\nexport const useAssetDownloadStore = defineStore('assetDownload', () => {\n  const downloads = ref<Map<string, AssetDownload>>(new Map())\n  const cancellingTaskIds = ref(new Set<TaskId>())\n  const reconcilingTasks = new Map<TaskId, Promise<void>>()\n  const dismissedPendingDownloads = new Map<TaskId, DismissedDownload>()\n  const taskNotFoundAttempts = new Map<TaskId, number>()\n  const unavailableTaskIds = reactive(new Set<TaskId>())\n  const failedReconcileAttempts = reactive(new Map<TaskId, number>())\n  const settledFailureTaskIds = reactive(new Set<TaskId>())\n  const lastCompletedDownload = ref<CompletedDownload | null>(null)\n\n  const downloadList = computed(() => Array.from(downloads.value.values()))\n  const activeDownloads = computed(() =>\n    downloadList.value.filter((download) => isDownloadActive(download.status))\n  )\n  const finishedDownloads = computed(() =>\n    downloadList.value.filter((download) => isDownloadFinished(download.status))\n  )\n  const unacknowledgedDownloads = computed(() =>\n    finishedDownloads.value.filter(\n      (d) => d.status === 'completed' && d.assetId && !d.acknowledged\n    )\n  )\n  const sessionDownloadCount = computed(\n    () => unacknowledgedDownloads.value.length\n  )\n  const hasActiveDownloads = computed(() => activeDownloads.value.length > 0)\n  const hasDownloads = computed(() => downloads.value.size > 0)\n  const hasPendingCancellation = computed(() =>\n    downloadList.value.some(\n      (download) => download.status === 'cancellation_pending'\n    )\n  )\n  const recheckableDownloads = computed(() =>\n    downloadList.value.filter(\n      (download) =>\n        isDownloadRecheckable(download.status) &&\n        !unavailableTaskIds.has(download.taskId) &&\n        !settledFailureTaskIds.has(download.taskId)\n    )\n  )\n  const hasRecheckableDownloads = computed(\n    () => recheckableDownloads.value.length > 0\n  )\n\n  function isDownloadedThisSession(assetId: string): boolean {\n    return unacknowledgedDownloads.value.some((d) => d.assetId === assetId)\n  }\n\n  function acknowledgeAsset(assetId: string) {\n    for (const download of downloads.value.values()) {\n      if (download.assetId === assetId) {\n        download.acknowledged = true\n      }\n    }\n  }\n\n  function trackDownload(taskId: TaskId, modelType: string, assetName: string) {\n    if (downloads.value.has(taskId)) return\n\n    dismissedPendingDownloads.delete(taskId)\n    taskNotFoundAttempts.delete(taskId)\n    unavailableTaskIds.delete(taskId)\n    failedReconcileAttempts.delete(taskId)\n    settledFailureTaskIds.delete(taskId)\n    downloads.value.set(\n      taskId,\n      generateDownloadTrackingPlaceholder(taskId, modelType, assetName)\n    )\n  }\n\n  function rememberDismissedDownload(download: AssetDownload) {\n    dismissedPendingDownloads.delete(download.taskId)\n    dismissedPendingDownloads.set(download.taskId, {\n      modelType: download.modelType,\n      completionNotified: download.status === 'completed'\n    })\n    while (dismissedPendingDownloads.size > MAX_DISMISSED_DOWNLOADS) {\n      const oldestTaskId = dismissedPendingDownloads.keys().next().value\n      if (oldestTaskId === undefined) break\n      dismissedPendingDownloads.delete(oldestTaskId)\n    }\n  }\n\n  function consumeDismissedDownload(data: AssetDownloadWsMessage): boolean {\n    if (!dismissedPendingDownloads.has(data.task_id)) return false\n\n    const dismissed = dismissedPendingDownloads.get(data.task_id)\n    if (\n      data.status === 'completed' &&\n      dismissed?.modelType &&\n      !dismissed.completionNotified\n    ) {\n      lastCompletedDownload.value = {\n        taskId: data.task_id,\n        modelType: dismissed.modelType,\n        timestamp: Date.now()\n      }\n      dismissed.completionNotified = true\n    }\n    return true\n  }\n\n  function handleAssetDownload(e: CustomEvent<AssetDownloadWsMessage>) {\n    const data = e.detail\n    if (consumeDismissedDownload(data)) return\n    const existing = downloads.value.get(data.task_id)\n\n    // WebSocket payloads are not runtime-validated at the event boundary.\n    // Unknown statuses must not create immortal, non-dismissible rows.\n    if (!wireTaskStatuses.has(data.status)) {\n      settleUnknownDownloadStatus(existing, data)\n      return\n    }\n\n    if (shouldIgnoreDownloadUpdate(existing?.status, data.status)) return\n\n    if (activeStatuses.has(data.status)) {\n      taskNotFoundAttempts.delete(data.task_id)\n      unavailableTaskIds.delete(data.task_id)\n      failedReconcileAttempts.delete(data.task_id)\n      settledFailureTaskIds.delete(data.task_id)\n    }\n\n    const download: AssetDownload = {\n      taskId: data.task_id,\n      assetId: data.asset_id,\n      assetName: data.asset_name,\n      bytesTotal: data.bytes_total,\n      bytesDownloaded: data.bytes_downloaded,\n      progress: data.progress,\n      status: data.status,\n      error: data.error,\n      lastUpdate: Date.now(),\n      modelType: existing?.modelType\n    }\n\n    downloads.value.set(data.task_id, download)\n\n    if (data.status === 'completed' && download.modelType) {\n      lastCompletedDownload.value = {\n        taskId: data.task_id,\n        modelType: download.modelType,\n        timestamp: Date.now()\n      }\n    }\n  }\n\n  function handleTaskNotFound(download: AssetDownload) {\n    if (download.status === 'cancellation_pending') {\n      taskNotFoundAttempts.delete(download.taskId)\n      finalizeCancellation(download)\n      return\n    }\n\n    const attempts = (taskNotFoundAttempts.get(download.taskId) ?? 0) + 1\n    taskNotFoundAttempts.set(download.taskId, attempts)\n    if (attempts < MAX_TASK_NOT_FOUND_ATTEMPTS) {\n      download.lastUpdate = Date.now()\n      return\n    }\n    taskNotFoundAttempts.delete(download.taskId)\n    unavailableTaskIds.add(download.taskId)\n    download.status = 'failed'\n    download.error = t('progressToast.taskUnavailable')\n    download.lastUpdate = Date.now()\n  }\n\n  async function runReconciliation(download: AssetDownload) {\n    const result = await taskService.getTask(download.taskId)\n    if (downloads.value.get(download.taskId) !== download) return\n\n    if (!result.ok) {\n      // A 404 is authoritative: the task row is gone, so a pending\n      // cancellation has nothing left to wait for. Other lookup failures are\n      // transient and must not consume the authoritative reconciliation bound.\n      if (result.error instanceof TaskNotFoundError) {\n        handleTaskNotFound(download)\n      } else {\n        taskNotFoundAttempts.delete(download.taskId)\n      }\n      return\n    }\n\n    taskNotFoundAttempts.delete(download.taskId)\n    unavailableTaskIds.delete(download.taskId)\n    const task = result.value\n    if (\n      download.status === 'cancellation_pending' &&\n      activeStatuses.has(task.status)\n    ) {\n      noteAuthoritativePendingCancellation(download)\n      return\n    }\n\n    const message = createReconciledDownloadMessage(download, task)\n    if (!message) {\n      download.lastUpdate = Date.now()\n      noteAuthoritativePendingCancellation(download)\n      return\n    }\n    if (task.status === 'failed') {\n      const attempts = (failedReconcileAttempts.get(download.taskId) ?? 0) + 1\n      failedReconcileAttempts.set(download.taskId, attempts)\n      if (attempts >= MAX_FAILED_RECONCILE_ATTEMPTS) {\n        settledFailureTaskIds.add(download.taskId)\n      }\n    } else {\n      failedReconcileAttempts.delete(download.taskId)\n      settledFailureTaskIds.delete(download.taskId)\n    }\n    handleAssetDownload(\n      new CustomEvent('asset_download', {\n        detail: message\n      })\n    )\n  }\n\n  async function reconcileDownload(\n    download: AssetDownload,\n    rereadAfterInFlight = false\n  ) {\n    const inFlight = reconcilingTasks.get(download.taskId)\n    if (inFlight) {\n      if (!rereadAfterInFlight) return\n      await inFlight\n      const latest = downloads.value.get(download.taskId)\n      if (!latest || isSettledDownload(latest)) return\n      download = latest\n    }\n\n    const reconciliation = runReconciliation(download)\n    reconcilingTasks.set(download.taskId, reconciliation)\n    try {\n      await reconciliation\n    } finally {\n      if (reconcilingTasks.get(download.taskId) === reconciliation) {\n        reconcilingTasks.delete(download.taskId)\n      }\n    }\n  }\n\n  async function pollStaleDownloads() {\n    const now = Date.now()\n    const staleDownloads = recheckableDownloads.value.filter(\n      (d) => now - d.lastUpdate >= STALE_THRESHOLD_MS\n    )\n\n    if (staleDownloads.length === 0) return\n\n    await Promise.all(\n      staleDownloads.map((download) => reconcileDownload(download))\n    )\n  }\n\n  const { pause, resume } = useIntervalFn(\n    () => void pollStaleDownloads(),\n    POLL_INTERVAL_MS,\n    { immediate: false }\n  )\n\n  watch(\n    hasRecheckableDownloads,\n    (hasRecheckable) => {\n      if (hasRecheckable) resume()\n      else pause()\n    },\n    { immediate: true }\n  )\n\n  api.addEventListener('asset_download', handleAssetDownload)\n\n  function clearFinishedDownloads() {\n    for (const download of finishedDownloads.value) {\n      rememberDismissedDownload(download)\n      taskNotFoundAttempts.delete(download.taskId)\n      unavailableTaskIds.delete(download.taskId)\n      failedReconcileAttempts.delete(download.taskId)\n      settledFailureTaskIds.delete(download.taskId)\n      downloads.value.delete(download.taskId)\n    }\n  }\n\n  function clearDismissibleDownloads() {\n    for (const download of downloadList.value) {\n      if (\n        isDownloadFinished(download.status) ||\n        download.status === 'cancellation_pending'\n      ) {\n        rememberDismissedDownload(download)\n        taskNotFoundAttempts.delete(download.taskId)\n        unavailableTaskIds.delete(download.taskId)\n        failedReconcileAttempts.delete(download.taskId)\n        settledFailureTaskIds.delete(download.taskId)\n        downloads.value.delete(download.taskId)\n      }\n    }\n  }\n\n  async function cancelDownload(taskId: TaskId): Promise<TaskResult<boolean>> {\n    const download = downloads.value.get(taskId)\n    if (!canCancelDownload(download, cancellingTaskIds.value.has(taskId))) {\n      return { ok: true, value: false }\n    }\n    cancellingTaskIds.value.add(taskId)\n    try {\n      const result = await taskService.cancelTask(taskId)\n      if (!result.ok) return result\n\n      const current = downloads.value.get(taskId)\n      if (!current) return { ok: true, value: false }\n      if (isSettledDownload(current)) {\n        return { ok: true, value: result.value === 'cancelling' }\n      }\n      unavailableTaskIds.delete(taskId)\n      failedReconcileAttempts.delete(taskId)\n      settledFailureTaskIds.delete(taskId)\n\n      // A DELETE 404 can mean the cancellation route is unavailable, not that\n      // the task is gone. Re-read the task before deciding how to settle it.\n      if (result.value === 'missing') {\n        beginPendingCancellation(current)\n        await reconcileDownload(current, true)\n        const latest = downloads.value.get(taskId)\n        if (!latest) return { ok: true, value: false }\n        if (latest.status === 'cancelled') return { ok: true, value: true }\n        return { ok: true, value: false }\n      }\n\n      // The backend refused. Re-read the task so the row moves to whatever\n      // status it is really in, instead of silently re-enabling Cancel.\n      if (result.value === 'not-cancellable') {\n        await reconcileDownload(current, true)\n        return { ok: true, value: false }\n      }\n\n      beginPendingCancellation(current)\n      return { ok: true, value: true }\n    } finally {\n      cancellingTaskIds.value.delete(taskId)\n    }\n  }\n\n  return {\n    activeDownloads,\n    finishedDownloads,\n    hasActiveDownloads,\n    hasDownloads,\n    hasPendingCancellation,\n    downloadList,\n    lastCompletedDownload,\n    sessionDownloadCount,\n    trackDownload,\n    cancellingTaskIds,\n    cancelDownload,\n    clearDismissibleDownloads,\n    clearFinishedDownloads,\n    isDownloadedThisSession,\n    acknowledgeAsset\n  }\n})\n","import { useAsyncState, whenever } from '@vueuse/core'\nimport { delay, difference } from 'es-toolkit'\nimport { defineStore } from 'pinia'\nimport {\n  computed,\n  effectScope,\n  reactive,\n  ref,\n  shallowReactive,\n  toValue,\n  watch\n} from 'vue'\nimport type { EffectScope } from 'vue'\n\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport {\n  mapInputFileToAssetItem,\n  mapTaskOutputToAssetItem,\n  unflattenOutputAssets\n} from '@/platform/assets/composables/media/assetMappers'\nimport type {\n  AssetItem,\n  AssetResponse,\n  TagsOperationResult\n} from '@/platform/assets/schemas/assetSchema'\nimport {\n  useAssetsQuery,\n  invalidateAll\n} from '@/platform/assets/composables/useAssetsQuery'\nimport { assetService } from '@/platform/assets/services/assetService'\nimport type { AssetPaginationOptions } from '@/platform/assets/services/assetService'\nimport type { JobListItem } from '@/platform/remote/comfyui/jobs/jobTypes'\nimport { api } from '@/scripts/api'\nimport { WrappedList } from '@/utils/pagedList'\nimport type { PagedList } from '@/utils/pagedList'\n\nimport { TaskItemImpl } from './queueStore'\nimport { useAssetDownloadStore } from './assetDownloadStore'\nimport { useModelToNodeStore } from './modelToNodeStore'\n\n/**\n * Fetch input files from the internal API (OSS version)\n */\nasync function fetchInputFilesFromAPI(): Promise<AssetItem[]> {\n  const response = await fetch(api.internalURL('/files/input'), {\n    headers: {\n      'Comfy-User': api.user\n    }\n  })\n\n  if (!response.ok) {\n    throw new Error('Failed to fetch input files')\n  }\n\n  const filenames: string[] = await response.json()\n  return filenames.map((name, index) =>\n    mapInputFileToAssetItem(name, index, 'input')\n  )\n}\n\n/**\n * Convert history job items to asset items\n */\nfunction mapHistoryToAssets(historyItems: JobListItem[]): AssetItem[] {\n  const assetItems: AssetItem[] = []\n\n  for (const job of historyItems) {\n    // Only process completed jobs with preview output\n    if (job.status !== 'completed' || !job.preview_output) {\n      continue\n    }\n\n    const task = new TaskItemImpl(job)\n\n    if (!task.previewOutput) {\n      continue\n    }\n\n    const assetItem = mapTaskOutputToAssetItem(task, task.previewOutput)\n\n    assetItem.user_metadata = {\n      ...assetItem.user_metadata,\n      outputCount:\n        task.previewableOutputsCount ??\n        task.outputsCount ??\n        task.previewableOutputs.length,\n      allOutputs: task.previewableOutputs\n    }\n\n    assetItems.push(assetItem)\n  }\n\n  return assetItems.sort(\n    (a, b) =>\n      new Date(b.created_at).getTime() - new Date(a.created_at).getTime()\n  )\n}\n\nconst BATCH_SIZE = 200\nconst MAX_HISTORY_ITEMS = 1000 // Maximum items to keep in memory\nconst MAX_OUTPUT_LOOKUP_PAGES = 20\n\nexport const useAssetsStore = defineStore('assets', () => {\n  const assetDownloadStore = useAssetDownloadStore()\n  const modelToNodeStore = useModelToNodeStore()\n  const { flags } = useFeatureFlags()\n\n  // Track assets currently being deleted (for loading overlay)\n  const deletingAssetIds = shallowReactive(new Set<string>())\n\n  const setAssetDeleting = (assetId: string, isDeleting: boolean) => {\n    if (isDeleting) {\n      deletingAssetIds.add(assetId)\n    } else {\n      deletingAssetIds.delete(assetId)\n    }\n  }\n\n  const isAssetDeleting = (assetId: string): boolean => {\n    return deletingAssetIds.has(assetId)\n  }\n\n  const fetchInputFiles = fetchInputFilesFromAPI\n\n  const {\n    state: rawInputAssets,\n    isLoading: inputLoading,\n    execute: executeUpdateInputs\n  } = useAsyncState(fetchInputFiles, [], {\n    immediate: false,\n    resetOnExecute: false,\n    onError: (err) => {\n      console.error('Error fetching input assets:', err)\n    }\n  })\n\n  const historyInputs: PagedList<AssetItem> = {\n    hasMore: false,\n    invalidate: async () => {\n      await executeUpdateInputs()\n    },\n    isLoading: inputLoading,\n    items: rawInputAssets,\n    loadMore: async () => false,\n    loadNew: async () => undefined\n  }\n\n  function useHistoryAssets(): PagedList<AssetItem> {\n    // Pagination state\n    const historyOffset = ref(0)\n    const hasMoreHistory = ref(true)\n    const isLoadingMore = ref(false)\n    const allHistoryItems = ref<AssetItem[]>([])\n    const loadedIds = shallowReactive(new Set<string>())\n\n    /**\n     * Fetch history assets with pagination support\n     * @param loadMore - true for pagination (append), false for initial load (replace)\n     */\n    const fetchHistoryAssets = async (\n      loadMore = false\n    ): Promise<AssetItem[]> => {\n      // Reset state for initial load\n      if (!loadMore) {\n        historyOffset.value = 0\n        hasMoreHistory.value = true\n        allHistoryItems.value = []\n        loadedIds.clear()\n      }\n\n      // Fetch from server with offset\n      const history = await api.getHistory(BATCH_SIZE, {\n        offset: historyOffset.value\n      })\n\n      // Convert JobListItems to AssetItems\n      const newAssets = mapHistoryToAssets(history)\n\n      if (loadMore) {\n        // Filter out duplicates and insert in sorted order\n        for (const asset of newAssets) {\n          if (loadedIds.has(asset.id)) {\n            continue // Skip duplicates\n          }\n          loadedIds.add(asset.id)\n\n          // Find insertion index to maintain sorted order (newest first)\n          const assetTime = new Date(asset.created_at).getTime()\n          const insertIndex = allHistoryItems.value.findIndex(\n            (item) => new Date(item.created_at).getTime() < assetTime\n          )\n\n          if (insertIndex === -1) {\n            // Asset is oldest, append to end\n            allHistoryItems.value.push(asset)\n          } else {\n            // Insert at the correct position\n            allHistoryItems.value.splice(insertIndex, 0, asset)\n          }\n        }\n      } else {\n        // Initial load: replace all\n        allHistoryItems.value = newAssets\n        newAssets.forEach((asset) => loadedIds.add(asset.id))\n      }\n\n      // Update pagination state\n      historyOffset.value += BATCH_SIZE\n      hasMoreHistory.value = history.length === BATCH_SIZE\n\n      if (allHistoryItems.value.length > MAX_HISTORY_ITEMS) {\n        const removed = allHistoryItems.value.slice(MAX_HISTORY_ITEMS)\n        allHistoryItems.value = allHistoryItems.value.slice(\n          0,\n          MAX_HISTORY_ITEMS\n        )\n\n        // Clean up Set\n        removed.forEach((item) => loadedIds.delete(item.id))\n      }\n\n      return allHistoryItems.value\n    }\n\n    const historyAssets = ref<AssetItem[]>([])\n    const historyLoading = ref(false)\n    const historyError = ref<unknown>(null)\n    let historyQueue = Promise.resolve()\n    let refreshPromise: Promise<void> | undefined\n    let loadMorePromise: Promise<boolean> | undefined\n\n    /**\n     * Initial load of history assets\n     */\n    const doUpdateHistory = async () => {\n      historyLoading.value = true\n      historyError.value = null\n      try {\n        await fetchHistoryAssets(false)\n        historyAssets.value = allHistoryItems.value\n      } catch (err) {\n        console.error('Error fetching history assets:', err)\n        historyError.value = err\n        // Keep existing data when error occurs\n        if (!historyAssets.value.length) {\n          historyAssets.value = []\n        }\n      } finally {\n        historyLoading.value = false\n      }\n    }\n\n    const updateHistory = () => {\n      if (!refreshPromise) {\n        refreshPromise = historyQueue.then(doUpdateHistory).finally(() => {\n          refreshPromise = undefined\n        })\n        historyQueue = refreshPromise\n      }\n      return refreshPromise\n    }\n\n    /**\n     * Load more history items (infinite scroll)\n     */\n    const doLoadMoreHistory = async () => {\n      isLoadingMore.value = true\n      historyError.value = null\n\n      try {\n        await fetchHistoryAssets(true)\n        historyAssets.value = allHistoryItems.value\n        return true\n      } catch (err) {\n        console.error('Error loading more history:', err)\n        historyError.value = err\n        // Keep existing data when error occurs (consistent with updateHistory)\n        if (!historyAssets.value.length) {\n          historyAssets.value = []\n        }\n        return false\n      } finally {\n        isLoadingMore.value = false\n      }\n    }\n\n    const loadMoreHistory = () => {\n      if (!loadMorePromise) {\n        const operation = historyQueue.then(() =>\n          hasMoreHistory.value ? doLoadMoreHistory() : false\n        )\n        loadMorePromise = operation.finally(() => {\n          loadMorePromise = undefined\n        })\n        historyQueue = operation.then(() => undefined)\n      }\n      return loadMorePromise\n    }\n\n    return {\n      hasMore: hasMoreHistory,\n      invalidate: updateHistory,\n      isLoading: computed(() => historyLoading.value || isLoadingMore.value),\n      items: historyAssets,\n      loadMore: loadMoreHistory,\n      loadNew: updateHistory\n    }\n  }\n\n  const inputAssets = ref<PagedList<AssetItem>>(undefined!)\n  const outputAssets = ref<PagedList<AssetItem>>(undefined!)\n  let assetsScope: EffectScope | undefined\n  watch(\n    () => flags.assetsEnabled,\n    (isAssets) => {\n      if (assetsScope) assetsScope.stop()\n      assetsScope = undefined\n\n      if (isAssets) {\n        assetsScope = effectScope()\n        assetsScope.run(() => {\n          inputAssets.value = useAssetsQuery({ tags_any: ['input'] })\n          const flatAssets = useAssetsQuery({ tags_any: ['output', 'temp'] })\n          outputAssets.value = new WrappedList(\n            flatAssets,\n            unflattenOutputAssets\n          )\n        })\n      } else {\n        inputAssets.value = historyInputs\n        outputAssets.value = useHistoryAssets()\n      }\n    },\n    { immediate: true }\n  )\n\n  async function loadOutputAsset(assetId: string): Promise<boolean> {\n    const assets = outputAssets.value\n    const hasAsset = () =>\n      toValue(assets.items).some(({ id }) => id === assetId)\n\n    let pagesLoaded = 0\n    while (\n      !hasAsset() &&\n      toValue(assets.hasMore) &&\n      pagesLoaded++ < MAX_OUTPUT_LOOKUP_PAGES\n    ) {\n      if (!(await assets.loadMore())) break\n    }\n    return hasAsset()\n  }\n\n  /**\n   * Map of asset hash filename to asset item for O(1) lookup\n   * Cloud assets use hash for the hash-based filename\n   */\n  const inputAssetsByFilename = computed(() => {\n    const map = new Map<string, AssetItem>()\n    for (const asset of toValue(inputAssets.value.items)) {\n      const hash = asset.hash\n      if (hash) {\n        map.set(hash, asset)\n      }\n    }\n    return map\n  })\n\n  /**\n   * @param filename Hash-based filename (e.g., \"72e786ff...efb7.png\")\n   * @returns Human-readable asset name or original filename if not found\n   */\n  function getInputName(filename: string): string {\n    return inputAssetsByFilename.value.get(filename)?.name ?? filename\n  }\n\n  const MODEL_BATCH_SIZE = 500\n\n  // Defensive backstop against a server that never signals exhaustion (e.g.\n  // emits an unbounded stream of unique cursors). At MODEL_BATCH_SIZE per\n  // batch this caps a single walk at 500k assets — far beyond any real\n  // category — so it only ever trips on pathological pagination.\n  const MAX_PAGINATION_BATCHES = 1000\n\n  interface ModelPaginationState {\n    assets: Map<string, AssetItem>\n    /**\n     * Count of assets fetched so far. Only drives the request `offset` when\n     * the backend is cursor-less (no `next_cursor` in responses).\n     */\n    offset: number\n    /**\n     * Keyset cursor from the latest response's `next_cursor`. When set,\n     * subsequent batches resume with `after` instead of `offset`.\n     */\n    nextCursor?: string\n    hasMore: boolean\n    isLoading: boolean\n    error?: Error\n  }\n\n  /**\n   * Model assets cached by category (e.g., 'checkpoints', 'loras')\n   * Multiple node types sharing the same category share the same cache entry.\n   * Public API accepts nodeType for backwards compatibility but translates\n   * to category internally using modelToNodeStore.getCategoryForNodeType().\n   *\n   * Runs on every distribution; whether anything fetches through it is\n   * decided by consumers via `assetService.isWidgetAssetPickerEnabled()`,\n   * which hard-gates widget surfaces to cloud.\n   */\n  const getModelState = () => {\n    const modelStateByCategory = ref(new Map<string, ModelPaginationState>())\n\n    const assetsArrayCache = new Map<\n      string,\n      { source: Map<string, AssetItem>; array: AssetItem[] }\n    >()\n\n    const pendingRequestByCategory = new Map<string, ModelPaginationState>()\n    const pendingPromiseByCategory = new Map<string, Promise<void>>()\n    const abortByCategory = new Map<string, AbortController>()\n\n    function createState(\n      existingAssets?: Map<string, AssetItem>\n    ): ModelPaginationState {\n      const assets = new Map(existingAssets)\n      return reactive({\n        assets,\n        offset: 0,\n        nextCursor: undefined,\n        hasMore: true,\n        isLoading: true\n      })\n    }\n\n    function isStale(category: string, state: ModelPaginationState): boolean {\n      const committed = modelStateByCategory.value.get(category)\n      const pending = pendingRequestByCategory.get(category)\n      return committed !== state && pending !== state\n    }\n\n    const EMPTY_ASSETS: AssetItem[] = []\n\n    /**\n     * Resolve a key to a category. Handles both nodeType and tag:xxx formats.\n     * @param key Either a nodeType (e.g., 'CheckpointLoaderSimple') or tag key (e.g., 'tag:models')\n     * @returns The category or undefined if not resolvable\n     */\n    function resolveCategory(key: string): string | undefined {\n      if (key.startsWith('tag:')) {\n        return key\n      }\n      return modelToNodeStore.getCategoryForNodeType(key)\n    }\n\n    /**\n     * Get assets by nodeType or tag key.\n     * Translates nodeType to category internally for cache lookup.\n     * @param key Either a nodeType (e.g., 'CheckpointLoaderSimple') or tag key (e.g., 'tag:models')\n     */\n    function getAssets(key: string): AssetItem[] {\n      const category = resolveCategory(key)\n      if (!category) return EMPTY_ASSETS\n\n      const state = modelStateByCategory.value.get(category)\n      const assetsMap = state?.assets\n      if (!assetsMap) return EMPTY_ASSETS\n\n      const cached = assetsArrayCache.get(category)\n      if (cached && cached.source === assetsMap) {\n        return cached.array\n      }\n\n      const array = Array.from(assetsMap.values())\n      assetsArrayCache.set(category, { source: assetsMap, array })\n      return array\n    }\n\n    function isLoading(key: string): boolean {\n      const category = resolveCategory(key)\n      if (!category) return false\n      return modelStateByCategory.value.get(category)?.isLoading ?? false\n    }\n\n    function getError(key: string): Error | undefined {\n      const category = resolveCategory(key)\n      if (!category) return undefined\n      return modelStateByCategory.value.get(category)?.error\n    }\n\n    function hasMore(key: string): boolean {\n      const category = resolveCategory(key)\n      if (!category) return false\n      return modelStateByCategory.value.get(category)?.hasMore ?? false\n    }\n\n    function hasAssetKey(key: string): boolean {\n      const category = resolveCategory(key)\n      if (!category) return false\n      return modelStateByCategory.value.has(category)\n    }\n\n    /**\n     * Check if a category exists in the cache.\n     * Checks both direct category keys and tag-prefixed keys.\n     * @param category The category to check (e.g., 'checkpoints', 'loras')\n     */\n    function hasCategory(category: string): boolean {\n      return (\n        modelStateByCategory.value.has(category) ||\n        modelStateByCategory.value.has(`tag:${category}`)\n      )\n    }\n\n    /**\n     * Internal helper to fetch and cache assets for a category.\n     * Loads first batch immediately, then progressively loads remaining batches.\n     * Keeps existing data visible until new data is successfully fetched.\n     *\n     * Concurrent calls for the same category are short-circuited: if a request\n     * is already in progress (tracked via pendingRequestByCategory), subsequent\n     * calls return immediately to avoid redundant work.\n     */\n    async function updateModelsForCategory(\n      category: string,\n      fetcher: (options: AssetPaginationOptions) => Promise<AssetResponse>\n    ): Promise<void> {\n      if (pendingPromiseByCategory.has(category)) {\n        return pendingPromiseByCategory.get(category)!\n      }\n\n      const existingState = modelStateByCategory.value.get(category)\n      const state = createState(existingState?.assets)\n\n      abortByCategory.get(category)?.abort()\n      const controller = new AbortController()\n      abortByCategory.set(category, controller)\n\n      const seenIds = new Set<string>()\n\n      const hasExistingData = modelStateByCategory.value.has(category)\n      if (hasExistingData) {\n        pendingRequestByCategory.set(category, state)\n      } else {\n        // Also track in pending map for initial loads to prevent concurrent calls\n        pendingRequestByCategory.set(category, state)\n        modelStateByCategory.value.set(category, state)\n      }\n\n      async function loadBatches(): Promise<void> {\n        let isFirstBatch = true\n        // Only prune unseen cached ids when the walk reaches a genuine end\n        // of list; bailing out on an anomaly (empty page, cursor cycle,\n        // batch cap) must not delete assets we simply never re-fetched.\n        let walkCompleted = false\n        // Cursors already requested this walk. A repeat means the server is\n        // cycling (immediate A->A or alternating A->B->A...), so we stop.\n        const seenCursors = new Set<string>()\n        let batchCount = 0\n        while (state.hasMore) {\n          if (batchCount++ >= MAX_PAGINATION_BATCHES) {\n            state.hasMore = false\n            break\n          }\n          try {\n            // Keyset cursor walk when the server provides one (stable under\n            // concurrent inserts/deletes); offset walk otherwise. The first\n            // batch sends offset 0, which the service omits from the request.\n            const after = state.nextCursor\n            const response = await fetcher(\n              after !== undefined\n                ? {\n                    limit: MODEL_BATCH_SIZE,\n                    after,\n                    signal: controller.signal\n                  }\n                : {\n                    limit: MODEL_BATCH_SIZE,\n                    offset: state.offset,\n                    signal: controller.signal\n                  }\n            )\n\n            if (isStale(category, state)) return\n\n            const newAssets = response.assets\n\n            if (isFirstBatch) {\n              assetsArrayCache.delete(category)\n              if (hasExistingData) {\n                pendingRequestByCategory.delete(category)\n                modelStateByCategory.value.set(category, state)\n              }\n            }\n\n            // Merge new assets into existing map and track seen IDs\n            for (const asset of newAssets) {\n              seenIds.add(asset.id)\n              state.assets.set(asset.id, asset)\n            }\n            state.assets = new Map(state.assets)\n\n            state.offset += newAssets.length\n\n            if (!response.has_more) {\n              // Server signalled a genuine end of list — safe to prune ids\n              // that no longer exist server-side.\n              state.hasMore = false\n              walkCompleted = true\n            } else if (newAssets.length === 0) {\n              // Anomaly: server claims more but returned an empty page. Stop,\n              // but do not prune — unseen cached assets may still live on a\n              // page we never received.\n              state.hasMore = false\n            } else if (response.next_cursor !== undefined) {\n              if (seenCursors.has(response.next_cursor)) {\n                // Repeated cursor: the server is cycling. Stop without\n                // pruning rather than loop forever.\n                state.hasMore = false\n              } else {\n                seenCursors.add(response.next_cursor)\n                state.nextCursor = response.next_cursor\n              }\n            } else {\n              // Cursor-less backend: legacy offset walk. A short page is the\n              // reliable natural end of the list, so it is safe to prune.\n              state.nextCursor = undefined\n              if (newAssets.length < MODEL_BATCH_SIZE) {\n                state.hasMore = false\n                walkCompleted = true\n              }\n            }\n\n            if (isFirstBatch) {\n              state.isLoading = false\n              isFirstBatch = false\n            }\n\n            if (state.hasMore) {\n              await delay(50, { signal: controller.signal })\n            }\n          } catch (err) {\n            if (controller.signal.aborted) {\n              if (isFirstBatch) state.isLoading = false\n              return\n            }\n            if (isStale(category, state)) return\n            console.error(`Error loading batch for ${category}:`, err)\n\n            state.error = err instanceof Error ? err : new Error(String(err))\n            state.hasMore = false\n            state.isLoading = false\n            // A refresh that fails before its first batch never replaces the\n            // committed state, so mirror the error onto the state consumers\n            // actually read (getError) instead of only the discarded one.\n            const committed = modelStateByCategory.value.get(category)\n            if (committed && committed !== state) {\n              committed.error = state.error\n            }\n            if (pendingRequestByCategory.get(category) === state) {\n              pendingRequestByCategory.delete(category)\n            }\n\n            return\n          }\n        }\n\n        // Prune ids that vanished server-side, but only after a complete\n        // walk — an early bail-out hasn't seen the whole list, so unseen\n        // cached assets must be kept rather than deleted.\n        if (walkCompleted) {\n          const staleIds = [...state.assets.keys()].filter(\n            (id) => !seenIds.has(id)\n          )\n          for (const id of staleIds) {\n            state.assets.delete(id)\n          }\n        }\n        assetsArrayCache.delete(category)\n        if (pendingRequestByCategory.get(category) === state) {\n          pendingRequestByCategory.delete(category)\n        }\n      }\n\n      const promise = loadBatches()\n      pendingPromiseByCategory.set(category, promise)\n      try {\n        await promise\n      } finally {\n        // Only clear the guards if this walk still owns them — an\n        // invalidateCategory() + fresh walk can register a newer promise and\n        // controller for the same category before this teardown runs.\n        if (pendingPromiseByCategory.get(category) === promise) {\n          pendingPromiseByCategory.delete(category)\n        }\n        if (abortByCategory.get(category) === controller) {\n          abortByCategory.delete(category)\n        }\n      }\n    }\n\n    /**\n     * Fetch and cache model assets for a specific node type.\n     * Translates nodeType to category internally - multiple node types\n     * sharing the same category will share the same cache entry.\n     * @param nodeType The node type to fetch assets for (e.g., 'CheckpointLoaderSimple')\n     */\n    async function updateModelsForNodeType(nodeType: string): Promise<void> {\n      const category = modelToNodeStore.getCategoryForNodeType(nodeType)\n      if (!category) return\n\n      // Use category as cache key but fetch using nodeType for API compatibility\n      await updateModelsForCategory(category, (opts) =>\n        assetService.getAssetsPageForNodeType(nodeType, opts)\n      )\n    }\n\n    /**\n     * Fetch and cache model assets for a specific tag\n     * @param tag The tag to fetch assets for (e.g., 'models')\n     */\n    async function updateModelsForTag(tag: string): Promise<void> {\n      const category = `tag:${tag}`\n      await updateModelsForCategory(category, (opts) =>\n        assetService.getAssetsPageByTag(tag, true, opts)\n      )\n    }\n\n    /**\n     * Invalidate the cache for a specific category.\n     * Forces a refetch on next access.\n     * @param category The category to invalidate (e.g., 'checkpoints', 'loras')\n     */\n    function invalidateCategory(category: string): void {\n      abortByCategory.get(category)?.abort()\n      abortByCategory.delete(category)\n      modelStateByCategory.value.delete(category)\n      assetsArrayCache.delete(category)\n      pendingRequestByCategory.delete(category)\n      pendingPromiseByCategory.delete(category)\n    }\n\n    /**\n     * Optimistically update an asset in the cache\n     * @param assetId The asset ID to update\n     * @param updates Partial asset data to merge\n     * @param cacheKey Optional cache key to target (nodeType or 'tag:xxx')\n     */\n    function updateAssetInCache(\n      assetId: string,\n      updates: Partial<AssetItem>,\n      cacheKey?: string\n    ) {\n      const category = cacheKey ? resolveCategory(cacheKey) : undefined\n      if (cacheKey && !category) return\n\n      const categoriesToCheck = category\n        ? [category]\n        : Array.from(modelStateByCategory.value.keys())\n\n      for (const cat of categoriesToCheck) {\n        const state = modelStateByCategory.value.get(cat)\n        if (!state?.assets) continue\n\n        const existingAsset = state.assets.get(assetId)\n        if (existingAsset) {\n          const updatedAsset = { ...existingAsset, ...updates }\n          state.assets.set(assetId, updatedAsset)\n          assetsArrayCache.delete(cat)\n          if (cacheKey) return\n        }\n      }\n    }\n\n    /**\n     * Update asset metadata with optimistic cache update\n     * @param asset The asset to update\n     * @param userMetadata The user_metadata to save\n     * @param cacheKey Optional cache key to target for optimistic update\n     */\n    async function updateAssetMetadata(\n      asset: AssetItem,\n      userMetadata: Record<string, unknown>,\n      cacheKey?: string\n    ) {\n      const originalMetadata = asset.user_metadata\n      updateAssetInCache(asset.id, { user_metadata: userMetadata }, cacheKey)\n\n      try {\n        const updatedAsset = await assetService.updateAsset(asset.id, {\n          user_metadata: userMetadata\n        })\n        updateAssetInCache(asset.id, updatedAsset, cacheKey)\n      } catch (error) {\n        console.error('Failed to update asset metadata:', error)\n        updateAssetInCache(\n          asset.id,\n          { user_metadata: originalMetadata },\n          cacheKey\n        )\n      }\n    }\n\n    /**\n     * Update asset tags using add/remove endpoints\n     * @param asset The asset to update (used to read current tags)\n     * @param newTags The desired tags array\n     * @param cacheKey Optional cache key to target for optimistic update\n     */\n    async function updateAssetTags(\n      asset: AssetItem,\n      newTags: string[],\n      cacheKey?: string\n    ) {\n      const originalTags = asset.tags\n      const tagsToAdd = difference(newTags, originalTags)\n      const tagsToRemove = difference(originalTags, newTags)\n\n      if (tagsToAdd.length === 0 && tagsToRemove.length === 0) return\n\n      updateAssetInCache(asset.id, { tags: newTags }, cacheKey)\n\n      let removedTagsOnServer: string[] = []\n      try {\n        let removeResult: TagsOperationResult | undefined\n        if (tagsToRemove.length > 0) {\n          removeResult = await assetService.removeAssetTags(\n            asset.id,\n            tagsToRemove\n          )\n          removedTagsOnServer = removeResult.removed ?? tagsToRemove\n        }\n\n        const addResult =\n          tagsToAdd.length > 0\n            ? await assetService.addAssetTags(asset.id, tagsToAdd)\n            : undefined\n\n        const finalTags = (addResult ?? removeResult)?.total_tags\n        if (finalTags) {\n          updateAssetInCache(asset.id, { tags: finalTags }, cacheKey)\n        }\n      } catch (error) {\n        console.error('Failed to update asset tags:', error)\n        updateAssetInCache(asset.id, { tags: originalTags }, cacheKey)\n\n        if (removedTagsOnServer.length > 0) {\n          try {\n            await assetService.addAssetTags(asset.id, removedTagsOnServer)\n          } catch (compensationError) {\n            console.error(\n              'Failed to restore tags after partial failure; invalidating cache to force refetch:',\n              compensationError\n            )\n            const categoriesToInvalidate = new Set<string>()\n            const resolved = cacheKey ? resolveCategory(cacheKey) : undefined\n            if (resolved) {\n              categoriesToInvalidate.add(resolved)\n            }\n            for (const [\n              category,\n              state\n            ] of modelStateByCategory.value.entries()) {\n              if (state.assets.has(asset.id)) {\n                categoriesToInvalidate.add(category)\n              }\n            }\n            for (const category of categoriesToInvalidate) {\n              invalidateCategory(category)\n            }\n          }\n        }\n      }\n    }\n\n    /**\n     * Invalidate model caches for a given category (e.g., 'checkpoints', 'loras')\n     * Clears the category cache and tag-based caches so next access triggers refetch\n     * @param category The model category to invalidate (e.g., 'checkpoints')\n     */\n    function invalidateModelsForCategory(category: string): void {\n      invalidateCategory(category)\n      invalidateCategory(`tag:${category}`)\n      invalidateCategory('tag:models')\n    }\n\n    return {\n      getAssets,\n      isLoading,\n      getError,\n      hasMore,\n      hasAssetKey,\n      hasCategory,\n      updateModelsForNodeType,\n      updateModelsForTag,\n      invalidateCategory,\n      updateAssetMetadata,\n      updateAssetTags,\n      invalidateModelsForCategory\n    }\n  }\n\n  const {\n    getAssets,\n    isLoading: isModelLoading,\n    getError,\n    hasMore,\n    hasAssetKey,\n    hasCategory,\n    updateModelsForNodeType,\n    updateModelsForTag,\n    invalidateCategory,\n    updateAssetMetadata,\n    updateAssetTags,\n    invalidateModelsForCategory\n  } = getModelState()\n\n  // Watch for completed downloads and refresh model caches\n  whenever(\n    () => assetDownloadStore.lastCompletedDownload,\n    async (latestDownload) => {\n      const { modelType } = latestDownload\n\n      const providers = modelToNodeStore\n        .getAllNodeProviders(modelType)\n        .filter((provider) => provider.nodeDef.name)\n\n      const nodeTypeUpdates = providers.map((provider) =>\n        updateModelsForNodeType(provider.nodeDef.name).then(\n          () => provider.nodeDef.name\n        )\n      )\n\n      // Also update by tag in case modal was opened with assetType\n      const tagUpdates = [\n        updateModelsForTag(modelType),\n        updateModelsForTag('models')\n      ]\n\n      const results = await Promise.allSettled([\n        ...nodeTypeUpdates,\n        ...tagUpdates\n      ])\n\n      for (const result of results) {\n        if (result.status === 'rejected') {\n          console.error(\n            `Failed to refresh model cache for provider: ${result.reason}`\n          )\n        }\n      }\n    }\n  )\n\n  return {\n    // States\n    inputAssets,\n    outputAssets,\n    invalidateAll,\n    loadOutputAsset,\n\n    // Deletion tracking\n    deletingAssetIds,\n    setAssetDeleting,\n    isAssetDeleting,\n\n    // Input mapping helpers\n    inputAssetsByFilename,\n    getInputName,\n\n    // Model assets - accessors\n    getAssets,\n    isModelLoading,\n    getError,\n    hasMore,\n    hasAssetKey,\n    hasCategory,\n\n    // Model assets - actions\n    updateModelsForNodeType,\n    updateModelsForTag,\n    invalidateCategory,\n    updateAssetMetadata,\n    updateAssetTags,\n    invalidateModelsForCategory\n  }\n})\n","import axios from 'axios'\nimport { shallowReactive } from 'vue'\n\nimport { useChainCallback } from '@/composables/functional/useChainCallback'\nimport type { ComboWidgetInventoryStatus } from '@/core/graph/widgets/comboWidgetInventory'\nimport type { IWidget, LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { isCloud } from '@/platform/distribution/types'\nimport type { RemoteWidgetConfig } from '@/schemas/nodeDefSchema'\nimport { api } from '@/scripts/api'\nimport { useAuthStore } from '@/stores/authStore'\n\nconst MAX_RETRIES = 5\nconst TIMEOUT = 4096\n\ninterface CacheEntry<T> {\n  data: T\n  timestamp?: number\n  error?: Error | null\n  fetchPromise?: Promise<T>\n  controller?: AbortController\n  lastErrorTime?: number\n  retryCount?: number\n  failed?: boolean\n}\n\nasync function getAuthHeaders() {\n  if (isCloud) {\n    const authStore = useAuthStore()\n    const authHeader = await authStore.getAuthHeader()\n    return {\n      ...(authHeader && { headers: authHeader })\n    }\n  }\n  return {}\n}\n\nconst dataCache = shallowReactive(new Map<string, CacheEntry<unknown>>())\n\nconst createCacheKey = (config: RemoteWidgetConfig): string => {\n  const { route, query_params = {}, refresh = 0 } = config\n\n  const paramsKey = Object.entries(query_params)\n    .sort(([a], [b]) => a.localeCompare(b))\n    .map(([k, v]) => `${k}=${v}`)\n    .join('&')\n\n  return [route, `r=${refresh}`, paramsKey].join(';')\n}\n\nconst getBackoff = (retryCount: number) =>\n  Math.min(1000 * Math.pow(2, retryCount), 512)\n\nconst isInitialized = (entry: CacheEntry<unknown> | undefined) =>\n  entry?.data !== undefined &&\n  entry.timestamp !== undefined &&\n  entry.timestamp > 0\n\nconst isStale = (entry: CacheEntry<unknown> | undefined, ttl: number) =>\n  entry?.timestamp && Date.now() - entry.timestamp >= ttl\n\nconst isFetching = (entry: CacheEntry<unknown> | undefined) =>\n  entry?.fetchPromise !== undefined\n\nconst isFailed = (entry: CacheEntry<unknown> | undefined) =>\n  entry?.failed === true\n\nconst isBackingOff = (entry: CacheEntry<unknown> | undefined) =>\n  entry?.error &&\n  entry.lastErrorTime &&\n  Date.now() - entry.lastErrorTime < getBackoff(entry.retryCount || 0)\n\nclass RemoteWidgetRequestError extends Error {}\n\nconst isSameOrigin = (route: string) =>\n  new URL(route, location.href).origin === location.origin\n\nconst withQuery = (\n  route: string,\n  params: RemoteWidgetConfig['query_params']\n) => {\n  const query = new URLSearchParams(params).toString()\n  if (!query) return route\n  return `${route}${route.includes('?') ? '&' : '?'}${query}`\n}\n\nconst parseBody = (text: string): unknown => {\n  try {\n    return JSON.parse(text)\n  } catch {\n    return text\n  }\n}\n\nconst pickKey = (data: unknown, key: string | undefined) => {\n  if (!key) return data\n  return typeof data === 'object' && data !== null\n    ? Reflect.get(data, key)\n    : undefined\n}\n\nconst fetchOnSession = async (\n  config: RemoteWidgetConfig,\n  controller: AbortController\n): Promise<{ data: unknown } | undefined> => {\n  const { route, query_params, timeout = TIMEOUT } = config\n  if (!isSameOrigin(route)) return undefined\n\n  const timeoutController = new AbortController()\n  const timer =\n    timeout > 0 ? setTimeout(() => timeoutController.abort(), timeout) : 0\n  try {\n    const res = await api.fetchOnWebSession(withQuery(route, query_params), {\n      method: 'GET',\n      signal: AbortSignal.any([controller.signal, timeoutController.signal])\n    })\n    if (!res) return undefined\n    if (!res.ok) {\n      throw new RemoteWidgetRequestError(\n        `Request failed with status ${res.status}`\n      )\n    }\n    return { data: parseBody(await res.text()) }\n  } finally {\n    clearTimeout(timer)\n  }\n}\n\nconst fetchData = async (\n  config: RemoteWidgetConfig,\n  controller: AbortController\n) => {\n  const { route, response_key, query_params, timeout = TIMEOUT } = config\n\n  const sessionRes = await fetchOnSession(config, controller)\n  if (sessionRes) return pickKey(sessionRes.data, response_key)\n\n  const authHeaders = await getAuthHeaders()\n\n  const res = await axios.get(route, {\n    params: query_params,\n    signal: controller.signal,\n    timeout,\n    ...authHeaders\n  })\n\n  return response_key ? res.data[response_key] : res.data\n}\n\nexport function useRemoteWidget<\n  T extends string | number | boolean | object\n>(options: {\n  remoteConfig: RemoteWidgetConfig\n  defaultValue: T\n  node: LGraphNode\n  widget: IWidget\n}) {\n  const { remoteConfig, defaultValue, node, widget } = options\n  const { refresh = 0, max_retries = MAX_RETRIES } = remoteConfig\n  const isPermanent = refresh <= 0\n  const cacheKey = createCacheKey(remoteConfig)\n  let isLoaded = false\n  let refreshQueued = false\n  let removed = false\n\n  const setSuccess = (entry: CacheEntry<T>, data: T) => {\n    entry.retryCount = 0\n    entry.lastErrorTime = 0\n    entry.error = null\n    entry.timestamp = Date.now()\n    entry.data = data\n  }\n\n  const setError = (entry: CacheEntry<T>, error: unknown) => {\n    entry.retryCount = (entry.retryCount || 0) + 1\n    entry.lastErrorTime = Date.now()\n    entry.error = error instanceof Error ? error : new Error(String(error))\n    entry.fetchPromise = undefined\n    if (entry.retryCount >= max_retries) {\n      setFailed(entry)\n    }\n  }\n\n  const setFailed = (entry: CacheEntry<T>) => {\n    dataCache.set(cacheKey, {\n      data: entry.data,\n      failed: true\n    })\n  }\n\n  const isFirstLoad = () => {\n    return !isLoaded && isInitialized(dataCache.get(cacheKey))\n  }\n\n  const onFirstLoad = (data: T | T[]) => {\n    isLoaded = true\n    const nextValue = Array.isArray(data)\n      ? (data.find((value) => value === widget.value) ?? data[0])\n      : undefined\n    widget.value = nextValue ?? (Array.isArray(data) ? defaultValue : data)\n    widget.callback?.(widget.value)\n    node.graph?.setDirtyCanvas(true)\n  }\n\n  const fetchValue = async () => {\n    const entry = dataCache.get(cacheKey)\n\n    if (isFailed(entry)) return entry!.data as T\n\n    const isValid =\n      isInitialized(entry) && (isPermanent || !isStale(entry, refresh))\n    if (isValid || isBackingOff(entry) || isFetching(entry))\n      return entry!.data as T\n\n    const currentEntry: CacheEntry<T> = shallowReactive(\n      (entry as CacheEntry<T> | undefined) || { data: defaultValue }\n    )\n    dataCache.set(cacheKey, currentEntry)\n\n    try {\n      currentEntry.controller = new AbortController()\n      currentEntry.fetchPromise = fetchData(\n        remoteConfig,\n        currentEntry.controller\n      )\n      const data = await currentEntry.fetchPromise\n\n      setSuccess(currentEntry, data)\n      return currentEntry.data\n    } catch (err) {\n      setError(currentEntry, err)\n      return currentEntry.data\n    } finally {\n      currentEntry.fetchPromise = undefined\n      currentEntry.controller = undefined\n    }\n  }\n\n  const onRefresh = () => {\n    if (remoteConfig.control_after_refresh) {\n      const data = getCachedValue()\n      if (!Array.isArray(data)) return // control_after_refresh is only supported for array values\n\n      switch (remoteConfig.control_after_refresh) {\n        case 'first':\n          widget.value = data[0] ?? defaultValue\n          break\n        case 'last':\n          widget.value = data.at(-1) ?? defaultValue\n          break\n      }\n      widget.callback?.(widget.value)\n      node.graph?.setDirtyCanvas(true)\n    }\n  }\n\n  /**\n   * Clear the widget's cached value, forcing a refresh on next access (e.g., a new render)\n   */\n  const clearCachedValue = () => {\n    const entry = dataCache.get(cacheKey)\n    if (!entry) return\n    if (entry.fetchPromise) entry.controller?.abort() // Abort in-flight request\n    dataCache.delete(cacheKey)\n  }\n\n  /**\n   * Get the cached value of the widget without starting a new fetch.\n   * @returns the most recently computed value of the widget.\n   */\n  function getCachedValue() {\n    return dataCache.get(cacheKey)?.data as T\n  }\n\n  function getInventoryStatus(): ComboWidgetInventoryStatus {\n    const entry = dataCache.get(cacheKey)\n    const isFresh =\n      isInitialized(entry) && (isPermanent || !isStale(entry, refresh))\n    if (isFresh) return isLoaded ? 'ready' : 'loading'\n    if (isFetching(entry)) return 'loading'\n    if (isFailed(entry) || entry?.error) return 'error'\n    return 'loading'\n  }\n\n  async function waitForInventory(signal?: AbortSignal): Promise<void> {\n    while (!signal?.aborted) {\n      const inFlight = dataCache.get(cacheKey)?.fetchPromise\n      if (inFlight) {\n        await inFlight.catch(() => undefined)\n        continue\n      }\n      await new Promise<void>((resolve) => getValue(resolve))\n      if (!dataCache.get(cacheKey)?.fetchPromise) return\n    }\n  }\n\n  /**\n   * Getter of the remote property of the widget (e.g., options.values, value, etc.).\n   * Starts the fetch process then returns the cached value immediately.\n   * @returns the most recent value of the widget.\n   */\n  function getValue(onFulfilled?: () => void) {\n    void fetchValue()\n      .then((data) => {\n        if (removed) return\n        if (isFirstLoad()) onFirstLoad(data)\n        if (refreshQueued && data !== defaultValue) {\n          onRefresh()\n          refreshQueued = false\n        }\n      })\n      .finally(() => onFulfilled?.())\n      .catch((err) => {\n        console.error(err)\n      })\n    return getCachedValue()\n  }\n\n  /**\n   * Force the widget to refresh its value\n   */\n  widget.refresh = function () {\n    refreshQueued = true\n    clearCachedValue()\n    getValue()\n  }\n\n  /**\n   * Add a refresh button to the node that, when clicked, will force the widget to refresh\n   */\n  function addRefreshButton() {\n    node.addWidget('button', 'refresh', 'refresh', widget.refresh)\n  }\n\n  /**\n   * Add auto-refresh toggle widget and execution success listener\n   */\n  function addAutoRefreshToggle() {\n    let autoRefreshEnabled = false\n\n    // Handler for execution success\n    const handleExecutionSuccess = () => {\n      if (autoRefreshEnabled && widget.refresh) {\n        widget.refresh()\n      }\n    }\n\n    // Add toggle widget\n    const autoRefreshWidget = node.addWidget(\n      'toggle',\n      'Auto-refresh after generation',\n      false,\n      (value: boolean) => {\n        autoRefreshEnabled = value\n      },\n      {\n        serialize: false\n      }\n    )\n\n    // Register event listener\n    api.addEventListener('execution_success', handleExecutionSuccess)\n\n    const cleanup = () => {\n      api.removeEventListener('execution_success', handleExecutionSuccess)\n    }\n    widget.onRemove = useChainCallback(widget.onRemove, () => {\n      removed = true\n      cleanup()\n    })\n    node.onRemoved = useChainCallback(node.onRemoved, cleanup)\n\n    return autoRefreshWidget\n  }\n\n  // Always add auto-refresh toggle for remote widgets\n  addAutoRefreshToggle()\n\n  return {\n    getCachedValue,\n    getValue,\n    refreshValue: widget.refresh,\n    addRefreshButton,\n    getCacheEntry: () => dataCache.get(cacheKey),\n    getInventoryStatus,\n    waitForInventory,\n\n    cacheKey\n  }\n}\n","import { ref, toValue } from 'vue'\n\nimport MultiSelectWidget from '@/components/graph/widgets/MultiSelectWidget.vue'\nimport { registerComboWidgetInventory } from '@/core/graph/widgets/comboWidgetInventory'\nimport { t } from '@/i18n'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { isComboWidget } from '@/lib/litegraph/src/litegraph'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport { assetService } from '@/platform/assets/services/assetService'\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport { getAssetFilename } from '@/platform/assets/utils/assetMetadataUtils'\nimport { createAssetWidget } from '@/platform/assets/utils/createAssetWidget'\nimport { isCloud } from '@/platform/distribution/types'\nimport type {\n  ComboInputSpec,\n  InputSpec\n} from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport { isComboInputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport { transformInputSpecV2ToV1 } from '@/schemas/nodeDef/migration'\nimport { ComponentWidgetImpl, addWidget } from '@/scripts/domWidget'\nimport type { BaseDOMWidget } from '@/scripts/domWidget'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\nimport { addValueControlWidgets } from '@/core/graph/widgets/valueControlWidgets'\nimport { useAssetsStore } from '@/stores/assetsStore'\nimport { getMediaTypeFromFilename } from '@/utils/formatUtil'\n\nimport { useRemoteWidget } from './useRemoteWidget'\n\nconst getDefaultValue = (inputSpec: ComboInputSpec) => {\n  if (inputSpec.default) return inputSpec.default\n  if (inputSpec.options?.length) return inputSpec.options[0]\n  if (inputSpec.remote) return 'Loading...'\n  return undefined\n}\n\n// Map node types to expected media types\nconst NODE_MEDIA_TYPE_MAP: Partial<\n  Record<string, 'image' | 'video' | 'audio'>\n> = {\n  LoadImage: 'image',\n  LoadVideo: 'video',\n  LoadAudio: 'audio'\n}\n\n// Map node types to placeholder i18n keys\nconst NODE_PLACEHOLDER_MAP: Record<string, string> = {\n  LoadImage: 'widgets.uploadSelect.placeholderImage',\n  LoadVideo: 'widgets.uploadSelect.placeholderVideo',\n  LoadAudio: 'widgets.uploadSelect.placeholderAudio'\n}\n\nconst bindDynamicValuesOption = (\n  widget: IBaseWidget,\n  getValues: () => unknown\n) => {\n  const options = widget.options\n  let fallbackValues = Array.isArray(options.values)\n    ? options.values\n    : ([] as unknown[])\n\n  Object.defineProperty(options, 'values', {\n    configurable: true,\n    enumerable: true,\n    get: () => {\n      const values = getValues()\n      if (values === undefined || values === null) return fallbackValues\n      return values\n    },\n    set: (values: unknown[]) => {\n      fallbackValues = Array.isArray(values) ? values : fallbackValues\n    }\n  })\n}\n\nconst addMultiSelectWidget = (\n  node: LGraphNode,\n  inputSpec: ComboInputSpec\n): IBaseWidget => {\n  const widgetValue = ref<string[]>([])\n  const widget = new ComponentWidgetImpl({\n    node,\n    name: inputSpec.name,\n    component: MultiSelectWidget,\n    inputSpec,\n    options: {\n      getValue: () => widgetValue.value,\n      setValue: (value: string[]) => {\n        widgetValue.value = value\n      }\n    }\n  })\n  addWidget(node, widget as BaseDOMWidget)\n  // TODO: Add remote support to multi-select widget\n  // https://github.com/Comfy-Org/ComfyUI_frontend/issues/3003\n  if (inputSpec.control_after_generate) {\n    const defaultType =\n      typeof inputSpec.control_after_generate === 'string'\n        ? inputSpec.control_after_generate\n        : 'fixed'\n    widget.linkedWidgets = addValueControlWidgets(\n      node,\n      widget,\n      defaultType,\n      undefined,\n      transformInputSpecV2ToV1(inputSpec)\n    )\n  }\n\n  return widget\n}\n\n/**\n * Resolve the default value for a cloud asset widget.\n * Priority: inputSpec.default (if present in cloud assets) → first cloud\n * asset → undefined (shows placeholder).\n */\nfunction resolveCloudDefault(\n  nodeType: string,\n  specDefault: string | undefined\n): string | undefined {\n  const assets = useAssetsStore().getAssets(nodeType)\n  if (specDefault != null) {\n    const inAssets = assets.some((a) => getAssetFilename(a) === specDefault)\n    if (inAssets) return specDefault\n  }\n  // empty filename → undefined (shows placeholder)\n  const filename = assets.length ? getAssetFilename(assets[0]) : undefined\n  return filename || undefined\n}\n\nfunction getCloudInputAssets(nodeType: string | undefined): AssetItem[] {\n  const mediaType = NODE_MEDIA_TYPE_MAP[nodeType ?? '']\n  if (!mediaType) return []\n\n  return toValue(useAssetsStore().inputAssets.items).filter(\n    (asset) =>\n      getCloudInputAssetValue(asset) &&\n      getMediaTypeFromFilename(asset.name) === mediaType\n  )\n}\n\nfunction getCloudInputAssetValue(asset: AssetItem): string | undefined {\n  return asset.hash ?? undefined\n}\n\nfunction getCloudInputAssetValues(nodeType: string | undefined): string[] {\n  return getCloudInputAssets(nodeType)\n    .map(getCloudInputAssetValue)\n    .filter((value): value is string => !!value)\n}\n\nfunction resolveCloudInputDefault(\n  nodeType: string | undefined,\n  specDefault: string | undefined\n): string | undefined {\n  const assets = getCloudInputAssets(nodeType)\n  if (specDefault != null) {\n    const matchingAsset =\n      assets.find((asset) => getCloudInputAssetValue(asset) === specDefault) ??\n      assets.find((asset) => asset.name === specDefault)\n    if (matchingAsset) return getCloudInputAssetValue(matchingAsset)\n  }\n\n  return assets[0] ? getCloudInputAssetValue(assets[0]) : undefined\n}\n\nfunction createAssetBrowserWidget(\n  node: LGraphNode,\n  inputSpec: ComboInputSpec,\n  defaultValue: string | undefined\n): IBaseWidget {\n  return createAssetWidget({\n    node,\n    widgetName: inputSpec.name,\n    nodeTypeForBrowser: node.comfyClass ?? '',\n    inputNameForBrowser: inputSpec.name,\n    defaultValue\n  })\n}\n\nconst createInputMappingWidget = (\n  node: LGraphNode,\n  inputSpec: ComboInputSpec,\n  defaultValue: string | undefined\n): IBaseWidget => {\n  const assetsStore = useAssetsStore()\n\n  const widget = node.addWidget(\n    'combo',\n    inputSpec.name,\n    defaultValue ?? '',\n    () => {},\n    {\n      values: [],\n      getOptionLabel: (value?: string | null) => {\n        if (!value) {\n          const placeholderKey =\n            NODE_PLACEHOLDER_MAP[node.comfyClass ?? ''] ??\n            'widgets.uploadSelect.placeholder'\n          return t(placeholderKey)\n        }\n        return assetsStore.getInputName(value)\n      }\n    }\n  )\n\n  async function loadAll() {\n    while (toValue(assetsStore.inputAssets.hasMore)) {\n      if (!(await assetsStore.inputAssets.loadMore())) break\n      node.setDirtyCanvas(true, false)\n    }\n  }\n  void loadAll()\n\n  bindDynamicValuesOption(widget, () =>\n    getCloudInputAssetValues(node.comfyClass)\n  )\n\n  if (inputSpec.control_after_generate) {\n    if (!isComboWidget(widget)) {\n      throw new Error(`Expected combo widget but received ${widget.type}`)\n    }\n    const defaultType =\n      typeof inputSpec.control_after_generate === 'string'\n        ? inputSpec.control_after_generate\n        : 'randomize'\n    widget.linkedWidgets = addValueControlWidgets(\n      node,\n      widget,\n      defaultType,\n      undefined,\n      transformInputSpecV2ToV1(inputSpec)\n    )\n  }\n\n  return widget\n}\n\nconst addComboWidget = (\n  node: LGraphNode,\n  inputSpec: ComboInputSpec\n): IBaseWidget => {\n  const defaultValue = getDefaultValue(inputSpec)\n\n  if (isCloud) {\n    if (\n      assetService.shouldUseWidgetAssetPicker(node.comfyClass, inputSpec.name)\n    ) {\n      // Default from cloud assets, not from server combo options.\n      // Server options list local files that may not exist in the user's\n      // cloud asset library, leading to missing-model errors on undo/reload.\n      const cloudDefault = resolveCloudDefault(\n        node.comfyClass ?? '',\n        inputSpec.default\n      )\n      return createAssetBrowserWidget(node, inputSpec, cloudDefault)\n    }\n\n    if (NODE_MEDIA_TYPE_MAP[node.comfyClass ?? '']) {\n      return createInputMappingWidget(\n        node,\n        inputSpec,\n        resolveCloudInputDefault(node.comfyClass, inputSpec.default)\n      )\n    }\n  }\n\n  // Standard combo widget\n  const widget = node.addWidget(\n    'combo',\n    inputSpec.name,\n    defaultValue,\n    () => {},\n    {\n      values: inputSpec.options ?? []\n    }\n  )\n\n  if (inputSpec.remote) {\n    if (!isComboWidget(widget)) {\n      throw new Error(`Expected combo widget but received ${widget.type}`)\n    }\n\n    const remoteWidget = useRemoteWidget({\n      remoteConfig: inputSpec.remote,\n      defaultValue,\n      node,\n      widget\n    })\n    if (inputSpec.remote.refresh_button) remoteWidget.addRefreshButton()\n\n    registerComboWidgetInventory(widget, {\n      getStatus: remoteWidget.getInventoryStatus,\n      waitForSettled: remoteWidget.waitForInventory\n    })\n    bindDynamicValuesOption(widget, () => remoteWidget.getValue())\n  }\n\n  if (inputSpec.control_after_generate) {\n    if (!isComboWidget(widget)) {\n      throw new Error(`Expected combo widget but received ${widget.type}`)\n    }\n\n    const defaultType =\n      typeof inputSpec.control_after_generate === 'string'\n        ? inputSpec.control_after_generate\n        : 'randomize'\n    widget.linkedWidgets = addValueControlWidgets(\n      node,\n      widget,\n      defaultType,\n      undefined,\n      transformInputSpecV2ToV1(inputSpec)\n    )\n  }\n\n  return widget\n}\n\nexport const useComboWidget = () => {\n  const widgetConstructor: ComfyWidgetConstructorV2 = (\n    node: LGraphNode,\n    inputSpec: InputSpec\n  ) => {\n    if (!isComboInputSpec(inputSpec)) {\n      throw new Error(`Invalid input data: ${inputSpec}`)\n    }\n    return inputSpec.multi_select\n      ? addMultiSelectWidget(node, inputSpec)\n      : addComboWidget(node, inputSpec)\n  }\n\n  return widgetConstructor\n}\n","import type { CompositorLayerState } from '@/renderer/extensions/compositor/composables/compositorLayerState'\n\nexport type CompositorWidgetValue = Partial<CompositorLayerState>\n\nexport function emptyCompositorWidgetValue(): CompositorWidgetValue {\n  return {}\n}\n\nexport function isCompositorWidgetValue(\n  value: unknown\n): value is CompositorWidgetValue {\n  return typeof value === 'object' && value !== null && !Array.isArray(value)\n}\n","import {\n  emptyCompositorWidgetValue,\n  isCompositorWidgetValue\n} from '@/renderer/extensions/compositor/components/types'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { ICompositorWidget } from '@/lib/litegraph/src/types/widgets'\nimport type { InputSpec as InputSpecV2 } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\n\nexport const useCompositorWidget = (): ComfyWidgetConstructorV2 => {\n  return (node: LGraphNode, inputSpec: InputSpecV2): ICompositorWidget => {\n    const defaultValue = isCompositorWidgetValue(inputSpec.default)\n      ? inputSpec.default\n      : emptyCompositorWidgetValue()\n\n    const rawWidget = node.addWidget(\n      'compositor',\n      inputSpec.name,\n      defaultValue,\n      null\n    )\n\n    if (rawWidget.type !== 'compositor') {\n      throw new Error(`Unexpected widget type: ${rawWidget.type}`)\n    }\n\n    return rawWidget as ICompositorWidget\n  }\n}\n","import { clamp } from 'es-toolkit/compat'\n\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { INumericWidget } from '@/lib/litegraph/src/types/widgets'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { isFloatInputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { InputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\nimport { addValueControlWidget } from '@/core/graph/widgets/valueControlWidgets'\nimport { transformInputSpecV2ToV1 } from '@/schemas/nodeDef/migration'\n\nfunction onFloatValueChange(this: INumericWidget, v: number) {\n  const round = this.options.round\n  if (round) {\n    const precision =\n      this.options.precision ?? Math.max(0, -Math.floor(Math.log10(round)))\n    const rounded = Math.round(v / round) * round\n    this.value = clamp(\n      Number(rounded.toFixed(precision)),\n      this.options.min ?? -Infinity,\n      this.options.max ?? Infinity\n    )\n  } else {\n    this.value = v\n  }\n}\n\nexport const _for_testing = {\n  onFloatValueChange\n}\n\nexport const useFloatWidget = () => {\n  const widgetConstructor: ComfyWidgetConstructorV2 = (\n    node: LGraphNode,\n    inputSpec: InputSpec\n  ) => {\n    if (!isFloatInputSpec(inputSpec)) {\n      throw new Error(`Invalid input data: ${inputSpec}`)\n    }\n\n    const settingStore = useSettingStore()\n    const sliderEnabled = !settingStore.get('Comfy.DisableSliders')\n\n    const display_type = inputSpec.display\n    const widgetType =\n      display_type == 'gradientslider'\n        ? 'gradientslider'\n        : sliderEnabled && display_type == 'slider'\n          ? 'slider'\n          : display_type == 'knob'\n            ? 'knob'\n            : 'number'\n\n    const step = inputSpec.step ?? 0.5\n    const precision =\n      settingStore.get('Comfy.FloatRoundingPrecision') ||\n      Math.max(0, -Math.floor(Math.log10(step)))\n    const enableRounding = !settingStore.get('Comfy.DisableFloatRounding')\n\n    /** Assertion {@link inputSpec.default} */\n    const defaultValue = (inputSpec.default as number | undefined) ?? 0\n    const widget = node.addWidget(\n      widgetType,\n      inputSpec.name,\n      defaultValue,\n      onFloatValueChange,\n      {\n        min: inputSpec.min ?? 0,\n        max: inputSpec.max ?? 2048,\n        round:\n          enableRounding && precision && !inputSpec.round\n            ? Math.pow(10, -precision)\n            : (inputSpec.round as number),\n        /** @deprecated Use step2 instead. The 10x value is a legacy implementation. */\n        step: step * 10.0,\n        step2: step,\n        precision,\n        ...(inputSpec.gradient_stops\n          ? { gradient_stops: inputSpec.gradient_stops }\n          : {})\n      }\n    )\n\n    if (inputSpec.control_after_generate) {\n      const controlWidget = addValueControlWidget(\n        node,\n        widget,\n        'fixed',\n        undefined,\n        undefined,\n        transformInputSpecV2ToV1(inputSpec)\n      )\n      widget.linkedWidgets = [controlWidget]\n    }\n\n    return widget\n  }\n\n  return widgetConstructor\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { IGalleriaWidget } from '@/lib/litegraph/src/types/widgets'\nimport { isGalleriaInputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type {\n  GalleriaInputSpec,\n  InputSpec as InputSpecV2\n} from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\n\nexport const useGalleriaWidget = (): ComfyWidgetConstructorV2 => {\n  return (node: LGraphNode, inputSpec: InputSpecV2): IGalleriaWidget => {\n    if (!isGalleriaInputSpec(inputSpec)) {\n      console.error('Invalid input spec for galleria widget')\n    }\n\n    const galleriaSpec = inputSpec as GalleriaInputSpec\n    const { name } = galleriaSpec\n    const images = galleriaSpec.images ?? galleriaSpec.options?.images ?? []\n\n    const widget = node.addWidget('galleria', name, images, () => {}, {\n      serialize: true\n    }) as IGalleriaWidget\n\n    return widget\n  }\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport type {\n  BoundingBoxesInputSpec,\n  InputSpec as InputSpecV2\n} from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\nimport type { BoundingBox } from '@/types/boundingBoxes'\n\nexport const useBoundingBoxesWidget = (): ComfyWidgetConstructorV2 => {\n  return (node: LGraphNode, inputSpec: InputSpecV2): IBaseWidget => {\n    const spec = inputSpec as BoundingBoxesInputSpec\n    const defaultValue: BoundingBox[] =\n      spec.default?.map((box) => ({\n        ...box,\n        metadata: { ...box.metadata, palette: [...box.metadata.palette] }\n      })) ?? []\n    return node.addWidget('boundingboxes', spec.name, defaultValue, null, {\n      serialize: true,\n      hideInPanel: true\n    })\n  }\n}\n","import type {\n  LightInfoEntry,\n  LightInfoType,\n  LightInfoVec3\n} from '@/types/lightInfo'\n\nexport type { LightInfoEntry, LightInfoType }\nexport type Vec3 = LightInfoVec3\n\nexport const LIGHT_TYPES: readonly LightInfoType[] = [\n  'directional',\n  'point',\n  'spot'\n]\n\nexport const LIGHT_TYPE_LABEL_KEYS: Record<LightInfoType, string> = {\n  directional: 'lightInfo.directional',\n  point: 'lightInfo.point',\n  spot: 'lightInfo.spot'\n}\n\nexport function createDefaultLight(type: LightInfoType): LightInfoEntry {\n  if (type === 'point') {\n    return {\n      type,\n      color: '#ffffff',\n      intensity: 25,\n      position: { x: 1.2, y: 2, z: 1.2 },\n      radius: 0.1\n    }\n  }\n  if (type === 'spot') {\n    return {\n      type,\n      color: '#ffffff',\n      intensity: 25,\n      position: { x: 1.2, y: 2, z: 1.2 },\n      target: { x: 0, y: 0, z: 0 },\n      innerConeAngle: 30,\n      outerConeAngle: 45,\n      radius: 0.1\n    }\n  }\n  return {\n    type: 'directional',\n    color: '#ffffff',\n    intensity: 1.5,\n    position: { x: 0, y: 1.8, z: 1.8 },\n    target: { x: 0, y: 0, z: 0 },\n    radius: 0.5\n  }\n}\n\nfunction cloneLight(light: LightInfoEntry): LightInfoEntry {\n  return {\n    ...light,\n    position: { ...light.position },\n    ...(light.target ? { target: { ...light.target } } : {})\n  }\n}\n\nexport function cloneLights(lights: LightInfoEntry[]): LightInfoEntry[] {\n  return lights.map(cloneLight)\n}\n\nexport function lightTarget(light: LightInfoEntry): Vec3 {\n  return light.target ?? { x: 0, y: 0, z: 0 }\n}\n","import { clamp } from 'es-toolkit'\n\nimport { LIGHT_TYPES, createDefaultLight } from './types'\nimport type { LightInfoEntry, LightInfoType, Vec3 } from './types'\n\nconst MIN_OUTER_CONE_ANGLE = 1\nconst MAX_CONE_ANGLE = 90\n\nfunction isLightType(value: unknown): value is LightInfoType {\n  return (\n    typeof value === 'string' &&\n    (LIGHT_TYPES as readonly string[]).includes(value)\n  )\n}\n\nfunction toVec3(value: unknown, fallback: Vec3): Vec3 {\n  const v = value as Partial<Vec3> | null | undefined\n  const num = (n: unknown, d: number) =>\n    typeof n === 'number' && Number.isFinite(n) ? n : d\n  return {\n    x: num(v?.x, fallback.x),\n    y: num(v?.y, fallback.y),\n    z: num(v?.z, fallback.z)\n  }\n}\n\nfunction toFinite(value: unknown, fallback: number): number {\n  return typeof value === 'number' && Number.isFinite(value) ? value : fallback\n}\n\nconst HEX_COLOR = /^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/\n\nfunction toColor(value: unknown, fallback: string): string {\n  return typeof value === 'string' && HEX_COLOR.test(value) ? value : fallback\n}\n\nfunction coneAngles(\n  raw: Record<string, unknown>,\n  defaults: LightInfoEntry\n): Pick<LightInfoEntry, 'innerConeAngle' | 'outerConeAngle'> {\n  const outer = clamp(\n    toFinite(raw.outerConeAngle, defaults.outerConeAngle ?? 45),\n    MIN_OUTER_CONE_ANGLE,\n    MAX_CONE_ANGLE\n  )\n  const inner = clamp(\n    toFinite(raw.innerConeAngle, defaults.innerConeAngle ?? 30),\n    0,\n    outer\n  )\n  return { innerConeAngle: inner, outerConeAngle: outer }\n}\n\nfunction typeSpecificFields(\n  raw: Record<string, unknown>,\n  defaults: LightInfoEntry\n): Partial<LightInfoEntry> {\n  const range = toFinite(raw.range, 0)\n  return {\n    ...(defaults.type !== 'point' && {\n      target: toVec3(raw.target, defaults.target ?? { x: 0, y: 0, z: 0 })\n    }),\n    ...(defaults.type !== 'directional' && range > 0 && { range }),\n    ...(defaults.type === 'spot' && coneAngles(raw, defaults))\n  }\n}\n\nfunction normalizeLight(value: unknown): LightInfoEntry | null {\n  if (typeof value !== 'object' || value === null) return null\n  const raw = value as Record<string, unknown>\n  if (!isLightType(raw.type)) return null\n  const defaults = createDefaultLight(raw.type)\n  return {\n    type: raw.type,\n    color: toColor(raw.color, defaults.color),\n    intensity: Math.max(0, toFinite(raw.intensity, defaults.intensity)),\n    position: toVec3(raw.position, defaults.position),\n    ...typeSpecificFields(raw, defaults),\n    radius: Math.max(0, toFinite(raw.radius, defaults.radius ?? 0)),\n    ...(raw.castShadow === false && { castShadow: false })\n  }\n}\n\nexport function normalizeLightsValue(value: unknown): LightInfoEntry[] {\n  if (!Array.isArray(value)) return []\n  return value\n    .map(normalizeLight)\n    .filter((light): light is LightInfoEntry => light !== null)\n}\n","import { normalizeLightsValue } from '@/extensions/core/lightInfo/lightsValue'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport type { InputSpec as InputSpecV2 } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\n\nexport const useLightInfoWidget = (): ComfyWidgetConstructorV2 => {\n  return (node: LGraphNode, inputSpec: InputSpecV2): IBaseWidget => {\n    return node.addWidget(\n      'lightinfo',\n      inputSpec.name,\n      normalizeLightsValue(inputSpec.default),\n      null,\n      { serialize: true, hideInPanel: true }\n    )\n  }\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport type {\n  ColorsInputSpec,\n  InputSpec as InputSpecV2\n} from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\n\nexport const useColorsWidget = (): ComfyWidgetConstructorV2 => {\n  return (node: LGraphNode, inputSpec: InputSpecV2): IBaseWidget => {\n    const spec = inputSpec as ColorsInputSpec\n    const defaultValue: string[] = spec.default ? [...spec.default] : []\n    return node.addWidget('colors', spec.name, defaultValue, null)\n  }\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { IImageCompareWidget } from '@/lib/litegraph/src/types/widgets'\nimport type {\n  ImageCompareInputSpec,\n  InputSpec as InputSpecV2\n} from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\n\nexport const useImageCompareWidget = (): ComfyWidgetConstructorV2 => {\n  return (node: LGraphNode, inputSpec: InputSpecV2): IImageCompareWidget => {\n    const { name, options = {} } = inputSpec as ImageCompareInputSpec\n\n    const widget = node.addWidget('imagecompare', name, ['', ''], () => {}, {\n      serialize: true,\n      ...options\n    }) as IImageCompareWidget\n\n    // widget.serialize controls workflow persistence; widget.options.serialize\n    // controls prompt (API) serialization — only disable the former.\n    widget.serialize = false\n\n    return widget\n  }\n}\n","import type { InjectionKey, Ref } from 'vue'\nimport { z } from 'zod'\n\nimport { zResultItem } from '@/platform/remote/comfyui/execution/types'\n\nimport { assetItemSchema } from './assetSchema'\n\nexport const zMediaKindSchema = z.enum([\n  'video',\n  'audio',\n  'image',\n  '3D',\n  'text',\n  'other'\n])\nexport type MediaKind = z.infer<typeof zMediaKindSchema>\n\nconst zDimensionsSchema = z.object({\n  width: z.number().positive(),\n  height: z.number().positive()\n})\n\n// Extend the base asset schema with media-specific fields\nconst zMediaAssetDisplayItemSchema = assetItemSchema.extend({\n  // New required fields\n  kind: zMediaKindSchema,\n  src: z.url(),\n\n  // New optional fields\n  duration: z.number().nonnegative().optional(),\n  dimensions: zDimensionsSchema.optional()\n})\n\n// Asset context schema\nconst zAssetContextSchema = z.object({\n  type: z.enum(['input', 'output']),\n  outputCount: z.number().positive().optional() // Only for output context\n})\n\n// Export the inferred types\nexport type AssetMeta = z.infer<typeof zMediaAssetDisplayItemSchema>\nexport type AssetContext = z.infer<typeof zAssetContextSchema>\n\n// Injection key for MediaAsset provide/inject pattern\ninterface MediaAssetProviderValue {\n  asset: Ref<AssetMeta | undefined>\n  context: Ref<AssetContext>\n}\n\nexport const MediaAssetKey: InjectionKey<MediaAssetProviderValue> =\n  Symbol('mediaAsset')\n\nexport const MIME_ASSET_INFO = 'application/x-comfy-asset-info'\n\nconst zDraggedAssetInfo = zResultItem.and(\n  z.object({\n    attachment_ref: z.string().min(1).optional(),\n    media_kind: zMediaKindSchema.optional(),\n    preview_url: z.url().optional(),\n    media_url: z.url().optional()\n  })\n)\n\nexport function parseAssetInfo(dataTransfer: DataTransfer) {\n  const assetString = dataTransfer.getData(MIME_ASSET_INFO)\n  try {\n    return zDraggedAssetInfo.safeParse(JSON.parse(assetString)).data\n  } catch {\n    // output was not parsable, allow fallthrough and return undefined\n  }\n}\n","import type { MediaKind } from '@/platform/assets/schemas/mediaAssetSchema'\nimport { parseAssetInfo } from '@/platform/assets/schemas/mediaAssetSchema'\nimport { isHdrImageFilename } from '@/utils/hdrFormatUtil'\n\nexport interface DroppedAsset {\n  name: string\n  uri?: string\n  ref?: string\n  kind?: MediaKind\n  previewUrl?: string\n  mediaUrl?: string\n}\n\nexport function getDroppedAsset(\n  dataTransfer: DataTransfer\n): DroppedAsset | undefined {\n  const asset = parseAssetInfo(dataTransfer)\n  const name = asset?.display_name ?? asset?.filename\n  const validTypes = ['text/uri-list', 'text/x-moz-url']\n  const match = [...dataTransfer.types].find((type) =>\n    validTypes.includes(type)\n  )\n  const uri = match && dataTransfer.getData(match).split('\\n')[0]\n  const ref = asset?.attachment_ref\n\n  return uri || ref\n    ? {\n        name: name ?? ref ?? uri!,\n        uri,\n        ref,\n        kind: asset?.media_kind,\n        previewUrl: asset?.preview_url,\n        mediaUrl: asset?.media_url\n      }\n    : undefined\n}\n\nexport async function fetchDroppedAsset({\n  name,\n  uri\n}: DroppedAsset): Promise<File | undefined> {\n  if (!uri) return undefined\n  try {\n    const response = await fetch(uri)\n    if (!response.ok) return undefined\n    const blob = await response.blob()\n    return new File([blob], name, { type: blob.type })\n  } catch {\n    return undefined\n  }\n}\n\nexport async function extractFilesFromDragEvent(\n  event: DragEvent\n): Promise<File[]> {\n  if (!event.dataTransfer) return []\n\n  // Dragging from Chrome->Firefox there is a file but its a bmp, so ignore that\n  const files = Array.from(event.dataTransfer.files)\n    .filter((file) => file.type !== 'image/bmp')\n    .map(withHdrImageType)\n\n  if (files.length > 0) return files\n\n  const asset = getDroppedAsset(event.dataTransfer)\n  if (!asset) return []\n\n  const file = await fetchDroppedAsset(asset)\n  return file ? [file] : []\n}\n\nexport function withHdrImageType(file: File): File {\n  if (file.type || !isHdrImageFilename(file.name)) return file\n  const type = file.name.toLowerCase().endsWith('.hdr')\n    ? 'image/vnd.radiance'\n    : 'image/x-exr'\n  return new File([file], file.name, { type, lastModified: file.lastModified })\n}\n\nexport function hasImageType({ type }: File): boolean {\n  return type.startsWith('image')\n}\n\nexport function hasAudioType({ type }: File): boolean {\n  return type.startsWith('audio')\n}\n\nexport function hasVideoType({ type }: File): boolean {\n  return type.startsWith('video')\n}\n\nexport function isMediaFile(file: File): boolean {\n  return hasImageType(file) || hasAudioType(file) || hasVideoType(file)\n}\n","import { useChainCallback } from '@/composables/functional/useChainCallback'\nimport { partition } from 'es-toolkit'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { parseAssetInfo } from '@/platform/assets/schemas/mediaAssetSchema'\nimport type { ResultItem } from '@/platform/remote/comfyui/execution/types'\nimport { withHdrImageType } from '@/utils/eventUtils'\n\ntype DragHandler = (e: DragEvent) => boolean\ntype DropHandler<T> = (files: File[]) => Promise<T[]>\n\ninterface DragAndDropOptions<T> {\n  onDragOver?: DragHandler\n  onDrop: DropHandler<T>\n  onResultItemDrop?: (item: ResultItem) => void\n  fileFilter?: (file: File) => boolean\n  onReject?: (files: File[]) => boolean\n}\n\n/**\n * Adds drag and drop file handling to a node\n * Will also resolve 'text/uri-list' to a file before passing\n */\nexport const useNodeDragAndDrop = <T>(\n  node: LGraphNode,\n  options: DragAndDropOptions<T>\n) => {\n  const { onDragOver, onDrop, fileFilter = () => true } = options\n\n  const hasFiles = (items: DataTransferItemList) =>\n    !!Array.from(items).find((f) => f.kind === 'file')\n\n  const filterFiles = (files: FileList | File[]) =>\n    Array.from(files).filter(fileFilter)\n\n  function handleRejectedFiles(files: File[]) {\n    return files.length > 0 && (options.onReject?.(files) ?? false)\n  }\n\n  const isDraggingFiles = (e: DragEvent | undefined) => {\n    if (!e?.dataTransfer?.items) return false\n    return (\n      onDragOver?.(e) ??\n      (hasFiles(e.dataTransfer.items) ||\n        e.dataTransfer.types.includes('text/uri-list'))\n    )\n  }\n\n  const installedDragOver = isDraggingFiles\n  node.onDragOver = installedDragOver\n\n  const installedDragDrop = async function (e: DragEvent) {\n    const { dataTransfer } = e\n    if (!dataTransfer) return false\n\n    const droppedFiles = Array.from(dataTransfer.files, withHdrImageType)\n    const [files, rejectedFiles] = partition(droppedFiles, fileFilter)\n    const rejectedFilesClaimed = handleRejectedFiles(rejectedFiles)\n    if (files.length) {\n      await onDrop(files)\n      return true\n    }\n    if (dataTransfer.files.length) {\n      return rejectedFilesClaimed\n    }\n    const asset = parseAssetInfo(dataTransfer)\n    if (asset?.filename && options.onResultItemDrop) {\n      await options.onResultItemDrop(asset)\n      return true\n    }\n\n    const baseUri = dataTransfer.getData('text/uri-list')\n    if (!baseUri) return false\n    const uri = URL.parse(baseUri, location.href)\n    if (!uri || uri.origin !== location.origin) return false\n\n    try {\n      const resp = await fetch(uri)\n      const fileName =\n        asset?.filename ??\n        uri.searchParams.get('filename') ??\n        baseUri.split('/').at(-1)\n      if (!fileName || !resp.ok) return false\n\n      const blob = await resp.blob()\n      const file = new File([blob], fileName, { type: blob.type })\n      const uriFiles = filterFiles([file])\n      if (!uriFiles.length) {\n        return handleRejectedFiles([file])\n      }\n\n      await onDrop(uriFiles)\n    } catch {\n      return false\n    }\n    return true\n  }\n  node.onDragDrop = installedDragDrop\n\n  node.onRemoved = useChainCallback(node.onRemoved, () => {\n    if (node.onDragOver === installedDragOver) node.onDragOver = undefined\n    if (node.onDragDrop === installedDragDrop) node.onDragDrop = undefined\n  })\n}\n","import { useChainCallback } from '@/composables/functional/useChainCallback'\nimport { partition } from 'es-toolkit'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\n\ninterface FileInputOptions {\n  accept?: string\n  allow_batch?: boolean\n  fileFilter?: (file: File) => boolean\n  onReject?: (files: File[]) => void\n  onSelect: (files: File[]) => void\n}\n\n/**\n * Creates a file input for a node.\n */\nexport function useNodeFileInput(node: LGraphNode, options: FileInputOptions) {\n  const {\n    accept,\n    allow_batch = false,\n    fileFilter = () => true,\n    onSelect\n  } = options\n\n  let fileInput: HTMLInputElement | null = document.createElement('input')\n  fileInput.type = 'file'\n  fileInput.accept = accept ?? '*'\n  fileInput.multiple = allow_batch\n\n  fileInput.onchange = () => {\n    const selectedFiles = fileInput?.files?.length\n      ? Array.from(fileInput.files)\n      : []\n    const [files, rejectedFiles] = partition(selectedFiles, fileFilter)\n    // Reset value so re-selecting the same file triggers onchange\n    if (fileInput) fileInput.value = ''\n    if (rejectedFiles.length) options.onReject?.(rejectedFiles)\n    if (files.length) onSelect(files)\n  }\n\n  node.onRemoved = useChainCallback(node.onRemoved, () => {\n    if (fileInput) {\n      fileInput.onchange = null\n      fileInput = null\n    }\n  })\n\n  return {\n    openFileSelection: () => fileInput?.click()\n  }\n}\n","import { useChainCallback } from '@/composables/functional/useChainCallback'\nimport { partition } from 'es-toolkit'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\n\ntype PasteHandler<T> = (files: File[]) => Promise<T>\n\ninterface NodePasteOptions<T> {\n  onPaste: PasteHandler<T>\n  fileFilter?: (file: File) => boolean\n  allow_batch?: boolean\n  onReject?: (files: File[]) => void\n}\n\n/**\n * Adds paste handling to a node\n */\nexport const useNodePaste = <T>(\n  node: LGraphNode,\n  options: NodePasteOptions<T>\n) => {\n  const { onPaste, fileFilter = () => true, allow_batch = false } = options\n\n  const installedPasteFiles = function (files: File[]) {\n    const [filteredFiles, rejectedFiles] = partition(files, fileFilter)\n    if (rejectedFiles.length) options.onReject?.(rejectedFiles)\n    if (!filteredFiles.length) {\n      return\n    }\n\n    const paste = allow_batch ? filteredFiles : filteredFiles.slice(0, 1)\n\n    void onPaste(paste)\n  }\n  node.pasteFiles = installedPasteFiles\n\n  node.onRemoved = useChainCallback(node.onRemoved, () => {\n    if (node.pasteFiles === installedPasteFiles) node.pasteFiles = undefined\n  })\n}\n","import { useNodeDragAndDrop } from '@/composables/node/useNodeDragAndDrop'\nimport { useNodeFileInput } from '@/composables/node/useNodeFileInput'\nimport { useNodePaste } from '@/composables/node/useNodePaste'\nimport { t } from '@/i18n'\nimport { ServerFeatureFlag } from '@/platform/remoteConfig/serverFeatureFlag'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport type { ResultItem } from '@/platform/remote/comfyui/execution/types'\nimport type { ResultItemType } from '@/schemas/resultItemTypeSchema'\nimport { useAssetsStore } from '@/stores/assetsStore'\nimport { api } from '@/scripts/api'\nimport { getErrorMessage } from '@/utils/errorUtil'\n\nconst UPLOAD_TIMEOUT_MS = 120_000\nconst BYTES_PER_MB = 1024 * 1024\n\nfunction buildUploadErrorMessage(resp: Response) {\n  if (resp.status === 413) {\n    const maxUploadSize = api.getServerFeature<number>(\n      ServerFeatureFlag.MAX_UPLOAD_SIZE\n    )\n    return typeof maxUploadSize === 'number' && maxUploadSize > 0\n      ? t('g.uploadFileTooLargeWithLimit', {\n          limit: Math.round(maxUploadSize / BYTES_PER_MB)\n        })\n      : t('g.uploadFileTooLarge')\n  }\n\n  return t('g.uploadFailed', {\n    reason: resp.statusText || `HTTP ${resp.status}`\n  })\n}\n\ninterface ImageUploadFormFields {\n  /**\n   * The folder to upload the file to.\n   * @example 'input', 'output', 'temp'\n   */\n  type: ResultItemType\n}\n\nconst uploadFile = async (\n  file: File,\n  formFields: Partial<ImageUploadFormFields> = {}\n) => {\n  const body = new FormData()\n  body.append('image', file)\n  if (formFields.type) body.append('type', formFields.type)\n\n  const resp = await api.fetchApi('/upload/image', {\n    method: 'POST',\n    body,\n    timeoutMs: UPLOAD_TIMEOUT_MS\n  })\n\n  if (resp.status !== 200) {\n    useToast().warning(buildUploadErrorMessage(resp))\n    return\n  }\n\n  const data = await resp.json()\n\n  // Update AssetsStore input assets when files are uploaded to input folder\n  if (formFields.type === 'input' || !formFields.type) {\n    await useAssetsStore().inputAssets.invalidate()\n  }\n\n  return data.subfolder ? `${data.subfolder}/${data.name}` : data.name\n}\n\ninterface ImageUploadOptions {\n  fileFilter?: (file: File) => boolean\n  onUploadComplete: (paths: (string | ResultItem)[]) => void\n  allow_batch?: boolean\n  /**\n   * The file types to accept.\n   * @example 'image/png,image/jpeg,image/webp,video/webm,video/mp4'\n   */\n  accept?: string\n  /**\n   * The folder to upload the file to.\n   * @example 'input', 'output', 'temp'\n   */\n  folder?: ResultItemType\n  onUploadStart?: (files: File[]) => void\n  onUploadError?: () => void\n  onReject?: (files: File[]) => boolean\n}\n\n/**\n * Adds image upload to a node via drag & drop, paste, and file input.\n */\nexport const useNodeImageUpload = (\n  node: LGraphNode,\n  options: ImageUploadOptions\n) => {\n  const { fileFilter, onUploadComplete, allow_batch, accept } = options\n\n  const handleUpload = async (file: File) => {\n    try {\n      const path = await uploadFile(file, {\n        type: options.folder\n      })\n      if (!path) return\n      return path\n    } catch (error) {\n      if (error instanceof DOMException && error.name === 'TimeoutError') {\n        useToast().warning(t('g.uploadTimedOut'))\n      } else {\n        useToast().warning(\n          t('g.uploadFailed', {\n            reason: getErrorMessage(error) ?? t('g.unknownError')\n          })\n        )\n      }\n    }\n  }\n\n  const handleUploadBatch = async (files: File[]) => {\n    if (node.isUploading) {\n      useToast().warning(t('g.uploadAlreadyInProgress'))\n      return []\n    }\n    node.isUploading = true\n\n    try {\n      node.imgs = undefined\n      node.graph?.setDirtyCanvas(true)\n      options.onUploadStart?.(files)\n\n      const paths = await Promise.all(files.map(handleUpload))\n      const validPaths = paths.filter((p): p is string => !!p)\n      if (validPaths.length) {\n        onUploadComplete(validPaths)\n      } else {\n        options.onUploadError?.()\n      }\n      return validPaths\n    } finally {\n      node.isUploading = false\n      node.graph?.setDirtyCanvas(true)\n    }\n  }\n\n  // Handle drag & drop\n  useNodeDragAndDrop(node, {\n    fileFilter,\n    onReject: options.onReject,\n    onDrop: handleUploadBatch,\n    onResultItemDrop: (item) => onUploadComplete([item])\n  })\n\n  // Handle paste\n  useNodePaste(node, {\n    fileFilter,\n    onReject: options.onReject,\n    allow_batch,\n    onPaste: handleUploadBatch\n  })\n\n  // Handle file input\n  const { openFileSelection } = useNodeFileInput(node, {\n    fileFilter,\n    onReject: options.onReject,\n    allow_batch,\n    accept,\n    onSelect: handleUploadBatch\n  })\n\n  return { openFileSelection, handleUpload }\n}\n","/**\n * Frontend augmentations for node definitions.\n *\n * This module defines type extensions that augment the backend node definition\n * types with frontend-specific properties. These augmentations are applied at\n * runtime and are not part of the backend API contract.\n */\nimport type { ComboInputOptions, InputSpec } from '@/schemas/nodeDefSchema'\n\n/**\n * Frontend augmentation for image upload combo inputs.\n * This extends ComboInputOptions with properties injected by the uploadImage extension.\n */\ninterface ImageUploadComboOptions extends ComboInputOptions {\n  /**\n   * Reference to the associated filename combo widget.\n   * Injected by uploadImage.ts to link upload buttons with their combo widgets.\n   *\n   * @remarks This property exists only in the frontend runtime.\n   */\n  imageInputName: string\n}\n\n/**\n * Type guard to check if an InputSpec has image upload augmentations.\n * Narrows from base InputSpec to augmented type.\n */\nexport function isImageUploadInput(\n  inputData: InputSpec\n): inputData is [string, ImageUploadComboOptions] {\n  const options = inputData[1]\n  return (\n    options !== undefined &&\n    typeof options === 'object' &&\n    'imageInputName' in options &&\n    typeof options.imageInputName === 'string'\n  )\n}\n","/** Accepted MIME types for the image upload file picker. */\nexport const ACCEPTED_IMAGE_TYPES = 'image/png,image/jpeg,image/webp'\n\n/** Accepted MIME types for the video upload file picker. */\nexport const ACCEPTED_VIDEO_TYPES = 'video/webm,video/mp4'\n\nexport function hasFilenameExtension(file: File) {\n  return /^\\.*[^.].*\\.[^.\\s/\\\\]+$/.test(file.name)\n}\n\nexport function isUploadableVideo(file: File) {\n  return file.type.startsWith('video/') && hasFilenameExtension(file)\n}\n\nexport function isExtensionlessVideo(file: File) {\n  return file.type.startsWith('video/') && !hasFilenameExtension(file)\n}\n","import { useNodeImage, useNodeVideo } from '@/composables/node/useNodeImage'\nimport { useNodeImageUpload } from '@/composables/node/useNodeImageUpload'\nimport { t } from '@/i18n'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { IComboWidget } from '@/lib/litegraph/src/types/widgets'\nimport type { ResultItem } from '@/platform/remote/comfyui/execution/types'\nimport type { ResultItemType } from '@/schemas/resultItemTypeSchema'\nimport type { InputSpec } from '@/schemas/nodeDefSchema'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport type { ComfyWidgetConstructor } from '@/types/comfy'\nimport { useNodeOutputStore } from '@/stores/nodeOutputStore'\nimport { isImageUploadInput } from '@/types/nodeDefAugmentation'\nimport { createAnnotatedPath } from '@/utils/createAnnotatedPath'\nimport { addToComboValues } from '@/utils/litegraphUtil'\n\nimport {\n  ACCEPTED_IMAGE_TYPES,\n  ACCEPTED_VIDEO_TYPES,\n  isExtensionlessVideo,\n  isUploadableVideo\n} from '@/utils/mediaUploadUtil'\n\nfunction isImageFile(file: File) {\n  return file.type.startsWith('image/')\n}\n\ntype ImageUploadComboWidget = Omit<IComboWidget, 'value' | 'callback'> & {\n  value: string | number | string[]\n  callback?: (value: string | number | string[]) => void\n}\n\nconst findFileComboWidget = (\n  node: LGraphNode,\n  inputName: string\n): ImageUploadComboWidget | undefined =>\n  node.widgets?.find((w): w is ImageUploadComboWidget => w.name === inputName)\n\nexport const useImageUploadWidget = () => {\n  const widgetConstructor: ComfyWidgetConstructor = (\n    node: LGraphNode,\n    inputName: string,\n    inputData: InputSpec\n  ) => {\n    if (!isImageUploadInput(inputData)) {\n      throw new Error(\n        'Image upload widget requires imageInputName augmentation'\n      )\n    }\n\n    const inputOptions = inputData[1]\n    const { imageInputName, allow_batch, image_folder = 'input' } = inputOptions\n    const folder: ResultItemType | undefined = image_folder\n    const nodeOutputStore = useNodeOutputStore()\n\n    const isAnimated = !!inputOptions.animated_image_upload\n    const isVideo = !!inputOptions.video_upload\n    const accept = isVideo ? ACCEPTED_VIDEO_TYPES : ACCEPTED_IMAGE_TYPES\n    const { showPreview } = isVideo ? useNodeVideo(node) : useNodeImage(node)\n\n    const fileFilter = isVideo ? isUploadableVideo : isImageFile\n    function alertExtensionlessVideo(files: File[]) {\n      if (!files.some(isExtensionlessVideo)) return false\n      useToast().warning(t('g.videoFilenameExtensionRequired'))\n      return true\n    }\n    const fileComboWidget = findFileComboWidget(node, imageInputName)\n    if (!fileComboWidget) {\n      throw new Error(`Widget \"${imageInputName}\" not found on node`)\n    }\n    function formatPath(value: string | ResultItem) {\n      return typeof value === 'string'\n        ? createAnnotatedPath(value, { rootFolder: image_folder })\n        : createAnnotatedPath(value)\n    }\n\n    // Setup file upload handling\n    let rollback: (() => void) | undefined\n    const { openFileSelection } = useNodeImageUpload(node, {\n      allow_batch,\n      fileFilter,\n      accept,\n      folder,\n      onReject: isVideo ? alertExtensionlessVideo : undefined,\n      onUploadStart: (files) => {\n        if (files.length > 0) {\n          const prev = fileComboWidget.value\n          fileComboWidget.value = files[0].name\n          rollback = () => {\n            fileComboWidget.value = prev\n          }\n        }\n      },\n      onUploadError: () => {\n        rollback?.()\n        rollback = undefined\n      },\n      onUploadComplete: (output) => {\n        rollback = undefined\n        const annotated = output.map(formatPath)\n        annotated.forEach((path) => {\n          addToComboValues(fileComboWidget, path)\n        })\n\n        const newValue = allow_batch ? annotated : annotated[0]\n        const oldValue = fileComboWidget.value\n\n        fileComboWidget.value = newValue\n        fileComboWidget.callback?.(newValue)\n        node.onWidgetChanged?.(\n          fileComboWidget.name,\n          newValue,\n          oldValue,\n          fileComboWidget\n        )\n        useWorkflowStore().activeWorkflow?.changeTracker.captureCanvasState()\n      }\n    })\n\n    // Create the button widget for selecting the files\n    const uploadWidget = node.addWidget(\n      'button',\n      inputName,\n      'image',\n      () => openFileSelection(),\n      {\n        serialize: false,\n        surfaces: { canvas: 'shown', vueNode: 'never', panel: 'never' }\n      }\n    )\n    uploadWidget.label = t('g.choose_file_to_upload')\n\n    // Add our own callback to the combo widget to render an image when it changes\n    fileComboWidget.callback = function () {\n      node.imgs = undefined\n      nodeOutputStore.setNodeOutputs(node, String(fileComboWidget.value), {\n        isAnimated\n      })\n      showPreview({ block: false })\n      node.graph?.setDirtyCanvas(true)\n    }\n\n    // On load if we have a value then render the image\n    // The value isn't set immediately so we need to wait a moment\n    // No change callbacks seem to be fired on initial setting of the value\n    requestAnimationFrame(() => {\n      const fileValue = fileComboWidget.value as\n        | string\n        | number\n        | null\n        | undefined\n      if (fileValue != null) {\n        nodeOutputStore.setNodeOutputs(node, String(fileValue), {\n          isAnimated\n        })\n      }\n      showPreview({ block: false })\n    })\n\n    return { widget: uploadWidget }\n  }\n\n  return widgetConstructor\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type {\n  IColorWidgetOptions,\n  INumericWidget\n} from '@/lib/litegraph/src/types/widgets'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport type { InputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport { isIntInputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\nimport { addValueControlWidget } from '@/core/graph/widgets/valueControlWidgets'\nimport { transformInputSpecV2ToV1 } from '@/schemas/nodeDef/migration'\n\nfunction onValueChange(this: INumericWidget, v: number) {\n  // For integers, always round to the nearest step\n  // step === 0 is invalid, assign 1 if options.step is 0\n  const step = this.options.step2 || 1\n\n  if (step === 1) {\n    // Simple case: round to nearest integer\n    this.value = Math.round(v)\n  } else {\n    // Round to nearest multiple of step\n    // First, determine if min value creates an offset\n    const min = this.options.min ?? 0\n    const offset = min % step\n\n    // Round to nearest step, accounting for offset\n    this.value = Math.round((v - offset) / step) * step + offset\n  }\n}\n\nexport const _for_testing = {\n  onValueChange\n}\n\nexport const useIntWidget = () => {\n  const widgetConstructor: ComfyWidgetConstructorV2 = (\n    node: LGraphNode,\n    inputSpec: InputSpec\n  ) => {\n    if (!isIntInputSpec(inputSpec)) {\n      throw new Error(`Invalid input data: ${inputSpec}`)\n    }\n\n    const settingStore = useSettingStore()\n    const sliderEnabled = !settingStore.get('Comfy.DisableSliders')\n    const display_type = inputSpec.display\n    const widgetType =\n      display_type == 'color'\n        ? 'color'\n        : sliderEnabled && display_type == 'slider'\n          ? 'slider'\n          : display_type == 'knob'\n            ? 'knob'\n            : 'number'\n\n    const step = inputSpec.step ?? 1\n    /** Assertion {@link inputSpec.default} */\n    const defaultValue = (inputSpec.default as number | undefined) ?? 0\n    const options: IColorWidgetOptions = {\n      min: inputSpec.min ?? 0,\n      max: inputSpec.max ?? 2048,\n      /** @deprecated Use step2 instead. The 10x value is a legacy implementation. */\n      step: step * 10,\n      step2: step,\n      precision: 0\n    }\n    if (display_type == 'color') options.format = 'int'\n\n    const widget = node.addWidget(\n      widgetType,\n      inputSpec.name,\n      defaultValue,\n      onValueChange,\n      options\n    )\n\n    const controlAfterGenerate =\n      inputSpec.control_after_generate ??\n      ['seed', 'noise_seed'].includes(inputSpec.name)\n\n    if (controlAfterGenerate) {\n      const defaultType =\n        typeof inputSpec.control_after_generate === 'string'\n          ? inputSpec.control_after_generate\n          : 'randomize'\n      const controlWidget = addValueControlWidget(\n        node,\n        widget,\n        defaultType,\n        undefined,\n        undefined,\n        transformInputSpecV2ToV1(inputSpec)\n      )\n      widget.linkedWidgets = [controlWidget]\n    }\n\n    return widget\n  }\n  return widgetConstructor\n}\n","import { Editor as TiptapEditor } from '@tiptap/core'\nimport {\n  Table as TiptapTable,\n  TableCell as TiptapTableCell,\n  TableHeader as TiptapTableHeader,\n  TableRow as TiptapTableRow\n} from '@tiptap/extension-table'\nimport TiptapStarterKit from '@tiptap/starter-kit'\nimport { Markdown as TiptapMarkdown } from 'tiptap-markdown'\n\nimport { useChainCallback } from '@/composables/functional/useChainCallback'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { resolveNodeRootGraphId } from '@/lib/litegraph/src/utils/widget'\nimport { forwardMiddleButtonToCanvas } from '@/renderer/extensions/vueNodes/widgets/utils/forwardMiddleButtonToCanvas'\nimport type { InputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport { useApp } from '@/scripts/appInstance'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\nimport { widgetId } from '@/types/widgetId'\n\n// TODO: This widget manually syncs with widgetValueStore via getValue/setValue.\n// Consolidate with useStringWidget into shared helpers (domWidgetHelpers.ts).\nfunction addMarkdownWidget(\n  node: LGraphNode,\n  name: string,\n  opts: { defaultVal: string }\n) {\n  TiptapMarkdown.configure({\n    html: false,\n    breaks: true,\n    transformPastedText: true\n  })\n  const editor = new TiptapEditor({\n    extensions: [\n      TiptapStarterKit,\n      TiptapMarkdown,\n      TiptapTable,\n      TiptapTableCell,\n      TiptapTableHeader,\n      TiptapTableRow\n    ],\n    content: opts.defaultVal,\n    editable: false\n  })\n\n  const widgetStore = useWidgetValueStore()\n\n  const inputEl = editor.options.element as HTMLElement\n  inputEl.classList.add('comfy-markdown')\n  const textarea = document.createElement('textarea')\n  inputEl.append(textarea)\n\n  const widget = node.addDOMWidget(name, 'MARKDOWN', inputEl, {\n    getValue(): string {\n      const graphId = resolveNodeRootGraphId(node, useApp().rootGraph.id)\n      const storedValue = widgetStore.getWidget(\n        widgetId(graphId, node.id, name)\n      )?.value\n      return typeof storedValue === 'string' ? storedValue : textarea.value\n    },\n    setValue(v: string) {\n      textarea.value = v\n      editor.commands.setContent(v)\n      const graphId = resolveNodeRootGraphId(node, useApp().rootGraph.id)\n      const widgetState = widgetStore.getWidget(\n        widgetId(graphId, node.id, name)\n      )\n      if (widgetState) widgetState.value = v\n    }\n  })\n  widget.element = inputEl\n  widget.options.minNodeSize = [400, 200]\n\n  const controller = new AbortController()\n  const { signal } = controller\n\n  inputEl.addEventListener(\n    'input',\n    (event) => {\n      if (event.target instanceof HTMLTextAreaElement) {\n        widget.value = event.target.value\n      }\n      widget.callback?.(widget.value)\n    },\n    { signal }\n  )\n\n  inputEl.addEventListener(\n    'dblclick',\n    () => {\n      inputEl.classList.add('editing')\n      setTimeout(() => textarea.focus(), 0)\n    },\n    { signal }\n  )\n\n  textarea.addEventListener('blur', () => inputEl.classList.remove('editing'), {\n    signal\n  })\n\n  textarea.addEventListener(\n    'change',\n    () => {\n      editor.commands.setContent(textarea.value)\n      widget.callback?.(widget.value)\n    },\n    { signal }\n  )\n\n  inputEl.addEventListener('keydown', (event) => event.stopPropagation(), {\n    signal\n  })\n\n  forwardMiddleButtonToCanvas(inputEl, signal)\n\n  widget.onRemove = useChainCallback(widget.onRemove, () => {\n    controller.abort()\n    if (!editor.isDestroyed) editor.destroy()\n  })\n\n  return widget\n}\n\nexport const useMarkdownWidget = () => {\n  const widgetConstructor: ComfyWidgetConstructorV2 = (\n    node: LGraphNode,\n    inputSpec: InputSpec\n  ) => {\n    return addMarkdownWidget(node, inputSpec.name, {\n      defaultVal: inputSpec.default ?? ''\n    })\n  }\n\n  return widgetConstructor\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport type { InputSpec as InputSpecV2 } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\n\nexport const usePainterWidget = (): ComfyWidgetConstructorV2 => {\n  return (node: LGraphNode, inputSpec: InputSpecV2): IBaseWidget => {\n    return node.addWidget('painter', inputSpec.name, inputSpec.default, null)\n  }\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type {\n  IRangeWidget,\n  IWidgetRangeOptions\n} from '@/lib/litegraph/src/types/widgets'\nimport type { RangeInputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\n\nexport const useRangeWidget = (): ComfyWidgetConstructorV2 => {\n  return (node: LGraphNode, inputSpec): IRangeWidget => {\n    const spec = inputSpec as RangeInputSpec\n    const defaultValue = spec.default ?? { min: 0.0, max: 1.0 }\n\n    const options: IWidgetRangeOptions = {\n      display: spec.display,\n      gradient_stops: spec.gradient_stops,\n      show_midpoint: spec.show_midpoint,\n      midpoint_scale: spec.midpoint_scale,\n      value_min: spec.value_min,\n      value_max: spec.value_max\n    }\n\n    const rawWidget = node.addWidget(\n      'range',\n      spec.name,\n      { ...defaultValue },\n      () => {},\n      options\n    )\n\n    if (rawWidget.type !== 'range') {\n      throw new Error(`Unexpected widget type: ${rawWidget.type}`)\n    }\n\n    return rawWidget as IRangeWidget\n  }\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type {\n  IResolutionPreviewWidget,\n  IWidgetResolutionPreviewOptions\n} from '@/lib/litegraph/src/types/widgets'\nimport { isResolutionPreviewInputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { InputSpec as InputSpecV2 } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\n\nexport const useResolutionPreviewWidget = (): ComfyWidgetConstructorV2 => {\n  return (\n    node: LGraphNode,\n    inputSpec: InputSpecV2\n  ): IResolutionPreviewWidget => {\n    const spec = isResolutionPreviewInputSpec(inputSpec) ? inputSpec : undefined\n    const options: IWidgetResolutionPreviewOptions = {\n      serialize: false,\n      canvasOnly: false,\n      hideInPanel: true,\n      ratio_widget: spec?.ratio_widget,\n      megapixels_widget: spec?.megapixels_widget,\n      multiple_widget: spec?.multiple_widget\n    }\n    const rawWidget = node.addWidget(\n      'resolutionpreview',\n      inputSpec.name,\n      null,\n      () => {},\n      options\n    )\n    rawWidget.serialize = false\n\n    return rawWidget as IResolutionPreviewWidget\n  }\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { resolveNodeRootGraphId } from '@/lib/litegraph/src/utils/widget'\nimport { defineDeprecatedProperty } from '@/lib/litegraph/src/utils/feedback'\nimport {\n  bindMultilineTextareaWidget,\n  createMultilineInputElement\n} from '@/renderer/extensions/vueNodes/widgets/utils/multilineTextarea'\nimport { isStringInputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { InputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport { useApp } from '@/scripts/appInstance'\nimport type { DOMWidgetOptions } from '@/scripts/domWidget'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\nimport { widgetId } from '@/types/widgetId'\n\nfunction addMultilineWidget(\n  node: LGraphNode,\n  name: string,\n  opts: { defaultVal: string; placeholder?: string }\n) {\n  const widgetStore = useWidgetValueStore()\n  const inputEl = createMultilineInputElement(\n    opts.defaultVal,\n    opts.placeholder || name\n  )\n\n  // Declared separately (rather than reading `widget.options` from the\n  // outer closure below) because `addDOMWidget` can invoke `setValue`\n  // synchronously, while restoring a saved value, before the `widget`\n  // binding it returns is initialized.\n  const widgetOptions: DOMWidgetOptions<string> = {\n    getValue(): string {\n      const graphId = resolveNodeRootGraphId(node, useApp().rootGraph.id)\n      const widgetState = widgetStore.getWidget(\n        widgetId(graphId, node.id, name)\n      )\n\n      return typeof widgetState?.value === 'string'\n        ? widgetState.value\n        : inputEl.value\n    },\n    setValue(v: string) {\n      inputEl.value = v\n      const graphId = resolveNodeRootGraphId(node, useApp().rootGraph.id)\n      const id = widgetId(graphId, node.id, name)\n      const widgetState = widgetStore.getWidget(id)\n      if (widgetState) {\n        widgetState.value = v\n        return\n      }\n      widgetStore.registerWidget(id, {\n        type: 'customtext',\n        value: v,\n        options: widgetOptions\n      })\n    }\n  }\n\n  const widget = node.addDOMWidget(name, 'customtext', inputEl, widgetOptions)\n\n  widget.element = inputEl\n\n  /** @deprecated Use {@link widget.element} instead (renamed in PR #8594). */\n  defineDeprecatedProperty(\n    widget,\n    'inputEl',\n    'element',\n    'widget.inputEl is deprecated. Use widget.element instead.'\n  )\n  widget.options.minNodeSize = [400, 200]\n\n  bindMultilineTextareaWidget(widget, inputEl)\n\n  return widget\n}\n\nexport const useStringWidget = () => {\n  const widgetConstructor: ComfyWidgetConstructorV2 = (\n    node: LGraphNode,\n    inputSpec: InputSpec\n  ) => {\n    if (!isStringInputSpec(inputSpec)) {\n      throw new Error(`Invalid input data: ${inputSpec}`)\n    }\n\n    const defaultVal = inputSpec.default ?? ''\n    const multiline = inputSpec.multiline\n\n    const widget = multiline\n      ? addMultilineWidget(node, inputSpec.name, {\n          defaultVal,\n          placeholder: inputSpec.placeholder\n        })\n      : node.addWidget('text', inputSpec.name, defaultVal, () => {}, {})\n\n    if (typeof inputSpec.dynamicPrompts === 'boolean') {\n      widget.dynamicPrompts = inputSpec.dynamicPrompts\n    }\n\n    return widget\n  }\n\n  return widgetConstructor\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { ITextareaWidget } from '@/lib/litegraph/src/types/widgets'\nimport { isTextareaInputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type {\n  InputSpec as InputSpecV2,\n  TextareaInputSpec\n} from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\n\nexport const useTextareaWidget = (): ComfyWidgetConstructorV2 => {\n  return (node: LGraphNode, inputSpec: InputSpecV2): ITextareaWidget => {\n    if (!isTextareaInputSpec(inputSpec)) {\n      console.error('Invalid input spec for textarea widget')\n    }\n\n    const textareaSpec = inputSpec as TextareaInputSpec\n    const { name, options } = textareaSpec\n    const defaultValue = textareaSpec.default ?? options?.default ?? ''\n    const rows = textareaSpec.rows ?? options?.rows ?? 5\n    const cols = textareaSpec.cols ?? options?.cols ?? 50\n\n    const widgetOptions = { rows, cols }\n\n    const widget = node.addWidget('textarea', name, defaultValue, () => {}, {\n      serialize: true,\n      ...widgetOptions\n    }) as ITextareaWidget\n\n    return widget\n  }\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type {\n  IVideoEditWidget,\n  IWidgetVideoEditOptions,\n  VideoEditValue\n} from '@/lib/litegraph/src/types/widgets'\nimport type {\n  InputSpec as InputSpecV2,\n  VideoEditInputSpec\n} from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\n\nexport const useVideoEditWidget = (): ComfyWidgetConstructorV2 => {\n  return (node: LGraphNode, inputSpec: InputSpecV2): IVideoEditWidget => {\n    const spec = inputSpec as VideoEditInputSpec\n    const features = spec.features ?? ['trim', 'crop']\n\n    const defaultValue: VideoEditValue = spec.default ?? {\n      ...(features.includes('trim') && {\n        trim: { start_time: 0, duration: 0 }\n      }),\n      ...(features.includes('crop') && {\n        crop: { x: 0, y: 0, width: 0, height: 0 }\n      })\n    }\n\n    const options: IWidgetVideoEditOptions = {\n      features,\n      serialize: true,\n      hideInPanel: true\n    }\n\n    const rawWidget = node.addWidget(\n      'videoedit',\n      spec.name,\n      structuredClone(defaultValue),\n      () => {},\n      options\n    )\n\n    if (rawWidget.type !== 'videoedit') {\n      throw new Error(`Unexpected widget type: ${rawWidget.type}`)\n    }\n\n    return rawWidget as IVideoEditWidget\n  }\n}\n","import { useChainCallback } from '@/composables/functional/useChainCallback'\nimport { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport { useBooleanWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useBooleanWidget'\nimport { useFloatWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useFloatWidget'\nimport { useStringWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useStringWidget'\n\nconst StringWidget = useStringWidget()\nconst FloatWidget = useFloatWidget()\nconst BooleanWidget = useBooleanWidget()\n\nfunction unknownWidgetName(node: LGraphNode): string {\n  const count = node.widgets?.length ?? 0\n  return count === 0 ? 'UNKNOWN' : `UNKNOWN_${count}`\n}\n\nfunction addWidgetFromValue(node: LGraphNode, value: unknown) {\n  let widget: IBaseWidget\n  const name = unknownWidgetName(node)\n\n  if (typeof value === 'string') {\n    widget = StringWidget(node, {\n      type: 'STRING',\n      name,\n      multiline: value.length > 20\n    })\n  } else if (typeof value === 'number') {\n    widget = FloatWidget(node, {\n      type: 'FLOAT',\n      name,\n      default: value\n    })\n  } else if (typeof value === 'boolean') {\n    widget = BooleanWidget(node, {\n      type: 'BOOLEAN',\n      name,\n      default: value\n    })\n  } else {\n    widget = StringWidget(node, {\n      type: 'STRING',\n      name,\n      multiline: true\n    })\n    widget.value = JSON.stringify(value)\n    widget.label = 'UNKNOWN'\n    return\n  }\n\n  widget.value = value\n  widget.label = 'UNKNOWN'\n}\n\n/**\n * Try add widgets to node with missing definition.\n */\nLGraphNode.prototype.onConfigure = useChainCallback(\n  LGraphNode.prototype.onConfigure,\n  function (this: LGraphNode, info) {\n    if (!this.has_errors || !info.widgets_values) return\n\n    /**\n     * Note: Some custom nodes overrides the `widgets_values` property to an\n     * object that has `length` property and index access. It is not safe to call\n     * any array methods on it.\n     * See example in https://github.com/Kosinkadink/ComfyUI-VideoHelperSuite/blob/8629188458dc6cb832f871ece3bd273507e8a766/web/js/VHS.core.js#L59-L84\n     */\n    for (let i = 0; i < info.widgets_values.length; i++) {\n      const widgetValue = info.widgets_values[i]\n      addWidgetFromValue(this, widgetValue)\n    }\n\n    this.serialize_widgets = true\n  }\n)\n","import { dynamicWidgets } from '@/core/graph/widgets/dynamicWidgets'\nimport {\n  addValueControlWidget as _addValueControlWidget,\n  addValueControlWidgets as _addValueControlWidgets,\n  updateControlWidgetLabel as _updateControlWidgetLabel\n} from '@/core/graph/widgets/valueControlWidgets'\nimport { useBooleanWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useBooleanWidget'\nimport { useBoundingBoxWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useBoundingBoxWidget'\nimport { useCurveWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useCurveWidget'\nimport { useChartWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useChartWidget'\nimport { useColorWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useColorWidget'\nimport { useComboWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useComboWidget'\nimport { useCompositorWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useCompositorWidget'\nimport { useFloatWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useFloatWidget'\nimport { useGalleriaWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useGalleriaWidget'\nimport { useBoundingBoxesWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useBoundingBoxesWidget'\nimport { useLightInfoWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useLightInfoWidget'\nimport { useColorsWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useColorsWidget'\nimport { useImageCompareWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useImageCompareWidget'\nimport { useImageUploadWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useImageUploadWidget'\nimport { useIntWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useIntWidget'\nimport { useMarkdownWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useMarkdownWidget'\nimport { usePainterWidget } from '@/renderer/extensions/vueNodes/widgets/composables/usePainterWidget'\nimport { useRangeWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useRangeWidget'\nimport { useResolutionPreviewWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useResolutionPreviewWidget'\nimport { useStringWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useStringWidget'\nimport { useTextareaWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useTextareaWidget'\nimport { useVideoEditWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useVideoEditWidget'\nimport { transformInputSpecV1ToV2 } from '@/schemas/nodeDef/migration'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\n\nimport type { ComfyWidgetConstructor } from '@/types/comfy'\n\nimport './domWidget'\nimport './errorNodeWidgets'\n\n/**\n * Transforms a V2 widget constructor to a V1 widget constructor.\n * @param widgetConstructorV2 The V2 widget constructor to transform.\n * @returns The transformed V1 widget constructor.\n */\nconst transformWidgetConstructorV2ToV1 = (\n  widgetConstructorV2: ComfyWidgetConstructorV2\n): ComfyWidgetConstructor => {\n  return (node, inputName, inputData) => {\n    const inputSpec = transformInputSpecV1ToV2(inputData, {\n      name: inputName\n    })\n    const widget = widgetConstructorV2(node, inputSpec)\n    return {\n      widget,\n      minWidth: widget.options.minNodeSize?.[0],\n      minHeight: widget.options.minNodeSize?.[1]\n    }\n  }\n}\n\nexport const ComfyWidgets = {\n  INT: transformWidgetConstructorV2ToV1(useIntWidget()),\n  FLOAT: transformWidgetConstructorV2ToV1(useFloatWidget()),\n  BOOLEAN: transformWidgetConstructorV2ToV1(useBooleanWidget()),\n  STRING: transformWidgetConstructorV2ToV1(useStringWidget()),\n  MARKDOWN: transformWidgetConstructorV2ToV1(useMarkdownWidget()),\n  COMBO: transformWidgetConstructorV2ToV1(useComboWidget()),\n  IMAGEUPLOAD: useImageUploadWidget(),\n  COLOR: transformWidgetConstructorV2ToV1(useColorWidget()),\n  IMAGECOMPARE: transformWidgetConstructorV2ToV1(useImageCompareWidget()),\n  BOUNDING_BOX: transformWidgetConstructorV2ToV1(useBoundingBoxWidget()),\n  CHART: transformWidgetConstructorV2ToV1(useChartWidget()),\n  GALLERIA: transformWidgetConstructorV2ToV1(useGalleriaWidget()),\n  PAINTER: transformWidgetConstructorV2ToV1(usePainterWidget()),\n  COMPOSITOR: transformWidgetConstructorV2ToV1(useCompositorWidget()),\n  TEXTAREA: transformWidgetConstructorV2ToV1(useTextareaWidget()),\n  CURVE: transformWidgetConstructorV2ToV1(useCurveWidget()),\n  RANGE: transformWidgetConstructorV2ToV1(useRangeWidget()),\n  VIDEO_EDIT: transformWidgetConstructorV2ToV1(useVideoEditWidget()),\n  RESOLUTION_PREVIEW: transformWidgetConstructorV2ToV1(\n    useResolutionPreviewWidget()\n  ),\n  BOUNDING_BOXES: transformWidgetConstructorV2ToV1(useBoundingBoxesWidget()),\n  LIGHT_INFO_PREVIEW: transformWidgetConstructorV2ToV1(useLightInfoWidget()),\n  COLORS: transformWidgetConstructorV2ToV1(useColorsWidget()),\n  ...dynamicWidgets\n} as const\n\nexport function isValidWidgetType(\n  key: unknown\n): key is keyof typeof ComfyWidgets {\n  return typeof key === 'string' && Object.hasOwn(ComfyWidgets, key)\n}\n\nexport const addValueControlWidget = _addValueControlWidget\nexport const addValueControlWidgets = _addValueControlWidgets\nexport const updateControlWidgetLabel = _updateControlWidgetLabel\n","import { defineStore } from 'pinia'\nimport { computed, ref } from 'vue'\n\nimport type { InputSpec as InputSpecV2 } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport { getInputSpecType } from '@/schemas/nodeDefSchema'\nimport type { InputSpec as InputSpecV1 } from '@/schemas/nodeDefSchema'\nimport { ComfyWidgets } from '@/scripts/widgets'\nimport type {\n  ComfyWidgetConstructor,\n  CustomComfyWidgetConstructor\n} from '@/types/comfy'\n\ntype WidgetConstructor = ComfyWidgetConstructor | CustomComfyWidgetConstructor\n\nexport const useWidgetStore = defineStore('widget', () => {\n  const coreWidgets = ComfyWidgets\n  const customWidgets = ref<Map<string, CustomComfyWidgetConstructor>>(\n    new Map()\n  )\n  const widgets = computed<Map<string, WidgetConstructor>>(\n    () => new Map([...customWidgets.value, ...Object.entries(coreWidgets)])\n  )\n\n  function inputIsWidget(spec: InputSpecV2 | InputSpecV1) {\n    const type = Array.isArray(spec) ? getInputSpecType(spec) : spec.type\n    return widgets.value.has(type)\n  }\n\n  function registerCustomWidgets(\n    newWidgets: Record<string, CustomComfyWidgetConstructor> | null | undefined\n  ) {\n    // Extensions are untrusted code: `getCustomWidgets` is typed to return\n    // `Record<string, ...>`, but in practice an extension can resolve it to\n    // null/undefined. Guard here so a single misbehaving custom node can't\n    // throw \"Cannot convert undefined or null to object\" and break app init.\n    if (!newWidgets) return\n    for (const [type, widget] of Object.entries(newWidgets)) {\n      customWidgets.value.set(type, widget)\n    }\n  }\n\n  return {\n    coreWidgets,\n    widgets,\n    inputIsWidget,\n    registerCustomWidgets\n  }\n})\n","export type CoreMediaMenuActionKind = 'input' | 'preview'\n\nconst coreMediaMenuActionKinds = new WeakMap<object, CoreMediaMenuActionKind>()\n\nexport function markCoreMediaMenuCallback<T extends object>(\n  callback: T,\n  kind: CoreMediaMenuActionKind\n): T {\n  coreMediaMenuActionKinds.set(callback, kind)\n  return callback\n}\n\nexport function filterUnavailableCoreMediaMenuActions<T>(\n  options: readonly T[],\n  unavailableKinds: ReadonlySet<CoreMediaMenuActionKind>\n): T[] {\n  return options.filter((option) => {\n    if (!option || typeof option !== 'object' || !('callback' in option))\n      return true\n\n    const { callback } = option\n    if (typeof callback !== 'function') return true\n\n    const kind = coreMediaMenuActionKinds.get(callback)\n    return !kind || !unavailableKinds.has(kind)\n  })\n}\n","import type { TWidgetValue } from '@/lib/litegraph/src/litegraph'\nimport type { InputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\n\n/**\n * Gets an ordered array of InputSpec objects based on input_order.\n * This is designed to work with V2 format used by litegraphService.\n *\n * @param nodeDefImpl - The ComfyNodeDefImpl containing both V1 and V2 formats\n * @param inputs - The V2 format inputs (flat Record<string, InputSpec>)\n * @returns Array of InputSpec objects in the correct order\n */\nexport function getOrderedInputSpecs(\n  nodeDefImpl: Pick<ComfyNodeDefImpl, 'input_order'>,\n  inputs: Partial<Record<string, InputSpec>>\n): InputSpec[] {\n  const orderedInputSpecs: InputSpec[] = []\n\n  // If no input_order, return default Object.values order\n  if (!nodeDefImpl.input_order) {\n    return Object.values(inputs).filter((input) => input !== undefined)\n  }\n\n  // Process required inputs in specified order\n  const requiredOrder = Object.hasOwn(nodeDefImpl.input_order, 'required')\n    ? nodeDefImpl.input_order.required\n    : []\n  for (const name of requiredOrder) {\n    const inputSpec = inputs[name]\n    if (inputSpec && !inputSpec.isOptional) {\n      orderedInputSpecs.push(inputSpec)\n    }\n  }\n\n  // Process optional inputs in specified order\n  const optionalOrder = Object.hasOwn(nodeDefImpl.input_order, 'optional')\n    ? nodeDefImpl.input_order.optional\n    : []\n  for (const name of optionalOrder) {\n    const inputSpec = inputs[name]\n    if (inputSpec?.isOptional) {\n      orderedInputSpecs.push(inputSpec)\n    }\n  }\n\n  // Add any remaining inputs not specified in input_order\n  const processedNames = new Set(orderedInputSpecs.map((spec) => spec.name))\n  for (const inputSpec of Object.values(inputs)) {\n    if (inputSpec && !processedNames.has(inputSpec.name)) {\n      orderedInputSpecs.push(inputSpec)\n    }\n  }\n\n  return orderedInputSpecs\n}\n\n/**\n * Reorders widget values based on the input_order to match expected widget order.\n * This is used when widgets were created in a different order than input_order specifies.\n *\n * @param widgetValues - The current widget values array\n * @param currentWidgetOrder - The current order of widget names\n * @param inputOrder - The desired order from input_order\n * @returns Reordered widget values array\n */\nexport function sortWidgetValuesByInputOrder(\n  widgetValues: TWidgetValue[],\n  currentWidgetOrder: string[],\n  inputOrder: string[]\n): TWidgetValue[] {\n  if (inputOrder.length === 0) {\n    return widgetValues\n  }\n\n  const widgetIndexByName = new Map<string, number>()\n  currentWidgetOrder.forEach((name, index) => {\n    if (index < widgetValues.length) {\n      widgetIndexByName.set(name, index)\n    }\n  })\n\n  // Reorder based on input_order\n  const reordered: TWidgetValue[] = []\n  const usedNames = new Set<string>()\n\n  // First, add values in the order specified by input_order\n  for (const name of inputOrder) {\n    const index = widgetIndexByName.get(name)\n    if (index === undefined) continue\n    reordered.push(widgetValues[index])\n    usedNames.add(name)\n  }\n\n  // Then add any remaining values not in input_order\n  for (const [name, index] of widgetIndexByName) {\n    if (!usedNames.has(name)) {\n      reordered.push(widgetValues[index])\n    }\n  }\n\n  // If there are extra values not in the map, append them\n  if (widgetValues.length > currentWidgetOrder.length) {\n    for (let i = currentWidgetOrder.length; i < widgetValues.length; i++) {\n      reordered.push(widgetValues[i])\n    }\n  }\n\n  return reordered\n}\n","import { pick, zip } from 'es-toolkit/compat'\n\nimport { downloadFile, openFileInNewTab } from '@/base/common/downloadUtil'\nimport { visibleCanvasViewport } from '@/composables/canvas/visibleCanvasViewport'\nimport { useSelectedLiteGraphItems } from '@/composables/canvas/useSelectedLiteGraphItems'\nimport { useSubgraphOperations } from '@/composables/graph/useSubgraphOperations'\nimport { useNodeAnimatedImage } from '@/composables/node/useNodeAnimatedImage'\nimport { useNodeCanvasImagePreview } from '@/composables/node/useNodeCanvasImagePreview'\nimport { useNodeImage, useNodeVideo } from '@/composables/node/useNodeImage'\nimport {\n  addWidgetPromotionOptions,\n  isPreviewPseudoWidget\n} from '@/core/graph/subgraph/promotionUtils'\nimport { applyDynamicInputs } from '@/core/graph/widgets/dynamicWidgets'\nimport { resolveNodeDefSlotText, st, t } from '@/i18n'\nimport {\n  LGraphCanvas,\n  LGraphEventMode,\n  LGraphNode,\n  LiteGraph,\n  RenderShape,\n  SubgraphNode,\n  createBounds,\n  outputAsSerialisable\n} from '@/lib/litegraph/src/litegraph'\nimport type {\n  CreateNodeOptions,\n  GraphAddOptions,\n  IContextMenuValue,\n  INodeInputSlot,\n  Point,\n  Subgraph\n} from '@/lib/litegraph/src/litegraph'\nimport type {\n  ExportedSubgraphInstance,\n  ISerialisableNodeInput,\n  ISerialisableNodeOutput,\n  ISerialisedNode\n} from '@/lib/litegraph/src/types/serialisation'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport { toConcreteWidget } from '@/lib/litegraph/src/widgets/widgetMap'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { createPromotedMultilineWidget } from '@/renderer/extensions/vueNodes/widgets/utils/multilineTextarea'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useDialogService } from '@/services/dialogService'\nimport { resolveSubgraphPseudoWidgetCache } from '@/services/subgraphPseudoWidgetCache'\nimport type { SubgraphPseudoWidgetCache } from '@/services/subgraphPseudoWidgetCache'\nimport { transformInputSpecV2ToV1 } from '@/schemas/nodeDef/migration'\nimport type {\n  ComfyNodeDef as ComfyNodeDefV2,\n  InputSpec,\n  OutputSpec\n} from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type {\n  ComfyNodeDef as ComfyNodeDefV1,\n  InputSpec as InputSpecV1\n} from '@/schemas/nodeDefSchema'\nimport {\n  getInputSpecType,\n  zDynamicGroupInputSpec\n} from '@/schemas/nodeDefSchema'\nimport { useApp } from '@/scripts/appInstance'\nimport {\n  clipspace,\n  copyToClipspace,\n  pasteFromClipspace\n} from '@/scripts/clipspace'\nimport { $el } from '@/scripts/ui/utils'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { useNodeOutputStore } from '@/stores/nodeOutputStore'\nimport { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport {\n  getPreviewExposureHostLocator,\n  usePreviewExposureStore\n} from '@/stores/previewExposureStore'\nimport { useSubgraphStore } from '@/stores/subgraphStore'\nimport { useFavoritedWidgetsStore } from '@/stores/workspace/favoritedWidgetsStore'\nimport { useRightSidePanelStore } from '@/stores/workspace/rightSidePanelStore'\nimport { useWidgetStore } from '@/stores/widgetStore'\nimport { parseNodeId } from '@/types/nodeId'\nimport type { SerializedNodeId } from '@/types/nodeId'\nimport { isBlueprintType } from '@/utils/blueprintUtils'\nimport { markCoreMediaMenuCallback } from '@/utils/coreMediaMenuActionUtils'\nimport { getImageFileUrl } from '@/utils/hdrFormatUtil'\nimport { getErrorMessage } from '@/utils/errorUtil'\nimport type { WidgetId } from '@/types/widgetId'\nimport { normalizeI18nKey } from '@/utils/formatUtil'\nimport {\n  isAnimatedOutput,\n  isVideoNode,\n  isVideoOutput,\n  migrateWidgetsValues\n} from '@/utils/litegraphUtil'\nimport { getOrderedInputSpecs } from '@/workbench/utils/nodeDefOrderingUtil'\n\nimport { useExtensionService } from './extensionService'\n\nasync function reencodeAsPngBlob(\n  blob: Blob,\n  width: number,\n  height: number\n): Promise<Blob> {\n  const canvas = $el('canvas', { width, height })\n  const ctx = canvas.getContext('2d')\n  if (!ctx) throw new Error('Could not get canvas context')\n\n  let image: ImageBitmap | HTMLImageElement\n  if (typeof window.createImageBitmap === 'undefined') {\n    const img = new Image()\n    const loaded = new Promise<void>((resolve, reject) => {\n      img.onload = () => resolve()\n      img.onerror = () => reject(new Error('Image load failed'))\n    })\n    img.src = URL.createObjectURL(blob)\n    try {\n      await loaded\n    } finally {\n      URL.revokeObjectURL(img.src)\n    }\n    image = img\n  } else {\n    image = await createImageBitmap(blob)\n  }\n\n  try {\n    ctx.drawImage(image, 0, 0)\n  } finally {\n    if ('close' in image && typeof image.close === 'function') {\n      image.close()\n    }\n  }\n\n  return new Promise<Blob>((resolve, reject) => {\n    canvas.toBlob((result) => {\n      if (result) resolve(result)\n      else reject(new Error('PNG conversion failed'))\n    }, 'image/png')\n  })\n}\n\nexport const CONFIG = Symbol()\nexport const GET_CONFIG = Symbol()\n\nexport function getExtraOptionsForWidget(\n  node: LGraphNode,\n  widget: IBaseWidget\n) {\n  const options: IContextMenuValue[] = []\n  const input = node.inputs.find((inp) => inp.widget?.name === widget.name)\n\n  if (input) {\n    options.unshift({\n      content: `${t('contextMenu.RenameWidget')}: ${widget.label ?? widget.name}`,\n      callback: async () => {\n        const newLabel = await useDialogService().prompt({\n          title: t('g.rename'),\n          message: t('g.enterNewNamePrompt'),\n          defaultValue: widget.label,\n          placeholder: widget.name\n        })\n        if (newLabel === null) return\n        widget.label = newLabel || undefined\n        input.label = newLabel || undefined\n        widget.callback?.(widget.value)\n        useCanvasStore().canvas?.setDirty(true)\n      }\n    })\n  }\n\n  const favoritedWidgetsStore = useFavoritedWidgetsStore()\n  const isFavorited = favoritedWidgetsStore.isFavorited(node, widget.name)\n  options.unshift({\n    content: isFavorited\n      ? `${t('contextMenu.UnfavoriteWidget')}: ${widget.label ?? widget.name}`\n      : `${t('contextMenu.FavoriteWidget')}: ${widget.label ?? widget.name}`,\n    callback: () => {\n      favoritedWidgetsStore.toggleFavorite(node, widget.name)\n    }\n  })\n\n  if (node.graph && !node.graph.isRootGraph) {\n    addWidgetPromotionOptions(options, widget, node)\n  }\n  return options\n}\n\nfunction getMinSize(node: LGraphNode) {\n  node._initialMinSize ??= { width: 1, height: 1 }\n  return node._initialMinSize\n}\n\n/**\n * Service that augments litegraph with ComfyUI specific functionality.\n */\nexport const useLitegraphService = () => {\n  const extensionService = useExtensionService()\n  const toast = useToast()\n  const widgetStore = useWidgetStore()\n  const canvasStore = useCanvasStore()\n  const { toggleSelectedNodesMode } = useSelectedLiteGraphItems()\n  const subgraphPseudoWidgetCache = new WeakMap<\n    SubgraphNode,\n    SubgraphPseudoWidgetCache<LGraphNode, IBaseWidget>\n  >()\n\n  function invalidateSubgraphPseudoWidgetCache(node: SubgraphNode) {\n    subgraphPseudoWidgetCache.delete(node)\n  }\n\n  function getPseudoWidgetPreviewTargets(node: SubgraphNode): LGraphNode[] {\n    const hostLocator = getPreviewExposureHostLocator(node)\n    if (!hostLocator) return []\n    const promotions = usePreviewExposureStore().getExposuresAsPromotionShape(\n      node.rootGraph.id,\n      hostLocator\n    )\n    const resolved = resolveSubgraphPseudoWidgetCache({\n      cache: subgraphPseudoWidgetCache.get(node) ?? null,\n      promotions,\n      getNodeById: (nodeId) => node.subgraph.getNodeById(nodeId) ?? undefined,\n      isPreviewPseudoWidget\n    })\n    subgraphPseudoWidgetCache.set(node, resolved.cache)\n    return resolved.nodes\n  }\n\n  /**\n   * @internal The node definition name used to resolve the node's i18n text.\n   */\n  function nodeDefName(node: LGraphNode): string {\n    return node.constructor.nodeData?.name ?? ''\n  }\n  /**\n   * @internal Add input sockets to the node. (No widget)\n   */\n  function addInputSocket(node: LGraphNode, inputSpec: InputSpec) {\n    const inputName = inputSpec.name\n    const widgetConstructor = widgetStore.widgets.get(\n      inputSpec.widgetType ?? inputSpec.type\n    )\n    if (\n      (widgetConstructor && !inputSpec.forceInput) ||\n      applyDynamicInputs(node, inputSpec)\n    )\n      return\n\n    node.addInput(inputName, inputSpec.type, {\n      shape: inputSpec.isOptional ? RenderShape.HollowCircle : undefined,\n      localized_name: resolveNodeDefSlotText(\n        'name',\n        nodeDefName(node),\n        inputName,\n        inputSpec.display_name,\n        inputName\n      )\n    })\n  }\n  /**\n   * @internal Setup stroke styles for the node under various conditions.\n   */\n  function setupStrokeStyles(node: LGraphNode) {\n    node.strokeStyles['running'] = function (this: LGraphNode) {\n      const nodeLocatorId = useWorkflowStore().nodeIdToNodeLocatorId(this.id)\n      const state =\n        useExecutionStore().nodeLocationProgressStates[nodeLocatorId]?.state\n      if (state === 'running') {\n        return { color: '#0f0', lineWidth: 3 }\n      }\n    }\n    node.strokeStyles['dragOver'] = function (this: LGraphNode) {\n      if (useApp().dragOverNode?.id == this.id) {\n        return { color: 'dodgerblue' }\n      }\n    }\n    node.strokeStyles['executionError'] = function (this: LGraphNode) {\n      if (useApp().lastExecutionError?.node_id == this.id) {\n        return { color: LiteGraph.NODE_ERROR_COLOUR, lineWidth: 3 }\n      }\n    }\n  }\n\n  /**\n   * Utility function. Implemented for use with dynamic widgets\n   */\n  function addNodeInput(node: LGraphNode, inputSpec: InputSpec) {\n    addInputSocket(node, inputSpec)\n    addInputWidget(node, inputSpec, { dynamic: true })\n  }\n\n  function validateDynamicGroupWidgets(inputData: InputSpecV1, name: string) {\n    const { template } = zDynamicGroupInputSpec.parse(inputData)[1]\n    const fields = { ...template.required, ...template.optional }\n    for (const [field, spec] of Object.entries(fields)) {\n      if (\n        !widgetStore.widgets.has(spec[1]?.widgetType ?? getInputSpecType(spec))\n      )\n        throw new TypeError(\n          `DynamicGroup field '${name}.${field}' requires a registered widget`\n        )\n    }\n  }\n\n  /**\n   * @internal Add a widget to the node. For both primitive types and custom widgets\n   * (unless `socketless`), an input socket is also added.\n   */\n  function addInputWidget(\n    node: LGraphNode,\n    inputSpec: InputSpec,\n    { dynamic }: { dynamic?: boolean } = {}\n  ) {\n    const widgetInputSpec = { ...inputSpec }\n    if (inputSpec.widgetType) {\n      widgetInputSpec.type = inputSpec.widgetType\n    }\n    const inputName = inputSpec.name\n    const resolveLabel = (fallback: string) =>\n      resolveNodeDefSlotText(\n        'name',\n        nodeDefName(node),\n        inputName,\n        widgetInputSpec.display_name,\n        fallback\n      )\n    const widgetConstructor = widgetStore.widgets.get(widgetInputSpec.type)\n    if (!widgetConstructor || inputSpec.forceInput) return\n\n    const inputData = transformInputSpecV2ToV1(widgetInputSpec)\n    if (widgetInputSpec.type === 'COMFY_DYNAMICGROUP_V3')\n      validateDynamicGroupWidgets(inputData, inputName)\n    const widgetsBefore = new Set(node.widgets ?? [])\n    const result = widgetConstructor(node, inputName, inputData, useApp())\n    const wrappedResult = result && !('type' in result) ? result : undefined\n    const { minWidth = 1, minHeight = 1 } = wrappedResult ?? {}\n    const returnedWidget = result && 'type' in result ? result : result?.widget\n    if (returnedWidget) {\n      // oxlint-disable-next-line typescript/no-unnecessary-condition -- extension widgets may omit options at runtime\n      returnedWidget.options ??= {}\n    }\n    const widget =\n      (node.widgets ?? []).find(\n        (candidate) =>\n          candidate === returnedWidget ||\n          (!widgetsBefore.has(candidate) &&\n            (!returnedWidget || candidate.name === returnedWidget.name))\n      ) ?? (returnedWidget ? toConcreteWidget(returnedWidget, node) : undefined)\n    if (!widget) return\n\n    widget.label = resolveLabel(\n      widget.label ?? widgetInputSpec.display_name ?? inputName\n    )\n    Object.assign(widget.options, {\n      advanced: inputSpec.advanced\n    })\n    if (inputSpec.hidden !== undefined) widget.hidden = inputSpec.hidden\n    if (dynamic) widget.tooltip = inputSpec.tooltip\n\n    if (!widget.options.socketless) {\n      const inputSpecV1 = transformInputSpecV2ToV1(widgetInputSpec)\n      node.addInput(inputName, inputSpec.type, {\n        shape: inputSpec.isOptional ? RenderShape.HollowCircle : undefined,\n        localized_name: resolveLabel(inputName),\n        widget: { name: inputName, [GET_CONFIG]: () => inputSpecV1 }\n      })\n    }\n    const minSize = getMinSize(node)\n    minSize.width = Math.max(minSize.width, minWidth)\n    minSize.height = Math.max(minSize.height, minHeight)\n  }\n\n  /**\n   * @internal Add inputs to the node.\n   */\n  function addInputs(node: LGraphNode, inputs: Record<string, InputSpec>) {\n    // Use input_order if available to ensure consistent widget ordering\n    const orderedInputSpecs = getOrderedInputSpecs(\n      node.constructor.nodeData ?? {},\n      inputs\n    )\n\n    // Create sockets and widgets in the determined order\n    for (const inputSpec of orderedInputSpecs) addInputSocket(node, inputSpec)\n    for (const inputSpec of orderedInputSpecs) addInputWidget(node, inputSpec)\n  }\n\n  /**\n   * @internal Add outputs to the node.\n   */\n  function addOutputs(node: LGraphNode, outputs: OutputSpec[]) {\n    for (const output of outputs) {\n      const { name, is_list } = output\n      // TODO: Fix the typing at the node spec level\n      const type = output.type === 'COMFY_MATCHTYPE_V3' ? '*' : output.type\n      const shapeOptions = is_list ? { shape: LiteGraph.GRID_SHAPE } : {}\n      const typeKey = `dataTypes.${normalizeI18nKey(type)}`\n      const outputOptions = {\n        ...shapeOptions,\n        // If the output name is different from the output type, use the output name.\n        // e.g.\n        // - type (\"INT\"); name (\"Positive\") => translate name\n        // - type (\"FLOAT\"); name (\"FLOAT\") => translate type\n        localized_name:\n          type !== name\n            ? resolveNodeDefSlotText(\n                'name',\n                nodeDefName(node),\n                output.index,\n                name\n              )\n            : st(typeKey, name)\n      }\n      node.addOutput(name, type, outputOptions)\n    }\n  }\n\n  /**\n   * @internal Set the initial size of the node.\n   */\n  function setInitialSize(node: LGraphNode) {\n    const s = node.computeSize()\n    // Expand the width a little to fit widget values on screen.\n    const pad =\n      node.widgets?.length &&\n      !useSettingStore().get('LiteGraph.Node.DefaultPadding')\n    const minSize = getMinSize(node)\n    s[0] = Math.max(minSize.width, s[0] + (pad ? 60 : 0))\n    s[1] = Math.max(minSize.height, s[1])\n    node.setSize(s)\n  }\n\n  function registerSubgraphNodeDef(\n    nodeDefV1: ComfyNodeDefV1,\n    subgraph: Subgraph,\n    instanceData: ExportedSubgraphInstance\n  ) {\n    const node = class ComfyNode extends SubgraphNode {\n      static comfyClass: string\n      static override title: string\n      static override category: string\n      static override nodeData: ComfyNodeDefV1 & ComfyNodeDefV2\n\n      constructor() {\n        super(useApp().rootGraph, subgraph, instanceData)\n\n        subgraph.events.addEventListener('widget-promoted', () => {\n          invalidateSubgraphPseudoWidgetCache(this)\n        })\n\n        subgraph.events.addEventListener('widget-demoted', () => {\n          invalidateSubgraphPseudoWidgetCache(this)\n        })\n\n        setupStrokeStyles(this)\n        addInputs(this, ComfyNode.nodeData.inputs)\n        addOutputs(this, ComfyNode.nodeData.outputs)\n        setInitialSize(this)\n        this.serialize_widgets = true\n        void extensionService.invokeExtensionsAsync('nodeCreated', this)\n      }\n\n      protected override createPromotedHostWidget(\n        input: INodeInputSlot,\n        widgetId: WidgetId,\n        sourceWidget: Readonly<IBaseWidget>\n      ): IBaseWidget | undefined {\n        return createPromotedMultilineWidget({\n          subgraphNode: this,\n          input,\n          widgetId,\n          sourceWidget\n        })\n      }\n\n      /**\n       * Configure the node from a serialised node. Keep 'name', 'type', 'shape',\n       * and 'localized_name' information from the original node definition.\n       */\n      override configure(data: ISerialisedNode): void {\n        const RESERVED_KEYS = ['name', 'type', 'shape', 'localized_name']\n\n        // Note: input name is unique in a node definition, so we can lookup\n        // input by name.\n        const inputByName = new Map<string, ISerialisableNodeInput>(\n          data.inputs?.map((input) => [input.name, input]) ?? []\n        )\n        // Inputs defined by the node definition.\n        const definedInputNames = new Set(\n          this.inputs.map((input) => input.name)\n        )\n        const definedInputs = this.inputs.map((input) => {\n          const inputData = inputByName.get(input.name)\n          return inputData\n            ? {\n                ...inputData,\n                // Whether the input has associated widget follows the\n                // original node definition.\n                ...pick(input, RESERVED_KEYS.concat('widget'))\n              }\n            : input\n        })\n        // Extra inputs that potentially dynamically added by custom js logic.\n        const extraInputs = data.inputs?.filter(\n          (input) => !definedInputNames.has(input.name)\n        )\n        data.inputs = [...definedInputs, ...(extraInputs ?? [])]\n\n        // Note: output name is not unique, so we cannot lookup output by name.\n        // Use index instead.\n        data.outputs = zip(this.outputs, data.outputs ?? []).map(\n          ([output, outputData], index) => {\n            // If there are extra outputs in the serialised node, use them directly.\n            // There are currently custom nodes that dynamically add outputs via\n            // js logic.\n            if (!output) return outputData as ISerialisableNodeOutput\n\n            return outputData\n              ? {\n                  ...outputData,\n                  ...pick(output, RESERVED_KEYS)\n                }\n              : outputAsSerialisable(output, this, index)\n          }\n        )\n\n        data.widgets_values = migrateWidgetsValues(\n          ComfyNode.nodeData.inputs,\n          this.widgets,\n          data.widgets_values ?? []\n        )\n\n        super.configure(data)\n      }\n    }\n\n    addNodeContextMenuHandler(node)\n    addDrawBackgroundHandler(node)\n    addNodeKeyHandler(node)\n    // Note: Some extensions expects node.comfyClass to be set in\n    // `beforeRegisterNodeDef`.\n    node.prototype.comfyClass = nodeDefV1.name\n    node.comfyClass = nodeDefV1.name\n\n    const nodeDef = new ComfyNodeDefImpl(nodeDefV1)\n    node.nodeData = nodeDef\n    LiteGraph.registerNodeType(subgraph.id, node)\n    // Note: Do not following assignments before `LiteGraph.registerNodeType`\n    // because `registerNodeType` will overwrite the assignments.\n    node.category = nodeDef.category\n    node.skip_list = true\n    node.title = nodeDef.display_name || nodeDef.name\n  }\n\n  async function registerNodeDef(nodeId: string, nodeDefV1: ComfyNodeDefV1) {\n    const node = class ComfyNode extends LGraphNode {\n      static comfyClass: string\n      static override title: string\n      static override category: string\n      static override nodeData: ComfyNodeDefV1 & ComfyNodeDefV2\n\n      constructor(title: string) {\n        super(title)\n        setupStrokeStyles(this)\n        addInputs(this, ComfyNode.nodeData.inputs)\n        addOutputs(this, ComfyNode.nodeData.outputs)\n        setInitialSize(this)\n        this.serialize_widgets = true\n\n        // Mark API Nodes yellow by default to distinguish with other nodes.\n        if (ComfyNode.nodeData.api_node) {\n          this.color = LGraphCanvas.node_colors.yellow.color\n          this.bgcolor = LGraphCanvas.node_colors.yellow.bgcolor\n        }\n\n        void extensionService.invokeExtensionsAsync('nodeCreated', this)\n      }\n\n      /**\n       * Configure the node from a serialised node. Keep 'name', 'type', 'shape',\n       * and 'localized_name' information from the original node definition.\n       */\n      override configure(data: ISerialisedNode): void {\n        const RESERVED_KEYS = ['name', 'type', 'shape', 'localized_name']\n\n        // Note: input name is unique in a node definition, so we can lookup\n        // input by name.\n        const inputByName = new Map<string, ISerialisableNodeInput>(\n          data.inputs?.map((input) => [input.name, input]) ?? []\n        )\n        // Inputs defined by the node definition.\n        const definedInputNames = new Set(\n          this.inputs.map((input) => input.name)\n        )\n        const definedInputs = this.inputs.map((input) => {\n          const inputData = inputByName.get(input.name)\n          return inputData\n            ? {\n                ...inputData,\n                // Whether the input has associated widget follows the\n                // original node definition.\n                ...pick(input, RESERVED_KEYS.concat('widget'))\n              }\n            : input\n        })\n        // Extra inputs that potentially dynamically added by custom js logic.\n        const extraInputs = data.inputs?.filter(\n          (input) => !definedInputNames.has(input.name)\n        )\n        data.inputs = [...definedInputs, ...(extraInputs ?? [])]\n\n        // Note: output name is not unique, so we cannot lookup output by name.\n        // Use index instead.\n        data.outputs = zip(this.outputs, data.outputs ?? []).map(\n          ([output, outputData], index) => {\n            // If there are extra outputs in the serialised node, use them directly.\n            // There are currently custom nodes that dynamically add outputs via\n            // js logic.\n            if (!output) return outputData as ISerialisableNodeOutput\n\n            return outputData\n              ? {\n                  ...outputData,\n                  ...pick(output, RESERVED_KEYS)\n                }\n              : outputAsSerialisable(output, this, index)\n          }\n        )\n\n        data.widgets_values = migrateWidgetsValues(\n          ComfyNode.nodeData.inputs,\n          this.widgets ?? [],\n          data.widgets_values ?? []\n        )\n\n        super.configure(data)\n      }\n    }\n\n    addNodeContextMenuHandler(node)\n    addDrawBackgroundHandler(node)\n    addNodeKeyHandler(node)\n    // Note: Some extensions expects node.comfyClass to be set in\n    // `beforeRegisterNodeDef`.\n    node.prototype.comfyClass = nodeDefV1.name\n    node.comfyClass = nodeDefV1.name\n    await extensionService.invokeExtensionsAsync(\n      'beforeRegisterNodeDef',\n      node,\n      nodeDefV1 // Receives V1 NodeDef, and potentially make modifications to it\n    )\n\n    const nodeDef = new ComfyNodeDefImpl(nodeDefV1)\n    node.nodeData = nodeDef\n    LiteGraph.registerNodeType(nodeId, node)\n    // Note: Do not following assignments before `LiteGraph.registerNodeType`\n    // because `registerNodeType` will overwrite the assignments.\n    node.category = nodeDef.category\n    node.title = nodeDef.display_name || nodeDef.name\n\n    // Set skip_list for dev-only nodes based on current DevMode setting\n    // This ensures nodes registered after initial load respect the current setting\n    if (nodeDef.dev_only) {\n      const settingStore = useSettingStore()\n      node.skip_list = !settingStore.get('Comfy.DevMode')\n    }\n  }\n\n  /**\n   * Adds special context menu handling for nodes\n   * e.g. this adds Open Image functionality for nodes that show images\n   * @param {*} node The node to add the menu handler\n   */\n  function addNodeContextMenuHandler(node: typeof LGraphNode) {\n    function getCopyImageOption(img: HTMLImageElement): IContextMenuValue[] {\n      if (typeof window.ClipboardItem === 'undefined') return []\n      return [\n        {\n          content: 'Copy Image',\n          callback: markCoreMediaMenuCallback(async () => {\n            const url = new URL(img.src)\n            url.searchParams.delete('preview')\n\n            try {\n              const data = await fetch(url)\n              const blob = await data.blob()\n              try {\n                await navigator.clipboard.write([\n                  new ClipboardItem({ [blob.type]: blob })\n                ])\n              } catch (error) {\n                // Chrome seems to only support PNG on write, convert and try again\n                if (blob.type !== 'image/png') {\n                  const pngBlob = await reencodeAsPngBlob(\n                    blob,\n                    img.naturalWidth,\n                    img.naturalHeight\n                  )\n                  await navigator.clipboard.write([\n                    new ClipboardItem({ 'image/png': pngBlob })\n                  ])\n                  return\n                }\n                throw error\n              }\n            } catch (error) {\n              toast.warning(\n                t('toastMessages.errorCopyImage', {\n                  error: getErrorMessage(error) ?? t('g.unknownError')\n                })\n              )\n            }\n          }, 'preview')\n        }\n      ]\n    }\n\n    node.prototype.getExtraMenuOptions = function (canvas, options) {\n      if (this.imgs) {\n        let img\n        if (this.imageIndex != null) {\n          img = this.imgs[this.imageIndex]\n        } else if (this.overIndex != null) {\n          img = this.imgs[this.overIndex]\n        }\n        if (img) {\n          options.unshift(\n            {\n              content: 'Open Image',\n              callback: markCoreMediaMenuCallback(() => {\n                const url = getImageFileUrl(img)\n                void openFileInNewTab(url.toString())\n              }, 'preview')\n            },\n            ...getCopyImageOption(img),\n            {\n              content: 'Save Image',\n              callback: markCoreMediaMenuCallback(() => {\n                const url = getImageFileUrl(img)\n                const filename = new URLSearchParams(url.search).get('filename')\n                downloadFile(url.toString(), filename ?? undefined)\n              }, 'preview')\n            }\n          )\n        }\n      }\n\n      options.push({\n        content: 'Bypass',\n        callback: () => {\n          toggleSelectedNodesMode(LGraphEventMode.BYPASS)\n          canvas.setDirty(true, true)\n        }\n      })\n\n      if (!clipspace.returnNode) {\n        options.push({\n          content: 'Copy (Clipspace)',\n          callback: () => {\n            copyToClipspace(this)\n          }\n        })\n\n        if (clipspace.current != null) {\n          options.push({\n            content: 'Paste (Clipspace)',\n            callback: markCoreMediaMenuCallback(() => {\n              pasteFromClipspace(this)\n            }, 'input')\n          })\n        }\n      }\n      if (this instanceof SubgraphNode) {\n        options.unshift(\n          {\n            content: 'Edit Subgraph Widgets',\n            callback: () => {\n              useRightSidePanelStore().openPanel('subgraph')\n            }\n          },\n          {\n            content: 'Unpack Subgraph',\n            callback: () => {\n              const { unpackSubgraph } = useSubgraphOperations()\n              unpackSubgraph()\n            }\n          }\n        )\n      }\n      const [x, y] = canvas.graph_mouse\n      const overWidget = this.getWidgetOnPos(x, y, true)\n      if (overWidget)\n        options.unshift(...getExtraOptionsForWidget(this, overWidget))\n      return []\n    }\n  }\n  function updatePreviews(node: LGraphNode, callback?: () => void) {\n    try {\n      unsafeUpdatePreviews.call(node, callback)\n    } catch (error) {\n      console.error('Error drawing node background', error)\n    }\n  }\n  function unsafeUpdatePreviews(this: LGraphNode, callback?: () => void) {\n    if (this.flags.collapsed) return\n\n    const nodeOutputStore = useNodeOutputStore()\n    const { showAnimatedPreview, removeAnimatedPreview } =\n      useNodeAnimatedImage()\n    const { showCanvasImagePreview, removeCanvasImagePreview } =\n      useNodeCanvasImagePreview()\n\n    const output = nodeOutputStore.getNodeOutputs(this)\n    const preview = nodeOutputStore.getNodePreviews(this)\n\n    const isNewOutput = output && this.images !== output.images\n    const isNewPreview = preview && this.preview !== preview\n\n    if (isNewPreview) this.preview = preview\n    if (isNewOutput) this.images = output.images\n\n    if (isNewOutput || isNewPreview) {\n      this.animatedImages = isAnimatedOutput(output)\n\n      const isVideo = isVideoOutput(output) || isVideoNode(this)\n      if (isVideo) {\n        useNodeVideo(this, callback).showPreview()\n      } else {\n        useNodeImage(this, callback).showPreview()\n      }\n    }\n\n    // Nothing to do\n    if (!this.imgs?.length) return\n\n    if (this.animatedImages) {\n      removeCanvasImagePreview(this)\n      showAnimatedPreview(this)\n    } else {\n      removeAnimatedPreview(this)\n      showCanvasImagePreview(this)\n    }\n  }\n\n  /**\n   * Adds Custom drawing logic for nodes\n   * e.g. Draws images and handles thumbnail navigation on nodes that output images\n   * @param {*} node The node to add the draw handler\n   */\n  function addDrawBackgroundHandler(node: typeof LGraphNode) {\n    /**\n     * @deprecated No longer needed as we use {@link useImagePreviewWidget}\n     */\n    node.prototype.setSizeForImage = function (this: LGraphNode) {\n      console.warn(\n        'node.setSizeForImage is deprecated. Now it has no effect. Please remove the call to it.'\n      )\n    }\n    node.prototype.onDrawBackground = function () {\n      updatePreviews(this)\n\n      if (this instanceof SubgraphNode) {\n        const parentGraph = this.graph\n        for (const interiorNode of getPseudoWidgetPreviewTargets(this)) {\n          updatePreviews(interiorNode, () => {\n            parentGraph?.setDirtyCanvas(true)\n          })\n        }\n      }\n    }\n  }\n\n  function addNodeKeyHandler(node: typeof LGraphNode) {\n    const origNodeOnKeyDown = node.prototype.onKeyDown\n\n    node.prototype.onKeyDown = function (e) {\n      const originalResult: unknown = origNodeOnKeyDown?.call(this, e)\n      if (originalResult === false) {\n        return false\n      }\n\n      if (this.flags.collapsed || !this.imgs || this.imageIndex === null) {\n        return\n      }\n\n      let handled = false\n\n      if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {\n        const imageIndex = this.imageIndex\n        if (imageIndex === undefined) return\n        if (e.key === 'ArrowLeft') {\n          this.imageIndex = imageIndex - 1\n        } else {\n          this.imageIndex = imageIndex + 1\n        }\n        this.imageIndex %= this.imgs.length\n\n        if (this.imageIndex < 0) {\n          this.imageIndex = this.imgs.length + this.imageIndex\n        }\n        handled = true\n      } else if (e.key === 'Escape') {\n        this.imageIndex = null\n        handled = true\n      }\n\n      if (handled) {\n        e.preventDefault()\n        e.stopImmediatePropagation()\n        return false\n      }\n    }\n  }\n\n  function addNodeOnGraph(\n    nodeDef: ComfyNodeDefV1 | ComfyNodeDefV2,\n    options: CreateNodeOptions = {},\n    addOptions?: GraphAddOptions\n  ): LGraphNode | null {\n    options.pos ??= getCanvasCenter()\n\n    if (isBlueprintType(nodeDef.name)) {\n      const canvas = canvasStore.getCanvas()\n      const bp = useSubgraphStore().getBlueprint(nodeDef.name)\n      const items: object = {\n        nodes: bp.nodes,\n        subgraphs: bp.definitions?.subgraphs\n      }\n      const results = canvas._deserializeItems(items, {\n        position: options.pos\n      })\n      if (!results) throw new Error('Failed to add subgraph blueprint')\n      const node = results.nodes.values().next().value\n      if (!node)\n        throw new Error(\n          'Subgraph blueprint was added, but failed to resolve a subgraph Node'\n        )\n      if (addOptions?.ghost) {\n        node.flags.ghost = true\n        canvas.graph?.trigger('node:property:changed', {\n          nodeId: node.id,\n          property: 'flags.ghost',\n          oldValue: false,\n          newValue: true\n        })\n        canvas.startGhostPlacement(node, addOptions.dragEvent)\n      }\n      return node\n    }\n\n    const node = LiteGraph.createNode(\n      nodeDef.name,\n      nodeDef.display_name,\n      options\n    )\n\n    const graph = useWorkflowStore().activeSubgraph ?? useApp().graph\n    if (!node) return null\n\n    graph.add(node, addOptions)\n    return node\n  }\n\n  function getCanvasCenter(): Point {\n    if (!useApp().isGraphReady) return [0, 0]\n    const visibleArea = useApp().canvas.ds.visible_area\n    const [x, y, w, h] = visibleArea\n    return [x + w / 2, y + h / 2]\n  }\n\n  function goToNode(nodeId: SerializedNodeId) {\n    const parsedNodeId = parseNodeId(nodeId)\n    if (!parsedNodeId) return\n    const graphNode = useApp().canvas.graph?.getNodeById(parsedNodeId)\n    if (!graphNode) return\n    useApp().canvas.animateToBounds(graphNode.boundingRect)\n  }\n\n  function ensureBounds(nodes: LGraphNode[]) {\n    for (const node of nodes) {\n      if (!node.boundingRect.every((i) => i === 0)) continue\n      node.updateArea()\n    }\n  }\n\n  /**\n   * Resets the canvas view to the default\n   */\n  function resetView() {\n    const canvas = canvasStore.canvas\n    if (!canvas) return\n\n    canvas.ds.scale = 1\n    canvas.ds.offset = [0, 0]\n    canvas.setDirty(true, true)\n  }\n\n  function fitView() {\n    const canvas = canvasStore.getCanvas()\n    const nodes = canvas.graph?.nodes\n    if (!nodes) return\n    ensureBounds(nodes)\n    const bounds = createBounds(nodes)\n    if (!bounds) return\n\n    canvas.ds.fitToBounds(bounds, {\n      viewport: visibleCanvasViewport(canvas)\n    })\n    canvas.setDirty(true, true)\n  }\n\n  return {\n    registerNodeDef,\n    registerSubgraphNodeDef,\n    addNodeOnGraph,\n    addNodeInput,\n    getCanvasCenter,\n    getExtraOptionsForWidget,\n    goToNode,\n    resetView,\n    fitView,\n    updatePreviews\n  }\n}\n","import QuickLRU from '@alloc/quick-lru'\nimport { useRouteHash } from '@vueuse/router'\nimport { defineStore } from 'pinia'\nimport { computed, ref, shallowRef, watch } from 'vue'\nimport {\n  NavigationFailureType,\n  isNavigationFailure,\n  useRouter\n} from 'vue-router'\n\nimport type { DragAndScaleState } from '@/lib/litegraph/src/DragAndScale'\nimport type { LGraph, Subgraph } from '@/lib/litegraph/src/litegraph'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useCanvasScheduler } from '@/renderer/core/canvas/useCanvasScheduler'\nimport { isUuidShapedSubgraphId } from '@/schemas/subgraphIdSchema'\nimport { useApp } from '@/scripts/appInstance'\nimport type { ComfyApp } from '@/types/comfy'\nimport { useLitegraphService } from '@/services/litegraphService'\nimport { findSubgraphPathById } from '@/utils/graphTraversalUtil'\nimport { isNonNullish, isSubgraph } from '@/utils/typeGuardUtil'\n\nexport const VIEWPORT_CACHE_MAX_SIZE = 32\n\n/**\n * Stores the current subgraph navigation state; a stack representing subgraph\n * navigation history from the root graph to the subgraph that is currently\n * open.\n */\nexport const useSubgraphNavigationStore = defineStore(\n  'subgraphNavigation',\n  () => {\n    const workflowStore = useWorkflowStore()\n    const canvasStore = useCanvasStore()\n    const canvasScheduler = useCanvasScheduler()\n    const router = useRouter()\n    const routeHash = useRouteHash()\n\n    /** The currently opened subgraph. */\n    const activeSubgraph = shallowRef<Subgraph>()\n\n    /** The stack of subgraph IDs from the root graph to the currently opened subgraph. */\n    const idStack = ref<string[]>([])\n\n    /** LRU cache for viewport states. Key: `workflowPath:graphId` */\n    const viewportCache = new QuickLRU<string, DragAndScaleState>({\n      maxSize: VIEWPORT_CACHE_MAX_SIZE\n    })\n\n    /** Get the ID of the root graph for the currently active workflow. */\n    const getCurrentRootGraphId = () => {\n      return canvasStore.canvas?.graph?.rootGraph.id ?? 'root'\n    }\n\n    /**\n     * Set by saveCurrentViewport() (called from beforeLoadNewGraph) to\n     * prevent onNavigated from re-saving a stale viewport during the\n     * workflow switch transition. Uses setTimeout instead of rAF so the\n     * flag resets even when the tab is backgrounded.\n     */\n    let isWorkflowSwitching = false\n    // ── Helpers ──────────────────────────────────────────────────────\n\n    /** Build a workflow-scoped cache key. */\n    function buildCacheKey(\n      graphId: string,\n      workflowRef?: { path?: string } | null\n    ): string {\n      const wf = workflowRef ?? workflowStore.activeWorkflow\n      const prefix = wf?.path ?? ''\n      return `${prefix}:${graphId}`\n    }\n\n    /** ID of the graph currently shown on the canvas. */\n    function getActiveGraphId(): string {\n      return canvasStore.canvas?.subgraph?.id ?? getCurrentRootGraphId()\n    }\n\n    // ── Navigation stack ─────────────────────────────────────────────\n\n    /**\n     * A stack representing subgraph navigation history from the root graph to\n     * the current opened subgraph.\n     */\n    const navigationStack = computed(() =>\n      idStack.value\n        .map((id) => useApp().rootGraph.subgraphs.get(id))\n        .filter(isNonNullish)\n    )\n\n    /**\n     * Restore the navigation stack from a list of subgraph IDs.\n     * @see exportState\n     */\n    const restoreState = (subgraphIds: string[]) => {\n      idStack.value.length = 0\n      for (const id of subgraphIds) idStack.value.push(id)\n    }\n\n    /**\n     * Export the navigation stack as a list of subgraph IDs.\n     * @see restoreState\n     */\n    const exportState = () => [...idStack.value]\n\n    // ── Viewport save / restore ──────────────────────────────────────\n\n    /** Get the current viewport state, or null if the canvas is not available. */\n    const getCurrentViewport = (): DragAndScaleState | null => {\n      const canvas = canvasStore.canvas\n      if (!canvas) return null\n      return {\n        scale: canvas.ds.state.scale,\n        offset: [...canvas.ds.state.offset]\n      }\n    }\n\n    /** Save the current viewport state for a graph. */\n    function saveViewport(graphId: string, workflowRef?: object | null): void {\n      const viewport = getCurrentViewport()\n      if (!viewport) return\n      viewportCache.set(buildCacheKey(graphId, workflowRef), viewport)\n    }\n\n    /** Apply a viewport state to the canvas. */\n    function applyViewport(viewport: DragAndScaleState): void {\n      const canvas = canvasStore.canvas\n      if (!canvas) return\n      canvas.ds.scale = viewport.scale\n      canvas.ds.offset[0] = viewport.offset[0]\n      canvas.ds.offset[1] = viewport.offset[1]\n      canvas.setDirty(true, true)\n    }\n\n    function restoreViewport(graphId: string): void {\n      const canvas = canvasStore.canvas\n      if (!canvas) return\n\n      if (getActiveGraphId() === graphId)\n        canvasScheduler.cancel('subgraph-navigation-fit')\n\n      const expectedKey = buildCacheKey(graphId)\n      const viewport = viewportCache.get(expectedKey)\n      if (viewport) {\n        applyViewport(viewport)\n        return\n      }\n\n      // First visit — fit to content so subgraph nodes are visible\n      canvasScheduler.schedule({\n        key: 'subgraph-navigation-fit',\n        isCurrent: () => getActiveGraphId() === graphId,\n        run: () => {\n          if (!canvas.graph?.nodes.length) return\n          useLitegraphService().fitView()\n        }\n      })\n    }\n\n    // ── Navigation handler ───────────────────────────────────────────\n\n    function onNavigated(\n      subgraph: Subgraph | undefined,\n      prevSubgraph: Subgraph | undefined\n    ): void {\n      // During a workflow switch, beforeLoadNewGraph already saved the\n      // outgoing viewport — skip the save here to avoid caching stale\n      // canvas state from the transition.\n      if (!isWorkflowSwitching) {\n        if (prevSubgraph) {\n          saveViewport(prevSubgraph.id)\n        } else if (subgraph) {\n          saveViewport(getCurrentRootGraphId())\n        }\n      }\n\n      const isInRootGraph = !subgraph\n      if (isInRootGraph) {\n        idStack.value.length = 0\n        restoreViewport(getCurrentRootGraphId())\n        return\n      }\n\n      const path = findSubgraphPathById(subgraph.rootGraph, subgraph.id)\n      const isInReachableSubgraph = !!path\n      if (isInReachableSubgraph) {\n        idStack.value = [...path]\n      } else {\n        idStack.value = [subgraph.id]\n      }\n\n      restoreViewport(subgraph.id)\n    }\n\n    // ── Watchers ─────────────────────────────────────────────────────\n\n    // Sync flush ensures we capture the outgoing viewport before any other\n    // watchers or DOM updates from the same state change mutate the canvas.\n    watch(\n      () => workflowStore.activeSubgraph,\n      (newValue, oldValue) => {\n        onNavigated(newValue, oldValue)\n      },\n      { flush: 'sync' }\n    )\n\n    // Counter so nested/overlapping async navigations don't release\n    // suppression early; gates both the canvasStore.currentGraph watcher\n    // (updateHash) and the routeHash watcher to prevent re-entrant\n    // navigateToHash calls during router.replace().\n    let blockNavDepth = 0\n    let initialLoad = true\n    let hashUpdateTail: Promise<void> = Promise.resolve()\n    type GraphNavigationIntent = {\n      id: number\n      hash: string\n      source: 'graph' | 'route'\n    }\n    type NavigationIntent =\n      | GraphNavigationIntent\n      | { id: number; source: 'workflow' }\n    const routeWriteStateKey = 'comfySubgraphNavigationWrite'\n    const pendingRouteWrites = new Map<number, string>()\n    // D14: the reset-suppression flag dies with shared-graph loading at\n    // ECS per-document scoping; the intent ids guard the router and survive.\n    let deferredNavigationIntent: GraphNavigationIntent | undefined\n    let latestNavigationIntent: NavigationIntent | undefined\n    let navigationIntentId = 0\n    let routeWriteId = 0\n    let blockedRouteHash: string | undefined\n    let pendingWorkflowResetGraph: ComfyApp['rootGraph'] | undefined\n\n    function createNavigationIntent(\n      hash: string,\n      source: GraphNavigationIntent['source']\n    ): GraphNavigationIntent {\n      const intent = { id: ++navigationIntentId, hash, source }\n      latestNavigationIntent = intent\n      return intent\n    }\n\n    function beginWorkflowNavigation(): number {\n      const intent = { id: ++navigationIntentId, source: 'workflow' as const }\n      latestNavigationIntent = intent\n      return intent.id\n    }\n\n    /**\n     * Releases a workflow-load intent whose load FAILED: while it stays the\n     * newest intent it suppresses the surviving graph's hash forever, so\n     * clear it and republish the live graph.\n     */\n    function endWorkflowNavigation(navigationId: number): void {\n      if (\n        latestNavigationIntent?.source !== 'workflow' ||\n        latestNavigationIntent.id !== navigationId\n      ) {\n        return\n      }\n      latestNavigationIntent = undefined\n      void updateHash('graph')\n    }\n\n    async function withNavBlocked<T>(\n      op: () => Promise<T>,\n      blockedHash: string\n    ): Promise<T> {\n      const previousBlockedRouteHash = blockedRouteHash\n      blockedRouteHash = blockedHash\n      blockNavDepth++\n      try {\n        return await op()\n      } finally {\n        blockNavDepth--\n        blockedRouteHash = previousBlockedRouteHash\n      }\n    }\n\n    function ensureCanvasOnRoot() {\n      const root = useApp().rootGraphOrUndefined\n      const canvas = canvasStore.canvas\n      if (!root || !canvas) return\n      if (canvas.graph?.id !== root.id) canvas.setGraph(root)\n    }\n\n    async function redirectToRoot(reason: string, navigationId: number) {\n      if (navigationId !== navigationIntentId) return\n      const root = useApp().rootGraph\n      const rootHash = '#' + root.id\n      console.warn(`[subgraphNavigation] ${reason}; redirecting to root graph`)\n      try {\n        await withNavBlocked(() => writeRouteHash(rootHash, true), rootHash)\n      } finally {\n        if (navigationId === navigationIntentId) ensureCanvasOnRoot()\n      }\n    }\n\n    async function navigateToHash(newHash: string, navigationId: number) {\n      const root = useApp().rootGraph\n      const locatorId = newHash.slice(1) || root.id\n      const canvas = canvasStore.getCanvas()\n\n      const isRoot = locatorId === root.id\n      const targetGraph = isRoot\n        ? root\n        : isUuidShapedSubgraphId(locatorId)\n          ? root.subgraphs.get(locatorId)\n          : undefined\n      if (targetGraph) {\n        if (canvas.graph?.id === targetGraph.id) return\n        return withNavBlocked(async () => {\n          canvas.setGraph(targetGraph)\n        }, newHash)\n      }\n\n      //Search all open workflows\n      for (const workflow of workflowStore.openWorkflows) {\n        const { activeState } = workflow\n        if (!activeState) continue\n        const subgraphs = activeState.definitions?.subgraphs ?? []\n        for (const graph of [activeState, ...subgraphs]) {\n          if (graph.id !== locatorId) continue\n          // This will trigger a navigation, which can break forward history.\n          // After openWorkflow resolves, app.rootGraph has been swapped, so we\n          // intentionally re-read app.rootGraph below instead of using the\n          // `root` captured at function entry.\n          try {\n            await withNavBlocked(\n              () =>\n                useWorkflowService().openWorkflow(workflow, {\n                  navigationIntentId: navigationId\n                }),\n              newHash\n            )\n          } catch (err) {\n            if (navigationId !== navigationIntentId) return\n            reportError(err, {\n              surface: 'graph',\n              errorType: 'workflow_navigation_failure',\n              level: 'warning',\n              context: { stage: 'recovery' }\n            })\n            return redirectToRoot('workflow load failed', navigationId)\n          }\n          if (navigationId !== navigationIntentId) return\n          const loadedGraph =\n            useApp().rootGraph.id === locatorId\n              ? useApp().rootGraph\n              : useApp().rootGraph.subgraphs.get(locatorId)\n          if (!loadedGraph) {\n            return redirectToRoot(\n              'subgraph not found after workflow load',\n              navigationId\n            )\n          }\n          if (canvas.graph?.id === loadedGraph.id) return\n          return withNavBlocked(async () => {\n            canvas.setGraph(loadedGraph)\n          }, newHash)\n        }\n      }\n\n      await redirectToRoot(`subgraph not found: ${locatorId}`, navigationId)\n    }\n\n    async function safeRouterCall(op: () => Promise<unknown>, label: string) {\n      try {\n        return !isNavigationFailure(await op())\n      } catch (err) {\n        if (\n          !isNavigationFailure(err, NavigationFailureType.duplicated) &&\n          !isNavigationFailure(err, NavigationFailureType.cancelled)\n        ) {\n          console.warn(`[subgraphNavigation] ${label} rejected`, err)\n        }\n        return false\n      }\n    }\n\n    async function writeRouteHash(hash: string, replace: boolean) {\n      const writeId = ++routeWriteId\n      pendingRouteWrites.set(writeId, hash)\n      const target = {\n        hash,\n        state: { [routeWriteStateKey]: writeId }\n      }\n      try {\n        return await safeRouterCall(\n          () => (replace ? router.replace(target) : router.push(target)),\n          replace ? 'router.replace' : 'router.push'\n        )\n      } finally {\n        pendingRouteWrites.delete(writeId)\n      }\n    }\n\n    async function syncGraphHash(intent: GraphNavigationIntent) {\n      if (intent.id !== navigationIntentId) return false\n      if (!routeHash.value) {\n        const rootHash = '#' + useApp().rootGraph.id\n        if (!(await writeRouteHash(rootHash, true))) return false\n        if (intent.id !== navigationIntentId) return false\n      }\n      const currentId = routeHash.value?.slice(1)\n      if (intent.hash.slice(1) === currentId) return true\n\n      return writeRouteHash(intent.hash, false)\n    }\n\n    function queueGraphHash(intent: GraphNavigationIntent): Promise<boolean> {\n      const result = hashUpdateTail.then(() => syncGraphHash(intent))\n      hashUpdateTail = result.then(\n        () => undefined,\n        () => undefined\n      )\n      return result\n    }\n\n    async function applyNavigationIntent(intent: GraphNavigationIntent) {\n      await navigateToHash(intent.hash, intent.id)\n      if (blockNavDepth > 0) return\n\n      const deferredIntent = deferredNavigationIntent\n      if (deferredIntent?.id === navigationIntentId) {\n        deferredNavigationIntent = undefined\n        return applyNavigationIntent(deferredIntent)\n      }\n\n      if (intent.source === 'graph' && intent.id === navigationIntentId) {\n        await queueGraphHash(intent)\n      }\n    }\n\n    async function navigateToGraph(targetGraph: LGraph): Promise<boolean> {\n      const canvas = canvasStore.canvas\n      const targetId = targetGraph.id\n      const belongsToCurrentWorkflow =\n        targetGraph === useApp().rootGraph ||\n        (targetGraph.rootGraph === useApp().rootGraph &&\n          useApp().rootGraph.subgraphs.get(targetId) === targetGraph)\n\n      if (!canvas?.graph || !targetId || !belongsToCurrentWorkflow) return false\n      if (canvas.graph === targetGraph) return true\n\n      const previousGraph = canvas.graph\n      const intent = createNavigationIntent('#' + targetId, 'graph')\n      await withNavBlocked(\n        async () => canvas.setGraph(targetGraph),\n        intent.hash\n      )\n      if (intent.id !== navigationIntentId) return false\n\n      const hashWritten = await queueGraphHash(intent)\n      if (\n        !hashWritten &&\n        intent.id === navigationIntentId &&\n        canvas.graph === targetGraph\n      ) {\n        await withNavBlocked(\n          async () => canvas.setGraph(previousGraph),\n          '#' + previousGraph.id\n        )\n      }\n      return (\n        hashWritten &&\n        intent.id === navigationIntentId &&\n        canvas.graph === targetGraph\n      )\n    }\n\n    async function updateHash(\n      source: 'graph' | 'workflow-load' = 'graph',\n      workflowNavigationId?: number,\n      currentGraph?: LGraph | null\n    ): Promise<void> {\n      const graph = currentGraph ?? canvasStore.getCanvas().graph\n      if (source === 'workflow-load') {\n        pendingWorkflowResetGraph = undefined\n        if (\n          blockNavDepth > 0 &&\n          workflowNavigationId === navigationIntentId &&\n          latestNavigationIntent?.source === 'workflow' &&\n          graph?.id\n        ) {\n          deferredNavigationIntent = {\n            id: workflowNavigationId,\n            hash: '#' + graph.id,\n            source: 'graph'\n          }\n          return Promise.resolve()\n        }\n        if (blockNavDepth > 0) return Promise.resolve()\n        if (workflowNavigationId !== undefined) {\n          if (workflowNavigationId !== navigationIntentId) {\n            const latestIntent = latestNavigationIntent\n            return latestIntent && latestIntent.source !== 'workflow'\n              ? applyNavigationIntent(latestIntent)\n              : Promise.resolve()\n          }\n        }\n      }\n      if (graph === pendingWorkflowResetGraph) {\n        pendingWorkflowResetGraph = undefined\n        return Promise.resolve()\n      }\n\n      const newId = graph?.id ?? ''\n      if (initialLoad) {\n        initialLoad = false\n        if (!routeHash.value) return Promise.resolve()\n        return applyNavigationIntent(\n          createNavigationIntent(routeHash.value, 'route')\n        ).then(() => {\n          const activeGraph = canvasStore.getCanvas().graph\n          if (isSubgraph(activeGraph)) {\n            workflowStore.activeSubgraph = activeGraph\n          }\n        })\n      }\n\n      if (!newId) return Promise.resolve()\n      const newHash = '#' + newId\n      if (newHash === routeHash.value) return Promise.resolve()\n      if (blockNavDepth > 0 && newHash === blockedRouteHash) {\n        return Promise.resolve()\n      }\n\n      const intent = createNavigationIntent(newHash, 'graph')\n      if (blockNavDepth > 0) {\n        deferredNavigationIntent = intent\n        return Promise.resolve()\n      }\n\n      await queueGraphHash(intent)\n    }\n    watch(\n      () => canvasStore.currentGraph,\n      (graph) => void updateHash('graph', undefined, graph),\n      { flush: 'sync' }\n    )\n    watch(\n      routeHash,\n      (newHash) => {\n        initialLoad = false\n        const hash = String(newHash)\n        const stateWriteId = router.options.history.state[routeWriteStateKey]\n        if (\n          typeof stateWriteId === 'number' &&\n          pendingRouteWrites.get(stateWriteId) === hash\n        ) {\n          pendingRouteWrites.delete(stateWriteId)\n          return\n        }\n        const intent = createNavigationIntent(hash, 'route')\n        if (blockNavDepth > 0) {\n          deferredNavigationIntent = intent\n          return\n        }\n        void applyNavigationIntent(intent)\n      },\n      { flush: 'sync' }\n    )\n\n    /** Save the current viewport for the active graph/workflow. Called by\n     *  workflowService.beforeLoadNewGraph() before the canvas is overwritten. */\n    function saveCurrentViewport(suppressWorkflowReset = true): void {\n      saveViewport(getActiveGraphId())\n      const graph = canvasStore.getCanvas().graph\n      pendingWorkflowResetGraph =\n        suppressWorkflowReset && graph !== useApp().rootGraph\n          ? useApp().rootGraph\n          : undefined\n      isWorkflowSwitching = true\n      setTimeout(() => {\n        isWorkflowSwitching = false\n      }, 0)\n    }\n\n    return {\n      activeSubgraph,\n      navigationStack,\n      restoreState,\n      exportState,\n      saveViewport,\n      restoreViewport,\n      saveCurrentViewport,\n      beginWorkflowNavigation,\n      endWorkflowNavigation,\n      navigateToGraph,\n      updateHash,\n      /** @internal Exposed for test assertions only. */\n      viewportCache\n    }\n  }\n)\n","import { useDebounceFn } from '@vueuse/core'\nimport _ from 'es-toolkit/compat'\n\nimport { assert } from '@/base/assert'\nimport { LAYER_EDITOR_DIALOG_KEY } from '@/renderer/extensions/layerEditor/layerEditorDialogKey'\nimport type { CanvasPointerEvent } from '@/lib/litegraph/src/litegraph'\nimport { LGraphCanvas, LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport type {\n  ComfyWorkflow,\n  WorkflowChangeTracker\n} from '@/platform/workflow/management/stores/comfyWorkflow'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport type { ComfyWorkflowJSON } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport {\n  collectSubgraphDefinitions,\n  parseFlattenableSubgraphDefinitions\n} from '@/platform/workflow/core/utils/workflowFlattening'\nimport type { ExecutedWsMessage } from '@/platform/remote/comfyui/execution/types'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { useNodeOutputStore } from '@/stores/nodeOutputStore'\nimport { useQueueSettingsStore } from '@/stores/queueSettingsStore'\nimport { useSubgraphNavigationStore } from '@/stores/subgraphNavigationStore'\nimport { serializeNodeId } from '@/types/nodeId'\nimport { isSelectOnly } from '@/utils/litegraphUtil'\nimport { isModalOpen } from '@/utils/modalUtil'\n\nimport { api } from './api'\nimport { useApp } from '@/scripts/appInstance'\nimport { clipspace } from '@/scripts/clipspace'\n\nfunction clone<T>(obj: T): T {\n  return JSON.parse(JSON.stringify(obj))\n}\n\nfunction withoutExecutionOrder(nodes: ComfyWorkflowJSON['nodes']) {\n  return nodes.map((node) => _.omit(node, ['order']))\n}\n\nfunction withNormalizedNodeSizes(state: ComfyWorkflowJSON): ComfyWorkflowJSON {\n  const comparable = clone(state)\n  const subgraphs = collectSubgraphDefinitions(\n    parseFlattenableSubgraphDefinitions(comparable.definitions?.subgraphs ?? [])\n  )\n  const nodes = [\n    ...comparable.nodes,\n    ...subgraphs.flatMap((subgraph) => subgraph.nodes)\n  ]\n  for (const node of nodes) {\n    if ('size' in node) node.size = [0, 0]\n  }\n  return comparable\n}\n\nfunction matchesRestoredTarget(\n  actual: ComfyWorkflowJSON,\n  target: ComfyWorkflowJSON,\n  previous: ComfyWorkflowJSON\n): boolean {\n  if (ChangeTracker.graphEqual(actual, target)) return true\n  const comparableTarget = withNormalizedNodeSizes(target)\n  return (\n    ChangeTracker.graphEqual(\n      withNormalizedNodeSizes(actual),\n      comparableTarget\n    ) &&\n    !ChangeTracker.graphEqual(\n      comparableTarget,\n      withNormalizedNodeSizes(previous)\n    )\n  )\n}\n\nfunction isActiveTracker(tracker: ChangeTracker): boolean {\n  return useWorkflowStore().activeWorkflow?.changeTracker === tracker\n}\n\nfunction historyShortcut(e: KeyboardEvent): 'undo' | 'redo' | undefined {\n  if (!(e.ctrlKey || e.metaKey) || e.altKey) return\n  const key = e.key.toUpperCase()\n  if (key === 'Y' && !e.shiftKey) return 'redo'\n  if (key === 'Z') return e.shiftKey ? 'redo' : 'undo'\n}\n\nfunction isAutoQueueOnChange(): boolean {\n  const { ui } = useApp()\n  return (\n    useQueueSettingsStore().mode === 'change' ||\n    (ui.autoQueueEnabled && ui.autoQueueMode === 'change')\n  )\n}\n\nconst nonExecutionGraphProperties = new Set([\n  'id',\n  'revision',\n  'last_node_id',\n  'last_link_id',\n  'state',\n  'groups',\n  'config',\n  'extra',\n  'version',\n  'models',\n  'reroutes',\n  'floatingLinks',\n  'subgraphs',\n  'definitions',\n  'name',\n  'description',\n  'category',\n  'essentials_category'\n])\n\nconst nonExecutionNodeProperties = new Set([\n  'pos',\n  'size',\n  // Node flags, including skip_repeated_outputs, only affect the editor.\n  'flags',\n  'order',\n  'color',\n  'bgcolor',\n  'boxcolor',\n  'shape',\n  'showAdvanced',\n  'title'\n])\n\nconst nonExecutionSlotProperties = new Set([\n  'localized_name',\n  'label',\n  'shape',\n  'color_off',\n  'color_on',\n  'pos',\n  'link',\n  'links',\n  'linkIds',\n  'slot_index'\n])\n\nconst nonExecutionBoundaryNodeProperties = new Set(['bounding', 'pinned'])\nconst nonExecutableNodeTypes = new Set(['Note', 'MarkdownNote'])\n\nfunction isRecord(value: unknown): value is Record<string, unknown> {\n  return typeof value === 'object' && value !== null && !Array.isArray(value)\n}\n\nfunction asRecord(value: unknown): Record<string, unknown> | null {\n  return isRecord(value) ? value : null\n}\n\nfunction omitProperties(\n  record: Record<string, unknown>,\n  properties: ReadonlySet<string>\n): Record<string, unknown> {\n  return Object.fromEntries(\n    Object.entries(record).filter(([key]) => !properties.has(key))\n  )\n}\n\nfunction getExecutionSlotState(value: unknown): unknown {\n  const slot = asRecord(value)\n  return slot ? omitProperties(slot, nonExecutionSlotProperties) : value\n}\n\nfunction getExecutionNodeState(value: unknown): unknown {\n  const node = asRecord(value)\n  if (!node) return value\n\n  const executionNode = omitProperties(node, nonExecutionNodeProperties)\n  if ('id' in node) {\n    executionNode.id = normalizeNodeId(node.id)\n  }\n  if (Array.isArray(node.inputs)) {\n    executionNode.inputs = node.inputs.map(getExecutionSlotState)\n  }\n  if (Array.isArray(node.outputs)) {\n    executionNode.outputs = node.outputs.map(getExecutionSlotState)\n  }\n  return executionNode\n}\n\nfunction getExecutionBoundaryNodeState(value: unknown): unknown {\n  const node = asRecord(value)\n  if (!node) return value\n\n  const executionNode = omitProperties(node, nonExecutionBoundaryNodeProperties)\n  if ('id' in node) {\n    executionNode.id = normalizeNodeId(node.id)\n  }\n  return executionNode\n}\n\nfunction getExecutionLinkState(value: unknown): unknown {\n  if (Array.isArray(value)) {\n    return [\n      normalizeNodeId(value[1]),\n      normalizeSlotIndex(value[2]),\n      normalizeNodeId(value[3]),\n      normalizeSlotIndex(value[4])\n    ]\n  }\n\n  const link = asRecord(value)\n  if (!link) return value\n  return [\n    normalizeNodeId(link.origin_id),\n    normalizeSlotIndex(link.origin_slot),\n    normalizeNodeId(link.target_id),\n    normalizeSlotIndex(link.target_slot)\n  ]\n}\n\nfunction normalizeNodeId(value: unknown): unknown {\n  return typeof value === 'number' || typeof value === 'string'\n    ? serializeNodeId(value)\n    : value\n}\n\nfunction normalizeSlotIndex(value: unknown): unknown {\n  if (typeof value !== 'string') return value\n\n  const index = parseInt(value)\n  return Number.isNaN(index) ? value : index\n}\n\nfunction isExecutableNodeState(value: unknown): boolean {\n  const node = asRecord(value)\n  return (\n    !node ||\n    typeof node.type !== 'string' ||\n    !nonExecutableNodeTypes.has(node.type)\n  )\n}\n\nfunction getExecutionDefinitionsState(value: unknown): unknown {\n  const definitions = asRecord(value)\n  if (!definitions || !Array.isArray(definitions.subgraphs)) return value\n\n  return {\n    ...definitions,\n    subgraphs: _.sortBy(\n      definitions.subgraphs,\n      (subgraph) => asRecord(subgraph)?.id\n    ).map(getExecutionGraphState)\n  }\n}\n\nfunction getExecutionGraphState(value: unknown): unknown {\n  const graph = asRecord(value)\n  if (!graph) return value\n\n  const executionGraph = omitProperties(graph, nonExecutionGraphProperties)\n  if (Array.isArray(graph.nodes)) {\n    executionGraph.nodes = _.sortBy(\n      graph.nodes.filter(isExecutableNodeState).map(getExecutionNodeState),\n      (node) => asRecord(node)?.id\n    )\n  }\n  if (Array.isArray(graph.links)) {\n    executionGraph.links = _.sortBy(\n      graph.links.map(getExecutionLinkState),\n      (link) => JSON.stringify(link)\n    )\n  } else if (!('links' in graph)) {\n    executionGraph.links = []\n  }\n  if (Array.isArray(graph.inputs)) {\n    executionGraph.inputs = graph.inputs.map(getExecutionSlotState)\n  }\n  if (Array.isArray(graph.outputs)) {\n    executionGraph.outputs = graph.outputs.map(getExecutionSlotState)\n  }\n  if ('inputNode' in graph) {\n    executionGraph.inputNode = getExecutionBoundaryNodeState(graph.inputNode)\n  }\n  if ('outputNode' in graph) {\n    executionGraph.outputNode = getExecutionBoundaryNodeState(graph.outputNode)\n  }\n  if ('definitions' in graph) {\n    executionGraph.definitions = getExecutionDefinitionsState(graph.definitions)\n  }\n  return executionGraph\n}\n\nconst reportedInactiveCalls = new Set<string>()\n\nfunction reportInactiveTrackerCall(method: string, workflowPath: string) {\n  const key = `${method}:${workflowPath}`\n  if (reportedInactiveCalls.has(key)) return\n  reportedInactiveCalls.add(key)\n  assert(false, `ChangeTracker.${method}() called on inactive tracker`)\n}\n\nexport class ChangeTracker implements WorkflowChangeTracker {\n  static MAX_HISTORY = 50\n  /**\n   * Guard flag to prevent captureCanvasState from running during loadGraphData.\n   * Between rootGraph.configure() and afterLoadNewGraph(), the rootGraph\n   * contains the NEW workflow's data while activeWorkflow still points to\n   * the OLD workflow. Any captureCanvasState call in that window would\n   * serialize the wrong graph into the old workflow's activeState, corrupting it.\n   */\n  static isLoadingGraph = false\n  /**\n   * The active state of the workflow.\n   */\n  activeState: ComfyWorkflowJSON\n  undoQueue: ComfyWorkflowJSON[] = []\n  redoQueue: ComfyWorkflowJSON[] = []\n  changeCount: number = 0\n  /**\n   * Whether the redo/undo restoring is in progress.\n   */\n  _restoringState: boolean = false\n  private restoreChain?: Promise<void>\n\n  ds?: { scale: number; offset: [number, number] }\n  nodeOutputs?: Partial<Record<string, ExecutedWsMessage['output']>>\n\n  private subgraphState?: {\n    navigation: string[]\n  }\n\n  constructor(\n    /**\n     * The workflow that this change tracker is tracking\n     */\n    public workflow: ComfyWorkflow,\n    /**\n     * The initial state of the workflow\n     */\n    public initialState: ComfyWorkflowJSON\n  ) {\n    this.activeState = initialState\n  }\n\n  /**\n   * Save the current state as the initial state.\n   */\n  reset(state?: ComfyWorkflowJSON) {\n    if (state) this.activeState = clone(state)\n    if (this._restoringState) return\n\n    this.initialState = clone(this.activeState)\n  }\n\n  store() {\n    const { ds } = useApp().canvas\n    this.ds = { scale: ds.scale, offset: [ds.offset[0], ds.offset[1]] }\n    this.nodeOutputs = useNodeOutputStore().snapshotOutputs()\n    const navigation = useSubgraphNavigationStore().exportState()\n    // Always store the navigation state, even if empty (root level)\n    this.subgraphState = { navigation }\n  }\n\n  /**\n   * Freeze this tracker's state before the workflow goes inactive.\n   * Always calls store() to preserve viewport/outputs. Calls\n   * captureCanvasState() only when not in undo/redo (to avoid\n   * corrupting undo history with intermediate graph state).\n   *\n   * PRECONDITION: must be called while this workflow is still the active one\n   * (before the activeWorkflow pointer is moved). If called after the pointer\n   * has already moved, this is a no-op to avoid freezing wrong viewport data.\n   *\n   * @internal Not part of the public extension API.\n   */\n  deactivate() {\n    if (!isActiveTracker(this)) {\n      reportInactiveTrackerCall('deactivate', this.workflow.path)\n      return\n    }\n    if (!this._restoringState) this.captureCanvasState()\n    this.store()\n  }\n\n  /**\n   * Ensure activeState is up-to-date for persistence.\n   * Active workflow: flushes canvas → activeState.\n   * Inactive workflow: no-op (activeState was frozen by deactivate()).\n   *\n   * @internal Not part of the public extension API.\n   */\n  prepareForSave() {\n    if (isActiveTracker(this)) this.captureCanvasState()\n  }\n\n  restore() {\n    const app = useApp()\n    if (this.ds) {\n      app.canvas.ds.scale = this.ds.scale\n      app.canvas.ds.offset = this.ds.offset\n    }\n    if (this.nodeOutputs) {\n      useNodeOutputStore().restoreOutputs(this.nodeOutputs)\n    }\n    if (this.subgraphState) {\n      const { navigation } = this.subgraphState\n      const firstInvalidIndex = navigation.findIndex(\n        (id) => !app.rootGraph.subgraphs.has(id)\n      )\n      if (firstInvalidIndex !== -1) navigation.splice(firstInvalidIndex)\n      useSubgraphNavigationStore().restoreState(navigation)\n\n      const activeId = navigation.at(-1)\n      if (activeId) {\n        // Navigate to the saved subgraph\n        const subgraph = app.rootGraph.subgraphs.get(activeId)\n        if (subgraph) {\n          app.canvas.setGraph(subgraph)\n        }\n      } else {\n        // Empty navigation array means root level\n        app.canvas.setGraph(app.rootGraph)\n      }\n    }\n  }\n\n  updateModified(previousState?: ComfyWorkflowJSON) {\n    // Get the workflow from the store as ChangeTracker is raw object, i.e.\n    // `this.workflow` is not reactive.\n    const workflow = useWorkflowStore().getWorkflowByPath(this.workflow.path)\n    if (workflow) {\n      workflow.isModified = !ChangeTracker.graphEqual(\n        this.initialState,\n        this.activeState\n      )\n    }\n\n    const autoQueueGraphChanged =\n      !!previousState &&\n      isAutoQueueOnChange() &&\n      !_.isEqual(\n        getExecutionGraphState(previousState),\n        getExecutionGraphState(this.activeState)\n      )\n\n    api.dispatchCustomEvent('graphChanged', this.activeState)\n    if (autoQueueGraphChanged) {\n      api.dispatchCustomEvent('autoQueueGraphChanged')\n    }\n  }\n\n  /**\n   * Snapshot the current canvas state into activeState and push undo.\n   * INVARIANT: only the active workflow's tracker may read from the canvas.\n   * Calling this on an inactive tracker would capture the wrong graph.\n   */\n  captureCanvasState() {\n    const isUndoRedoing = this._restoringState\n    const isInsideChangeTransaction = this.changeCount > 0\n    if (\n      !useApp().isGraphReady ||\n      isInsideChangeTransaction ||\n      isUndoRedoing ||\n      ChangeTracker.isLoadingGraph\n    )\n      return\n\n    if (!isActiveTracker(this)) {\n      reportInactiveTrackerCall('captureCanvasState', this.workflow.path)\n      return\n    }\n\n    const currentState = clone(\n      useApp().rootGraph.serialize()\n    ) as ComfyWorkflowJSON\n    if (!ChangeTracker.graphEqual(this.activeState, currentState)) {\n      const previousState = this.activeState\n      this.undoQueue.push(previousState)\n      if (this.undoQueue.length > ChangeTracker.MAX_HISTORY) {\n        this.undoQueue.shift()\n      }\n\n      this.activeState = currentState\n      this.redoQueue.length = 0\n      this.updateModified(previousState)\n      void this.squashState()\n    }\n  }\n  squashState = useDebounceFn(() => {\n    if (\n      this !== useWorkflowStore().activeWorkflow?.changeTracker ||\n      ChangeTracker.isLoadingGraph\n    )\n      return\n\n    const currentState = clone(\n      useApp().rootGraph.serialize()\n    ) as ComfyWorkflowJSON\n    if (ChangeTracker.graphEqual(this.activeState, currentState)) return\n\n    const previousState = this.activeState\n    this.activeState = currentState\n    this.updateModified(previousState)\n  }, 50)\n\n  /** @deprecated Use {@link captureCanvasState} instead. */\n  checkState() {\n    if (!ChangeTracker._checkStateWarned) {\n      ChangeTracker._checkStateWarned = true\n      console.warn(\n        'checkState() is deprecated — use captureCanvasState() instead.'\n      )\n    }\n    this.captureCanvasState()\n  }\n\n  private static _checkStateWarned = false\n\n  static resetCheckStateWarningForTest() {\n    ChangeTracker._checkStateWarned = false\n  }\n\n  async updateState(source: ComfyWorkflowJSON[], target: ComfyWorkflowJSON[]) {\n    const restore = async () => {\n      if (this._restoringState || source.length === 0) return\n      const prevState = source.pop()\n      if (prevState) {\n        const previousState = this.activeState\n        const restoresSavedState = ChangeTracker.graphEqual(\n          prevState,\n          this.initialState\n        )\n        let restored = false\n        this._restoringState = true\n        try {\n          const result = await useApp().loadGraphData(\n            prevState,\n            false,\n            false,\n            this.workflow,\n            {\n              checkForRerouteMigration: false,\n              silentAssetErrors: true\n            }\n          )\n          restored = result !== false && result !== undefined\n        } finally {\n          this._restoringState = false\n          restored ||=\n            !ChangeTracker.graphEqual(this.activeState, previousState) &&\n            matchesRestoredTarget(this.activeState, prevState, previousState)\n          if (restored) {\n            target.push(previousState)\n            if (restoresSavedState) this.initialState = clone(this.activeState)\n          } else {\n            source.push(prevState)\n          }\n          if (restored) this.updateModified(previousState)\n        }\n      }\n    }\n    this.restoreChain = (this.restoreChain ?? Promise.resolve()).then(\n      restore,\n      restore\n    )\n    return this.restoreChain\n  }\n\n  async undo() {\n    await this.updateState(this.undoQueue, this.redoQueue)\n  }\n\n  async redo() {\n    await this.updateState(this.redoQueue, this.undoQueue)\n  }\n\n  async undoRedo(e: KeyboardEvent, selectOnly = isSelectOnly(useApp().canvas)) {\n    const shortcut = historyShortcut(e)\n    if (!shortcut) return\n    if (!selectOnly) {\n      await (shortcut === 'redo' ? this.redo() : this.undo())\n    }\n    return true\n  }\n\n  beforeChange() {\n    this.changeCount++\n  }\n\n  afterChange() {\n    if (!--this.changeCount) {\n      this.captureCanvasState()\n    }\n  }\n\n  static init() {\n    const getCurrentChangeTracker = () =>\n      useWorkflowStore().activeWorkflow?.changeTracker\n    const captureState = () => getCurrentChangeTracker()?.captureCanvasState()\n    const dialogStore = useDialogStore()\n\n    let keyIgnored = false\n    window.addEventListener(\n      'keydown',\n      (e: KeyboardEvent) => {\n        // Do not trigger on repeat events (Holding down a key)\n        // This can happen when user is holding down \"Space\" to pan the canvas.\n        if (e.repeat) return\n\n        // If the mask editor is opened, we don't want to trigger on key events\n        if (clipspace.maskEditorIsOpened?.()) return\n\n        const activeEl = document.activeElement\n        if (\n          !isAutoQueueOnChange() &&\n          (activeEl?.tagName === 'INPUT' ||\n            activeEl?.tagName === 'TEXTAREA' ||\n            (activeEl instanceof HTMLElement && activeEl.isContentEditable))\n        ) {\n          // Text editors own their history. Bail out before the document-wide\n          // modal probes, whose cost otherwise scales with transcript size.\n          return\n        }\n        if (isModalOpen(dialogStore.dialogStack.length)) return\n\n        // The layer editor has its own session-local undo history\n        if (useDialogStore().isDialogOpen(LAYER_EDITOR_DIALOG_KEY)) return\n\n        keyIgnored =\n          e.key === 'Control' ||\n          e.key === 'Shift' ||\n          e.key === 'Alt' ||\n          e.key === 'Meta'\n        if (keyIgnored) return\n\n        const selectOnlyAtKeydown = isSelectOnly(useApp().canvas)\n        requestAnimationFrame(async () => {\n          let bindInputEl: Element | null = null\n          // If we are auto queue in change mode then we do want to trigger on inputs\n          if (!isAutoQueueOnChange()) {\n            bindInputEl = activeEl\n          }\n\n          const changeTracker = getCurrentChangeTracker()\n          if (!changeTracker) return\n\n          // Check if this is a ctrl+z ctrl+y\n          if (await changeTracker.undoRedo(e, selectOnlyAtKeydown)) return\n\n          // If our active element is some type of input then handle changes after they're done\n          if (ChangeTracker.bindInput(bindInputEl)) return\n          changeTracker.captureCanvasState()\n        })\n      },\n      true\n    )\n\n    window.addEventListener('keyup', () => {\n      if (keyIgnored) {\n        keyIgnored = false\n        captureState()\n      }\n    })\n\n    // Handle clicking DOM elements (e.g. widgets)\n    window.addEventListener('mouseup', () => {\n      captureState()\n    })\n\n    // Handle prompt queue event for dynamic widget changes\n    api.addEventListener('promptQueued', () => {\n      captureState()\n    })\n\n    api.addEventListener('graphCleared', () => {\n      captureState()\n    })\n\n    // Handle litegraph clicks\n    const processMouseUp = LGraphCanvas.prototype.processMouseUp\n    LGraphCanvas.prototype.processMouseUp = function (e) {\n      const v = processMouseUp.apply(this, [e])\n      captureState()\n      return v\n    }\n\n    // Handle litegraph dialog popup for number/string widgets\n    const prompt = LGraphCanvas.prototype.prompt\n    LGraphCanvas.prototype.prompt = function (\n      title: string,\n      value: string | number,\n      callback: (v: string) => void,\n      event: CanvasPointerEvent\n    ) {\n      const extendedCallback = (v: string) => {\n        callback(v)\n        captureState()\n      }\n      return prompt.apply(this, [title, value, extendedCallback, event])\n    }\n\n    // Handle litegraph context menu for COMBO widgets\n    const close = LiteGraph.ContextMenu.prototype.close\n    LiteGraph.ContextMenu.prototype.close = function (e: MouseEvent) {\n      const v = close.apply(this, [e])\n      captureState()\n      return v\n    }\n\n    // Handle multiple commands as a single transaction\n    document.addEventListener('litegraph:canvas', (e: Event) => {\n      const detail = (e as CustomEvent).detail\n      if (detail.subType === 'before-change') {\n        getCurrentChangeTracker()?.beforeChange()\n      } else if (detail.subType === 'after-change') {\n        getCurrentChangeTracker()?.afterChange()\n      }\n    })\n\n    // Store node outputs\n    api.addEventListener('executed', (e: CustomEvent<ExecutedWsMessage>) => {\n      const detail = e.detail\n      const workflow =\n        useExecutionStore().queuedJobs[detail.prompt_id]?.workflow\n      const changeTracker = workflow?.changeTracker\n      if (!changeTracker) return\n      changeTracker.nodeOutputs ??= {}\n      const nodeOutputs = changeTracker.nodeOutputs\n      const output = nodeOutputs[detail.node]\n      if (detail.merge && output) {\n        for (const k in detail.output) {\n          const v = output[k]\n          if (v instanceof Array) {\n            output[k] = v.concat(detail.output[k])\n          } else {\n            output[k] = detail.output[k]\n          }\n        }\n      } else {\n        nodeOutputs[detail.node] = detail.output\n      }\n    })\n  }\n\n  static bindInput(activeEl: Element | null): boolean {\n    if (\n      !activeEl ||\n      activeEl.tagName === 'CANVAS' ||\n      activeEl.tagName === 'BODY'\n    ) {\n      return false\n    }\n\n    for (const evt of ['change', 'input', 'blur']) {\n      const htmlElement = activeEl as HTMLElement\n      if (`on${evt}` in htmlElement) {\n        const listener = () => {\n          useWorkflowStore().activeWorkflow?.changeTracker.captureCanvasState()\n          htmlElement.removeEventListener(evt, listener)\n        }\n        htmlElement.addEventListener(evt, listener)\n        return true\n      }\n    }\n    return false\n  }\n\n  static graphEqual(a: ComfyWorkflowJSON, b: ComfyWorkflowJSON) {\n    if (a === b) return true\n\n    // Compare nodes ignoring array position and execution order\n    if (\n      !_.isEqualWith(\n        withoutExecutionOrder(a.nodes),\n        withoutExecutionOrder(b.nodes),\n        (arrA, arrB) => {\n          if (Array.isArray(arrA) && Array.isArray(arrB)) {\n            return _.isEqual(new Set(arrA), new Set(arrB))\n          }\n        }\n      )\n    ) {\n      return false\n    }\n\n    // Compare extra properties ignoring ds\n    if (\n      !_.isEqual(_.omit(a.extra ?? {}, ['ds']), _.omit(b.extra ?? {}, ['ds']))\n    )\n      return false\n\n    // Compare other properties normally\n    for (const key of [\n      'links',\n      'floatingLinks',\n      'reroutes',\n      'groups',\n      'definitions',\n      'subgraphs'\n    ]) {\n      if (!_.isEqual(a[key], b[key])) {\n        return false\n      }\n    }\n\n    return true\n  }\n}\n","import { union } from 'es-toolkit/compat'\nimport { createEventHook, until, useAsyncState } from '@vueuse/core'\nimport { defineStore } from 'pinia'\nimport { computed, markRaw, ref, shallowRef, watch } from 'vue'\nimport type { Raw } from 'vue'\n\nimport { t } from '@/i18n'\nimport type {\n  LGraph,\n  LGraphNode,\n  Subgraph\n} from '@/lib/litegraph/src/litegraph'\nimport {\n  areWorkflowIdsEquivalent,\n  ensureWorkflowId,\n  getLegacyWorkflowId\n} from '@/platform/workflow/core/utils/workflowId'\nimport type { ComfyWorkflowJSON } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useWorkflowDraftStoreV2 } from '@/platform/workflow/persistence/stores/workflowDraftStoreV2'\n// oxlint-disable-next-line comfy/no-restricted-paths\nimport { useWorkflowThumbnail } from '@/renderer/core/thumbnail/useWorkflowThumbnail'\nimport { api } from '@/scripts/api'\nimport { useApp } from '@/scripts/appInstance'\nimport { ChangeTracker } from '@/scripts/changeTracker'\nimport { defaultGraph } from '@/scripts/defaultGraph'\nimport { useDialogService } from '@/services/dialogService'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport type { NodeExecutionId, NodeLocatorId } from '@/types/nodeIdentification'\nimport {\n  createLeafNodeExecutionId,\n  createNodeLocatorId,\n  parseNodeExecutionId,\n  parseNodeLocatorId,\n  tryNormalizeNodeExecutionId\n} from '@/types/nodeIdentification'\nimport { parseNodeId } from '@/types/nodeId'\nimport type { NodeId } from '@/types/nodeId'\nimport { generateUUID, getPathDetails } from '@/utils/formatUtil'\nimport { syncEntities } from '@/utils/syncUtil'\nimport { isSubgraph } from '@/utils/typeGuardUtil'\nimport { ComfyWorkflow, registerWorkflowRuntime } from './comfyWorkflow'\nimport type { LoadedComfyWorkflow } from './comfyWorkflow'\nimport type { WorkflowStore } from './workflowStoreTypes'\nexport { ComfyWorkflow, type LoadedComfyWorkflow }\n\nregisterWorkflowRuntime({\n  createChangeTracker: (workflow, initialState) =>\n    new ChangeTracker(workflow, initialState),\n  getDraft: (path) => useWorkflowDraftStoreV2().getDraft(path),\n  removeDraft: (path) => useWorkflowDraftStoreV2().removeDraft(path),\n  markDraftUsed: (path) => useWorkflowDraftStoreV2().markDraftUsed(path),\n  isDraftPersistenceEnabled: () =>\n    useSettingStore().get('Comfy.Workflow.Persist'),\n  async promptSave(workflow) {\n    try {\n      return await useDialogService().prompt({\n        title: t(workflow.saveNamePrompt.title),\n        message: t(workflow.saveNamePrompt.message),\n        defaultValue: workflow.filename\n      })\n    } catch (error) {\n      reportError(error, {\n        surface: 'graph',\n        errorType: 'error_loading_dialog_service_prompt_save'\n      })\n      return null\n    }\n  }\n})\n\nexport const useWorkflowStore = defineStore('workflow', () => {\n  /**\n   * History of tab activations. Most recent at the end.\n   * Tracks the order in which tabs were activated to support \"go to previous\" behavior.\n   * Lazily cleaned on access.\n   */\n  const tabActivationHistory = ref<string[]>([])\n  const MAX_HISTORY_SIZE = 32\n\n  /**\n   * Detach the workflow from the store. lightweight helper function.\n   * @param workflow The workflow to detach.\n   * @returns The index of the workflow in the openWorkflowPaths array, or -1 if the workflow was not open.\n   */\n  const detachWorkflow = (workflow: ComfyWorkflow) => {\n    delete workflowLookup.value[workflow.path]\n    const index = openWorkflowPaths.value.indexOf(workflow.path)\n    if (index !== -1) {\n      openWorkflowPaths.value = openWorkflowPaths.value.filter(\n        (path) => path !== workflow.path\n      )\n    }\n    return index\n  }\n\n  /**\n   * Attach the workflow to the store. lightweight helper function.\n   * @param workflow The workflow to attach.\n   * @param openIndex The index to open the workflow at.\n   */\n  const attachWorkflow = (workflow: ComfyWorkflow, openIndex: number = -1) => {\n    workflowLookup.value[workflow.path] = workflow\n\n    if (openIndex !== -1) {\n      openWorkflowPaths.value.splice(openIndex, 0, workflow.path)\n    }\n  }\n\n  /**\n   * The active workflow currently being edited.\n   */\n  const activeWorkflow = ref<LoadedComfyWorkflow | null>(null)\n  const isActive = (workflow: ComfyWorkflow) =>\n    activeWorkflow.value?.path === workflow.path\n  /**\n   * All workflows.\n   */\n  const workflowLookup = ref<Record<string, ComfyWorkflow>>({})\n  const workflows = computed<ComfyWorkflow[]>(() =>\n    Object.values(workflowLookup.value)\n  )\n  const getWorkflowByPath = (path: string): ComfyWorkflow | null =>\n    workflowLookup.value[path] ?? null\n\n  /**\n   * The paths of the open workflows. It is setup as a ref to allow user\n   * to reorder the workflows opened.\n   */\n  const openWorkflowPaths = ref<string[]>([])\n  const openWorkflowPathSet = computed(() => new Set(openWorkflowPaths.value))\n  const openWorkflows = computed(() =>\n    openWorkflowPaths.value\n      .map(getWorkflowByPath)\n      .filter((workflow) => workflow !== null)\n  )\n  const reorderWorkflows = (from: number, to: number) => {\n    const paths = openWorkflows.value.map((workflow) => workflow.path)\n    const [movedTab] = paths.splice(from, 1)\n    paths.splice(to, 0, movedTab)\n    openWorkflowPaths.value = paths\n  }\n  const isOpen = (workflow: ComfyWorkflow) =>\n    openWorkflowPathSet.value.has(workflow.path)\n\n  /**\n   * Add paths to the list of open workflow paths without loading the files\n   * or changing the active workflow.\n   *\n   * @param paths - The workflows to open, specified as:\n   *   - `left`: Workflows to be added to the left.\n   *   - `right`: Workflows to be added to the right.\n   *\n   * Invalid paths (non-strings or paths not found in `workflowLookup.value`)\n   * will be ignored. Duplicate paths are automatically removed.\n   */\n  const openWorkflowsInBackground = (paths: {\n    left?: string[]\n    right?: string[]\n  }) => {\n    const { left = [], right = [] } = paths\n    if (!left.length && !right.length) return\n\n    const isValidPath = (\n      path: unknown\n    ): path is keyof typeof workflowLookup.value =>\n      typeof path === 'string' && path in workflowLookup.value\n\n    openWorkflowPaths.value = union(\n      left,\n      openWorkflowPaths.value,\n      right\n    ).filter(isValidPath)\n  }\n\n  /**\n   * Set the workflow as the active workflow.\n   * @param workflow The workflow to open.\n   */\n  const openWorkflow = async (\n    workflow: ComfyWorkflow\n  ): Promise<LoadedComfyWorkflow> => {\n    if (isActive(workflow)) return workflow as LoadedComfyWorkflow\n\n    if (!openWorkflowPaths.value.includes(workflow.path)) {\n      openWorkflowPaths.value.push(workflow.path)\n    }\n    const graphState = useApp().rootGraphOrUndefined?.state\n    const loadedWorkflow = await workflow.load()\n    if (graphState !== useApp().rootGraphOrUndefined?.state) {\n      throw new DOMException('Workflow load was replaced', 'AbortError')\n    }\n    activeWorkflow.value = loadedWorkflow\n    useApp().canvas.bg_tint = loadedWorkflow.tintCanvasBg\n\n    // Track activation in history (move to end if already present)\n    const historyIndex = tabActivationHistory.value.indexOf(workflow.path)\n    if (historyIndex !== -1) {\n      tabActivationHistory.value.splice(historyIndex, 1)\n    }\n    tabActivationHistory.value.push(workflow.path)\n    // Trim history if too large\n    if (tabActivationHistory.value.length > MAX_HISTORY_SIZE) {\n      tabActivationHistory.value.shift()\n    }\n\n    return loadedWorkflow\n  }\n\n  const getUnconflictedPath = (basePath: string): string => {\n    const { directory, filename, suffix } = getPathDetails(basePath)\n    let counter = 2\n    let newPath = basePath\n    while (Object.hasOwn(workflowLookup.value, newPath)) {\n      newPath = `${directory}/${filename} (${counter}).${suffix}`\n      counter++\n    }\n    return newPath\n  }\n  const saveAs = (\n    existingWorkflow: ComfyWorkflow,\n    path: string\n  ): ComfyWorkflow => {\n    // Generate new id when saving existing workflow as a new file\n    const id = generateUUID()\n    const state = JSON.parse(\n      JSON.stringify(existingWorkflow.activeState)\n    ) as ComfyWorkflowJSON\n    state.id = id\n\n    const workflow: ComfyWorkflow =\n      new (existingWorkflow.constructor as typeof ComfyWorkflow)({\n        path,\n        modified: Date.now(),\n        size: -1\n      })\n    workflow.initialMode = existingWorkflow.initialMode\n    workflow.originalContent = workflow.content = JSON.stringify(state)\n    workflowLookup.value[workflow.path] = workflow\n    return workflow\n  }\n\n  /**\n   * Helper to create a new temporary workflow\n   */\n  const createNewWorkflow = (\n    path: string,\n    workflowData?: ComfyWorkflowJSON\n  ): ComfyWorkflow => {\n    const workflow = new ComfyWorkflow({\n      path,\n      modified: Date.now(),\n      size: -1\n    })\n    workflow.legacyId = getLegacyWorkflowId(workflowData?.id)\n\n    const initialWorkflowData = ensureWorkflowId(\n      structuredClone(workflowData ?? defaultGraph)\n    )\n    workflow.originalContent = workflow.content =\n      JSON.stringify(initialWorkflowData)\n\n    workflowLookup.value[workflow.path] = workflow\n    return workflow\n  }\n\n  /**\n   * Create a temporary workflow, attempting to reuse an existing workflow if conditions match\n   */\n  const createTemporary = (path?: string, workflowData?: ComfyWorkflowJSON) => {\n    const fullPath = getUnconflictedPath(\n      ComfyWorkflow.basePath + (path ?? 'Unsaved Workflow.json')\n    )\n\n    // Try to reuse an existing loaded workflow with the same filename\n    // that is not stored in the workflows directory\n    if (path && workflowData) {\n      const existingWorkflow = workflows.value.find(\n        (w) => w.fullFilename === path\n      )\n      if (\n        existingWorkflow?.changeTracker &&\n        !existingWorkflow.directory.startsWith(\n          ComfyWorkflow.basePath.slice(0, -1)\n        ) &&\n        areWorkflowIdsEquivalent(\n          existingWorkflow.activeState?.id,\n          workflowData.id,\n          existingWorkflow.legacyId\n        )\n      ) {\n        existingWorkflow.legacyId ??= getLegacyWorkflowId(workflowData.id)\n        existingWorkflow.changeTracker.reset(\n          ensureWorkflowId(workflowData, existingWorkflow.activeState?.id)\n        )\n        return existingWorkflow\n      }\n    }\n\n    return createNewWorkflow(fullPath, workflowData)\n  }\n\n  /**\n   * Create a new temporary workflow without attempting to reuse existing workflows\n   */\n  const createNewTemporary = (\n    path?: string,\n    workflowData?: ComfyWorkflowJSON\n  ): ComfyWorkflow => {\n    const fullPath = getUnconflictedPath(\n      ComfyWorkflow.basePath + (path ?? 'Unsaved Workflow.json')\n    )\n    return createNewWorkflow(fullPath, workflowData)\n  }\n\n  const closeWorkflow = async (workflow: ComfyWorkflow) => {\n    openWorkflowPaths.value = openWorkflowPaths.value.filter(\n      (path) => path !== workflow.path\n    )\n    useWorkflowDraftStoreV2().removeDraft(workflow.path)\n    if (workflow.isTemporary) {\n      clearThumbnail(workflow.key)\n      delete workflowLookup.value[workflow.path]\n    } else {\n      workflow.unload()\n    }\n  }\n\n  /**\n   * Get the workflow at the given index shift from the active workflow.\n   * @param shift The shift to the next workflow. Positive for next, negative for previous.\n   * @returns The next workflow or null if the shift is out of bounds.\n   */\n  const openedWorkflowIndexShift = (shift: number): ComfyWorkflow | null => {\n    const index = openWorkflows.value.findIndex(\n      (workflow) => workflow.path === activeWorkflow.value?.path\n    )\n\n    if (index !== -1) {\n      const length = openWorkflows.value.length\n      const nextIndex = (index + shift + length) % length\n      const nextWorkflow = openWorkflows.value[nextIndex]\n      return nextWorkflow\n    }\n    return null\n  }\n\n  /**\n   * Get the most recently active workflow from history (excluding current).\n   * Lazily cleans invalid paths from history.\n   * @returns The most recent valid workflow or null if none found.\n   */\n  const getMostRecentWorkflow = (): ComfyWorkflow | null => {\n    const currentPath = activeWorkflow.value?.path\n    const validPaths: string[] = []\n\n    // Scan backwards through history\n    for (let i = tabActivationHistory.value.length - 1; i >= 0; i--) {\n      const path = tabActivationHistory.value[i]\n\n      // Skip current workflow\n      if (path === currentPath) continue\n\n      // Check if workflow is still open\n      if (openWorkflowPathSet.value.has(path)) {\n        validPaths.unshift(path)\n        const workflow = getWorkflowByPath(path)\n        {\n          // Lazy cleanup: keep only valid paths\n          tabActivationHistory.value = validPaths\n          return workflow\n        }\n      }\n    }\n\n    // Cleanup: no valid workflows found, clear history\n    tabActivationHistory.value = []\n    return null\n  }\n\n  const persistedWorkflows = computed(() =>\n    Array.from(workflows.value).filter(\n      (workflow) =>\n        workflow.isPersisted && !workflow.path.startsWith('subgraphs/')\n    )\n  )\n\n  const {\n    isReady: isSyncReady,\n    isLoading: isSyncLoading,\n    execute: executeSyncWorkflows\n  } = useAsyncState(\n    async (dir: string = '') => {\n      await syncEntities(\n        dir ? 'workflows/' + dir : 'workflows',\n        workflowLookup.value,\n        (file) =>\n          new ComfyWorkflow({\n            path: file.path,\n            modified: file.modified,\n            size: file.size\n          }),\n        (existingWorkflow, file) => {\n          const isActiveWorkflow =\n            activeWorkflow.value?.path === existingWorkflow.path\n\n          const nextLastModified = Math.max(\n            existingWorkflow.lastModified,\n            file.modified\n          )\n\n          const isMetadataUnchanged =\n            nextLastModified === existingWorkflow.lastModified &&\n            file.size === existingWorkflow.size\n\n          if (!isMetadataUnchanged) {\n            existingWorkflow.lastModified = nextLastModified\n            existingWorkflow.size = file.size\n          }\n\n          // Never unload the active workflow - it may contain unsaved in-memory edits.\n          if (isActiveWorkflow) {\n            return\n          }\n\n          // If nothing changed, keep any loaded content cached.\n          if (isMetadataUnchanged) {\n            return\n          }\n\n          existingWorkflow.unload()\n        },\n        /* exclude */ (workflow) => workflow.isTemporary,\n        /* beforeDelete */ (workflow, path) => {\n          if (isActive(workflow)) return false\n          openWorkflowPaths.value = openWorkflowPaths.value.filter(\n            (openPath) => openPath !== path\n          )\n          return true\n        }\n      )\n    },\n    undefined,\n    { immediate: false }\n  )\n\n  async function syncWorkflows(dir: string = '') {\n    return executeSyncWorkflows(0, dir)\n  }\n\n  async function loadWorkflows(): Promise<void> {\n    if (isSyncReady.value) return\n\n    if (isSyncLoading.value) {\n      await until(isSyncLoading).toBe(false)\n      return\n    }\n\n    await syncWorkflows()\n  }\n\n  const bookmarkStore = useWorkflowBookmarkStore()\n  const bookmarkedWorkflows = computed(() =>\n    workflows.value.filter((workflow) =>\n      bookmarkStore.isBookmarked(workflow.path)\n    )\n  )\n  const modifiedWorkflows = computed(() =>\n    workflows.value.filter((workflow) => workflow.isModified)\n  )\n\n  /** A filesystem operation is currently in progress (e.g. save, rename, delete) */\n  const isBusy = ref<boolean>(false)\n  const workflowRenamed = createEventHook<ComfyWorkflow>()\n  const { moveWorkflowThumbnail, clearThumbnail } = useWorkflowThumbnail()\n\n  const renameWorkflow = async (workflow: ComfyWorkflow, newPath: string) => {\n    isBusy.value = true\n    try {\n      // Capture all needed values upfront\n      const oldPath = workflow.path\n      const oldKey = workflow.key\n      const wasBookmarked = bookmarkStore.isBookmarked(oldPath)\n      const draftStore = useWorkflowDraftStoreV2()\n\n      await workflow.rename(newPath)\n      void workflowRenamed.trigger(workflow)\n\n      // Synchronously swap old path for new path in lookup and open paths\n      // to avoid a tab flicker caused by an async gap between detach/attach.\n      delete workflowLookup.value[oldPath]\n      workflowLookup.value[workflow.path] = workflow\n      const openIndex = openWorkflowPaths.value.indexOf(oldPath)\n      if (openIndex !== -1) {\n        openWorkflowPaths.value.splice(openIndex, 1, workflow.path)\n      }\n\n      draftStore.moveDraft(oldPath, newPath, workflow.key)\n\n      // Move thumbnail from old key to new key (using workflow keys, not full paths)\n      const newKey = workflow.key\n      moveWorkflowThumbnail(oldKey, newKey)\n      // Update bookmarks\n      if (wasBookmarked) {\n        await bookmarkStore.setBookmarked(oldPath, false)\n        await bookmarkStore.setBookmarked(newPath, true)\n      }\n    } finally {\n      isBusy.value = false\n    }\n  }\n\n  const deleteWorkflow = async (workflow: ComfyWorkflow) => {\n    isBusy.value = true\n    try {\n      await workflow.delete()\n      useWorkflowDraftStoreV2().removeDraft(workflow.path)\n      if (bookmarkStore.isBookmarked(workflow.path)) {\n        await bookmarkStore.setBookmarked(workflow.path, false)\n      }\n      // Clear thumbnail when workflow is deleted\n      clearThumbnail(workflow.key)\n      detachWorkflow(workflow)\n    } finally {\n      isBusy.value = false\n    }\n  }\n\n  /**\n   * Save a workflow.\n   * @param workflow The workflow to save.\n   */\n  const saveWorkflow = async (workflow: ComfyWorkflow) => {\n    isBusy.value = true\n    try {\n      await workflow.save()\n      // Synchronously detach and re-attach to force refresh the tree objects\n      // without an async gap that would cause the tab to disappear.\n      const openIndex = detachWorkflow(workflow)\n      attachWorkflow(workflow, openIndex)\n    } finally {\n      isBusy.value = false\n    }\n  }\n\n  /** @see WorkflowStore.isSubgraphActive */\n  const isSubgraphActive = ref(false)\n\n  /** @see WorkflowStore.activeSubgraph */\n  const activeSubgraph = shallowRef<Raw<Subgraph>>()\n\n  /** @see WorkflowStore.updateActiveGraph */\n  const updateActiveGraph = () => {\n    const canvas = useApp().canvasOrUndefined\n    if (!canvas) return\n    const subgraph = canvas.subgraph\n    activeSubgraph.value = subgraph ? markRaw(subgraph) : undefined\n\n    isSubgraphActive.value = isSubgraph(subgraph)\n  }\n\n  const subgraphNodeIdToSubgraph = (id: string, graph: LGraph | Subgraph) => {\n    const parsedNodeId = parseNodeId(id)\n    if (!parsedNodeId) return\n    const node = graph.getNodeById(parsedNodeId)\n    if (node?.isSubgraphNode()) return node.subgraph\n  }\n\n  const getSubgraphsFromInstanceIds = (\n    currentGraph: LGraph | Subgraph,\n    subgraphNodeIds: string[]\n  ): Subgraph[] | undefined => {\n    const currentPart = subgraphNodeIds.at(0)\n    const remainingParts = subgraphNodeIds.slice(1)\n    if (currentPart === undefined) return []\n\n    const subgraph = subgraphNodeIdToSubgraph(currentPart, currentGraph)\n    if (subgraph === undefined) return\n\n    const childSubgraphs = getSubgraphsFromInstanceIds(subgraph, remainingParts)\n    return childSubgraphs ? [subgraph, ...childSubgraphs] : undefined\n  }\n\n  //FIXME: use existing util function\n  const executionIdToCurrentId = (id: string): string | undefined => {\n    const subgraph = activeSubgraph.value\n\n    // Short-circuit: ID belongs to the parent workflow / no active subgraph\n    if (!id.includes(':')) {\n      return !subgraph ? id : undefined\n    } else if (!subgraph) {\n      return\n    }\n\n    const executionPath = parseNodeExecutionId(id)?.map(String)\n    if (!executionPath) return\n\n    const nodeId = executionPath.at(-1)\n    if (nodeId === undefined) return\n\n    const subgraphs = getSubgraphsFromInstanceIds(\n      useApp().rootGraph,\n      executionPath.slice(0, -1)\n    )\n    if (subgraphs?.at(-1) === subgraph) return nodeId\n  }\n\n  watch(activeWorkflow, updateActiveGraph)\n\n  /**\n   * Convert a node ID to a NodeLocatorId\n   * @param nodeId The local node ID\n   * @param subgraph The subgraph containing the node (defaults to active subgraph)\n   * @returns The NodeLocatorId\n   */\n  const nodeIdToNodeLocatorId = (\n    nodeId: NodeId,\n    subgraph?: Subgraph\n  ): NodeLocatorId => {\n    const targetSubgraph = subgraph ?? activeSubgraph.value\n    if (!targetSubgraph) {\n      return createNodeLocatorId(null, nodeId)\n    }\n\n    return createNodeLocatorId(targetSubgraph.id, nodeId)\n  }\n  /**\n   * Convert a node to a NodeLocatorId\n   * Does not assume the node resides in  the active graph\n   * @param The actual node instance\n   * @returns The NodeLocatorId (for root graph nodes, returns the node ID as-is)\n   */\n  const nodeToNodeLocatorId = (node: LGraphNode): NodeLocatorId => {\n    if (isSubgraph(node.graph))\n      return createNodeLocatorId(node.graph.id, node.id)\n    return createNodeLocatorId(null, node.id)\n  }\n\n  /**\n   * Extract the node ID from a NodeLocatorId\n   * @param locatorId The NodeLocatorId\n   * @returns The local node ID\n   */\n  const nodeLocatorIdToNodeId = (locatorId: NodeLocatorId): NodeId | null =>\n    parseNodeLocatorId(locatorId)?.localNodeId ?? null\n\n  /**\n   * Convert a NodeLocatorId to an execution ID for a specific context\n   * @param locatorId The NodeLocatorId\n   * @param targetSubgraph The subgraph context (defaults to active subgraph)\n   * @returns The execution ID or null if the node is not accessible from the target context\n   */\n  const nodeLocatorIdToNodeExecutionId = (\n    locatorId: NodeLocatorId,\n    targetSubgraph?: Subgraph\n  ): NodeExecutionId | null => {\n    const parsed = parseNodeLocatorId(locatorId)\n    if (!parsed) return null\n\n    const { subgraphUuid, localNodeId } = parsed\n\n    // If no subgraph UUID, this is a root graph node\n    if (!subgraphUuid) {\n      return createLeafNodeExecutionId(localNodeId)\n    }\n\n    // Find the path from root to the subgraph with this UUID\n    const findSubgraphPath = (\n      graph: LGraph | Subgraph,\n      targetUuid: string,\n      path: NodeId[] = []\n    ): NodeId[] | null => {\n      if (isSubgraph(graph) && graph.id === targetUuid) {\n        return path\n      }\n\n      for (const node of graph._nodes) {\n        if (node.isSubgraphNode()) {\n          const result = findSubgraphPath(node.subgraph, targetUuid, [\n            ...path,\n            node.id\n          ])\n          if (result) return result\n        }\n      }\n\n      return null\n    }\n\n    const path = findSubgraphPath(useApp().rootGraph, subgraphUuid)\n    if (!path) return null\n\n    // If we have a target subgraph, check if the path goes through it\n    if (\n      targetSubgraph &&\n      !path.some((_, idx) => {\n        const subgraphs = getSubgraphsFromInstanceIds(\n          useApp().rootGraph,\n          path.slice(0, idx + 1).map((id) => String(id))\n        )\n        return subgraphs?.at(-1) === targetSubgraph\n      })\n    ) {\n      return null\n    }\n\n    return tryNormalizeNodeExecutionId([...path, localNodeId].join(':'))\n  }\n\n  return {\n    activeWorkflow,\n    attachWorkflow,\n    isActive,\n    openWorkflows,\n    openedWorkflowIndexShift,\n    getMostRecentWorkflow,\n    openWorkflow,\n    openWorkflowsInBackground,\n    isOpen,\n    isBusy,\n    closeWorkflow,\n    createTemporary,\n    createNewTemporary,\n    renameWorkflow,\n    onWorkflowRenamed: workflowRenamed.on,\n    deleteWorkflow,\n    saveAs,\n    saveWorkflow,\n    reorderWorkflows,\n\n    workflows,\n    bookmarkedWorkflows,\n    persistedWorkflows,\n    modifiedWorkflows,\n    getWorkflowByPath,\n    syncWorkflows,\n    isSyncLoading,\n    loadWorkflows,\n\n    isSubgraphActive,\n    activeSubgraph,\n    updateActiveGraph,\n    executionIdToCurrentId,\n    nodeIdToNodeLocatorId,\n    nodeToNodeLocatorId,\n    nodeLocatorIdToNodeId,\n    nodeLocatorIdToNodeExecutionId\n  }\n}) satisfies () => WorkflowStore\n\nexport const useWorkflowBookmarkStore = defineStore('workflowBookmark', () => {\n  const bookmarks = ref<Set<string>>(new Set())\n\n  const isBookmarked = (path: string) => bookmarks.value.has(path)\n\n  const loadBookmarks = async () => {\n    const resp = await api.getUserData('workflows/.index.json')\n    if (resp.status === 200) {\n      const info = await resp.json()\n      bookmarks.value = new Set(info?.favorites ?? [])\n    }\n  }\n\n  const saveBookmarks = async () => {\n    await api.storeUserData('workflows/.index.json', {\n      favorites: Array.from(bookmarks.value)\n    })\n  }\n\n  const setBookmarked = async (path: string, value: boolean) => {\n    if (bookmarks.value.has(path) === value) return\n    if (value) {\n      bookmarks.value.add(path)\n    } else {\n      bookmarks.value.delete(path)\n    }\n    await saveBookmarks()\n  }\n\n  const toggleBookmarked = async (path: string) => {\n    await setBookmarked(path, !bookmarks.value.has(path))\n  }\n\n  return {\n    isBookmarked,\n    loadBookmarks,\n    saveBookmarks,\n    setBookmarked,\n    toggleBookmarked\n  }\n})\n","import { computed, ref } from 'vue'\n\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { getWorkflowMode, isAppModeValue } from '@/utils/appMode'\nimport type { AppMode } from '@/utils/appMode'\n\nconst enableAppBuilder = ref(true)\n\nexport function useAppMode() {\n  const workflowStore = useWorkflowStore()\n  const mode = computed(() => getWorkflowMode(workflowStore.activeWorkflow))\n\n  const isBuilderMode = computed(\n    () => isSelectMode.value || isArrangeMode.value\n  )\n  const isSelectInputsMode = computed(() => mode.value === 'builder:inputs')\n  const isSelectOutputsMode = computed(() => mode.value === 'builder:outputs')\n  const isSelectMode = computed(\n    () => isSelectInputsMode.value || isSelectOutputsMode.value\n  )\n  const isArrangeMode = computed(() => mode.value === 'builder:arrange')\n  const isAppMode = computed(() => isAppModeValue(mode.value))\n  const isGraphMode = computed(\n    () => mode.value === 'graph' || isSelectMode.value\n  )\n\n  function setMode(newMode: AppMode) {\n    const workflow = workflowStore.activeWorkflow\n    if (workflow) workflow.activeMode = newMode\n  }\n\n  return {\n    mode,\n    enableAppBuilder,\n    isBuilderMode,\n    isSelectMode,\n    isSelectInputsMode,\n    isSelectOutputsMode,\n    isArrangeMode,\n    isAppMode,\n    isGraphMode,\n    setMode\n  }\n}\n","import { useEventListener, whenever } from '@vueuse/core'\nimport { defineStore } from 'pinia'\nimport { computed, ref, shallowRef } from 'vue'\n\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useAppMode } from '@/composables/useAppMode'\nimport { visibleCanvasViewport } from '@/composables/canvas/visibleCanvasViewport'\n\nimport type { Point, Positionable } from '@/lib/litegraph/src/interfaces'\nimport type {\n  LGraph,\n  LGraphCanvas,\n  LGraphGroup,\n  LGraphNode,\n  SubgraphNode\n} from '@/lib/litegraph/src/litegraph'\nimport { resolveSelectable } from '@/renderer/core/canvas/litegraph/selectionAdapter'\nimport { promoteRecommendedWidgets } from '@/core/graph/subgraph/promotionUtils'\nimport { useSelectionStore } from '@/core/selection/selectionStore'\nimport { useLayoutMutations } from '@/renderer/core/layout/operations/layoutMutations'\nimport { LayoutSource } from '@/renderer/core/layout/types'\nimport { graphScopeOf } from '@/types/graphScopeId'\nimport type { NodeId } from '@/types/nodeId'\nimport { isLGraphNode } from '@/utils/litegraphUtil'\nimport { createPositionBounds } from '@/utils/positionBounds'\n\nexport const useTitleEditorStore = defineStore('titleEditor', () => {\n  const titleEditorTarget = shallowRef<LGraphNode | LGraphGroup | null>(null)\n\n  return {\n    titleEditorTarget\n  }\n})\n\nexport const useCanvasStore = defineStore('canvas', () => {\n  /**\n   * The LGraphCanvas instance.\n   *\n   * The root LGraphCanvas object is a shallow ref.\n   */\n  const canvas = shallowRef<LGraphCanvas | null>(null)\n  const selectionStore = useSelectionStore()\n\n  // Reactive scale percentage that syncs with app.canvas.ds.scale\n  const appScalePercentage = ref(100)\n  const updateAppScalePercentage = (scale: number) => {\n    appScalePercentage.value = Math.round(scale * 100)\n  }\n\n  const { isAppMode, setMode } = useAppMode()\n  const linearMode = computed({\n    get: () => isAppMode.value,\n    set: (val: boolean) => {\n      setMode(val ? 'app' : 'graph')\n    }\n  })\n  const isReadOnly = ref(false)\n\n  // Set up scale synchronization when canvas is available\n  let originalOnChanged: ((scale: number, offset: Point) => void) | undefined =\n    undefined\n  const initScaleSync = () => {\n    const ds = canvas.value?.ds\n    if (!ds) return\n\n    originalOnChanged = ds.onChanged\n    updateAppScalePercentage(ds.scale)\n\n    ds.onChanged = () => {\n      if (ds.scale) {\n        updateAppScalePercentage(ds.scale)\n      }\n      originalOnChanged?.(ds.scale, ds.offset)\n    }\n  }\n\n  const cleanupScaleSync = () => {\n    const ds = canvas.value?.ds\n    if (!ds) return\n    ds.onChanged = originalOnChanged\n    originalOnChanged = undefined\n  }\n\n  const getCanvas = () => {\n    if (!canvas.value) throw new Error('getCanvas: canvas is null')\n    return canvas.value\n  }\n\n  /**\n   * Sets the canvas zoom level from a percentage value\n   * @param percentage - Zoom percentage value (1-1000, where 1000 = 1000% zoom)\n   */\n  const setAppZoomFromPercentage = (percentage: number) => {\n    const currentCanvas = canvas.value\n    if (!currentCanvas || percentage <= 0) return\n\n    // Convert percentage to scale (1000% = 10.0 scale)\n    const newScale = percentage / 100\n    const { ds } = currentCanvas\n    const { element } = ds\n\n    ds.changeScale(newScale, [element.width / 2, element.height / 2])\n    currentCanvas.setDirty(true, true)\n\n    // Update reactive value immediately for UI consistency\n    updateAppScalePercentage(newScale)\n  }\n\n  const currentGraph = shallowRef<LGraph | null>(null)\n  const rootGraphId = computed(() => currentGraph.value?.rootGraph.id)\n  const isInSubgraph = ref(false)\n  const isGhostPlacing = ref(false)\n  const isPickingNodes = ref(false)\n  const toast = useToast()\n\n  function startNodePicking(): void {\n    const currentCanvas = canvas.value\n    if (!currentCanvas || isPickingNodes.value) return\n    isPickingNodes.value = true\n    toast.held = true\n    const selected = [...currentCanvas.selectedItems]\n    const bounds = createPositionBounds(\n      selected.length ? selected : (currentCanvas.graph?.nodes ?? []),\n      40\n    )\n    if (bounds) {\n      currentCanvas.animateToBounds(bounds, {\n        viewport: visibleCanvasViewport(currentCanvas)\n      })\n    }\n  }\n\n  function stopNodePicking(): undefined {\n    if (!isPickingNodes.value) return\n    isPickingNodes.value = false\n    toast.held = false\n    canvas.value?.deselectAll()\n  }\n\n  /** The selected items of the on-screen graph, derived from the selection store. */\n  const selectedItems = computed<Positionable[]>(() => {\n    const graph = currentGraph.value\n    if (!graph) return []\n    return selectionStore\n      .selectedKeys(graphScopeOf(graph))\n      .flatMap((key) => resolveSelectable(graph, key) ?? [])\n  })\n\n  const selectedNodeIds = computed<Set<NodeId>>(\n    () =>\n      new Set(selectedItems.value.filter(isLGraphNode).map((item) => item.id))\n  )\n\n  whenever(\n    () => canvas.value,\n    (newCanvas) => {\n      currentGraph.value = newCanvas.graph\n      // Scoped to the on-screen graph: selection only holds items from it,\n      // so removals in other graphs can't affect the live selection.\n      useEventListener(\n        () => currentGraph.value?.events,\n        'node:before-removed',\n        (e: CustomEvent<{ node: LGraphNode }>) => {\n          newCanvas.deselect(e.detail.node)\n        }\n      )\n\n      isReadOnly.value = newCanvas.read_only\n\n      useEventListener(\n        newCanvas.canvas,\n        'litegraph:read-only-changed',\n        (event: CustomEvent<{ readOnly: boolean }>) => {\n          isReadOnly.value = event.detail.readOnly\n        }\n      )\n\n      useEventListener(\n        newCanvas.canvas,\n        'litegraph:set-graph',\n        (event: CustomEvent<{ newGraph?: LGraph; oldGraph: LGraph }>) => {\n          const newGraph = event.detail.newGraph ?? newCanvas.graph // TODO: Ambiguous Graph\n          currentGraph.value = newGraph\n          isInSubgraph.value = Boolean(newCanvas.subgraph)\n        }\n      )\n\n      useEventListener(newCanvas.canvas, 'subgraph-opened', () => {\n        isInSubgraph.value = true\n      })\n\n      useEventListener(\n        newCanvas.canvas,\n        'subgraph-converted',\n        (e: CustomEvent<{ subgraphNode: SubgraphNode }>) =>\n          promoteRecommendedWidgets(e.detail.subgraphNode)\n      )\n\n      useEventListener(\n        newCanvas.canvas,\n        'litegraph:ghost-placement',\n        (e: CustomEvent<{ active: boolean; nodeId: NodeId }>) => {\n          isGhostPlacing.value = e.detail.active\n          const graph = currentGraph.value\n          if (e.detail.active && graph) {\n            const mutations = useLayoutMutations(LayoutSource.Canvas)\n            mutations.setNodeOrder(graph, e.detail.nodeId, 'front')\n          }\n        }\n      )\n    },\n    { immediate: true }\n  )\n\n  return {\n    canvas,\n    selectedItems,\n    selectedNodeIds,\n    appScalePercentage,\n    linearMode,\n    isReadOnly,\n    getCanvas,\n    setAppZoomFromPercentage,\n    initScaleSync,\n    cleanupScaleSync,\n    currentGraph,\n    rootGraphId,\n    isInSubgraph,\n    isGhostPlacing,\n    isPickingNodes,\n    startNodePicking,\n    stopNodePicking\n  }\n})\n","import { defineStore } from 'pinia'\nimport { computed, ref } from 'vue'\n\nimport { t } from '@/i18n'\n// oxlint-disable-next-line comfy/no-restricted-paths\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useApp } from '@/scripts/appInstance'\nimport { isMissingWarningVisible } from '@/platform/settings/missingWarningVisibility'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport type { MissingModelCandidate } from '@/platform/missingModel/types'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { getAncestorExecutionIds } from '@/types/nodeIdentification'\nimport type { NodeExecutionId, NodeLocatorId } from '@/types/nodeIdentification'\nimport { getActiveGraphNodeIds } from '@/utils/graphTraversalUtil'\n\n/**\n * Missing model error state and interaction state.\n * Separated from executionErrorStore to keep domain boundaries clean.\n * The executionErrorStore composes from this store for aggregate error flags.\n */\nexport const useMissingModelStore = defineStore('missingModel', () => {\n  const canvasStore = useCanvasStore()\n  const workflowStore = useWorkflowStore()\n\n  const missingModelCandidates = ref<MissingModelCandidate[] | null>(null)\n  const isRefreshingMissingModels = ref(false)\n\n  /** Candidates to display; `null` while the missing models warning is off. */\n  const visibleMissingModelCandidates = computed(() =>\n    isMissingWarningVisible('models') ? missingModelCandidates.value : null\n  )\n\n  const hasMissingModels = computed(\n    () => !!visibleMissingModelCandidates.value?.length\n  )\n\n  const missingModelCount = computed(\n    () => visibleMissingModelCandidates.value?.length ?? 0\n  )\n\n  const missingModelNodeIds = computed<Set<string>>(() => {\n    const ids = new Set<string>()\n    if (!visibleMissingModelCandidates.value) return ids\n    for (const m of visibleMissingModelCandidates.value) {\n      // Promoted-widget candidates are scoped to the subgraph host node\n      // (`nodeId`) but originate at an interior node (`sourceExecutionId`);\n      // both execution ids carry the missing model.\n      if (m.nodeId != null) ids.add(String(m.nodeId))\n      if (m.sourceExecutionId != null) ids.add(String(m.sourceExecutionId))\n    }\n    return ids\n  })\n\n  const missingModelWidgetKeys = computed<Set<string>>(() => {\n    const keys = new Set<string>()\n    if (!visibleMissingModelCandidates.value) return keys\n    for (const m of visibleMissingModelCandidates.value) {\n      keys.add(`${String(m.nodeId)}::${m.widgetName}`)\n    }\n    return keys\n  })\n\n  /**\n   * Set of all execution ID prefixes derived from missing model node IDs,\n   * including the missing model nodes themselves.\n   *\n   * Example: missing model on node \"65:70:63\" → Set { \"65\", \"65:70\", \"65:70:63\" }\n   */\n  const missingModelAncestorExecutionIds = computed<Set<NodeExecutionId>>(\n    () => {\n      const ids = new Set<NodeExecutionId>()\n      for (const nodeId of missingModelNodeIds.value) {\n        for (const id of getAncestorExecutionIds(nodeId)) {\n          ids.add(id)\n        }\n      }\n      return ids\n    }\n  )\n\n  const activeMissingModelGraphIds = computed<Set<string>>(() => {\n    const rootGraph = useApp().rootGraphOrUndefined\n    if (!rootGraph) return new Set()\n    return getActiveGraphNodeIds(\n      rootGraph,\n      canvasStore.currentGraph ?? rootGraph,\n      missingModelAncestorExecutionIds.value\n    )\n  })\n\n  // Persists across component re-mounts so that download progress\n  // survives tab switches within the right-side panel.\n  const modelExpandState = ref<Record<string, boolean>>({})\n  const selectedLibraryModel = ref<Record<string, string>>({})\n  const importTaskIds = ref<Record<string, string>>({})\n  const folderPaths = ref<Record<string, string[]>>({})\n  const fileSizes = ref<Record<string, number>>({})\n  const gatedRepoUrls = ref<Record<string, string>>({})\n\n  let _verificationAbortController: AbortController | null = null\n\n  function createVerificationAbortController(): AbortController {\n    _verificationAbortController?.abort()\n    _verificationAbortController = new AbortController()\n    return _verificationAbortController\n  }\n\n  function setMissingModels(models: MissingModelCandidate[]) {\n    missingModelCandidates.value = models.length ? models : null\n  }\n\n  function removeMissingModelByNameOnNodes(\n    modelName: string,\n    nodeIds: Set<string>\n  ) {\n    if (!missingModelCandidates.value) return\n    missingModelCandidates.value = missingModelCandidates.value.filter(\n      (m) =>\n        m.name !== modelName ||\n        m.nodeId == null ||\n        !nodeIds.has(String(m.nodeId))\n    )\n    if (!missingModelCandidates.value.length)\n      missingModelCandidates.value = null\n  }\n\n  function removeMissingModelByWidget(nodeId: string, widgetName: string) {\n    if (!missingModelCandidates.value) return\n    missingModelCandidates.value = missingModelCandidates.value.filter(\n      (m) => !(String(m.nodeId) === nodeId && m.widgetName === widgetName)\n    )\n    if (!missingModelCandidates.value.length)\n      missingModelCandidates.value = null\n  }\n\n  function clearInteractionStateForName(name: string) {\n    delete modelExpandState.value[name]\n    delete selectedLibraryModel.value[name]\n    delete importTaskIds.value[name]\n  }\n\n  function removeMissingModelsByNodeId(nodeId: string) {\n    if (!missingModelCandidates.value) return\n    const removedNames = new Set(\n      missingModelCandidates.value\n        .filter((m) => String(m.nodeId) === nodeId)\n        .map((m) => m.name)\n    )\n    missingModelCandidates.value = missingModelCandidates.value.filter(\n      (m) => String(m.nodeId) !== nodeId\n    )\n    for (const name of removedNames) {\n      if (!missingModelCandidates.value.some((m) => m.name === name)) {\n        clearInteractionStateForName(name)\n      }\n    }\n    if (!missingModelCandidates.value.length)\n      missingModelCandidates.value = null\n  }\n\n  /**\n   * Remove all candidates whose nodeId starts with `prefix`.\n   *\n   * Intended for clearing all interior errors when a subgraph container is\n   * removed. Callers are expected to pass `${execId}:` (with trailing\n   * colon) so that sibling IDs sharing a numeric prefix (e.g. `\"705\"` vs\n   * `\"70\"`) are not matched.\n   */\n  function removeMissingModelsByPrefix(prefix: string) {\n    if (!missingModelCandidates.value) return\n    const removedNames = new Set<string>()\n    const remaining: MissingModelCandidate[] = []\n    for (const m of missingModelCandidates.value) {\n      // Preserve workflow-level candidates with no nodeId; they are not\n      // tied to any subgraph scope and should never be matched by prefix.\n      if (m.nodeId == null) {\n        remaining.push(m)\n        continue\n      }\n      if (String(m.nodeId).startsWith(prefix)) {\n        removedNames.add(m.name)\n      } else {\n        remaining.push(m)\n      }\n    }\n    if (removedNames.size === 0) return\n    missingModelCandidates.value = remaining.length ? remaining : null\n    for (const name of removedNames) {\n      if (!remaining.some((m) => m.name === name)) {\n        clearInteractionStateForName(name)\n      }\n    }\n  }\n\n  function removeMissingModelsBySourceScope(executionId: string) {\n    if (!missingModelCandidates.value) return\n    const prefix = `${executionId}:`\n    const removedNames = new Set<string>()\n    const remaining: MissingModelCandidate[] = []\n    for (const candidate of missingModelCandidates.value) {\n      const sourceExecutionId =\n        candidate.sourceExecutionId == null\n          ? undefined\n          : String(candidate.sourceExecutionId)\n      if (\n        sourceExecutionId === executionId ||\n        sourceExecutionId?.startsWith(prefix)\n      ) {\n        removedNames.add(candidate.name)\n      } else {\n        remaining.push(candidate)\n      }\n    }\n    if (removedNames.size === 0) return\n    missingModelCandidates.value = remaining.length ? remaining : null\n    for (const name of removedNames) {\n      if (!remaining.some((candidate) => candidate.name === name)) {\n        clearInteractionStateForName(name)\n      }\n    }\n  }\n\n  function addMissingModels(models: MissingModelCandidate[]) {\n    if (!models.length) return\n    const existing = missingModelCandidates.value ?? []\n    const existingKeys = new Set(\n      existing.map((m) => `${String(m.nodeId)}::${m.widgetName}::${m.name}`)\n    )\n    const newModels = models.filter(\n      (m) =>\n        !existingKeys.has(`${String(m.nodeId)}::${m.widgetName}::${m.name}`)\n    )\n    if (!newModels.length) return\n    missingModelCandidates.value = [...existing, ...newModels]\n  }\n\n  function hasMissingModelOnNode(nodeLocatorId: NodeLocatorId): boolean {\n    const executionId =\n      workflowStore.nodeLocatorIdToNodeExecutionId(nodeLocatorId)\n    return executionId ? missingModelNodeIds.value.has(executionId) : false\n  }\n\n  function isWidgetMissingModel(nodeId: string, widgetName: string): boolean {\n    return missingModelWidgetKeys.value.has(`${nodeId}::${widgetName}`)\n  }\n\n  function isContainerWithMissingModel(node: LGraphNode): boolean {\n    return activeMissingModelGraphIds.value.has(String(node.id))\n  }\n\n  function setFolderPaths(paths: Record<string, string[]>) {\n    folderPaths.value = paths\n  }\n\n  function setFileSize(url: string, size: number) {\n    fileSizes.value[url] = size\n  }\n\n  function setGatedRepoUrl(url: string, repoUrl: string) {\n    gatedRepoUrls.value[url] = repoUrl\n  }\n\n  function clearMissingModels() {\n    _verificationAbortController?.abort()\n    _verificationAbortController = null\n    missingModelCandidates.value = null\n    modelExpandState.value = {}\n    selectedLibraryModel.value = {}\n    importTaskIds.value = {}\n    folderPaths.value = {}\n    fileSizes.value = {}\n    gatedRepoUrls.value = {}\n  }\n\n  function isAbortError(error: unknown) {\n    return error instanceof Error && error.name === 'AbortError'\n  }\n\n  async function refreshMissingModels(options: { reloadDefs?: boolean } = {}) {\n    if (isRefreshingMissingModels.value) return\n\n    isRefreshingMissingModels.value = true\n    try {\n      await useApp().refreshMissingModels({\n        silent: true,\n        reloadDefs: options.reloadDefs\n      })\n    } catch (error) {\n      if (isAbortError(error)) return\n\n      console.error('Failed to refresh missing models:', error)\n      useToast().error(t('g.error'), {\n        description: t('rightSidePanel.missingModels.refreshFailed')\n      })\n    } finally {\n      isRefreshingMissingModels.value = false\n    }\n  }\n\n  return {\n    missingModelCandidates,\n    visibleMissingModelCandidates,\n    isRefreshingMissingModels,\n    hasMissingModels,\n    missingModelCount,\n    missingModelNodeIds,\n    activeMissingModelGraphIds,\n    missingModelAncestorExecutionIds,\n\n    setMissingModels,\n    addMissingModels,\n    removeMissingModelByNameOnNodes,\n    removeMissingModelByWidget,\n    removeMissingModelsByNodeId,\n    removeMissingModelsByPrefix,\n    removeMissingModelsBySourceScope,\n    clearMissingModels,\n    refreshMissingModels,\n    createVerificationAbortController,\n\n    hasMissingModelOnNode,\n    isWidgetMissingModel,\n    isContainerWithMissingModel,\n\n    modelExpandState,\n    selectedLibraryModel,\n    importTaskIds,\n    folderPaths,\n    fileSizes,\n    gatedRepoUrls,\n\n    setFolderPaths,\n    setFileSize,\n    setGatedRepoUrl\n  }\n})\n","import { defineStore } from 'pinia'\nimport { computed, ref, toRaw, watch } from 'vue'\nimport { whenever } from '@vueuse/core'\n\nimport { classifyPanelErrors } from '@/utils/errorSeverityClassification'\nimport { classifyValidationErrorAbsorption } from '@/utils/missingResourceAbsorption'\nimport type { MissingResourceAbsorption } from '@/utils/missingResourceAbsorption'\n\nimport { useNodeErrorFlagSync } from '@/composables/graph/useNodeErrorFlagSync'\nimport {\n  getLiftedErrorSource,\n  liftNodeErrorsToBoundary,\n  resolveLiftChain\n} from '@/core/graph/subgraph/liftNodeErrorsToBoundary'\nimport type { LGraphNode, LGraph } from '@/lib/litegraph/src/litegraph'\nimport { useMissingModelStore } from '@/platform/missingModel/missingModelStore'\nimport { useMissingMediaStore } from '@/platform/missingMedia/missingMediaStore'\nimport type { MissingModelCandidate } from '@/platform/missingModel/types'\nimport type { MissingMediaCandidate } from '@/platform/missingMedia/types'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useApp } from '@/scripts/appInstance'\nimport { ChangeTracker } from '@/scripts/changeTracker'\nimport { useDialogService } from '@/services/dialogService'\nimport type { ExecutionErrorWsMessage } from '@/platform/remote/comfyui/execution/types'\nimport type { NodeError, PromptError } from '@/platform/remote/comfyui/types'\nimport {\n  getAncestorExecutionIds,\n  tryNormalizeNodeExecutionId\n} from '@/types/nodeIdentification'\nimport type { NodeExecutionId, NodeLocatorId } from '@/types/nodeIdentification'\nimport {\n  executionIdToNodeLocatorId,\n  getExecutionIdByNode,\n  getNodeByExecutionId\n} from '@/utils/graphTraversalUtil'\nimport type { UUID } from '@/utils/uuid'\nimport { zeroUuid } from '@/utils/uuid'\nimport {\n  SIMPLE_ERROR_TYPES,\n  errorsForSlot,\n  getInputConfigBounds,\n  hasErrorForSlot,\n  isMissingNodePromptError,\n  isValueStillOutOfRange\n} from '@/utils/executionErrorUtil'\nimport type { NodeValidationError } from '@/utils/executionErrorUtil'\nimport { useMissingNodesErrorStore } from '@/platform/nodeReplacement/missingNodesErrorStore'\n\ninterface SlotNodeErrorClearTarget {\n  executionId: NodeExecutionId\n  slotName: string\n  /** Interior targets validate against the bounds recorded on their errors. */\n  useRecordedBounds?: boolean\n}\n\ninterface ValidationErrorSurface {\n  executionId: NodeExecutionId\n  error: NodeValidationError\n}\n\n// undefined means no verdict yet; null or [] means a verified empty result.\ninterface MissingResourceCandidates {\n  models?: MissingModelCandidate[] | null\n  media?: MissingMediaCandidate[] | null\n}\n\ninterface RunErrorState {\n  absorbedValidationErrors: WeakMap<\n    NodeValidationError,\n    MissingResourceAbsorption\n  >\n  nodeErrors: Record<string, NodeError> | null\n  executionError: ExecutionErrorWsMessage | null\n  promptError: PromptError | null\n}\n\n/** Execution error state: node errors, runtime errors, prompt errors, and missing assets. */\nexport const useExecutionErrorStore = defineStore('executionError', () => {\n  const workflowStore = useWorkflowStore()\n  const canvasStore = useCanvasStore()\n  const missingModelStore = useMissingModelStore()\n  const missingNodesStore = useMissingNodesErrorStore()\n  const missingMediaStore = useMissingMediaStore()\n\n  /**\n   * Run errors belong to the workflow that produced them, so they are parked\n   * under its path and root graph id and follow that graph back into view\n   * rather than being discarded when another workflow is loaded.\n   */\n  const runErrorsByWorkflow = ref(new Map<string, RunErrorState>())\n  const activeRunErrorKey = ref<string | null>(`:${zeroUuid}`)\n  const isErrorOverlayOpen = ref(false)\n\n  const activeRunErrors = computed<RunErrorState | undefined>(() =>\n    activeRunErrorKey.value === null\n      ? undefined\n      : runErrorsByWorkflow.value.get(activeRunErrorKey.value)\n  )\n\n  const lastNodeErrors = computed(\n    () => activeRunErrors.value?.nodeErrors ?? null\n  )\n  const lastExecutionError = computed(\n    () => activeRunErrors.value?.executionError ?? null\n  )\n  const lastPromptError = computed(\n    () => activeRunErrors.value?.promptError ?? null\n  )\n\n  function updateRunErrors(patch: Partial<RunErrorState>, key: string | null) {\n    if (key === null) return\n\n    const next: RunErrorState = {\n      absorbedValidationErrors: new WeakMap(),\n      nodeErrors: null,\n      executionError: null,\n      promptError: null,\n      ...runErrorsByWorkflow.value.get(key),\n      ...patch\n    }\n\n    if (!next.nodeErrors && !next.executionError && !next.promptError) {\n      runErrorsByWorkflow.value.delete(key)\n    } else {\n      runErrorsByWorkflow.value.set(key, next)\n    }\n  }\n\n  function runErrorKey(graphId: UUID, workflowPath?: string) {\n    return `${workflowPath ?? workflowStore.activeWorkflow?.path ?? ''}:${graphId}`\n  }\n\n  function moveRunErrors(\n    graphId: UUID,\n    oldWorkflowPath: string,\n    newWorkflowPath: string\n  ) {\n    const oldKey = runErrorKey(graphId, oldWorkflowPath)\n    const newKey = runErrorKey(graphId, newWorkflowPath)\n    if (oldKey === newKey) return\n\n    const runErrors = runErrorsByWorkflow.value.get(oldKey)\n    if (runErrors) runErrorsByWorkflow.value.set(newKey, runErrors)\n    else runErrorsByWorkflow.value.delete(newKey)\n    runErrorsByWorkflow.value.delete(oldKey)\n\n    if (activeRunErrorKey.value === oldKey) {\n      activeRunErrorKey.value = newKey\n    }\n  }\n\n  function captureRunErrorKey() {\n    return activeRunErrorKey.value\n  }\n\n  /**\n   * Point the store at the run errors of `graphId`. `null` detaches it, so a\n   * discarded graph shows nothing until the next one is loaded. The overlay is\n   * dismissed on every move so it only ever reopens for the graph in front.\n   */\n  function setActiveGraph(graphId: UUID | null, workflowPath?: string) {\n    const key = graphId === null ? null : runErrorKey(graphId, workflowPath)\n    if (key === activeRunErrorKey.value) return\n    activeRunErrorKey.value = key\n    isErrorOverlayOpen.value = false\n  }\n\n  const pendingAddedNodeScans = new WeakMap<\n    LGraph,\n    Map<NodeExecutionId, number>\n  >()\n  const pendingAddedNodeScanRevision = ref(0)\n  // Preserve the lifted host identity so retirement still matches after node deletion.\n  const validationErrorSurfaces = new WeakMap<\n    NodeValidationError,\n    ValidationErrorSurface[]\n  >()\n\n  function getValidationErrorSurfaces(\n    rootGraph: LGraph | undefined,\n    rawNodeId: NodeExecutionId,\n    nodeError: NodeError,\n    error: NodeValidationError\n  ): ValidationErrorSurface[] {\n    const rawErrorRecord = {\n      [rawNodeId]: { ...nodeError, errors: [error] }\n    }\n    const surfacedErrorRecord = rootGraph\n      ? liftNodeErrorsToBoundary(rootGraph, rawErrorRecord)\n      : rawErrorRecord\n\n    return Object.entries(surfacedErrorRecord).flatMap(\n      ([surfaceNodeId, surfaceNodeError]) => {\n        const executionId = tryNormalizeNodeExecutionId(surfaceNodeId)\n        if (!executionId) return []\n        return surfaceNodeError.errors.map((error) => ({ executionId, error }))\n      }\n    )\n  }\n\n  function captureValidationErrorSurfaces(\n    nodeErrors: Record<string, NodeError>\n  ): void {\n    const rootGraph = useApp().rootGraphOrUndefined\n    if (!rootGraph) return\n\n    for (const [rawNodeId, nodeError] of Object.entries(nodeErrors)) {\n      const executionId = tryNormalizeNodeExecutionId(rawNodeId)\n      if (!executionId) continue\n      for (const error of nodeError.errors) {\n        validationErrorSurfaces.set(\n          toRaw(error),\n          getValidationErrorSurfaces(rootGraph, executionId, nodeError, error)\n        )\n      }\n    }\n  }\n\n  function resolveValidationErrorSurfaces(\n    executionId: NodeExecutionId,\n    nodeError: NodeError,\n    error: NodeValidationError\n  ): ValidationErrorSurface[] {\n    const rawError = toRaw(error)\n    const cached = validationErrorSurfaces.get(rawError)\n    if (cached) return cached\n\n    const rootGraph = useApp().rootGraphOrUndefined\n    const surfaces = getValidationErrorSurfaces(\n      rootGraph,\n      executionId,\n      nodeError,\n      error\n    )\n    if (rootGraph) validationErrorSurfaces.set(rawError, surfaces)\n    return surfaces\n  }\n\n  function beginAddedNodeErrorScan(\n    rootGraph: LGraph,\n    executionId: NodeExecutionId\n  ): () => void {\n    const scansForGraph = pendingAddedNodeScans.get(rootGraph) ?? new Map()\n    scansForGraph.set(executionId, (scansForGraph.get(executionId) ?? 0) + 1)\n    pendingAddedNodeScans.set(rootGraph, scansForGraph)\n    pendingAddedNodeScanRevision.value++\n\n    let finished = false\n    return () => {\n      if (finished) return\n      finished = true\n\n      const remaining = (scansForGraph.get(executionId) ?? 1) - 1\n      if (remaining > 0) scansForGraph.set(executionId, remaining)\n      else scansForGraph.delete(executionId)\n      pendingAddedNodeScanRevision.value++\n    }\n  }\n\n  function hasPendingAddedNodeErrorScan(\n    rootGraph: LGraph,\n    executionId: NodeExecutionId\n  ): boolean {\n    // Subscribe callers to changes in the non-reactive WeakMap.\n    void pendingAddedNodeScanRevision.value\n    return (pendingAddedNodeScans.get(rootGraph)?.get(executionId) ?? 0) > 0\n  }\n\n  /**\n   * Also called after a graph load settles: the sync watcher below skips\n   * transitions that happen while a load is in flight, and no later\n   * transition reruns it.\n   */\n  function retireResolvedMissingNodePromptError() {\n    if (missingNodesStore.missingNodesError?.nodeTypes.length) return\n    if (!isMissingNodePromptError(lastPromptError.value)) return\n    updateRunErrors({ promptError: null }, activeRunErrorKey.value)\n  }\n\n  whenever(\n    () => !missingNodesStore.missingNodesError?.nodeTypes.length,\n    () => {\n      if (ChangeTracker.isLoadingGraph) return\n      retireResolvedMissingNodePromptError()\n    },\n    // The missing-node scan and prompt recording share a synchronous block; clear before recording the new error.\n    { flush: 'sync' }\n  )\n\n  function classifyMissingResource(\n    surfaces: ValidationErrorSurface[],\n    { models, media }: MissingResourceCandidates\n  ): MissingResourceAbsorption | null {\n    for (const { executionId, error } of surfaces) {\n      const kind = classifyValidationErrorAbsorption(\n        models ?? null,\n        media ?? null,\n        error,\n        executionId\n      )\n      if (kind) return kind\n    }\n    return null\n  }\n\n  /**\n   * The model/media analog of the missing-node retirement above: when a\n   * candidate leaves the store (installed + refreshed, node deleted or\n   * bypassed), the validation errors it was absorbing must retire with it —\n   * otherwise resolving the resource resurfaces them as blocking errors.\n   * Matching is by content, so a rescan that rebuilds equivalent candidates\n   * retires nothing.\n   */\n  function reconcileAbsorbedErrors(\n    { models, media }: MissingResourceCandidates,\n    key: string | null,\n    previous?: MissingResourceCandidates\n  ) {\n    if (\n      ChangeTracker.isLoadingGraph ||\n      key === null ||\n      key !== activeRunErrorKey.value\n    )\n      return\n    const state = activeRunErrors.value\n    if (!state?.nodeErrors) return\n    const record = state.nodeErrors\n\n    const possiblyMissingModels =\n      models?.map((candidate) =>\n        candidate.isMissing === undefined\n          ? { ...candidate, isMissing: true }\n          : candidate\n      ) ?? null\n    const possiblyMissingMedia =\n      media?.map((candidate) =>\n        candidate.isMissing === undefined\n          ? { ...candidate, isMissing: true }\n          : candidate\n      ) ?? null\n\n    const current = { models, media }\n    const possiblyMissing = {\n      models: possiblyMissingModels,\n      media: possiblyMissingMedia\n    }\n    const updated = filterNodeErrors(record, (surfaces, error) => {\n      const rawError = toRaw(error)\n      const kind = classifyMissingResource(surfaces, current)\n      if (kind) {\n        state.absorbedValidationErrors.set(rawError, kind)\n        return true\n      }\n      const wasAbsorbed =\n        state.absorbedValidationErrors.get(rawError) ??\n        (previous ? classifyMissingResource(surfaces, previous) : null)\n      if (!wasAbsorbed) return true\n      const wasVerified =\n        wasAbsorbed === 'missing_model'\n          ? models !== undefined\n          : media !== undefined\n      return (\n        !wasVerified ||\n        classifyMissingResource(surfaces, possiblyMissing) !== null\n      )\n    })\n    if (updated !== record) updateRunErrors({ nodeErrors: updated }, key)\n  }\n\n  function filterNodeErrors(\n    record: Record<string, NodeError>,\n    keepAndRecord: (\n      surfaces: ValidationErrorSurface[],\n      error: NodeValidationError\n    ) => boolean\n  ): Record<string, NodeError> | null {\n    let changed = false\n    const updated: Record<string, NodeError> = {}\n    for (const [rawNodeId, nodeError] of Object.entries(record)) {\n      const executionId = tryNormalizeNodeExecutionId(rawNodeId)\n      if (!executionId) {\n        updated[rawNodeId] = nodeError\n        continue\n      }\n      const remaining = nodeError.errors.filter((error) =>\n        keepAndRecord(\n          resolveValidationErrorSurfaces(executionId, nodeError, error),\n          error\n        )\n      )\n      if (remaining.length === nodeError.errors.length) {\n        updated[rawNodeId] = nodeError\n      } else {\n        changed = true\n        if (remaining.length > 0)\n          updated[rawNodeId] = { ...nodeError, errors: remaining }\n      }\n    }\n    if (!changed) return record\n    return Object.keys(updated).length ? updated : null\n  }\n\n  function retireResolvedMissingResourceErrors(\n    candidates: MissingResourceCandidates,\n    key: string | null = activeRunErrorKey.value\n  ) {\n    reconcileAbsorbedErrors(candidates, key)\n  }\n\n  watch(\n    () => ({\n      key: activeRunErrorKey.value,\n      models: missingModelStore.missingModelCandidates,\n      media: missingMediaStore.missingMediaCandidates\n    }),\n    (next, previous) => {\n      if (next.key !== previous.key) return\n      reconcileAbsorbedErrors(next, next.key, previous)\n    }\n  )\n\n  /**\n   * Replaces the full record; empty or null means the run produced no errors.\n   *\n   * `key` files the errors against the workflow that produced them, which is\n   * not necessarily the one on screen. Build it with `runErrorKey`. It defaults\n   * to the visible workflow for callers that record synchronously while\n   * submitting it.\n   */\n  function recordNodeErrors(\n    nodeErrors: Record<string, NodeError> | null,\n    key: string | null = activeRunErrorKey.value\n  ) {\n    const record =\n      nodeErrors && Object.keys(nodeErrors).length > 0 ? nodeErrors : null\n    updateRunErrors(\n      { nodeErrors: record, absorbedValidationErrors: new WeakMap() },\n      key\n    )\n    if (record && key !== null && key === activeRunErrorKey.value) {\n      captureValidationErrorSurfaces(record)\n      reconcileAbsorbedErrors(\n        {\n          models: missingModelStore.missingModelCandidates,\n          media: missingMediaStore.missingMediaCandidates\n        },\n        key\n      )\n    }\n  }\n\n  function recordExecutionError(\n    detail: ExecutionErrorWsMessage,\n    key: string | null = activeRunErrorKey.value\n  ) {\n    updateRunErrors({ executionError: detail }, key)\n  }\n\n  function showExecutionError(\n    detail: ExecutionErrorWsMessage,\n    key: string | null = activeRunErrorKey.value\n  ) {\n    if (key === null || key !== activeRunErrorKey.value) return\n\n    if (useSettingStore().get('Comfy.RightSidePanel.ShowErrorsTab')) {\n      showErrorOverlay()\n    } else {\n      useDialogService().showExecutionErrorDialog(detail)\n    }\n  }\n\n  function recordPromptError(\n    promptError: PromptError,\n    key: string | null = activeRunErrorKey.value\n  ) {\n    updateRunErrors({ promptError }, key)\n  }\n\n  function showErrorOverlay() {\n    isErrorOv